  WHERE provider = 'openai' AND active = true
$$;


--
-- Name: _btpm_adoption_template_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._btpm_adoption_template_v1() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT jsonb_build_array(
    jsonb_build_object(
      'key','stakeholder_impact','name','Stakeholder Impact',
      'readiness_area','stakeholder_impact','sort_order',10,
      'summary','Identify who is impacted by the change, how they are impacted, and who owns engagement for each group.',
      'tasks', jsonb_build_array(
        jsonb_build_object('key','identify_impacted_stakeholder_groups','title','Identify impacted stakeholder groups'),
        jsonb_build_object('key','assess_impact_level','title','Assess impact level by stakeholder group'),
        jsonb_build_object('key','confirm_stakeholder_owners','title','Confirm stakeholder owners and engagement needs')
      )
    ),
