--
-- Name: _clone_anchor_for_phase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clone_anchor_for_phase(_phase_id uuid) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  _start date;
  _earliest date;
BEGIN
  SELECT start_date INTO _start FROM public.phases WHERE id = _phase_id;
  IF _start IS NOT NULL THEN
    RETURN _start;
  END IF;

  SELECT MIN(d) INTO _earliest FROM (
    SELECT start_date AS d FROM public.phases WHERE id = _phase_id
    UNION ALL SELECT target_end_date FROM public.phases WHERE id = _phase_id
    UNION ALL SELECT start_date FROM public.tasks
      WHERE phase_id = _phase_id AND is_archived = false
    UNION ALL SELECT due_date FROM public.tasks
      WHERE phase_id = _phase_id AND is_archived = false
  ) s WHERE d IS NOT NULL;

  RETURN _earliest;
END;
$$;


--
-- Name: _clone_anchor_for_project(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clone_anchor_for_project(_project_id uuid) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  _start date;
  _earliest date;
BEGIN
  SELECT start_date INTO _start FROM public.projects WHERE id = _project_id;
  IF _start IS NOT NULL THEN
    RETURN _start;
  END IF;

  SELECT MIN(d) INTO _earliest FROM (
    SELECT start_date AS d FROM public.projects WHERE id = _project_id
    UNION ALL SELECT target_end_date FROM public.projects WHERE id = _project_id
    UNION ALL SELECT start_date FROM public.phases
      WHERE project_id = _project_id AND is_archived = false
    UNION ALL SELECT target_end_date FROM public.phases
      WHERE project_id = _project_id AND is_archived = false
    UNION ALL SELECT start_date FROM public.tasks
      WHERE project_id = _project_id AND is_archived = false
    UNION ALL SELECT due_date FROM public.tasks
      WHERE project_id = _project_id AND is_archived = false
    UNION ALL SELECT start_date FROM public.sprints
      WHERE project_id = _project_id AND is_archived = false
    UNION ALL SELECT end_date FROM public.sprints
      WHERE project_id = _project_id AND is_archived = false
  ) s WHERE d IS NOT NULL;

  RETURN _earliest;
END;
$$;


--
-- Name: _clone_anchor_for_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clone_anchor_for_task(_task_id uuid) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _anchor date;
BEGIN
  SELECT start_date INTO _anchor
  FROM public.tasks
  WHERE id = _task_id;

  IF _anchor IS NOT NULL THEN
    RETURN _anchor;
  END IF;

  SELECT LEAST(
    COALESCE(t.start_date, 'infinity'::date),
    COALESCE(t.due_date,   'infinity'::date)
  )
  INTO _anchor
  FROM public.tasks t
  WHERE t.id = _task_id;

  IF _anchor = 'infinity'::date THEN
    RETURN NULL;
  END IF;

  RETURN _anchor;
END;
$$;


--
-- Name: _clone_offset_days(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._clone_offset_days(_anchor date, _target date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _anchor IS NULL OR _target IS NULL THEN NULL
    ELSE (_target - _anchor)
  END;
$$;


--
-- Name: _compute_project_effective_window(jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._compute_project_effective_window(_bp jsonb, _anchor date) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  _proj jsonb := COALESCE(_bp->'project', '{}'::jsonb);
  _nom_start date;
  _nom_end date;
  _eff_start date;
  _eff_end date;
  _reasons jsonb := '[]'::jsonb;
  _ph jsonb;
  _tk jsonb;
  _sp jsonb;
  _start_off int;
  _end_off int;
  _due_off int;
  _d_start date;
  _d_end date;
BEGIN
  IF _anchor IS NULL THEN
    RETURN jsonb_build_object(
      'nominal_start', NULL, 'nominal_end', NULL,
      'effective_start', NULL, 'effective_end', NULL,
      'requires_widening', false, 'reasons', '[]'::jsonb
    );
  END IF;

  _start_off := NULLIF(_proj->'schedule'->>'start_offset_days','')::int;
  _end_off   := NULLIF(_proj->'schedule'->>'target_end_offset_days','')::int;
  _nom_start := CASE WHEN _start_off IS NOT NULL THEN _anchor + _start_off ELSE _anchor END;
  _nom_end   := CASE WHEN _end_off   IS NOT NULL THEN _anchor + _end_off   ELSE NULL END;

  _eff_start := _nom_start;
  _eff_end   := _nom_end;

  -- Walk phases
  FOR _ph IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'phases','[]'::jsonb)) LOOP
    _start_off := NULLIF(_ph->'schedule'->>'start_offset_days','')::int;
    _end_off   := NULLIF(_ph->'schedule'->>'target_end_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      _d_start := _anchor + _start_off;
      IF _eff_start IS NULL OR _d_start < _eff_start THEN
        _eff_start := _d_start;
        _reasons := _reasons || jsonb_build_object(
          'kind','phase_before_project','name', _ph->>'name','date', _d_start
        );
      END IF;
    END IF;
    IF _end_off IS NOT NULL THEN
      _d_end := _anchor + _end_off;
      IF _eff_end IS NULL OR _d_end > _eff_end THEN
        _eff_end := _d_end;
        _reasons := _reasons || jsonb_build_object(
          'kind','phase_after_project','name', _ph->>'name','date', _d_end
        );
      END IF;
    END IF;
  END LOOP;

  -- Walk tasks
  FOR _tk IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'tasks','[]'::jsonb)) LOOP
    _start_off := NULLIF(_tk->'schedule'->>'start_offset_days','')::int;
    _due_off   := NULLIF(_tk->'schedule'->>'due_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      _d_start := _anchor + _start_off;
      IF _eff_start IS NULL OR _d_start < _eff_start THEN
        _eff_start := _d_start;
        _reasons := _reasons || jsonb_build_object(
          'kind','task_before_project','name', _tk->>'name','date', _d_start
        );
      END IF;
    END IF;
    IF _due_off IS NOT NULL THEN
      _d_end := _anchor + _due_off;
      IF _eff_end IS NULL OR _d_end > _eff_end THEN
        _eff_end := _d_end;
        _reasons := _reasons || jsonb_build_object(
          'kind','task_after_project','name', _tk->>'name','date', _d_end
        );
      END IF;
    END IF;
  END LOOP;

  -- Sprints (agile, optional)
  FOR _sp IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'agile'->'sprints','[]'::jsonb)) LOOP
    _start_off := NULLIF(_sp->'schedule'->>'start_offset_days','')::int;
    _end_off   := NULLIF(_sp->'schedule'->>'end_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      _d_start := _anchor + _start_off;
      IF _eff_start IS NULL OR _d_start < _eff_start THEN
        _eff_start := _d_start;
        _reasons := _reasons || jsonb_build_object(
          'kind','sprint_before_project','name', _sp->>'name','date', _d_start
        );
      END IF;
    END IF;
    IF _end_off IS NOT NULL THEN
      _d_end := _anchor + _end_off;
      IF _eff_end IS NULL OR _d_end > _eff_end THEN
        _eff_end := _d_end;
        _reasons := _reasons || jsonb_build_object(
          'kind','sprint_after_project','name', _sp->>'name','date', _d_end
        );
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'nominal_start', _nom_start,
    'nominal_end', _nom_end,
    'effective_start', _eff_start,
    'effective_end', _eff_end,
    'requires_widening',
        (_eff_start IS DISTINCT FROM _nom_start)
        OR (_eff_end   IS DISTINCT FROM _nom_end),
    'reasons', _reasons
  );
END;
$$;


--
-- Name: _ensure_membership_layers(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_membership_layers(_target_user_id uuid, _organization_id uuid, _actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _tid uuid;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id = _organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'Organization not found'; END IF;

  INSERT INTO public.tenant_memberships
    (tenant_id, user_id, role, status, created_by, updated_by)
  VALUES (_tid, _target_user_id, 'tenant_member'::public.tenant_role,
          'active'::public.membership_status, _actor, _actor)
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET status = 'active'::public.membership_status,
        updated_by = _actor,
        updated_at = now()
    WHERE public.tenant_memberships.status <> 'active';

  INSERT INTO public.organization_memberships
    (tenant_id, organization_id, user_id, role, status, created_by, updated_by)
  VALUES (_tid, _organization_id, _target_user_id, 'org_member'::public.organization_role,
          'active'::public.membership_status, _actor, _actor)
  ON CONFLICT (organization_id, user_id) DO UPDATE
    SET status = 'active'::public.membership_status,
        updated_by = _actor,
        updated_at = now()
    WHERE public.organization_memberships.status <> 'active';
END $$;


--
-- Name: _gov_advance_next_expected_date(date, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gov_advance_next_expected_date(_base_date date, _frequency_type text, _actual_date_held date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE _next date; _guard int := 0;
BEGIN
  IF _frequency_type = 'ad_hoc' OR _base_date IS NULL THEN
    RETURN NULL;
  END IF;
  _next := _gov_frequency_next_date(_base_date, _frequency_type);
  IF _next IS NULL THEN RETURN NULL; END IF;
  -- Advance from the prior expected date until strictly after actual_date_held,
  -- preserving cadence rhythm even if the meeting was late.
  WHILE _actual_date_held IS NOT NULL AND _next <= _actual_date_held LOOP
    _next := _gov_frequency_next_date(_next, _frequency_type);
    _guard := _guard + 1;
    IF _guard > 1000 OR _next IS NULL THEN
      EXIT;
    END IF;
  END LOOP;
  RETURN _next;
END; $$;


--
-- Name: _gov_assert_project_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gov_assert_project_read(_project_id uuid) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _r record;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();

  IF v_caller IS NULL OR NOT is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE='42501';
  END IF;

  SELECT id, organization_id, workspace_id INTO _r FROM projects WHERE id = _project_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;

  IF public.is_user_org_member(v_caller, _r.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;
  RETURN _r;
END; $$;


--
-- Name: _gov_assert_project_write(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gov_assert_project_write(_project_id uuid) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
