  _r record;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();

  IF v_caller IS NULL OR NOT is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE='42501';
  END IF;

  SELECT id, organization_id, workspace_id INTO _r FROM projects WHERE id = _project_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;

  IF public.is_user_org_member(v_caller, _r.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Forbidden: project PM authority required' USING ERRCODE='42501';
  END IF;

  IF NOT public.has_project_pm_authority(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: project PM authority required' USING ERRCODE='42501';
  END IF;
  RETURN _r;
END; $$;


--
-- Name: _gov_derive_cadence_status(text, date, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gov_derive_cadence_status(_frequency_type text, _next_expected_date date, _archived_at timestamp with time zone, _due_soon_days integer DEFAULT 7) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _archived_at IS NOT NULL THEN 'inactive'
    WHEN _frequency_type = 'ad_hoc' THEN 'ad_hoc'
    WHEN _next_expected_date IS NULL THEN 'no_next_date'
    WHEN _next_expected_date < CURRENT_DATE THEN 'overdue'
    WHEN _next_expected_date <= CURRENT_DATE + (_due_soon_days || ' days')::interval THEN 'due_soon'
    ELSE 'on_track'
  END
$$;


--
-- Name: _gov_frequency_next_date(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gov_frequency_next_date(_base_date date, _frequency_type text) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _base_date IS NULL THEN NULL
    WHEN _frequency_type = 'weekly'    THEN _base_date + INTERVAL '7 days'
    WHEN _frequency_type = 'biweekly'  THEN _base_date + INTERVAL '14 days'
    WHEN _frequency_type = 'monthly'   THEN _base_date + INTERVAL '1 month'
    WHEN _frequency_type = 'quarterly' THEN _base_date + INTERVAL '3 months'
    ELSE NULL
  END::date
$$;


--
-- Name: _gov_report_assert_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._gov_report_assert_scope(_organization_id uuid, _workspace_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT is_active_user(_uid) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required' USING ERRCODE = '22023';
  END IF;
  IF is_org_admin(_uid, _organization_id) THEN
    RETURN;
  END IF;
  -- Non org-admin callers must scope to a workspace they belong to.
  IF _workspace_id IS NULL THEN
    RAISE EXCEPTION 'Forbidden: workspace_id required for non org-admin reporting'
      USING ERRCODE = '42501';
  END IF;
  IF NOT is_workspace_member(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: _is_allowed_tenant_integration_secret_name(public.tenant_integration_kind, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._is_allowed_tenant_integration_secret_name(_integration_kind public.tenant_integration_kind, _secret_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  SELECT CASE
    WHEN _secret_name IS NULL THEN false
    WHEN _secret_name !~ '^[a-z][a-z0-9_]{1,48}$' THEN false
    ELSE _secret_name = ANY (
      CASE _integration_kind::text
        WHEN 'openai'          THEN ARRAY['api_key']
        WHEN 'azure_openai'    THEN ARRAY['api_key','endpoint','deployment','api_version']
        WHEN 'microsoft_graph' THEN ARRAY['tenant_id','client_id','client_secret']
        WHEN 'sharepoint'      THEN ARRAY['site_url','site_id']
        -- 'powerbi' branch retired (PBI 6.4C2): generic REST integration is frozen.
        WHEN 'mulesoft_kpi'    THEN ARRAY['api_url','username','password']
        WHEN 'smtp'            THEN ARRAY['host','port','username','password','from_email','from_name']
        ELSE ARRAY[]::text[]
      END
    )
  END;
$_$;


--
-- Name: _kc_ai_meta_decrypt_array(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._kc_ai_meta_decrypt_array(_cipher text, _org uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_plain text;
BEGIN
  IF _cipher IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;
  v_plain := public.btpm_decrypt(_cipher, _org);
  IF v_plain IS NULL OR v_plain = '' THEN
    RETURN ARRAY[]::text[];
  END IF;
  RETURN ARRAY(SELECT jsonb_array_elements_text(v_plain::jsonb));
EXCEPTION WHEN OTHERS THEN
  RETURN ARRAY[]::text[];
END;
$$;


--
-- Name: _kc_ai_meta_decrypt_jsonb(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._kc_ai_meta_decrypt_jsonb(_cipher text, _org uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_plain text;
BEGIN
  IF _cipher IS NULL THEN RETURN NULL; END IF;
  v_plain := public.btpm_decrypt(_cipher, _org);
  IF v_plain IS NULL OR v_plain = '' THEN RETURN NULL; END IF;
  RETURN v_plain::jsonb;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$$;


--
-- Name: _kc_ai_meta_encrypt_array(text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._kc_ai_meta_encrypt_array(_arr text[], _org uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF _arr IS NULL THEN
    RETURN NULL;
  END IF;
  PERFORM public.ensure_org_encryption_key(_org);
  RETURN public.btpm_encrypt(to_jsonb(_arr)::text, _org);
END;
$$;


--
-- Name: _kc_ai_meta_encrypt_jsonb(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._kc_ai_meta_encrypt_jsonb(_value jsonb, _org uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF _value IS NULL THEN RETURN NULL; END IF;
  PERFORM public.ensure_org_encryption_key(_org);
  RETURN public.btpm_encrypt(_value::text, _org);
END;
$$;


--
-- Name: _lifecycle_bypass_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._lifecycle_bypass_allowed() RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN COALESCE(current_setting('app.allow_lifecycle_bypass', true), '') = 'on';
END;
$$;


--
-- Name: _log_admin_authority(text, uuid, uuid, uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._log_admin_authority(_action text, _tenant_id uuid, _organization_id uuid, _target_user_id uuid, _target_email text, _previous_role text, _new_role text, _previous_status text, _new_status text, _reason text, _metadata jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.admin_authority_audit(
    actor_user_id, action, tenant_id, organization_id, target_user_id,
    target_email, previous_role, new_role, previous_status, new_status, reason, metadata
  ) VALUES (
    COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid),
    _action, _tenant_id, _organization_id, _target_user_id,
    _target_email, _previous_role, _new_role, _previous_status, _new_status,
    _reason, COALESCE(_metadata, '{}'::jsonb)
  );
END;
$$;


--
-- Name: _log_entity_material_update(text, uuid, uuid, uuid, text, uuid, jsonb, uuid[], uuid[], text[], text[], jsonb, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._log_entity_material_update(_owner_type text, _owner_id uuid, _organization_id uuid, _workspace_id uuid, _anchor_type text, _anchor_id uuid, _scalar_diff jsonb, _old_user_ids uuid[], _new_user_ids uuid[], _old_object_keys text[], _new_object_keys text[], _old_user_labels jsonb, _new_user_labels jsonb, _old_object_labels jsonb, _new_object_labels jsonb, _entity_title text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event           text;
  v_meta            jsonb;
  v_added_users     uuid[];
  v_removed_users   uuid[];
  v_added_objects   text[];
  v_removed_objects text[];
  v_has_change      boolean := false;
BEGIN
  v_added_users     := ARRAY(SELECT u FROM unnest(_new_user_ids)   u WHERE u <> ALL (COALESCE(_old_user_ids,   ARRAY[]::uuid[])));
  v_removed_users   := ARRAY(SELECT u FROM unnest(_old_user_ids)   u WHERE u <> ALL (COALESCE(_new_user_ids,   ARRAY[]::uuid[])));
  v_added_objects   := ARRAY(SELECT k FROM unnest(_new_object_keys) k WHERE k <> ALL (COALESCE(_old_object_keys, ARRAY[]::text[])));
  v_removed_objects := ARRAY(SELECT k FROM unnest(_old_object_keys) k WHERE k <> ALL (COALESCE(_new_object_keys, ARRAY[]::text[])));

  IF jsonb_strip_nulls(COALESCE(_scalar_diff, '{}'::jsonb)) <> '{}'::jsonb THEN v_has_change := true; END IF;
  IF array_length(v_added_users,     1) IS NOT NULL THEN v_has_change := true; END IF;
  IF array_length(v_removed_users,   1) IS NOT NULL THEN v_has_change := true; END IF;
  IF array_length(v_added_objects,   1) IS NOT NULL THEN v_has_change := true; END IF;
  IF array_length(v_removed_objects, 1) IS NOT NULL THEN v_has_change := true; END IF;

  IF NOT v_has_change THEN RETURN; END IF;

  v_event := CASE _owner_type WHEN 'blocker' THEN 'blocker_updated' WHEN 'risk' THEN 'risk_updated' ELSE _owner_type || '_updated' END;

  v_meta := jsonb_build_object(
    CASE _owner_type WHEN 'blocker' THEN 'blocker_id' ELSE 'risk_id' END, _owner_id,
    'title',           _entity_title,
    'anchor_type',     _anchor_type,
    'anchor_id',       _anchor_id,
    'changed_fields',  COALESCE(_scalar_diff, '{}'::jsonb),
    'people_added',    COALESCE(_new_user_labels,   '[]'::jsonb),
    'people_removed',  COALESCE(_old_user_labels,   '[]'::jsonb),
    'objects_added',   COALESCE(_new_object_labels, '[]'::jsonb),
    'objects_removed', COALESCE(_old_object_labels, '[]'::jsonb)
  );

  -- Replace the *_added / *_removed arrays with the actually-added/removed
  -- subset (above passed full sets so we have labels). We rebuild here using
  -- the diff arrays.
  v_meta := v_meta
    || jsonb_build_object(
      'people_added', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_new_user_labels,'[]'::jsonb)) elt
         WHERE (elt->>'user_id')::uuid = ANY (v_added_users)
      ), '[]'::jsonb),
      'people_removed', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_old_user_labels,'[]'::jsonb)) elt
         WHERE (elt->>'user_id')::uuid = ANY (v_removed_users)
      ), '[]'::jsonb),
      'objects_added', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_new_object_labels,'[]'::jsonb)) elt
         WHERE ((elt->>'referenced_type') || ':' || (elt->>'referenced_id')) = ANY (v_added_objects)
      ), '[]'::jsonb),
      'objects_removed', COALESCE((
        SELECT jsonb_agg(elt) FROM jsonb_array_elements(COALESCE(_old_object_labels,'[]'::jsonb)) elt
         WHERE ((elt->>'referenced_type') || ':' || (elt->>'referenced_id')) = ANY (v_removed_objects)
      ), '[]'::jsonb)
    );

  -- Write on the entity itself
  PERFORM public.log_activity_event(
    _organization_id, auth.uid(), v_event, _owner_type, _owner_id, v_meta, _workspace_id
  );
  -- Mirror on the anchor object
  IF _anchor_type IS NOT NULL AND _anchor_id IS NOT NULL THEN
    PERFORM public.log_activity_event(
      _organization_id, auth.uid(), v_event, _anchor_type, _anchor_id, v_meta, _workspace_id
    );
  END IF;
END;
$$;


--
-- Name: _normalize_azure_openai_endpoint(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._normalize_azure_openai_endpoint(_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  _s text;
  _rest text;
  _host text;
  _path text;
BEGIN
  IF _input IS NULL THEN RETURN NULL; END IF;
  _s := btrim(_input);
  IF _s = '' THEN RETURN NULL; END IF;

  -- Require HTTPS scheme (case-insensitive) and reject anything else.
  IF _s !~* '^https://' THEN RETURN NULL; END IF;
  _rest := substring(_s FROM 9);

  -- Reject query strings and fragments.
  IF position('?' IN _rest) > 0 OR position('#' IN _rest) > 0 THEN
    RETURN NULL;
  END IF;

  -- Reject embedded userinfo (user:pass@host).
  IF position('@' IN split_part(_rest, '/', 1)) > 0 THEN
    RETURN NULL;
  END IF;

  _host := lower(split_part(_rest, '/', 1));
  IF _host = '' THEN RETURN NULL; END IF;

  -- Reject host:port; Azure endpoints use default 443.
  IF position(':' IN _host) > 0 THEN RETURN NULL; END IF;

  -- Reject IP-address hosts.
  IF _host ~ '^[0-9]+(\.[0-9]+){3}$' THEN RETURN NULL; END IF;
  IF _host ~ '^[0-9.]+$' THEN RETURN NULL; END IF;
  IF _host ~ '^\[' THEN RETURN NULL; END IF; -- ipv6 literal

  -- Whitelist Azure OpenAI host suffixes anchored at end.
  IF NOT (_host ~ '\.openai\.azure\.com$' OR _host ~ '\.services\.ai\.azure\.com$') THEN
    RETURN NULL;
  END IF;

  -- Extract path portion after host.
  _path := substring(_rest FROM (length(split_part(_rest, '/', 1)) + 1));
  IF _path IS NULL THEN _path := ''; END IF;

  -- Trim trailing slashes.
  _path := regexp_replace(_path, '/+$', '');
  -- Trim canonical /openai/v1 suffix if present (case-insensitive).
  _path := regexp_replace(_path, '/openai/v1$', '', 'i');
  -- Any remaining non-empty path is disallowed.
  IF _path <> '' THEN RETURN NULL; END IF;

  RETURN 'https://' || _host;
END $_$;


