--
-- Name: project_people_presets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.project_people_presets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    scope_type text DEFAULT 'workspace'::text NOT NULL,
    name text NOT NULL,
    description text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    archived_by uuid,
    CONSTRAINT ppp_archive_pair CHECK (((archived_at IS NULL) OR (archived_by IS NOT NULL))),
    CONSTRAINT ppp_scope_type_workspace_only CHECK ((scope_type = 'workspace'::text))
);


--
-- Name: _ppp_authorize_write(uuid, public.project_people_presets, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ppp_authorize_write(_actor uuid, _preset public.project_people_presets, _require_active boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF _actor IS NULL OR NOT public.is_active_user(_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.has_pm_authority(_actor, _preset.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF NOT public.can_write_demo(_actor, _preset.workspace_id) THEN
    RAISE EXCEPTION 'Demo workspace is read-only';
  END IF;
  IF _require_active AND _preset.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'Preset is archived';
  END IF;
END; $$;


