--

CREATE FUNCTION public._project_id_from_target(_target_type text, _target_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE _target_type
    WHEN 'project' THEN _target_id
    WHEN 'phase'   THEN (SELECT project_id FROM public.phases WHERE id = _target_id)
    WHEN 'task'    THEN (SELECT project_id FROM public.tasks  WHERE id = _target_id)
  END
$$;


--
-- Name: _provision_default_tenant_integrations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._provision_default_tenant_integrations(_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF _tenant_id IS NULL THEN RETURN; END IF;
  INSERT INTO public.tenant_integrations (tenant_id, kind, name, status, is_enabled, config_metadata)
  SELECT _tenant_id, k.kind::public.tenant_integration_kind, 'default',
         'not_configured'::public.tenant_integration_status, false, '{}'::jsonb
    FROM (VALUES
      ('openai'),
      ('azure_openai'),
      ('microsoft_graph'),
      ('sharepoint'),
      -- 'powerbi' default provisioning retired (PBI 6.4C2).
      ('mulesoft_kpi'),
      ('smtp')
    ) AS k(kind)
  ON CONFLICT (tenant_id, kind, name) DO NOTHING;
END $$;


--
-- Name: _recompute_phase_actuals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recompute_phase_actuals(_phase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_start date;
  v_max_end   date;
  v_any_unfinished boolean;
BEGIN
  SELECT
    MIN(actual_start_date),
    MAX(actual_end_date),
    bool_or(actual_start_date IS NOT NULL AND actual_end_date IS NULL)
  INTO v_min_start, v_max_end, v_any_unfinished
  FROM public.tasks
  WHERE phase_id = _phase_id
    AND status <> 'cancelled'
    AND is_archived = false;

  IF v_any_unfinished THEN
    v_max_end := NULL;
  END IF;

  PERFORM set_config('app.allow_actual_rollup', 'on', true);
  UPDATE public.phases
  SET actual_start_date = v_min_start,
      actual_end_date   = v_max_end,
      updated_at        = now()
  WHERE id = _phase_id
    AND (actual_start_date IS DISTINCT FROM v_min_start
      OR actual_end_date   IS DISTINCT FROM v_max_end);
  PERFORM set_config('app.allow_actual_rollup', '', true);
END;
$$;


--
-- Name: _recompute_phase_completion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recompute_phase_completion(_phase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_phase            public.phases%ROWTYPE;
  v_eligible_count   integer;
  v_incomplete_count integer;
  v_should_be_complete boolean;
BEGIN
  SELECT * INTO v_phase FROM public.phases p WHERE p.id = _phase_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_phase.is_archived OR v_phase.status = 'cancelled' THEN
    RETURN;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE t.status <> 'completed')
  INTO v_eligible_count, v_incomplete_count
  FROM public.tasks t
  WHERE t.phase_id = _phase_id
    AND t.is_archived = false
    AND t.status <> 'cancelled';

  v_should_be_complete := (v_eligible_count > 0 AND v_incomplete_count = 0);

  IF v_should_be_complete AND v_phase.status <> 'completed' THEN
    PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
    UPDATE public.phases p
    SET status = 'completed', updated_at = now()
    WHERE p.id = _phase_id;
    PERFORM set_config('app.allow_lifecycle_bypass', '', true);

    PERFORM public.log_activity_event(
      v_phase.organization_id,
      NULL,
      'phase_auto_completed',
      'phase',
      _phase_id,
      jsonb_build_object(
        'prior_status', v_phase.status,
        'new_status', 'completed',
        'reason', 'all_eligible_tasks_completed',
        'eligible_task_count', v_eligible_count,
        'project_id', v_phase.project_id
      ),
      v_phase.workspace_id
    );

  ELSIF (NOT v_should_be_complete) AND v_phase.status = 'completed' THEN
    PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
    UPDATE public.phases p
    SET status = 'active', updated_at = now()
    WHERE p.id = _phase_id;
    PERFORM set_config('app.allow_lifecycle_bypass', '', true);

    PERFORM public.log_activity_event(
      v_phase.organization_id,
      NULL,
      'phase_auto_reopened',
      'phase',
      _phase_id,
      jsonb_build_object(
        'prior_status', 'completed',
        'new_status', 'active',
        'reason', CASE
          WHEN v_eligible_count = 0 THEN 'no_eligible_tasks'
          ELSE 'incomplete_eligible_tasks'
        END,
        'eligible_task_count', v_eligible_count,
        'incomplete_task_count', v_incomplete_count,
        'project_id', v_phase.project_id
      ),
      v_phase.workspace_id
    );
  END IF;
END;
$$;


--
-- Name: _recompute_project_actuals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._recompute_project_actuals(_project_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_min_start date;
  v_max_end   date;
  v_any_unfinished boolean;
BEGIN
  SELECT
    MIN(actual_start_date),
    MAX(actual_end_date),
    bool_or(actual_start_date IS NOT NULL AND actual_end_date IS NULL)
  INTO v_min_start, v_max_end, v_any_unfinished
  FROM public.phases
  WHERE project_id = _project_id
    AND status <> 'cancelled'
    AND is_archived = false;

  IF v_any_unfinished THEN
    v_max_end := NULL;
  END IF;

  PERFORM set_config('app.allow_actual_rollup', 'on', true);
  UPDATE public.projects
  SET actual_start_date = v_min_start,
      actual_end_date   = v_max_end,
      updated_at        = now()
  WHERE id = _project_id
    AND (actual_start_date IS DISTINCT FROM v_min_start
      OR actual_end_date   IS DISTINCT FROM v_max_end);
  PERFORM set_config('app.allow_actual_rollup', '', true);
END;
$$;


--
-- Name: _required_tenant_integration_config_names(public.tenant_integration_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._required_tenant_integration_config_names(_integration_kind public.tenant_integration_kind) RETURNS text[]
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE _integration_kind::text
    WHEN 'azure_openai' THEN ARRAY['endpoint']
    ELSE ARRAY[]::text[]
  END
$$;


--
-- Name: _required_tenant_integration_secret_names(public.tenant_integration_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._required_tenant_integration_secret_names(_integration_kind public.tenant_integration_kind) RETURNS text[]
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE _integration_kind::text
    WHEN 'smtp' THEN ARRAY['host','port','password','from_email']
    WHEN 'openai' THEN ARRAY['api_key']
    WHEN 'azure_openai' THEN ARRAY['api_key']
    WHEN 'microsoft_graph' THEN ARRAY['tenant_id','client_id','client_secret']
    WHEN 'sharepoint' THEN ARRAY['site_url']
    -- 'powerbi' branch retired (PBI 6.4C2): generic REST integration is frozen.
    WHEN 'mulesoft_kpi' THEN ARRAY['api_url','username','password']
    ELSE ARRAY[]::text[]
  END
$$;


--
-- Name: _safe_integration_config_metadata(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._safe_integration_config_metadata(_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  _out jsonb := '{}'::jsonb;
  _k text;
  _v jsonb;
  _pattern text := '(secret|password|passwd|token|api[_-]?key|access[_-]?key|private[_-]?key|client[_-]?secret|connection[_-]?string|conn[_-]?str|credential|bearer|refresh[_-]?token|shared[_-]?key|cert(ificate)?)';
BEGIN
  IF _input IS NULL OR jsonb_typeof(_input) <> 'object' THEN
    RETURN '{}'::jsonb;
  END IF;

  FOR _k, _v IN SELECT * FROM jsonb_each(_input) LOOP
    IF _k !~* _pattern THEN
      _out := _out || jsonb_build_object(_k, _v);
    END IF;
  END LOOP;

  RETURN _out;
END $$;


--
-- Name: _sanitize_storage_segment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sanitize_storage_segment(_input text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE _s text;
BEGIN
  IF _input IS NULL THEN RETURN NULL; END IF;
  _s := btrim(_input);
  IF length(_s) = 0 THEN RETURN NULL; END IF;
  IF _s ~ '[\/\\]' OR _s ~ '[[:cntrl:]]' OR _s = '.' OR _s = '..' OR _s ~ '\.\.' THEN
    RAISE EXCEPTION 'Unsafe storage segment: %', _input;
  END IF;
  _s := regexp_replace(_s, '[^A-Za-z0-9._\-\(\) ]', '_', 'g');
  IF length(_s) > 200 THEN _s := substr(_s, 1, 200); END IF;
  RETURN _s;
END $$;


--
-- Name: _seed_single_org_preference(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._seed_single_org_preference(_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_count int;
  _tid uuid;
  _oid uuid;
  _ws_count int;
  _ws uuid;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.user_active_context_preferences p
     WHERE p.user_id = _target_user_id
       AND p.last_active_organization_id IS NOT NULL
       AND public.is_organization_member(p.last_active_organization_id, _target_user_id)
  ) THEN
    RETURN; -- keep valid existing preference
  END IF;

  SELECT COUNT(*) INTO _org_count
    FROM public.organization_memberships om
    JOIN public.tenant_memberships tm
      ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
   WHERE om.user_id = _target_user_id AND om.status = 'active' AND tm.status = 'active';

  IF _org_count <> 1 THEN RETURN; END IF;

  SELECT om.tenant_id, om.organization_id INTO _tid, _oid
    FROM public.organization_memberships om
    JOIN public.tenant_memberships tm
      ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
   WHERE om.user_id = _target_user_id AND om.status = 'active' AND tm.status = 'active'
   LIMIT 1;

  SELECT COUNT(*) INTO _ws_count
    FROM public.workspace_memberships wm
    JOIN public.workspaces w ON w.id = wm.workspace_id
   WHERE wm.user_id = _target_user_id AND w.organization_id = _oid
     AND COALESCE(w.is_archived, false) = false;

  IF _ws_count = 1 THEN
    SELECT wm.workspace_id INTO _ws
      FROM public.workspace_memberships wm
      JOIN public.workspaces w ON w.id = wm.workspace_id
     WHERE wm.user_id = _target_user_id AND w.organization_id = _oid
       AND COALESCE(w.is_archived, false) = false
     LIMIT 1;
  END IF;

  INSERT INTO public.user_active_context_preferences
    (user_id, last_active_tenant_id, last_active_organization_id,
     last_active_workspace_id, is_all_workspaces)
  VALUES (_target_user_id, _tid, _oid, _ws, CASE WHEN _ws IS NULL THEN true ELSE false END)
  ON CONFLICT (user_id) DO UPDATE
    SET last_active_tenant_id = COALESCE(public.user_active_context_preferences.last_active_tenant_id, EXCLUDED.last_active_tenant_id),
        last_active_organization_id = COALESCE(public.user_active_context_preferences.last_active_organization_id, EXCLUDED.last_active_organization_id),
        last_active_workspace_id = COALESCE(public.user_active_context_preferences.last_active_workspace_id, EXCLUDED.last_active_workspace_id),
        is_all_workspaces = CASE
          WHEN public.user_active_context_preferences.last_active_organization_id IS NULL
            THEN EXCLUDED.is_all_workspaces
          ELSE public.user_active_context_preferences.is_all_workspaces END,
        updated_at = now();
END $$;


--
-- Name: _snapshot_baseline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._snapshot_baseline(_project_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_proj public.projects%ROWTYPE;
        v_bad_phase int; v_bad_task int; v_phase_oob int; v_task_oob int;
BEGIN
  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Not authorized to baseline this project'; END IF;
  IF v_proj.start_date IS NULL OR v_proj.target_end_date IS NULL THEN
    RAISE EXCEPTION 'Project planned start and target end dates are required.'; END IF;
  IF v_proj.start_date > v_proj.target_end_date THEN
    RAISE EXCEPTION 'Project planned start is after target end date.'; END IF;
  SELECT count(*) INTO v_bad_phase FROM public.phases
   WHERE project_id=_project_id AND is_archived=false
     AND (start_date IS NULL OR target_end_date IS NULL OR start_date > target_end_date);
  IF v_bad_phase > 0 THEN RAISE EXCEPTION 'All phases must have a valid planned start and end date (% invalid).', v_bad_phase; END IF;
  SELECT count(*) INTO v_bad_task FROM public.tasks
   WHERE project_id=_project_id AND is_archived=false
     AND (start_date IS NULL OR due_date IS NULL OR start_date > due_date);
  IF v_bad_task > 0 THEN RAISE EXCEPTION 'All tasks must have a valid planned start and due date (% invalid).', v_bad_task; END IF;
  SELECT count(*) INTO v_phase_oob FROM public.phases
   WHERE project_id=_project_id AND is_archived=false
     AND (start_date < v_proj.start_date OR target_end_date > v_proj.target_end_date);
  IF v_phase_oob > 0 THEN RAISE EXCEPTION 'Phase planned dates must fit within project range (% out of bounds).', v_phase_oob; END IF;
  SELECT count(*) INTO v_task_oob FROM public.tasks t JOIN public.phases p ON p.id=t.phase_id
   WHERE t.project_id=_project_id AND t.is_archived=false AND p.is_archived=false
     AND (t.start_date < p.start_date OR t.due_date > p.target_end_date);
  IF v_task_oob > 0 THEN RAISE EXCEPTION 'Task planned dates must fit within their phase range (% out of bounds).', v_task_oob; END IF;
  PERFORM set_config('btpm.baseline_write','on',true);
  UPDATE public.projects SET baseline_start_date=start_date, baseline_end_date=target_end_date,
    is_baselined=true, baseline_approved_at=now(), baseline_approved_by=auth.uid() WHERE id=_project_id;
  UPDATE public.phases SET baseline_start_date=start_date, baseline_end_date=target_end_date,
    added_after_baseline=false WHERE project_id=_project_id AND is_archived=false;
  UPDATE public.tasks SET baseline_start_date=start_date, baseline_end_date=due_date,
    added_after_baseline=false WHERE project_id=_project_id AND is_archived=false;
  PERFORM set_config('btpm.baseline_write','off',true);
END; $$;


--
-- Name: _template_blueprint_summary(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._template_blueprint_summary(_blueprint jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'schedule_mode', _blueprint->>'schedule_mode',
    'anchor_source', _blueprint->>'anchor_source',
    'agile_enabled', COALESCE((_blueprint->'project'->>'agile_enabled')::boolean, false),
    'summary_counts', jsonb_build_object(
      'phases',           COALESCE(jsonb_array_length(_blueprint->'phases'), 0),
      'tasks',            COALESCE(jsonb_array_length(_blueprint->'tasks'), 0),
      'dependencies',     COALESCE(jsonb_array_length(_blueprint->'dependencies'), 0),
      'kpi_definitions',  COALESCE(jsonb_array_length(_blueprint->'kpi_definitions'), 0),
      'workflow_states',  COALESCE(jsonb_array_length(_blueprint->'agile'->'workflow_states'), 0),
      'sprints',          COALESCE(jsonb_array_length(_blueprint->'agile'->'sprints'), 0),
      'backlog_items',    COALESCE(jsonb_array_length(_blueprint->'agile'->'backlog_items'), 0)
    )
  );
$$;


--
-- Name: _tenant_ai_provider_readiness(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._tenant_ai_provider_readiness(_tenant_id uuid, _provider text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kind public.tenant_integration_kind;
  v_ti public.tenant_integrations;
  v_required text[];
  v_required_config text[];
  v_missing_secret_count int := 0;
  v_missing_config_count int := 0;
  v_present boolean;
  v_enabled boolean;
  v_active boolean;
  v_tested boolean;
  v_ready boolean;
  v_issue text;
  v_meta jsonb;
  v_deps jsonb;
  v_required_deps text[];
  v_missing_deps_count int := 0;
  v_deps_complete boolean := true;
BEGIN
  IF _provider NOT IN ('openai', 'azure_openai') THEN
    RETURN jsonb_build_object(
      'provider', _provider, 'present', false, 'ready', false,
      'issue_code', 'unsupported_provider'
    );
  END IF;
  v_kind := _provider::public.tenant_integration_kind;

  SELECT * INTO v_ti FROM public.tenant_integrations
   WHERE tenant_id = _tenant_id AND kind = v_kind AND name = 'default'
   LIMIT 1;

  v_present := v_ti.id IS NOT NULL;
  IF NOT v_present THEN
    RETURN jsonb_build_object(
      'provider', _provider, 'present', false, 'ready', false,
      'issue_code', 'integration_missing'
    );
  END IF;

  v_enabled := v_ti.is_enabled;
  v_active := v_ti.status = 'active';
  v_tested := v_ti.last_success_at IS NOT NULL;

  v_required := public._required_tenant_integration_secret_names(v_kind);
  v_required_config := public._required_tenant_integration_config_names(v_kind);

  SELECT COUNT(*)::int INTO v_missing_secret_count
  FROM unnest(v_required) req
  WHERE NOT EXISTS (
    SELECT 1 FROM public.tenant_secret_refs r
    WHERE r.tenant_id = _tenant_id
      AND r.integration_id = v_ti.id
      AND r.secret_name = req
      AND r.secret_scope = 'tenant'
      AND r.disabled_at IS NULL
      AND r.revoked_at IS NULL
      AND r.status = 'active'
  );

  IF COALESCE(array_length(v_required_config, 1), 0) > 0 THEN
    SELECT COUNT(*)::int INTO v_missing_config_count
    FROM unnest(v_required_config) cfg
    WHERE NOT (
      jsonb_typeof(COALESCE(v_ti.config_metadata, '{}'::jsonb)) = 'object'
      AND COALESCE(v_ti.config_metadata, '{}'::jsonb) ? cfg
      AND jsonb_typeof(COALESCE(v_ti.config_metadata, '{}'::jsonb) -> cfg) = 'string'
      AND btrim(COALESCE(v_ti.config_metadata, '{}'::jsonb) ->> cfg) <> ''
    );
  END IF;

  -- Azure-only: require complete deployment mappings.
  IF _provider = 'azure_openai' THEN
    v_meta := COALESCE(v_ti.config_metadata, '{}'::jsonb);
    IF jsonb_typeof(v_meta) = 'object'
       AND (v_meta ? 'azure_deployments')
       AND jsonb_typeof(v_meta -> 'azure_deployments') = 'object' THEN
      v_deps := v_meta -> 'azure_deployments';
    ELSE
      v_deps := '{}'::jsonb;
    END IF;
    v_required_deps := public._azure_openai_required_deployment_keys();
    SELECT COUNT(*)::int INTO v_missing_deps_count
    FROM unnest(v_required_deps) k
    WHERE NOT (
      (v_deps ? k)
      AND jsonb_typeof(v_deps -> k) = 'string'
      AND btrim(v_deps ->> k) <> ''
    );
    v_deps_complete := (v_missing_deps_count = 0);
  END IF;

  v_ready := v_enabled AND v_active
    AND v_missing_secret_count = 0
    AND v_missing_config_count = 0
    AND v_tested
    AND v_deps_complete;

  IF v_ready THEN v_issue := NULL;
  ELSIF NOT v_enabled THEN v_issue := 'integration_disabled';
  ELSIF NOT v_active THEN v_issue := 'integration_not_active';
  ELSIF v_missing_secret_count > 0 THEN v_issue := 'missing_required_secrets';
  ELSIF v_missing_config_count > 0 THEN v_issue := 'missing_required_configuration';
  ELSIF NOT v_tested THEN v_issue := 'connection_test_not_passed';
  ELSIF NOT v_deps_complete THEN v_issue := 'azure_openai_deployments_incomplete';
  ELSE v_issue := 'not_ready';
  END IF;

  RETURN jsonb_build_object(
    'provider', _provider,
    'present', true,
    'integration_id', v_ti.id,
    'is_enabled', v_enabled,
    'status', v_ti.status::text,
    'configuration_ready', (v_missing_config_count = 0),
    'secrets_ready', (v_missing_secret_count = 0),
    'connection_tested_ok', v_tested,
    'deployments_complete', v_deps_complete,
    'ready', v_ready,
    'issue_code', v_issue
  );
END $$;


--
-- Name: _validate_azure_openai_deployments(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._validate_azure_openai_deployments(_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_required text[];
  v_out jsonb := '{}'::jsonb;
  v_k text;
  v_v jsonb;
  v_str text;
BEGIN
  IF _input IS NULL OR jsonb_typeof(_input) <> 'object' THEN
    RAISE EXCEPTION 'azure_openai_deployments_invalid' USING ERRCODE = '22023';
  END IF;

  v_required := public._azure_openai_required_deployment_keys();

  FOR v_k IN SELECT jsonb_object_keys(_input) LOOP
    IF NOT (v_k = ANY(v_required)) THEN
      RAISE EXCEPTION 'azure_openai_deployments_unknown_key' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOREACH v_k IN ARRAY v_required LOOP
    IF NOT (_input ? v_k) THEN
      RAISE EXCEPTION 'azure_openai_deployments_missing_key' USING ERRCODE = '22023';
    END IF;
    v_v := _input -> v_k;
    IF jsonb_typeof(v_v) <> 'string' THEN
      RAISE EXCEPTION 'azure_openai_deployments_invalid_value' USING ERRCODE = '22023';
    END IF;
    v_str := btrim(_input ->> v_k);
    IF v_str = '' THEN
      RAISE EXCEPTION 'azure_openai_deployments_invalid_value' USING ERRCODE = '22023';
    END IF;
    IF char_length(v_str) > 128 THEN
      RAISE EXCEPTION 'azure_openai_deployments_invalid_value' USING ERRCODE = '22023';
    END IF;
    IF v_str ~ '[[:cntrl:]]' OR v_str ~ '[/\\?#]' THEN
      RAISE EXCEPTION 'azure_openai_deployments_invalid_value' USING ERRCODE = '22023';
    END IF;
    v_out := v_out || jsonb_build_object(v_k, to_jsonb(v_str));
  END LOOP;

  RETURN v_out;
END $$;


--
-- Name: _validate_object_links(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._validate_object_links(_links jsonb, _workspace_id uuid, _organization_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_type text;
  v_id uuid;
  v_count int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN RETURN; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(_links) LOOP
    v_type := v->>'referenced_type';
    v_id := (v->>'referenced_id')::uuid;
    IF v_type NOT IN ('project','phase','task') THEN
      RAISE EXCEPTION 'Invalid object link type: %', v_type;
    END IF;
    -- Same-workspace + same-org enforcement
    IF v_type = 'project' THEN
      SELECT count(*) INTO v_count FROM public.projects
       WHERE id = v_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
    ELSIF v_type = 'phase' THEN
      SELECT count(*) INTO v_count FROM public.phases
       WHERE id = v_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
    ELSE
      SELECT count(*) INTO v_count FROM public.tasks
       WHERE id = v_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
    END IF;
    IF v_count = 0 THEN
      RAISE EXCEPTION 'Linked % % is not in this workspace', v_type, v_id;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: _validate_user_links(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._validate_user_links(_links jsonb, _workspace_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
  v_user uuid;
  v_count int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN RETURN; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(_links) LOOP
    v_user := (v->>'user_id')::uuid;
    SELECT count(*) INTO v_count FROM public.workspace_memberships
     WHERE user_id = v_user AND workspace_id = _workspace_id;
    IF v_count = 0 THEN
      RAISE EXCEPTION 'Linked user % is not a member of this workspace', v_user;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: _validate_user_links(jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._validate_user_links(_links jsonb, _workspace_id uuid, _project_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb; v_user uuid; v_stk uuid; v_count int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN RETURN; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(_links) LOOP
    v_user := NULLIF(v->>'user_id','')::uuid;
    v_stk  := NULLIF(v->>'stakeholder_id','')::uuid;
    IF (v_user IS NULL AND v_stk IS NULL) OR (v_user IS NOT NULL AND v_stk IS NOT NULL) THEN
      RAISE EXCEPTION 'Each person link must have exactly one of user_id or stakeholder_id';
    END IF;
    IF v_user IS NOT NULL THEN
      SELECT count(*) INTO v_count FROM public.workspace_memberships
       WHERE user_id = v_user AND workspace_id = _workspace_id;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'Linked user % is not a member of this workspace', v_user;
      END IF;
    ELSE
      IF _project_id IS NULL THEN
        RAISE EXCEPTION 'Stakeholder links require a project context';
      END IF;
      SELECT count(*) INTO v_count FROM public.project_stakeholders
       WHERE id = v_stk AND project_id = _project_id
         AND workspace_id = _workspace_id AND removed_at IS NULL;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'Linked stakeholder % is not an active stakeholder of this project', v_stk;
      END IF;
    END IF;
  END LOOP;
END $$;


--
-- Name: accept_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_invitation(_token uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _inv RECORD;
  _user_id uuid;
  _user_email text;
  _token_hash text;
  _tenant_id uuid;
  _target_org_role public.organization_role;
BEGIN
  _user_id := auth.uid();
  IF _user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_user_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  _token_hash := encode(digest(_token::text, 'sha256'), 'hex');
  SELECT i.id, i.email, i.organization_id, i.workspace_id, i.tenant_id,
         i.tenant_role, i.organization_role, i.role, i.status, i.expires_at
    INTO _inv
    FROM public.invitations i
   WHERE i.token = _token_hash AND i.status = 'pending' AND i.expires_at > now();
  IF _inv.id IS NULL THEN RAISE EXCEPTION 'Invitation not found, expired, or already used'; END IF;

  SELECT email INTO _user_email FROM auth.users WHERE id = _user_id;
  IF lower(_user_email) <> lower(_inv.email) THEN RAISE EXCEPTION 'Invitation email does not match your account'; END IF;

  -- Resolve tenant id from organization when the invitation predates tenant_id column.
  _tenant_id := _inv.tenant_id;
  IF _tenant_id IS NULL AND _inv.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _tenant_id FROM public.organizations WHERE id = _inv.organization_id;
  END IF;

  -- Profile organization link (legacy field, kept for compatibility).
  IF _inv.organization_id IS NOT NULL THEN
    UPDATE public.profiles
       SET organization_id = _inv.organization_id
     WHERE id = _user_id AND (organization_id IS NULL OR organization_id = _inv.organization_id);
  END IF;

  -- Tenant membership (activate if missing/deactivated).
  IF _tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_memberships (tenant_id, user_id, role, status, created_by, updated_by)
    VALUES (_tenant_id, _user_id,
            COALESCE(_inv.tenant_role, 'tenant_member'::public.tenant_role),
            'active'::public.membership_status, _user_id, _user_id)
    ON CONFLICT (tenant_id, user_id) DO UPDATE
      SET status = 'active'::public.membership_status,
          updated_at = now();
  END IF;

  -- Organization membership.
  IF _inv.organization_id IS NOT NULL AND _tenant_id IS NOT NULL THEN
    _target_org_role := COALESCE(
      _inv.organization_role,
      CASE WHEN _inv.role = 'org_admin' THEN 'org_admin'::public.organization_role
           ELSE 'org_member'::public.organization_role END
    );
    INSERT INTO public.organization_memberships
      (tenant_id, organization_id, user_id, role, status, created_by, updated_by)
    VALUES (_tenant_id, _inv.organization_id, _user_id, _target_org_role,
            'active'::public.membership_status, _user_id, _user_id)
    ON CONFLICT (organization_id, user_id) DO UPDATE
      SET status = 'active'::public.membership_status,
          role = CASE WHEN EXCLUDED.role = 'org_admin' THEN 'org_admin'::public.organization_role
                      ELSE public.organization_memberships.role END,
          updated_at = now();
  END IF;

  -- Workspace membership + legacy user_roles preservation.
  IF _inv.workspace_id IS NOT NULL THEN
    INSERT INTO public.workspace_memberships (workspace_id, user_id)
    VALUES (_inv.workspace_id, _user_id) ON CONFLICT (workspace_id, user_id) DO NOTHING;
    IF _inv.role IS NOT NULL AND _inv.role <> 'org_admin' THEN
      INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
      VALUES (_user_id, _inv.role, _inv.organization_id, _inv.workspace_id)
      ON CONFLICT DO NOTHING;
    END IF;
  ELSIF _inv.role = 'org_admin' AND _inv.organization_id IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role, organization_id)
    VALUES (_user_id, 'org_admin', _inv.organization_id) ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.invitations SET status = 'accepted', updated_at = now() WHERE id = _inv.id;

  -- Conservative context seed for single-org users only.
  PERFORM public._seed_single_org_preference(_user_id);

  PERFORM public.log_activity_event(_inv.organization_id, _user_id, 'invitation_accepted',
    'invitation', _inv.id,
    jsonb_build_object('email', _inv.email, 'role', _inv.role::text, 'workspace_id', _inv.workspace_id),
    _inv.workspace_id);
  RETURN _inv.id;
END;
$$;


--
-- Name: accept_pending_invitation_for_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_pending_invitation_for_user(_user_id uuid, _invitation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _inv record;
  _email text;
  _org_tenant uuid;
  _ws_org uuid;
  _ws_org_tenant uuid;
  _profile_org uuid;
  _target_org_role public.organization_role;
  _effective_organization_id uuid;
BEGIN
  IF _user_id IS NULL OR _invitation_id IS NULL THEN
    RAISE EXCEPTION 'accept_pending_invitation_for_user: user_id and invitation_id required';
  END IF;

  SELECT lower(au.email) INTO _email FROM auth.users au WHERE au.id = _user_id;
  IF _email IS NULL THEN RAISE EXCEPTION 'User % has no email', _user_id; END IF;

  SELECT i.id, i.email, i.organization_id, i.workspace_id, i.tenant_id,
         i.tenant_role, i.organization_role, i.role, i.status, i.expires_at
  INTO _inv
  FROM public.invitations i
  WHERE i.id = _invitation_id;

  IF _inv.id IS NULL THEN RAISE EXCEPTION 'Invitation not found'; END IF;
  IF _inv.status <> 'pending' THEN RAISE EXCEPTION 'Invitation is not pending (status=%).', _inv.status; END IF;
  IF _inv.expires_at IS NULL OR _inv.expires_at <= now() THEN RAISE EXCEPTION 'Invitation is expired'; END IF;
  IF lower(_inv.email) <> _email THEN
    RAISE EXCEPTION 'Invitation email does not match authenticated user';
  END IF;
  IF _inv.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Invitation is missing tenant_id (invalid post-4D.2 state)';
  END IF;

  -- Organization -> tenant consistency
  IF _inv.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _inv.organization_id;
    IF _org_tenant IS NULL THEN RAISE EXCEPTION 'Invitation organization not found'; END IF;
    IF _org_tenant <> _inv.tenant_id THEN
      RAISE EXCEPTION 'Invitation tenant does not match organization tenant';
    END IF;
  END IF;

  -- Workspace -> organization -> tenant consistency
  IF _inv.workspace_id IS NOT NULL THEN
    SELECT organization_id INTO _ws_org FROM public.workspaces WHERE id = _inv.workspace_id;
    IF _ws_org IS NULL THEN RAISE EXCEPTION 'Invitation workspace not found'; END IF;
    IF _inv.organization_id IS NOT NULL AND _ws_org <> _inv.organization_id THEN
      RAISE EXCEPTION 'Invitation workspace does not belong to invitation organization';
    END IF;
    SELECT tenant_id INTO _ws_org_tenant FROM public.organizations WHERE id = _ws_org;
    IF _ws_org_tenant IS NULL THEN RAISE EXCEPTION 'Invitation workspace organization not found'; END IF;
    IF _ws_org_tenant <> _inv.tenant_id THEN
      RAISE EXCEPTION 'Invitation workspace organization tenant does not match invitation tenant';
    END IF;
  END IF;

  -- Effective organization: invitation.org > workspace.org > NULL (tenant-only)
  _effective_organization_id := COALESCE(_inv.organization_id, _ws_org);

  -- Profile: never overwrite existing organization_id; set only when currently NULL and we have one
  SELECT organization_id INTO _profile_org FROM public.profiles WHERE id = _user_id;
  IF _profile_org IS NULL AND _effective_organization_id IS NOT NULL THEN
    INSERT INTO public.profiles (id, email, organization_id)
    VALUES (_user_id, _email, _effective_organization_id)
    ON CONFLICT (id) DO UPDATE SET
      organization_id = COALESCE(public.profiles.organization_id, EXCLUDED.organization_id),
      email = COALESCE(public.profiles.email, EXCLUDED.email);
  ELSE
    INSERT INTO public.profiles (id, email)
    VALUES (_user_id, _email)
    ON CONFLICT (id) DO UPDATE SET email = COALESCE(public.profiles.email, EXCLUDED.email);
  END IF;

  -- Tenant membership
  INSERT INTO public.tenant_memberships (tenant_id, user_id, role, status, created_by)
  VALUES (_inv.tenant_id, _user_id, COALESCE(_inv.tenant_role, 'tenant_member'), 'active', _user_id)
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET status = 'active', updated_at = now();

  -- Organization membership (effective org — includes workspace-only derived org)
  IF _effective_organization_id IS NOT NULL THEN
    _target_org_role := COALESCE(
      _inv.organization_role,
      CASE WHEN _inv.role = 'org_admin' THEN 'org_admin'::public.organization_role
           ELSE 'org_member'::public.organization_role END
    );
    INSERT INTO public.organization_memberships
      (tenant_id, organization_id, user_id, role, status, created_by)
    VALUES (_inv.tenant_id, _effective_organization_id, _user_id, _target_org_role, 'active', _user_id)
    ON CONFLICT (organization_id, user_id) DO UPDATE
      SET status = 'active',
          role = CASE
            WHEN EXCLUDED.role = 'org_admin' THEN 'org_admin'::public.organization_role
            ELSE public.organization_memberships.role
          END,
          updated_at = now();
  END IF;

  -- Workspace membership + legacy user_roles preservation
  IF _inv.workspace_id IS NOT NULL THEN
    INSERT INTO public.workspace_memberships (workspace_id, user_id)
    VALUES (_inv.workspace_id, _user_id)
    ON CONFLICT DO NOTHING;

    IF _inv.role IS NOT NULL AND _inv.role <> 'org_admin' AND _effective_organization_id IS NOT NULL THEN
      INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
      VALUES (_user_id, _inv.role, _effective_organization_id, _inv.workspace_id)
      ON CONFLICT DO NOTHING;
    END IF;
  ELSIF _inv.role = 'org_admin' AND _effective_organization_id IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role, organization_id)
    VALUES (_user_id, 'org_admin', _effective_organization_id)
    ON CONFLICT DO NOTHING;
  END IF;

  -- Mark accepted
  UPDATE public.invitations
     SET status = 'accepted', updated_at = now()
   WHERE id = _inv.id AND status = 'pending';

  -- Activity log (best-effort) when organization context exists
  IF _effective_organization_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.activity_events
        (organization_id, actor_id, event_type, target_type, target_id, metadata)
      VALUES (_effective_organization_id, _user_id, 'invitation_accepted', 'invitation', _inv.id,
              jsonb_build_object(
                'email', _email,
                'source', 'accept_pending_invitation_for_user',
                'workspace_id', _inv.workspace_id,
                'effective_organization_id', _effective_organization_id,
                'invitation_organization_id', _inv.organization_id
              )::text);
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'activity_events insert skipped for invitation %: %', _inv.id, SQLERRM;
    END;
  END IF;

  RETURN true;
END $$;


--
-- Name: acknowledge_api_d_policy(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_api_d_policy(_client_key text, _correlation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  _uid uuid := auth.uid();
  _client public.api_clients%rowtype;
  _policy public.api_client_policy_versions%rowtype;
  _policy_count integer;
  _org_count integer;
  _existing public.api_user_policy_acknowledgements%rowtype;
  _reactivated boolean := false;
  _first boolean := false;
  _fail_closed constant jsonb := jsonb_build_object('ok', false, 'changed', false, 'acknowledged', false);
begin
  if _uid is null then return _fail_closed; end if;

  if _client_key is null
     or length(_client_key) < 3 or length(_client_key) > 64
     or _client_key !~ '^[a-z0-9][a-z0-9_.-]{1,62}[a-z0-9]$' then
    return _fail_closed;
  end if;

  if _correlation_id is not null
     and _correlation_id !~ '^[A-Za-z0-9_-]{1,64}$' then
    return _fail_closed;
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = _uid and p.is_active = true
  ) then
    return _fail_closed;
  end if;

  select * into _client
  from public.api_clients
  where client_key = _client_key and lifecycle_status = 'active'
  limit 1;
  if _client.id is null then return _fail_closed; end if;

  select count(*) into _policy_count
  from public.api_client_policy_versions
  where api_client_id = _client.id and lifecycle_status = 'active';
  if _policy_count <> 1 then return _fail_closed; end if;

  select * into _policy
  from public.api_client_policy_versions
  where api_client_id = _client.id and lifecycle_status = 'active'
  limit 1;

  -- Eligible-org gate: authoritative org membership ∩ active tenant chain
  -- ∩ current active tenant membership ∩ enabled API-C org enablement.
  select count(*) into _org_count
  from public.organization_memberships om
  join public.organizations o
    on o.id = om.organization_id
  join public.tenants t
    on t.id = o.tenant_id
   and t.id = om.tenant_id
  join public.tenant_memberships tm_o
    on tm_o.tenant_id = t.id
   and tm_o.user_id = _uid
   and tm_o.status = 'active'
   and tm_o.deactivated_at is null
  join public.api_organization_client_enablements oe
    on oe.organization_id = o.id
   and oe.tenant_id = t.id
   and oe.api_client_id = _client.id
   and oe.lifecycle_status = 'enabled'
  where om.user_id = _uid
    and om.status = 'active'
    and om.deactivated_at is null
    and t.status = 'active'
    and t.suspended_at is null
    and t.archived_at is null
    and t.purged_at is null;

  if _org_count = 0 then return _fail_closed; end if;

  -- Existing acknowledgement row for the exact identity.
  select * into _existing
  from public.api_user_policy_acknowledgements
  where user_id = _uid
    and api_client_id = _client.id
    and policy_version_id = _policy.id
  limit 1;

  if _existing.id is not null and _existing.revoked_at is null then
    -- Idempotent no-op — do not append an audit row.
    return jsonb_build_object('ok', true, 'changed', false, 'acknowledged', true);
  end if;

  if _existing.id is not null then
    -- Reactivate revoked row.
    update public.api_user_policy_acknowledgements
       set revoked_at = null,
           acknowledged_at = now(),
           ack_metadata = jsonb_build_object('source', 'btpm_ui')
     where id = _existing.id;
    _reactivated := true;
  else
    insert into public.api_user_policy_acknowledgements
      (user_id, api_client_id, policy_version_id, acknowledged_at, ack_metadata)
    values
      (_uid, _client.id, _policy.id, now(), jsonb_build_object('source', 'btpm_ui'));
    _first := true;
  end if;

  insert into public.api_consent_audit_events
    (actor_user_id, api_client_id, policy_version_id, action, source_channel, correlation_id)
  values
    (_uid, _client.id, _policy.id, 'acknowledge', 'btpm_ui', _correlation_id);

  return jsonb_build_object('ok', true, 'changed', true, 'acknowledged', true);
exception
  when others then
    return _fail_closed;
end;
$_$;


--
-- Name: ai_instruction_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_instruction_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    feature_key text NOT NULL,
    version integer NOT NULL,
    title text NOT NULL,
    instruction_text text NOT NULL,
    notes text,
    status text DEFAULT 'draft'::text NOT NULL,
    created_by uuid,
    activated_by uuid,
    activated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_instruction_templates_feature_check CHECK ((feature_key = 'decision_case_brief'::text)),
    CONSTRAINT ai_instruction_templates_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text]))),
    CONSTRAINT ai_instruction_templates_version_pos CHECK ((version > 0))
);


--
-- Name: activate_ai_instruction_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_ai_instruction_template(_id uuid) RETURNS public.ai_instruction_templates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
  _row public.ai_instruction_templates;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.ai_instruction_templates WHERE id = _id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'template not found'; END IF;
  IF _row.organization_id <> _org_id THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF _row.status = 'archived' THEN RAISE EXCEPTION 'cannot activate archived version'; END IF;
  IF _row.status = 'active' THEN RETURN _row; END IF;

  -- AI.8.1e: demote previously active version to 'draft' (was 'archived'),
  -- so version switching remains reversible. Explicit archive remains the only
  -- path to 'archived' via archive_ai_instruction_template.
  UPDATE public.ai_instruction_templates
     SET status = 'draft'
   WHERE organization_id = _org_id
     AND feature_key = _row.feature_key
     AND status = 'active'
     AND id <> _id;

  UPDATE public.ai_instruction_templates
     SET status = 'active',
         activated_by = auth.uid(),
         activated_at = now()
   WHERE id = _id
  RETURNING * INTO _row;

  RETURN _row;
END;
$$;


--
-- Name: add_adoption_template_tasks_to_existing_plan(uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_adoption_template_tasks_to_existing_plan(_project_id uuid, _template_id uuid DEFAULT NULL::uuid, _template_key text DEFAULT 'btpm_standard_adoption'::text, _selected_task_keys text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _ws uuid;
  _plan_id uuid;
  _phase_id uuid;
  _phase_start date;
  _phase_end date;
  _created_initiatives int := 0;
  _created_tasks int := 0;
  _skipped int := 0;
  _selected_count int := 0;
  _existing_titles text[] := ARRAY[]::text[];
  _init_key text;
  _task_key text;
  _init_name text;
  _init_readiness text;
  _init_sort int;
  _init_summary text;
  _task_title text;
  _task_desc text;
  _norm_title text;
  _initiative_id uuid;
  _next_sort int;
  _is_standard boolean := (_template_id IS NULL);
  _max_init_sort int;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT organization_id, workspace_id INTO _org, _ws
  FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_project'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT id INTO _plan_id
  FROM public.adoption_plans
  WHERE project_id = _project_id AND is_archived = false
  LIMIT 1;
  IF _plan_id IS NULL THEN
    RAISE EXCEPTION 'adoption_plan_required';
  END IF;

  IF _is_standard THEN
    IF COALESCE(_template_key, 'btpm_standard_adoption') <> 'btpm_standard_adoption' THEN
      RAISE EXCEPTION 'invalid_template_key';
    END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.adoption_templates
      WHERE id = _template_id AND workspace_id = _ws AND is_archived = false
    ) THEN
      RAISE EXCEPTION 'invalid_template';
    END IF;
  END IF;

  SELECT phase_id INTO _phase_id
  FROM public.tasks
  WHERE project_id = _project_id
    AND is_archived = false
    AND is_adoption_related = true
    AND phase_id IS NOT NULL
  GROUP BY phase_id
  ORDER BY count(*) DESC
  LIMIT 1;

  IF _phase_id IS NULL THEN
    RAISE EXCEPTION 'adoption_phase_not_found';
  END IF;

  SELECT start_date, target_end_date INTO _phase_start, _phase_end
  FROM public.phases WHERE id = _phase_id;

  IF EXISTS (SELECT 1 FROM public.projects WHERE id = _project_id AND COALESCE(is_baselined,false))
     AND (_phase_start IS NULL OR _phase_end IS NULL) THEN
    RAISE EXCEPTION 'adoption_phase_dates_required_for_baselined_project';
  END IF;

  IF _selected_task_keys IS NULL OR array_length(_selected_task_keys, 1) IS NULL THEN
    RAISE EXCEPTION 'adoption_template_selection_empty';
  END IF;
  _selected_count := array_length(_selected_task_keys, 1);

  SELECT COALESCE(array_agg(DISTINCT lower(btrim(regexp_replace(
      public.btpm_decrypt(name, organization_id), '\s+', ' ', 'g')))), ARRAY[]::text[])
    INTO _existing_titles
  FROM public.tasks
  WHERE project_id = _project_id
    AND is_archived = false
    AND is_adoption_related = true;

  SELECT COALESCE(MAX(sort_order), -1) INTO _max_init_sort
  FROM public.adoption_initiatives
  WHERE adoption_plan_id = _plan_id AND is_archived = false;

  FOR _init_key, _task_key IN
    SELECT split_part(k,'.',1) AS ik,
           substring(k from position('.' in k)+1) AS tk
    FROM unnest(_selected_task_keys) AS k
    WHERE position('.' in k) > 0
  LOOP
    _init_name := NULL; _init_readiness := NULL; _init_sort := NULL; _init_summary := NULL;
    _task_title := NULL; _task_desc := NULL;

    IF _is_standard THEN
      SELECT i->>'name', i->>'readiness_area', (i->>'sort_order')::int, i->>'summary',
             t->>'title', NULL::text
        INTO _init_name, _init_readiness, _init_sort, _init_summary,
             _task_title, _task_desc
      FROM jsonb_array_elements(public._btpm_adoption_template_v1()) AS i,
           jsonb_array_elements(i->'tasks') AS t
      WHERE i->>'key' = _init_key AND t->>'key' = _task_key;
    ELSE
      SELECT public.btpm_decrypt(i.name, i.organization_id),
             i.readiness_area, i.sort_order,
             public.btpm_decrypt(i.summary, i.organization_id),
             public.btpm_decrypt(t.title, t.organization_id),
             public.btpm_decrypt(t.description, t.organization_id)
        INTO _init_name, _init_readiness, _init_sort, _init_summary,
             _task_title, _task_desc
      FROM public.adoption_template_initiatives i
      JOIN public.adoption_template_tasks t ON t.adoption_template_initiative_id = i.id
      WHERE i.adoption_template_id = _template_id
        AND i.is_archived = false AND t.is_archived = false
        AND i.template_key = _init_key AND t.template_key = _task_key
      LIMIT 1;
    END IF;

    IF _task_title IS NULL OR btrim(_task_title) = '' THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    _norm_title := lower(btrim(regexp_replace(_task_title, '\s+', ' ', 'g')));

    IF _norm_title = ANY(_existing_titles) THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    SELECT id INTO _initiative_id
    FROM public.adoption_initiatives
    WHERE adoption_plan_id = _plan_id AND is_archived = false
      AND readiness_area = _init_readiness
    LIMIT 1;

    IF _initiative_id IS NULL THEN
      _max_init_sort := _max_init_sort + 1;
      INSERT INTO public.adoption_initiatives(
        organization_id, workspace_id, project_id, adoption_plan_id,
        name, summary, readiness_area, status, priority, sort_order, created_by
      ) VALUES (
        _org, _ws, _project_id, _plan_id,
        _init_name, _init_summary, _init_readiness,
        'planned'::public.adoption_initiative_status,
        'medium'::public.pm_priority,
        _max_init_sort, _uid
      ) RETURNING id INTO _initiative_id;
      _created_initiatives := _created_initiatives + 1;
    END IF;

    SELECT COALESCE(MAX(sort_order), -1) + 10 INTO _next_sort
    FROM public.tasks WHERE phase_id = _phase_id AND is_archived = false;

    INSERT INTO public.tasks(
      organization_id, workspace_id, project_id, phase_id,
      name, description, task_type, status, priority, sort_order,
      start_date, due_date,
      is_adoption_related, adoption_initiative_id, created_by
    ) VALUES (
      _org, _ws, _project_id, _phase_id,
      _task_title, _task_desc,
      'work_item'::public.task_type,
      'planned'::public.pm_status,
      'medium'::public.pm_priority,
      _next_sort,
      _phase_start, _phase_end,
      true, _initiative_id, _uid
    );
    _created_tasks := _created_tasks + 1;
    _existing_titles := _existing_titles || _norm_title;
  END LOOP;

  PERFORM public.log_activity_event(
    _org,
    _uid,
    'adoption_template_tasks_added',
    'project',
    _project_id,
    jsonb_build_object(
      'adoption_plan_id', _plan_id,
      'phase_id', _phase_id,
      'template_id', _template_id,
      'template_key', CASE WHEN _is_standard THEN _template_key ELSE NULL END,
      'created_initiative_count', _created_initiatives,
      'created_task_count', _created_tasks,
      'skipped_duplicate_count', _skipped,
      'selected_task_count', _selected_count
    ),
    _ws
  );

  RETURN jsonb_build_object(
    'project_id', _project_id,
    'adoption_plan_id', _plan_id,
    'phase_id', _phase_id,
    'template_id', _template_id,
    'template_key', CASE WHEN _is_standard THEN _template_key ELSE NULL END,
    'created_initiative_count', _created_initiatives,
    'created_task_count', _created_tasks,
    'skipped_duplicate_count', _skipped,
    'selected_task_count', _selected_count
  );
END $$;


--
-- Name: add_project_people_preset_member(uuid, timestamp with time zone, text, text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_project_people_preset_member(_preset_id uuid, _expected_preset_updated_at timestamp with time zone, _member_kind text, _stakeholder_type text, _user_id uuid, _external_name text, _canonical_role_key text, _role_label text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor          uuid := auth.uid();
  v_preset         public.project_people_presets;
  v_new_id         uuid;
  v_role_norm      text;
  v_canonical_norm text;
  v_external_norm  text;
  v_dupe_external  uuid;
  r                record;
BEGIN
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR UPDATE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'add_project_people_preset_member',
      'project_people_preset_member', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  IF v_preset.updated_at IS DISTINCT FROM _expected_preset_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'add_project_people_preset_member',
      'project_people_preset_member', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  IF _member_kind NOT IN ('team_member','stakeholder') THEN
    RETURN public.pmg_build_result('invalid', 'add_project_people_preset_member',
      'project_people_preset_member', NULL, NULL,
      jsonb_build_object('reason','invalid_member_kind'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  v_role_norm      := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_canonical_norm := NULLIF(btrim(COALESCE(_canonical_role_key, '')), '');
  v_external_norm  := NULLIF(btrim(COALESCE(_external_name, '')), '');

  IF _member_kind = 'stakeholder' AND _stakeholder_type = 'external' THEN
    IF v_external_norm IS NULL THEN
      RETURN public.pmg_build_result('invalid', 'add_project_people_preset_member',
        'project_people_preset_member', NULL, NULL,
        jsonb_build_object('reason','external_name_required'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
    -- decrypt-compare within preset for case-insensitive duplicate external name
    FOR r IN
      SELECT id, external_name FROM public.project_people_preset_members
       WHERE preset_id = _preset_id
         AND member_kind = 'stakeholder' AND stakeholder_type = 'external'
       FOR UPDATE
    LOOP
      IF lower(btrim(public.btpm_decrypt(r.external_name, v_preset.organization_id))) = lower(v_external_norm) THEN
        v_dupe_external := r.id; EXIT;
      END IF;
    END LOOP;
    IF v_dupe_external IS NOT NULL THEN
      RETURN public.pmg_build_result('no_change', 'add_project_people_preset_member',
        'project_people_preset_member', v_dupe_external, NULL,
        jsonb_build_object('id', v_dupe_external, 'reason','duplicate_external_name'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.project_people_preset_members (
      preset_id, member_kind, stakeholder_type,
      user_id, external_name, canonical_role_key, role_label
    ) VALUES (
      _preset_id, _member_kind,
      CASE WHEN _member_kind = 'stakeholder' THEN _stakeholder_type ELSE NULL END,
      CASE WHEN _member_kind = 'team_member' OR (_member_kind='stakeholder' AND _stakeholder_type='workspace_member') THEN _user_id ELSE NULL END,
      CASE WHEN _member_kind = 'stakeholder' AND _stakeholder_type = 'external' THEN v_external_norm ELSE NULL END,
      CASE WHEN _member_kind = 'team_member' THEN v_canonical_norm ELSE NULL END,
      v_role_norm
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN unique_violation THEN
      RETURN public.pmg_build_result('no_change', 'add_project_people_preset_member',
        'project_people_preset_member', NULL, NULL,
        jsonb_build_object('reason','already_member'),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_text_representation OR raise_exception THEN
      RETURN public.pmg_build_result('invalid', 'add_project_people_preset_member',
        'project_people_preset_member', NULL, NULL,
        jsonb_build_object('reason', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END;

  -- Touch parent updated_at so library views refresh
  UPDATE public.project_people_presets SET updated_at = now() WHERE id = _preset_id;

  PERFORM public._ppp_record_audit('applied', 'add_project_people_preset_member',
    v_preset, 'project_people_preset_member', v_new_id, _correlation_id, _idempotency_key,
    jsonb_build_object('member_kind', _member_kind, 'stakeholder_type', _stakeholder_type));

  RETURN public.pmg_build_result('applied', 'add_project_people_preset_member',
    'project_people_preset_member', v_new_id, NULL,
    jsonb_build_object('id', v_new_id, 'preset_id', _preset_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $$;


--
-- Name: add_project_stakeholder(uuid, text, uuid, text, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_project_stakeholder(_project_id uuid, _stakeholder_type text, _user_id uuid, _external_name text, _role_label text, _notes text, _start_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor uuid := auth.uid(); v_org uuid; v_ws uuid; v_new_id uuid; v_display text;
  v_role_label text := NULLIF(btrim(COALESCE(_role_label, '')), '');
  v_notes text := NULLIF(btrim(COALESCE(_notes, '')), '');
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT organization_id, workspace_id INTO v_org, v_ws FROM public.projects WHERE id = _project_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.has_project_pm_authority(v_actor, _project_id) THEN
    RAISE EXCEPTION 'Not authorized to manage stakeholders'; END IF;
  IF _stakeholder_type = 'workspace_member' THEN
    IF _user_id IS NULL THEN RAISE EXCEPTION 'user_id required for workspace_member'; END IF;
    IF NOT public.is_workspace_member(_user_id, v_ws) THEN
      RAISE EXCEPTION 'Selected user is not a workspace member'; END IF;
    IF EXISTS (SELECT 1 FROM public.project_stakeholders WHERE project_id = _project_id
      AND stakeholder_type='workspace_member' AND user_id=_user_id AND removed_at IS NULL) THEN
      RAISE EXCEPTION 'This member is already an active stakeholder'; END IF;
    SELECT COALESCE(display_name, email, _user_id::text) INTO v_display FROM public.profiles WHERE id=_user_id;
  ELSIF _stakeholder_type = 'external' THEN
    IF _external_name IS NULL OR length(btrim(_external_name)) = 0 THEN
      RAISE EXCEPTION 'external_name required for external stakeholder'; END IF;
    v_display := btrim(_external_name);
  ELSE RAISE EXCEPTION 'Invalid stakeholder_type'; END IF;
  INSERT INTO public.project_stakeholders (organization_id, workspace_id, project_id, stakeholder_type,
    user_id, external_name, role_label, notes, start_date, created_by)
  VALUES (v_org, v_ws, _project_id, _stakeholder_type,
    CASE WHEN _stakeholder_type='workspace_member' THEN _user_id ELSE NULL END,
    CASE WHEN _stakeholder_type='external' THEN btrim(_external_name) ELSE NULL END,
    v_role_label, v_notes, _start_date, v_actor) RETURNING id INTO v_new_id;
  PERFORM public.log_activity_event(v_org, v_actor, 'stakeholder_added', 'project', _project_id,
    jsonb_build_object('stakeholder_id', v_new_id, 'stakeholder_type', _stakeholder_type,
      'display_name', v_display, 'role_label', v_role_label, 'start_date', _start_date), v_ws);
  RETURN v_new_id;
END; $$;


--
-- Name: add_roadmap_story_pack_external_file(uuid, text, text, text, text, text, text, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_roadmap_story_pack_external_file(_story_pack_id uuid, _drive_id text, _item_id text, _display_name text DEFAULT NULL::text, _web_url text DEFAULT NULL::text, _user_note text DEFAULT NULL::text, _mime_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _include_in_story boolean DEFAULT true, _provider text DEFAULT 'sharepoint'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _new_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);
  IF _provider IS NULL OR _provider <> 'sharepoint' THEN
    RAISE EXCEPTION 'unsupported provider' USING ERRCODE = '22023';
  END IF;

  SELECT organization_id INTO _org_id FROM public.roadmap_story_packs WHERE id = _story_pack_id;

  INSERT INTO public.roadmap_story_pack_external_files (
    story_pack_id, provider, drive_id, item_id,
    display_name_encrypted, web_url_encrypted, user_note_encrypted,
    mime_type, size_bytes, include_in_story, created_by
  ) VALUES (
    _story_pack_id, _provider, _drive_id, _item_id,
    CASE WHEN _display_name IS NULL OR _display_name = '' THEN NULL ELSE public.btpm_encrypt(_display_name, _org_id) END,
    CASE WHEN _web_url      IS NULL OR _web_url      = '' THEN NULL ELSE public.btpm_encrypt(_web_url,      _org_id) END,
    CASE WHEN _user_note    IS NULL OR _user_note    = '' THEN NULL ELSE public.btpm_encrypt(_user_note,    _org_id) END,
    _mime_type, _size_bytes, COALESCE(_include_in_story, true), _uid
  ) RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$$;


--
-- Name: add_roadmap_story_pack_note(uuid, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_roadmap_story_pack_note(_story_pack_id uuid, _body text, _label text DEFAULT NULL::text, _include_in_story boolean DEFAULT true, _sort_order integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _new_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);
  IF _body IS NULL OR length(_body) = 0 THEN
    RAISE EXCEPTION 'body required' USING ERRCODE = '22023';
  END IF;

  SELECT organization_id INTO _org_id FROM public.roadmap_story_packs WHERE id = _story_pack_id;

  INSERT INTO public.roadmap_story_pack_notes (
    story_pack_id, label_encrypted, body_encrypted, include_in_story, sort_order, created_by
  ) VALUES (
    _story_pack_id,
    CASE WHEN _label IS NULL OR _label = '' THEN NULL ELSE public.btpm_encrypt(_label, _org_id) END,
    public.btpm_encrypt(_body, _org_id),
    COALESCE(_include_in_story, true),
    _sort_order,
    _uid
  ) RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$$;


--
-- Name: adjust_governance_cadence_next_expected_date(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_governance_cadence_next_expected_date(_cadence_id uuid, _next_expected_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _row governance_cadences%ROWTYPE; _old date; v_client_id text; v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot adjust archived cadence' USING ERRCODE='42501';
  END IF;
  IF _row.frequency_type <> 'ad_hoc' AND _next_expected_date IS NULL THEN
    RAISE EXCEPTION 'Non-ad-hoc cadence requires a next expected date' USING ERRCODE='22023';
  END IF;
  _old := _row.next_expected_date;
  UPDATE governance_cadences
    SET next_expected_date = _next_expected_date,
        updated_at = now(),
        updated_by = v_caller
    WHERE id = _cadence_id;
  PERFORM log_activity_event(_row.organization_id, v_caller,
    'governance_cadence_next_expected_date_adjusted', 'governance_cadence', _cadence_id,
    jsonb_build_object('project_id', _row.project_id,
                       'cadence_id', _cadence_id,
                       'old_next_expected_date', _old,
                       'new_next_expected_date', _next_expected_date,
                       'event_type', _row.event_type,
                       'frequency_type', _row.frequency_type),
    _row.workspace_id);
END; $$;


--
-- Name: admin_add_portfolio_team_member(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_add_portfolio_team_member(_portfolio_item_id uuid, _user_id uuid, _role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _user_active boolean;
  _user_exists boolean;
  _existing_id uuid;
  _existing_active boolean;
  v_client_id text;
BEGIN
  -- External-OAuth denial (Portfolio-12E.1; must precede all executable business logic).
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  IF _role NOT IN (
    'product_manager','commercial_lead','finance_partner','supply_lead',
    'regulatory_lead','quality_lead','tech_services_lead','launch_lead',
    'bd_lead','srm_lead','other'
  ) THEN RAISE EXCEPTION 'Invalid role'; END IF;

  -- Target-user existence and activation state.
  -- profiles.is_active is read ONLY for activation state, never for Organization membership.
  SELECT true, is_active INTO _user_exists, _user_active
    FROM public.profiles WHERE id = _user_id;
  IF _user_exists IS NOT TRUE THEN RAISE EXCEPTION 'User not found'; END IF;

  -- Canonical, transition-aware Organization membership (replaces legacy
  -- profiles.organization_id pointer comparison). Gates both the new-add and
  -- reactivation paths, before any Team-row lookup, mutation or activity event.
  IF public.is_user_org_member(_user_id, _org) IS NOT TRUE THEN
    RAISE EXCEPTION 'User must belong to the same organization';
  END IF;

  IF NOT COALESCE(_user_active, false) THEN RAISE EXCEPTION 'User is deactivated'; END IF;

  -- Look for existing row (active or inactive) for same portfolio+user+role
  SELECT id, is_active INTO _existing_id, _existing_active
    FROM public.portfolio_item_team_members
   WHERE portfolio_item_id = _portfolio_item_id
     AND user_id = _user_id
     AND role = _role
   ORDER BY is_active DESC, updated_at DESC
   LIMIT 1;

  IF _existing_id IS NOT NULL THEN
    IF _existing_active THEN
      -- No-op: already active
      RETURN _existing_id;
    ELSE
      UPDATE public.portfolio_item_team_members
         SET is_active = true, updated_by = _uid
       WHERE id = _existing_id;

      PERFORM public.log_activity_event(
        _org, _uid, 'portfolio_team_member_added', 'portfolio', _portfolio_item_id,
        jsonb_build_object('user_id', _user_id, 'role', _role, 'reactivated', true),
        NULL::uuid
      );
      RETURN _existing_id;
    END IF;
  END IF;

  INSERT INTO public.portfolio_item_team_members (
    portfolio_item_id, organization_id, user_id, role, created_by, updated_by
  ) VALUES (
    _portfolio_item_id, _org, _user_id, _role, _uid, _uid
  ) RETURNING id INTO _existing_id;

  PERFORM public.log_activity_event(
    _org, _uid, 'portfolio_team_member_added', 'portfolio', _portfolio_item_id,
    jsonb_build_object('user_id', _user_id, 'role', _role),
    NULL::uuid
  );

  RETURN _existing_id;
END;
$$;


--
-- Name: admin_add_workspace_access(uuid, uuid, uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_add_workspace_access(_organization_id uuid, _target_user_id uuid, _workspace_id uuid, _role public.app_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _ws_name text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN
    RAISE EXCEPTION 'User not found';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workspaces WHERE id = _workspace_id AND organization_id = _organization_id) THEN
    RAISE EXCEPTION 'Workspace not found';
  END IF;
  IF _role IN ('org_admin') THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;

  -- Ensure tenant + organization membership layers exist first.
  PERFORM public._ensure_membership_layers(_target_user_id, _organization_id, auth.uid());

  INSERT INTO public.workspace_memberships (workspace_id, user_id)
    VALUES (_workspace_id, _target_user_id)
    ON CONFLICT (workspace_id, user_id) DO NOTHING;
  DELETE FROM public.user_roles
    WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
    VALUES (_target_user_id, _role, _organization_id, _workspace_id);

  -- Conservative context seed for single-org users only.
  PERFORM public._seed_single_org_preference(_target_user_id);

  SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'workspace_access_added',
    'user', _target_user_id,
    jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name, 'role', _role::text),
    _workspace_id);
END;
$$;


--
-- Name: admin_archive_portfolio_item(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_archive_portfolio_item(_portfolio_item_id uuid, _is_archived boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  v_client_id text;
BEGIN
  -- ---------------------------------------------------------------------
  -- External-OAuth denial (must precede all executable business logic).
  -- Server-derived identity only; no caller-supplied client/source/capability
  -- input is accepted. Resolution failure fails closed as external.
  -- ---------------------------------------------------------------------
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;

  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  UPDATE public.portfolio_items
     SET is_archived = _is_archived,
         archived_at = CASE WHEN _is_archived THEN now() ELSE NULL END,
         updated_by = _uid
   WHERE id = _portfolio_item_id;

  PERFORM public.log_activity_event(
    _org, _uid,
    CASE WHEN _is_archived THEN 'portfolio_archived' ELSE 'portfolio_unarchived' END,
    'portfolio', _portfolio_item_id, NULL::jsonb, NULL::uuid
  );
END;
$$;


--
-- Name: admin_assign_projects_to_portfolio(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_assign_projects_to_portfolio(_portfolio_item_id uuid, _project_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _archived boolean;
  _assigned int := 0;
  _reassigned int := 0;
  _skipped int := 0;
  _affected uuid[] := ARRAY[]::uuid[];
  _rec record;
  v_client_id text;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF _project_ids IS NULL OR array_length(_project_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one project must be selected';
  END IF;

  SELECT organization_id, is_archived INTO _org, _archived
    FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF _archived THEN RAISE EXCEPTION 'Portfolio item is archived and cannot receive new assignments'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  FOR _rec IN
    SELECT p.id, p.organization_id, p.workspace_id, p.portfolio_item_id AS current_pi
      FROM public.projects p
     WHERE p.id = ANY(_project_ids)
  LOOP
    IF _rec.organization_id <> _org THEN
      RAISE EXCEPTION 'Project % belongs to a different organization', _rec.id;
    END IF;

    IF _rec.current_pi IS NOT DISTINCT FROM _portfolio_item_id THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    UPDATE public.projects
       SET portfolio_item_id = _portfolio_item_id,
           updated_at = now()
     WHERE id = _rec.id;

    IF _rec.current_pi IS NULL THEN
      _assigned := _assigned + 1;
    ELSE
      _reassigned := _reassigned + 1;
    END IF;
    _affected := _affected || _rec.id;

    PERFORM public.log_activity_event(
      _org, _uid, 'project_portfolio_changed', 'project', _rec.id,
      jsonb_build_object(
        'old_portfolio_item_id', _rec.current_pi,
        'new_portfolio_item_id', _portfolio_item_id,
        'source', 'admin_portfolio_manage'
      ),
      _rec.workspace_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'assigned_count', _assigned,
    'reassigned_count', _reassigned,
    'skipped_count', _skipped,
    'affected_project_ids', to_jsonb(_affected)
  );
END;
$$;


--
-- Name: admin_change_workspace_role(uuid, uuid, uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_change_workspace_role(_organization_id uuid, _target_user_id uuid, _workspace_id uuid, _new_role public.app_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _ws_name text; _old_role text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workspace_memberships WHERE user_id = _target_user_id AND workspace_id = _workspace_id) THEN RAISE EXCEPTION 'User is not a member'; END IF;
  IF _new_role IN ('org_admin') THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  SELECT ur.role::text INTO _old_role FROM public.user_roles ur WHERE ur.user_id = _target_user_id AND ur.workspace_id = _workspace_id AND ur.organization_id = _organization_id LIMIT 1;
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
  INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id) VALUES (_target_user_id, _new_role, _organization_id, _workspace_id);
  SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'workspace_role_changed', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name, 'old_role', _old_role, 'new_role', _new_role::text), _workspace_id);
END;
$$;


--
-- Name: admin_create_invitation(uuid, text, uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_create_invitation(_organization_id uuid, _email text, _workspace_id uuid, _role public.app_role) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _caller_id uuid; _inv_id uuid; _ws_name text; _raw_token uuid; _token_hash text; _tenant uuid;
BEGIN
  _caller_id := auth.uid(); IF _caller_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_caller_id) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(_caller_id, _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT tenant_id INTO _tenant FROM public.organizations WHERE id = _organization_id;
  IF _tenant IS NULL THEN RAISE EXCEPTION 'Organization tenant not resolvable'; END IF;
  IF _workspace_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.workspaces WHERE id = _workspace_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'Workspace not found'; END IF;
  IF _role = 'org_admin' AND _workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Cannot assign org_admin as workspace role'; END IF;
  IF EXISTS (SELECT 1 FROM public.invitations WHERE organization_id = _organization_id AND lower(email) = lower(_email) AND status='pending' AND expires_at > now()) THEN RAISE EXCEPTION 'A pending invitation already exists for this email'; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE organization_id = _organization_id AND lower(email) = lower(_email)) THEN RAISE EXCEPTION 'This email already belongs to an accepted user'; END IF;
  _raw_token := gen_random_uuid(); _token_hash := encode(digest(_raw_token::text, 'sha256'), 'hex');
  INSERT INTO public.invitations (email, organization_id, workspace_id, role, invited_by, status, token, tenant_id, organization_role)
  VALUES (lower(_email), _organization_id, _workspace_id, _role, _caller_id, 'pending', _token_hash, _tenant,
          CASE WHEN _role = 'org_admin' THEN 'org_admin'::public.organization_role ELSE 'org_member'::public.organization_role END)
  RETURNING id INTO _inv_id;
  IF _workspace_id IS NOT NULL THEN SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id; END IF;
  PERFORM public.log_activity_event(_organization_id, _caller_id, 'invitation_created', 'invitation', _inv_id, jsonb_build_object('email', lower(_email), 'role', _role::text, 'workspace_id', _workspace_id, 'workspace_name', _ws_name, 'tenant_id', _tenant), _workspace_id);
  RETURN _inv_id;
END $$;


--
-- Name: admin_create_portfolio_item(uuid, text, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_create_portfolio_item(_organization_id uuid, _name text, _code text DEFAULT NULL::text, _description text DEFAULT NULL::text, _lifecycle_state text DEFAULT 'opportunity_candidate'::text, _owner_id uuid DEFAULT NULL::uuid, _strategic_priority text DEFAULT 'medium'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- API-Q Portfolio-12B.2A: server-derived external OAuth identity. Never caller-provided.
  v_client_id text;
  v_trusted boolean := false;
  v_trusted_channel text;
  _uid uuid := auth.uid();
  _new_id uuid;
  _name_trim text;
BEGIN
  -- 0. Source-awareness + exact-capability containment.
  --    Runs before active-user evaluation, Organization authority evaluation,
  --    owner lookup, narrative validation, INSERT, encryption triggers and
  --    activity logging.
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    BEGIN
      v_trusted := api_e_private.assert_trusted_context();
    EXCEPTION WHEN OTHERS THEN
      v_trusted := false;
    END;

    v_trusted_channel := nullif(btrim(coalesce(current_setting('api_e.source_channel', true),'')),'');

    IF v_trusted IS NOT TRUE
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.api_version', true),'')),''), '') <> 'v1'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_kind', true),'')),''), '') <> 'command'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_key', true),'')),''), '') <> 'portfolios:create'
       OR v_trusted_channel IS NULL
       OR v_trusted_channel NOT IN ('external_api','mcp')
    THEN
      -- Fail closed: bounded generic authorization error, no business detail.
      RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  _name_trim := btrim(COALESCE(_name, ''));
  IF _name_trim = '' THEN RAISE EXCEPTION 'Name is required'; END IF;
  IF char_length(_name_trim) > 200 THEN RAISE EXCEPTION 'Name exceeds 200 characters'; END IF;
  IF _code IS NOT NULL AND char_length(_code) > 80 THEN RAISE EXCEPTION 'Code exceeds 80 characters'; END IF;
  IF _description IS NOT NULL AND char_length(_description) > 4000 THEN RAISE EXCEPTION 'Description exceeds 4000 characters'; END IF;
  IF _lifecycle_state NOT IN (
    'opportunity_candidate','business_case_approved','contracted','development',
    'submission_approval','launch_preparation','launched_commercial',
    'lcm_optimization','on_hold','discontinuation','retired'
  ) THEN RAISE EXCEPTION 'Invalid lifecycle_state'; END IF;
  IF _strategic_priority NOT IN ('critical','high','medium','low','watchlist') THEN
    RAISE EXCEPTION 'Invalid strategic_priority';
  END IF;
  -- API-Q Portfolio-12C.1: authoritative Organization membership, not the legacy
  -- profiles.organization_id home pointer.
  IF _owner_id IS NOT NULL THEN
    IF public.is_user_org_member(_owner_id, _organization_id) IS NOT TRUE THEN
      RAISE EXCEPTION 'Owner must belong to the same organization';
    END IF;
  END IF;

  INSERT INTO public.portfolio_items (
    organization_id, name, code, description, lifecycle_state, strategic_priority, owner_id, created_by, updated_by
  ) VALUES (
    _organization_id, _name_trim, _code, _description, _lifecycle_state, _strategic_priority, _owner_id, _uid, _uid
  ) RETURNING id INTO _new_id;

  PERFORM public.log_activity_event(
    _organization_id, _uid, 'portfolio_created', 'portfolio', _new_id, NULL::jsonb, NULL::uuid
  );

  RETURN _new_id;
END;
$$;


--
-- Name: admin_deactivate_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_deactivate_user(_organization_id uuid, _target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot deactivate yourself'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  UPDATE public.profiles SET is_active = false, updated_at = now() WHERE id = _target_user_id AND organization_id = _organization_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'user_deactivated', 'user', _target_user_id, '{}'::jsonb, NULL);
END;
$$;


--
-- Name: admin_delete_invitation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_invitation(_organization_id uuid, _invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _email text; _ws_id uuid;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT email, workspace_id INTO _email, _ws_id FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status IN ('pending','revoked','expired','declined');
  DELETE FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status IN ('pending','revoked','expired','declined');
  IF NOT FOUND THEN RAISE EXCEPTION 'Invitation not found or cannot be deleted'; END IF;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'invitation_deleted', 'invitation', _invitation_id, jsonb_build_object('email', _email), _ws_id);
END;
$$;


--
-- Name: admin_delete_knowledge_article_ai_metadata(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_knowledge_article_ai_metadata(_article_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  DELETE FROM public.knowledge_article_ai_metadata m
  USING public.knowledge_articles a
  WHERE m.article_id = _article_id
    AND a.id = m.article_id
    AND a.organization_id = v_org;
END;
$$;


--
-- Name: admin_delete_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_user(_organization_id uuid, _target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _target_email text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot delete yourself'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _target_user_id AND organization_id = _organization_id AND role = 'org_admin' AND workspace_id IS NULL) THEN
    IF (SELECT count(*) FROM public.user_roles WHERE organization_id = _organization_id AND role = 'org_admin' AND workspace_id IS NULL) <= 1 THEN RAISE EXCEPTION 'Cannot delete the last org admin'; END IF;
  END IF;
  IF EXISTS (SELECT ur.workspace_id FROM public.user_roles ur WHERE ur.user_id = _target_user_id AND ur.organization_id = _organization_id AND ur.role = 'workspace_admin' AND ur.workspace_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.user_roles ur2 WHERE ur2.workspace_id = ur.workspace_id AND ur2.role = 'workspace_admin' AND ur2.user_id != _target_user_id)) THEN RAISE EXCEPTION 'Cannot delete: last workspace admin. Reassign first.'; END IF;
  SELECT email INTO _target_email FROM public.profiles WHERE id = _target_user_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'user_deleted', 'user', _target_user_id, jsonb_build_object('email', _target_email), NULL);
  UPDATE public.comments SET author_id = '00000000-0000-0000-0000-000000000000' WHERE author_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.execution_updates SET author_id = '00000000-0000-0000-0000-000000000000' WHERE author_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.activity_events SET actor_id = NULL WHERE actor_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.blockers SET reported_by = NULL WHERE reported_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.blockers SET resolved_by = NULL WHERE resolved_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.risks SET reported_by = NULL WHERE reported_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.tasks SET owner_id = NULL WHERE owner_id = _target_user_id AND organization_id = _organization_id;
  UPDATE public.tasks SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.phases SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.projects SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.programs SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  UPDATE public.kpi_definitions SET created_by = NULL WHERE created_by = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.task_assignments WHERE assignee_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.task_assignments WHERE assigned_by = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.raci_assignments WHERE user_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.project_team_members WHERE user_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.kpi_updates WHERE author_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.workspace_memberships wm USING public.workspaces w WHERE wm.workspace_id = w.id AND w.organization_id = _organization_id AND wm.user_id = _target_user_id;
  UPDATE public.invitations SET invited_by = auth.uid() WHERE invited_by = _target_user_id AND organization_id = _organization_id;
  DELETE FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id;
END;
$$;


--
-- Name: tenant_secret_refs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_secret_refs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    integration_id uuid NOT NULL,
    secret_name text NOT NULL,
    secret_kind text NOT NULL,
    secret_scope public.tenant_secret_scope DEFAULT 'tenant'::public.tenant_secret_scope NOT NULL,
    vault_secret_id uuid,
    secret_fingerprint text,
    status public.tenant_secret_status DEFAULT 'active'::public.tenant_secret_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    rotated_at timestamp with time zone,
    disabled_at timestamp with time zone,
    revoked_at timestamp with time zone,
    organization_id uuid,
    CONSTRAINT tenant_secret_refs_kind_nonempty CHECK ((length(btrim(secret_kind)) > 0)),
    CONSTRAINT tenant_secret_refs_name_nonempty CHECK ((length(btrim(secret_name)) > 0)),
    CONSTRAINT tenant_secret_refs_scope_org_consistency CHECK ((((secret_scope = 'tenant'::public.tenant_secret_scope) AND (organization_id IS NULL)) OR ((secret_scope = 'organization_override'::public.tenant_secret_scope) AND (organization_id IS NOT NULL))))
);


--
-- Name: admin_disable_tenant_secret(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_disable_tenant_secret(_secret_ref_id uuid, _revoke boolean DEFAULT false, _reason text DEFAULT NULL::text) RETURNS public.tenant_secret_refs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row public.tenant_secret_refs;
BEGIN
  SELECT * INTO _row FROM public.tenant_secret_refs WHERE id = _secret_ref_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Secret ref % not found', _secret_ref_id; END IF;
  PERFORM public._assert_tenant_admin_or_super(_row.tenant_id, _reason);
  UPDATE public.tenant_secret_refs
     SET status = CASE WHEN _revoke THEN 'revoked'::public.tenant_secret_status ELSE 'disabled'::public.tenant_secret_status END,
         disabled_at = CASE WHEN _revoke THEN disabled_at ELSE now() END,
         revoked_at = CASE WHEN _revoke THEN now() ELSE revoked_at END,
         updated_by = auth.uid(), updated_at = now()
   WHERE id = _secret_ref_id
   RETURNING * INTO _row;
  INSERT INTO public.tenant_secret_access_audit(tenant_id, integration_id, secret_ref_id, actor_user_id, action, reason, function_name, result)
  VALUES (_row.tenant_id, _row.integration_id, _row.id, auth.uid(),
          CASE WHEN _revoke THEN 'revoked'::public.tenant_secret_audit_action ELSE 'disabled'::public.tenant_secret_audit_action END,
          _reason, 'admin_disable_tenant_secret', 'success');
  RETURN _row;
END $$;


--
-- Name: admin_get_knowledge_article_ai_metadata(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_knowledge_article_ai_metadata(_article_id uuid) RETURNS TABLE(article_id uuid, ai_flow text, feature_area text[], route_patterns text[], user_intents text[], audience text[], synonyms text[], freshness_label text, related_feature_flags text[], question_examples text[], answer_rules text[], forbidden_claims text[], created_at timestamp with time zone, updated_at timestamp with time zone, created_by uuid, updated_by uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT
    m.article_id,
    m.ai_flow,
    m.feature_area,
    m.route_patterns,
    m.user_intents,
    m.audience,
    m.synonyms,
    m.freshness_label,
    m.related_feature_flags,
    public._kc_ai_meta_decrypt_array(m.question_examples_protected, m.organization_id),
    public._kc_ai_meta_decrypt_array(m.answer_rules_protected,      m.organization_id),
    public._kc_ai_meta_decrypt_array(m.forbidden_claims_protected,  m.organization_id),
    m.created_at,
    m.updated_at,
    m.created_by,
    m.updated_by
  FROM public.knowledge_article_ai_metadata m
  JOIN public.knowledge_articles a ON a.id = m.article_id
  WHERE m.article_id = _article_id
    AND a.organization_id = v_org;
END;
$$;


--
-- Name: admin_list_btpm_import_batches(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_btpm_import_batches(_organization_id uuid) RETURNS TABLE(id uuid, organization_id uuid, workspace_id uuid, workspace_name text, requested_by uuid, requested_by_email text, requested_by_display_name text, schema_version text, import_type text, source_name text, source_file_name text, payload_hash text, status text, counts_json jsonb, safe_summary_json jsonb, safe_issue_summary_json jsonb, created_at timestamp with time zone, dry_run_at timestamp with time zone, committed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _user uuid := auth.uid();
  _active boolean;
BEGIN
  IF _user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT is_active INTO _active FROM public.profiles WHERE id = _user;
  IF _active IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'inactive_user';
  END IF;
  IF NOT public.is_org_admin(_user, _organization_id) THEN
    RAISE EXCEPTION 'org_admin_required';
  END IF;

  RETURN QUERY
  SELECT
    b.id,
    b.organization_id,
    b.workspace_id,
    w.name AS workspace_name,
    b.requested_by,
    p.email AS requested_by_email,
    COALESCE(NULLIF(TRIM(p.display_name), ''), p.email) AS requested_by_display_name,
    b.schema_version,
    b.import_type,
    b.source_name,
    b.source_file_name,
    b.payload_hash,
    b.status,
    b.counts_json,
    b.safe_summary_json,
    b.safe_issue_summary_json,
    b.created_at,
    b.dry_run_at,
    b.committed_at
  FROM public.btpm_import_batches b
  LEFT JOIN public.workspaces w ON w.id = b.workspace_id
  LEFT JOIN public.profiles p ON p.id = b.requested_by
  WHERE b.organization_id = _organization_id
  ORDER BY b.created_at DESC
  LIMIT 200;
END;
$$;


--
-- Name: admin_list_invitations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_invitations(_organization_id uuid) RETURNS TABLE(id uuid, email text, status text, role text, workspace_name text, invited_at timestamp with time zone, expires_at timestamp with time zone, is_expired boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied: not an organization admin'; END IF;

  RETURN QUERY
  SELECT inv.id, inv.email, inv.status, inv.role::text, w.name AS workspace_name, inv.created_at AS invited_at, inv.expires_at,
    (inv.status = 'pending' AND inv.expires_at <= now()) AS is_expired
  FROM public.invitations inv LEFT JOIN public.workspaces w ON w.id = inv.workspace_id
  WHERE inv.organization_id = _organization_id ORDER BY inv.created_at DESC;
END;
$$;


--
-- Name: admin_list_org_workspaces(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_org_workspaces(_organization_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result json;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  -- Caller must be an org admin of the target organization
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _uid
      AND organization_id = _organization_id
      AND role = 'org_admin'
  ) THEN
    RAISE EXCEPTION 'Insufficient privileges';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT
      w.id,
      public.btpm_decrypt(w.name, _organization_id) AS name,
      w.organization_id,
      w.is_archived
    FROM public.workspaces w
    WHERE w.organization_id = _organization_id
      AND w.is_archived = false
    ORDER BY public.btpm_decrypt(w.name, _organization_id)
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: admin_list_portfolio_items(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_portfolio_items(_organization_id uuid, _include_archived boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
  v_client_id text;
BEGIN
  -- Portfolio-12E.4: browser-internal only. Signed external OAuth is always denied.
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.name_sort), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      pi.id,
      pi.organization_id,
      public.btpm_decrypt(pi.name,        pi.organization_id) AS name,
      public.btpm_decrypt(pi.code,        pi.organization_id) AS code,
      public.btpm_decrypt(pi.description, pi.organization_id) AS description,
      pi.lifecycle_state,
      pi.strategic_priority,
      pi.owner_id,
      pi.is_archived,
      pi.archived_at,
      pi.created_by,
      pi.updated_by,
      pi.created_at,
      pi.updated_at,
      (SELECT count(*) FROM public.projects p WHERE p.portfolio_item_id = pi.id) AS project_count,
      (SELECT count(*) FROM public.projects p WHERE p.portfolio_item_id = pi.id AND p.is_archived = false) AS active_project_count,
      (SELECT count(DISTINCT p.workspace_id) FROM public.projects p WHERE p.portfolio_item_id = pi.id) AS workspace_count,
      (SELECT count(*) FROM public.portfolio_item_team_members tm
         WHERE tm.portfolio_item_id = pi.id AND tm.is_active = true) AS active_team_member_count,
      public.btpm_decrypt(pi.name, pi.organization_id) AS name_sort
    FROM public.portfolio_items pi
    WHERE pi.organization_id = _organization_id
      AND (_include_archived OR pi.is_archived = false)
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: admin_list_portfolio_project_assignment_candidates(uuid, uuid[], text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_portfolio_project_assignment_candidates(_portfolio_item_id uuid, _workspace_ids uuid[] DEFAULT NULL::uuid[], _search text DEFAULT NULL::text, _include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
  _q text;
  v_client_id text;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  _q := NULLIF(btrim(COALESCE(_search, '')), '');

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.project_name), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      p.id AS project_id,
      public.btpm_decrypt(p.name, p.organization_id) AS project_name,
      p.workspace_id,
      w.name AS workspace_name,
      p.program_id,
      (SELECT public.btpm_decrypt(pr.name, p.organization_id)
         FROM public.programs pr WHERE pr.id = p.program_id) AS program_name,
      p.status,
      p.priority,
      p.project_stage,
      p.delivery_model,
      p.start_date,
      p.target_end_date,
      p.is_archived,
      p.portfolio_item_id AS current_portfolio_item_id,
      CASE WHEN p.portfolio_item_id IS NOT NULL
           THEN public.btpm_decrypt(cur.name, p.organization_id) END AS current_portfolio_name,
      CASE WHEN p.portfolio_item_id IS NOT NULL
           THEN public.btpm_decrypt(cur.code, p.organization_id) END AS current_portfolio_code,
      CASE
        WHEN p.portfolio_item_id IS NULL THEN 'unassigned'
        WHEN p.portfolio_item_id = _portfolio_item_id THEN 'assigned_to_current'
        ELSE 'assigned_to_other'
      END AS assignment_state
    FROM public.projects p
    JOIN public.workspaces w ON w.id = p.workspace_id
    LEFT JOIN public.portfolio_items cur ON cur.id = p.portfolio_item_id
    WHERE p.organization_id = _org
      AND (_include_archived OR p.is_archived = false)
      AND (_workspace_ids IS NULL OR array_length(_workspace_ids, 1) IS NULL
           OR p.workspace_id = ANY(_workspace_ids))
      AND (p.portfolio_item_id IS DISTINCT FROM _portfolio_item_id)
      AND (
        _q IS NULL
        OR public.btpm_decrypt(p.name, p.organization_id) ILIKE '%' || _q || '%'
      )
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: admin_list_portfolio_team_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_portfolio_team_members(_portfolio_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
  v_client_id text;
BEGIN
  -- External-OAuth denial (must precede all executable business logic).
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.display_name NULLS LAST, t.email), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      tm.id AS team_member_id,
      tm.portfolio_item_id,
      tm.organization_id,
      tm.user_id,
      tm.role,
      CASE WHEN p.organization_id IS NOT NULL
           THEN public.btpm_decrypt(p.display_name, p.organization_id)
           ELSE p.display_name END AS display_name,
      p.email,
      tm.is_active,
      tm.created_at,
      tm.updated_at
    FROM public.portfolio_item_team_members tm
    JOIN public.profiles p ON p.id = tm.user_id
    WHERE tm.portfolio_item_id = _portfolio_item_id
      AND tm.is_active = true
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: admin_list_project_move_candidates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_project_move_candidates(_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_rows jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized: org admin required';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.project_name), '[]'::jsonb) INTO v_rows
  FROM (
    SELECT
      p.id              AS project_id,
      p.name            AS project_name,
      p.workspace_id    AS source_workspace_id,
      w.name            AS source_workspace_name,
      p.program_id      AS program_id,
      CASE WHEN pg.id IS NULL THEN NULL
           ELSE public.btpm_decrypt(pg.name, pg.organization_id) END AS program_name,
      p.status, p.project_stage, p.delivery_model, p.is_archived
    FROM public.projects p
    JOIN public.workspaces w ON w.id = p.workspace_id
    LEFT JOIN public.programs pg ON pg.id = p.program_id
    WHERE p.organization_id = _organization_id
  ) t;

  RETURN v_rows;
END;
$$;


--
-- Name: admin_list_tenant_integration_secret_metadata(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_tenant_integration_secret_metadata(_integration_id uuid, _reason text DEFAULT NULL::text) RETURNS TABLE(secret_ref_id uuid, integration_id uuid, organization_id uuid, organization_name text, secret_name text, secret_kind text, secret_scope public.tenant_secret_scope, status public.tenant_secret_status, fingerprint text, rotated_at timestamp with time zone, disabled_at timestamp with time zone, revoked_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _integ public.tenant_integrations;
  _is_super boolean;
BEGIN
  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN
    RAISE EXCEPTION 'Integration % not found', _integration_id;
  END IF;

  _is_super := public.is_platform_super_admin(auth.uid());

  IF NOT (public.is_tenant_admin(_integ.tenant_id, auth.uid()) OR _is_super) THEN
    RAISE EXCEPTION 'Not authorized for tenant %', _integ.tenant_id USING ERRCODE = '42501';
  END IF;

  IF _is_super AND (NOT public.is_tenant_admin(_integ.tenant_id, auth.uid()))
     AND (_reason IS NULL OR length(btrim(_reason)) = 0) THEN
    RAISE EXCEPTION 'Platform super admin sensitive metadata access requires a reason'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, integration_id, actor_user_id, action, reason, function_name, result
  ) VALUES (
    _integ.tenant_id, _integ.id, auth.uid(), 'resolved', _reason,
    'admin_list_tenant_integration_secret_metadata', 'success'
  );

  RETURN QUERY
    SELECT r.id, r.integration_id, r.organization_id,
           o.name AS organization_name,
           r.secret_name, r.secret_kind, r.secret_scope, r.status,
           r.secret_fingerprint, r.rotated_at, r.disabled_at, r.revoked_at, r.updated_at
      FROM public.tenant_secret_refs r
      LEFT JOIN public.organizations o ON o.id = r.organization_id
     WHERE r.integration_id = _integ.id
     ORDER BY r.secret_scope::text, r.secret_name, o.name NULLS FIRST;
END $$;


--
-- Name: admin_list_tenant_integrations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_tenant_integrations(_tenant_id uuid) RETURNS TABLE(integration_id uuid, kind public.tenant_integration_kind, name text, status public.tenant_integration_status, is_enabled boolean, config_metadata jsonb, has_config_metadata boolean, config_metadata_key_count integer, last_tested_at timestamp with time zone, last_success_at timestamp with time zone, last_error_at timestamp with time zone, last_error_message text, tenant_secret_count integer, active_secret_count integer, organization_override_count integer, required_secret_count integer, configured_required_secret_count integer, missing_required_secret_count integer, configuration_ready boolean, configuration_issue_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  RETURN QUERY
    WITH req AS (
      SELECT ti.id AS integration_id,
             public._required_tenant_integration_secret_names(ti.kind) AS names,
             public._required_tenant_integration_config_names(ti.kind) AS config_names
      FROM public.tenant_integrations ti
      WHERE ti.tenant_id = _tenant_id
    ),
    req_counts AS (
      SELECT r.integration_id,
             COALESCE(array_length(r.names, 1), 0) AS required_secret_count,
             (
               SELECT COUNT(*)::int
               FROM unnest(r.names) req_name
               WHERE EXISTS (
                 SELECT 1 FROM public.tenant_secret_refs tr
                 WHERE tr.tenant_id = _tenant_id
                   AND tr.integration_id = r.integration_id
                   AND tr.secret_name = req_name
                   AND tr.secret_scope = 'tenant'
                   AND tr.disabled_at IS NULL
                   AND tr.revoked_at IS NULL
                   AND tr.status = 'active'
               )
             ) AS configured_required_secret_count,
             r.config_names AS required_config_names
      FROM req r
    )
    SELECT ti.id,
           ti.kind,
           ti.name,
           ti.status,
           ti.is_enabled,
           '{}'::jsonb AS config_metadata,
           (jsonb_typeof(COALESCE(ti.config_metadata, '{}'::jsonb)) = 'object'
             AND (SELECT COUNT(*) FROM jsonb_object_keys(COALESCE(ti.config_metadata, '{}'::jsonb))) > 0) AS has_config_metadata,
           CASE WHEN jsonb_typeof(COALESCE(ti.config_metadata, '{}'::jsonb)) = 'object'
                THEN (SELECT COUNT(*)::int FROM jsonb_object_keys(COALESCE(ti.config_metadata, '{}'::jsonb)))
                ELSE 0 END AS config_metadata_key_count,
           ti.last_tested_at, ti.last_success_at, ti.last_error_at, ti.last_error_message,
           (SELECT COUNT(*)::int FROM public.tenant_secret_refs r2 WHERE r2.integration_id = ti.id)::int,
           (SELECT COUNT(*)::int FROM public.tenant_secret_refs r2 WHERE r2.integration_id = ti.id AND r2.status = 'active')::int,
           (SELECT COUNT(*)::int FROM public.organization_secret_overrides o WHERE o.integration_id = ti.id)::int,
           rc.required_secret_count,
           rc.configured_required_secret_count,
           GREATEST(rc.required_secret_count - rc.configured_required_secret_count, 0) AS missing_required_secret_count,
           (
             COALESCE(array_length(rc.required_config_names, 1), 0) = 0
             OR NOT EXISTS (
               SELECT 1 FROM unnest(rc.required_config_names) cfg
               WHERE NOT (
                 jsonb_typeof(COALESCE(ti.config_metadata, '{}'::jsonb)) = 'object'
                 AND COALESCE(ti.config_metadata, '{}'::jsonb) ? cfg
                 AND jsonb_typeof(COALESCE(ti.config_metadata, '{}'::jsonb) -> cfg) = 'string'
                 AND btrim(COALESCE(ti.config_metadata, '{}'::jsonb) ->> cfg) <> ''
               )
             )
           ) AS configuration_ready,
           (
             SELECT CASE WHEN COUNT(*) = 0 THEN NULL
                         ELSE 'missing:' || string_agg(cfg, ',' ORDER BY cfg) END
             FROM unnest(rc.required_config_names) cfg
             WHERE NOT (
               jsonb_typeof(COALESCE(ti.config_metadata, '{}'::jsonb)) = 'object'
               AND COALESCE(ti.config_metadata, '{}'::jsonb) ? cfg
               AND jsonb_typeof(COALESCE(ti.config_metadata, '{}'::jsonb) -> cfg) = 'string'
               AND btrim(COALESCE(ti.config_metadata, '{}'::jsonb) ->> cfg) <> ''
             )
           ) AS configuration_issue_code
      FROM public.tenant_integrations ti
      JOIN req_counts rc ON rc.integration_id = ti.id
     WHERE ti.tenant_id = _tenant_id
     ORDER BY ti.kind::text, ti.name;
END $$;


--
-- Name: admin_move_project_workspace(uuid, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_move_project_workspace(_organization_id uuid, _project_id uuid, _target_workspace_id uuid, _target_program_id uuid DEFAULT NULL::uuid, _confirm_program_clear boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_src_ws public.workspaces%ROWTYPE;
  v_tgt_ws public.workspaces%ROWTYPE;
  v_tgt_pg public.programs%ROWTYPE;
  v_phases uuid[];
  v_tasks uuid[];
  v_kpis uuid[];
  v_prev_program uuid;
  v_program_clear boolean;
  v_access_removed int := 0;
  v_updated jsonb := '{}'::jsonb;
  v_dup boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized: org admin required';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = _project_id FOR UPDATE;
  IF NOT FOUND OR v_project.organization_id <> _organization_id THEN
    RAISE EXCEPTION 'Project not found in organization';
  END IF;
  IF v_project.is_archived THEN RAISE EXCEPTION 'Project is archived'; END IF;

  SELECT * INTO v_src_ws FROM public.workspaces WHERE id = v_project.workspace_id;
  SELECT * INTO v_tgt_ws FROM public.workspaces WHERE id = _target_workspace_id;
  IF NOT FOUND OR v_tgt_ws.organization_id <> _organization_id THEN
    RAISE EXCEPTION 'Target workspace not in organization';
  END IF;
  IF v_src_ws.id = v_tgt_ws.id THEN RAISE EXCEPTION 'Source and target workspaces are the same'; END IF;
  IF v_src_ws.is_archived OR v_src_ws.is_active = false THEN RAISE EXCEPTION 'Source workspace inactive'; END IF;
  IF v_tgt_ws.is_archived OR v_tgt_ws.is_active = false THEN RAISE EXCEPTION 'Target workspace inactive'; END IF;

  IF _target_program_id IS NOT NULL THEN
    SELECT * INTO v_tgt_pg FROM public.programs WHERE id = _target_program_id;
    IF NOT FOUND
       OR v_tgt_pg.organization_id <> _organization_id
       OR v_tgt_pg.workspace_id <> _target_workspace_id
       OR v_tgt_pg.is_archived THEN
      RAISE EXCEPTION 'Invalid target program';
    END IF;
  END IF;

  v_prev_program := v_project.program_id;
  v_program_clear := (v_prev_program IS NOT NULL AND _target_program_id IS NULL);
  IF v_program_clear AND NOT _confirm_program_clear THEN
    RAISE EXCEPTION 'Program clear not confirmed';
  END IF;

  -- Duplicate name guard
  SELECT EXISTS (
    SELECT 1 FROM public.projects
    WHERE workspace_id = _target_workspace_id
      AND id <> _project_id
      AND is_archived = false
      AND lower(name) = lower(v_project.name)
  ) INTO v_dup;
  IF v_dup THEN RAISE EXCEPTION 'Duplicate project name in target workspace'; END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_phases FROM public.phases WHERE project_id = _project_id;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_tasks FROM public.tasks WHERE project_id = _project_id;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_kpis FROM public.kpi_definitions
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));

  -- 1. Update project itself
  UPDATE public.projects
     SET workspace_id = _target_workspace_id,
         program_id   = _target_program_id,
         updated_at   = now()
   WHERE id = _project_id;

  -- 2. Move Set A (direct project-scoped tables)
  UPDATE public.phases                         SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.tasks                          SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.backlog_items                  SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.sprints                        SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.board_workflow_states          SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.project_team_members           SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.project_stakeholders           SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.generated_operational_documents SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_cadences            SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_records             SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_record_decisions    SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.governance_record_links        SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_snapshots                  SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_snapshot_capture_run_items SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_app_mappings               SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_app_submission_outbox      SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.kpi_app_scheduler_run_items    SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.powerbi_data_scope_rules       SET workspace_id = _target_workspace_id WHERE project_id=_project_id;
  UPDATE public.sharepoint_project_bindings    SET workspace_id = _target_workspace_id WHERE project_id=_project_id;

  -- 3. Move Set B (polymorphic target_type/target_id)
  UPDATE public.comments                 SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.execution_updates        SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.activity_events          SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.blockers                 SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.risks                    SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.dependencies             SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.kpi_definitions          SET workspace_id = _target_workspace_id
    WHERE id = ANY(v_kpis);
  UPDATE public.raci_assignments         SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.notification_outbox      SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));
  UPDATE public.email_payload_snapshots  SET workspace_id = _target_workspace_id
    WHERE (target_type='project' AND target_id=_project_id)
       OR (target_type='phase'   AND target_id = ANY(v_phases))
       OR (target_type='task'    AND target_id = ANY(v_tasks));

  -- 4. Derived
  UPDATE public.kpi_updates      SET workspace_id = _target_workspace_id WHERE kpi_definition_id = ANY(v_kpis);
  UPDATE public.task_assignments SET workspace_id = _target_workspace_id WHERE task_id = ANY(v_tasks);
  UPDATE public.entity_object_links SET workspace_id = _target_workspace_id
    WHERE (owner_type IN ('project','phase','task')
           AND (owner_id=_project_id OR owner_id = ANY(v_phases) OR owner_id = ANY(v_tasks)))
       OR (referenced_type IN ('project','phase','task')
           AND (referenced_id=_project_id OR referenced_id = ANY(v_phases) OR referenced_id = ANY(v_tasks)));
  UPDATE public.entity_user_links SET workspace_id = _target_workspace_id
    WHERE owner_type IN ('project','phase','task')
      AND (owner_id=_project_id OR owner_id = ANY(v_phases) OR owner_id = ANY(v_tasks));

  -- 5. Soft-remove stale direct project memberships
  WITH removed AS (
    UPDATE public.project_memberships
       SET removed_at = now(), updated_at = now()
     WHERE project_id = _project_id
       AND removed_at IS NULL
       AND user_id NOT IN (SELECT user_id FROM public.workspace_memberships WHERE workspace_id = _target_workspace_id)
     RETURNING 1
  ) SELECT count(*) INTO v_access_removed FROM removed;

  v_updated := jsonb_build_object(
    'phases', array_length(v_phases,1),
    'tasks',  array_length(v_tasks,1),
    'kpi_definitions', array_length(v_kpis,1)
  );

  -- 6. Activity event for the move (IDs/counts only — no decrypted names)
  INSERT INTO public.activity_events (organization_id, workspace_id, event_type, target_type, target_id, actor_id, metadata)
  VALUES (_organization_id, _target_workspace_id, 'project_workspace_moved', 'project', _project_id, v_uid,
    jsonb_build_object(
      'source_workspace_id', v_src_ws.id,
      'target_workspace_id', v_tgt_ws.id,
      'previous_program_id', v_prev_program,
      'new_program_id', _target_program_id,
      'program_cleared', v_program_clear,
      'access_removed_count', v_access_removed,
      'updated_counts', v_updated
    )::text
  );

  RETURN jsonb_build_object(
    'moved_project_id', _project_id,
    'source_workspace_id', v_src_ws.id,
    'target_workspace_id', v_tgt_ws.id,
    'target_route', '/workspace/' || _target_workspace_id::text || '/project/' || _project_id::text,
    'previous_program_id', v_prev_program,
    'new_program_id', _target_program_id,
    'program_cleared', v_program_clear,
    'updated_counts', v_updated,
    'access_removed_count', v_access_removed
  );
END;
$$;


--
-- Name: admin_preview_project_workspace_move(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_preview_project_workspace_move(_organization_id uuid, _project_id uuid, _target_workspace_id uuid, _target_program_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_project public.projects%ROWTYPE;
  v_src_ws public.workspaces%ROWTYPE;
  v_tgt_ws public.workspaces%ROWTYPE;
  v_tgt_pg public.programs%ROWTYPE;
  v_blocking text[] := ARRAY[]::text[];
  v_dup boolean := false;
  v_counts jsonb := '{}'::jsonb;
  v_access_removed int := 0;
  v_cross_dep int := 0;
  v_program_clear boolean := false;
  v_phases uuid[];
  v_tasks uuid[];
  v_kpis uuid[];
  v_src_program_name text;
  v_tgt_program_name text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Not authorized: org admin required';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = _project_id;
  IF NOT FOUND OR v_project.organization_id <> _organization_id THEN
    RAISE EXCEPTION 'Project not found in organization';
  END IF;

  SELECT * INTO v_src_ws FROM public.workspaces WHERE id = v_project.workspace_id;
  SELECT * INTO v_tgt_ws FROM public.workspaces WHERE id = _target_workspace_id;
  IF NOT FOUND OR v_tgt_ws.organization_id <> _organization_id THEN
    RAISE EXCEPTION 'Target workspace not found in organization';
  END IF;

  IF v_project.is_archived THEN v_blocking := v_blocking || 'project_is_archived'; END IF;
  IF v_src_ws.id = v_tgt_ws.id THEN v_blocking := v_blocking || 'same_workspace'; END IF;
  IF v_src_ws.is_archived OR v_src_ws.is_active = false THEN v_blocking := v_blocking || 'source_workspace_inactive'; END IF;
  IF v_tgt_ws.is_archived OR v_tgt_ws.is_active = false THEN v_blocking := v_blocking || 'target_workspace_inactive'; END IF;

  IF _target_program_id IS NOT NULL THEN
    SELECT * INTO v_tgt_pg FROM public.programs WHERE id = _target_program_id;
    IF NOT FOUND
       OR v_tgt_pg.organization_id <> _organization_id
       OR v_tgt_pg.workspace_id <> _target_workspace_id
       OR v_tgt_pg.is_archived THEN
      v_blocking := v_blocking || 'invalid_target_program';
    ELSE
      v_tgt_program_name := public.btpm_decrypt(v_tgt_pg.name, v_tgt_pg.organization_id);
    END IF;
  END IF;

  v_program_clear := (v_project.program_id IS NOT NULL AND _target_program_id IS NULL);

  IF v_project.program_id IS NOT NULL THEN
    SELECT public.btpm_decrypt(name, organization_id) INTO v_src_program_name
    FROM public.programs WHERE id = v_project.program_id;
  END IF;

  -- Duplicate name in target workspace (case-insensitive, exclude this project, exclude archived)
  SELECT EXISTS (
    SELECT 1 FROM public.projects
    WHERE workspace_id = _target_workspace_id
      AND id <> _project_id
      AND is_archived = false
      AND lower(name) = lower(v_project.name)
  ) INTO v_dup;
  IF v_dup THEN v_blocking := v_blocking || 'duplicate_project_name_in_target'; END IF;

  -- Discovery sets
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_phases FROM public.phases WHERE project_id = _project_id;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_tasks FROM public.tasks WHERE project_id = _project_id;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_kpis FROM public.kpi_definitions
    WHERE (target_type = 'project' AND target_id = _project_id)
       OR (target_type = 'phase'   AND target_id = ANY(v_phases))
       OR (target_type = 'task'    AND target_id = ANY(v_tasks));

  -- Counts (Move Set A direct project-scoped)
  v_counts := jsonb_build_object(
    'phases',                          array_length(v_phases,1),
    'tasks',                           array_length(v_tasks,1),
    'backlog_items',                   (SELECT count(*) FROM public.backlog_items WHERE project_id=_project_id),
    'sprints',                         (SELECT count(*) FROM public.sprints WHERE project_id=_project_id),
    'board_workflow_states',           (SELECT count(*) FROM public.board_workflow_states WHERE project_id=_project_id),
    'project_team_members',            (SELECT count(*) FROM public.project_team_members WHERE project_id=_project_id),
    'project_stakeholders',            (SELECT count(*) FROM public.project_stakeholders WHERE project_id=_project_id),
    'generated_operational_documents', (SELECT count(*) FROM public.generated_operational_documents WHERE project_id=_project_id),
    'governance_cadences',             (SELECT count(*) FROM public.governance_cadences WHERE project_id=_project_id),
    'governance_records',              (SELECT count(*) FROM public.governance_records WHERE project_id=_project_id),
    'governance_record_decisions',     (SELECT count(*) FROM public.governance_record_decisions WHERE project_id=_project_id),
    'governance_record_links',         (SELECT count(*) FROM public.governance_record_links WHERE project_id=_project_id),
    'kpi_snapshots',                   (SELECT count(*) FROM public.kpi_snapshots WHERE project_id=_project_id),
    'kpi_snapshot_capture_run_items',  (SELECT count(*) FROM public.kpi_snapshot_capture_run_items WHERE project_id=_project_id),
    'kpi_app_mappings',                (SELECT count(*) FROM public.kpi_app_mappings WHERE project_id=_project_id),
    'kpi_app_submission_outbox',       (SELECT count(*) FROM public.kpi_app_submission_outbox WHERE project_id=_project_id),
    'kpi_app_scheduler_run_items',     (SELECT count(*) FROM public.kpi_app_scheduler_run_items WHERE project_id=_project_id),
    'powerbi_data_scope_rules',        (SELECT count(*) FROM public.powerbi_data_scope_rules WHERE project_id=_project_id),
    'sharepoint_project_bindings',     (SELECT count(*) FROM public.sharepoint_project_bindings WHERE project_id=_project_id),
    'kpi_definitions',                 array_length(v_kpis,1),
    'kpi_updates',                     (SELECT count(*) FROM public.kpi_updates WHERE kpi_definition_id = ANY(v_kpis)),
    'task_assignments',                (SELECT count(*) FROM public.task_assignments WHERE task_id = ANY(v_tasks)),
    'comments',                        (SELECT count(*) FROM public.comments
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'execution_updates',               (SELECT count(*) FROM public.execution_updates
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'activity_events_history',         (SELECT count(*) FROM public.activity_events
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'blockers',                        (SELECT count(*) FROM public.blockers
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'risks',                           (SELECT count(*) FROM public.risks
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'dependencies',                    (SELECT count(*) FROM public.dependencies
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'raci_assignments',                (SELECT count(*) FROM public.raci_assignments
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'notification_outbox',             (SELECT count(*) FROM public.notification_outbox
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'email_payload_snapshots',         (SELECT count(*) FROM public.email_payload_snapshots
                                          WHERE (target_type='project' AND target_id=_project_id)
                                             OR (target_type='phase' AND target_id = ANY(v_phases))
                                             OR (target_type='task'  AND target_id = ANY(v_tasks))),
    'entity_object_links',             (SELECT count(*) FROM public.entity_object_links
                                          WHERE (owner_type IN ('project','phase','task') AND (owner_id=_project_id OR owner_id = ANY(v_phases) OR owner_id = ANY(v_tasks)))
                                             OR (referenced_type IN ('project','phase','task') AND (referenced_id=_project_id OR referenced_id = ANY(v_phases) OR referenced_id = ANY(v_tasks)))),
    'entity_user_links',               (SELECT count(*) FROM public.entity_user_links
                                          WHERE owner_type IN ('project','phase','task')
                                            AND (owner_id=_project_id OR owner_id = ANY(v_phases) OR owner_id = ANY(v_tasks)))
  );

  -- Access removal preview
  SELECT count(*) INTO v_access_removed
  FROM public.project_memberships pm
  WHERE pm.project_id = _project_id
    AND pm.removed_at IS NULL
    AND pm.user_id NOT IN (SELECT user_id FROM public.workspace_memberships WHERE workspace_id = _target_workspace_id);

  -- Cross-workspace dependency warning: dependencies attached to this project whose counterparty resolves to a different workspace
  SELECT count(*) INTO v_cross_dep
  FROM public.dependencies d
  WHERE d.target_type='project' AND d.target_id = _project_id;
  -- (Best-effort signal: count of project-level dependency rows; cross-workspace nature is reported via UI for admin review.)

  RETURN jsonb_build_object(
    'project_id', _project_id,
    'project_name', v_project.name,
    'source_workspace_id', v_src_ws.id,
    'source_workspace_name', v_src_ws.name,
    'target_workspace_id', v_tgt_ws.id,
    'target_workspace_name', v_tgt_ws.name,
    'current_program_id', v_project.program_id,
    'current_program_name', v_src_program_name,
    'target_program_id', _target_program_id,
    'target_program_name', v_tgt_program_name,
    'program_will_be_cleared', v_program_clear,
    'duplicate_name_in_target', v_dup,
    'cross_workspace_dependency_count', v_cross_dep,
    'access_removed_count', v_access_removed,
    'counts', v_counts,
    'blocking_issues', to_jsonb(v_blocking)
  );
END;
$$;


--
-- Name: admin_reactivate_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reactivate_user(_organization_id uuid, _target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN RAISE EXCEPTION 'User not found'; END IF;
  UPDATE public.profiles SET is_active = true, updated_at = now() WHERE id = _target_user_id AND organization_id = _organization_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'user_reactivated', 'user', _target_user_id, '{}'::jsonb, NULL);
END;
$$;


--
-- Name: admin_remove_portfolio_team_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_remove_portfolio_team_member(_team_member_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _row public.portfolio_item_team_members%ROWTYPE;
  v_client_id text;
BEGIN
  -- External-OAuth denial (must precede all executable business logic).
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO _row FROM public.portfolio_item_team_members WHERE id = _team_member_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Team member not found'; END IF;
  IF NOT public.is_org_admin(_uid, _row.organization_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  IF _row.is_active THEN
    UPDATE public.portfolio_item_team_members
       SET is_active = false, updated_by = _uid
     WHERE id = _team_member_id;

    PERFORM public.log_activity_event(
      _row.organization_id, _uid, 'portfolio_team_member_removed', 'portfolio', _row.portfolio_item_id,
      jsonb_build_object('user_id', _row.user_id, 'role', _row.role),
      NULL::uuid
    );
  END IF;
END;
$$;


--
-- Name: admin_remove_projects_from_portfolio(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_remove_projects_from_portfolio(_portfolio_item_id uuid, _project_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _removed int := 0;
  _skipped int := 0;
  _affected uuid[] := ARRAY[]::uuid[];
  _rec record;
  v_client_id text;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF _project_ids IS NULL OR array_length(_project_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one project must be selected';
  END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;
  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  FOR _rec IN
    SELECT p.id, p.organization_id, p.workspace_id, p.portfolio_item_id AS current_pi
      FROM public.projects p
     WHERE p.id = ANY(_project_ids)
  LOOP
    IF _rec.organization_id <> _org THEN
      RAISE EXCEPTION 'Project % belongs to a different organization', _rec.id;
    END IF;

    IF _rec.current_pi IS DISTINCT FROM _portfolio_item_id THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    UPDATE public.projects
       SET portfolio_item_id = NULL,
           updated_at = now()
     WHERE id = _rec.id;

    _removed := _removed + 1;
    _affected := _affected || _rec.id;

    PERFORM public.log_activity_event(
      _org, _uid, 'project_portfolio_changed', 'project', _rec.id,
      jsonb_build_object(
        'old_portfolio_item_id', _portfolio_item_id,
        'new_portfolio_item_id', NULL,
        'source', 'admin_portfolio_manage'
      ),
      _rec.workspace_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'removed_count', _removed,
    'skipped_count', _skipped,
    'affected_project_ids', to_jsonb(_affected)
  );
END;
$$;


--
-- Name: admin_remove_workspace_access(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_remove_workspace_access(_organization_id uuid, _target_user_id uuid, _workspace_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _ws_name text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT name INTO _ws_name FROM public.workspaces WHERE id = _workspace_id;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'workspace_access_removed', 'user', _target_user_id, jsonb_build_object('workspace_id', _workspace_id, 'workspace_name', _ws_name), _workspace_id);
  DELETE FROM public.user_roles WHERE user_id = _target_user_id AND workspace_id = _workspace_id AND organization_id = _organization_id;
  DELETE FROM public.workspace_memberships WHERE user_id = _target_user_id AND workspace_id = _workspace_id;
END;
$$;


--
-- Name: admin_resend_invitation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_resend_invitation(_organization_id uuid, _invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _email text; _new_token uuid; _token_hash text;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT email INTO _email FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pending invitation not found'; END IF;
  _new_token := gen_random_uuid(); _token_hash := encode(digest(_new_token::text, 'sha256'), 'hex');
  UPDATE public.invitations SET expires_at = now() + interval '7 days', updated_at = now(), token = _token_hash WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'invitation_resent', 'invitation', _invitation_id, jsonb_build_object('email', _email));
END;
$$;


--
-- Name: admin_revoke_invitation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revoke_invitation(_organization_id uuid, _invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _email text; _ws_id uuid;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT email, workspace_id INTO _email, _ws_id FROM public.invitations WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  UPDATE public.invitations SET status = 'revoked', updated_at = now() WHERE id = _invitation_id AND organization_id = _organization_id AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pending invitation not found'; END IF;
  PERFORM public.log_activity_event(_organization_id, auth.uid(), 'invitation_revoked', 'invitation', _invitation_id, jsonb_build_object('email', _email), _ws_id);
END;
$$;


--
-- Name: admin_set_org_admin(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_org_admin(_organization_id uuid, _target_user_id uuid, _is_admin boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _remaining int;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _target_user_id AND organization_id = _organization_id) THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  IF _is_admin THEN
    PERFORM public._ensure_membership_layers(_target_user_id, _organization_id, auth.uid());
    UPDATE public.organization_memberships
       SET role = 'org_admin'::public.organization_role,
           status = 'active'::public.membership_status,
           updated_by = auth.uid(), updated_at = now()
     WHERE organization_id = _organization_id AND user_id = _target_user_id
       AND role <> 'org_admin';
    INSERT INTO public.user_roles (user_id, role, organization_id, workspace_id)
      VALUES (_target_user_id, 'org_admin', _organization_id, NULL) ON CONFLICT DO NOTHING;
    PERFORM public.log_activity_event(_organization_id, auth.uid(), 'org_admin_granted',
      'user', _target_user_id, '{}'::jsonb, NULL);
  ELSE
    IF _target_user_id = auth.uid() THEN RAISE EXCEPTION 'Cannot remove your own org admin role'; END IF;

    -- Last-admin safeguard (preserves current behavior).
    SELECT COUNT(*) INTO _remaining
      FROM public.organization_memberships
     WHERE organization_id = _organization_id AND status = 'active'
       AND role = 'org_admin' AND user_id <> _target_user_id;
    IF _remaining < 1 AND EXISTS (
      SELECT 1 FROM public.organization_memberships
       WHERE organization_id = _organization_id AND user_id = _target_user_id
         AND status = 'active' AND role = 'org_admin'
    ) THEN
      RAISE EXCEPTION 'Cannot remove the last Org Admin';
    END IF;

    UPDATE public.organization_memberships
       SET role = 'org_member'::public.organization_role,
           updated_by = auth.uid(), updated_at = now()
     WHERE organization_id = _organization_id AND user_id = _target_user_id
       AND role = 'org_admin';
    DELETE FROM public.user_roles
     WHERE user_id = _target_user_id AND role = 'org_admin'
       AND organization_id = _organization_id AND workspace_id IS NULL;
    PERFORM public.log_activity_event(_organization_id, auth.uid(), 'org_admin_revoked',
      'user', _target_user_id, '{}'::jsonb, NULL);
  END IF;
END;
$$;


--
-- Name: admin_store_tenant_secret(uuid, uuid, text, text, text, text, public.tenant_secret_scope, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_store_tenant_secret(_tenant_id uuid, _integration_id uuid, _secret_name text, _secret_kind text, _secret_value text, _fingerprint text DEFAULT NULL::text, _scope public.tenant_secret_scope DEFAULT 'tenant'::public.tenant_secret_scope, _reason text DEFAULT NULL::text, _organization_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_secret_refs;
  _integration_tenant uuid;
  _org_tenant uuid;
  _vault_name text;
  _vault_id uuid;
  _existing_ref_id uuid;
  _existing_vault_id uuid;
  _was_rotation boolean := false;
BEGIN
  PERFORM public._assert_tenant_admin_or_super(_tenant_id, _reason);

  SELECT tenant_id INTO _integration_tenant
    FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integration_tenant IS NULL OR _integration_tenant <> _tenant_id THEN
    RAISE EXCEPTION 'Integration % does not belong to tenant %', _integration_id, _tenant_id;
  END IF;

  IF _secret_value IS NULL OR length(_secret_value) = 0 THEN
    RAISE EXCEPTION 'Secret value must not be empty';
  END IF;

  IF _scope = 'tenant' THEN
    IF _organization_id IS NOT NULL THEN
      RAISE EXCEPTION 'organization_id must be NULL for tenant-scope secrets';
    END IF;
  ELSIF _scope = 'organization_override' THEN
    IF _organization_id IS NULL THEN
      RAISE EXCEPTION 'organization_id is required for organization_override secrets';
    END IF;
    SELECT tenant_id INTO _org_tenant
      FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _tenant_id;
    END IF;
  END IF;

  -- Locate existing row via scope-aware natural key.
  IF _scope = 'tenant' THEN
    SELECT id, vault_secret_id INTO _existing_ref_id, _existing_vault_id
      FROM public.tenant_secret_refs
     WHERE tenant_id = _tenant_id
       AND integration_id = _integration_id
       AND secret_name = _secret_name
       AND secret_scope = 'tenant'
     LIMIT 1;
  ELSE
    SELECT id, vault_secret_id INTO _existing_ref_id, _existing_vault_id
      FROM public.tenant_secret_refs
     WHERE tenant_id = _tenant_id
       AND integration_id = _integration_id
       AND secret_name = _secret_name
       AND secret_scope = 'organization_override'
       AND organization_id = _organization_id
     LIMIT 1;
  END IF;

  _vault_name := format(
    'btpm_ti_%s_%s_%s_%s_%s',
    _tenant_id::text, _integration_id::text, _secret_name, _scope::text,
    COALESCE(_organization_id::text, 'tenant')
  );

  IF _existing_vault_id IS NOT NULL THEN
    PERFORM vault.update_secret(_existing_vault_id, _secret_value);
    _vault_id := _existing_vault_id;
    _was_rotation := true;
  ELSE
    _vault_id := vault.create_secret(_secret_value, _vault_name, 'BTPM tenant integration secret');
  END IF;

  IF _existing_ref_id IS NOT NULL THEN
    UPDATE public.tenant_secret_refs
       SET vault_secret_id = _vault_id,
           secret_fingerprint = COALESCE(_fingerprint, secret_fingerprint),
           secret_kind = _secret_kind,
           status = 'active',
           rotated_at = CASE WHEN _was_rotation THEN now() ELSE rotated_at END,
           disabled_at = NULL,
           revoked_at = NULL,
           updated_by = auth.uid(),
           updated_at = now()
     WHERE id = _existing_ref_id
     RETURNING * INTO _row;
  ELSE
    INSERT INTO public.tenant_secret_refs (
      tenant_id, organization_id, integration_id, secret_name, secret_kind,
      secret_scope, vault_secret_id, secret_fingerprint, status,
      created_by, updated_by
    ) VALUES (
      _tenant_id, _organization_id, _integration_id, _secret_name, _secret_kind,
      _scope, _vault_id, _fingerprint, 'active',
      auth.uid(), auth.uid()
    ) RETURNING * INTO _row;
  END IF;

  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, organization_id, integration_id, secret_ref_id, actor_user_id,
    action, reason, function_name, result
  ) VALUES (
    _tenant_id, _organization_id, _integration_id, _row.id, auth.uid(),
    CASE WHEN _was_rotation THEN 'rotated'::public.tenant_secret_audit_action
         ELSE 'created'::public.tenant_secret_audit_action END,
    _reason, 'admin_store_tenant_secret', 'success'
  );

  RETURN jsonb_build_object(
    'integration_id', _row.integration_id,
    'organization_id', _row.organization_id,
    'secret_ref_id', _row.id,
    'secret_name', _row.secret_name,
    'secret_kind', _row.secret_kind,
    'secret_scope', _row.secret_scope,
    'status', _row.status,
    'rotated_at', _row.rotated_at,
    'fingerprint', _row.secret_fingerprint
  );
END $$;


--
-- Name: admin_test_tenant_integration_metadata(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_test_tenant_integration_metadata(_integration_id uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _integ public.tenant_integrations;
  _secret_count int;
  _new_status public.tenant_integration_status;
BEGIN
  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN RAISE EXCEPTION 'Integration % not found', _integration_id; END IF;
  PERFORM public._assert_tenant_admin_or_super(_integ.tenant_id, _reason);
  SELECT COUNT(*) INTO _secret_count FROM public.tenant_secret_refs
   WHERE integration_id = _integ.id AND status = 'active';
  _new_status := CASE
    WHEN _secret_count = 0 THEN 'not_configured'::public.tenant_integration_status
    WHEN _integ.is_enabled THEN 'active'::public.tenant_integration_status
    ELSE 'disabled'::public.tenant_integration_status
  END;
  UPDATE public.tenant_integrations
     SET last_tested_at = now(), status = _new_status,
         updated_by = auth.uid(), updated_at = now()
   WHERE id = _integration_id;
  INSERT INTO public.tenant_secret_access_audit(tenant_id, integration_id, actor_user_id, action, reason, function_name, result)
  VALUES (_integ.tenant_id, _integ.id, auth.uid(), 'tested', _reason, 'admin_test_tenant_integration_metadata', 'success');
  RETURN jsonb_build_object('integration_id', _integ.id, 'status', _new_status,
                            'active_secret_count', _secret_count, 'tested_at', now());
END $$;


--
-- Name: admin_update_portfolio_item(uuid, text, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_portfolio_item(_portfolio_item_id uuid, _name text, _code text DEFAULT NULL::text, _description text DEFAULT NULL::text, _lifecycle_state text DEFAULT 'opportunity_candidate'::text, _owner_id uuid DEFAULT NULL::uuid, _strategic_priority text DEFAULT 'medium'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  -- API-Q Portfolio-12B.2B: server-derived external OAuth identity. Never caller-provided.
  v_client_id text;
  v_trusted boolean := false;
  v_trusted_channel text;
  _uid uuid := auth.uid();
  _org uuid;
  _name_trim text;
BEGIN
  -- 0. Source-awareness + exact-capability containment.
  --    Runs before active-user evaluation, Portfolio lookup (and therefore before
  --    any Portfolio-existence disclosure), Organization authority evaluation,
  --    narrative validation, owner lookup, UPDATE, encryption triggers and
  --    activity logging.
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    BEGIN
      v_trusted := api_e_private.assert_trusted_context();
    EXCEPTION WHEN OTHERS THEN
      v_trusted := false;
    END;

    v_trusted_channel := nullif(btrim(coalesce(current_setting('api_e.source_channel', true),'')),'');

    IF v_trusted IS NOT TRUE
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.api_version', true),'')),''), '') <> 'v1'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_kind', true),'')),''), '') <> 'command'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_key', true),'')),''), '') <> 'portfolios:update'
       OR v_trusted_channel IS NULL
       OR v_trusted_channel NOT IN ('external_api','mcp')
    THEN
      -- Fail closed: bounded generic authorization error, no business detail.
      RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;

  IF NOT public.is_org_admin(_uid, _org) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  _name_trim := btrim(COALESCE(_name, ''));
  IF _name_trim = '' THEN RAISE EXCEPTION 'Name is required'; END IF;
  IF char_length(_name_trim) > 200 THEN RAISE EXCEPTION 'Name exceeds 200 characters'; END IF;
  IF _code IS NOT NULL AND char_length(_code) > 80 THEN RAISE EXCEPTION 'Code exceeds 80 characters'; END IF;
  IF _description IS NOT NULL AND char_length(_description) > 4000 THEN RAISE EXCEPTION 'Description exceeds 4000 characters'; END IF;
  IF _lifecycle_state NOT IN (
    'opportunity_candidate','business_case_approved','contracted','development',
    'submission_approval','launch_preparation','launched_commercial',
    'lcm_optimization','on_hold','discontinuation','retired'
  ) THEN RAISE EXCEPTION 'Invalid lifecycle_state'; END IF;
  IF _strategic_priority NOT IN ('critical','high','medium','low','watchlist') THEN
    RAISE EXCEPTION 'Invalid strategic_priority';
  END IF;
  -- API-Q Portfolio-12C.1: authoritative Organization membership, not the legacy
  -- profiles.organization_id home pointer.
  IF _owner_id IS NOT NULL THEN
    IF public.is_user_org_member(_owner_id, _org) IS NOT TRUE THEN
      RAISE EXCEPTION 'Owner must belong to the same organization';
    END IF;
  END IF;

  UPDATE public.portfolio_items
     SET name = _name_trim,
         code = _code,
         description = _description,
         lifecycle_state = _lifecycle_state,
         strategic_priority = _strategic_priority,
         owner_id = _owner_id,
         updated_by = _uid
   WHERE id = _portfolio_item_id;

  PERFORM public.log_activity_event(
    _org, _uid, 'portfolio_updated', 'portfolio', _portfolio_item_id, NULL::jsonb, NULL::uuid
  );
END;
$$;


--
-- Name: admin_update_portfolio_team_member_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_portfolio_team_member_role(_team_member_id uuid, _role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _row public.portfolio_item_team_members%ROWTYPE;
  _conflict_id uuid;
  v_client_id text;
BEGIN
  -- External-OAuth denial (must precede all executable business logic).
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO _row FROM public.portfolio_item_team_members WHERE id = _team_member_id;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Team member not found'; END IF;
  IF NOT public.is_org_admin(_uid, _row.organization_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;

  IF _role NOT IN (
    'product_manager','commercial_lead','finance_partner','supply_lead',
    'regulatory_lead','quality_lead','tech_services_lead','launch_lead',
    'bd_lead','srm_lead','other'
  ) THEN RAISE EXCEPTION 'Invalid role'; END IF;

  IF _row.role = _role THEN RETURN; END IF;

  -- Prevent duplicate active row conflict
  SELECT id INTO _conflict_id
    FROM public.portfolio_item_team_members
   WHERE portfolio_item_id = _row.portfolio_item_id
     AND user_id = _row.user_id
     AND role = _role
     AND is_active = true
     AND id <> _team_member_id
   LIMIT 1;
  IF _conflict_id IS NOT NULL THEN
    RAISE EXCEPTION 'This user already has that role on this Portfolio';
  END IF;

  UPDATE public.portfolio_item_team_members
     SET role = _role, updated_by = _uid
   WHERE id = _team_member_id;

  PERFORM public.log_activity_event(
    _row.organization_id, _uid, 'portfolio_team_member_role_changed', 'portfolio', _row.portfolio_item_id,
    jsonb_build_object('user_id', _row.user_id, 'previous_role', _row.role, 'new_role', _role),
    NULL::uuid
  );
END;
$$;


--
-- Name: admin_upsert_knowledge_article_ai_metadata(uuid, text, text[], text[], text[], text[], text[], text, text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_knowledge_article_ai_metadata(_article_id uuid, _ai_flow text DEFAULT 'direct_answer'::text, _feature_area text[] DEFAULT '{}'::text[], _route_patterns text[] DEFAULT '{}'::text[], _user_intents text[] DEFAULT '{}'::text[], _audience text[] DEFAULT '{}'::text[], _synonyms text[] DEFAULT '{}'::text[], _freshness_label text DEFAULT 'current'::text, _related_feature_flags text[] DEFAULT '{}'::text[], _question_examples text[] DEFAULT '{}'::text[], _answer_rules text[] DEFAULT '{}'::text[], _forbidden_claims text[] DEFAULT '{}'::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_article_org uuid;
  v_id uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT organization_id INTO v_article_org
  FROM public.knowledge_articles WHERE id = _article_id;

  IF v_article_org IS NULL OR v_article_org <> v_org THEN
    RAISE EXCEPTION 'article_not_found';
  END IF;

  INSERT INTO public.knowledge_article_ai_metadata AS m (
    article_id, organization_id,
    ai_flow, feature_area, route_patterns, user_intents, audience,
    synonyms, freshness_label, related_feature_flags,
    question_examples_protected, answer_rules_protected, forbidden_claims_protected,
    created_by, updated_by
  ) VALUES (
    _article_id, v_org,
    _ai_flow, _feature_area, _route_patterns, _user_intents, _audience,
    _synonyms, _freshness_label, _related_feature_flags,
    public._kc_ai_meta_encrypt_array(_question_examples, v_org),
    public._kc_ai_meta_encrypt_array(_answer_rules,      v_org),
    public._kc_ai_meta_encrypt_array(_forbidden_claims,  v_org),
    auth.uid(), auth.uid()
  )
  ON CONFLICT (article_id) DO UPDATE SET
    ai_flow                     = EXCLUDED.ai_flow,
    feature_area                = EXCLUDED.feature_area,
    route_patterns              = EXCLUDED.route_patterns,
    user_intents                = EXCLUDED.user_intents,
    audience                    = EXCLUDED.audience,
    synonyms                    = EXCLUDED.synonyms,
    freshness_label             = EXCLUDED.freshness_label,
    related_feature_flags       = EXCLUDED.related_feature_flags,
    question_examples_protected = EXCLUDED.question_examples_protected,
    answer_rules_protected      = EXCLUDED.answer_rules_protected,
    forbidden_claims_protected  = EXCLUDED.forbidden_claims_protected,
    updated_by                  = auth.uid(),
    updated_at                  = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: admin_upsert_knowledge_article_ai_metadata(uuid, text, text[], text[], text[], text[], text[], text, text[], text[], text[], text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_knowledge_article_ai_metadata(_article_id uuid, _ai_flow text DEFAULT 'direct_answer'::text, _feature_area text[] DEFAULT '{}'::text[], _route_patterns text[] DEFAULT '{}'::text[], _user_intents text[] DEFAULT '{}'::text[], _audience text[] DEFAULT '{}'::text[], _synonyms text[] DEFAULT '{}'::text[], _freshness_label text DEFAULT 'current'::text, _related_feature_flags text[] DEFAULT '{}'::text[], _question_examples text[] DEFAULT '{}'::text[], _answer_rules text[] DEFAULT '{}'::text[], _forbidden_claims text[] DEFAULT '{}'::text[], _workflow_metadata jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_article_org uuid;
  v_id uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT organization_id INTO v_article_org FROM public.knowledge_articles WHERE id = _article_id;
  IF v_article_org IS NULL OR v_article_org <> v_org THEN
    RAISE EXCEPTION 'article_not_found';
  END IF;
  INSERT INTO public.knowledge_article_ai_metadata AS m (
    article_id, organization_id,
    ai_flow, feature_area, route_patterns, user_intents, audience,
    synonyms, freshness_label, related_feature_flags,
    question_examples_protected, answer_rules_protected, forbidden_claims_protected,
    workflow_metadata_protected,
    created_by, updated_by
  ) VALUES (
    _article_id, v_org,
    _ai_flow, _feature_area, _route_patterns, _user_intents, _audience,
    _synonyms, _freshness_label, _related_feature_flags,
    public._kc_ai_meta_encrypt_array(_question_examples, v_org),
    public._kc_ai_meta_encrypt_array(_answer_rules,      v_org),
    public._kc_ai_meta_encrypt_array(_forbidden_claims,  v_org),
    public._kc_ai_meta_encrypt_jsonb(_workflow_metadata, v_org),
    auth.uid(), auth.uid()
  )
  ON CONFLICT (article_id) DO UPDATE SET
    ai_flow                     = EXCLUDED.ai_flow,
    feature_area                = EXCLUDED.feature_area,
    route_patterns              = EXCLUDED.route_patterns,
    user_intents                = EXCLUDED.user_intents,
    audience                    = EXCLUDED.audience,
    synonyms                    = EXCLUDED.synonyms,
    freshness_label             = EXCLUDED.freshness_label,
    related_feature_flags       = EXCLUDED.related_feature_flags,
    question_examples_protected = EXCLUDED.question_examples_protected,
    answer_rules_protected      = EXCLUDED.answer_rules_protected,
    forbidden_claims_protected  = EXCLUDED.forbidden_claims_protected,
    workflow_metadata_protected = EXCLUDED.workflow_metadata_protected,
    updated_by                  = auth.uid(),
    updated_at                  = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: tenant_integrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_integrations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind public.tenant_integration_kind NOT NULL,
    name text NOT NULL,
    status public.tenant_integration_status DEFAULT 'not_configured'::public.tenant_integration_status NOT NULL,
    is_enabled boolean DEFAULT false NOT NULL,
    config_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_tested_at timestamp with time zone,
    last_success_at timestamp with time zone,
    last_error_at timestamp with time zone,
    last_error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT tenant_integrations_config_is_object CHECK ((jsonb_typeof(config_metadata) = 'object'::text)),
    CONSTRAINT tenant_integrations_name_nonempty CHECK ((length(btrim(name)) > 0))
);


--
-- Name: admin_upsert_tenant_integration(uuid, public.tenant_integration_kind, text, jsonb, boolean, public.tenant_integration_status, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_tenant_integration(_tenant_id uuid, _kind public.tenant_integration_kind, _name text DEFAULT 'default'::text, _config jsonb DEFAULT '{}'::jsonb, _is_enabled boolean DEFAULT NULL::boolean, _status public.tenant_integration_status DEFAULT NULL::public.tenant_integration_status, _reason text DEFAULT NULL::text) RETURNS public.tenant_integrations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_integrations;
  _cfg jsonb := COALESCE(_config, '{}'::jsonb);
BEGIN
  PERFORM public._assert_tenant_admin_or_super(_tenant_id, _reason);

  IF jsonb_typeof(_cfg) <> 'object' THEN
    RAISE EXCEPTION 'config_metadata must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  -- Phase 4D.10A.5: Fail-closed on ANY non-empty config_metadata. Only '{}'
  -- is permitted until per-integration metadata allowlists are implemented.
  IF _cfg <> '{}'::jsonb THEN
    RAISE EXCEPTION 'config_metadata is disabled until per-integration metadata allowlists are implemented. Store secrets through tenant secret setup only.'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.tenant_integrations (tenant_id, kind, name, config_metadata, is_enabled, status, created_by, updated_by)
  VALUES (_tenant_id, _kind, _name, '{}'::jsonb,
          COALESCE(_is_enabled, false), COALESCE(_status, 'not_configured'), auth.uid(), auth.uid())
  ON CONFLICT (tenant_id, kind, name) DO UPDATE
    SET is_enabled = COALESCE(_is_enabled, public.tenant_integrations.is_enabled),
        status = COALESCE(_status, public.tenant_integrations.status),
        updated_by = auth.uid(),
        updated_at = now()
  RETURNING * INTO _row;

  INSERT INTO public.tenant_secret_access_audit(tenant_id, integration_id, actor_user_id, action, reason, function_name, result)
  VALUES (_tenant_id, _row.id, auth.uid(), 'updated', _reason, 'admin_upsert_tenant_integration', 'success');

  RETURN _row;
END $$;


--
-- Name: adoption_resolve_object_project(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adoption_resolve_object_project(_object_type text, _object_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _t text; _tid uuid; _proj uuid;
BEGIN
  IF _object_type = 'risk' THEN
    SELECT target_type, target_id INTO _t, _tid FROM public.risks WHERE id = _object_id;
  ELSIF _object_type = 'blocker' THEN
    SELECT target_type, target_id INTO _t, _tid FROM public.blockers WHERE id = _object_id;
  ELSIF _object_type = 'kpi' THEN
    SELECT target_type, target_id INTO _t, _tid FROM public.kpi_definitions WHERE id = _object_id;
    -- KPIs must be project-scoped for adoption linking
    IF _t IS DISTINCT FROM 'project' THEN RETURN NULL; END IF;
    RETURN _tid;
  ELSE
    RETURN NULL;
  END IF;

  IF _tid IS NULL THEN RETURN NULL; END IF;
  IF _t = 'project' THEN
    RETURN _tid;
  ELSIF _t = 'phase' THEN
    SELECT project_id INTO _proj FROM public.phases WHERE id = _tid;
    RETURN _proj;
  ELSIF _t = 'task' THEN
    SELECT project_id INTO _proj FROM public.tasks WHERE id = _tid;
    RETURN _proj;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: ai_guide_v2_admin_get_chunk_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_guide_v2_admin_get_chunk_summary(p_organization_id uuid) RETURNS TABLE(source_type text, source_status text, total_count bigint, vector_ready_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not public.is_org_admin(auth.uid(), p_organization_id) then
    raise exception 'admin required' using errcode = '42501';
  end if;

  return query
  select
    c.source_type,
    c.source_status,
    count(*)::bigint as total_count,
    count(*) filter (where c.vector_ready)::bigint as vector_ready_count
  from public.ai_guide_v2_knowledge_chunks c
  where c.organization_id = p_organization_id
  group by c.source_type, c.source_status
  order by c.source_type, c.source_status;
end;
$$;


--
-- Name: ai_guide_v2_admin_reindex_knowledge(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_guide_v2_admin_reindex_knowledge(p_scope text, p_article_id uuid DEFAULT NULL::uuid, p_force boolean DEFAULT false) RETURNS TABLE(job_id uuid, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  _org uuid;
  _job_type text;
  _new_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Access denied';
  end if;
  _org := public.get_user_org_id(auth.uid());
  if _org is null or not public.is_org_admin(auth.uid(), _org) then
    raise exception 'Access denied';
  end if;

  _job_type := case p_scope
    when 'full' then 'full_rebuild'
    when 'article' then 'article_refresh'
    when 'workflow' then 'workflow_refresh'
    when 'metadata' then 'metadata_refresh'
    else null
  end;

  if _job_type is null then
    raise exception 'Invalid scope: %', p_scope;
  end if;

  insert into public.ai_guide_v2_embedding_jobs (
    organization_id, job_type, status, requested_by, source_article_id, stats
  ) values (
    _org, _job_type, 'queued', auth.uid(), p_article_id,
    jsonb_build_object('force', coalesce(p_force, false))
  )
  returning id into _new_id;

  return query select _new_id, 'queued'::text;
end;
$$;


--
-- Name: ai_guide_v2_list_index_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_guide_v2_list_index_status(p_organization_id uuid) RETURNS TABLE(total_chunks bigint, vector_ready_count bigint, stale_count bigint, last_indexed_at timestamp with time zone, failed_jobs_24h bigint, embedding_model text, embedding_dimensions integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  _caller_org uuid;
begin
  if auth.uid() is null then
    raise exception 'Access denied';
  end if;
  _caller_org := public.get_user_org_id(auth.uid());
  if _caller_org is null or _caller_org <> p_organization_id then
    raise exception 'Access denied';
  end if;
  if not public.is_org_admin(auth.uid(), p_organization_id) then
    raise exception 'Access denied';
  end if;

  return query
  select
    (select count(*) from public.ai_guide_v2_knowledge_chunks c where c.organization_id = p_organization_id),
    (select count(*) from public.ai_guide_v2_knowledge_chunks c where c.organization_id = p_organization_id and c.vector_ready = true),
    (select count(*) from public.ai_guide_v2_knowledge_chunks c
       where c.organization_id = p_organization_id
         and (c.source_updated_at is not null and (c.indexed_at is null or c.indexed_at < c.source_updated_at))),
    (select max(c.indexed_at) from public.ai_guide_v2_knowledge_chunks c where c.organization_id = p_organization_id),
    (select count(*) from public.ai_guide_v2_embedding_jobs j
       where j.organization_id = p_organization_id
         and j.status = 'failed'
         and j.created_at >= now() - interval '24 hours'),
    'text-embedding-3-small@1536'::text,
    1536::integer;
end;
$$;


--
-- Name: ai_guide_v2_match_knowledge_chunks(extensions.vector, uuid, uuid, text, text[], text, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_guide_v2_match_knowledge_chunks(query_embedding extensions.vector, p_organization_id uuid, p_user_id uuid, p_route text DEFAULT NULL::text, p_feature_area text[] DEFAULT NULL::text[], p_intent_type text DEFAULT NULL::text, p_workflow_id text DEFAULT NULL::text, p_match_count integer DEFAULT 8, p_min_similarity numeric DEFAULT 0.0) RETURNS TABLE(chunk_id uuid, source_type text, article_id uuid, article_slug text, article_title text, source_id text, similarity numeric, hybrid_score numeric, metadata jsonb, route_match boolean, feature_match boolean, workflow_match boolean, source_confidence text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  _caller_org uuid;
begin
  if auth.uid() is null then
    return;
  end if;
  if p_user_id is null or p_user_id <> auth.uid() then
    return;
  end if;

  _caller_org := public.get_user_org_id(auth.uid());
  if _caller_org is null or _caller_org <> p_organization_id then
    return;
  end if;

  return query
  with scored as (
    select
      c.id as chunk_id,
      c.source_type,
      c.article_id,
      c.article_slug,
      c.article_title,
      c.source_id,
      (1 - (c.embedding <=> query_embedding))::numeric as similarity,
      c.metadata,
      (p_route is not null and c.route_patterns is not null and p_route = any(c.route_patterns)) as route_match,
      (p_feature_area is not null and c.feature_area is not null and c.feature_area && p_feature_area) as feature_match,
      (p_workflow_id is not null and c.workflow_id is not null and c.workflow_id = p_workflow_id) as workflow_match
    from public.ai_guide_v2_knowledge_chunks c
    where c.organization_id = p_organization_id
      and c.source_status = 'published'
      and c.vector_ready = true
  )
  select
    s.chunk_id,
    s.source_type,
    s.article_id,
    s.article_slug,
    s.article_title,
    s.source_id,
    s.similarity,
    (
      0.55 * s.similarity
      + (case when s.route_match then 0.10 else 0.0 end)
      + (case when s.feature_match then 0.10 else 0.0 end)
      + (case when s.workflow_match then 0.15 else 0.0 end)
    )::numeric as hybrid_score,
    s.metadata,
    s.route_match,
    s.feature_match,
    s.workflow_match,
    case
      when s.similarity >= 0.80 then 'high'
      when s.similarity >= 0.60 then 'medium'
      else 'low'
    end as source_confidence
  from scored s
  where s.similarity >= coalesce(p_min_similarity, 0.0)
  order by hybrid_score desc, s.similarity desc
  limit greatest(coalesce(p_match_count, 8), 1);
end;
$$;


--
-- Name: ai_help_admin_list_history_feedback(timestamp with time zone, timestamp with time zone, uuid, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_help_admin_list_history_feedback(_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, _date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, _user_id uuid DEFAULT NULL::uuid, _rating text DEFAULT NULL::text, _reason_code text DEFAULT NULL::text, _context_route text DEFAULT NULL::text, _search text DEFAULT NULL::text, _limit integer DEFAULT 500) RETURNS TABLE(conversation_id uuid, conversation_title text, conversation_created_at timestamp with time zone, conversation_updated_at timestamp with time zone, user_id uuid, user_email text, user_message_id uuid, user_question text, assistant_message_id uuid, assistant_answer text, source_article_ids uuid[], context_route text, context_label text, assistant_created_at timestamp with time zone, feedback_id uuid, feedback_rating text, feedback_reason_code text, feedback_comment text, feedback_created_at timestamp with time zone, feedback_updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_lim int  := LEAST(GREATEST(COALESCE(_limit, 500), 1), 1000);
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  WITH asst AS (
    SELECT m.id, m.conversation_id, m.organization_id, m.user_id,
           public.btpm_decrypt(m.content, m.organization_id) AS answer,
           m.source_article_ids, m.context_route,
           public.btpm_decrypt(m.context_label, m.organization_id) AS context_label,
           m.created_at
    FROM public.ai_help_messages m
    WHERE m.organization_id = v_org AND m.role = 'assistant'
  ),
  paired AS (
    SELECT a.*,
           (
             SELECT u.id FROM public.ai_help_messages u
             WHERE u.conversation_id = a.conversation_id
               AND u.role = 'user'
               AND u.created_at <= a.created_at
             ORDER BY u.created_at DESC LIMIT 1
           ) AS user_message_id
    FROM asst a
  )
  SELECT
    c.id AS conversation_id,
    public.btpm_decrypt(c.title, c.organization_id) AS conversation_title,
    c.created_at AS conversation_created_at,
    c.updated_at AS conversation_updated_at,
    p.user_id,
    pr.email AS user_email,
    p.user_message_id,
    (SELECT public.btpm_decrypt(um.content, um.organization_id)
       FROM public.ai_help_messages um WHERE um.id = p.user_message_id) AS user_question,
    p.id AS assistant_message_id,
    p.answer AS assistant_answer,
    p.source_article_ids,
    p.context_route,
    p.context_label,
    p.created_at AS assistant_created_at,
    f.id AS feedback_id,
    f.rating AS feedback_rating,
    f.reason_code AS feedback_reason_code,
    public.btpm_decrypt(f.comment, f.organization_id) AS feedback_comment,
    f.created_at AS feedback_created_at,
    f.updated_at AS feedback_updated_at
  FROM paired p
  JOIN public.ai_help_conversations c ON c.id = p.conversation_id
  LEFT JOIN public.ai_help_message_feedback f
         ON f.assistant_message_id = p.id
  LEFT JOIN public.profiles pr ON pr.id = p.user_id
  WHERE
    (_date_from IS NULL OR p.created_at >= _date_from)
    AND (_date_to   IS NULL OR p.created_at <= _date_to)
    AND (_user_id   IS NULL OR p.user_id = _user_id)
    AND (
      _rating IS NULL
      OR (_rating = 'none' AND f.id IS NULL)
      OR (_rating IN ('helpful','not_helpful') AND f.rating = _rating)
    )
    AND (_reason_code IS NULL OR f.reason_code = _reason_code)
    AND (_context_route IS NULL OR p.context_route = _context_route)
    AND (
      _search IS NULL OR _search = ''
      OR p.answer ILIKE '%' || _search || '%'
      OR EXISTS (
        SELECT 1 FROM public.ai_help_messages um2
        WHERE um2.id = p.user_message_id
          AND public.btpm_decrypt(um2.content, um2.organization_id) ILIKE '%' || _search || '%'
      )
    )
  ORDER BY p.created_at DESC
  LIMIT v_lim;
END; $$;


--
-- Name: ai_help_append_message(uuid, text, text, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_help_append_message(_conversation_id uuid, _role text, _content text, _context_route text DEFAULT NULL::text, _context_label text DEFAULT NULL::text, _source_article_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org  uuid := public.get_user_org_id(auth.uid());
  v_conv public.ai_help_conversations%ROWTYPE;
  v_id   uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF _role NOT IN ('user','assistant') THEN
    RAISE EXCEPTION 'invalid role';
  END IF;
  SELECT * INTO v_conv FROM public.ai_help_conversations WHERE id = _conversation_id;
  IF v_conv.id IS NULL OR v_conv.user_id <> auth.uid() OR v_conv.organization_id <> v_org THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO public.ai_help_messages
    (conversation_id, organization_id, user_id, role, content, context_route, context_label, source_article_ids)
  VALUES
    (_conversation_id, v_org, auth.uid(), _role, _content, _context_route, _context_label, COALESCE(_source_article_ids, '{}'::uuid[]))
  RETURNING id INTO v_id;

  UPDATE public.ai_help_conversations SET updated_at = now() WHERE id = _conversation_id;
  RETURN v_id;
END; $$;


