-- Name: ai_help_create_conversation(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_help_create_conversation(_context_route text DEFAULT NULL::text, _context_label text DEFAULT NULL::text, _title text DEFAULT NULL::text) RETURNS uuid
