--
-- Name: ai_help_list_conversations(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_help_list_conversations(_include_archived boolean DEFAULT false) RETURNS TABLE(id uuid, title text, context_route text, context_label text, created_at timestamp with time zone, updated_at timestamp with time zone, archived_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org uuid := public.get_user_org_id(auth.uid());
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  RETURN QUERY
  SELECT c.id,
         public.btpm_decrypt(c.title, c.organization_id),
         c.context_route,
         public.btpm_decrypt(c.context_label, c.organization_id),
         c.created_at, c.updated_at, c.archived_at
  FROM public.ai_help_conversations c
  WHERE c.user_id = auth.uid()
    AND c.organization_id = v_org
    AND (_include_archived OR c.archived_at IS NULL)
  ORDER BY c.updated_at DESC
  LIMIT 100;
END; $$;


--
-- Name: ai_help_list_messages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_help_list_messages(_conversation_id uuid) RETURNS TABLE(id uuid, role text, content text, context_route text, context_label text, source_article_ids uuid[], created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org  uuid := public.get_user_org_id(auth.uid());
  v_conv public.ai_help_conversations%ROWTYPE;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  SELECT * INTO v_conv FROM public.ai_help_conversations c WHERE c.id = _conversation_id;
  IF v_conv.id IS NULL OR v_conv.user_id <> auth.uid() OR v_conv.organization_id <> v_org THEN RETURN; END IF;

  RETURN QUERY
  SELECT m.id, m.role,
         public.btpm_decrypt(m.content, m.organization_id),
         m.context_route,
