--
-- Name: ai_help_upsert_message_feedback(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_help_upsert_message_feedback(_assistant_message_id uuid, _rating text, _reason_code text DEFAULT NULL::text, _comment text DEFAULT NULL::text) RETURNS TABLE(id uuid, assistant_message_id uuid, conversation_id uuid, rating text, reason_code text, comment text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
#variable_conflict use_column
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_msg public.ai_help_messages%ROWTYPE;
  v_id  uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF _rating NOT IN ('helpful','not_helpful') THEN
    RAISE EXCEPTION 'invalid rating';
  END IF;
  SELECT * INTO v_msg FROM public.ai_help_messages m WHERE m.id = _assistant_message_id;
  IF v_msg.id IS NULL
     OR v_msg.role <> 'assistant'
     OR v_msg.user_id <> auth.uid()
     OR v_msg.organization_id <> v_org THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Pass plaintext _comment; the BEFORE INSERT/UPDATE trigger
  -- (trg_encrypt_ai_help_feedback_fields) handles encryption exactly once.
  INSERT INTO public.ai_help_message_feedback AS f
    (organization_id, conversation_id, assistant_message_id, user_id, rating, reason_code, comment)
  VALUES
    (v_org, v_msg.conversation_id, _assistant_message_id, auth.uid(), _rating, _reason_code, _comment)
  ON CONFLICT (user_id, assistant_message_id) DO UPDATE
    SET rating      = EXCLUDED.rating,
        reason_code = EXCLUDED.reason_code,
        comment     = _comment
  RETURNING f.id INTO v_id;

  RETURN QUERY
  SELECT f.id, f.assistant_message_id, f.conversation_id, f.rating, f.reason_code,
         public.btpm_decrypt(f.comment, f.organization_id),
         f.created_at, f.updated_at
  FROM public.ai_help_message_feedback f
  WHERE f.id = v_id;
END; $$;


--
-- Name: api_c_enforce_ack_policy_client_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_c_enforce_ack_policy_client_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy_client uuid;
BEGIN
  SELECT api_client_id INTO v_policy_client
  FROM public.api_client_policy_versions
  WHERE id = NEW.policy_version_id;

  IF v_policy_client IS NULL THEN
    RAISE EXCEPTION
      'api_c_4: policy_version_id % does not exist', NEW.policy_version_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_policy_client <> NEW.api_client_id THEN
    RAISE EXCEPTION
      'api_c_4: policy_version_id % does not belong to api_client_id %',
      NEW.policy_version_id, NEW.api_client_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_c_enforce_capability_grant_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_c_enforce_capability_grant_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_tenant uuid;
  v_ws_org uuid;
BEGIN
  SELECT tenant_id INTO v_org_tenant
  FROM public.organizations
  WHERE id = NEW.organization_id;

  IF v_org_tenant IS NULL THEN
    RAISE EXCEPTION
      'api_c_4: organization_id % does not exist', NEW.organization_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_org_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION
      'api_c_4: organization_id % belongs to tenant %, not %',
      NEW.organization_id, v_org_tenant, NEW.tenant_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.workspace_id IS NOT NULL THEN
    SELECT organization_id INTO v_ws_org
    FROM public.workspaces
    WHERE id = NEW.workspace_id;

    IF v_ws_org IS NULL THEN
      RAISE EXCEPTION
        'api_c_4: workspace_id % does not exist', NEW.workspace_id
        USING ERRCODE = 'check_violation';
    END IF;

    IF v_ws_org <> NEW.organization_id THEN
      RAISE EXCEPTION
        'api_c_4: workspace_id % belongs to organization %, not %',
        NEW.workspace_id, v_ws_org, NEW.organization_id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_c_enforce_enablement_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_c_enforce_enablement_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_authoritative_tenant_id uuid;
  v_authoritative_organization_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'api_organization_client_enablements' THEN
    IF NEW.organization_id IS NULL THEN
      RAISE EXCEPTION 'api_c scope integrity: organization_id is required'
        USING ERRCODE = '23514';
    END IF;

    SELECT o.tenant_id
      INTO v_authoritative_tenant_id
      FROM public.organizations o
     WHERE o.id = NEW.organization_id;

    IF v_authoritative_tenant_id IS NULL THEN
      RAISE EXCEPTION
        'api_c scope integrity: organization % not found or has no tenant',
        NEW.organization_id
        USING ERRCODE = '23503';
    END IF;

    IF NEW.tenant_id IS NULL OR NEW.tenant_id <> v_authoritative_tenant_id THEN
      RAISE EXCEPTION
        'api_c scope integrity: tenant_id % does not match authoritative tenant % for organization %',
        NEW.tenant_id, v_authoritative_tenant_id, NEW.organization_id
        USING ERRCODE = '23514';
    END IF;

    RETURN NEW;

  ELSIF TG_TABLE_NAME = 'api_workspace_client_enablements' THEN
    IF NEW.workspace_id IS NULL THEN
      RAISE EXCEPTION 'api_c scope integrity: workspace_id is required'
        USING ERRCODE = '23514';
    END IF;

    SELECT w.organization_id
      INTO v_authoritative_organization_id
      FROM public.workspaces w
     WHERE w.id = NEW.workspace_id;

    IF v_authoritative_organization_id IS NULL THEN
      RAISE EXCEPTION
        'api_c scope integrity: workspace % not found or has no organization',
        NEW.workspace_id
        USING ERRCODE = '23503';
    END IF;

    IF NEW.organization_id IS NULL
       OR NEW.organization_id <> v_authoritative_organization_id THEN
      RAISE EXCEPTION
        'api_c scope integrity: organization_id % does not match authoritative organization % for workspace %',
        NEW.organization_id, v_authoritative_organization_id, NEW.workspace_id
        USING ERRCODE = '23514';
    END IF;

    SELECT o.tenant_id
      INTO v_authoritative_tenant_id
      FROM public.organizations o
     WHERE o.id = v_authoritative_organization_id;

    IF v_authoritative_tenant_id IS NULL THEN
      RAISE EXCEPTION
        'api_c scope integrity: authoritative organization % has no tenant',
        v_authoritative_organization_id
        USING ERRCODE = '23503';
    END IF;

    IF NEW.tenant_id IS NULL OR NEW.tenant_id <> v_authoritative_tenant_id THEN
      RAISE EXCEPTION
        'api_c scope integrity: tenant_id % does not match authoritative tenant % for workspace %',
        NEW.tenant_id, v_authoritative_tenant_id, NEW.workspace_id
        USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'api_c scope integrity: unsupported table %', TG_TABLE_NAME
    USING ERRCODE = '42P01';
END;
$$;


