--
-- Name: api_g_5_10_get_mcp_connection_verification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_get_mcp_connection_verification(_api_client_id uuid) RETURNS TABLE(verified boolean, last_successful_authentication_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_last timestamptz;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _api_client_id IS NULL THEN
    RAISE EXCEPTION 'invalid_mcp_connection_verification_query' USING ERRCODE = '22023';
  END IF;

  SELECT max(e.event_at) INTO v_last
  FROM public.api_request_activity_events e
  WHERE e.api_client_id = _api_client_id
    AND e.source_channel = 'mcp'
    AND e.route_id = 'mcp.connection_verified'
    AND e.http_status = 200;

  RETURN QUERY SELECT (v_last IS NOT NULL), v_last;
END;
$$;


--
-- Name: api_g_5_10_get_organization_client_rate_profile(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_get_organization_client_rate_profile(_organization_id uuid, _api_client_id uuid) RETURNS TABLE(profile_key text, display_name text, description text, request_limit integer, window_seconds integer, is_default boolean, is_explicit boolean, assigned_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid;
  v_tenant_id uuid;
  v_assignment_profile_id uuid;
  v_assigned_at timestamptz;
  v_profile public.api_rate_limit_profile_catalogue%ROWTYPE;
BEGIN
  v_actor := auth.uid();

  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'connected_app_unavailable' USING ERRCODE = '22023';
  END IF;

  -- Server-derived Tenant scope; caller never supplies Tenant identity.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'connected_app_unavailable' USING ERRCODE = '22023';
  END IF;

  IF NOT (
    public.is_tenant_admin(v_tenant_id, v_actor)
    OR public.is_org_admin(v_actor, _organization_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Connected-app containment: exact Organization/client enablement must exist.
  PERFORM 1
  FROM public.api_organization_client_enablements oe
  WHERE oe.organization_id = _organization_id
    AND oe.api_client_id = _api_client_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'connected_app_unavailable' USING ERRCODE = '22023';
  END IF;

  BEGIN
    SELECT a.rate_profile_id, a.updated_at
      INTO v_assignment_profile_id, v_assigned_at
      FROM public.api_organization_client_rate_profile_assignments a
     WHERE a.organization_id = _organization_id
       AND a.api_client_id = _api_client_id;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE EXCEPTION 'rate_profile_assignment_unavailable' USING ERRCODE = '22023';
  END;

  IF v_assignment_profile_id IS NOT NULL THEN
    SELECT * INTO v_profile
    FROM public.api_rate_limit_profile_catalogue c
    WHERE c.id = v_assignment_profile_id
      AND c.lifecycle_status = 'active';

    -- A retired explicit selection must never silently fall back to the default.
    IF v_profile.id IS NULL THEN
      RAISE EXCEPTION 'rate_profile_unavailable' USING ERRCODE = '22023';
    END IF;

    RETURN QUERY
      SELECT v_profile.profile_key,
             v_profile.display_name,
             v_profile.description,
             v_profile.request_limit,
             v_profile.window_seconds,
             v_profile.is_default,
             true,
             v_assigned_at;
    RETURN;
  END IF;

  SELECT * INTO v_profile
  FROM public.api_rate_limit_profile_catalogue c
  WHERE c.lifecycle_status = 'active'
    AND c.is_default = true;

  IF v_profile.id IS NULL THEN
    RAISE EXCEPTION 'rate_profile_unavailable' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
    SELECT v_profile.profile_key,
           v_profile.display_name,
           v_profile.description,
           v_profile.request_limit,
           v_profile.window_seconds,
           v_profile.is_default,
           false,
           NULL::timestamptz;
END;
$$;


--
-- Name: api_g_5_10_list_client_activity(uuid, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_list_client_activity(_api_client_id uuid, _organization_id uuid DEFAULT NULL::uuid, _limit integer DEFAULT 50, _before_event_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _before_event_id uuid DEFAULT NULL::uuid) RETURNS TABLE(event_id uuid, event_at timestamp with time zone, api_client_id uuid, actor_user_id uuid, api_version text, route_id text, http_method text, http_status integer, status_class text, duration_ms integer, tenant_id uuid, organization_id uuid, workspace_id uuid, project_id uuid, scope_level text, correlation_id text, source_channel text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_authorized boolean := false;
  v_platform_mode boolean := (_organization_id IS NULL);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Query-shape validation (never echoes supplied values).
  IF _api_client_id IS NULL THEN
    RAISE EXCEPTION 'invalid_activity_query' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'invalid_activity_query' USING ERRCODE = '22023';
  END IF;

  IF (_before_event_at IS NULL) <> (_before_event_id IS NULL) THEN
    RAISE EXCEPTION 'invalid_activity_query' USING ERRCODE = '22023';
  END IF;

  IF v_platform_mode THEN
    -- Platform mode: the only mode permitted to observe unscoped or
    -- cross-Organization activity.
    v_authorized := public.is_platform_super_admin(v_actor);
    IF NOT v_authorized THEN
      RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
    END IF;
  ELSE
    -- Organization mode: Tenant is derived server-side only.
    SELECT o.tenant_id INTO v_tenant_id
    FROM public.organizations o
    WHERE o.id = _organization_id;

    IF v_tenant_id IS NULL THEN
      RAISE EXCEPTION 'invalid_activity_query' USING ERRCODE = '22023';
    END IF;

    -- Platform authority is deliberately NOT accepted here.
    v_authorized := public.is_tenant_admin(v_tenant_id, v_actor)
      OR public.is_org_admin(v_actor, _organization_id);

    IF NOT v_authorized THEN
      RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    e.id AS event_id,
    e.event_at,
    e.api_client_id,
    e.actor_user_id,
    e.api_version,
    e.route_id,
    e.http_method,
    e.http_status,
    CASE
      WHEN e.http_status BETWEEN 100 AND 199 THEN 'informational'
      WHEN e.http_status BETWEEN 200 AND 299 THEN 'success'
      WHEN e.http_status BETWEEN 300 AND 399 THEN 'redirect'
      WHEN e.http_status BETWEEN 400 AND 499 THEN 'client_error'
      WHEN e.http_status BETWEEN 500 AND 599 THEN 'server_error'
      ELSE 'unknown'
    END::text AS status_class,
    e.duration_ms,
    e.tenant_id,
    e.organization_id,
    e.workspace_id,
    e.project_id,
    CASE
      WHEN e.project_id IS NOT NULL THEN 'project'
      WHEN e.workspace_id IS NOT NULL THEN 'workspace'
      WHEN e.organization_id IS NOT NULL THEN 'organization'
      WHEN e.tenant_id IS NOT NULL THEN 'tenant'
      ELSE 'unscoped'
    END::text AS scope_level,
    e.correlation_id,
    e.source_channel
  FROM public.api_request_activity_events e
  WHERE e.api_client_id = _api_client_id
    AND (
      v_platform_mode
      OR e.organization_id = _organization_id
    )
    AND (
      _before_event_at IS NULL
      OR (e.event_at, e.id) < (_before_event_at, _before_event_id)
    )
  ORDER BY e.event_at DESC, e.id DESC
  LIMIT _limit;

EXCEPTION
  WHEN OTHERS THEN
    IF SQLERRM = 'not_authorized' THEN
      RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
    END IF;
    IF SQLERRM = 'invalid_activity_query' THEN
      RAISE EXCEPTION 'invalid_activity_query' USING ERRCODE = '22023';
    END IF;
    RAISE EXCEPTION 'activity_unavailable' USING ERRCODE = '58000';
END;
$$;


--
-- Name: api_g_5_10_list_rate_profile_catalogue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_list_rate_profile_catalogue() RETURNS TABLE(profile_key text, display_name text, description text, request_limit integer, window_seconds integer, is_default boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  v_actor := auth.uid();

  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  BEGIN
    RETURN QUERY
      SELECT c.profile_key,
             c.display_name,
             c.description,
             c.request_limit,
             c.window_seconds,
             c.is_default
        FROM public.api_rate_limit_profile_catalogue AS c
       WHERE c.lifecycle_status = 'active'
       ORDER BY c.is_default DESC, c.profile_key ASC;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE EXCEPTION 'rate_profile_catalogue_unavailable';
  END;
END;
$$;


--
-- Name: api_g_5_10_record_api_activity(uuid, text, text, text, integer, integer, uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_record_api_activity(_api_client_id uuid, _api_version text, _route_id text, _http_method text, _http_status integer, _duration_ms integer, _actor_user_id uuid DEFAULT NULL::uuid, _tenant_id uuid DEFAULT NULL::uuid, _organization_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _project_id uuid DEFAULT NULL::uuid, _correlation_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_method text;
  v_id uuid;
BEGIN
  IF _api_client_id IS NULL THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  IF _api_version IS NULL OR _api_version !~ '^v[1-9][0-9]*$' THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  IF _route_id IS NULL OR _route_id !~ '^[A-Za-z0-9._:-]{1,128}$' THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  IF _http_method IS NULL OR btrim(_http_method) IS DISTINCT FROM _http_method THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;
  v_method := upper(_http_method);
  IF v_method NOT IN ('GET','POST','PUT','PATCH','DELETE','OPTIONS','HEAD') THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  IF _http_status IS NULL OR _http_status < 100 OR _http_status > 599 THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  IF _duration_ms IS NULL OR _duration_ms < 0 OR _duration_ms > 3600000 THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  IF _correlation_id IS NOT NULL AND _correlation_id !~ '^[A-Za-z0-9_-]{1,64}$' THEN
    RAISE EXCEPTION 'invalid_activity_event';
  END IF;

  INSERT INTO public.api_request_activity_events (
    api_client_id, actor_user_id,
    api_version, route_id, http_method, http_status, duration_ms,
    tenant_id, organization_id, workspace_id, project_id,
    correlation_id
  ) VALUES (
    _api_client_id, _actor_user_id,
    _api_version, _route_id, v_method, _http_status, _duration_ms,
    _tenant_id, _organization_id, _workspace_id, _project_id,
    _correlation_id
  )
  RETURNING id INTO v_id;

  RETURN v_id;

EXCEPTION
  WHEN foreign_key_violation
    OR check_violation
    OR not_null_violation
  THEN
    RAISE EXCEPTION 'invalid_activity_event';

  WHEN OTHERS THEN
    IF SQLERRM = 'invalid_activity_scope' THEN
      RAISE EXCEPTION 'invalid_activity_scope';
    END IF;

    RAISE EXCEPTION 'invalid_activity_event';
END;
$_$;


--
-- Name: api_g_5_10_record_mcp_connection_verification(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_record_mcp_connection_verification(_api_client_id uuid, _actor_user_id uuid, _request_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_event_id uuid;
BEGIN
  IF _api_client_id IS NULL THEN
    RAISE EXCEPTION 'invalid_mcp_connection_verification' USING ERRCODE = '22023';
  END IF;

  IF _actor_user_id IS NULL THEN
    RAISE EXCEPTION 'invalid_mcp_connection_verification' USING ERRCODE = '22023';
  END IF;

  IF _request_id IS NULL OR _request_id !~ '^[A-Za-z0-9_-]{1,64}$' THEN
    RAISE EXCEPTION 'invalid_mcp_connection_verification' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.api_request_activity_events (
    api_client_id,
    actor_user_id,
    api_version,
    route_id,
    http_method,
    http_status,
    duration_ms,
    tenant_id,
    organization_id,
    workspace_id,
    project_id,
    correlation_id,
    source_channel
  ) VALUES (
    _api_client_id,
    _actor_user_id,
    'v1',
    'mcp.connection_verified',
    'POST',
    200,
    0,
    NULL,
    NULL,
    NULL,
    NULL,
    _request_id,
    'mcp'
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$_$;


--
-- Name: api_g_5_10_reject_activity_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_reject_activity_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.actor_user_id IS NOT NULL
     AND NEW.actor_user_id IS NULL
     AND (to_jsonb(NEW) - 'actor_user_id')
           IS NOT DISTINCT FROM
         (to_jsonb(OLD) - 'actor_user_id')
     AND NOT EXISTS (
       SELECT 1
       FROM auth.users u
       WHERE u.id = OLD.actor_user_id
     )
  THEN
    -- Sole permitted mutation: database-driven de-identification required by
    -- actor_user_id ON DELETE SET NULL.
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'invalid_activity_event';
END;
$$;


--
-- Name: api_g_5_10_resolve_target_activity_scope(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_resolve_target_activity_scope(_target_type text, _target_id uuid) RETURNS TABLE(tenant_id uuid, organization_id uuid, workspace_id uuid, project_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_project_id uuid;
BEGIN
  -- Fail closed on unsupported target types or invalid identity.
  IF _target_type IS NULL OR _target_id IS NULL THEN
    RETURN;
  END IF;
  IF _target_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
    RETURN;
  END IF;
  IF _target_type NOT IN ('project', 'phase', 'task') THEN
    RETURN;
  END IF;

  IF _target_type = 'project' THEN
    SELECT p.id INTO v_project_id
    FROM public.projects p
    WHERE p.id = _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT ph.project_id INTO v_project_id
    FROM public.phases ph
    WHERE ph.id = _target_id;
  ELSE
    SELECT ph.project_id INTO v_project_id
    FROM public.tasks t
    JOIN public.phases ph ON ph.id = t.phase_id
    WHERE t.id = _target_id;
  END IF;

  IF v_project_id IS NULL THEN
    RETURN;
  END IF;

  -- Canonical hierarchy: project -> workspace -> organization -> tenant.
  RETURN QUERY
  SELECT o.tenant_id, o.id, w.id, p.id
  FROM public.projects p
  JOIN public.workspaces w ON w.id = p.workspace_id
  JOIN public.organizations o ON o.id = w.organization_id
  WHERE p.id = v_project_id
    AND o.tenant_id IS NOT NULL;
END;
$$;


--
-- Name: api_g_5_10_set_organization_client_rate_profile(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_set_organization_client_rate_profile(_organization_id uuid, _api_client_id uuid, _profile_key text) RETURNS TABLE(profile_key text, display_name text, description text, request_limit integer, window_seconds integer, is_default boolean, is_explicit boolean, assigned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_actor uuid;
  v_tenant_id uuid;
  v_profile public.api_rate_limit_profile_catalogue%ROWTYPE;
  v_match_count integer;
  v_assigned_at timestamptz;
BEGIN
  v_actor := auth.uid();

  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'connected_app_unavailable' USING ERRCODE = '22023';
  END IF;

  -- Server-derived Tenant scope; caller never supplies Tenant identity.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'connected_app_unavailable' USING ERRCODE = '22023';
  END IF;

  IF NOT (
    public.is_tenant_admin(v_tenant_id, v_actor)
    OR public.is_org_admin(v_actor, _organization_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Connected-app containment: exact Organization/client enablement must exist.
  PERFORM 1
  FROM public.api_organization_client_enablements oe
  WHERE oe.organization_id = _organization_id
    AND oe.api_client_id = _api_client_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'connected_app_unavailable' USING ERRCODE = '22023';
  END IF;

  -- Profile key is the only accepted profile input.
  IF _profile_key IS NULL
     OR _profile_key !~ '^[a-z][a-z0-9_]{0,63}$' THEN
    RAISE EXCEPTION 'rate_profile_unavailable' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_match_count
  FROM public.api_rate_limit_profile_catalogue c
  WHERE c.profile_key = _profile_key
    AND c.lifecycle_status = 'active';

  IF v_match_count <> 1 THEN
    RAISE EXCEPTION 'rate_profile_unavailable' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_profile
  FROM public.api_rate_limit_profile_catalogue c
  WHERE c.profile_key = _profile_key
    AND c.lifecycle_status = 'active';

  BEGIN
    -- Transaction-scoped serialization for the exact Organization/client pair.
    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'api_g_5_10_organization_client_rate_profile|' ||
        _organization_id::text || '|' ||
        _api_client_id::text,
        0
      )
    );

    INSERT INTO public.api_organization_client_rate_profile_assignments AS a (
      organization_id, api_client_id, rate_profile_id, assigned_by,
      created_at, updated_at
    )
    VALUES (
      _organization_id, _api_client_id, v_profile.id, v_actor,
      now(), now()
    )
    ON CONFLICT (organization_id, api_client_id) DO UPDATE
      SET rate_profile_id = v_profile.id,
          assigned_by = v_actor,
          updated_at = now()
    RETURNING a.updated_at INTO v_assigned_at;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE EXCEPTION 'rate_profile_assignment_unavailable' USING ERRCODE = '22023';
  END;

  RETURN QUERY
    SELECT v_profile.profile_key,
           v_profile.display_name,
           v_profile.description,
           v_profile.request_limit,
           v_profile.window_seconds,
           v_profile.is_default,
           true,
           v_assigned_at;
END;
$_$;


--
-- Name: api_g_5_10_validate_activity_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_10_validate_activity_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_org_tenant uuid;
  v_ws_org uuid;
  v_proj_ws uuid;
BEGIN
  -- Hierarchy requirements (fail closed)
  IF NEW.organization_id IS NOT NULL AND NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'invalid_activity_scope';
  END IF;
  IF NEW.workspace_id IS NOT NULL AND (NEW.organization_id IS NULL OR NEW.tenant_id IS NULL) THEN
    RAISE EXCEPTION 'invalid_activity_scope';
  END IF;
  IF NEW.project_id IS NOT NULL AND (NEW.workspace_id IS NULL OR NEW.organization_id IS NULL OR NEW.tenant_id IS NULL) THEN
    RAISE EXCEPTION 'invalid_activity_scope';
  END IF;

  -- Canonical re-derivation (never trust caller-supplied parents)
  IF NEW.organization_id IS NOT NULL THEN
    SELECT o.tenant_id INTO v_org_tenant
    FROM public.organizations o WHERE o.id = NEW.organization_id;
    IF v_org_tenant IS NULL OR v_org_tenant IS DISTINCT FROM NEW.tenant_id THEN
      RAISE EXCEPTION 'invalid_activity_scope';
    END IF;
  END IF;

  IF NEW.workspace_id IS NOT NULL THEN
    SELECT w.organization_id INTO v_ws_org
    FROM public.workspaces w WHERE w.id = NEW.workspace_id;
    IF v_ws_org IS NULL OR v_ws_org IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'invalid_activity_scope';
    END IF;
  END IF;

  IF NEW.project_id IS NOT NULL THEN
    SELECT p.workspace_id INTO v_proj_ws
    FROM public.projects p WHERE p.id = NEW.project_id;
    IF v_proj_ws IS NULL OR v_proj_ws IS DISTINCT FROM NEW.workspace_id THEN
      RAISE EXCEPTION 'invalid_activity_scope';
    END IF;
  END IF;

  -- Tenant existence is enforced by the foreign key.
  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_2_enforce_catalogue_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_2_enforce_catalogue_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION
      'api_g_5_2: catalogue capabilities are retired, not deleted'
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.lifecycle_status = 'active' AND NEW.lifecycle_status = 'retired' THEN
    IF EXISTS (
      SELECT 1
      FROM public.api_client_supported_capabilities s
      WHERE s.api_version = OLD.api_version
        AND s.capability_kind = OLD.capability_kind
        AND s.capability_key = OLD.capability_key
        AND s.lifecycle_status = 'enabled'
    ) THEN
      RAISE EXCEPTION
        'api_g_5_2: cannot retire capability % while enabled client support references it',
        OLD.capability_key
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_2_enforce_grant_capability_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_2_enforce_grant_capability_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_catalogue_status text;
  v_supported_status text;
BEGIN
  IF NEW.lifecycle_status <> 'enabled' THEN
    RETURN NEW;
  END IF;

  -- Lock order: client-supported capability first, then catalogue. This keeps
  -- a consistent ordering with supported-capability lifecycle changes.
  SELECT lifecycle_status INTO v_supported_status
  FROM public.api_client_supported_capabilities
  WHERE api_client_id = NEW.api_client_id
    AND api_version = NEW.api_version
    AND capability_kind = NEW.capability_kind
    AND capability_key = NEW.capability_key
  FOR UPDATE;

  IF v_supported_status IS DISTINCT FROM 'enabled' THEN
    RAISE EXCEPTION
      'api_g_5_2: capability % is not an enabled supported capability for this API client',
      NEW.capability_key
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT lifecycle_status INTO v_catalogue_status
  FROM public.api_capability_catalogue
  WHERE api_version = NEW.api_version
    AND capability_kind = NEW.capability_kind
    AND capability_key = NEW.capability_key
  FOR UPDATE;

  IF v_catalogue_status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION
      'api_g_5_2: capability % (%) is not active in the catalogue',
      NEW.capability_key, NEW.api_version
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_2_enforce_supported_capability_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_2_enforce_supported_capability_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_catalogue_status text;
BEGIN
  IF NEW.lifecycle_status = 'enabled' THEN
    -- Lock the parent catalogue row so support enablement serializes against
    -- concurrent catalogue retirement or deletion attempts.
    SELECT lifecycle_status INTO v_catalogue_status
    FROM public.api_capability_catalogue
    WHERE api_version = NEW.api_version
      AND capability_kind = NEW.capability_kind
      AND capability_key = NEW.capability_key
    FOR UPDATE;

    IF v_catalogue_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION
        'api_g_5_2: capability % (%) is not active in the catalogue',
        NEW.capability_key, NEW.api_version
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.lifecycle_status = 'enabled'
     AND NEW.lifecycle_status = 'disabled' THEN
    IF EXISTS (
      SELECT 1
      FROM public.api_capability_grants g
      WHERE g.api_client_id = OLD.api_client_id
        AND g.api_version = OLD.api_version
        AND g.capability_kind = OLD.capability_kind
        AND g.capability_key = OLD.capability_key
        AND g.lifecycle_status = 'enabled'
    ) THEN
      RAISE EXCEPTION
        'api_g_5_2: cannot disable supported capability % while enabled grants reference it',
        OLD.capability_key
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_3_enforce_project_enablement_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_3_enforce_project_enablement_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_project_workspace_id uuid;
  v_project_organization_id uuid;
  v_workspace_organization_id uuid;
  v_authoritative_tenant_id uuid;
BEGIN
  IF NEW.project_id IS NULL THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: project_id is required'
      USING ERRCODE = '23514';
  END IF;

  SELECT p.workspace_id, p.organization_id
    INTO v_project_workspace_id, v_project_organization_id
    FROM public.projects p
   WHERE p.id = NEW.project_id
   FOR UPDATE;

  IF v_project_workspace_id IS NULL OR v_project_organization_id IS NULL THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: project scope could not be authoritatively derived'
      USING ERRCODE = '23503';
  END IF;

  SELECT w.organization_id
    INTO v_workspace_organization_id
    FROM public.workspaces w
   WHERE w.id = v_project_workspace_id
   FOR UPDATE;

  IF v_workspace_organization_id IS NULL
     OR v_workspace_organization_id <> v_project_organization_id THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: workspace scope could not be authoritatively derived'
      USING ERRCODE = '23514';
  END IF;

  SELECT o.tenant_id
    INTO v_authoritative_tenant_id
    FROM public.organizations o
   WHERE o.id = v_project_organization_id
   FOR UPDATE;

  IF v_authoritative_tenant_id IS NULL THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: tenant scope could not be authoritatively derived'
      USING ERRCODE = '23503';
  END IF;

  IF NEW.workspace_id IS NULL OR NEW.workspace_id <> v_project_workspace_id THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: supplied workspace does not match authoritative project scope'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.organization_id IS NULL OR NEW.organization_id <> v_project_organization_id THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: supplied organization does not match authoritative project scope'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.tenant_id IS NULL OR NEW.tenant_id <> v_authoritative_tenant_id THEN
    RAISE EXCEPTION 'api_g_5_3 scope integrity: supplied tenant does not match authoritative project scope'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_4_enforce_client_oauth_registration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_4_enforce_client_oauth_registration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_locked_client_id uuid;
  v_active_redirect_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.lifecycle_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'api_g_5_4 client registration: an API client may only be created in draft'
        USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
  END IF;

  SELECT c.id
    INTO v_locked_client_id
    FROM public.api_clients c
   WHERE c.id = OLD.id
   FOR UPDATE;

  IF v_locked_client_id IS NULL THEN
    RAISE EXCEPTION 'api_g_5_4 client registration: API client is not registered'
      USING ERRCODE = '23503';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'api_g_5_4 client registration: API client identity is immutable'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.lifecycle_status <> 'draft'
     AND NEW.lifecycle_status = 'draft' THEN
    RAISE EXCEPTION 'api_g_5_4 client registration: an API client cannot return to draft'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.lifecycle_status <> 'draft'
     AND NEW.oauth_client_id IS DISTINCT FROM OLD.oauth_client_id THEN
    RAISE EXCEPTION 'api_g_5_4 client registration: technical OAuth client identifier is immutable after draft'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.lifecycle_status = 'active' THEN
    IF NEW.oauth_client_id IS NULL
       OR length(btrim(NEW.oauth_client_id)) = 0 THEN
      RAISE EXCEPTION 'api_g_5_4 client registration: an active API client requires a technical OAuth client identifier'
        USING ERRCODE = '23514';
    END IF;

    SELECT r.id
      INTO v_active_redirect_id
      FROM public.api_client_oauth_redirect_uris r
     WHERE r.api_client_id = NEW.id
       AND r.lifecycle_status = 'active'
     LIMIT 1
     FOR UPDATE;

    IF v_active_redirect_id IS NULL THEN
      RAISE EXCEPTION 'api_g_5_4 client registration: an active API client requires an active redirect record'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_4_enforce_oauth_redirect_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_4_enforce_oauth_redirect_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_client_id uuid;
  v_client_oauth_client_id text;
  v_client_lifecycle text;
  v_other_active_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: physical deletion is prohibited'
      USING ERRCODE = '42501';
  END IF;

  SELECT c.id, c.oauth_client_id, c.lifecycle_status
    INTO v_client_id, v_client_oauth_client_id, v_client_lifecycle
    FROM public.api_clients c
   WHERE c.id = NEW.api_client_id
   FOR UPDATE;

  IF v_client_id IS NULL THEN
    RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: parent API client is not registered'
      USING ERRCODE = '23503';
  END IF;

  IF NEW.lifecycle_status = 'active'
     AND (v_client_oauth_client_id IS NULL
          OR length(btrim(v_client_oauth_client_id)) = 0) THEN
    RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: active redirect metadata requires a linked technical OAuth client identifier'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Irreversible lifecycle progression:
    -- draft -> draft|active|retired, active -> active|retired, retired -> retired.
    IF OLD.lifecycle_status = 'active'
       AND NEW.lifecycle_status NOT IN ('active','retired') THEN
      RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: an active redirect cannot return to draft'
        USING ERRCODE = '23514';
    END IF;

    IF OLD.lifecycle_status = 'retired'
       AND NEW.lifecycle_status <> 'retired' THEN
      RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: a retired redirect cannot be reinstated'
        USING ERRCODE = '23514';
    END IF;

    -- Identity and history are permanently frozen once the row leaves draft.
    IF OLD.lifecycle_status IN ('active','retired') THEN
      IF NEW.api_client_id IS DISTINCT FROM OLD.api_client_id
         OR NEW.redirect_uri IS DISTINCT FROM OLD.redirect_uri THEN
        RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: redirect identity is immutable after draft'
          USING ERRCODE = '23514';
      END IF;

      IF NEW.verified_at IS DISTINCT FROM OLD.verified_at THEN
        RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: historical verification timestamp is immutable'
          USING ERRCODE = '23514';
      END IF;
    END IF;

    IF OLD.lifecycle_status = 'retired'
       AND NEW.retired_at IS DISTINCT FROM OLD.retired_at THEN
      RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: historical retirement timestamp is immutable'
        USING ERRCODE = '23514';
    END IF;

    IF OLD.lifecycle_status = 'active'
       AND NEW.lifecycle_status <> 'active'
       AND v_client_lifecycle = 'active' THEN
      SELECT r.id
        INTO v_other_active_id
        FROM public.api_client_oauth_redirect_uris r
       WHERE r.api_client_id = OLD.api_client_id
         AND r.id <> OLD.id
         AND r.lifecycle_status = 'active'
       LIMIT 1
       FOR UPDATE;

      IF v_other_active_id IS NULL THEN
        RAISE EXCEPTION 'api_g_5_4 redirect lifecycle: an active API client must retain at least one active redirect record'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_5_enforce_policy_version_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_enforce_policy_version_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_parent_lifecycle text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'api client policy versions cannot be deleted (API-G.5.5B)'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.lifecycle_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'a policy version may only be created as draft'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.effective_at IS NOT NULL OR NEW.retired_at IS NOT NULL THEN
      RAISE EXCEPTION 'a draft policy version cannot carry lifecycle timestamps'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE path -----------------------------------------------------------

  -- Permanent identity.
  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'policy version identity is immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.api_client_id IS DISTINCT FROM OLD.api_client_id THEN
    RAISE EXCEPTION 'policy version parent identity is immutable'
      USING ERRCODE = '23514';
  END IF;

  -- Per-client serialization for direct service-role writes as well.
  SELECT c.lifecycle_status
    INTO v_parent_lifecycle
    FROM public.api_clients c
   WHERE c.id = OLD.api_client_id
   FOR UPDATE;

  IF OLD.lifecycle_status NOT IN ('draft','active','retired')
     OR NEW.lifecycle_status NOT IN ('draft','active','retired') THEN
    RAISE EXCEPTION 'unknown policy version lifecycle status' USING ERRCODE = '23514';
  END IF;

  -- Exact permitted progression.
  IF NOT (
       (OLD.lifecycle_status = 'draft'   AND NEW.lifecycle_status IN ('draft','active','retired'))
    OR (OLD.lifecycle_status = 'active'  AND NEW.lifecycle_status IN ('active','retired'))
    OR (OLD.lifecycle_status = 'retired' AND NEW.lifecycle_status = 'retired')
  ) THEN
    RAISE EXCEPTION 'policy version lifecycle transition is not permitted'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.lifecycle_status = 'retired' THEN
    RAISE EXCEPTION 'a retired policy version is immutable' USING ERRCODE = '23514';
  END IF;

  IF OLD.lifecycle_status = 'draft' AND NEW.lifecycle_status = 'draft' THEN
    -- Draft metadata may change freely; lifecycle timestamps must stay NULL.
    IF NEW.effective_at IS NOT NULL OR NEW.retired_at IS NOT NULL THEN
      RAISE EXCEPTION 'a draft policy version cannot carry lifecycle timestamps'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.lifecycle_status = 'draft' AND NEW.lifecycle_status IN ('active','retired') THEN
    -- Metadata is finalized before transition.
    IF NEW.version IS DISTINCT FROM OLD.version
       OR NEW.policy_uri IS DISTINCT FROM OLD.policy_uri
       OR NEW.policy_digest IS DISTINCT FROM OLD.policy_digest THEN
      RAISE EXCEPTION 'policy version metadata cannot change during a lifecycle transition'
        USING ERRCODE = '23514';
    END IF;

    IF NEW.lifecycle_status = 'active' THEN
      IF NEW.effective_at IS NULL OR NEW.retired_at IS NOT NULL THEN
        RAISE EXCEPTION 'activation must set an effective timestamp and no retirement timestamp'
          USING ERRCODE = '23514';
      END IF;
    ELSE
      IF NEW.effective_at IS NOT NULL OR NEW.retired_at IS NULL THEN
        RAISE EXCEPTION 'retiring a draft must set only a retirement timestamp'
          USING ERRCODE = '23514';
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  -- OLD is active from here on: metadata and effective_at are frozen.
  IF NEW.version IS DISTINCT FROM OLD.version
     OR NEW.policy_uri IS DISTINCT FROM OLD.policy_uri
     OR NEW.policy_digest IS DISTINCT FROM OLD.policy_digest THEN
    RAISE EXCEPTION 'an active policy version is immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.effective_at IS DISTINCT FROM OLD.effective_at THEN
    RAISE EXCEPTION 'the historical effective timestamp is immutable'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.lifecycle_status = 'active' THEN
    IF NEW.retired_at IS NOT NULL THEN
      RAISE EXCEPTION 'an active policy version cannot carry a retirement timestamp'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  -- active -> retired
  IF OLD.retired_at IS NOT NULL OR NEW.retired_at IS NULL THEN
    RAISE EXCEPTION 'retirement must set the retirement timestamp exactly once'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: api_g_5_5_platform_create_client(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_create_client(_client_key text, _display_name text, _description text DEFAULT NULL::text, _oauth_client_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_display_name text;
  v_description text;
  v_client_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  IF _client_key IS NULL
     OR _client_key <> btrim(_client_key)
     OR _client_key <> lower(_client_key)
     OR length(_client_key) = 0 THEN
    RAISE EXCEPTION 'invalid client key' USING ERRCODE = '22023';
  END IF;

  v_display_name := btrim(coalesce(_display_name, ''));
  IF length(v_display_name) = 0 THEN
    RAISE EXCEPTION 'invalid display name' USING ERRCODE = '22023';
  END IF;

  v_description := nullif(btrim(coalesce(_description, '')), '');

  IF _oauth_client_id IS NOT NULL THEN
    IF _oauth_client_id <> btrim(_oauth_client_id)
       OR _oauth_client_id <> lower(_oauth_client_id)
       OR length(_oauth_client_id) = 0 THEN
      RAISE EXCEPTION 'invalid oauth client identifier' USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.api_clients (
    client_key, display_name, description, oauth_client_id,
    lifecycle_status, created_by, updated_by
  )
  VALUES (
    _client_key, v_display_name, v_description, _oauth_client_id,
    'draft', v_actor, v_actor
  )
  RETURNING id INTO v_client_id;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, v_client_id, 'api_client', v_client_id,
    'client_create', NULL, 'draft'
  );

  RETURN v_client_id;
END;
$$;


--
-- Name: api_g_5_5_platform_create_oauth_redirect(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_create_oauth_redirect(_api_client_id uuid, _redirect_uri text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_client_lifecycle text;
  v_redirect_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  -- Parent-client-first lock ordering.
  SELECT c.lifecycle_status
    INTO v_client_lifecycle
    FROM public.api_clients c
   WHERE c.id = _api_client_id
   FOR UPDATE;

  IF v_client_lifecycle IS NULL THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;
  IF v_client_lifecycle = 'retired' THEN
    RAISE EXCEPTION 'a retired api client cannot receive new redirect metadata'
      USING ERRCODE = '23514';
  END IF;

  -- The exact supplied value is preserved; the accepted API-G.5.4
  -- structural constraints remain the sole validators.
  INSERT INTO public.api_client_oauth_redirect_uris (
    api_client_id, redirect_uri, lifecycle_status,
    verified_at, retired_at, created_by, updated_by
  )
  VALUES (
    _api_client_id, _redirect_uri, 'draft',
    NULL, NULL, v_actor, v_actor
  )
  RETURNING id INTO v_redirect_id;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, _api_client_id, 'oauth_redirect', v_redirect_id,
    'redirect_create', NULL, 'draft'
  );

  RETURN v_redirect_id;
END;
$$;


--
-- Name: api_g_5_5_platform_create_policy_version(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_create_policy_version(_api_client_id uuid, _version text, _policy_uri text, _policy_document text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_client_lifecycle text;
  v_digest text;
  v_policy_version_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  -- Parent-client-first lock ordering.
  SELECT c.lifecycle_status
    INTO v_client_lifecycle
    FROM public.api_clients c
   WHERE c.id = _api_client_id
   FOR UPDATE;

  IF v_client_lifecycle IS NULL THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;
  IF v_client_lifecycle = 'retired' THEN
    RAISE EXCEPTION 'a retired api client cannot receive new policy metadata'
      USING ERRCODE = '23514';
  END IF;

  IF _version IS NULL
     OR _version <> btrim(_version)
     OR length(_version) < 1
     OR length(_version) > 64
     OR _version !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$' THEN
    RAISE EXCEPTION 'invalid policy version label' USING ERRCODE = '22023';
  END IF;

  IF _policy_uri IS NULL
     OR _policy_uri <> btrim(_policy_uri)
     OR octet_length(_policy_uri) < 1
     OR octet_length(_policy_uri) > 2048
     OR _policy_uri !~ '^https://'
     OR _policy_uri ~ '[[:space:][:cntrl:]]' THEN
    RAISE EXCEPTION 'invalid policy uri' USING ERRCODE = '22023';
  END IF;

  IF _policy_document IS NULL
     OR length(btrim(_policy_document)) = 0
     OR octet_length(_policy_document) > 1048576 THEN
    RAISE EXCEPTION 'invalid policy document' USING ERRCODE = '22023';
  END IF;

  -- Server-calculated digest over the exact transient UTF-8 bytes.
  v_digest := encode(
    extensions.digest(convert_to(_policy_document, 'UTF8'), 'sha256'),
    'hex'
  );

  INSERT INTO public.api_client_policy_versions (
    api_client_id, version, policy_uri, policy_digest,
    lifecycle_status, effective_at, retired_at, created_by, updated_by
  )
  VALUES (
    _api_client_id, _version, _policy_uri, v_digest,
    'draft', NULL, NULL, v_actor, v_actor
  )
  RETURNING id INTO v_policy_version_id;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, _api_client_id, 'policy_version', v_policy_version_id,
    'policy_create', NULL, 'draft'
  );

  RETURN v_policy_version_id;
END;
$_$;


--
-- Name: api_g_5_5_platform_transition_client(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_transition_client(_api_client_id uuid, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_previous text;
  v_target text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  v_target := _target_lifecycle_status;
  IF v_target IS NULL
     OR v_target NOT IN ('draft','active','suspended','retired') THEN
    RAISE EXCEPTION 'unknown lifecycle status' USING ERRCODE = '22023';
  END IF;

  SELECT c.lifecycle_status
    INTO v_previous
    FROM public.api_clients c
   WHERE c.id = _api_client_id
   FOR UPDATE;

  IF v_previous IS NULL THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;

  IF v_previous = v_target THEN
    RAISE EXCEPTION 'lifecycle transition is not permitted' USING ERRCODE = '23514';
  END IF;

  -- Exact permitted client transition graph.
  IF NOT (
       (v_previous = 'draft'     AND v_target IN ('active','retired'))
    OR (v_previous = 'active'    AND v_target IN ('suspended','retired'))
    OR (v_previous = 'suspended' AND v_target IN ('active','retired'))
  ) THEN
    RAISE EXCEPTION 'lifecycle transition is not permitted' USING ERRCODE = '23514';
  END IF;

  -- Ordinary UPDATE: the accepted API-G.5.4/C1 trigger stays authoritative.
  UPDATE public.api_clients
     SET lifecycle_status = v_target,
         updated_by = v_actor
   WHERE id = _api_client_id;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, _api_client_id, 'api_client', _api_client_id,
    'client_transition', v_previous, v_target
  );

  RETURN _api_client_id;
END;
$$;


--
-- Name: api_g_5_5_platform_transition_oauth_redirect(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_transition_oauth_redirect(_redirect_id uuid, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_candidate_client_id uuid;
  v_locked_client_id uuid;
  v_client_lifecycle text;
  v_previous text;
  v_target text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  v_target := _target_lifecycle_status;
  IF v_target IS NULL
     OR v_target NOT IN ('draft','active','retired') THEN
    RAISE EXCEPTION 'unknown lifecycle status' USING ERRCODE = '22023';
  END IF;

  -- Candidate parent discovery (unlocked).
  SELECT r.api_client_id
    INTO v_candidate_client_id
    FROM public.api_client_oauth_redirect_uris r
   WHERE r.id = _redirect_id;

  IF v_candidate_client_id IS NULL THEN
    RAISE EXCEPTION 'redirect metadata is not available' USING ERRCODE = '42501';
  END IF;

  -- Parent-client-first lock ordering.
  SELECT c.lifecycle_status
    INTO v_client_lifecycle
    FROM public.api_clients c
   WHERE c.id = v_candidate_client_id
   FOR UPDATE;

  -- Then the redirect row; read its authoritative parent and lifecycle.
  SELECT r.api_client_id, r.lifecycle_status
    INTO v_locked_client_id, v_previous
    FROM public.api_client_oauth_redirect_uris r
   WHERE r.id = _redirect_id
   FOR UPDATE;

  IF v_previous IS NULL THEN
    RAISE EXCEPTION 'redirect metadata is not available' USING ERRCODE = '42501';
  END IF;

  -- Authoritative-parent revalidation. Abort before mutation and before audit.
  IF v_locked_client_id IS DISTINCT FROM v_candidate_client_id THEN
    RAISE EXCEPTION 'redirect metadata changed concurrently; retry the command'
      USING ERRCODE = '40001';
  END IF;

  IF v_previous = v_target THEN
    RAISE EXCEPTION 'lifecycle transition is not permitted' USING ERRCODE = '23514';
  END IF;

  -- Exact permitted redirect transition graph.
  IF NOT (
       (v_previous = 'draft'  AND v_target IN ('active','retired'))
    OR (v_previous = 'active' AND v_target = 'retired')
  ) THEN
    RAISE EXCEPTION 'lifecycle transition is not permitted' USING ERRCODE = '23514';
  END IF;

  -- Ordinary UPDATE statements: the accepted API-G.5.4/C1 redirect trigger
  -- (including last-active-redirect protection) stays authoritative.
  IF v_target = 'active' THEN
    UPDATE public.api_client_oauth_redirect_uris
       SET lifecycle_status = 'active',
           verified_at = now(),
           retired_at = NULL,
           updated_by = v_actor
     WHERE id = _redirect_id;
  ELSE
    UPDATE public.api_client_oauth_redirect_uris
       SET lifecycle_status = 'retired',
           retired_at = now(),
           updated_by = v_actor
     WHERE id = _redirect_id;
  END IF;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, v_locked_client_id, 'oauth_redirect', _redirect_id,
    'redirect_transition', v_previous, v_target
  );

  RETURN _redirect_id;
END;
$$;


--
-- Name: api_g_5_5_platform_transition_policy_version(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_transition_policy_version(_policy_version_id uuid, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_candidate_client_id uuid;
  v_locked_client_id uuid;
  v_client_lifecycle text;
  v_previous text;
  v_target text;
  v_superseded_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  v_target := _target_lifecycle_status;
  IF v_target IS NULL OR v_target NOT IN ('draft','active','retired') THEN
    RAISE EXCEPTION 'unknown lifecycle status' USING ERRCODE = '22023';
  END IF;

  SELECT p.api_client_id
    INTO v_candidate_client_id
    FROM public.api_client_policy_versions p
   WHERE p.id = _policy_version_id;

  IF v_candidate_client_id IS NULL THEN
    RAISE EXCEPTION 'policy metadata is not available' USING ERRCODE = '42501';
  END IF;

  -- Parent-client-first lock ordering.
  SELECT c.lifecycle_status
    INTO v_client_lifecycle
    FROM public.api_clients c
   WHERE c.id = v_candidate_client_id
   FOR UPDATE;

  -- Then the policy row; re-read its authoritative parent and lifecycle.
  SELECT p.api_client_id, p.lifecycle_status
    INTO v_locked_client_id, v_previous
    FROM public.api_client_policy_versions p
   WHERE p.id = _policy_version_id
   FOR UPDATE;

  IF v_previous IS NULL THEN
    RAISE EXCEPTION 'policy metadata is not available' USING ERRCODE = '42501';
  END IF;

  -- Authoritative-parent revalidation. Abort before mutation and before audit.
  IF v_locked_client_id IS DISTINCT FROM v_candidate_client_id THEN
    RAISE EXCEPTION 'policy metadata changed concurrently; retry the command'
      USING ERRCODE = '40001';
  END IF;

  IF v_previous = v_target THEN
    RAISE EXCEPTION 'lifecycle transition is not permitted' USING ERRCODE = '23514';
  END IF;

  -- Exact permitted policy transition graph.
  IF NOT (
       (v_previous = 'draft'  AND v_target IN ('active','retired'))
    OR (v_previous = 'active' AND v_target = 'retired')
  ) THEN
    RAISE EXCEPTION 'lifecycle transition is not permitted' USING ERRCODE = '23514';
  END IF;

  IF v_target = 'active' THEN
    IF v_client_lifecycle = 'retired' THEN
      RAISE EXCEPTION 'a retired api client cannot activate a policy version'
        USING ERRCODE = '23514';
    END IF;

    -- Supersede any different currently active policy for the same client.
    SELECT p.id
      INTO v_superseded_id
      FROM public.api_client_policy_versions p
     WHERE p.api_client_id = v_locked_client_id
       AND p.lifecycle_status = 'active'
       AND p.id <> _policy_version_id
     FOR UPDATE;

    IF v_superseded_id IS NOT NULL THEN
      -- Preserve the historical effective_at; set retired_at exactly once.
      UPDATE public.api_client_policy_versions
         SET lifecycle_status = 'retired',
             retired_at = now(),
             updated_by = v_actor
       WHERE id = v_superseded_id;

      INSERT INTO public.api_platform_admin_audit_events (
        actor_user_id, api_client_id, target_type, target_id,
        action, previous_lifecycle_status, resulting_lifecycle_status
      )
      VALUES (
        v_actor, v_locked_client_id, 'policy_version', v_superseded_id,
        'policy_transition', 'active', 'retired'
      );
    END IF;

    UPDATE public.api_client_policy_versions
       SET lifecycle_status = 'active',
           effective_at = now(),
           retired_at = NULL,
           updated_by = v_actor
     WHERE id = _policy_version_id;
  ELSE
    -- draft -> retired keeps effective_at NULL; active -> retired preserves it.
    UPDATE public.api_client_policy_versions
       SET lifecycle_status = 'retired',
           retired_at = now(),
           updated_by = v_actor
     WHERE id = _policy_version_id;
  END IF;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, v_locked_client_id, 'policy_version', _policy_version_id,
    'policy_transition', v_previous, v_target
  );

  RETURN _policy_version_id;
END;
$$;


--
-- Name: api_g_5_5_platform_update_draft_client(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_platform_update_draft_client(_api_client_id uuid, _display_name text, _description text DEFAULT NULL::text, _oauth_client_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_display_name text;
  v_description text;
  v_lifecycle text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT c.lifecycle_status
    INTO v_lifecycle
    FROM public.api_clients c
   WHERE c.id = _api_client_id
   FOR UPDATE;

  IF v_lifecycle IS NULL THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;
  IF v_lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'api client metadata may only be updated while draft'
      USING ERRCODE = '23514';
  END IF;

  v_display_name := btrim(coalesce(_display_name, ''));
  IF length(v_display_name) = 0 THEN
    RAISE EXCEPTION 'invalid display name' USING ERRCODE = '22023';
  END IF;

  v_description := nullif(btrim(coalesce(_description, '')), '');

  IF _oauth_client_id IS NOT NULL THEN
    IF _oauth_client_id <> btrim(_oauth_client_id)
       OR _oauth_client_id <> lower(_oauth_client_id)
       OR length(_oauth_client_id) = 0 THEN
      RAISE EXCEPTION 'invalid oauth client identifier' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.api_clients
     SET display_name = v_display_name,
         description = v_description,
         oauth_client_id = _oauth_client_id,
         updated_by = v_actor
   WHERE id = _api_client_id;

  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, _api_client_id, 'api_client', _api_client_id,
    'client_update', 'draft', 'draft'
  );

  RETURN _api_client_id;
END;
$$;


