-- Name: api_g_5_5_protect_platform_admin_audit_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_5_protect_platform_admin_audit_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION 'api_platform_admin_audit_events is append-only (API-G.5.5A): % denied', TG_OP
    USING ERRCODE = '42501';
END;
$$;


--
-- Name: api_g_5_6_platform_get_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_6_platform_get_client(_api_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_client jsonb;
  v_redirects jsonb;
  v_policies jsonb;
  v_capabilities jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  IF _api_client_id IS NULL THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'id', c.id,
    'client_key', c.client_key,
    'display_name', c.display_name,
    'description', c.description,
    'oauth_client_id', c.oauth_client_id,
    'lifecycle_status', c.lifecycle_status,
    'created_at', c.created_at,
    'updated_at', c.updated_at
  )
  INTO v_client
  FROM public.api_clients c
  WHERE c.id = _api_client_id;

  IF v_client IS NULL THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(jsonb_agg(item ORDER BY ord_created_at ASC, ord_id ASC), '[]'::jsonb)
  INTO v_redirects
  FROM (
    SELECT
      r.created_at AS ord_created_at,
      r.id AS ord_id,
      jsonb_build_object(
        'id', r.id,
        'redirect_uri', r.redirect_uri,
        'lifecycle_status', r.lifecycle_status,
        'verified_at', r.verified_at,
        'retired_at', r.retired_at,
        'created_at', r.created_at,
        'updated_at', r.updated_at
      ) AS item
    FROM public.api_client_oauth_redirect_uris r
    WHERE r.api_client_id = _api_client_id
  ) redirect_rows;

  SELECT coalesce(jsonb_agg(item ORDER BY ord_rank ASC, ord_created_at DESC, ord_id ASC), '[]'::jsonb)
  INTO v_policies
  FROM (
    SELECT
      CASE p.lifecycle_status
        WHEN 'active' THEN 0
        WHEN 'draft' THEN 1
        ELSE 2
      END AS ord_rank,
      p.created_at AS ord_created_at,
      p.id AS ord_id,
      jsonb_build_object(
        'id', p.id,
        'version', p.version,
        'policy_uri', p.policy_uri,
        'policy_digest', p.policy_digest,
        'lifecycle_status', p.lifecycle_status,
        'effective_at', p.effective_at,
        'retired_at', p.retired_at,
        'created_at', p.created_at,
        'updated_at', p.updated_at
      ) AS item
    FROM public.api_client_policy_versions p
    WHERE p.api_client_id = _api_client_id
  ) policy_rows;

  SELECT coalesce(
    jsonb_agg(item ORDER BY ord_api_version ASC, ord_display_name ASC, ord_capability_key ASC),
    '[]'::jsonb
  )
  INTO v_capabilities
  FROM (
    SELECT
      cat.api_version AS ord_api_version,
      cat.display_name AS ord_display_name,
      cat.capability_key AS ord_capability_key,
      jsonb_build_object(
        'supported_capability_id', s.id,
        'api_version', cat.api_version,
        'capability_kind', cat.capability_kind,
        'capability_key', cat.capability_key,
        'display_name', cat.display_name,
        'description', cat.description,
        'route_id', cat.route_id,
        'http_method', cat.http_method,
        'route_path', cat.route_path,
        'scope_level', cat.scope_level,
        'catalogue_lifecycle_status', cat.lifecycle_status,
        'administrator_assignable', cat.administrator_assignable,
        'support_lifecycle_status', s.lifecycle_status,
        'enabled_at', s.enabled_at,
        'disabled_at', s.disabled_at,
        'created_at', s.created_at,
        'updated_at', s.updated_at
      ) AS item
    FROM public.api_capability_catalogue cat
    LEFT JOIN public.api_client_supported_capabilities s
      ON s.api_client_id = _api_client_id
     AND s.api_version = cat.api_version
     AND s.capability_kind = cat.capability_kind
     AND s.capability_key = cat.capability_key
    WHERE s.id IS NOT NULL
       OR (cat.lifecycle_status = 'active' AND cat.administrator_assignable)
  ) capability_rows;

  RETURN jsonb_build_object(
    'client', v_client,
    'redirects', v_redirects,
    'policy_versions', v_policies,
    'supported_capabilities', v_capabilities
  );
END;
$$;


--
-- Name: api_g_5_6_platform_list_assignable_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_6_platform_list_assignable_capabilities() RETURNS TABLE(api_version text, capability_kind text, capability_key text, route_id text, http_method text, route_path text, scope_level text, display_name text, description text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    cat.api_version,
    cat.capability_kind,
    cat.capability_key,
    cat.route_id,
    cat.http_method,
    cat.route_path,
    cat.scope_level,
    cat.display_name,
    cat.description
  FROM public.api_capability_catalogue cat
  WHERE cat.lifecycle_status = 'active'
    AND cat.administrator_assignable = true
  ORDER BY cat.api_version ASC, cat.display_name ASC, cat.capability_key ASC;
END;
$$;


--
-- Name: api_g_5_6_platform_list_clients(boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_6_platform_list_clients(_include_retired boolean DEFAULT false, _limit integer DEFAULT 50, _offset integer DEFAULT 0) RETURNS TABLE(id uuid, client_key text, display_name text, description text, oauth_client_id text, lifecycle_status text, created_at timestamp with time zone, updated_at timestamp with time zone, redirect_count bigint, active_redirect_count bigint, policy_version_count bigint, active_policy_version text, enabled_supported_capability_count bigint, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_total bigint;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  IF _include_retired IS NULL THEN
    RAISE EXCEPTION 'invalid pagination request' USING ERRCODE = '22023';
  END IF;
  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'invalid pagination request' USING ERRCODE = '22023';
  END IF;
  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'invalid pagination request' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_total
  FROM public.api_clients c
  WHERE _include_retired OR c.lifecycle_status <> 'retired';

  RETURN QUERY
  SELECT
    c.id,
    c.client_key,
    c.display_name,
    c.description,
    c.oauth_client_id,
    c.lifecycle_status,
    c.created_at,
    c.updated_at,
    (SELECT count(*) FROM public.api_client_oauth_redirect_uris r
      WHERE r.api_client_id = c.id)::bigint,
    (SELECT count(*) FROM public.api_client_oauth_redirect_uris r
      WHERE r.api_client_id = c.id AND r.lifecycle_status = 'active')::bigint,
    (SELECT count(*) FROM public.api_client_policy_versions p
      WHERE p.api_client_id = c.id)::bigint,
    (SELECT p.version FROM public.api_client_policy_versions p
      WHERE p.api_client_id = c.id AND p.lifecycle_status = 'active'
      ORDER BY p.created_at DESC, p.id ASC
      LIMIT 1),
    (SELECT count(*) FROM public.api_client_supported_capabilities s
      WHERE s.api_client_id = c.id AND s.lifecycle_status = 'enabled')::bigint,
    v_total
  FROM public.api_clients c
  WHERE _include_retired OR c.lifecycle_status <> 'retired'
  ORDER BY c.updated_at DESC, c.id ASC
  LIMIT _limit
  OFFSET _offset;
END;
$$;


--
-- Name: api_g_5_6_platform_transition_supported_capability(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_6_platform_transition_supported_capability(_api_client_id uuid, _api_version text, _capability_kind text, _capability_key text, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_client_lifecycle text;
  v_cat_lifecycle text;
  v_cat_assignable boolean;
  v_supported_id uuid;
  v_previous text;
  v_result_id uuid;
BEGIN
  -- 1. Actor derivation and authorization. Unchanged.
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_platform_super_admin(v_actor) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  -- 2. Exact target validation. No normalization of catalogue identity.
  IF _target_lifecycle_status IS NULL
     OR _target_lifecycle_status NOT IN ('enabled','disabled') THEN
    RAISE EXCEPTION 'invalid supported capability target status' USING ERRCODE = '22023';
  END IF;
  IF _api_client_id IS NULL
     OR _api_version IS NULL
     OR _capability_kind IS NULL
     OR _capability_key IS NULL THEN
    RAISE EXCEPTION 'invalid supported capability request' USING ERRCODE = '22023';
  END IF;

  -- 3. Lock the authoritative parent client row first.
  SELECT c.lifecycle_status
    INTO v_client_lifecycle
    FROM public.api_clients c
   WHERE c.id = _api_client_id
   FOR UPDATE;

  -- 4. Safe non-enumerating client availability check.
  IF v_client_lifecycle IS NULL OR v_client_lifecycle = 'retired' THEN
    RAISE EXCEPTION 'api client is not available' USING ERRCODE = '42501';
  END IF;

  -- 5. Lock any existing exact supported-capability row second. This ordering
  -- aligns with api_g_5_2_enforce_grant_capability_lifecycle(), which locks the
  -- supported-capability row before the catalogue row. When no supported row
  -- exists this lookup simply returns no row and the catalogue row is locked
  -- afterwards, before insertion.
  SELECT s.id, s.lifecycle_status
    INTO v_supported_id, v_previous
    FROM public.api_client_supported_capabilities s
   WHERE s.api_client_id = _api_client_id
     AND s.api_version = _api_version
     AND s.capability_kind = _capability_kind
     AND s.capability_key = _capability_key
   FOR UPDATE;

  -- 6. Lock the exact catalogue row third.
  SELECT cat.lifecycle_status, cat.administrator_assignable
    INTO v_cat_lifecycle, v_cat_assignable
    FROM public.api_capability_catalogue cat
   WHERE cat.api_version = _api_version
     AND cat.capability_kind = _capability_kind
     AND cat.capability_key = _capability_key
   FOR UPDATE;

  -- 7. Only active administrator-assignable catalogue rows are usable.
  IF v_cat_lifecycle IS NULL
     OR v_cat_lifecycle <> 'active'
     OR v_cat_assignable IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'capability is not administrator assignable' USING ERRCODE = '42501';
  END IF;

  -- 8-11. Apply only the permitted transition graph. Unchanged.
  IF v_supported_id IS NULL THEN
    IF _target_lifecycle_status <> 'enabled' THEN
      RAISE EXCEPTION 'supported capability transition is not permitted' USING ERRCODE = '23514';
    END IF;

    INSERT INTO public.api_client_supported_capabilities (
      api_client_id, api_version, capability_kind, capability_key,
      lifecycle_status, reason, enabled_at, disabled_at,
      created_by, updated_by
    )
    VALUES (
      _api_client_id, _api_version, _capability_kind, _capability_key,
      'enabled', NULL, now(), NULL,
      v_actor, v_actor
    )
    RETURNING id INTO v_result_id;

    v_previous := NULL;

  ELSIF v_previous = 'disabled' AND _target_lifecycle_status = 'enabled' THEN
    UPDATE public.api_client_supported_capabilities s
       SET lifecycle_status = 'enabled',
           enabled_at = now(),
           disabled_at = NULL,
           reason = NULL,
           updated_by = v_actor
     WHERE s.id = v_supported_id
    RETURNING s.id INTO v_result_id;

  ELSIF v_previous = 'enabled' AND _target_lifecycle_status = 'disabled' THEN
    UPDATE public.api_client_supported_capabilities s
       SET lifecycle_status = 'disabled',
           disabled_at = now(),
           reason = NULL,
           updated_by = v_actor
     WHERE s.id = v_supported_id
    RETURNING s.id INTO v_result_id;

  ELSE
    RAISE EXCEPTION 'supported capability transition is not permitted' USING ERRCODE = '23514';
  END IF;

  -- 13. Atomic append-only audit event with structural fields only.
  INSERT INTO public.api_platform_admin_audit_events (
    actor_user_id, api_client_id, target_type, target_id,
    action, previous_lifecycle_status, resulting_lifecycle_status
  )
  VALUES (
    v_actor, _api_client_id, 'supported_capability', v_result_id,
    'supported_capability_transition', v_previous, _target_lifecycle_status
  );

  -- 14. Return only the supported-capability identifier.
  RETURN v_result_id;
END;
$$;


--
-- Name: api_g_5_7_admin_list_organization_client_capabilities(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_list_organization_client_capabilities(_organization_id uuid, _api_client_id uuid, _limit integer, _offset integer) RETURNS TABLE(api_version text, capability_kind text, capability_key text, display_name text, description text, scope_level text, catalogue_lifecycle_status text, administrator_assignable boolean, supported_capability_id uuid, supported_capability_status text, grant_id uuid, grant_status text, grant_enabled_at timestamp with time zone, grant_disabled_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_authorized boolean := false;
  v_client_relevant boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 200 THEN
    RAISE EXCEPTION 'invalid_limit' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'invalid_offset' USING ERRCODE = '22023';
  END IF;

  -- Tenant scope is derived server-side from the Organization only.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NOT NULL THEN
    v_authorized := public.is_tenant_admin(v_tenant_id, v_actor)
      OR public.is_org_admin(v_actor, _organization_id);
  END IF;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Client relevance: active client, or retained configuration in THIS Organization.
  SELECT EXISTS (
    SELECT 1 FROM public.api_clients c
     WHERE c.id = _api_client_id
       AND c.lifecycle_status = 'active'
  )
  OR EXISTS (
    SELECT 1 FROM public.api_organization_client_enablements e
     WHERE e.api_client_id = _api_client_id
       AND e.organization_id = _organization_id
       AND e.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_workspace_client_enablements we
     JOIN public.workspaces w2
       ON w2.id = we.workspace_id
      AND w2.organization_id = _organization_id
     WHERE we.api_client_id = _api_client_id
       AND we.organization_id = _organization_id
       AND we.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_project_client_enablements pe
     JOIN public.projects pj
       ON pj.id = pe.project_id
      AND pj.organization_id = _organization_id
     WHERE pe.api_client_id = _api_client_id
       AND pe.organization_id = _organization_id
       AND pe.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_capability_grants g
     WHERE g.api_client_id = _api_client_id
       AND g.organization_id = _organization_id
       AND g.tenant_id = v_tenant_id
  )
  INTO v_client_relevant;

  IF NOT v_client_relevant THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH supported AS (
    SELECT s.id AS supported_capability_id,
           s.api_version,
           s.capability_kind,
           s.capability_key,
           s.lifecycle_status AS supported_capability_status
    FROM public.api_client_supported_capabilities s
    WHERE s.api_client_id = _api_client_id
  ),
  joined AS (
    SELECT sup.supported_capability_id,
           cat.api_version,
           cat.capability_kind,
           cat.capability_key,
           cat.display_name,
           cat.description,
           cat.scope_level,
           cat.lifecycle_status AS catalogue_lifecycle_status,
           cat.administrator_assignable,
           sup.supported_capability_status
    FROM supported sup
    JOIN public.api_capability_catalogue cat
      ON cat.api_version = sup.api_version
     AND cat.capability_kind = sup.capability_kind
     AND cat.capability_key = sup.capability_key
  ),
  projected AS (
    SELECT j.*,
           eg.id AS grant_id,
           eg.lifecycle_status AS grant_status,
           eg.enabled_at AS grant_enabled_at,
           eg.disabled_at AS grant_disabled_at
    FROM joined j
    LEFT JOIN public.api_capability_grants eg
      ON eg.tenant_id = v_tenant_id
     AND eg.organization_id = _organization_id
     AND eg.workspace_id IS NULL
     AND eg.api_client_id = _api_client_id
     AND eg.api_version = j.api_version
     AND eg.capability_kind = j.capability_kind
     AND eg.capability_key = j.capability_key
  ),
  eligible AS (
    -- API-N.10A visibility rule: Platform-supported status drives visibility.
    -- Scope level, capability kind, administrator assignability and catalogue
    -- lifecycle no longer restrict DISPLAY. Grantability remains enforced by
    -- public.api_g_5_7_admin_transition_organization_client_capability.
    SELECT p.*
    FROM projected p
    WHERE p.supported_capability_status = 'enabled'
       OR p.grant_id IS NOT NULL
  ),
  counted AS (
    SELECT e.*, count(*) OVER ()::bigint AS total
    FROM eligible e
  )
  SELECT c.api_version,
         c.capability_kind,
         c.capability_key,
         c.display_name,
         c.description,
         c.scope_level,
         c.catalogue_lifecycle_status,
         c.administrator_assignable,
         c.supported_capability_id,
         c.supported_capability_status,
         c.grant_id,
         c.grant_status,
         c.grant_enabled_at,
         c.grant_disabled_at,
         c.total
  FROM counted c
  ORDER BY c.api_version ASC,
           c.capability_kind ASC,
           lower(COALESCE(c.display_name, '')) ASC,
           c.capability_key ASC
  LIMIT _limit OFFSET _offset;
END;
$$;


--
-- Name: api_g_5_7_admin_list_organization_client_workspaces(uuid, uuid, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_list_organization_client_workspaces(_organization_id uuid, _api_client_id uuid, _include_archived boolean, _limit integer, _offset integer) RETURNS TABLE(workspace_id uuid, workspace_name text, workspace_is_archived boolean, workspace_enablement_id uuid, workspace_enablement_status text, workspace_enabled_at timestamp with time zone, workspace_disabled_at timestamp with time zone, enabled_project_count bigint, enabled_capability_grant_count bigint, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_authorized boolean := false;
  v_client_relevant boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _include_archived IS NULL THEN
    RAISE EXCEPTION 'invalid_include_archived' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 200 THEN
    RAISE EXCEPTION 'invalid_limit' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'invalid_offset' USING ERRCODE = '22023';
  END IF;

  -- Tenant scope is derived server-side from the Organization only.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NOT NULL THEN
    v_authorized := public.is_tenant_admin(v_tenant_id, v_actor)
      OR public.is_org_admin(v_actor, _organization_id);
  END IF;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Client relevance: active client, or retained configuration in THIS Organization.
  SELECT EXISTS (
    SELECT 1 FROM public.api_clients c
     WHERE c.id = _api_client_id
       AND c.lifecycle_status = 'active'
  )
  OR EXISTS (
    SELECT 1 FROM public.api_organization_client_enablements e
     WHERE e.api_client_id = _api_client_id
       AND e.organization_id = _organization_id
       AND e.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_workspace_client_enablements we
     JOIN public.workspaces w2
       ON w2.id = we.workspace_id
      AND w2.organization_id = _organization_id
     WHERE we.api_client_id = _api_client_id
       AND we.organization_id = _organization_id
       AND we.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_project_client_enablements pe
     JOIN public.projects pj
       ON pj.id = pe.project_id
      AND pj.organization_id = _organization_id
     WHERE pe.api_client_id = _api_client_id
       AND pe.organization_id = _organization_id
       AND pe.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_capability_grants g
     WHERE g.api_client_id = _api_client_id
       AND g.organization_id = _organization_id
       AND g.tenant_id = v_tenant_id
  )
  INTO v_client_relevant;

  -- Non-relevant or absent client shares the same non-enumerating failure.
  IF NOT v_client_relevant THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH org_ws AS (
    SELECT w.id,
           public.btpm_decrypt(w.name, _organization_id) AS name,
           COALESCE(w.is_archived, false) AS is_archived
    FROM public.workspaces w
    WHERE w.organization_id = _organization_id
  ),
  ws_enable AS (
    SELECT we.id, we.workspace_id, we.lifecycle_status, we.enabled_at, we.disabled_at
    FROM public.api_workspace_client_enablements we
    JOIN public.workspaces w2
      ON w2.id = we.workspace_id
     AND w2.organization_id = _organization_id
    WHERE we.api_client_id = _api_client_id
      AND we.organization_id = _organization_id
      AND we.tenant_id = v_tenant_id
  ),
  proj_counts AS (
    SELECT pe.workspace_id, count(*)::bigint AS c
    FROM public.api_project_client_enablements pe
    JOIN public.projects pj
      ON pj.id = pe.project_id
     AND pj.organization_id = _organization_id
     AND pj.workspace_id = pe.workspace_id
    JOIN public.workspaces w3
      ON w3.id = pe.workspace_id
     AND w3.organization_id = _organization_id
    WHERE pe.api_client_id = _api_client_id
      AND pe.organization_id = _organization_id
      AND pe.tenant_id = v_tenant_id
      AND pe.lifecycle_status = 'enabled'
    GROUP BY pe.workspace_id
  ),
  grant_counts AS (
    SELECT g.workspace_id, count(*)::bigint AS c
    FROM public.api_capability_grants g
    JOIN public.workspaces w4
      ON w4.id = g.workspace_id
     AND w4.organization_id = _organization_id
    WHERE g.api_client_id = _api_client_id
      AND g.organization_id = _organization_id
      AND g.tenant_id = v_tenant_id
      AND g.workspace_id IS NOT NULL
      AND g.lifecycle_status = 'enabled'
    GROUP BY g.workspace_id
  ),
  retained AS (
    SELECT DISTINCT x.workspace_id FROM (
      SELECT we.workspace_id FROM ws_enable we
      UNION ALL
      SELECT pe.workspace_id
        FROM public.api_project_client_enablements pe
        JOIN public.projects pj
          ON pj.id = pe.project_id
         AND pj.organization_id = _organization_id
         AND pj.workspace_id = pe.workspace_id
       WHERE pe.api_client_id = _api_client_id
         AND pe.organization_id = _organization_id
         AND pe.tenant_id = v_tenant_id
      UNION ALL
      SELECT g.workspace_id
        FROM public.api_capability_grants g
       WHERE g.api_client_id = _api_client_id
         AND g.organization_id = _organization_id
         AND g.tenant_id = v_tenant_id
         AND g.workspace_id IS NOT NULL
    ) x
    WHERE x.workspace_id IS NOT NULL
  ),
  eligible AS (
    SELECT ow.id,
           ow.name,
           ow.is_archived,
           we.id AS enablement_id,
           we.lifecycle_status,
           we.enabled_at,
           we.disabled_at,
           COALESCE(pc.c, 0::bigint) AS project_count,
           COALESCE(gc.c, 0::bigint) AS grant_count
    FROM org_ws ow
    LEFT JOIN ws_enable we ON we.workspace_id = ow.id
    LEFT JOIN proj_counts pc ON pc.workspace_id = ow.id
    LEFT JOIN grant_counts gc ON gc.workspace_id = ow.id
    WHERE ow.is_archived = false
       OR _include_archived = true
       OR EXISTS (SELECT 1 FROM retained r WHERE r.workspace_id = ow.id)
  ),
  counted AS (
    SELECT e.*, count(*) OVER ()::bigint AS total
    FROM eligible e
  )
  SELECT c.id,
         c.name,
         c.is_archived,
         c.enablement_id,
         c.lifecycle_status,
         c.enabled_at,
         c.disabled_at,
         c.project_count,
         c.grant_count,
         c.total
  FROM counted c
  ORDER BY lower(COALESCE(c.name, '')) ASC, c.id ASC
  LIMIT _limit OFFSET _offset;
END;
$$;


--
-- Name: api_g_5_7_admin_list_organization_clients(uuid, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_list_organization_clients(_organization_id uuid, _include_retired boolean, _limit integer, _offset integer) RETURNS TABLE(api_client_id uuid, client_key text, display_name text, description text, client_lifecycle_status text, active_policy_version text, organization_enablement_id uuid, organization_enablement_status text, organization_enabled_at timestamp with time zone, organization_disabled_at timestamp with time zone, enabled_workspace_count bigint, enabled_project_count bigint, enabled_capability_grant_count bigint, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_authorized boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _include_retired IS NULL THEN
    RAISE EXCEPTION 'invalid_include_retired' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'invalid_limit' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'invalid_offset' USING ERRCODE = '22023';
  END IF;

  -- Tenant scope is derived server-side from the Organization only.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NOT NULL THEN
    v_authorized := public.is_tenant_admin(v_tenant_id, v_actor)
      OR public.is_org_admin(v_actor, _organization_id);
  END IF;

  -- Absent Organization and unauthorized actor share one controlled,
  -- non-enumerating failure.
  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH org_enablement AS (
    SELECT e.*
    FROM public.api_organization_client_enablements e
    WHERE e.organization_id = _organization_id
      AND e.tenant_id = v_tenant_id
  ),
  ws AS (
    SELECT w.api_client_id, count(*)::bigint AS c
    FROM public.api_workspace_client_enablements w
    WHERE w.organization_id = _organization_id
      AND w.tenant_id = v_tenant_id
      AND w.lifecycle_status = 'enabled'
    GROUP BY w.api_client_id
  ),
  pr AS (
    SELECT p.api_client_id, count(*)::bigint AS c
    FROM public.api_project_client_enablements p
    JOIN public.projects pj
      ON pj.id = p.project_id
     AND pj.organization_id = _organization_id
    WHERE p.organization_id = _organization_id
      AND p.tenant_id = v_tenant_id
      AND p.lifecycle_status = 'enabled'
    GROUP BY p.api_client_id
  ),
  gr AS (
    SELECT g.api_client_id, count(*)::bigint AS c
    FROM public.api_capability_grants g
    WHERE g.organization_id = _organization_id
      AND g.tenant_id = v_tenant_id
      AND g.lifecycle_status = 'enabled'
    GROUP BY g.api_client_id
  ),
  configured AS (
    SELECT DISTINCT x.api_client_id FROM (
      SELECT e.api_client_id
        FROM public.api_organization_client_enablements e
       WHERE e.organization_id = _organization_id AND e.tenant_id = v_tenant_id
      UNION ALL
      SELECT w.api_client_id
        FROM public.api_workspace_client_enablements w
       WHERE w.organization_id = _organization_id AND w.tenant_id = v_tenant_id
      UNION ALL
      SELECT p.api_client_id
        FROM public.api_project_client_enablements p
        JOIN public.projects pj
          ON pj.id = p.project_id AND pj.organization_id = _organization_id
       WHERE p.organization_id = _organization_id AND p.tenant_id = v_tenant_id
      UNION ALL
      SELECT g.api_client_id
        FROM public.api_capability_grants g
       WHERE g.organization_id = _organization_id AND g.tenant_id = v_tenant_id
    ) x
  ),
  relevant AS (
    SELECT c.id,
           c.client_key,
           c.display_name,
           c.description,
           c.lifecycle_status
    FROM public.api_clients c
    WHERE (
            c.lifecycle_status = 'active'
            OR EXISTS (SELECT 1 FROM configured cf WHERE cf.api_client_id = c.id)
          )
      AND (
            c.lifecycle_status <> 'retired'
            OR (
                 _include_retired
                 AND EXISTS (SELECT 1 FROM configured cf WHERE cf.api_client_id = c.id)
               )
          )
  ),
  counted AS (
    SELECT r.*, count(*) OVER ()::bigint AS total
    FROM relevant r
  )
  SELECT
    cn.id,
    cn.client_key,
    cn.display_name,
    cn.description,
    cn.lifecycle_status,
    (
      SELECT pv.version
      FROM public.api_client_policy_versions pv
      WHERE pv.api_client_id = cn.id
        AND pv.lifecycle_status = 'active'
      ORDER BY pv.effective_at DESC NULLS LAST, pv.created_at DESC
      LIMIT 1
    ),
    oe.id,
    oe.lifecycle_status,
    oe.enabled_at,
    oe.disabled_at,
    COALESCE(ws.c, 0::bigint),
    COALESCE(pr.c, 0::bigint),
    COALESCE(gr.c, 0::bigint),
    cn.total
  FROM counted cn
  LEFT JOIN org_enablement oe ON oe.api_client_id = cn.id
  LEFT JOIN ws ON ws.api_client_id = cn.id
  LEFT JOIN pr ON pr.api_client_id = cn.id
  LEFT JOIN gr ON gr.api_client_id = cn.id
  ORDER BY
    CASE WHEN cn.lifecycle_status = 'active' THEN 0 ELSE 1 END,
    lower(cn.display_name),
    cn.id
  LIMIT _limit
  OFFSET _offset;
END;
$$;


--
-- Name: api_g_5_7_admin_list_workspace_client_capabilities(uuid, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_list_workspace_client_capabilities(_organization_id uuid, _workspace_id uuid, _api_client_id uuid, _limit integer, _offset integer) RETURNS TABLE(api_version text, capability_kind text, capability_key text, display_name text, description text, scope_level text, catalogue_lifecycle_status text, administrator_assignable boolean, supported_capability_id uuid, supported_capability_status text, organization_grant_id uuid, organization_grant_status text, organization_grant_enabled_at timestamp with time zone, organization_grant_disabled_at timestamp with time zone, workspace_grant_id uuid, workspace_grant_status text, workspace_grant_enabled_at timestamp with time zone, workspace_grant_disabled_at timestamp with time zone, effective_grant_status text, effective_grant_source text, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_authorized boolean := false;
  v_workspace_ok boolean := false;
  v_client_relevant boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _workspace_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 200 THEN
    RAISE EXCEPTION 'invalid_limit' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'invalid_offset' USING ERRCODE = '22023';
  END IF;

  -- Tenant scope is derived server-side from the Organization only.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NOT NULL THEN
    v_authorized := public.is_tenant_admin(v_tenant_id, v_actor)
      OR public.is_org_admin(v_actor, _organization_id);
  END IF;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Workspace containment: the Workspace must belong to the exact Organization.
  SELECT EXISTS (
    SELECT 1 FROM public.workspaces w
     WHERE w.id = _workspace_id
       AND w.organization_id = _organization_id
  ) INTO v_workspace_ok;

  IF NOT v_workspace_ok THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Client relevance: active client, or retained configuration in THIS Organization.
  SELECT EXISTS (
    SELECT 1 FROM public.api_clients c
     WHERE c.id = _api_client_id
       AND c.lifecycle_status = 'active'
  )
  OR EXISTS (
    SELECT 1 FROM public.api_organization_client_enablements e
     WHERE e.api_client_id = _api_client_id
       AND e.organization_id = _organization_id
       AND e.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_workspace_client_enablements we
     JOIN public.workspaces w2
       ON w2.id = we.workspace_id
      AND w2.organization_id = _organization_id
     WHERE we.api_client_id = _api_client_id
       AND we.organization_id = _organization_id
       AND we.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_project_client_enablements pe
     JOIN public.projects pj
       ON pj.id = pe.project_id
      AND pj.organization_id = _organization_id
     WHERE pe.api_client_id = _api_client_id
       AND pe.organization_id = _organization_id
       AND pe.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_capability_grants g
     WHERE g.api_client_id = _api_client_id
       AND g.organization_id = _organization_id
       AND g.tenant_id = v_tenant_id
  )
  INTO v_client_relevant;

  IF NOT v_client_relevant THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH supported AS (
    SELECT s.id AS supported_capability_id,
           s.api_version,
           s.capability_kind,
           s.capability_key,
           s.lifecycle_status AS supported_capability_status
    FROM public.api_client_supported_capabilities s
    WHERE s.api_client_id = _api_client_id
  ),
  joined AS (
    SELECT sup.supported_capability_id,
           cat.api_version,
           cat.capability_kind,
           cat.capability_key,
           cat.display_name,
           cat.description,
           cat.scope_level,
           cat.lifecycle_status AS catalogue_lifecycle_status,
           cat.administrator_assignable,
           sup.supported_capability_status
    FROM supported sup
    JOIN public.api_capability_catalogue cat
      ON cat.api_version = sup.api_version
     AND cat.capability_kind = sup.capability_kind
     AND cat.capability_key = sup.capability_key
  ),
  projected AS (
    SELECT j.*,
           og.id AS organization_grant_id,
           og.lifecycle_status AS organization_grant_status,
           og.enabled_at AS organization_grant_enabled_at,
           og.disabled_at AS organization_grant_disabled_at,
           wg.id AS workspace_grant_id,
           wg.lifecycle_status AS workspace_grant_status,
           wg.enabled_at AS workspace_grant_enabled_at,
           wg.disabled_at AS workspace_grant_disabled_at
    FROM joined j
    LEFT JOIN public.api_capability_grants og
      ON og.tenant_id = v_tenant_id
     AND og.organization_id = _organization_id
     AND og.workspace_id IS NULL
     AND og.api_client_id = _api_client_id
     AND og.api_version = j.api_version
     AND og.capability_kind = j.capability_kind
     AND og.capability_key = j.capability_key
    LEFT JOIN (
      SELECT g2.id,
             g2.lifecycle_status,
             g2.enabled_at,
             g2.disabled_at,
             g2.api_version,
             g2.capability_kind,
             g2.capability_key
      FROM public.api_capability_grants g2
      JOIN public.workspaces w3
        ON w3.id = g2.workspace_id
       AND w3.organization_id = _organization_id
      WHERE g2.tenant_id = v_tenant_id
        AND g2.organization_id = _organization_id
        AND g2.workspace_id = _workspace_id
        AND g2.api_client_id = _api_client_id
    ) wg
      ON wg.api_version = j.api_version
     AND wg.capability_kind = j.capability_kind
     AND wg.capability_key = j.capability_key
  ),
  eligible AS (
    -- API-ADM-UX2.1: Project-scoped capabilities are administered at Workspace
    -- level alongside Workspace-scoped ones. Organization-scoped capabilities
    -- remain non-grantable here and continue to appear only as retained rows.
    SELECT p.*
    FROM projected p
    WHERE (
      p.supported_capability_status = 'enabled'
      AND p.catalogue_lifecycle_status = 'active'
      AND p.administrator_assignable = true
      AND p.scope_level IN ('workspace', 'project')
    )
    OR p.workspace_grant_id IS NOT NULL
    OR p.organization_grant_id IS NOT NULL
  ),
  effective AS (
    SELECT e.*,
           CASE
             WHEN e.workspace_grant_status = 'enabled'
               OR e.organization_grant_status = 'enabled' THEN 'enabled'
             WHEN e.workspace_grant_id IS NOT NULL
               OR e.organization_grant_id IS NOT NULL THEN 'disabled'
             ELSE NULL
           END AS effective_grant_status,
           CASE
             WHEN e.workspace_grant_status = 'enabled' THEN 'workspace'
             WHEN e.organization_grant_status = 'enabled' THEN 'organization'
             ELSE 'none'
           END AS effective_grant_source
    FROM eligible e
  ),
  counted AS (
    SELECT f.*, count(*) OVER ()::bigint AS total
    FROM effective f
  )
  SELECT c.api_version,
         c.capability_kind,
         c.capability_key,
         c.display_name,
         c.description,
         c.scope_level,
         c.catalogue_lifecycle_status,
         c.administrator_assignable,
         c.supported_capability_id,
         c.supported_capability_status,
         c.organization_grant_id,
         c.organization_grant_status,
         c.organization_grant_enabled_at,
         c.organization_grant_disabled_at,
         c.workspace_grant_id,
         c.workspace_grant_status,
         c.workspace_grant_enabled_at,
         c.workspace_grant_disabled_at,
         c.effective_grant_status,
         c.effective_grant_source,
         c.total
  FROM counted c
  ORDER BY c.api_version ASC,
           c.capability_kind ASC,
           lower(COALESCE(c.display_name, '')) ASC,
           c.capability_key ASC
  LIMIT _limit OFFSET _offset;
END;
$$;


--
-- Name: api_g_5_7_admin_list_workspace_client_projects(uuid, uuid, uuid, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_list_workspace_client_projects(_organization_id uuid, _workspace_id uuid, _api_client_id uuid, _include_archived boolean, _limit integer, _offset integer) RETURNS TABLE(project_id uuid, project_name text, project_is_archived boolean, project_enablement_id uuid, project_enablement_status text, project_enabled_at timestamp with time zone, project_disabled_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_authorized boolean := false;
  v_client_relevant boolean := false;
  v_ws_ok boolean := false;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _workspace_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _include_archived IS NULL THEN
    RAISE EXCEPTION 'invalid_include_archived' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 200 THEN
    RAISE EXCEPTION 'invalid_limit' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'invalid_offset' USING ERRCODE = '22023';
  END IF;

  -- Tenant scope is derived server-side from the Organization only.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NOT NULL THEN
    v_authorized := public.is_tenant_admin(v_tenant_id, v_actor)
      OR public.is_org_admin(v_actor, _organization_id);
  END IF;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Workspace containment: exact Workspace inside the exact Organization.
  SELECT EXISTS (
    SELECT 1 FROM public.workspaces w
     WHERE w.id = _workspace_id
       AND w.organization_id = _organization_id
  ) INTO v_ws_ok;

  IF NOT v_ws_ok THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Client relevance: active client, or retained configuration in THIS Organization.
  SELECT EXISTS (
    SELECT 1 FROM public.api_clients c
     WHERE c.id = _api_client_id
       AND c.lifecycle_status = 'active'
  )
  OR EXISTS (
    SELECT 1 FROM public.api_organization_client_enablements e
     WHERE e.api_client_id = _api_client_id
       AND e.organization_id = _organization_id
       AND e.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_workspace_client_enablements we
     JOIN public.workspaces w2
       ON w2.id = we.workspace_id
      AND w2.organization_id = _organization_id
     WHERE we.api_client_id = _api_client_id
       AND we.organization_id = _organization_id
       AND we.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_project_client_enablements pe
     JOIN public.projects pj
       ON pj.id = pe.project_id
      AND pj.organization_id = _organization_id
     WHERE pe.api_client_id = _api_client_id
       AND pe.organization_id = _organization_id
       AND pe.tenant_id = v_tenant_id
  )
  OR EXISTS (
    SELECT 1 FROM public.api_capability_grants g
     WHERE g.api_client_id = _api_client_id
       AND g.organization_id = _organization_id
       AND g.tenant_id = v_tenant_id
  )
  INTO v_client_relevant;

  IF NOT v_client_relevant THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH ws_projects AS (
    SELECT p.id,
           public.btpm_decrypt(p.name, _organization_id) AS name,
           COALESCE(p.is_archived, false) AS is_archived
    FROM public.projects p
    JOIN public.workspaces w
      ON w.id = p.workspace_id
     AND w.organization_id = _organization_id
    WHERE p.workspace_id = _workspace_id
      AND p.organization_id = _organization_id
  ),
  proj_enable AS (
    SELECT pe.id,
           pe.project_id,
           pe.lifecycle_status,
           pe.enabled_at,
           pe.disabled_at
    FROM public.api_project_client_enablements pe
    JOIN public.projects pj
      ON pj.id = pe.project_id
     AND pj.workspace_id = pe.workspace_id
     AND pj.organization_id = pe.organization_id
    WHERE pe.api_client_id = _api_client_id
      AND pe.tenant_id = v_tenant_id
      AND pe.organization_id = _organization_id
      AND pe.workspace_id = _workspace_id
  ),
  eligible AS (
    SELECT wp.id,
           wp.name,
           wp.is_archived,
           pe.id AS enablement_id,
           pe.lifecycle_status,
           pe.enabled_at,
           pe.disabled_at
    FROM ws_projects wp
    LEFT JOIN proj_enable pe ON pe.project_id = wp.id
    WHERE wp.is_archived = false
       OR _include_archived = true
       OR pe.id IS NOT NULL
  ),
  counted AS (
    SELECT e.*, count(*) OVER ()::bigint AS total
    FROM eligible e
  )
  SELECT c.id,
         c.name,
         c.is_archived,
         c.enablement_id,
         c.lifecycle_status,
         c.enabled_at,
         c.disabled_at,
         c.total
  FROM counted c
  ORDER BY lower(COALESCE(c.name, '')) ASC, c.id ASC
  LIMIT _limit OFFSET _offset;
END;
$$;


--
-- Name: api_g_5_7_admin_transition_organization_client(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_transition_organization_client(_organization_id uuid, _api_client_id uuid, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_client_status text;
  v_row public.api_organization_client_enablements%ROWTYPE;
  v_previous text;
  v_enablement_id uuid;
  v_action text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = '22023';
  END IF;

  IF _target_lifecycle_status IS NULL
     OR _target_lifecycle_status NOT IN ('enabled', 'disabled') THEN
    RAISE EXCEPTION 'invalid_target_lifecycle_status' USING ERRCODE = '22023';
  END IF;

  -- Server-derived Tenant scope. Absent Organization collapses into not_authorized.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.is_tenant_admin(v_tenant_id, v_actor)
    OR public.is_org_admin(v_actor, _organization_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Transaction-scoped serialization for the exact Organization/client pair.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'api_g_5_7_organization_client_transition|' ||
      _organization_id::text || '|' ||
      _api_client_id::text,
      0
    )
  );

  SELECT * INTO v_row
  FROM public.api_organization_client_enablements e
  WHERE e.organization_id = _organization_id
    AND e.api_client_id = _api_client_id
  FOR UPDATE;

  IF _target_lifecycle_status = 'enabled' THEN
    SELECT c.lifecycle_status INTO v_client_status
    FROM public.api_clients c
    WHERE c.id = _api_client_id;

    IF v_client_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'client_not_active' USING ERRCODE = '22023';
    END IF;

    IF v_row.id IS NULL THEN
      v_previous := NULL;
      INSERT INTO public.api_organization_client_enablements (
        tenant_id, organization_id, api_client_id, lifecycle_status,
        enabled_at, disabled_at, created_by, updated_by
      )
      VALUES (
        v_tenant_id, _organization_id, _api_client_id, 'enabled',
        now(), NULL, v_actor, v_actor
      )
      RETURNING id INTO v_enablement_id;
    ELSIF v_row.lifecycle_status = 'disabled' THEN
      v_previous := v_row.lifecycle_status;
      UPDATE public.api_organization_client_enablements e
      SET lifecycle_status = 'enabled',
          enabled_at = now(),
          disabled_at = NULL,
          updated_by = v_actor
      WHERE e.id = v_row.id
      RETURNING e.id INTO v_enablement_id;
    ELSE
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_action := 'enable_organization_client';
  ELSE
    IF v_row.id IS NULL OR v_row.lifecycle_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_previous := v_row.lifecycle_status;
    UPDATE public.api_organization_client_enablements e
    SET lifecycle_status = 'disabled',
        disabled_at = now(),
        updated_by = v_actor
    WHERE e.id = v_row.id
    RETURNING e.id INTO v_enablement_id;

    v_action := 'disable_organization_client';
  END IF;

  INSERT INTO public.api_connected_apps_admin_audit_events (
    correlation_id, actor_user_id, tenant_id, organization_id, api_client_id,
    target_type, target_id, action,
    previous_lifecycle_status, resulting_lifecycle_status, source_channel
  )
  VALUES (
    gen_random_uuid(), v_actor, v_tenant_id, _organization_id, _api_client_id,
    'organization_client_enablement', v_enablement_id, v_action,
    v_previous, _target_lifecycle_status, 'btpm_ui'
  );

  RETURN v_enablement_id;
END;
$$;


--
-- Name: api_g_5_7_admin_transition_organization_client_capability(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_transition_organization_client_capability(_organization_id uuid, _api_client_id uuid, _api_version text, _capability_key text, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_client_status text;
  v_org_parent_status text;
  v_capability_kind text;
  v_row public.api_capability_grants%ROWTYPE;
  v_previous text;
  v_grant_id uuid;
  v_action text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL
     OR _api_client_id IS NULL
     OR _api_version IS NULL
     OR _capability_key IS NULL
     OR btrim(_api_version) = ''
     OR btrim(_capability_key) = '' THEN
    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = '22023';
  END IF;

  IF _target_lifecycle_status IS NULL
     OR _target_lifecycle_status NOT IN ('enabled', 'disabled') THEN
    RAISE EXCEPTION 'invalid_target_lifecycle_status' USING ERRCODE = '22023';
  END IF;

  -- Server-derived Tenant scope. Absent Organization collapses into not_authorized.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.is_tenant_admin(v_tenant_id, v_actor)
    OR public.is_org_admin(v_actor, _organization_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Transaction-scoped serialization for the exact Organization/client pair.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'api_g_5_7_organization_client_transition|' ||
      _organization_id::text || '|' ||
      _api_client_id::text,
      0
    )
  );

  -- Authoritative capability kind: derived from the exact client-supported
  -- declaration joined to the catalogue on version, kind and key.
  SELECT cat.capability_kind INTO v_capability_kind
  FROM public.api_client_supported_capabilities s
  JOIN public.api_capability_catalogue cat
    ON cat.api_version = s.api_version
   AND cat.capability_kind = s.capability_kind
   AND cat.capability_key = s.capability_key
  WHERE s.api_client_id = _api_client_id
    AND s.api_version = _api_version
    AND s.capability_key = _capability_key;

  IF _target_lifecycle_status = 'enabled' THEN
    SELECT c.lifecycle_status INTO v_client_status
    FROM public.api_clients c
    WHERE c.id = _api_client_id;

    IF v_client_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'client_not_active' USING ERRCODE = '22023';
    END IF;

    SELECT oe.lifecycle_status INTO v_org_parent_status
    FROM public.api_organization_client_enablements oe
    WHERE oe.tenant_id = v_tenant_id
      AND oe.organization_id = _organization_id
      AND oe.api_client_id = _api_client_id;

    IF v_org_parent_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'organization_client_not_enabled' USING ERRCODE = '22023';
    END IF;

    -- Capability availability is decided solely by the authoritative
    -- supported-capability/catalogue metadata. No capability-kind allowlist
    -- exists at this layer.
    PERFORM 1
    FROM public.api_client_supported_capabilities s
    JOIN public.api_capability_catalogue cat
      ON cat.api_version = s.api_version
     AND cat.capability_kind = s.capability_kind
     AND cat.capability_key = s.capability_key
    WHERE s.api_client_id = _api_client_id
      AND s.api_version = _api_version
      AND s.capability_key = _capability_key
      AND s.lifecycle_status = 'enabled'
      AND cat.lifecycle_status = 'active'
      AND cat.administrator_assignable = true
      AND cat.scope_level = 'organization';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'capability_not_available' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- Exact Organization-level grant identity. capability_kind is never part of it.
  SELECT * INTO v_row
  FROM public.api_capability_grants g
  WHERE g.tenant_id = v_tenant_id
    AND g.organization_id = _organization_id
    AND g.workspace_id IS NULL
    AND g.api_client_id = _api_client_id
    AND g.api_version = _api_version
    AND g.capability_key = _capability_key
  FOR UPDATE;

  -- Fail closed on malformed stored identity; never repair it here.
  IF v_row.id IS NOT NULL
     AND (v_capability_kind IS NULL OR v_row.capability_kind IS DISTINCT FROM v_capability_kind) THEN
    RAISE EXCEPTION 'capability_not_available' USING ERRCODE = '22023';
  END IF;

  IF _target_lifecycle_status = 'enabled' THEN
    IF v_capability_kind IS NULL THEN
      RAISE EXCEPTION 'capability_not_available' USING ERRCODE = '22023';
    END IF;

    IF v_row.id IS NULL THEN
      v_previous := NULL;
      INSERT INTO public.api_capability_grants (
        tenant_id, organization_id, workspace_id, api_client_id,
        api_version, capability_kind, capability_key,
        lifecycle_status, reason, enabled_at, disabled_at, created_by, updated_by
      )
      VALUES (
        v_tenant_id, _organization_id, NULL, _api_client_id,
        _api_version, v_capability_kind, _capability_key,
        'enabled', NULL, now(), NULL, v_actor, v_actor
      )
      RETURNING id INTO v_grant_id;
    ELSIF v_row.lifecycle_status = 'disabled' THEN
      v_previous := v_row.lifecycle_status;
      UPDATE public.api_capability_grants g
      SET lifecycle_status = 'enabled',
          enabled_at = now(),
          disabled_at = NULL,
          updated_by = v_actor
      WHERE g.id = v_row.id
      RETURNING g.id INTO v_grant_id;
    ELSE
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_action := 'enable_organization_capability';
  ELSE
    IF v_row.id IS NULL OR v_row.lifecycle_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_previous := v_row.lifecycle_status;
    UPDATE public.api_capability_grants g
    SET lifecycle_status = 'disabled',
        disabled_at = now(),
        updated_by = v_actor
    WHERE g.id = v_row.id
    RETURNING g.id INTO v_grant_id;

    v_action := 'disable_organization_capability';
  END IF;

  INSERT INTO public.api_connected_apps_admin_audit_events (
    correlation_id, actor_user_id, tenant_id, organization_id, api_client_id,
    target_type, target_id, action,
    previous_lifecycle_status, resulting_lifecycle_status, source_channel
  )
  VALUES (
    gen_random_uuid(), v_actor, v_tenant_id, _organization_id, _api_client_id,
    'organization_capability_grant', v_grant_id, v_action,
    v_previous, _target_lifecycle_status, 'btpm_ui'
  );

  RETURN v_grant_id;
END;
$$;


--
-- Name: api_g_5_7_admin_transition_project_client(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_7_admin_transition_project_client(_organization_id uuid, _workspace_id uuid, _project_id uuid, _api_client_id uuid, _target_lifecycle_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant_id uuid;
  v_client_status text;
  v_org_parent_status text;
  v_ws_parent_status text;
  v_ws_ok boolean;
  v_project_ok boolean;
  v_row public.api_project_client_enablements%ROWTYPE;
  v_previous text;
  v_enablement_id uuid;
  v_action text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NULL OR _workspace_id IS NULL OR _project_id IS NULL OR _api_client_id IS NULL THEN
    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = '22023';
  END IF;

  IF _target_lifecycle_status IS NULL
     OR _target_lifecycle_status NOT IN ('enabled', 'disabled') THEN
    RAISE EXCEPTION 'invalid_target_lifecycle_status' USING ERRCODE = '22023';
  END IF;

  -- Server-derived Tenant scope. Absent Organization collapses into not_authorized.
  SELECT o.tenant_id INTO v_tenant_id
  FROM public.organizations o
  WHERE o.id = _organization_id;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.is_tenant_admin(v_tenant_id, v_actor)
    OR public.is_org_admin(v_actor, _organization_id)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Workspace containment: foreign or missing Workspace is indistinguishable.
  PERFORM 1
  FROM public.workspaces w
  WHERE w.id = _workspace_id
    AND w.organization_id = _organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Project containment: foreign or missing Project is indistinguishable.
  PERFORM 1
  FROM public.projects p
  WHERE p.id = _project_id
    AND p.workspace_id = _workspace_id
    AND p.organization_id = _organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Transaction-scoped serialization for the exact Organization/client pair.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'api_g_5_7_organization_client_transition|' ||
      _organization_id::text || '|' ||
      _api_client_id::text,
      0
    )
  );

  IF _target_lifecycle_status = 'enabled' THEN
    SELECT c.lifecycle_status INTO v_client_status
    FROM public.api_clients c
    WHERE c.id = _api_client_id;

    IF v_client_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'client_not_active' USING ERRCODE = '22023';
    END IF;

    SELECT oe.lifecycle_status INTO v_org_parent_status
    FROM public.api_organization_client_enablements oe
    WHERE oe.tenant_id = v_tenant_id
      AND oe.organization_id = _organization_id
      AND oe.api_client_id = _api_client_id;

    IF v_org_parent_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'organization_client_not_enabled' USING ERRCODE = '22023';
    END IF;

    SELECT we.lifecycle_status INTO v_ws_parent_status
    FROM public.api_workspace_client_enablements we
    JOIN public.workspaces w2
      ON w2.id = we.workspace_id
     AND w2.organization_id = _organization_id
    WHERE we.tenant_id = v_tenant_id
      AND we.organization_id = _organization_id
      AND we.workspace_id = _workspace_id
      AND we.api_client_id = _api_client_id;

    IF v_ws_parent_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'workspace_client_not_enabled' USING ERRCODE = '22023';
    END IF;

    SELECT true INTO v_ws_ok
    FROM public.workspaces w
    WHERE w.id = _workspace_id
      AND w.organization_id = _organization_id
      AND w.is_active = true
      AND w.is_archived = false;

    IF v_ws_ok IS NOT TRUE THEN
      RAISE EXCEPTION 'workspace_not_active' USING ERRCODE = '22023';
    END IF;

    SELECT true INTO v_project_ok
    FROM public.projects p
    WHERE p.id = _project_id
      AND p.workspace_id = _workspace_id
      AND p.organization_id = _organization_id
      AND COALESCE(p.is_archived, false) = false;

    IF v_project_ok IS NOT TRUE THEN
      RAISE EXCEPTION 'project_not_active' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT * INTO v_row
  FROM public.api_project_client_enablements e
  WHERE e.tenant_id = v_tenant_id
    AND e.organization_id = _organization_id
    AND e.workspace_id = _workspace_id
    AND e.project_id = _project_id
    AND e.api_client_id = _api_client_id
  FOR UPDATE;

  IF _target_lifecycle_status = 'enabled' THEN
    IF v_row.id IS NULL THEN
      v_previous := NULL;
      INSERT INTO public.api_project_client_enablements (
        tenant_id, organization_id, workspace_id, project_id, api_client_id, lifecycle_status,
        enabled_at, disabled_at, created_by, updated_by
      )
      VALUES (
        v_tenant_id, _organization_id, _workspace_id, _project_id, _api_client_id, 'enabled',
        now(), NULL, v_actor, v_actor
      )
      RETURNING id INTO v_enablement_id;
    ELSIF v_row.lifecycle_status = 'disabled' THEN
      v_previous := v_row.lifecycle_status;
      UPDATE public.api_project_client_enablements e
      SET lifecycle_status = 'enabled',
          enabled_at = now(),
          disabled_at = NULL,
          updated_by = v_actor
      WHERE e.id = v_row.id
      RETURNING e.id INTO v_enablement_id;
    ELSE
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_action := 'enable_project_client';
  ELSE
    IF v_row.id IS NULL OR v_row.lifecycle_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_previous := v_row.lifecycle_status;
    UPDATE public.api_project_client_enablements e
    SET lifecycle_status = 'disabled',
        disabled_at = now(),
        updated_by = v_actor
    WHERE e.id = v_row.id
    RETURNING e.id INTO v_enablement_id;

    v_action := 'disable_project_client';
  END IF;

  INSERT INTO public.api_connected_apps_admin_audit_events (
    correlation_id, actor_user_id, tenant_id, organization_id, api_client_id,
    target_type, target_id, action,
    previous_lifecycle_status, resulting_lifecycle_status, source_channel
  )
  VALUES (
    gen_random_uuid(), v_actor, v_tenant_id, _organization_id, _api_client_id,
    'project_client_enablement', v_enablement_id, v_action,
    v_previous, _target_lifecycle_status, 'btpm_ui'
  );

  RETURN v_enablement_id;
END;
$$;


