    SELECT c.lifecycle_status INTO v_client_status
    FROM public.api_clients c
    WHERE c.id = _api_client_id;

    IF v_client_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'client_not_active' USING ERRCODE = '22023';
    END IF;

    SELECT oe.lifecycle_status INTO v_org_parent_status
    FROM public.api_organization_client_enablements oe
    WHERE oe.tenant_id = v_tenant_id
      AND oe.organization_id = _organization_id
      AND oe.api_client_id = _api_client_id;

    IF v_org_parent_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'organization_client_not_enabled' USING ERRCODE = '22023';
    END IF;

    SELECT we.lifecycle_status INTO v_ws_parent_status
    FROM public.api_workspace_client_enablements we
    JOIN public.workspaces w2
      ON w2.id = we.workspace_id
     AND w2.organization_id = _organization_id
    WHERE we.tenant_id = v_tenant_id
      AND we.organization_id = _organization_id
      AND we.workspace_id = _workspace_id
      AND we.api_client_id = _api_client_id;

    IF v_ws_parent_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'workspace_client_not_enabled' USING ERRCODE = '22023';
    END IF;

    SELECT true INTO v_ws_ok
    FROM public.workspaces w
    WHERE w.id = _workspace_id
      AND w.organization_id = _organization_id
      AND w.is_active = true
      AND w.is_archived = false;

    IF v_ws_ok IS NOT TRUE THEN
      RAISE EXCEPTION 'workspace_not_active' USING ERRCODE = '22023';
    END IF;

    -- API-ADM-UX2.1: Workspace administration covers Workspace-scoped and
    -- Project-scoped capabilities. Organization-scoped capabilities remain
    -- rejected here. Runtime scope of the capability is unchanged.
    PERFORM 1
    FROM public.api_client_supported_capabilities s
    JOIN public.api_capability_catalogue cat
      ON cat.api_version = s.api_version
     AND cat.capability_kind = s.capability_kind
     AND cat.capability_key = s.capability_key
    WHERE s.api_client_id = _api_client_id
      AND s.api_version = _api_version
      AND s.capability_key = _capability_key
      AND s.lifecycle_status = 'enabled'
      AND cat.lifecycle_status = 'active'
      AND cat.administrator_assignable = true
      AND cat.scope_level IN ('workspace', 'project');

    IF NOT FOUND THEN
      RAISE EXCEPTION 'capability_not_available' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- Exact Workspace-level grant identity. capability_kind is never part of it.
  SELECT g.* INTO v_row
  FROM public.api_capability_grants g
  JOIN public.workspaces w3
    ON w3.id = g.workspace_id
   AND w3.organization_id = _organization_id
  WHERE g.tenant_id = v_tenant_id
    AND g.organization_id = _organization_id
    AND g.workspace_id = _workspace_id
    AND g.api_client_id = _api_client_id
    AND g.api_version = _api_version
    AND g.capability_key = _capability_key
  FOR UPDATE OF g;

  -- Fail closed on malformed stored identity; never repair it here.
  IF v_row.id IS NOT NULL
     AND (v_capability_kind IS NULL OR v_row.capability_kind IS DISTINCT FROM v_capability_kind) THEN
    RAISE EXCEPTION 'capability_not_available' USING ERRCODE = '22023';
  END IF;

  IF _target_lifecycle_status = 'enabled' THEN
    IF v_capability_kind IS NULL THEN
      RAISE EXCEPTION 'capability_not_available' USING ERRCODE = '22023';
    END IF;

    -- An enabled inherited Organization grant is a separate additive scope and
    -- never blocks creating or re-enabling the exact Workspace grant.
    IF v_row.id IS NULL THEN
      v_previous := NULL;
      INSERT INTO public.api_capability_grants (
        tenant_id, organization_id, workspace_id, api_client_id,
        api_version, capability_kind, capability_key,
        lifecycle_status, reason, enabled_at, disabled_at, created_by, updated_by
      )
      VALUES (
        v_tenant_id, _organization_id, _workspace_id, _api_client_id,
        _api_version, v_capability_kind, _capability_key,
        'enabled', NULL, now(), NULL, v_actor, v_actor
      )
      RETURNING id INTO v_grant_id;
    ELSIF v_row.lifecycle_status = 'disabled' THEN
      v_previous := v_row.lifecycle_status;
      UPDATE public.api_capability_grants g
      SET lifecycle_status = 'enabled',
          enabled_at = now(),
          disabled_at = NULL,
          updated_by = v_actor
      WHERE g.id = v_row.id
      RETURNING g.id INTO v_grant_id;
    ELSE
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_action := 'enable_workspace_capability';
  ELSE
    IF v_row.id IS NULL OR v_row.lifecycle_status IS DISTINCT FROM 'enabled' THEN
      RAISE EXCEPTION 'invalid_lifecycle_transition' USING ERRCODE = '22023';
    END IF;

    v_previous := v_row.lifecycle_status;
    UPDATE public.api_capability_grants g
    SET lifecycle_status = 'disabled',
        disabled_at = now(),
        updated_by = v_actor
    WHERE g.id = v_row.id
    RETURNING g.id INTO v_grant_id;

    v_action := 'disable_workspace_capability';
  END IF;

  INSERT INTO public.api_connected_apps_admin_audit_events (
    correlation_id, actor_user_id, tenant_id, organization_id, api_client_id,
    target_type, target_id, action,
    previous_lifecycle_status, resulting_lifecycle_status, source_channel
  )
  VALUES (
    gen_random_uuid(), v_actor, v_tenant_id, _organization_id, _api_client_id,
    'workspace_capability_grant', v_grant_id, v_action,
    v_previous, _target_lifecycle_status, 'btpm_ui'
  );

  RETURN v_grant_id;
END;
$$;


--
-- Name: api_g_5_9_disconnect_my_connected_app(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_9_disconnect_my_connected_app(_client_key text, _correlation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
declare
  _uid uuid := auth.uid();
  _client_id uuid;
  _now timestamptz := now();
  _changed integer := 0;
  _fail_closed constant jsonb := jsonb_build_object('ok', false, 'changed', false, 'connected', false);
begin
  if _uid is null then
    return _fail_closed;
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = _uid and p.is_active = true
  ) then
    return _fail_closed;
  end if;

  if _client_key is null
     or length(_client_key) < 3
     or length(_client_key) > 64
     or _client_key !~ '^[a-z0-9][a-z0-9_.-]{1,62}[a-z0-9]$' then
    return _fail_closed;
  end if;

  if _correlation_id is not null and _correlation_id !~ '^[A-Za-z0-9_-]{1,64}$' then
    return _fail_closed;
  end if;

  select c.id into _client_id
  from public.api_clients c
  where c.client_key = _client_key
  limit 1;

  if _client_id is null then
    return _fail_closed;
  end if;

  -- Lock every non-revoked acknowledgement row for this exact actor + client.
  perform 1
  from public.api_user_policy_acknowledgements a
  where a.user_id = _uid
    and a.api_client_id = _client_id
    and a.revoked_at is null
  for update;

  with revoked as (
    update public.api_user_policy_acknowledgements a
    set revoked_at = _now
    where a.user_id = _uid
      and a.api_client_id = _client_id
      and a.revoked_at is null
    returning a.policy_version_id
  ),
  audited as (
    insert into public.api_consent_audit_events (
      actor_user_id,
      api_client_id,
      policy_version_id,
      action,
      source_channel,
      correlation_id
    )
    select _uid, _client_id, r.policy_version_id, 'revoke', 'btpm_ui', _correlation_id
    from revoked r
    returning 1
  )
  select count(*)::integer into _changed from audited;

  return jsonb_build_object(
    'ok', true,
    'changed', _changed > 0,
    'connected', false
  );
exception
  when others then
    return _fail_closed;
end;
$_$;


--
-- Name: api_g_5_9_list_my_connected_apps(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_g_5_9_list_my_connected_apps(_limit integer, _offset integer) RETURNS TABLE(client_key text, display_name text, description text, latest_acknowledged_at timestamp with time zone, connection_status text, policy jsonb, organizations jsonb, workspaces jsonb, capabilities jsonb, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  _uid uuid := auth.uid();
  _empty_scope constant jsonb := jsonb_build_object('count', 0, 'display_names', '[]'::jsonb);
begin
  if _uid is null then
    raise exception 'not_authorized';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = _uid and p.is_active = true
  ) then
    raise exception 'not_authorized';
  end if;

  if _limit is null or _limit < 1 or _limit > 100 then
    raise exception 'invalid_limit';
  end if;

  if _offset is null or _offset < 0 or _offset > 10000 then
    raise exception 'invalid_offset';
  end if;

  return query
  with retained as (
    select
      a.api_client_id,
      max(a.acknowledged_at) as latest_acknowledged_at
    from public.api_user_policy_acknowledgements a
    where a.user_id = _uid
      and a.revoked_at is null
    group by a.api_client_id
  ),
  joined as (
    select
      c.client_key,
      c.display_name,
      c.description,
      r.latest_acknowledged_at,
      ctx.ctx
    from retained r
    join public.api_clients c
      on c.id = r.api_client_id
    cross join lateral (
      select public.get_api_d_consent_context(c.client_key) as ctx
    ) ctx
  ),
  shaped as (
    select
      j.client_key,
      j.display_name,
      j.description,
      j.latest_acknowledged_at,
      case
        when coalesce((j.ctx -> 'eligible')::text = 'true', false)
         and coalesce((j.ctx -> 'acknowledged')::text = 'true', false)
        then 'active'
        else 'unavailable'
      end as connection_status,
      j.ctx
    from joined j
  ),
  projected as (
    select
      s.client_key,
      s.display_name,
      s.description,
      s.latest_acknowledged_at,
      s.connection_status,
      case
        when s.connection_status = 'active' then jsonb_build_object(
          'version', s.ctx -> 'policy' -> 'version',
          'policy_uri', s.ctx -> 'policy' -> 'policy_uri',
          'effective_at', s.ctx -> 'policy' -> 'effective_at'
        )
        else null::jsonb
      end as policy,
      case
        when s.connection_status = 'active'
        then coalesce(s.ctx -> 'organizations', _empty_scope)
        else _empty_scope
      end as organizations,
      case
        when s.connection_status = 'active'
        then coalesce(s.ctx -> 'workspaces', _empty_scope)
        else _empty_scope
      end as workspaces,
      case
        when s.connection_status = 'active'
        then coalesce(s.ctx -> 'capabilities', '[]'::jsonb)
        else '[]'::jsonb
      end as capabilities
    from shaped s
  ),
  counted as (
    select p.*, count(*) over () as total_count
    from projected p
  )
  select
    c.client_key,
    c.display_name,
    c.description,
    c.latest_acknowledged_at,
    c.connection_status,
    c.policy,
    c.organizations,
    c.workspaces,
    c.capabilities,
    c.total_count
  from counted c
  order by
    case when c.connection_status = 'active' then 0 else 1 end asc,
    lower(c.display_name) asc,
    c.client_key asc
  offset _offset
  limit _limit;
end;
$$;


