--
-- Name: api_v1_get_blocker(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_blocker(_expected_oauth_client_id text, _blocker_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _target_type text;
  _target_id uuid;
  _blocker_org_id uuid;
  _blocker_ws_id uuid;
  _derived_project_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _result jsonb;
BEGIN
  IF _blocker_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT b.target_type, b.target_id, b.organization_id, b.workspace_id
    INTO _target_type, _target_id, _blocker_org_id, _blocker_ws_id
  FROM public.blockers b
  WHERE b.id = _blocker_id;

  IF _target_type IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _target_type = 'project' THEN
    _derived_project_id := _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT ph.project_id INTO _derived_project_id
    FROM public.phases ph
    WHERE ph.id = _target_id;
  ELSIF _target_type = 'task' THEN
    SELECT tk.project_id INTO _derived_project_id
    FROM public.tasks tk
    LEFT JOIN public.phases tph ON tph.id = tk.phase_id
    WHERE tk.id = _target_id
      AND (tk.phase_id IS NULL OR tph.project_id = tk.project_id);
  ELSE
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _derived_project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _derived_project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'blockers:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'blockers:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'blockers:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL
     OR _org_id <> _blocker_org_id
     OR _ws_id <> _blocker_ws_id THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
           'blockerId', b.id,
           'projectId', _derived_project_id,
           'targetType', b.target_type,
           'targetId', b.target_id,
           'title', public.btpm_decrypt(b.title, b.organization_id),
           'description', public.btpm_decrypt(b.description, b.organization_id),
           'severity', b.severity::text,
           'status', b.status::text,
           'resolvedAt', b.resolved_at,
           'updatedAt', b.updated_at,
           'resolvedBy', b.resolved_by
         )
    INTO _result
  FROM public.blockers b
  WHERE b.id = _blocker_id
    AND b.organization_id = _org_id
    AND b.workspace_id = _ws_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_kpi(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_kpi(_expected_oauth_client_id text, _kpi_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _proj_id uuid;
  _rowcount integer;
  _result jsonb;
BEGIN
  -- 1. Strict input contract. No normalization, no repair.
  IF _kpi_id IS NULL
     OR _kpi_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  -- 2. Canonical delegated read principal (no duplicated OAuth/policy logic).
  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- 3. Server-derived KPI -> Project -> Workspace -> Organization -> Tenant scope
  --    plus the accepted external Project-read authority chain.
  SELECT
    jsonb_build_object(
      'kpiId', k.id,
      'projectId', p.id,
      'name', k.name,
      'description', public.btpm_decrypt(k.description, k.organization_id),
      'unit', k.unit,
      'targetValue', k.target_value,
      'currentValue', k.current_value,
      'targetDirection', k.target_direction::text,
      'sourceMode', k.source_mode,
      'valueType', k.value_type,
      'cadence', k.cadence,
      'calculationKey', k.calculation_key,
      'formulaVersion', k.formula_version,
      'completionMethod', k.completion_method,
      'commentRequired', k.comment_required,
      'actionPlanRequired', k.action_plan_required,
      'autoSnapshotEnabled', k.auto_snapshot_enabled,
      'isArchived', k.is_archived,
      'createdAt', k.created_at,
      'updatedAt', k.updated_at
    ),
    p.id, w.id, o.id, t.id
    INTO _result, _proj_id, _ws_id, _org_id, _tenant_id
  FROM public.kpi_definitions k
  JOIN public.projects p
    ON p.id = k.target_id
   AND p.is_archived = false
   AND p.workspace_id = k.workspace_id
   AND p.organization_id = k.organization_id
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE k.id = _kpi_id
    AND k.target_type = 'project'
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'kpis:read'
        AND sc.lifecycle_status = 'enabled'
    )
    -- API-ADM-UX2.2: exact enabled Workspace capability grant.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'kpis:read'
        AND g.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'kpis:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    );

  IF _result IS NULL
     OR _proj_id IS NULL OR _ws_id IS NULL OR _org_id IS NULL OR _tenant_id IS NULL THEN
    -- Missing KPI, malformed containment, unsupported target type, inaccessible
    -- Project and unauthorized caller are all indistinguishable.
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_me(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_me(_expected_oauth_client_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
BEGIN
  SELECT p.authenticated_user_id, p.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) p;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_memberships om
    JOIN public.organizations o ON o.id = om.organization_id
    JOIN public.tenants t ON t.id = o.tenant_id
    JOIN public.tenant_memberships tm
      ON tm.tenant_id = t.id AND tm.user_id = _uid
    JOIN public.api_organization_client_enablements e
      ON e.tenant_id = t.id
     AND e.organization_id = o.id
     AND e.api_client_id = _client_id
    JOIN public.api_capability_grants g
      ON g.tenant_id = t.id
     AND g.organization_id = o.id
     AND g.api_client_id = _client_id
     AND g.workspace_id IS NULL
     AND g.api_version = 'v1'
     AND g.capability_kind = 'read'
     AND g.capability_key = 'me:read'
     AND g.lifecycle_status = 'enabled'
    WHERE om.user_id = _uid
      AND om.status = 'active'
      AND om.deactivated_at IS NULL
      AND tm.status = 'active'
      AND tm.deactivated_at IS NULL
      AND t.status = 'active'
      AND e.lifecycle_status = 'enabled'
  ) THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object('userId', _uid);
END;
$$;


--
-- Name: api_v1_get_me_context(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_me_context(_expected_oauth_client_id text, _context_type text DEFAULT NULL::text, _context_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT api_e_private.resolve_me_context(
    _expected_oauth_client_id,
    _context_type,
    _context_id
  );
$$;


--
-- Name: api_v1_get_phase(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_phase(_expected_oauth_client_id text, _phase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _project_id uuid;
  _tgt_ws_id uuid;
  _tgt_org_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _result jsonb;
BEGIN
  IF _phase_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT ph.project_id, ph.workspace_id, ph.organization_id
    INTO _project_id, _tgt_ws_id, _tgt_org_id
  FROM public.phases ph
  WHERE ph.id = _phase_id;

  IF _project_id IS NULL OR _tgt_ws_id IS NULL OR _tgt_org_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'phases:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'phases:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'phases:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL
     OR _org_id <> _tgt_org_id
     OR _ws_id <> _tgt_ws_id THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
           'phaseId', ph.id,
           'projectId', ph.project_id,
           'name', public.btpm_decrypt(ph.name, ph.organization_id),
           'description', public.btpm_decrypt(ph.description, ph.organization_id),
           'status', ph.status::text,
           'phaseType', ph.phase_type::text,
           'sortOrder', ph.sort_order,
           'startDate', ph.start_date,
           'targetEndDate', ph.target_end_date,
           'baselineStartDate', ph.baseline_start_date,
           'baselineEndDate', ph.baseline_end_date,
           'addedAfterBaseline', ph.added_after_baseline,
           'actualStartDate', ph.actual_start_date,
           'actualEndDate', ph.actual_end_date,
           'updatedAt', ph.updated_at
         )
    INTO _result
  FROM public.phases ph
  WHERE ph.id = _phase_id
    AND ph.project_id = _project_id
    AND ph.organization_id = _org_id
    AND ph.workspace_id = _ws_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_portfolio(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_portfolio(_expected_oauth_client_id text, _portfolio_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _tgt_org_id uuid;
  _tenant_id uuid;
  _result jsonb;
BEGIN
  IF _portfolio_item_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Authoritative Organization scope is derived from the target Portfolio only;
  -- it is never accepted from the caller.
  SELECT o.id, t.id
    INTO _tgt_org_id, _tenant_id
  FROM public.portfolio_items pi
  JOIN public.organizations o
    ON o.id = pi.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
   AND om.role::text = 'org_admin'
  WHERE pi.id = _portfolio_item_id
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.api_client_id = _client_id
        AND g.workspace_id IS NULL
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'portfolios:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tgt_org_id IS NULL OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
           'portfolioId', pi.id,
           'organizationId', pi.organization_id,
           'name', public.btpm_decrypt(pi.name, pi.organization_id),
           'code', public.btpm_decrypt(pi.code, pi.organization_id),
           'description', public.btpm_decrypt(pi.description, pi.organization_id),
           'lifecycleState', pi.lifecycle_state,
           'strategicPriority', pi.strategic_priority,
           'ownerId', pi.owner_id,
           'isArchived', pi.is_archived,
           'archivedAt', pi.archived_at,
           'createdAt', pi.created_at,
           'updatedAt', pi.updated_at
         )
    INTO _result
  FROM public.portfolio_items pi
  WHERE pi.id = _portfolio_item_id
    AND pi.organization_id = _tgt_org_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_program(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_program(_expected_oauth_client_id text, _program_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _tgt_ws_id uuid;
  _tgt_org_id uuid;
  _tenant_id uuid;
  _result jsonb;
BEGIN
  IF _program_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Authoritative scope is derived from the target Program only:
  -- Program -> Workspace -> Organization -> Tenant, with strict
  -- Program/Workspace Organization consistency.
  SELECT w.id, o.id, t.id
    INTO _tgt_ws_id, _tgt_org_id, _tenant_id
  FROM public.programs pg
  JOIN public.workspaces w
    ON w.id = pg.workspace_id
   AND w.organization_id = pg.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = w.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE pg.id = _program_id
    AND pg.is_archived = false
    AND (
      om.role::text = 'org_admin'
      OR EXISTS (
        SELECT 1 FROM public.workspace_memberships wm
        WHERE wm.workspace_id = w.id
          AND wm.user_id = _uid
      )
    )
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'programs:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tgt_ws_id IS NULL OR _tgt_org_id IS NULL OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
           'programId', pg.id,
           'organizationId', pg.organization_id,
           'workspaceId', pg.workspace_id,
           'name', public.btpm_decrypt(pg.name, pg.organization_id),
           'description', public.btpm_decrypt(pg.description, pg.organization_id),
           'status', pg.status::text,
           'createdAt', pg.created_at,
           'updatedAt', pg.updated_at
         )
    INTO _result
  FROM public.programs pg
  WHERE pg.id = _program_id
    AND pg.is_archived = false
    AND pg.workspace_id = _tgt_ws_id
    AND pg.organization_id = _tgt_org_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_project(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_project(_expected_oauth_client_id text, _project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _result jsonb;
BEGIN
  IF _project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
           'projectId', p.id,
           'organizationId', p.organization_id,
           'workspaceId', p.workspace_id,
           'programId', p.program_id,
           'portfolioItemId', p.portfolio_item_id,
           'name', public.btpm_decrypt(p.name, p.organization_id),
           'description', public.btpm_decrypt(p.description, p.organization_id),
           'status', p.status::text,
           'priority', p.priority::text,
           'projectStage', p.project_stage::text,
           'deliveryModel', p.delivery_model::text,
           'startDate', p.start_date,
           'targetEndDate', p.target_end_date,
           'actualStartDate', p.actual_start_date,
           'actualEndDate', p.actual_end_date,
           'agileEnabled', p.agile_enabled,
           'updatedAt', p.updated_at,
           'charter', public.btpm_decrypt(p.charter, p.organization_id),
           'goals', public.btpm_decrypt(p.goals, p.organization_id),
           'scopeIn', public.btpm_decrypt(p.scope_in, p.organization_id),
           'scopeOut', public.btpm_decrypt(p.scope_out, p.organization_id),
           'businessCase', public.btpm_decrypt(p.business_case, p.organization_id),
           'successCriteria', public.btpm_decrypt(p.success_criteria, p.organization_id),
           'completionCriteria', public.btpm_decrypt(p.completion_criteria, p.organization_id),
           'budgetNarrative', public.btpm_decrypt(p.budget_narrative, p.organization_id),
           'assumptions', public.btpm_decrypt(p.assumptions, p.organization_id),
           'constraints', public.btpm_decrypt(p.constraints, p.organization_id)
         )
    INTO _result
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'projects:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'projects:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'projects:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_project_planning(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_project_planning(_expected_oauth_client_id text, _project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _org_id uuid;
  _project jsonb;
  _phases jsonb;
  _tasks jsonb;
  _dependencies jsonb;
  _phase_ids uuid[];
  _task_ids uuid[];
  _object_ids uuid[];
BEGIN
  IF _project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Authorization + scope derivation from the target Project only. Tenant,
  -- Organization and Workspace are never taken from the caller.
  SELECT p.organization_id,
         jsonb_build_object(
           'projectId', p.id,
           'name', public.btpm_decrypt(p.name, p.organization_id),
           'startDate', p.start_date,
           'targetEndDate', p.target_end_date,
           'actualStartDate', p.actual_start_date,
           'actualEndDate', p.actual_end_date,
           'isBaselined', p.is_baselined
         )
    INTO _org_id, _project
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'planning:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'planning:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'planning:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _project IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Canonical planning set: non-archived Phases of the authorized Project,
  -- mirroring the current BTPM Gantt inclusion behavior.
  SELECT COALESCE(array_agg(ph.id), ARRAY[]::uuid[])
    INTO _phase_ids
  FROM public.phases ph
  WHERE ph.project_id = _project_id
    AND ph.is_archived = false;

  SELECT COALESCE(array_agg(t.id), ARRAY[]::uuid[])
    INTO _task_ids
  FROM public.tasks t
  WHERE t.project_id = _project_id
    AND t.is_archived = false
    AND t.phase_id = ANY (_phase_ids);

  _object_ids := _phase_ids || _task_ids;

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'phaseId', ph.id,
             'projectId', ph.project_id,
             'name', public.btpm_decrypt(ph.name, ph.organization_id),
             'status', ph.status::text,
             'phaseType', ph.phase_type::text,
             'sortOrder', ph.sort_order,
             'startDate', ph.start_date,
             'targetEndDate', ph.target_end_date,
             'baselineStartDate', ph.baseline_start_date,
             'baselineEndDate', ph.baseline_end_date,
             'addedAfterBaseline', ph.added_after_baseline,
             'actualStartDate', ph.actual_start_date,
             'actualEndDate', ph.actual_end_date,
             'updatedAt', ph.updated_at
           )
           ORDER BY ph.sort_order, ph.id
         ), '[]'::jsonb)
    INTO _phases
  FROM public.phases ph
  WHERE ph.id = ANY (_phase_ids);

  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'taskId', t.id,
             'projectId', t.project_id,
             'phaseId', t.phase_id,
             'name', public.btpm_decrypt(t.name, t.organization_id),
             'status', t.status::text,
             'priority', t.priority::text,
             'taskType', t.task_type::text,
             'sortOrder', t.sort_order,
             'startDate', t.start_date,
             'dueDate', t.due_date,
             'baselineStartDate', t.baseline_start_date,
             'baselineEndDate', t.baseline_end_date,
             'addedAfterBaseline', t.added_after_baseline,
             'actualStartDate', t.actual_start_date,
             'actualEndDate', t.actual_end_date,
             'updatedAt', t.updated_at
           )
           ORDER BY ph.sort_order, ph.id, t.sort_order, t.id
         ), '[]'::jsonb)
    INTO _tasks
  FROM public.tasks t
  JOIN public.phases ph
    ON ph.id = t.phase_id
  WHERE t.id = ANY (_task_ids);

  -- Dependency projection: both endpoints must belong to this authorized
  -- Project planning set, so no cross-Project identifier can leak.
  SELECT COALESCE(jsonb_agg(
           jsonb_build_object(
             'dependencyId', d.id,
             'sourceType', d.source_type,
             'sourceId', d.source_id,
             'targetType', d.target_type,
             'targetId', d.target_id,
             'dependencyType', d.dependency_type::text
           )
           ORDER BY d.source_id, d.target_id, d.id
         ), '[]'::jsonb)
    INTO _dependencies
  FROM public.dependencies d
  WHERE d.source_id = ANY (_object_ids)
    AND d.target_id = ANY (_object_ids);

  RETURN jsonb_build_object(
    'project', _project,
    'phases', _phases,
    'tasks', _tasks,
    'dependencies', _dependencies
  );
END;
$$;


--
-- Name: api_v1_get_risk(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_risk(_expected_oauth_client_id text, _risk_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _target_type text;
  _target_id uuid;
  _risk_org_id uuid;
  _risk_ws_id uuid;
  _derived_project_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _result jsonb;
BEGIN
  IF _risk_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT r.target_type, r.target_id, r.organization_id, r.workspace_id
    INTO _target_type, _target_id, _risk_org_id, _risk_ws_id
  FROM public.risks r
  WHERE r.id = _risk_id;

  IF _target_type IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _target_type = 'project' THEN
    _derived_project_id := _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT ph.project_id INTO _derived_project_id
    FROM public.phases ph
    WHERE ph.id = _target_id;
  ELSIF _target_type = 'task' THEN
    SELECT tk.project_id INTO _derived_project_id
    FROM public.tasks tk
    LEFT JOIN public.phases tph ON tph.id = tk.phase_id
    WHERE tk.id = _target_id
      AND (tk.phase_id IS NULL OR tph.project_id = tk.project_id);
  ELSE
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  IF _derived_project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _derived_project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'risks:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'risks:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'risks:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL
     OR _org_id <> _risk_org_id
     OR _ws_id <> _risk_ws_id THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
           'riskId', r.id,
           'projectId', _derived_project_id,
           'targetType', r.target_type,
           'targetId', r.target_id,
           'title', public.btpm_decrypt(r.title, r.organization_id),
           'description', public.btpm_decrypt(r.description, r.organization_id),
           'mitigationPlan', public.btpm_decrypt(r.mitigation_plan, r.organization_id),
           'likelihood', r.likelihood::text,
           'impact', r.impact::text,
           'status', r.status::text,
           'updatedAt', r.updated_at
         )
    INTO _result
  FROM public.risks r
  WHERE r.id = _risk_id
    AND r.organization_id = _org_id
    AND r.workspace_id = _ws_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_get_task(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_get_task(_expected_oauth_client_id text, _task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _project_id uuid;
  _phase_id uuid;
  _tgt_ws_id uuid;
  _tgt_org_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _assignee_id uuid;
  _result jsonb;
BEGIN
  IF _task_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT tk.project_id, tk.phase_id, tk.workspace_id, tk.organization_id
    INTO _project_id, _phase_id, _tgt_ws_id, _tgt_org_id
  FROM public.tasks tk
  LEFT JOIN public.phases tph ON tph.id = tk.phase_id
  WHERE tk.id = _task_id
    AND (
      tk.phase_id IS NULL
      OR (
        tph.project_id = tk.project_id
        AND tph.workspace_id = tk.workspace_id
        AND tph.organization_id = tk.organization_id
      )
    );

  IF _project_id IS NULL OR _tgt_ws_id IS NULL OR _tgt_org_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'tasks:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'tasks:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'tasks:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL
     OR _org_id <> _tgt_org_id
     OR _ws_id <> _tgt_ws_id THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT ta.assignee_id INTO _assignee_id
  FROM public.task_assignments ta
  WHERE ta.task_id = _task_id
  ORDER BY ta.created_at DESC
  LIMIT 1;

  SELECT jsonb_build_object(
           'taskId', tk.id,
           'projectId', tk.project_id,
           'phaseId', tk.phase_id,
           'name', public.btpm_decrypt(tk.name, tk.organization_id),
           'description', public.btpm_decrypt(tk.description, tk.organization_id),
           'status', tk.status::text,
           'priority', tk.priority::text,
           'taskType', tk.task_type::text,
           'sortOrder', tk.sort_order,
           'startDate', tk.start_date,
           'dueDate', tk.due_date,
           'baselineStartDate', tk.baseline_start_date,
           'baselineEndDate', tk.baseline_end_date,
           'addedAfterBaseline', tk.added_after_baseline,
           'actualStartDate', tk.actual_start_date,
           'actualEndDate', tk.actual_end_date,
           'estimatedHours', tk.estimated_hours,
           'assigneeId', _assignee_id,
           'updatedAt', tk.updated_at
         )
    INTO _result
  FROM public.tasks tk
  WHERE tk.id = _task_id
    AND tk.project_id = _project_id
    AND tk.organization_id = _org_id
    AND tk.workspace_id = _ws_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN _result;
END;
$$;


--
-- Name: api_v1_list_execution_updates(text, text, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_execution_updates(_expected_oauth_client_id text, _target_type text, _target_id uuid, _limit integer, _after_created_at timestamp with time zone, _after_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _project_id uuid;
  _tgt_ws_id uuid;
  _tgt_org_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _items jsonb;
  _next_created_at timestamptz;
  _next_id uuid;
BEGIN
  IF _target_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _target_type IS NULL OR _target_type NOT IN ('phase', 'task') THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 500 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF (_after_created_at IS NULL) <> (_after_id IS NULL) THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Authoritative target -> structural scope derivation from canonical hierarchy only.
  IF _target_type = 'phase' THEN
    SELECT ph.project_id, ph.workspace_id, ph.organization_id
      INTO _project_id, _tgt_ws_id, _tgt_org_id
    FROM public.phases ph
    WHERE ph.id = _target_id;
  ELSE
    SELECT tk.project_id, tk.workspace_id, tk.organization_id
      INTO _project_id, _tgt_ws_id, _tgt_org_id
    FROM public.tasks tk
    LEFT JOIN public.phases tph ON tph.id = tk.phase_id
    WHERE tk.id = _target_id
      AND (
        tk.phase_id IS NULL
        OR (
          tph.project_id = tk.project_id
          AND tph.workspace_id = tk.workspace_id
          AND tph.organization_id = tk.organization_id
        )
      );
  END IF;

  IF _project_id IS NULL OR _tgt_ws_id IS NULL OR _tgt_org_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'execution_updates:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'execution_updates:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'execution_updates:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL
     OR _org_id <> _tgt_org_id
     OR _ws_id <> _tgt_ws_id THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH candidate AS (
    SELECT eu.id,
           eu.created_at,
           eu.target_type,
           eu.target_id,
           eu.author_id,
           public.btpm_decrypt(eu.summary, eu.organization_id) AS summary,
           eu.status_label,
           eu.update_date
    FROM public.execution_updates eu
    WHERE eu.organization_id = _org_id
      AND eu.workspace_id = _ws_id
      AND eu.target_type = _target_type
      AND eu.target_id = _target_id
      AND (
        _after_created_at IS NULL
        OR (eu.created_at, eu.id) < (_after_created_at, _after_id)
      )
    ORDER BY eu.created_at DESC, eu.id DESC
    LIMIT _limit + 1
  ), numbered AS (
    SELECT c.*, row_number() OVER (ORDER BY c.created_at DESC, c.id DESC) AS rn
    FROM candidate c
  ), page AS (
    SELECT n.* FROM numbered n WHERE n.rn <= _limit
  )
  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'executionUpdateId', page.id,
               'targetType', page.target_type,
               'targetId', page.target_id,
               'authorId', page.author_id,
               'summary', page.summary,
               'statusLabel', page.status_label,
               'updateDate', page.update_date,
               'createdAt', page.created_at
             )
             ORDER BY page.rn
           ), '[]'::jsonb),
         CASE WHEN (SELECT count(*) FROM numbered) > _limit
              THEN (SELECT p2.created_at FROM page p2 ORDER BY p2.rn DESC LIMIT 1)
              ELSE NULL END,
         CASE WHEN (SELECT count(*) FROM numbered) > _limit
              THEN (SELECT p3.id FROM page p3 ORDER BY p3.rn DESC LIMIT 1)
              ELSE NULL END
    INTO _items, _next_created_at, _next_id
  FROM page;

  RETURN jsonb_build_object(
    'items', COALESCE(_items, '[]'::jsonb),
    'nextCursorCreatedAt', _next_created_at,
    'nextCursorId', _next_id
  );
END;
$$;


--
-- Name: api_v1_list_kpi_updates(text, uuid, integer, date, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_kpi_updates(_expected_oauth_client_id text, _kpi_id uuid, _limit integer, _after_update_date date, _after_created_at timestamp with time zone, _after_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _proj_id uuid;
  _kpi_def_id uuid;
  _rowcount integer;
  _cursor_supplied integer;
  _rows jsonb;
  _items jsonb;
  _has_more boolean;
  _last jsonb;
BEGIN
  -- 1. Strict input contract. No normalization, no repair.
  IF _kpi_id IS NULL
     OR _kpi_id = '00000000-0000-0000-0000-000000000000'::uuid
     OR _limit IS NULL
     OR _limit < 1
     OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  -- The keyset cursor triple is all-or-nothing.
  _cursor_supplied :=
      (CASE WHEN _after_update_date IS NULL THEN 0 ELSE 1 END)
    + (CASE WHEN _after_created_at IS NULL THEN 0 ELSE 1 END)
    + (CASE WHEN _after_id IS NULL THEN 0 ELSE 1 END);

  IF _cursor_supplied <> 0 AND _cursor_supplied <> 3 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  -- 2. Canonical delegated read principal (no duplicated OAuth/policy logic).
  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- 3. Server-derived KPI -> Project -> Workspace -> Organization -> Tenant scope
  --    plus the accepted external Project-read authority chain.
  SELECT kd.id, p.id, w.id, o.id, t.id
    INTO _kpi_def_id, _proj_id, _ws_id, _org_id, _tenant_id
  FROM public.kpi_definitions kd
  JOIN public.projects p
    ON p.id = kd.target_id
   AND p.is_archived = false
   AND p.workspace_id = kd.workspace_id
   AND p.organization_id = kd.organization_id
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE kd.id = _kpi_id
    AND kd.target_type = 'project'
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'kpis:read'
        AND sc.lifecycle_status = 'enabled'
    )
    -- API-ADM-UX2.2: exact enabled Workspace capability grant.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'kpis:read'
        AND g.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'kpis:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    );

  IF _kpi_def_id IS NULL
     OR _proj_id IS NULL OR _ws_id IS NULL OR _org_id IS NULL OR _tenant_id IS NULL THEN
    -- Missing KPI, malformed containment, unsupported target type, inaccessible
    -- Project and unauthorized caller are all indistinguishable.
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- 4. Bounded deterministic keyset page over canonical update rows only.
  SELECT COALESCE(jsonb_agg(row_json ORDER BY ord), '[]'::jsonb)
    INTO _rows
  FROM (
    SELECT
      row_number() OVER (
        ORDER BY ku.update_date DESC, ku.created_at DESC, ku.id DESC
      ) AS ord,
      jsonb_build_object(
        'kpiUpdateId', ku.id,
        'kpiId', ku.kpi_definition_id,
        'value', ku.value,
        'updateDate', ku.update_date,
        'note', CASE
                  WHEN ku.note IS NULL THEN NULL
                  ELSE public.btpm_decrypt(ku.note, ku.organization_id)
                END,
        'authorId', ku.author_id,
        'createdAt', ku.created_at
      ) AS row_json
    FROM public.kpi_updates ku
    WHERE ku.kpi_definition_id = _kpi_def_id
      AND ku.workspace_id = _ws_id
      AND ku.organization_id = _org_id
      AND (
        _after_id IS NULL
        OR (ku.update_date, ku.created_at, ku.id)
             < (_after_update_date, _after_created_at, _after_id)
      )
    ORDER BY ku.update_date DESC, ku.created_at DESC, ku.id DESC
    LIMIT (_limit + 1)
  ) page;

  _has_more := jsonb_array_length(_rows) > _limit;

  IF _has_more THEN
    SELECT COALESCE(jsonb_agg(elem ORDER BY idx), '[]'::jsonb)
      INTO _items
    FROM jsonb_array_elements(_rows) WITH ORDINALITY AS a(elem, idx)
    WHERE idx <= _limit;
  ELSE
    _items := _rows;
  END IF;

  IF _has_more AND jsonb_array_length(_items) > 0 THEN
    _last := _items -> (jsonb_array_length(_items) - 1);
    RETURN jsonb_build_object(
      'items', _items,
      'nextCursorUpdateDate', _last -> 'updateDate',
      'nextCursorCreatedAt', _last -> 'createdAt',
      'nextCursorId', _last -> 'kpiUpdateId'
    );
  END IF;

  RETURN jsonb_build_object(
    'items', _items,
    'nextCursorUpdateDate', NULL,
    'nextCursorCreatedAt', NULL,
    'nextCursorId', NULL
  );
END;
$$;


--
-- Name: api_v1_list_organizations(text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_organizations(_expected_oauth_client_id text, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;
  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  SELECT p.authenticated_user_id, p.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) p;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- API-G.5.13A-1 route-authority precheck: independent of _search.
  IF NOT EXISTS (
    SELECT 1
    FROM public.organizations o
    JOIN public.tenants t ON t.id = o.tenant_id AND t.status = 'active'
    JOIN public.tenant_memberships tm
      ON tm.tenant_id = t.id
     AND tm.user_id = _uid
     AND tm.status = 'active'
     AND tm.deactivated_at IS NULL
    JOIN public.organization_memberships om
      ON om.organization_id = o.id
     AND om.user_id = _uid
     AND om.status = 'active'
     AND om.deactivated_at IS NULL
    JOIN public.api_organization_client_enablements e
      ON e.tenant_id = t.id
     AND e.organization_id = o.id
     AND e.api_client_id = _client_id
     AND e.lifecycle_status = 'enabled'
    JOIN public.api_capability_grants g
      ON g.tenant_id = t.id
     AND g.organization_id = o.id
     AND g.api_client_id = _client_id
     AND g.workspace_id IS NULL
     AND g.api_version = 'v1'
     AND g.capability_kind = 'read'
     AND g.capability_key = 'organizations:list'
     AND g.lifecycle_status = 'enabled'
  ) THEN
    RAISE EXCEPTION 'api_v1_not_authorized'
      USING ERRCODE = '42501';
  END IF;

  WITH eligible AS (
    SELECT o.id AS organization_id, o.name AS name, om.role AS role
    FROM public.organizations o
    JOIN public.tenants t ON t.id = o.tenant_id AND t.status = 'active'
    JOIN public.tenant_memberships tm
      ON tm.tenant_id = t.id
     AND tm.user_id = _uid
     AND tm.status = 'active'
     AND tm.deactivated_at IS NULL
    JOIN public.organization_memberships om
      ON om.organization_id = o.id
     AND om.user_id = _uid
     AND om.status = 'active'
     AND om.deactivated_at IS NULL
    WHERE EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.api_client_id = _client_id
        AND g.workspace_id IS NULL
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'organizations:list'
        AND g.lifecycle_status = 'enabled'
    )
    AND (
      NOT _has_search
      OR position(lower(_search_trimmed) IN lower(o.name)) > 0
    )
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'organizationId', sub.organization_id,
          'name', sub.name,
          'role', sub.role
        )
        ORDER BY sub.name_lower, sub.organization_id
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      e.organization_id,
      e.name,
      e.role,
      lower(e.name) AS name_lower,
      row_number() OVER (ORDER BY lower(e.name), e.organization_id) AS rn
    FROM eligible e
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_portfolio_projects(text, uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_portfolio_projects(_expected_oauth_client_id text, _portfolio_item_id uuid, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _org_role text;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _portfolio_item_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Portfolio-level route-authority precheck. Organization and Tenant are
  -- derived from the requested Portfolio row; never from the caller.
  -- An archived Portfolio is still readable: existing Project assignments to
  -- archived Portfolios remain valid history.
  SELECT t.id, o.id, om.role::text
    INTO _tenant_id, _org_id, _org_role
  FROM public.portfolio_items pi
  JOIN public.organizations o
    ON o.id = pi.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
   AND om.role::text = 'org_admin'
  WHERE pi.id = _portfolio_item_id
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.api_client_id = _client_id
        AND g.workspace_id IS NULL
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'portfolios:list_projects'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tenant_id IS NULL OR _org_id IS NULL OR _org_role IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH eligible AS (
    SELECT
      p.id AS project_id,
      p.workspace_id,
      p.program_id,
      public.btpm_decrypt(p.name, p.organization_id) AS name,
      p.status::text AS status,
      p.priority::text AS priority,
      p.project_stage::text AS project_stage,
      p.delivery_model::text AS delivery_model,
      p.start_date,
      p.target_end_date,
      p.updated_at
    FROM public.projects p
    JOIN public.workspaces w
      ON w.id = p.workspace_id
     AND w.organization_id = _org_id
     AND w.is_active = true
     AND w.is_archived = false
    WHERE p.portfolio_item_id = _portfolio_item_id
      AND p.organization_id = _org_id
      AND p.is_archived = false
      AND public.has_project_access(_uid, p.id)
      AND EXISTS (
        SELECT 1 FROM public.api_workspace_client_enablements we
        WHERE we.tenant_id = _tenant_id
          AND we.organization_id = _org_id
          AND we.workspace_id = p.workspace_id
          AND we.api_client_id = _client_id
          AND we.lifecycle_status = 'enabled'
      )
      AND EXISTS (
        SELECT 1 FROM public.api_project_client_enablements pe
        WHERE pe.tenant_id = _tenant_id
          AND pe.organization_id = _org_id
          AND pe.workspace_id = p.workspace_id
          AND pe.project_id = p.id
          AND pe.api_client_id = _client_id
          AND pe.lifecycle_status = 'enabled'
          AND pe.enabled_at IS NOT NULL
          AND pe.disabled_at IS NULL
      )
  ),
  filtered AS (
    SELECT e.*
    FROM eligible e
    WHERE NOT _has_search
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.name, ''))) > 0
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'projectId', sub.project_id,
          'workspaceId', sub.workspace_id,
          'programId', sub.program_id,
          'name', sub.name,
          'status', sub.status,
          'priority', sub.priority,
          'projectStage', sub.project_stage,
          'deliveryModel', sub.delivery_model,
          'startDate', sub.start_date,
          'targetEndDate', sub.target_end_date,
          'updatedAt', sub.updated_at
        )
        ORDER BY sub.rn
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      f.*,
      row_number() OVER (ORDER BY lower(COALESCE(f.name, '')), f.project_id) AS rn
    FROM filtered f
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_portfolios(text, uuid, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_portfolios(_expected_oauth_client_id text, _organization_id uuid, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text, _include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_role text;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _include boolean := COALESCE(_include_archived, false);
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Organization-level route-authority precheck. Portfolio master data keeps
  -- its existing Organization Administrator authority; this step does not
  -- widen Portfolio authority.
  SELECT t.id, om.role::text
    INTO _tenant_id, _org_role
  FROM public.organizations o
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
   AND om.role::text = 'org_admin'
  WHERE o.id = _organization_id
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.api_client_id = _client_id
        AND g.workspace_id IS NULL
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'portfolios:list'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tenant_id IS NULL OR _org_role IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH eligible AS (
    SELECT
      pi.id AS portfolio_id,
      pi.organization_id,
      public.btpm_decrypt(pi.name, pi.organization_id) AS name,
      public.btpm_decrypt(pi.code, pi.organization_id) AS code,
      pi.lifecycle_state,
      pi.strategic_priority,
      pi.owner_id,
      pi.is_archived,
      pi.updated_at
    FROM public.portfolio_items pi
    WHERE pi.organization_id = _organization_id
      AND (_include OR pi.is_archived = false)
  ),
  filtered AS (
    SELECT e.*
    FROM eligible e
    WHERE NOT _has_search
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.name, ''))) > 0
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'portfolioId', sub.portfolio_id,
          'organizationId', sub.organization_id,
          'name', sub.name,
          'code', sub.code,
          'lifecycleState', sub.lifecycle_state,
          'strategicPriority', sub.strategic_priority,
          'ownerId', sub.owner_id,
          'isArchived', sub.is_archived,
          'updatedAt', sub.updated_at
        )
        ORDER BY sub.rn
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      f.*,
      row_number() OVER (ORDER BY lower(COALESCE(f.name, '')), f.portfolio_id) AS rn
    FROM filtered f
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_programs(text, uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_programs(_expected_oauth_client_id text, _workspace_id uuid, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _workspace_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Authoritative Workspace-level route-authority precheck: independent of
  -- _search and of whether any Program row would be returned.
  SELECT t.id, o.id
    INTO _tenant_id, _org_id
  FROM public.workspaces w
  JOIN public.organizations o
    ON o.id = w.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE w.id = _workspace_id
    AND w.is_active = true
    AND w.is_archived = false
    AND (
      om.role::text = 'org_admin'
      OR EXISTS (
        SELECT 1 FROM public.workspace_memberships wm
        WHERE wm.workspace_id = w.id
          AND wm.user_id = _uid
      )
    )
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'programs:list'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tenant_id IS NULL OR _org_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH eligible AS (
    SELECT
      pg.id AS program_id,
      pg.organization_id,
      pg.workspace_id,
      public.btpm_decrypt(pg.name, pg.organization_id) AS name,
      pg.status::text AS status,
      pg.created_at,
      pg.updated_at
    FROM public.programs pg
    WHERE pg.workspace_id = _workspace_id
      AND pg.organization_id = _org_id
      AND pg.is_archived = false
  ),
  filtered AS (
    SELECT e.*
    FROM eligible e
    WHERE NOT _has_search
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.name, ''))) > 0
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'programId', sub.program_id,
          'organizationId', sub.organization_id,
          'workspaceId', sub.workspace_id,
          'name', sub.name,
          'status', sub.status,
          'createdAt', sub.created_at,
          'updatedAt', sub.updated_at
        )
        ORDER BY sub.rn
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      f.*,
      row_number() OVER (ORDER BY lower(COALESCE(f.name, '')), f.program_id) AS rn
    FROM filtered f
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_project_blockers(text, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_project_blockers(_expected_oauth_client_id text, _project_id uuid, _limit integer, _after_created_at timestamp with time zone, _after_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _org_id uuid;
  _ws_id uuid;
  _items jsonb;
  _next_created_at timestamptz;
  _next_id uuid;
BEGIN
  IF _project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 500 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF (_after_created_at IS NULL) <> (_after_id IS NULL) THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'blockers:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'blockers:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'blockers:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH candidate AS (
    SELECT b.id,
           b.created_at,
           b.target_type,
           b.target_id,
           public.btpm_decrypt(b.title, b.organization_id) AS title,
           public.btpm_decrypt(b.description, b.organization_id) AS description,
           b.severity,
           b.status,
           b.resolved_at,
           b.updated_at,
           b.resolved_by
    FROM public.blockers b
    WHERE b.organization_id = _org_id
      AND b.workspace_id = _ws_id
      AND (
        (b.target_type = 'project' AND b.target_id = _project_id)
        OR (b.target_type = 'phase' AND EXISTS (
              SELECT 1 FROM public.phases ph
              WHERE ph.id = b.target_id
                AND ph.project_id = _project_id
            ))
        OR (b.target_type = 'task' AND EXISTS (
              SELECT 1 FROM public.tasks tk
              LEFT JOIN public.phases tph ON tph.id = tk.phase_id
              WHERE tk.id = b.target_id
                AND tk.project_id = _project_id
                AND (tk.phase_id IS NULL OR tph.project_id = _project_id)
            ))
      )
      AND (
        _after_created_at IS NULL
        OR (b.created_at, b.id) < (_after_created_at, _after_id)
      )
    ORDER BY b.created_at DESC, b.id DESC
    LIMIT _limit + 1
  ), numbered AS (
    SELECT c.*, row_number() OVER (ORDER BY c.created_at DESC, c.id DESC) AS rn
    FROM candidate c
  ), page AS (
    SELECT n.* FROM numbered n WHERE n.rn <= _limit
  )
  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'blockerId', page.id,
               'projectId', _project_id,
               'targetType', page.target_type,
               'targetId', page.target_id,
               'title', page.title,
               'description', page.description,
               'severity', page.severity::text,
               'status', page.status::text,
               'resolvedAt', page.resolved_at,
               'updatedAt', page.updated_at,
               'resolvedBy', page.resolved_by
             )
             ORDER BY page.rn
           ), '[]'::jsonb),
         CASE WHEN (SELECT count(*) FROM numbered) > _limit
              THEN (SELECT p2.created_at FROM page p2 ORDER BY p2.rn DESC LIMIT 1)
              ELSE NULL END,
         CASE WHEN (SELECT count(*) FROM numbered) > _limit
              THEN (SELECT p3.id FROM page p3 ORDER BY p3.rn DESC LIMIT 1)
              ELSE NULL END
    INTO _items, _next_created_at, _next_id
  FROM page;

  RETURN jsonb_build_object(
    'items', COALESCE(_items, '[]'::jsonb),
    'nextCursorCreatedAt', _next_created_at,
    'nextCursorId', _next_id
  );
END;
$$;


--
-- Name: api_v1_list_project_kpis(text, uuid, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_project_kpis(_expected_oauth_client_id text, _project_id uuid, _limit integer, _offset integer, _include_archived boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _ws_id uuid;
  _proj_id uuid;
  _rowcount integer;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  -- 1. Strict input contract. No normalization, no repair.
  IF _project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _include_archived IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  -- 2. Canonical delegated read principal (no duplicated OAuth/policy logic).
  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- 3. Server-derived Project -> Workspace -> Organization -> Tenant scope
  --    plus the established external Project-read posture.
  SELECT p.id, w.id, o.id, t.id
    INTO _proj_id, _ws_id, _org_id, _tenant_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'kpis:read'
        AND sc.lifecycle_status = 'enabled'
    )
    -- API-ADM-UX2.2: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'kpis:read'
        AND g.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'kpis:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    );

  IF _proj_id IS NULL OR _ws_id IS NULL OR _org_id IS NULL OR _tenant_id IS NULL THEN
    -- Missing Project and unauthorized Project are indistinguishable.
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- 4. Contained KPI read + exact frozen external projection.
  WITH eligible AS (
    SELECT
      k.id,
      k.name,
      public.btpm_decrypt(k.description, k.organization_id) AS description,
      k.unit,
      k.target_value,
      k.current_value,
      k.target_direction,
      k.source_mode,
      k.value_type,
      k.cadence,
      k.calculation_key,
      k.formula_version,
      k.completion_method,
      k.comment_required,
      k.action_plan_required,
      k.auto_snapshot_enabled,
      k.is_archived,
      k.created_at,
      k.updated_at
    FROM public.kpi_definitions k
    WHERE k.target_type = 'project'
      AND k.target_id = _proj_id
      AND k.workspace_id = _ws_id
      AND k.organization_id = _org_id
      AND (_include_archived OR k.is_archived = false)
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'kpiId', sub.id,
          'projectId', _proj_id,
          'name', sub.name,
          'description', sub.description,
          'unit', sub.unit,
          'targetValue', sub.target_value,
          'currentValue', sub.current_value,
          'targetDirection', sub.target_direction::text,
          'sourceMode', sub.source_mode,
          'valueType', sub.value_type,
          'cadence', sub.cadence,
          'calculationKey', sub.calculation_key,
          'formulaVersion', sub.formula_version,
          'completionMethod', sub.completion_method,
          'commentRequired', sub.comment_required,
          'actionPlanRequired', sub.action_plan_required,
          'autoSnapshotEnabled', sub.auto_snapshot_enabled,
          'isArchived', sub.is_archived,
          'createdAt', sub.created_at,
          'updatedAt', sub.updated_at
        )
        ORDER BY sub.rn
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT e.*,
           row_number() OVER (ORDER BY e.is_archived ASC, e.created_at ASC, e.id ASC) AS rn
    FROM eligible e
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_project_risks(text, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_project_risks(_expected_oauth_client_id text, _project_id uuid, _limit integer, _after_created_at timestamp with time zone, _after_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _rowcount integer;
  _org_id uuid;
  _ws_id uuid;
  _items jsonb;
  _next_created_at timestamptz;
  _next_id uuid;
BEGIN
  IF _project_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 500 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF (_after_created_at IS NULL) <> (_after_id IS NULL) THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id, p.workspace_id
    INTO _org_id, _ws_id
  FROM public.projects p
  JOIN public.workspaces w
    ON w.id = p.workspace_id
   AND w.organization_id = p.organization_id
   AND w.is_active = true
   AND w.is_archived = false
  JOIN public.organizations o
    ON o.id = p.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE p.id = _project_id
    AND p.is_archived = false
    AND public.has_project_access(_uid, p.id)
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_project_client_enablements pe
      WHERE pe.tenant_id = t.id
        AND pe.organization_id = o.id
        AND pe.workspace_id = w.id
        AND pe.project_id = p.id
        AND pe.api_client_id = _client_id
        AND pe.lifecycle_status = 'enabled'
        AND pe.enabled_at IS NOT NULL
        AND pe.disabled_at IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.api_client_supported_capabilities sc
      WHERE sc.api_client_id = _client_id
        AND sc.api_version = 'v1'
        AND sc.capability_kind = 'read'
        AND sc.capability_key = 'risks:read'
        AND sc.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_catalogue cc
      WHERE cc.api_version = 'v1'
        AND cc.capability_kind = 'read'
        AND cc.capability_key = 'risks:read'
        AND cc.scope_level = 'project'
        AND cc.lifecycle_status = 'active'
    )
    -- API-ADM-UX2.2-C1: exact enabled Workspace capability grant. An
    -- Organization grant (workspace_id IS NULL) is never sufficient.
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'risks:read'
        AND g.lifecycle_status = 'enabled'
    );

  IF _org_id IS NULL OR _ws_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH candidate AS (
    SELECT r.id,
           r.created_at,
           r.target_type,
           r.target_id,
           public.btpm_decrypt(r.title, r.organization_id) AS title,
           public.btpm_decrypt(r.description, r.organization_id) AS description,
           public.btpm_decrypt(r.mitigation_plan, r.organization_id) AS mitigation_plan,
           r.likelihood,
           r.impact,
           r.status,
           r.updated_at
    FROM public.risks r
    WHERE r.organization_id = _org_id
      AND r.workspace_id = _ws_id
      AND (
        (r.target_type = 'project' AND r.target_id = _project_id)
        OR (r.target_type = 'phase' AND EXISTS (
              SELECT 1 FROM public.phases ph
              WHERE ph.id = r.target_id
                AND ph.project_id = _project_id
            ))
        OR (r.target_type = 'task' AND EXISTS (
              SELECT 1 FROM public.tasks tk
              LEFT JOIN public.phases tph ON tph.id = tk.phase_id
              WHERE tk.id = r.target_id
                AND tk.project_id = _project_id
                AND (tk.phase_id IS NULL OR tph.project_id = _project_id)
            ))
      )
      AND (
        _after_created_at IS NULL
        OR (r.created_at, r.id) < (_after_created_at, _after_id)
      )
    ORDER BY r.created_at DESC, r.id DESC
    LIMIT _limit + 1
  ), numbered AS (
    SELECT c.*, row_number() OVER (ORDER BY c.created_at DESC, c.id DESC) AS rn
    FROM candidate c
  ), page AS (
    SELECT n.* FROM numbered n WHERE n.rn <= _limit
  )
  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'riskId', page.id,
               'projectId', _project_id,
               'targetType', page.target_type,
               'targetId', page.target_id,
               'title', page.title,
               'description', page.description,
               'mitigationPlan', page.mitigation_plan,
               'likelihood', page.likelihood::text,
               'impact', page.impact::text,
               'status', page.status::text,
               'updatedAt', page.updated_at
             )
             ORDER BY page.rn
           ), '[]'::jsonb),
         CASE WHEN (SELECT count(*) FROM numbered) > _limit
              THEN (SELECT p2.created_at FROM page p2 ORDER BY p2.rn DESC LIMIT 1)
              ELSE NULL END,
         CASE WHEN (SELECT count(*) FROM numbered) > _limit
              THEN (SELECT p3.id FROM page p3 ORDER BY p3.rn DESC LIMIT 1)
              ELSE NULL END
    INTO _items, _next_created_at, _next_id
  FROM page;

  RETURN jsonb_build_object(
    'items', COALESCE(_items, '[]'::jsonb),
    'nextCursorCreatedAt', _next_created_at,
    'nextCursorId', _next_id
  );
END;
$$;


--
-- Name: api_v1_list_projects(text, uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_projects(_expected_oauth_client_id text, _workspace_id uuid, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _workspace_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  SELECT p.authenticated_user_id, p.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) p;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Workspace-level route-authority precheck: independent of _search, pagination and results.
  SELECT t.id, o.id
    INTO _tenant_id, _org_id
  FROM public.workspaces w
  JOIN public.organizations o
    ON o.id = w.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE w.id = _workspace_id
    AND w.is_active = true
    AND w.is_archived = false
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'projects:list'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tenant_id IS NULL OR _org_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH eligible AS (
    SELECT
      p.id AS project_id,
      p.program_id AS program_id,
      p.status::text AS status,
      p.priority::text AS priority,
      p.project_stage::text AS project_stage,
      p.delivery_model::text AS delivery_model,
      p.start_date AS start_date,
      p.target_end_date AS target_end_date,
      p.agile_enabled AS agile_enabled,
      p.updated_at AS updated_at,
      public.btpm_decrypt(p.name, p.organization_id) AS name
    FROM public.projects p
    WHERE p.workspace_id = _workspace_id
      AND p.organization_id = _org_id
      AND p.is_archived = false
      AND public.has_project_access(_uid, p.id)
      -- API-HR.2-C1: per-row Connected App Project enablement containment.
      AND EXISTS (
        SELECT 1 FROM public.api_project_client_enablements pe
        WHERE pe.tenant_id = _tenant_id
          AND pe.organization_id = _org_id
          AND pe.workspace_id = _workspace_id
          AND pe.project_id = p.id
          AND pe.api_client_id = _client_id
          AND pe.lifecycle_status = 'enabled'
          AND pe.enabled_at IS NOT NULL
          AND pe.disabled_at IS NULL
      )
  ),
  filtered AS (
    SELECT e.*
    FROM eligible e
    WHERE NOT _has_search
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.name, ''))) > 0
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'projectId', sub.project_id,
          'organizationId', _org_id,
          'workspaceId', _workspace_id,
          'programId', sub.program_id,
          'name', sub.name,
          'status', sub.status,
          'priority', sub.priority,
          'projectStage', sub.project_stage,
          'deliveryModel', sub.delivery_model,
          'startDate', sub.start_date,
          'targetEndDate', sub.target_end_date,
          'agileEnabled', sub.agile_enabled,
          'updatedAt', sub.updated_at
        )
        ORDER BY sub.name_lower, sub.project_id
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      f.*,
      lower(COALESCE(f.name, '')) AS name_lower,
      row_number() OVER (ORDER BY lower(COALESCE(f.name, '')), f.project_id) AS rn
    FROM filtered f
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_workspace_members(text, uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_workspace_members(_expected_oauth_client_id text, _workspace_id uuid, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_id uuid;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _workspace_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  -- Accepted delegated API-v1 read-principal resolution. Caller-supplied
  -- actor / client / Tenant / Organization identity is never trusted.
  SELECT r.authenticated_user_id, r.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) r;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Authoritative Workspace-level route-authority precheck (unchanged).
  -- Workspace -> Organization -> Tenant is derived server-side. A missing,
  -- foreign, inactive or inaccessible Workspace fails through this same
  -- bounded not-authorized path and never discloses existence.
  SELECT t.id, o.id
    INTO _tenant_id, _org_id
  FROM public.workspaces w
  JOIN public.organizations o
    ON o.id = w.organization_id
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE w.id = _workspace_id
    AND w.is_active = true
    AND w.is_archived = false
    AND (
      om.role::text = 'org_admin'
      OR EXISTS (
        SELECT 1 FROM public.workspace_memberships wm
        WHERE wm.workspace_id = w.id
          AND wm.user_id = _uid
      )
    )
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements oe
      WHERE oe.tenant_id = t.id
        AND oe.organization_id = o.id
        AND oe.api_client_id = _client_id
        AND oe.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_workspace_client_enablements we
      WHERE we.tenant_id = t.id
        AND we.organization_id = o.id
        AND we.workspace_id = w.id
        AND we.api_client_id = _client_id
        AND we.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.workspace_id = w.id
        AND g.api_client_id = _client_id
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'workspace_members:list'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tenant_id IS NULL OR _org_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- WML-1A-C1: returned members require exact Workspace membership, an active
  -- profile, ACTIVE Tenant membership for the resolved Tenant, and ACTIVE
  -- Organization membership for the resolved Tenant/Organization.
  -- profiles.organization_id is NOT an authority test here; it is used only as
  -- the accepted protected-field decryption context.
  WITH eligible AS (
    SELECT
      p.id AS user_id,
      CASE
        WHEN p.organization_id IS NOT NULL AND p.display_name IS NOT NULL
          THEN public.btpm_decrypt(p.display_name, p.organization_id)
        ELSE p.display_name
      END AS display_name,
      CASE
        WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
          THEN public.btpm_decrypt(p.email, p.organization_id)
        ELSE p.email
      END AS email
    FROM public.workspace_memberships wm
    JOIN public.profiles p
      ON p.id = wm.user_id
    WHERE wm.workspace_id = _workspace_id
      AND p.is_active = true
      AND EXISTS (
        SELECT 1 FROM public.tenant_memberships mtm
        WHERE mtm.tenant_id = _tenant_id
          AND mtm.user_id = p.id
          AND mtm.status = 'active'
          AND mtm.deactivated_at IS NULL
      )
      AND EXISTS (
        SELECT 1 FROM public.organization_memberships mom
        WHERE mom.tenant_id = _tenant_id
          AND mom.organization_id = _org_id
          AND mom.user_id = p.id
          AND mom.status = 'active'
          AND mom.deactivated_at IS NULL
      )
  ),
  filtered AS (
    SELECT e.user_id, e.display_name, e.email
    FROM eligible e
    WHERE NOT _has_search
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.display_name, ''))) > 0
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.email, ''))) > 0
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'userId', sub.user_id,
          'displayName', sub.display_name,
          'email', sub.email
        )
        ORDER BY sub.display_name_lower, sub.email_lower, sub.user_id
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      f.user_id,
      f.display_name,
      f.email,
      lower(COALESCE(f.display_name, '')) AS display_name_lower,
      lower(COALESCE(f.email, '')) AS email_lower,
      row_number() OVER (
        ORDER BY
          lower(COALESCE(f.display_name, '')),
          lower(COALESCE(f.email, '')),
          f.user_id
      ) AS rn
    FROM filtered f
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


--
-- Name: api_v1_list_workspaces(text, uuid, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_v1_list_workspaces(_expected_oauth_client_id text, _organization_id uuid, _limit integer DEFAULT 50, _offset integer DEFAULT 0, _search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  _uid uuid;
  _client_id uuid;
  _tenant_id uuid;
  _org_role text;
  _rowcount integer;
  _search_trimmed text;
  _has_search boolean := false;
  _total integer := 0;
  _items jsonb := '[]'::jsonb;
BEGIN
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _limit IS NULL OR _limit < 1 OR _limit > 100 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _offset IS NULL OR _offset < 0 OR _offset > 10000 THEN
    RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
  END IF;

  IF _search IS NOT NULL THEN
    _search_trimmed := btrim(_search);
    IF length(_search_trimmed) = 0 THEN
      _has_search := false;
    ELSE
      IF length(_search_trimmed) > 100 THEN
        RAISE EXCEPTION 'api_v1_invalid_request' USING ERRCODE = '22023';
      END IF;
      _has_search := true;
    END IF;
  END IF;

  SELECT p.authenticated_user_id, p.api_client_id
    INTO _uid, _client_id
  FROM api_e_private.resolve_delegated_read_principal(_expected_oauth_client_id) p;

  GET DIAGNOSTICS _rowcount = ROW_COUNT;
  IF _rowcount <> 1 OR _uid IS NULL OR _client_id IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Organization-level route-authority precheck: independent of _search and of results.
  SELECT t.id, om.role::text
    INTO _tenant_id, _org_role
  FROM public.organizations o
  JOIN public.tenants t
    ON t.id = o.tenant_id
   AND t.status = 'active'
   AND t.suspended_at IS NULL
   AND t.archived_at IS NULL
   AND t.purged_at IS NULL
  JOIN public.tenant_memberships tm
    ON tm.tenant_id = t.id
   AND tm.user_id = _uid
   AND tm.status = 'active'
   AND tm.deactivated_at IS NULL
  JOIN public.organization_memberships om
    ON om.organization_id = o.id
   AND om.user_id = _uid
   AND om.status = 'active'
   AND om.deactivated_at IS NULL
  WHERE o.id = _organization_id
    AND EXISTS (
      SELECT 1 FROM public.api_organization_client_enablements e
      WHERE e.tenant_id = t.id
        AND e.organization_id = o.id
        AND e.api_client_id = _client_id
        AND e.lifecycle_status = 'enabled'
    )
    AND EXISTS (
      SELECT 1 FROM public.api_capability_grants g
      WHERE g.tenant_id = t.id
        AND g.organization_id = o.id
        AND g.api_client_id = _client_id
        AND g.workspace_id IS NULL
        AND g.api_version = 'v1'
        AND g.capability_kind = 'read'
        AND g.capability_key = 'workspaces:list'
        AND g.lifecycle_status = 'enabled'
    );

  IF _tenant_id IS NULL OR _org_role IS NULL THEN
    RAISE EXCEPTION 'api_v1_not_authorized' USING ERRCODE = '42501';
  END IF;

  WITH eligible AS (
    SELECT
      w.id AS workspace_id,
      public.btpm_decrypt(w.name, _organization_id) AS name
    FROM public.workspaces w
    WHERE w.organization_id = _organization_id
      AND w.is_active = true
      AND w.is_archived = false
      AND EXISTS (
        SELECT 1 FROM public.api_workspace_client_enablements we
        WHERE we.tenant_id = _tenant_id
          AND we.organization_id = _organization_id
          AND we.workspace_id = w.id
          AND we.api_client_id = _client_id
          AND we.lifecycle_status = 'enabled'
      )
      AND (
        _org_role = 'org_admin'
        OR EXISTS (
          SELECT 1 FROM public.workspace_memberships wm
          WHERE wm.workspace_id = w.id
            AND wm.user_id = _uid
        )
      )
  ),
  filtered AS (
    SELECT e.workspace_id, e.name
    FROM eligible e
    WHERE NOT _has_search
       OR position(lower(_search_trimmed) IN lower(COALESCE(e.name, ''))) > 0
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'workspaceId', sub.workspace_id,
          'organizationId', _organization_id,
          'name', sub.name
        )
        ORDER BY sub.name_lower, sub.workspace_id
      ) FILTER (WHERE sub.rn > _offset AND sub.rn <= _offset + _limit),
      '[]'::jsonb
    )
  INTO _total, _items
  FROM (
    SELECT
      f.workspace_id,
      f.name,
      lower(COALESCE(f.name, '')) AS name_lower,
      row_number() OVER (ORDER BY lower(COALESCE(f.name, '')), f.workspace_id) AS rn
    FROM filtered f
  ) sub;

  RETURN jsonb_build_object(
    'items', _items,
    'pagination', jsonb_build_object(
      'limit', _limit,
      'offset', _offset,
      'returned', jsonb_array_length(_items),
      'total', _total
    )
  );
END;
$$;


