CREATE FUNCTION public.disable_sharepoint_org_site(_connection_id uuid) RETURNS public.sharepoint_org_site_connections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.sharepoint_org_site_connections;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;
  SELECT * INTO v_row FROM public.sharepoint_org_site_connections WHERE id = _connection_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF NOT public.is_org_admin(auth.uid(), v_row.organization_id) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  UPDATE public.sharepoint_org_site_connections
  SET connection_status = 'disabled',
      disabled_at = now(),
      disabled_by = auth.uid()
  WHERE id = _connection_id
  RETURNING * INTO v_row;
  RETURN v_row;
END
$$;


