--
-- Name: enforce_completed_project_child_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_completed_project_child_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_project uuid;
  v_new_project uuid;
BEGIN
  IF TG_OP IN ('UPDATE','DELETE') THEN
    IF TG_TABLE_NAME IN ('phases','tasks') THEN
      v_old_project := OLD.project_id;
    ELSE
      v_old_project := public.resolve_child_project_scope(
        TG_TABLE_NAME, OLD.target_type, OLD.target_id, NULL);
    END IF;
    IF v_old_project IS NOT NULL AND public.is_project_completed(v_old_project) THEN
      RAISE EXCEPTION
        'BTPM_PROJECT_COMPLETED_READONLY: parent project is Completed and read-only; reopen before changing %', TG_TABLE_NAME
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF TG_OP IN ('INSERT','UPDATE') THEN
    IF TG_TABLE_NAME IN ('phases','tasks') THEN
      v_new_project := NEW.project_id;
    ELSE
      v_new_project := public.resolve_child_project_scope(
        TG_TABLE_NAME, NEW.target_type, NEW.target_id, NULL);
    END IF;
    IF v_new_project IS NOT NULL AND public.is_project_completed(v_new_project) THEN
      RAISE EXCEPTION
        'BTPM_PROJECT_COMPLETED_READONLY: parent project is Completed and read-only; reopen before changing %', TG_TABLE_NAME
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: enforce_dependency_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_dependency_schedule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pred_dates record;
  succ_dates record;
BEGIN
  -- Only enforce for FS (the only active type in v1).
  IF NEW.dependency_type <> 'finish_to_start' THEN
    RETURN NEW;
  END IF;

  -- Canonical: source = predecessor, target = successor.
  SELECT * INTO pred_dates FROM public.btpm_get_entity_dates(NEW.source_type, NEW.source_id);
  SELECT * INTO succ_dates FROM public.btpm_get_entity_dates(NEW.target_type, NEW.target_id);

  IF public.btpm_fs_pair_conflict(pred_dates.end_date, succ_dates.start_date) THEN
    RAISE EXCEPTION
      'BTPM_DEP_CREATE_CONFLICT: cannot create dependency — % (ends %) must finish on or before % starts (currently %)',
      COALESCE(pred_dates.name,'predecessor'), pred_dates.end_date,
      COALESCE(succ_dates.name,'successor'),   succ_dates.start_date
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_entity_schedule_phase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_entity_schedule_phase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  conflict record;
BEGIN
  IF NEW.start_date IS NOT DISTINCT FROM OLD.start_date
     AND NEW.target_end_date IS NOT DISTINCT FROM OLD.target_end_date THEN
    RETURN NEW;
  END IF;

  SELECT * INTO conflict
  FROM public.btpm_check_entity_schedule('phase', NEW.id, NEW.start_date, NEW.target_end_date)
  LIMIT 1;

  IF conflict.side = 'successor' THEN
    RAISE EXCEPTION
      'BTPM_DEP_CONFLICT_SUCC: cannot move "%": predecessor "%" must finish (ends %) on or before this item starts (would be %)',
      NEW.name, conflict.other_name, conflict.other_end, NEW.start_date
      USING ERRCODE = 'check_violation';
  ELSIF conflict.side = 'predecessor' THEN
    RAISE EXCEPTION
      'BTPM_DEP_CONFLICT_PRED: cannot move "%": successor "%" starts % which is before this item would finish (%)',
      NEW.name, conflict.other_name, conflict.other_start, NEW.target_end_date
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_entity_schedule_project(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_entity_schedule_project() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
