--
-- Name: enforce_entity_schedule_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_entity_schedule_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  conflict record;
BEGIN
  IF NEW.start_date IS NOT DISTINCT FROM OLD.start_date
     AND NEW.due_date IS NOT DISTINCT FROM OLD.due_date THEN
    RETURN NEW;
  END IF;

  -- Coordinated phase-level moves shift many sibling tasks atomically.
  -- Per-row validation would see stale sibling dates and false-positive.
  -- The caller is responsible for re-validating after the statement.
  IF current_setting('app.allow_coordinated_shift', true) = 'on' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO conflict
  FROM public.btpm_check_entity_schedule('task', NEW.id, NEW.start_date, NEW.due_date)
  LIMIT 1;

  IF conflict.side = 'successor' THEN
    RAISE EXCEPTION
      'BTPM_DEP_CONFLICT_SUCC: cannot move "%": predecessor "%" must finish (ends %) on or before this item starts (would be %)',
      NEW.name, conflict.other_name, conflict.other_end, NEW.start_date
      USING ERRCODE = 'check_violation';
  ELSIF conflict.side = 'predecessor' THEN
    RAISE EXCEPTION
      'BTPM_DEP_CONFLICT_PRED: cannot move "%": successor "%" starts % which is before this item would finish (%)',
      NEW.name, conflict.other_name, conflict.other_start, NEW.due_date
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_invitation_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_invitation_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_tenant uuid; _ws_org uuid; _ws_org_tenant uuid;
BEGIN
  IF NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Invitation tenant_id is required';
  END IF;

  IF NEW.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = NEW.organization_id;
    IF _org_tenant IS NULL THEN RAISE EXCEPTION 'Invitation organization not found'; END IF;
    IF NEW.tenant_id IS DISTINCT FROM _org_tenant THEN
      RAISE EXCEPTION 'Invitation tenant_id must match organization tenant';
    END IF;
  END IF;

  IF NEW.workspace_id IS NOT NULL THEN
    SELECT organization_id INTO _ws_org FROM public.workspaces WHERE id = NEW.workspace_id;
    IF _ws_org IS NULL THEN RAISE EXCEPTION 'Invitation workspace not found'; END IF;
    IF NEW.organization_id IS NOT NULL AND _ws_org <> NEW.organization_id THEN
      RAISE EXCEPTION 'Invitation workspace does not belong to organization';
    END IF;
    -- Workspace-only path: verify workspace's organization is inside invitation tenant
    IF NEW.organization_id IS NULL THEN
      SELECT tenant_id INTO _ws_org_tenant FROM public.organizations WHERE id = _ws_org;
      IF _ws_org_tenant IS NULL THEN RAISE EXCEPTION 'Invitation workspace organization not found'; END IF;
      IF _ws_org_tenant IS DISTINCT FROM NEW.tenant_id THEN
        RAISE EXCEPTION 'Invitation workspace organization tenant (%) does not match invitation tenant (%)', _ws_org_tenant, NEW.tenant_id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_last_org_admin_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_last_org_admin_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _remaining int; _was_admin boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    _was_admin := (OLD.role='org_admin' AND OLD.status='active');
    IF _was_admin THEN
      SELECT count(*) INTO _remaining FROM public.organization_memberships
        WHERE organization_id = OLD.organization_id AND role='org_admin' AND status='active' AND id <> OLD.id;
      IF _remaining = 0 THEN RAISE EXCEPTION 'Cannot delete the last active org_admin for organization %', OLD.organization_id; END IF;
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    _was_admin := (OLD.role='org_admin' AND OLD.status='active');
    IF _was_admin AND (NEW.role <> 'org_admin' OR NEW.status <> 'active') THEN
      SELECT count(*) INTO _remaining FROM public.organization_memberships
        WHERE organization_id = NEW.organization_id AND role='org_admin' AND status='active' AND id <> NEW.id;
      IF _remaining = 0 THEN RAISE EXCEPTION 'Cannot downgrade/deactivate the last active org_admin for organization %', NEW.organization_id; END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_last_platform_super_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_last_platform_super_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _remaining int;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_active THEN
      SELECT count(*) INTO _remaining FROM public.platform_super_admins WHERE is_active AND id <> OLD.id;
      IF _remaining = 0 THEN RAISE EXCEPTION 'Cannot delete the last active Platform Super Admin'; END IF;
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.is_active AND NEW.is_active = false THEN
    SELECT count(*) INTO _remaining FROM public.platform_super_admins WHERE is_active AND id <> NEW.id;
    IF _remaining = 0 THEN RAISE EXCEPTION 'Cannot deactivate the last active Platform Super Admin'; END IF;
    IF NEW.deactivated_at IS NULL THEN NEW.deactivated_at := now(); END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_last_tenant_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_last_tenant_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _remaining int; _tenant uuid; _was_owner boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    _tenant := OLD.tenant_id; _was_owner := (OLD.role = 'tenant_owner' AND OLD.status = 'active');
    IF _was_owner THEN
      SELECT count(*) INTO _remaining FROM public.tenant_memberships
        WHERE tenant_id = _tenant AND role='tenant_owner' AND status='active' AND id <> OLD.id;
      IF _remaining = 0 THEN RAISE EXCEPTION 'Cannot delete the last active tenant_owner for tenant %', _tenant; END IF;
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    _was_owner := (OLD.role='tenant_owner' AND OLD.status='active');
    IF _was_owner AND (NEW.role <> 'tenant_owner' OR NEW.status <> 'active') THEN
      SELECT count(*) INTO _remaining FROM public.tenant_memberships
        WHERE tenant_id = NEW.tenant_id AND role='tenant_owner' AND status='active' AND id <> NEW.id;
      IF _remaining = 0 THEN RAISE EXCEPTION 'Cannot downgrade/deactivate the last active tenant_owner for tenant %', NEW.tenant_id; END IF;
    END IF;
    IF NEW.status='deactivated' AND NEW.deactivated_at IS NULL THEN NEW.deactivated_at := now(); END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_org_secret_override_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_org_secret_override_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_tenant uuid;
  _integ_tenant uuid;
  _ref public.tenant_secret_refs;
BEGIN
  SELECT tenant_id INTO _org_tenant
    FROM public.organizations WHERE id = NEW.organization_id;
  IF _org_tenant IS NULL OR _org_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'Organization % does not belong to tenant %',
      NEW.organization_id, NEW.tenant_id;
  END IF;

  SELECT tenant_id INTO _integ_tenant
    FROM public.tenant_integrations WHERE id = NEW.integration_id;
  IF _integ_tenant IS NULL OR _integ_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'Integration % does not belong to tenant %',
      NEW.integration_id, NEW.tenant_id;
  END IF;

  IF NEW.secret_ref_id IS NOT NULL THEN
    IF NEW.secret_name IS NULL THEN
      RAISE EXCEPTION 'Integration-level override rows cannot carry a secret_ref_id';
    END IF;
    SELECT * INTO _ref FROM public.tenant_secret_refs WHERE id = NEW.secret_ref_id;
    IF _ref.id IS NULL THEN
      RAISE EXCEPTION 'Secret ref % not found', NEW.secret_ref_id;
    END IF;
    IF _ref.tenant_id <> NEW.tenant_id THEN
      RAISE EXCEPTION 'Secret ref % does not belong to tenant %',
        NEW.secret_ref_id, NEW.tenant_id;
    END IF;
    IF _ref.integration_id <> NEW.integration_id THEN
      RAISE EXCEPTION 'Secret ref % does not belong to integration %',
        NEW.secret_ref_id, NEW.integration_id;
    END IF;
    IF _ref.secret_scope <> 'organization_override' THEN
      RAISE EXCEPTION 'Secret ref % is not an organization_override scope', NEW.secret_ref_id;
    END IF;
    IF _ref.organization_id IS NULL OR _ref.organization_id <> NEW.organization_id THEN
      RAISE EXCEPTION 'Secret ref % does not belong to organization %',
        NEW.secret_ref_id, NEW.organization_id;
    END IF;
    IF _ref.secret_name <> NEW.secret_name THEN
      RAISE EXCEPTION 'Secret ref name % does not match override secret_name %',
        _ref.secret_name, NEW.secret_name;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_organization_membership_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_organization_membership_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_tenant uuid;
BEGIN
  SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = NEW.organization_id;
  IF _org_tenant IS NULL THEN RAISE EXCEPTION 'Organization % not found', NEW.organization_id; END IF;
  IF NEW.tenant_id IS DISTINCT FROM _org_tenant THEN
    RAISE EXCEPTION 'organization_memberships.tenant_id (%) must match organizations.tenant_id (%)', NEW.tenant_id, _org_tenant;
  END IF;
  IF NEW.status = 'active' THEN
    IF NOT EXISTS (SELECT 1 FROM public.tenant_memberships WHERE tenant_id = NEW.tenant_id AND user_id = NEW.user_id AND status='active') THEN
      RAISE EXCEPTION 'User % has no active tenant membership in tenant %', NEW.user_id, NEW.tenant_id;
    END IF;
  END IF;
  IF NEW.status = 'deactivated' AND NEW.deactivated_at IS NULL THEN NEW.deactivated_at := now(); END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_phase_parent_containment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_phase_parent_containment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pr record;
  bad_child record;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.start_date       IS NOT DISTINCT FROM OLD.start_date
     AND NEW.target_end_date  IS NOT DISTINCT FROM OLD.target_end_date
     AND NEW.project_id       IS NOT DISTINCT FROM OLD.project_id THEN
    RETURN NEW;
  END IF;

  IF public._planned_extension_allowed() THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'cancelled' OR NEW.is_archived THEN
    RETURN NEW;
  END IF;

  -- 1) Phase must fit inside project planned window
  SELECT id, name, start_date, target_end_date
    INTO pr
    FROM public.projects
   WHERE id = NEW.project_id;

  IF pr.id IS NOT NULL THEN
    IF NEW.start_date IS NOT NULL AND pr.start_date IS NOT NULL
       AND NEW.start_date < pr.start_date THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PHASE_BEFORE_PROJECT: phase "%": planned start (%) is before project "%": planned start (%). Use the planning dialog to extend the project, or adjust the phase date.',
        NEW.name, NEW.start_date, pr.name, pr.start_date
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.target_end_date IS NOT NULL AND pr.target_end_date IS NOT NULL
       AND NEW.target_end_date > pr.target_end_date THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PHASE_AFTER_PROJECT: phase "%": planned end (%) is after project "%": planned end (%). Use the planning dialog to extend the project, or adjust the phase date.',
        NEW.name, NEW.target_end_date, pr.name, pr.target_end_date
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- 2) Phase cannot shrink under existing non-cancelled, non-archived children (UPDATE only)
  IF TG_OP = 'UPDATE' THEN
    -- Earliest child start
    SELECT id, name, start_date AS d INTO bad_child
      FROM public.tasks
     WHERE phase_id = NEW.id
       AND status <> 'cancelled' AND NOT is_archived
       AND start_date IS NOT NULL
       AND NEW.start_date IS NOT NULL
       AND start_date < NEW.start_date
     ORDER BY start_date ASC
     LIMIT 1;

    IF bad_child.id IS NOT NULL THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PHASE_SHRINK_START: cannot move phase "%": child task "%" starts %, which is before the proposed phase start %. Adjust the task or pick a different phase start.',
        NEW.name, bad_child.name, bad_child.d, NEW.start_date
        USING ERRCODE = 'check_violation';
    END IF;

    -- Latest child end
    SELECT id, name, due_date AS d INTO bad_child
      FROM public.tasks
     WHERE phase_id = NEW.id
       AND status <> 'cancelled' AND NOT is_archived
       AND due_date IS NOT NULL
       AND NEW.target_end_date IS NOT NULL
       AND due_date > NEW.target_end_date
     ORDER BY due_date DESC
     LIMIT 1;

    IF bad_child.id IS NOT NULL THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PHASE_SHRINK_END: cannot move phase "%": child task "%" ends %, which is after the proposed phase end %. Adjust the task or pick a different phase end.',
        NEW.name, bad_child.name, bad_child.d, NEW.target_end_date
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_child_containment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_project_child_containment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  bad record;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.start_date       IS NOT DISTINCT FROM OLD.start_date
     AND NEW.target_end_date  IS NOT DISTINCT FROM OLD.target_end_date THEN
    RETURN NEW;
  END IF;

  IF public._planned_extension_allowed() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT id, name, start_date AS d INTO bad
      FROM public.phases
     WHERE project_id = NEW.id
       AND status <> 'cancelled' AND NOT is_archived
       AND start_date IS NOT NULL
       AND NEW.start_date IS NOT NULL
       AND start_date < NEW.start_date
     ORDER BY start_date ASC
     LIMIT 1;

    IF bad.id IS NOT NULL THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PROJECT_SHRINK_START: cannot move project "%": child phase "%" starts %, which is before the proposed project start %.',
        NEW.name, bad.name, bad.d, NEW.start_date
        USING ERRCODE = 'check_violation';
    END IF;

    SELECT id, name, target_end_date AS d INTO bad
      FROM public.phases
     WHERE project_id = NEW.id
       AND status <> 'cancelled' AND NOT is_archived
       AND target_end_date IS NOT NULL
       AND NEW.target_end_date IS NOT NULL
       AND target_end_date > NEW.target_end_date
     ORDER BY target_end_date DESC
     LIMIT 1;

    IF bad.id IS NOT NULL THEN
      RAISE EXCEPTION
        'BTPM_CONTAINMENT_PROJECT_SHRINK_END: cannot move project "%": child phase "%" ends %, which is after the proposed project end %.',
        NEW.name, bad.name, bad.d, NEW.target_end_date
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_project_completion_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_project_completion_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_open_blockers int := 0;
  v_other_changed boolean;
BEGIN
  IF NEW.status = 'completed'
     AND COALESCE(OLD.status::text, '') <> 'completed' THEN
    SELECT COUNT(*) INTO v_open_blockers
    FROM public.blockers b
    WHERE b.status <> 'resolved'
      AND (
        (b.target_type = 'project' AND b.target_id = NEW.id)
        OR (b.target_type = 'phase' AND b.target_id IN (
              SELECT id FROM public.phases WHERE project_id = NEW.id))
        OR (b.target_type = 'task'  AND b.target_id IN (
              SELECT id FROM public.tasks  WHERE project_id = NEW.id))
      );
    IF v_open_blockers > 0 THEN
      RAISE EXCEPTION
        'BTPM_PROJECT_COMPLETE_BLOCKED_OPEN_BLOCKERS: project has % unresolved blocker(s)', v_open_blockers
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF OLD.status = 'completed' THEN
    v_other_changed := ROW(
        NEW.name, NEW.priority, NEW.start_date, NEW.target_end_date,
        NEW.description, NEW.charter, NEW.goals, NEW.scope_in, NEW.scope_out,
        NEW.business_case, NEW.success_criteria, NEW.completion_criteria,
        NEW.budget_narrative, NEW.assumptions, NEW.constraints,
        NEW.program_id, NEW.delivery_model
      ) IS DISTINCT FROM ROW(
        OLD.name, OLD.priority, OLD.start_date, OLD.target_end_date,
        OLD.description, OLD.charter, OLD.goals, OLD.scope_in, OLD.scope_out,
        OLD.business_case, OLD.success_criteria, OLD.completion_criteria,
        OLD.budget_narrative, OLD.assumptions, OLD.constraints,
        OLD.program_id, OLD.delivery_model
      );

    IF NEW.status = 'completed' THEN
      IF v_other_changed THEN
        RAISE EXCEPTION
          'BTPM_PROJECT_COMPLETED_READONLY: project is Completed and read-only; reopen before editing'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF v_other_changed THEN
        RAISE EXCEPTION
          'BTPM_PROJECT_REOPEN_MUST_BE_STATUS_ONLY: completed projects must be reopened before other changes can be made'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_task_parent_containment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_task_parent_containment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ph record;
BEGIN
  -- Skip if planned-date fields didn't change (UPDATE only)
  IF TG_OP = 'UPDATE'
     AND NEW.start_date IS NOT DISTINCT FROM OLD.start_date
     AND NEW.due_date   IS NOT DISTINCT FROM OLD.due_date
     AND NEW.phase_id   IS NOT DISTINCT FROM OLD.phase_id THEN
    RETURN NEW;
  END IF;

  -- Allow when bypass session var is set by the canonical apply RPC
  IF public._planned_extension_allowed() THEN
    RETURN NEW;
  END IF;

  -- Cancelled / archived child tasks are excluded from containment checks (4F.1 §6)
  IF NEW.status = 'cancelled' OR NEW.is_archived THEN
    RETURN NEW;
  END IF;

  SELECT id, name, start_date, target_end_date
    INTO ph
    FROM public.phases
   WHERE id = NEW.phase_id;

  IF ph.id IS NULL THEN
    RETURN NEW;  -- FK validator will catch
  END IF;

  -- Only check when both child and parent have the relevant date set
  IF NEW.start_date IS NOT NULL AND ph.start_date IS NOT NULL
     AND NEW.start_date < ph.start_date THEN
    RAISE EXCEPTION
      'BTPM_CONTAINMENT_TASK_BEFORE_PHASE: task "%": planned start (%) is before phase "%": planned start (%). Use the planning dialog to extend the phase, or adjust the task date.',
      NEW.name, NEW.start_date, ph.name, ph.start_date
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.due_date IS NOT NULL AND ph.target_end_date IS NOT NULL
     AND NEW.due_date > ph.target_end_date THEN
    RAISE EXCEPTION
      'BTPM_CONTAINMENT_TASK_AFTER_PHASE: task "%": planned end (%) is after phase "%": planned end (%). Use the planning dialog to extend the phase, or adjust the task date.',
      NEW.name, NEW.due_date, ph.name, ph.target_end_date
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_tenant_scoped_boundaries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tenant_scoped_boundaries() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_tenant uuid; _ws_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = NEW.organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> NEW.tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', NEW.organization_id, NEW.tenant_id;
    END IF;
  END IF;
  IF NEW.workspace_id IS NOT NULL THEN
    SELECT organization_id INTO _ws_org FROM public.workspaces WHERE id = NEW.workspace_id;
    IF _ws_org IS NULL OR _ws_org <> NEW.organization_id THEN
      RAISE EXCEPTION 'Workspace % does not belong to organization %', NEW.workspace_id, NEW.organization_id;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_tenant_secret_ref_tenant_match(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tenant_secret_ref_tenant_match() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _integration_tenant uuid;
  _org_tenant uuid;
BEGIN
  SELECT tenant_id INTO _integration_tenant
    FROM public.tenant_integrations WHERE id = NEW.integration_id;
  IF _integration_tenant IS NULL THEN
    RAISE EXCEPTION 'Integration % not found', NEW.integration_id;
  END IF;
  IF _integration_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'Integration % does not belong to tenant %',
      NEW.integration_id, NEW.tenant_id;
  END IF;

  IF NEW.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant
      FROM public.organizations WHERE id = NEW.organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> NEW.tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %',
        NEW.organization_id, NEW.tenant_id;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enqueue_tenant_background_job(uuid, text, jsonb, uuid, uuid, integer, text, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_tenant_background_job(_tenant_id uuid, _job_type text, _payload jsonb DEFAULT '{}'::jsonb, _organization_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _priority integer DEFAULT 100, _idempotency_key text DEFAULT NULL::text, _max_attempts integer DEFAULT 3, _not_before timestamp with time zone DEFAULT NULL::timestamp with time zone, _run_as_user_id uuid DEFAULT NULL::uuid) RETURNS public.tenant_background_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_background_jobs;
  _org_tenant uuid;
  _actor uuid := auth.uid();
  _effective_run_as uuid;
  _is_tenant_admin boolean;
  _is_org_admin boolean;
BEGIN
  IF _actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id is required'; END IF;
  IF _job_type IS NULL OR length(btrim(_job_type)) = 0 THEN RAISE EXCEPTION 'job_type is required'; END IF;
  IF jsonb_typeof(COALESCE(_payload, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'payload must be a JSON object';
  END IF;
  PERFORM public._assert_job_payload_no_secret_keys(COALESCE(_payload, '{}'::jsonb));

  IF NOT (
    public.is_platform_super_admin(_actor)
    OR public.is_tenant_admin(_tenant_id, _actor)
    OR (_organization_id IS NOT NULL AND public.is_organization_admin(_organization_id, _actor))
    OR (_workspace_id IS NOT NULL AND public.is_workspace_member(_actor, _workspace_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to enqueue job in this scope' USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _tenant_id;
    END IF;
  END IF;

  _effective_run_as := COALESCE(_run_as_user_id, _actor);
  IF _effective_run_as <> _actor THEN
    _is_tenant_admin := public.is_tenant_admin(_tenant_id, _actor) OR public.is_platform_super_admin(_actor);
    _is_org_admin := (_organization_id IS NOT NULL AND public.is_organization_admin(_organization_id, _actor));
    IF NOT (_is_tenant_admin OR _is_org_admin) THEN
      RAISE EXCEPTION 'Only tenant or organization admins may set run_as_user_id to another user'
        USING ERRCODE = '42501';
    END IF;
    IF NOT public.is_tenant_member(_tenant_id, _effective_run_as) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active tenant member';
    END IF;
    IF _organization_id IS NOT NULL
       AND NOT public.is_organization_member(_organization_id, _effective_run_as) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_effective_run_as, _workspace_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active workspace member';
    END IF;
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT * INTO _row FROM public.tenant_background_jobs
      WHERE tenant_id = _tenant_id AND job_type = _job_type AND idempotency_key = _idempotency_key;
    IF _row.id IS NOT NULL THEN RETURN _row; END IF;
  END IF;

  INSERT INTO public.tenant_background_jobs (
    tenant_id, organization_id, workspace_id, job_type, priority,
    requested_by, run_as_user_id, idempotency_key, payload, max_attempts, not_before
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _job_type, COALESCE(_priority, 100),
    _actor, _effective_run_as, _idempotency_key, COALESCE(_payload, '{}'::jsonb),
    COALESCE(_max_attempts, 3), _not_before
  ) RETURNING * INTO _row;
  RETURN _row;
END $$;


--
-- Name: ensure_active_tenant_encryption_key_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_active_tenant_encryption_key_version(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  _tenant_exists boolean;
  _existing record;
  _next_version int;
  _vault_name text;
  _now timestamptz := now();
  _safe_metadata jsonb;
BEGIN
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id_required';
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.tenants WHERE id = _tenant_id) INTO _tenant_exists;
  IF NOT _tenant_exists THEN
    RAISE EXCEPTION 'tenant_not_found';
  END IF;

  -- Already-active row?
  SELECT tenant_id, key_scope, key_version, key_status, key_provider
    INTO _existing
    FROM public.tenant_encryption_keys
    WHERE tenant_id = _tenant_id
      AND key_scope = 'tenant_encryption_key'
      AND key_status = 'active_for_encrypt'
    ORDER BY key_version DESC
    LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'tenant_id', _existing.tenant_id,
      'key_scope', _existing.key_scope,
      'key_version', _existing.key_version,
      'key_status', _existing.key_status,
      'key_provider', _existing.key_provider,
      'payload_format_ready', true,
      'fresh_tenant_key_created', false,
      'legacy_org_keys_retained', true,
      'business_records_touched', false,
      'runtime_changed', false,
      'prepared_at', _now
    );
  END IF;

  -- Choose next fresh version. Do not overwrite import_blocked v1.
  SELECT COALESCE(MAX(key_version), 0) + 1
    INTO _next_version
    FROM public.tenant_encryption_keys
    WHERE tenant_id = _tenant_id
      AND key_scope = 'tenant_encryption_key';

  _vault_name := 'btpm_tenant_key_' || _tenant_id::text || '_v' || _next_version::text;

  -- Create Vault secret only if it does not already exist. Never overwrite.
  IF NOT EXISTS (SELECT 1 FROM vault.decrypted_secrets WHERE name = _vault_name) THEN
    PERFORM vault.create_secret(
      encode(gen_random_bytes(32), 'hex'),
      _vault_name,
      'BTPM Tenant encryption key (fresh). Backend-only.'
    );
  END IF;

  _safe_metadata := jsonb_build_object(
    'source_phase', '4D.12F',
    'versioning_model', 'tenant_key_family',
    'tenant_key_version', _next_version,
    'fresh_tenant_key_created', true,
    'legacy_material_imported', false,
    'payload_format_ready', true,
    'runtime_caller_migration_active', false,
    'business_record_reencryption_performed', false,
    'legacy_org_keys_retained', true,
    'tenant_admin_key_management_allowed', false,
    'prepared_at', _now
  );

  INSERT INTO public.tenant_encryption_keys
    (tenant_id, key_scope, key_version, key_status, key_provider, metadata, created_at, updated_at)
  VALUES
    (_tenant_id, 'tenant_encryption_key', _next_version, 'active_for_encrypt',
     'supabase_vault_fresh_tenant_key_version', _safe_metadata, _now, _now)
  ON CONFLICT (tenant_id, key_scope, key_version) DO UPDATE
    SET key_status = 'active_for_encrypt',
        key_provider = 'supabase_vault_fresh_tenant_key_version',
        metadata = public.tenant_encryption_keys.metadata || _safe_metadata,
        updated_at = _now;

  RETURN jsonb_build_object(
    'tenant_id', _tenant_id,
    'key_scope', 'tenant_encryption_key',
    'key_version', _next_version,
    'key_status', 'active_for_encrypt',
    'key_provider', 'supabase_vault_fresh_tenant_key_version',
    'payload_format_ready', true,
    'fresh_tenant_key_created', true,
    'legacy_org_keys_retained', true,
    'business_records_touched', false,
    'runtime_changed', false,
    'prepared_at', _now
  );
END;
$$;


--
-- Name: ensure_org_encryption_key(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_org_encryption_key(_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _key_name text;
BEGIN
  _key_name := 'btpm_org_key_' || _org_id::text;
  IF NOT EXISTS (SELECT 1 FROM vault.decrypted_secrets WHERE name = _key_name) THEN
    PERFORM vault.create_secret(encode(gen_random_bytes(32), 'hex'), _key_name, 'BTPM organization encryption key');
  END IF;
  -- Keep encryption posture metadata aligned. Never reads key value.
  PERFORM public.ensure_organization_encryption_metadata(_org_id);
END;
$$;


--
-- Name: ensure_organization_encryption_metadata(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_organization_encryption_metadata(_organization_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _tenant_id uuid; _tek_id uuid;
BEGIN
  IF _organization_id IS NULL THEN RETURN; END IF;
  SELECT tenant_id INTO _tenant_id FROM public.organizations WHERE id = _organization_id;
  IF _tenant_id IS NULL THEN RETURN; END IF;

  SELECT id INTO _tek_id FROM public.tenant_encryption_keys
   WHERE tenant_id = _tenant_id AND key_scope = 'tenant_master_key'
   ORDER BY key_version DESC LIMIT 1;

  IF _tek_id IS NULL THEN
    INSERT INTO public.tenant_encryption_keys
      (tenant_id, key_scope, key_status, key_provider, key_version, metadata)
    VALUES
      (_tenant_id, 'tenant_master_key', 'planned_legacy_org_key_model', 'supabase_vault_legacy_org_keys', 1, '{}'::jsonb)
    RETURNING id INTO _tek_id;
  END IF;

  INSERT INTO public.organization_encryption_keys
    (tenant_id, organization_id, tenant_encryption_key_id, key_scope, legacy_key_name, key_status, key_version, metadata)
  VALUES
    (_tenant_id, _organization_id, _tek_id, 'organization_data_key',
     'btpm_org_key_' || _organization_id::text,
     'active_legacy_org_key', 1, '{}'::jsonb)
  ON CONFLICT (organization_id) DO UPDATE
    SET tenant_encryption_key_id = COALESCE(public.organization_encryption_keys.tenant_encryption_key_id, EXCLUDED.tenant_encryption_key_id),
        legacy_key_name = COALESCE(public.organization_encryption_keys.legacy_key_name, EXCLUDED.legacy_key_name),
        updated_at = now();
END;
$$;


--
-- Name: ensure_tenant_encryption_key_v1_from_legacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_tenant_encryption_key_v1_from_legacy(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  _tenant_exists boolean := false;
  _org record;
  _first_secret text;
  _cand_secret text;
  _first_digest text;
  _cand_digest text;
  _org_count int := 0;
  _found_count int := 0;
  _missing_count int := 0;
  _all_equal boolean := true;
  _existing_tenant_secret text;
  _existing_tenant_digest text;
  _tenant_vault_name text := 'btpm_tenant_key_' || _tenant_id::text || '_v1';
  _idempotent boolean := false;
  _imported boolean := false;
  _blocked boolean := false;
  _blocked_reason text;
  _now timestamptz := now();
  _safe_metadata jsonb;
BEGIN
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id_required';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.tenants WHERE id = _tenant_id) INTO _tenant_exists;
  IF NOT _tenant_exists THEN
    RAISE EXCEPTION 'tenant_not_found';
  END IF;

  FOR _org IN SELECT id FROM public.organizations WHERE tenant_id = _tenant_id LOOP
    _org_count := _org_count + 1;
    SELECT decrypted_secret INTO _cand_secret
      FROM vault.decrypted_secrets
      WHERE name = 'btpm_org_key_' || _org.id::text
      LIMIT 1;
    IF _cand_secret IS NULL THEN
      _missing_count := _missing_count + 1;
    ELSE
      _found_count := _found_count + 1;
      _cand_digest := encode(extensions.digest(_cand_secret::bytea, 'sha256'), 'hex');
      IF _first_secret IS NULL THEN
        _first_secret := _cand_secret;
        _first_digest := _cand_digest;
      ELSIF _cand_digest <> _first_digest THEN
        _all_equal := false;
      END IF;
    END IF;
    _cand_secret := NULL;
  END LOOP;

  IF _org_count = 0 OR _missing_count > 0 OR NOT _all_equal OR _first_secret IS NULL THEN
    _blocked := true;
    _blocked_reason := CASE
      WHEN _org_count = 0 THEN 'no_organizations'
      WHEN _missing_count > 0 THEN 'legacy_org_key_missing'
      WHEN NOT _all_equal THEN 'legacy_org_key_mismatch'
      ELSE 'unknown'
    END;
  END IF;

  IF _blocked THEN
    _safe_metadata := jsonb_build_object(
      'source_phase', '4D.12E',
      'versioning_model', 'tenant_key_family',
      'tenant_key_version', 1,
      'legacy_material_imported', false,
      'legacy_material_equivalence_verified', false,
      'runtime_caller_migration_active', false,
      'business_record_reencryption_performed', false,
      'payload_format_ready', false,
      'legacy_org_keys_retained', true,
      'active_for_new_versioned_helpers', false,
      'tenant_admin_key_management_allowed', false,
      'block_reason_code', _blocked_reason,
      'organization_count', _org_count,
      'legacy_keys_found_count', _found_count,
      'legacy_keys_missing_count', _missing_count,
      'prepared_at', _now
    );

    INSERT INTO public.tenant_encryption_keys AS t
      (tenant_id, key_scope, key_version, key_status, key_provider, metadata, created_at, updated_at)
    VALUES
      (_tenant_id, 'tenant_encryption_key', 1, 'import_blocked',
       'supabase_vault_imported_legacy_material_tenant_v1', _safe_metadata, _now, _now)
    ON CONFLICT (tenant_id, key_scope, key_version) DO UPDATE
      SET key_status = 'import_blocked',
          key_provider = EXCLUDED.key_provider,
          metadata = t.metadata || _safe_metadata,
          updated_at = _now
      WHERE t.key_status <> 'active_for_encrypt';

    RETURN jsonb_build_object(
      'tenant_id', _tenant_id,
      'key_scope', 'tenant_encryption_key',
      'key_version', 1,
      'key_status', 'import_blocked',
      'imported', false,
      'idempotent', false,
      'safe_for_future_versioned_helpers', false,
      'legacy_org_keys_retained', true,
      'business_records_touched', false,
      'runtime_changed', false,
      'prepared_at', _now
    );
  END IF;

  SELECT decrypted_secret INTO _existing_tenant_secret
    FROM vault.decrypted_secrets
    WHERE name = _tenant_vault_name
    LIMIT 1;

  IF _existing_tenant_secret IS NOT NULL THEN
    _existing_tenant_digest := encode(extensions.digest(_existing_tenant_secret::bytea, 'sha256'), 'hex');
    IF _existing_tenant_digest = _first_digest THEN
      _idempotent := true;
      _imported := true;
    ELSE
      _safe_metadata := jsonb_build_object(
        'source_phase', '4D.12E',
        'versioning_model', 'tenant_key_family',
        'tenant_key_version', 1,
        'legacy_material_imported', false,
        'legacy_material_equivalence_verified', true,
        'runtime_caller_migration_active', false,
        'business_record_reencryption_performed', false,
        'payload_format_ready', false,
        'legacy_org_keys_retained', true,
        'active_for_new_versioned_helpers', false,
        'tenant_admin_key_management_allowed', false,
        'block_reason_code', 'tenant_v1_vault_conflict',
        'organization_count', _org_count,
        'legacy_keys_found_count', _found_count,
        'legacy_keys_missing_count', _missing_count,
        'prepared_at', _now
      );
      INSERT INTO public.tenant_encryption_keys AS t
        (tenant_id, key_scope, key_version, key_status, key_provider, metadata, created_at, updated_at)
      VALUES
        (_tenant_id, 'tenant_encryption_key', 1, 'import_blocked',
         'supabase_vault_imported_legacy_material_tenant_v1', _safe_metadata, _now, _now)
      ON CONFLICT (tenant_id, key_scope, key_version) DO UPDATE
        SET key_status = 'import_blocked',
            metadata = t.metadata || _safe_metadata,
            updated_at = _now
        WHERE t.key_status <> 'active_for_encrypt';

      _existing_tenant_secret := NULL;
      RETURN jsonb_build_object(
        'tenant_id', _tenant_id,
        'key_scope', 'tenant_encryption_key',
        'key_version', 1,
        'key_status', 'import_blocked',
        'imported', false,
        'idempotent', false,
        'safe_for_future_versioned_helpers', false,
        'legacy_org_keys_retained', true,
        'business_records_touched', false,
        'runtime_changed', false,
        'prepared_at', _now
      );
    END IF;
  ELSE
    PERFORM vault.create_secret(_first_secret, _tenant_vault_name,
      'BTPM Tenant encryption key v1 (imported from legacy Organization key material). Backend-only.');
    _imported := true;
  END IF;

  _first_secret := NULL;
  _existing_tenant_secret := NULL;

  _safe_metadata := jsonb_build_object(
    'source_phase', '4D.12E',
    'versioning_model', 'tenant_key_family',
    'tenant_key_version', 1,
    'legacy_material_imported', true,
    'legacy_material_equivalence_verified', true,
    'runtime_caller_migration_active', false,
    'business_record_reencryption_performed', false,
    'payload_format_ready', false,
    'legacy_org_keys_retained', true,
    'active_for_new_versioned_helpers', false,
    'tenant_admin_key_management_allowed', false,
    'organization_count', _org_count,
    'legacy_keys_found_count', _found_count,
    'legacy_keys_missing_count', _missing_count,
    'prepared_at', _now
  );

  INSERT INTO public.tenant_encryption_keys AS t
    (tenant_id, key_scope, key_version, key_status, key_provider, metadata, created_at, updated_at)
  VALUES
    (_tenant_id, 'tenant_encryption_key', 1, 'active_for_encrypt',
     'supabase_vault_imported_legacy_material_tenant_v1', _safe_metadata, _now, _now)
  ON CONFLICT (tenant_id, key_scope, key_version) DO UPDATE
    SET key_status = 'active_for_encrypt',
        key_provider = 'supabase_vault_imported_legacy_material_tenant_v1',
        metadata = t.metadata || _safe_metadata,
        updated_at = _now;

  RETURN jsonb_build_object(
    'tenant_id', _tenant_id,
    'key_scope', 'tenant_encryption_key',
    'key_version', 1,
    'key_status', 'active_for_encrypt',
    'imported', _imported,
    'idempotent', _idempotent,
    'safe_for_future_versioned_helpers', true,
    'legacy_org_keys_retained', true,
    'business_records_touched', false,
    'runtime_changed', false,
    'prepared_at', _now
  );
END;
$$;


--
-- Name: ensure_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_user_profile() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _user_id uuid; _email text;
BEGIN
  _user_id := auth.uid(); IF _user_id IS NULL THEN RETURN; END IF;
  SELECT email INTO _email FROM auth.users WHERE id = _user_id;
  INSERT INTO public.profiles (id, email) VALUES (_user_id, lower(_email)) ON CONFLICT (id) DO UPDATE SET email = COALESCE(profiles.email, EXCLUDED.email), updated_at = now();
END;
$$;


--
-- Name: fail_roadmap_story_generation_run(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_roadmap_story_generation_run(_run_id uuid, _error_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_ai_runs;
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_ai_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _run.story_pack_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.roadmap_story_ai_runs
  SET status = 'failed',
      completed_at = now(),
      error_text_encrypted = CASE WHEN _error_text IS NULL OR _error_text = '' THEN NULL
                                  ELSE public.btpm_encrypt(_error_text, _pack.organization_id) END
  WHERE id = _run_id;
END;
$$;


--
-- Name: fail_roadmap_story_presentation_run(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_roadmap_story_presentation_run(_run_id uuid, _error_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_pack_presentation_runs;
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_pack_presentation_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _run.story_pack_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE public.roadmap_story_pack_presentation_runs
     SET status = 'failed',
         error_text_encrypted = CASE WHEN _error_text IS NULL OR _error_text = '' THEN NULL
              ELSE public.btpm_encrypt(_error_text, _pack.organization_id) END,
         completed_at = COALESCE(completed_at, now())
   WHERE id = _run_id;
END;
$$;


--
-- Name: fail_tenant_background_job(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_tenant_background_job(_job_id uuid, _error text, _dead_letter boolean DEFAULT false) RETURNS public.tenant_background_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row public.tenant_background_jobs;
BEGIN
  UPDATE public.tenant_background_jobs
     SET status = CASE
                    WHEN _dead_letter THEN 'dead_letter'
                    WHEN attempt_count >= max_attempts THEN 'failed'
                    ELSE 'queued'
                  END,
         failed_at = now(),
         last_error = _error,
         updated_at = now()
   WHERE id = _job_id
   RETURNING * INTO _row;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Job % not found', _job_id; END IF;
  RETURN _row;
END $$;


--
-- Name: generate_project_adoption_plan_from_saved_template(uuid, uuid, text, text, date, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_project_adoption_plan_from_saved_template(_project_id uuid, _template_id uuid DEFAULT NULL::uuid, _template_key text DEFAULT 'btpm_standard_adoption'::text, _phase_name text DEFAULT 'Adoption & Readiness'::text, _phase_start_date date DEFAULT NULL::date, _phase_end_date date DEFAULT NULL::date, _selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _ws uuid;
  _is_baselined boolean := false;
  _phase_start date;
  _phase_end date;
  _plan_id uuid;
  _phase_id uuid;
  _next_phase_sort int;
  _initiative_id uuid;
  _initiative_count int := 0;
  _task_count int := 0;
  _selected_task_count int := 0;
  _custom_task_count int := 0;
  _selected_keys text[] := NULL;
  _custom_tasks jsonb := '[]'::jsonb;
  _has_selection boolean := false;
  _valid_init_keys text[] := ARRAY[]::text[];
  _valid_task_keys text[] := ARRAY[]::text[];
  _k text;
  _ct jsonb;
  _ikey text;
  _init_row record;
  _task_row record;
  _selected_in_init int;
  _sort int;
  _template_name text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Delegate to existing CM.7A path when standard template selected
  IF _template_id IS NULL THEN
    IF COALESCE(_template_key, 'btpm_standard_adoption') <> 'btpm_standard_adoption' THEN
      RAISE EXCEPTION 'invalid_template_key';
    END IF;
    RETURN public.generate_project_adoption_plan_from_template(
      _project_id, true, _phase_name, _selection, _phase_start_date, _phase_end_date
    );
  END IF;

  -- Saved custom template path
  SELECT organization_id, workspace_id, COALESCE(is_baselined,false)
    INTO _org, _ws, _is_baselined
  FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_project'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF EXISTS (SELECT 1 FROM public.adoption_plans
             WHERE project_id = _project_id AND is_archived = false) THEN
    RAISE EXCEPTION 'adoption_plan_already_exists';
  END IF;

  -- Validate template exists and belongs to project's workspace; capture decrypted name
  SELECT public.btpm_decrypt(name, organization_id) INTO _template_name
  FROM public.adoption_templates
  WHERE id = _template_id AND workspace_id = _ws AND is_archived = false;
  IF _template_name IS NULL THEN
    RAISE EXCEPTION 'invalid_template';
  END IF;

  -- Phase date rules
  IF _is_baselined AND (_phase_start_date IS NULL OR _phase_end_date IS NULL) THEN
    RAISE EXCEPTION 'adoption_phase_dates_required_for_baselined_project';
  END IF;
  IF _phase_start_date IS NOT NULL AND _phase_end_date IS NOT NULL
     AND _phase_end_date < _phase_start_date THEN
    RAISE EXCEPTION 'adoption_phase_end_before_start';
  END IF;
  _phase_start := _phase_start_date;
  _phase_end := _phase_end_date;

  -- Build valid key sets from saved template
  SELECT array_agg(template_key) INTO _valid_init_keys
  FROM public.adoption_template_initiatives
  WHERE adoption_template_id = _template_id AND is_archived = false;

  SELECT array_agg(format('%s.%s', i.template_key, t.template_key)) INTO _valid_task_keys
  FROM public.adoption_template_initiatives i
  JOIN public.adoption_template_tasks t ON t.adoption_template_initiative_id = i.id
  WHERE i.adoption_template_id = _template_id
    AND i.is_archived = false AND t.is_archived = false;

  -- Parse selection
  IF _selection IS NOT NULL THEN
    IF jsonb_typeof(_selection) <> 'object' THEN
      RAISE EXCEPTION 'adoption_template_selection_invalid';
    END IF;
    _has_selection := true;
    IF _selection ? 'selected_task_keys' AND jsonb_typeof(_selection->'selected_task_keys') = 'array' THEN
      SELECT array_agg(value::text) INTO _selected_keys
      FROM jsonb_array_elements_text(_selection->'selected_task_keys');
      _selected_keys := COALESCE(_selected_keys, ARRAY[]::text[]);
      FOREACH _k IN ARRAY _selected_keys LOOP
        IF NOT (_k = ANY(COALESCE(_valid_task_keys, ARRAY[]::text[]))) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
      END LOOP;
    ELSE
      _selected_keys := ARRAY[]::text[];
    END IF;
    IF _selection ? 'custom_tasks' AND jsonb_typeof(_selection->'custom_tasks') = 'array' THEN
      _custom_tasks := _selection->'custom_tasks';
      FOR _ct IN SELECT value FROM jsonb_array_elements(_custom_tasks) AS value LOOP
        _ikey := _ct->>'initiative_key';
        IF _ikey IS NULL OR NOT (_ikey = ANY(COALESCE(_valid_init_keys, ARRAY[]::text[]))) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        IF COALESCE(btrim(_ct->>'title'),'') = '' THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
      END LOOP;
    END IF;
    IF (COALESCE(array_length(_selected_keys,1),0) + COALESCE(jsonb_array_length(_custom_tasks),0)) = 0 THEN
      RAISE EXCEPTION 'adoption_template_selection_empty';
    END IF;
  END IF;

  _selected_task_count := COALESCE(array_length(_selected_keys,1),0);
  _custom_task_count := COALESCE(jsonb_array_length(_custom_tasks),0);

  -- Create adoption plan
  INSERT INTO public.adoption_plans(
    organization_id, workspace_id, project_id,
    objective, impacted_audience_summary, approach_summary,
    readiness_status, created_from_template, enabled, created_by
  ) VALUES (
    _org, _ws, _project_id,
    'Drive successful adoption of the change delivered by this project so impacted users work in the new way and the expected business outcome is realized.',
    'All users, teams, and stakeholder groups directly affected by the change delivered by this project. Refine the audience as stakeholder analysis progresses.',
    'Use the saved workspace adoption template chosen at generation time.',
    'preparing', true, true, _uid
  ) RETURNING id INTO _plan_id;

  SELECT COALESCE(MAX(sort_order), -1) + 1 INTO _next_phase_sort
  FROM public.phases WHERE project_id = _project_id AND is_archived = false;

  INSERT INTO public.phases(
    organization_id, workspace_id, project_id,
    name, description, status, sort_order,
    start_date, target_end_date, created_by
  ) VALUES (
    _org, _ws, _project_id,
    _phase_name,
    'Contains people-side adoption work generated from a saved workspace Adoption Template. Tasks here are normal BTPM tasks linked to Adoption Initiatives.',
    'planned', _next_phase_sort,
    _phase_start, _phase_end, _uid
  ) RETURNING id INTO _phase_id;

  -- Iterate saved template initiatives (do NOT mutate template rows)
  FOR _init_row IN
    SELECT id, template_key, name, summary, readiness_area, sort_order, organization_id
    FROM public.adoption_template_initiatives
    WHERE adoption_template_id = _template_id AND is_archived = false
    ORDER BY sort_order, template_key
  LOOP
    _selected_in_init := 0;
    IF _has_selection THEN
      SELECT COUNT(*) INTO _selected_in_init
      FROM public.adoption_template_tasks t
      WHERE t.adoption_template_initiative_id = _init_row.id
        AND t.is_archived = false
        AND format('%s.%s', _init_row.template_key, t.template_key) = ANY(_selected_keys);
      _selected_in_init := _selected_in_init + (
        SELECT COUNT(*) FROM jsonb_array_elements(_custom_tasks) AS c
        WHERE c->>'initiative_key' = _init_row.template_key
      );
    ELSE
      SELECT COUNT(*) INTO _selected_in_init
      FROM public.adoption_template_tasks t
      WHERE t.adoption_template_initiative_id = _init_row.id AND t.is_archived = false;
    END IF;

    IF _selected_in_init = 0 THEN CONTINUE; END IF;

    INSERT INTO public.adoption_initiatives(
      organization_id, workspace_id, project_id, adoption_plan_id,
      name, summary, readiness_area, status, priority, sort_order, created_by
    ) VALUES (
      _org, _ws, _project_id, _plan_id,
      public.btpm_decrypt(_init_row.name, _init_row.organization_id),
      public.btpm_decrypt(_init_row.summary, _init_row.organization_id),
      _init_row.readiness_area,
      'planned'::public.adoption_initiative_status,
      'medium'::public.pm_priority,
      _init_row.sort_order,
      _uid
    ) RETURNING id INTO _initiative_id;
    _initiative_count := _initiative_count + 1;

    _sort := 0;
    -- Selected template tasks → normal BTPM tasks
    FOR _task_row IN
      SELECT t.template_key, t.title, t.description, t.sort_order, t.organization_id
      FROM public.adoption_template_tasks t
      WHERE t.adoption_template_initiative_id = _init_row.id
        AND t.is_archived = false
        AND (
          NOT _has_selection
          OR format('%s.%s', _init_row.template_key, t.template_key) = ANY(_selected_keys)
        )
      ORDER BY t.sort_order, t.template_key
    LOOP
      INSERT INTO public.tasks(
        organization_id, workspace_id, project_id, phase_id,
        name, description, task_type, status, priority, sort_order,
        start_date, due_date,
        is_adoption_related, adoption_initiative_id, created_by
      ) VALUES (
        _org, _ws, _project_id, _phase_id,
        public.btpm_decrypt(_task_row.title, _task_row.organization_id),
        public.btpm_decrypt(_task_row.description, _task_row.organization_id),
        'work_item'::public.task_type,
        'planned'::public.pm_status,
        'medium'::public.pm_priority,
        _sort,
        _phase_start, _phase_end,
        true, _initiative_id, _uid
      );
      _sort := _sort + 10;
      _task_count := _task_count + 1;
    END LOOP;

    -- Custom tasks attached to this initiative (single, correct loop)
    FOR _ct IN
      SELECT c FROM jsonb_array_elements(_custom_tasks) AS c
      WHERE c->>'initiative_key' = _init_row.template_key
    LOOP
      INSERT INTO public.tasks(
        organization_id, workspace_id, project_id, phase_id,
        name, description, task_type, status, priority, sort_order,
        start_date, due_date,
        is_adoption_related, adoption_initiative_id, created_by
      ) VALUES (
        _org, _ws, _project_id, _phase_id,
        btrim(_ct->>'title'),
        NULLIF(btrim(COALESCE(_ct->>'description','')),''),
        'work_item'::public.task_type,
        'planned'::public.pm_status,
        'medium'::public.pm_priority,
        _sort,
        _phase_start, _phase_end,
        true, _initiative_id, _uid
      );
      _sort := _sort + 10;
      _task_count := _task_count + 1;
    END LOOP;
  END LOOP;

  -- Activity event via canonical helper (uses event_type, not action)
  PERFORM public.log_activity_event(
    _org,
    _uid,
    'adoption_template_generated',
    'project',
    _project_id,
    jsonb_build_object(
      'adoption_plan_id', _plan_id,
      'created_phase_id', _phase_id,
      'created_initiative_count', _initiative_count,
      'created_task_count', _task_count,
      'selected_task_count', _selected_task_count,
      'custom_task_count', _custom_task_count,
      'generated_from_selection', _has_selection,
      'template_name', _template_name,
      'template_id', _template_id,
      'template_source', 'workspace',
      'phase_name', _phase_name,
      'phase_start_date', _phase_start,
      'phase_end_date', _phase_end,
      'is_baselined_project', _is_baselined
    ),
    _ws
  );

  RETURN jsonb_build_object(
    'adoption_plan_id', _plan_id,
    'phase_id', _phase_id,
    'initiative_count', _initiative_count,
    'task_count', _task_count,
    'template_id', _template_id,
    'template_source', 'workspace'
  );
END $$;


--
-- Name: generate_project_adoption_plan_from_template(uuid, boolean, text, jsonb, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_project_adoption_plan_from_template(_project_id uuid, _create_phase boolean DEFAULT true, _phase_name text DEFAULT 'Adoption & Readiness'::text, _selection jsonb DEFAULT NULL::jsonb, _phase_start_date date DEFAULT NULL::date, _phase_end_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _ws  uuid;
  _proj_start date;
  _proj_end   date;
  _is_baselined boolean := false;
  _phase_start date;
  _phase_end   date;
  _plan_id uuid;
  _phase_id uuid := NULL;
  _next_phase_sort int;
  _template jsonb;
  _init jsonb;
  _initiative_id uuid;
  _task_sort int := 0;
  _initiative_count int := 0;
  _task_count int := 0;
  _initiative_map jsonb := '[]'::jsonb;
  _selected_keys text[] := NULL;
  _custom_tasks jsonb := '[]'::jsonb;
  _has_selection boolean := false;
  _selected_std_count int := 0;
  _custom_count int := 0;
  _valid_task_keys text[] := ARRAY[]::text[];
  _valid_init_keys text[] := ARRAY[]::text[];
  _k text;
  _ct jsonb;
  _init_key text;
  _selected_in_init int;
  _custom_titles_for_init text[];
  _custom_descs_for_init text[];
  _picked_titles text[];
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT organization_id, workspace_id, start_date, target_end_date, COALESCE(is_baselined, false)
    INTO _org, _ws, _proj_start, _proj_end, _is_baselined
  FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'invalid_project';
  END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF EXISTS (SELECT 1 FROM public.adoption_plans
             WHERE project_id = _project_id AND is_archived = false) THEN
    RAISE EXCEPTION 'adoption_plan_already_exists';
  END IF;

  IF NOT _create_phase THEN
    RAISE EXCEPTION 'phase_required_for_task_generation';
  END IF;

  _template := public._btpm_adoption_template_v1();

  SELECT array_agg(i->>'key') INTO _valid_init_keys
  FROM jsonb_array_elements(_template) AS i;

  SELECT array_agg(format('%s.%s', i->>'key', t->>'key')) INTO _valid_task_keys
  FROM jsonb_array_elements(_template) AS i,
       jsonb_array_elements(i->'tasks') AS t;

  IF _selection IS NOT NULL THEN
    IF jsonb_typeof(_selection) <> 'object' THEN
      RAISE EXCEPTION 'adoption_template_selection_invalid';
    END IF;
    _has_selection := true;

    IF _selection ? 'selected_task_keys' AND jsonb_typeof(_selection->'selected_task_keys') <> 'null' THEN
      IF jsonb_typeof(_selection->'selected_task_keys') <> 'array' THEN
        RAISE EXCEPTION 'adoption_template_selection_invalid';
      END IF;
      SELECT array_agg(value::text) INTO _selected_keys
      FROM jsonb_array_elements_text(_selection->'selected_task_keys');
      _selected_keys := COALESCE(_selected_keys, ARRAY[]::text[]);
      FOREACH _k IN ARRAY _selected_keys LOOP
        IF NOT (_k = ANY(_valid_task_keys)) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
      END LOOP;
      _selected_std_count := COALESCE(array_length(_selected_keys, 1), 0);
    ELSE
      _selected_keys := ARRAY[]::text[];
    END IF;

    IF _selection ? 'custom_tasks' AND jsonb_typeof(_selection->'custom_tasks') <> 'null' THEN
      IF jsonb_typeof(_selection->'custom_tasks') <> 'array' THEN
        RAISE EXCEPTION 'adoption_template_selection_invalid';
      END IF;
      _custom_tasks := _selection->'custom_tasks';
      FOR _ct IN SELECT * FROM jsonb_array_elements(_custom_tasks) LOOP
        IF jsonb_typeof(_ct) <> 'object' THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        _init_key := _ct->>'initiative_key';
        IF _init_key IS NULL OR NOT (_init_key = ANY(_valid_init_keys)) THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        IF COALESCE(btrim(_ct->>'title'),'') = '' THEN
          RAISE EXCEPTION 'adoption_template_selection_invalid';
        END IF;
        _custom_count := _custom_count + 1;
      END LOOP;
    END IF;

    IF (_selected_std_count + _custom_count) = 0 THEN
      RAISE EXCEPTION 'adoption_template_selection_empty';
    END IF;
  END IF;

  -- Phase dates: use ONLY caller-confirmed dates. No hidden fabrication.
  _phase_start := _phase_start_date;
  _phase_end   := _phase_end_date;

  IF _phase_start IS NOT NULL AND _phase_end IS NOT NULL AND _phase_end < _phase_start THEN
    RAISE EXCEPTION 'adoption_phase_end_before_start';
  END IF;

  -- Baselined projects require explicit phase dates so generated tasks can carry planned dates.
  IF _is_baselined AND (_phase_start IS NULL OR _phase_end IS NULL) THEN
    RAISE EXCEPTION 'adoption_phase_dates_required_for_baselined_project';
  END IF;

  INSERT INTO public.adoption_plans(
    organization_id, workspace_id, project_id,
    objective, impacted_audience_summary, approach_summary,
    readiness_status, created_from_template, enabled, created_by
  ) VALUES (
    _org, _ws, _project_id,
    'Drive successful adoption of the change delivered by this project so impacted users work in the new way and the expected business outcome is realized.',
    'All users, teams, and stakeholder groups directly affected by the change delivered by this project. Refine the audience as stakeholder analysis progresses.',
    'Use the BTPM standard adoption approach: stakeholder impact, sponsor alignment, communication, training and enablement, feedback, adoption tracking, hypercare, and reinforcement.',
    'preparing', true, true, _uid
  ) RETURNING id INTO _plan_id;

  SELECT COALESCE(MAX(sort_order), -1) + 1 INTO _next_phase_sort
  FROM public.phases
  WHERE project_id = _project_id AND is_archived = false;

  INSERT INTO public.phases(
    organization_id, workspace_id, project_id,
    name, description, status, sort_order,
    start_date, target_end_date, created_by
  ) VALUES (
    _org, _ws, _project_id,
    _phase_name,
    'Contains people-side adoption work generated from the BTPM Adoption Plan template. Tasks here are normal BTPM tasks linked to Adoption Initiatives.',
    'planned', _next_phase_sort,
    _phase_start, _phase_end, _uid
  ) RETURNING id INTO _phase_id;

  FOR _init IN SELECT * FROM jsonb_array_elements(_template)
  LOOP
    _init_key := _init->>'key';

    IF _has_selection THEN
      SELECT COALESCE(array_agg(t->>'title' ORDER BY ord), ARRAY[]::text[])
        INTO _picked_titles
      FROM jsonb_array_elements(_init->'tasks') WITH ORDINALITY AS x(t, ord)
      WHERE format('%s.%s', _init_key, t->>'key') = ANY(_selected_keys);
    ELSE
      SELECT COALESCE(array_agg(t->>'title' ORDER BY ord), ARRAY[]::text[])
        INTO _picked_titles
      FROM jsonb_array_elements(_init->'tasks') WITH ORDINALITY AS x(t, ord);
    END IF;

    IF _has_selection THEN
      SELECT
        COALESCE(array_agg(ct->>'title' ORDER BY ord), ARRAY[]::text[]),
        COALESCE(array_agg(NULLIF(btrim(COALESCE(ct->>'description','')), '') ORDER BY ord), ARRAY[]::text[])
        INTO _custom_titles_for_init, _custom_descs_for_init
      FROM jsonb_array_elements(_custom_tasks) WITH ORDINALITY AS y(ct, ord)
      WHERE ct->>'initiative_key' = _init_key;
    ELSE
      _custom_titles_for_init := ARRAY[]::text[];
      _custom_descs_for_init  := ARRAY[]::text[];
    END IF;

    _selected_in_init := COALESCE(array_length(_picked_titles, 1), 0)
                       + COALESCE(array_length(_custom_titles_for_init, 1), 0);

    IF _selected_in_init = 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.adoption_initiatives(
      organization_id, workspace_id, project_id, adoption_plan_id,
      name, summary, readiness_area, status, priority, sort_order, created_by
    ) VALUES (
      _org, _ws, _project_id, _plan_id,
      _init->>'name',
      _init->>'summary',
      (_init->>'readiness_area')::public.adoption_readiness_area,
      'planned'::public.adoption_initiative_status,
      'medium'::public.pm_priority,
      (_init->>'sort_order')::int,
      _uid
    ) RETURNING id INTO _initiative_id;

    _initiative_count := _initiative_count + 1;
    _initiative_map := _initiative_map || jsonb_build_object(
      'initiative_id', _initiative_id, 'name', _init->>'name', 'key', _init_key
    );

    IF COALESCE(array_length(_picked_titles, 1), 0) > 0 THEN
      FOR i IN 1..array_length(_picked_titles, 1) LOOP
        INSERT INTO public.tasks(
          organization_id, workspace_id, project_id, phase_id,
          name, task_type, status, priority, sort_order,
          start_date, due_date,
          is_adoption_related, adoption_initiative_id, created_by
        ) VALUES (
          _org, _ws, _project_id, _phase_id,
          _picked_titles[i],
          'work_item'::public.task_type,
          'planned'::public.pm_status,
          'medium'::public.pm_priority,
          _task_sort,
          _phase_start, _phase_end,
          true, _initiative_id, _uid
        );
        _task_sort := _task_sort + 1;
        _task_count := _task_count + 1;
      END LOOP;
    END IF;

    IF COALESCE(array_length(_custom_titles_for_init, 1), 0) > 0 THEN
      FOR i IN 1..array_length(_custom_titles_for_init, 1) LOOP
        INSERT INTO public.tasks(
          organization_id, workspace_id, project_id, phase_id,
          name, description, task_type, status, priority, sort_order,
          start_date, due_date,
          is_adoption_related, adoption_initiative_id, created_by
        ) VALUES (
          _org, _ws, _project_id, _phase_id,
          _custom_titles_for_init[i],
          _custom_descs_for_init[i],
          'work_item'::public.task_type,
          'planned'::public.pm_status,
          'medium'::public.pm_priority,
          _task_sort,
          _phase_start, _phase_end,
          true, _initiative_id, _uid
        );
        _task_sort := _task_sort + 1;
        _task_count := _task_count + 1;
      END LOOP;
    END IF;
  END LOOP;

  PERFORM public.log_activity_event(
    _organization_id => _org,
    _actor_id        => _uid,
    _event_type      => 'adoption_template_generated',
    _target_type     => 'project',
    _target_id       => _project_id,
    _metadata        => jsonb_build_object(
      'adoption_plan_id', _plan_id,
      'created_phase_id', _phase_id,
      'created_initiative_count', _initiative_count,
      'created_task_count', _task_count,
      'phase_start_date', _phase_start,
      'phase_end_date',   _phase_end,
      'is_baselined_project', _is_baselined,
      'selection_mode', CASE WHEN _has_selection THEN 'selective' ELSE 'full_template' END,
      'selected_standard_task_count', _selected_std_count,
      'selected_custom_task_count', _custom_count
    )
  );

  RETURN jsonb_build_object(
    'adoption_plan_id', _plan_id,
    'phase_id', _phase_id,
    'phase_start_date', _phase_start,
    'phase_end_date', _phase_end,
    'initiative_count', _initiative_count,
    'task_count', _task_count,
    'initiatives', _initiative_map
  );
END $$;


--
-- Name: get_accessible_roadmap_story_published_versions(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_roadmap_story_published_versions(_query text DEFAULT NULL::text, _limit integer DEFAULT 50) RETURNS TABLE(version_id uuid, presentation_id uuid, story_pack_id uuid, version_number integer, title text, status text, published_by uuid, published_at timestamp with time zone, source_project_count integer, is_owner boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _user_org uuid;
  _lim integer := COALESCE(_limit, 50);
  _q text := NULLIF(btrim(COALESCE(_query, '')), '');
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF _lim < 1 THEN _lim := 1; END IF;
  IF _lim > 200 THEN _lim := 200; END IF;

  SELECT organization_id INTO _user_org FROM public.profiles WHERE id = _uid;
  IF _user_org IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT * FROM (
    SELECT
      v.id AS version_id,
      v.presentation_id,
      v.story_pack_id,
      v.version_number,
      public.btpm_decrypt(v.title_encrypted, v.organization_id) AS title,
      v.status,
      v.published_by,
      v.published_at,
      (SELECT count(*)::int FROM public.roadmap_story_presentation_version_projects p
        WHERE p.presentation_version_id = v.id) AS source_project_count,
      (v.published_by = _uid) AS is_owner
    FROM public.roadmap_story_presentation_versions v
    JOIN public.roadmap_story_presentations c ON c.id = v.presentation_id
    WHERE v.organization_id = _user_org
      AND v.status = 'active'
      AND c.status = 'active'
      AND public.can_view_roadmap_story_presentation_version(v.id, _uid) = true
  ) t
  WHERE _q IS NULL OR t.title ILIKE ('%' || _q || '%')
  ORDER BY t.published_at DESC
  LIMIT _lim;
END;
$$;


--
-- Name: get_active_ai_instruction_template(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_ai_instruction_template(_feature_key text) RETURNS public.ai_instruction_templates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _org_id uuid;
  _row public.ai_instruction_templates;
  _next int;
  _default_body text;
  _default_title text := 'Decision Brief Assistant — Structured Brief v2';
  _default_notes text := 'Introduced in AI.8.1c to align LLM behavior with the structured Decision Brief UX. Previous versions retained for rollback.';
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _feature_key NOT IN ('decision_case_brief') THEN
    RAISE EXCEPTION 'invalid feature_key';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.ai_instruction_templates
     WHERE organization_id = _org_id
       AND feature_key = _feature_key
       AND status = 'active'
  ) THEN
    _default_body := $TPL$You are the BTPM Decision Brief Assistant.

Your job is to prepare a structured decision brief for an internal business decision case using only the evidence and BTPM context provided in the request.

You must help the user make a decision, not produce a generic summary.

Core principles:
- Be evidence-grounded.
- Do not invent facts.
- Distinguish evidence, inference, assumptions, and gaps.
- Prefer concise executive wording over long analysis.
- Use the selected BTPM context as internal project evidence when it is resolved.
- Treat metadata-only, unresolved, unsupported, or permission-limited context as weak context.
- Treat skipped evidence files as unavailable.
- If the evidence is insufficient, say what is missing in the open questions field.
- Do not claim certainty when the evidence does not support it.

The Decision Brief must populate these business fields:

1. Executive summary
Provide a short executive-level summary of the situation, why the decision is needed, what is being asked, and why it matters now.

2. Options summary
Summarize the realistic decision options. If the evidence mainly supports one proposal, still describe the practical alternatives, such as approve the proposal, defer/rework, or maintain the current approach. Do not invent detailed options beyond what the evidence supports.

3. Requested decision
State the exact decision the decision-maker is being asked to make.

4. Recommendation
State the recommended option and the main evidence-based rationale.

5. Conditions / guardrails
List the conditions, caveats, controls, implementation guardrails, approval limits, or follow-up actions that should accompany the decision.

6. Residual risks
List the remaining risks after the recommendation and guardrails. Include risk areas, not generic warnings.

7. Open questions / missing information
List material gaps, assumptions, missing evidence, unresolved dependencies, or questions that should be clarified before or after the decision.

8. Decision readiness
Classify readiness as one of:
- ready_for_decision
- needs_clarification
- not_ready

Use:
- ready_for_decision only when the evidence is sufficient for a decision with manageable caveats.
- needs_clarification when the decision can progress but some important questions remain.
- not_ready when the evidence is too incomplete or contradictory.

9. Confidence
Classify confidence as one of:
- high
- medium
- low

Use:
- high when the evidence is consistent, specific, and sufficient.
- medium when the evidence is usable but incomplete or partially inferential.
- low when the evidence is weak, contradictory, mostly missing, or heavily assumption-based.

Output expectations:
- The runtime will require a JSON object with draft_markdown and structured_fields.
- Fill every structured field where the evidence allows.
- Prefer a concise evidence-based value over null.
- Return null only when the field is genuinely not inferable from the provided evidence.
- If you return null for a core field, explain the gap in open_questions_text.
- The draft_markdown must use these exact section headings so BTPM can display and recover the structure:
  ## Executive summary
  ## Options summary
  ## Requested decision
  ## Recommendation
  ## Conditions / guardrails
  ## Residual risks
  ## Open questions / missing information
  ## Decision readiness and confidence

Style:
- Write for senior business stakeholders.
- Be direct and practical.
- Avoid filler, motivational language, and generic project-management phrases.
- Use bullets where they improve clarity.
- Keep recommendations actionable.
$TPL$;

    -- Move any currently-active row (different title) to 'draft' rather than
    -- 'archived', so it remains reactivatable. In practice this branch only
    -- runs when no active row exists, but kept for safety/idempotency.
    UPDATE public.ai_instruction_templates
       SET status = 'draft'
     WHERE organization_id = _org_id
       AND feature_key = _feature_key
       AND status = 'active';

    SELECT COALESCE(MAX(version), 0) + 1 INTO _next
      FROM public.ai_instruction_templates
     WHERE organization_id = _org_id AND feature_key = _feature_key;

    INSERT INTO public.ai_instruction_templates
      (organization_id, feature_key, version, title, instruction_text, notes, status, activated_at)
    VALUES
      (_org_id, _feature_key, _next, _default_title, _default_body,
       _default_notes, 'active', now());
  END IF;

  SELECT t.id,
         t.organization_id,
         t.feature_key,
         t.version,
         t.title,
         public.btpm_decrypt(t.instruction_text, t.organization_id),
         CASE WHEN t.notes IS NULL THEN NULL
              ELSE public.btpm_decrypt(t.notes, t.organization_id) END,
         t.status,
         t.created_by,
         t.activated_by,
         t.activated_at,
         t.created_at,
         t.updated_at
    INTO _row
    FROM public.ai_instruction_templates t
   WHERE t.organization_id = _org_id
     AND t.feature_key = _feature_key
     AND t.status = 'active'
   LIMIT 1;

  RETURN _row;
END;
$_$;


--
-- Name: get_active_ai_instruction_template_for_org(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_ai_instruction_template_for_org(_organization_id uuid, _feature_key text) RETURNS public.ai_instruction_templates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _row public.ai_instruction_templates;
  _next int;
  _default_body text;
  _default_title text := 'Decision Brief Assistant — Structured Brief v2';
  _default_notes text := 'Introduced in AI.8.1c to align LLM behavior with the structured Decision Brief UX. Previous versions retained for rollback.';
BEGIN
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id required';
  END IF;
  IF _feature_key NOT IN ('decision_case_brief') THEN
    RAISE EXCEPTION 'invalid feature_key';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.ai_instruction_templates
     WHERE organization_id = _organization_id
       AND feature_key = _feature_key
       AND status = 'active'
  ) THEN
    _default_body := $TPL$You are the BTPM Decision Brief Assistant.

Your job is to prepare a structured decision brief for an internal business decision case using only the evidence and BTPM context provided in the request.

You must help the user make a decision, not produce a generic summary.

Core principles:
- Be evidence-grounded.
- Do not invent facts.
- Distinguish evidence, inference, assumptions, and gaps.
- Prefer concise executive wording over long analysis.
- Use the selected BTPM context as internal project evidence when it is resolved.
- Treat metadata-only, unresolved, unsupported, or permission-limited context as weak context.
- Treat skipped evidence files as unavailable.
- If the evidence is insufficient, say what is missing in the open questions field.
- Do not claim certainty when the evidence does not support it.

The Decision Brief must populate these business fields:

1. Executive summary
Provide a short executive-level summary of the situation, why the decision is needed, what is being asked, and why it matters now.

2. Options summary
Summarize the realistic decision options. If the evidence mainly supports one proposal, still describe the practical alternatives, such as approve the proposal, defer/rework, or maintain the current approach. Do not invent detailed options beyond what the evidence supports.

3. Requested decision
State the exact decision the decision-maker is being asked to make.

4. Recommendation
State the recommended option and the main evidence-based rationale.

5. Conditions / guardrails
List the conditions, caveats, controls, implementation guardrails, approval limits, or follow-up actions that should accompany the decision.

6. Residual risks
List the remaining risks after the recommendation and guardrails. Include risk areas, not generic warnings.

7. Open questions / missing information
List material gaps, assumptions, missing evidence, unresolved dependencies, or questions that should be clarified before or after the decision.

8. Decision readiness
Classify readiness as one of:
- ready_for_decision
- needs_clarification
- not_ready

Use:
- ready_for_decision only when the evidence is sufficient for a decision with manageable caveats.
- needs_clarification when the decision can progress but some important questions remain.
- not_ready when the evidence is too incomplete or contradictory.

9. Confidence
Classify confidence as one of:
- high
- medium
- low

Use:
- high when the evidence is consistent, specific, and sufficient.
- medium when the evidence is usable but incomplete or partially inferential.
- low when the evidence is weak, contradictory, mostly missing, or heavily assumption-based.

Output expectations:
- The runtime will require a JSON object with draft_markdown and structured_fields.
- Fill every structured field where the evidence allows.
- Prefer a concise evidence-based value over null.
- Return null only when the field is genuinely not inferable from the provided evidence.
- If you return null for a core field, explain the gap in open_questions_text.
- The draft_markdown must use these exact section headings so BTPM can display and recover the structure:
  ## Executive summary
  ## Options summary
  ## Requested decision
  ## Recommendation
  ## Conditions / guardrails
  ## Residual risks
  ## Open questions / missing information
  ## Decision readiness and confidence

Style:
- Write for senior business stakeholders.
- Be direct and practical.
- Avoid filler, motivational language, and generic project-management phrases.
- Use bullets where they improve clarity.
- Keep recommendations actionable.
$TPL$;

    UPDATE public.ai_instruction_templates
       SET status = 'draft'
     WHERE organization_id = _organization_id
       AND feature_key = _feature_key
       AND status = 'active';

    SELECT COALESCE(MAX(version), 0) + 1 INTO _next
      FROM public.ai_instruction_templates
     WHERE organization_id = _organization_id AND feature_key = _feature_key;

    INSERT INTO public.ai_instruction_templates
      (organization_id, feature_key, version, title, instruction_text, notes, status, activated_at)
    VALUES
      (_organization_id, _feature_key, _next, _default_title, _default_body,
       _default_notes, 'active', now());
  END IF;

  SELECT t.id,
         t.organization_id,
         t.feature_key,
         t.version,
         t.title,
         public.btpm_decrypt(t.instruction_text, t.organization_id),
         CASE WHEN t.notes IS NULL THEN NULL
              ELSE public.btpm_decrypt(t.notes, t.organization_id) END,
         t.status,
         t.created_by,
         t.activated_by,
         t.activated_at,
         t.created_at,
         t.updated_at
    INTO _row
    FROM public.ai_instruction_templates t
   WHERE t.organization_id = _organization_id
     AND t.feature_key = _feature_key
     AND t.status = 'active'
   LIMIT 1;

  RETURN _row;
END;
$_$;


--
-- Name: get_admin_user_detail(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_user_detail(_organization_id uuid, _user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _result jsonb;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT jsonb_build_object('user_id', p.id, 'display_name', btpm_decrypt(p.display_name, _organization_id), 'email', p.email, 'avatar_url', btpm_decrypt(p.avatar_url, _organization_id), 'created_at', p.created_at, 'is_active', p.is_active, 'is_org_admin', EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = p.id AND ur.organization_id = _organization_id AND ur.role = 'org_admin' AND ur.workspace_id IS NULL), 'workspaces', COALESCE((SELECT jsonb_agg(jsonb_build_object('workspace_id', w.id, 'workspace_name', w.name, 'membership_id', wm.id, 'role', (SELECT ur.role::text FROM public.user_roles ur WHERE ur.user_id = p.id AND ur.workspace_id = w.id AND ur.organization_id = _organization_id ORDER BY CASE ur.role WHEN 'workspace_admin' THEN 1 WHEN 'project_manager' THEN 2 WHEN 'contributor' THEN 3 WHEN 'viewer' THEN 4 ELSE 5 END LIMIT 1)) ORDER BY w.name) FROM public.workspace_memberships wm JOIN public.workspaces w ON w.id = wm.workspace_id AND w.organization_id = _organization_id WHERE wm.user_id = p.id), '[]'::jsonb)) INTO _result FROM public.profiles p WHERE p.id = _user_id AND p.organization_id = _organization_id;
  IF _result IS NULL THEN RAISE EXCEPTION 'User not found in this organization'; END IF;
  RETURN _result;
END;
$$;


--
-- Name: ai_feature_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_feature_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    feature_key text NOT NULL,
    provider text DEFAULT 'openai'::text NOT NULL,
    model_registry_id uuid NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    reasoning_effort text,
    max_files_per_request integer,
    max_individual_file_mb integer,
    max_total_file_mb integer,
    require_user_confirmation boolean DEFAULT true NOT NULL,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_feature_settings_feature_check CHECK ((feature_key = ANY (ARRAY['btpm_guide'::text, 'decision_cases'::text, 'roadmap_story'::text]))),
    CONSTRAINT ai_feature_settings_files_pos CHECK (((max_files_per_request IS NULL) OR (max_files_per_request > 0))),
    CONSTRAINT ai_feature_settings_indiv_pos CHECK (((max_individual_file_mb IS NULL) OR (max_individual_file_mb > 0))),
    CONSTRAINT ai_feature_settings_provider_check CHECK ((provider = 'openai'::text)),
    CONSTRAINT ai_feature_settings_reasoning_check CHECK (((reasoning_effort IS NULL) OR (reasoning_effort = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text])))),
    CONSTRAINT ai_feature_settings_total_pos CHECK (((max_total_file_mb IS NULL) OR (max_total_file_mb > 0)))
);


--
-- Name: get_ai_feature_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_feature_settings() RETURNS SETOF public.ai_feature_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
  _guide_model uuid;
  _dc_model uuid;
  _rs_model uuid;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO _guide_model FROM public.ai_model_registry WHERE provider='openai' AND recommended_for_guide = true AND active = true ORDER BY sort_order LIMIT 1;
  SELECT id INTO _dc_model    FROM public.ai_model_registry WHERE provider='openai' AND recommended_for_decision_cases = true AND active = true ORDER BY sort_order LIMIT 1;
  SELECT id INTO _rs_model    FROM public.ai_model_registry WHERE provider='openai' AND recommended_for_roadmap_story = true AND active = true ORDER BY sort_order LIMIT 1;
  IF _rs_model IS NULL THEN
    SELECT id INTO _rs_model FROM public.ai_model_registry WHERE provider='openai' AND capability_tier='low_cost' AND active = true ORDER BY sort_order LIMIT 1;
  END IF;
  IF _rs_model IS NULL THEN
    SELECT id INTO _rs_model FROM public.ai_model_registry WHERE provider='openai' AND active = true ORDER BY sort_order LIMIT 1;
  END IF;

  INSERT INTO public.ai_feature_settings (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, require_user_confirmation)
  VALUES (_org_id, 'btpm_guide', 'openai', _guide_model, false, NULL, false)
  ON CONFLICT (organization_id, feature_key) DO NOTHING;

  INSERT INTO public.ai_feature_settings (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, max_files_per_request, max_individual_file_mb, max_total_file_mb, require_user_confirmation)
  VALUES (_org_id, 'decision_cases', 'openai', _dc_model, false, 'high', 5, 10, 25, true)
  ON CONFLICT (organization_id, feature_key) DO NOTHING;

  INSERT INTO public.ai_feature_settings (organization_id, feature_key, provider, model_registry_id, enabled, reasoning_effort, max_files_per_request, max_individual_file_mb, max_total_file_mb, require_user_confirmation)
  VALUES (_org_id, 'roadmap_story', 'openai', _rs_model, false, 'low', 5, 10, 25, true)
  ON CONFLICT (organization_id, feature_key) DO NOTHING;

  RETURN QUERY SELECT * FROM public.ai_feature_settings WHERE organization_id = _org_id ORDER BY feature_key;
END;
$$;


--
-- Name: get_api_d_consent_context(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_api_d_consent_context(_client_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  _uid uuid := auth.uid();
  _client public.api_clients%rowtype;
  _policy public.api_client_policy_versions%rowtype;
  _policy_count integer;
  _org_names text[];
  _ws_names text[];
  _org_count integer;
  _ws_count integer;
  _org_ids uuid[];
  _ws_ids uuid[];
  _capabilities jsonb;
  _acknowledged boolean;
  _fail_closed constant jsonb := jsonb_build_object('eligible', false);
begin
  -- Authentication required.
  if _uid is null then
    return _fail_closed;
  end if;

  -- Validate input: non-null, non-empty, bounded length, safe alphabet.
  if _client_key is null then
    return _fail_closed;
  end if;
  if length(_client_key) < 3 or length(_client_key) > 64 then
    return _fail_closed;
  end if;
  if _client_key !~ '^[a-z0-9][a-z0-9_.-]{1,62}[a-z0-9]$' then
    return _fail_closed;
  end if;

  -- Caller must be an active, non-deactivated BTPM user profile.
  if not exists (
    select 1 from public.profiles p
    where p.id = _uid and p.is_active = true
  ) then
    return _fail_closed;
  end if;

  -- Resolve active client by exact client_key.
  select * into _client
  from public.api_clients
  where client_key = _client_key
    and lifecycle_status = 'active'
  limit 1;

  if _client.id is null then
    return _fail_closed;
  end if;

  -- Resolve exactly one current active policy version for that client.
  select count(*) into _policy_count
  from public.api_client_policy_versions
  where api_client_id = _client.id
    and lifecycle_status = 'active';

  if _policy_count <> 1 then
    return _fail_closed;
  end if;

  select * into _policy
  from public.api_client_policy_versions
  where api_client_id = _client.id
    and lifecycle_status = 'active'
  limit 1;

  -- Derive eligible Organizations:
  --   authoritative active organization membership
  --   ∩ active tenant chain
  --   ∩ current active tenant membership for the caller on that tenant
  --   ∩ enabled API-C Organization enablement for this client
  --   with tenant consistency preserved.
  select
    coalesce(array_agg(o.name order by o.name), array[]::text[]),
    count(*)::integer,
    coalesce(array_agg(o.id), array[]::uuid[])
  into _org_names, _org_count, _org_ids
  from public.organization_memberships om
  join public.organizations o
    on o.id = om.organization_id
  join public.tenants t
    on t.id = o.tenant_id
   and t.id = om.tenant_id
  join public.tenant_memberships tm_o
    on tm_o.tenant_id = t.id
   and tm_o.user_id = _uid
   and tm_o.status = 'active'
   and tm_o.deactivated_at is null
  join public.api_organization_client_enablements oe
    on oe.organization_id = o.id
   and oe.tenant_id = t.id
   and oe.api_client_id = _client.id
   and oe.lifecycle_status = 'enabled'
  where om.user_id = _uid
    and om.status = 'active'
    and om.deactivated_at is null
    and t.status = 'active'
    and t.suspended_at is null
    and t.archived_at is null
    and t.purged_at is null;

  if _org_count = 0 then
    return _fail_closed;
  end if;

  -- Derive eligible Workspaces independently:
  --   authoritative workspace membership
  --   ∩ active workspace
  --   ∩ current active tenant membership for the caller on the workspace's tenant
  --   ∩ enabled API-C Workspace enablement for this client
  --   ∩ workspace org must itself be in the eligible-org set (tenant chain
  --     with an independently required tenant membership).
  select
    coalesce(array_agg(w.name order by w.name), array[]::text[]),
    count(*)::integer,
    coalesce(array_agg(w.id), array[]::uuid[])
  into _ws_names, _ws_count, _ws_ids
  from public.workspace_memberships wm
  join public.workspaces w
    on w.id = wm.workspace_id
  join public.organizations o
    on o.id = w.organization_id
  join public.tenants t
    on t.id = o.tenant_id
  join public.tenant_memberships tm_w
    on tm_w.tenant_id = t.id
   and tm_w.user_id = _uid
   and tm_w.status = 'active'
   and tm_w.deactivated_at is null
  join public.api_workspace_client_enablements we
    on we.workspace_id = w.id
   and we.organization_id = o.id
   and we.tenant_id = t.id
   and we.api_client_id = _client.id
   and we.lifecycle_status = 'enabled'
  -- Require the same Org to be independently authorized above.
  join public.organization_memberships om2
    on om2.organization_id = o.id
   and om2.tenant_id = t.id
   and om2.user_id = _uid
   and om2.status = 'active'
   and om2.deactivated_at is null
  join public.tenant_memberships tm_w2
    on tm_w2.tenant_id = t.id
   and tm_w2.user_id = _uid
   and tm_w2.status = 'active'
   and tm_w2.deactivated_at is null
  join public.api_organization_client_enablements oe2
    on oe2.organization_id = o.id
   and oe2.tenant_id = t.id
   and oe2.api_client_id = _client.id
   and oe2.lifecycle_status = 'enabled'
  where wm.user_id = _uid
    and w.is_active = true
    and w.is_archived = false
    and t.status = 'active'
    and t.suspended_at is null
    and t.archived_at is null
    and t.purged_at is null;

  -- Acknowledgement flag for the exact user + client + current policy version.
  select exists (
    select 1
    from public.api_user_policy_acknowledgements
    where user_id = _uid
      and api_client_id = _client.id
      and policy_version_id = _policy.id
      and revoked_at is null
  ) into _acknowledged;

  -- Effective, catalogue-controlled capability context for the caller's
  -- eligible Organization / Workspace scope. Additive model only: a disabled
  -- direct Workspace grant never overrides an enabled Organization grant.
  with org_scoped as (
    select
      cat.api_version,
      cat.capability_kind,
      cat.capability_key,
      cat.scope_level,
      cat.display_name,
      cat.description
    from public.api_capability_grants g
    join public.organizations org
      on org.id = g.organization_id
    join public.api_client_supported_capabilities sc
      on sc.api_client_id = g.api_client_id
     and sc.api_version = g.api_version
     and sc.capability_kind = g.capability_kind
     and sc.capability_key = g.capability_key
     and sc.lifecycle_status = 'enabled'
    join public.api_capability_catalogue cat
      on cat.api_version = sc.api_version
     and cat.capability_kind = sc.capability_kind
     and cat.capability_key = sc.capability_key
     and cat.lifecycle_status = 'active'
    where g.api_client_id = _client.id
      and g.lifecycle_status = 'enabled'
      and g.workspace_id is null
      and g.organization_id = any(_org_ids)
      and g.tenant_id = org.tenant_id
      and cat.scope_level = 'organization'
  ),
  workspace_inherited_from_organization as (
    -- Workspace-scoped capabilities enabled by an Organization-level grant.
    -- Runtime authorization accepts such a grant for a Workspace request, so
    -- the consent context must show it — but only when the caller actually has
    -- an eligible Workspace inside that exact Organization.
    select
      cat.api_version,
      cat.capability_kind,
      cat.capability_key,
      cat.scope_level,
      cat.display_name,
      cat.description
    from public.api_capability_grants g
    join public.organizations org
      on org.id = g.organization_id
    join public.api_client_supported_capabilities sc
      on sc.api_client_id = g.api_client_id
     and sc.api_version = g.api_version
     and sc.capability_kind = g.capability_kind
     and sc.capability_key = g.capability_key
     and sc.lifecycle_status = 'enabled'
    join public.api_capability_catalogue cat
      on cat.api_version = sc.api_version
     and cat.capability_kind = sc.capability_kind
     and cat.capability_key = sc.capability_key
     and cat.lifecycle_status = 'active'
    where g.api_client_id = _client.id
      and g.lifecycle_status = 'enabled'
      and g.workspace_id is null
      and g.organization_id = any(_org_ids)
      and g.tenant_id = org.tenant_id
      and cat.scope_level = 'workspace'
      and exists (
        select 1
        from public.workspaces eligible_ws
        where eligible_ws.id = any(_ws_ids)
          and eligible_ws.organization_id = g.organization_id
      )
  ),
  workspace_scoped as (
    select
      cat.api_version,
      cat.capability_kind,
      cat.capability_key,
      cat.scope_level,
      cat.display_name,
      cat.description
    from public.api_capability_grants g
    join public.workspaces ws
      on ws.id = g.workspace_id
    join public.organizations org
      on org.id = ws.organization_id
     and org.id = g.organization_id
    join public.api_client_supported_capabilities sc
      on sc.api_client_id = g.api_client_id
     and sc.api_version = g.api_version
     and sc.capability_kind = g.capability_kind
     and sc.capability_key = g.capability_key
     and sc.lifecycle_status = 'enabled'
    join public.api_capability_catalogue cat
      on cat.api_version = sc.api_version
     and cat.capability_kind = sc.capability_kind
     and cat.capability_key = sc.capability_key
     and cat.lifecycle_status = 'active'
    where g.api_client_id = _client.id
      and g.lifecycle_status = 'enabled'
      and g.workspace_id = any(_ws_ids)
      and g.organization_id = any(_org_ids)
      and g.tenant_id = org.tenant_id
      and cat.scope_level = 'workspace'
  ),
  unioned as (
    select * from org_scoped
    union all
    select * from workspace_inherited_from_organization
    union all
    select * from workspace_scoped
  ),
  deduplicated as (
    select distinct
      api_version,
      capability_kind,
      capability_key,
      scope_level,
      display_name,
      description
    from unioned
  ),
  ordered as (
    select
      api_version,
      display_name,
      description,
      scope_level,
      capability_key,
      case scope_level
        when 'organization' then 1
        when 'workspace' then 2
        when 'project' then 3
        else 4
      end as scope_order
    from deduplicated
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'api_version', api_version,
        'display_name', display_name,
        'description', description,
        'scope_level', scope_level
      )
      order by api_version asc, scope_order asc, lower(display_name) asc, capability_key asc
    ),
    '[]'::jsonb
  )
  into _capabilities
  from ordered;

  return jsonb_build_object(
    'eligible', true,
    'client', jsonb_build_object(
      'client_key', _client.client_key,
      'display_name', _client.display_name
    ),
    'policy', jsonb_build_object(
      'version', _policy.version,
      'policy_uri', _policy.policy_uri,
      'policy_digest', _policy.policy_digest,
      'effective_at', _policy.effective_at
    ),
    'acknowledged', _acknowledged,
    'organizations', jsonb_build_object(
      'count', _org_count,
      'display_names', to_jsonb(_org_names)
    ),
    'workspaces', jsonb_build_object(
      'count', _ws_count,
      'display_names', to_jsonb(coalesce(_ws_names, array[]::text[]))
    ),
    'capabilities', coalesce(_capabilities, '[]'::jsonb)
  );
exception
  when others then
    return _fail_closed;
end;
$_$;


--
-- Name: get_api_d_oauth_consent_gate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_api_d_oauth_consent_gate(_oauth_client_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  _fail_closed constant jsonb := jsonb_build_object('eligible', false);
  _client_key text;
  _ctx jsonb;
  _acknowledged jsonb;
begin
  -- Input contract mirrors the accepted api_clients oauth_client_id structural
  -- contract: non-null, non-empty, already trimmed, already lowercase. No
  -- UUID-only assumption, no second identifier format, no maximum length.
  if _oauth_client_id is null then
    return _fail_closed;
  end if;
  if length(_oauth_client_id) = 0 then
    return _fail_closed;
  end if;
  if _oauth_client_id <> btrim(_oauth_client_id) then
    return _fail_closed;
  end if;
  if _oauth_client_id <> lower(_oauth_client_id) then
    return _fail_closed;
  end if;

  -- Exact client resolution. Identity correlation is ONLY the unique
  -- oauth_client_id; display name and redirect metadata are never used. Only
  -- active clients resolve; draft/suspended/retired are indistinguishable.
  select c.client_key
    into _client_key
  from public.api_clients c
  where c.oauth_client_id = _oauth_client_id
    and c.lifecycle_status = 'active'
  limit 1;

  if _client_key is null then
    return _fail_closed;
  end if;

  -- Sole business-consent authority (caller identity, active policy version,
  -- Organization/Workspace eligibility, enablement, acknowledgement,
  -- capability context). Not duplicated here.
  _ctx := public.get_api_d_consent_context(_client_key);

  if _ctx is null or jsonb_typeof(_ctx) <> 'object' then
    return _fail_closed;
  end if;
  if coalesce((_ctx -> 'eligible')::text, '') <> 'true' then
    return _fail_closed;
  end if;
  if coalesce(_ctx #>> '{client,client_key}', '') <> _client_key then
    return _fail_closed;
  end if;

  _acknowledged := _ctx -> 'acknowledged';
  if _acknowledged is null or jsonb_typeof(_acknowledged) <> 'boolean' then
    return _fail_closed;
  end if;

  return jsonb_build_object(
    'eligible', true,
    'client_key', _client_key,
    'acknowledged', (_acknowledged)::boolean
  );
end;
$$;


--
-- Name: get_comment_mention_email_status(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_comment_mention_email_status(_target_type text, _target_id uuid) RETURNS TABLE(comment_id uuid, status text, total_count integer, sent_count integer, pending_count integer, failed_count integer, skipped_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    n.source_comment_id AS comment_id,
    CASE
      WHEN count(*) FILTER (WHERE n.status = 'failed')  = count(*) THEN 'failed'
      WHEN count(*) FILTER (WHERE n.status = 'sent')    = count(*) THEN 'sent'
      WHEN count(*) FILTER (WHERE n.status = 'pending') = count(*) THEN 'queued'
      WHEN count(*) FILTER (WHERE n.status = 'sent')    > 0
       AND count(*) FILTER (WHERE n.status IN ('failed','skipped')) > 0 THEN 'partial'
      WHEN count(*) FILTER (WHERE n.status = 'sent')    > 0 THEN 'partial'
      ELSE 'queued'
    END AS status,
    count(*)::integer AS total_count,
    count(*) FILTER (WHERE n.status = 'sent')::integer    AS sent_count,
    count(*) FILTER (WHERE n.status = 'pending')::integer AS pending_count,
    count(*) FILTER (WHERE n.status = 'failed')::integer  AS failed_count,
    count(*) FILTER (WHERE n.status = 'skipped')::integer AS skipped_count
  FROM public.notification_outbox n
  JOIN public.comments c ON c.id = n.source_comment_id
  WHERE n.event_type = 'mention'
    AND n.source_comment_id IS NOT NULL
    AND c.target_type = _target_type
    AND c.target_id = _target_id
    AND c.author_id = auth.uid()
  GROUP BY n.source_comment_id;
END;
$$;


--
-- Name: get_decrypted_knowledge_article(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decrypted_knowledge_article(_id uuid) RETURNS TABLE(id uuid, organization_id uuid, category_id uuid, title text, slug text, article_type public.knowledge_article_type, summary text, body text, tooltip_excerpt text, status public.knowledge_article_status, visibility public.knowledge_article_visibility, related_route text, related_object_type text, related_object_id uuid, workspace_id uuid, owner_id uuid, version integer, published_at timestamp with time zone, archived_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org      uuid := public.get_user_org_id(auth.uid());
  v_is_admin boolean;
  v_row      public.knowledge_articles%ROWTYPE;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  SELECT * INTO v_row FROM public.knowledge_articles WHERE knowledge_articles.id = _id;
  IF v_row.id IS NULL OR v_row.organization_id <> v_org THEN RETURN; END IF;

  v_is_admin := public.is_org_admin(auth.uid(), v_org);
  IF NOT v_is_admin THEN
    IF v_row.status <> 'published' THEN RETURN; END IF;
    IF v_row.visibility = 'admin_only' THEN RETURN; END IF;
    IF v_row.visibility = 'workspace_scoped' THEN
      IF v_row.workspace_id IS NULL OR NOT public.is_workspace_member(auth.uid(), v_row.workspace_id) THEN RETURN; END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_row.id, v_row.organization_id, v_row.category_id,
    public.btpm_decrypt(v_row.title, v_row.organization_id),
    v_row.slug, v_row.article_type,
    public.btpm_decrypt(v_row.summary, v_row.organization_id),
    public.btpm_decrypt(v_row.body, v_row.organization_id),
    public.btpm_decrypt(v_row.tooltip_excerpt, v_row.organization_id),
    v_row.status, v_row.visibility,
    v_row.related_route, v_row.related_object_type, v_row.related_object_id,
    v_row.workspace_id, v_row.owner_id, v_row.version,
    v_row.published_at, v_row.archived_at, v_row.created_at, v_row.updated_at;
END; $$;


--
-- Name: get_decrypted_phase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decrypted_phase(_phase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _phase phases%ROWTYPE;
  _result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _phase FROM phases WHERE id = _phase_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF public.is_user_org_member(v_caller, _phase.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  -- Authorization: same as existing scoped policy
  IF NOT (is_workspace_member(v_caller, _phase.workspace_id)
          OR is_org_admin(v_caller, _phase.organization_id)) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  _result := jsonb_build_object(
    'id', _phase.id,
    'organization_id', _phase.organization_id,
    'workspace_id', _phase.workspace_id,
    'project_id', _phase.project_id,
    'name', CASE WHEN _phase.name IS NULL THEN NULL ELSE btpm_decrypt(_phase.name, _phase.organization_id) END,
    'description', CASE WHEN _phase.description IS NULL THEN NULL ELSE btpm_decrypt(_phase.description, _phase.organization_id) END,
    'status', _phase.status,
    'phase_type', _phase.phase_type,
    'sort_order', _phase.sort_order,
    'start_date', _phase.start_date,
    'target_end_date', _phase.target_end_date,
    'baseline_start_date', _phase.baseline_start_date,
    'baseline_end_date', _phase.baseline_end_date,
    'added_after_baseline', _phase.added_after_baseline,
    'is_archived', _phase.is_archived,
    'created_by', _phase.created_by,
    'created_at', _phase.created_at,
    'updated_at', _phase.updated_at
  );

  RETURN _result;
END;
$$;


--
-- Name: get_decrypted_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decrypted_profile(_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _result jsonb; _target_id uuid;
BEGIN
  _target_id := COALESCE(_user_id, auth.uid());
  IF _target_id IS NULL THEN RETURN NULL; END IF;
  IF NOT is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT jsonb_build_object('id', p.id, 'email', p.email, 'is_active', p.is_active, 'organization_id', p.organization_id, 'created_at', p.created_at, 'updated_at', p.updated_at, 'display_name', CASE WHEN p.organization_id IS NOT NULL THEN btpm_decrypt(p.display_name, p.organization_id) ELSE p.display_name END, 'avatar_url', CASE WHEN p.organization_id IS NOT NULL THEN btpm_decrypt(p.avatar_url, p.organization_id) ELSE p.avatar_url END) INTO _result FROM profiles p WHERE p.id = _target_id AND (p.id = auth.uid() OR p.organization_id IS NULL OR p.organization_id = get_user_org_id(auth.uid()));
  RETURN _result;
END;
$$;


--
-- Name: get_decrypted_program(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decrypted_program(_program_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_prog public.programs%ROWTYPE;
  _result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_prog FROM public.programs WHERE id = _program_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF NOT public.is_user_org_member(v_caller, v_prog.organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF NOT (
    public.is_workspace_member(v_caller, v_prog.workspace_id)
    OR public.is_org_admin(v_caller, v_prog.organization_id)
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT jsonb_build_object(
    'id', pg.id,
    'name', public.btpm_decrypt(pg.name, pg.organization_id),
    'description', public.btpm_decrypt(pg.description, pg.organization_id),
    'status', pg.status,
    'is_archived', pg.is_archived,
    'workspace_id', pg.workspace_id,
    'organization_id', pg.organization_id,
    'created_by', pg.created_by,
    'created_at', pg.created_at,
    'updated_at', pg.updated_at
  ) INTO _result FROM public.programs pg WHERE pg.id = _program_id;
  RETURN _result;
END;
$$;


--
-- Name: get_decrypted_project(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decrypted_project(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_row public.projects%ROWTYPE;
  v_org uuid;
  v_pi  public.portfolio_items%ROWTYPE;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  v_org := v_row.organization_id;

  IF public.is_user_org_member(v_caller, v_row.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project_or_demo(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_row.portfolio_item_id IS NOT NULL THEN
    SELECT * INTO v_pi FROM public.portfolio_items WHERE id = v_row.portfolio_item_id;
  END IF;

  RETURN jsonb_build_object(
    'id', v_row.id, 'organization_id', v_row.organization_id,
    'workspace_id', v_row.workspace_id, 'program_id', v_row.program_id, 'name', v_row.name,
    'description',         public.btpm_decrypt(v_row.description,         v_org),
    'charter',             public.btpm_decrypt(v_row.charter,             v_org),
    'goals',               public.btpm_decrypt(v_row.goals,               v_org),
    'scope_in',            public.btpm_decrypt(v_row.scope_in,            v_org),
    'scope_out',           public.btpm_decrypt(v_row.scope_out,           v_org),
    'business_case',       public.btpm_decrypt(v_row.business_case,       v_org),
    'success_criteria',    public.btpm_decrypt(v_row.success_criteria,    v_org),
    'completion_criteria', public.btpm_decrypt(v_row.completion_criteria, v_org),
    'budget_narrative',    public.btpm_decrypt(v_row.budget_narrative,    v_org),
    'assumptions',         public.btpm_decrypt(v_row.assumptions,         v_org),
    'constraints',         public.btpm_decrypt(v_row.constraints,         v_org),
    'status', v_row.status, 'priority', v_row.priority, 'project_stage', v_row.project_stage,
    'delivery_model', v_row.delivery_model,
    'start_date', v_row.start_date, 'target_end_date', v_row.target_end_date,
    'actual_start_date', v_row.actual_start_date, 'actual_end_date', v_row.actual_end_date,
    'baseline_start_date', v_row.baseline_start_date, 'baseline_end_date', v_row.baseline_end_date,
    'is_baselined', v_row.is_baselined, 'baseline_approved_at', v_row.baseline_approved_at,
    'baseline_approved_by', v_row.baseline_approved_by,
    'agile_enabled', v_row.agile_enabled, 'is_archived', v_row.is_archived,
    'created_at', v_row.created_at, 'updated_at', v_row.updated_at, 'created_by', v_row.created_by,
    'portfolio_item_id',        v_row.portfolio_item_id,
    'portfolio_name',           CASE WHEN v_pi.id IS NOT NULL THEN public.btpm_decrypt(v_pi.name, v_org) ELSE NULL END,
    'portfolio_code',           CASE WHEN v_pi.id IS NOT NULL THEN public.btpm_decrypt(v_pi.code, v_org) ELSE NULL END,
    'portfolio_lifecycle_state', v_pi.lifecycle_state,
    'portfolio_is_archived',     CASE WHEN v_pi.id IS NOT NULL THEN v_pi.is_archived ELSE NULL END
  );
END;
$$;


--
-- Name: get_decrypted_project_closure_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_decrypted_project_closure_summary(_project_id uuid) RETURNS TABLE(id uuid, organization_id uuid, workspace_id uuid, project_id uuid, outcome_summary text, benefits_summary text, achievements_summary text, open_items_summary text, transition_notes text, created_by uuid, updated_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_access(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Access denied to project %', _project_id USING ERRCODE='42501';
  END IF;

  RETURN QUERY
  SELECT
    s.id,
    s.organization_id,
    s.workspace_id,
    s.project_id,
    CASE WHEN s.outcome_summary_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(s.outcome_summary_encrypted, s.organization_id) END,
    CASE WHEN s.benefits_summary_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(s.benefits_summary_encrypted, s.organization_id) END,
    CASE WHEN s.achievements_summary_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(s.achievements_summary_encrypted, s.organization_id) END,
    CASE WHEN s.open_items_summary_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(s.open_items_summary_encrypted, s.organization_id) END,
    CASE WHEN s.transition_notes_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(s.transition_notes_encrypted, s.organization_id) END,
    s.created_by,
    s.updated_by,
    s.created_at,
    s.updated_at
  FROM public.project_closure_summaries s
  WHERE s.project_id = _project_id
  LIMIT 1;
END;
$$;


