--
-- Name: get_kpi_app_payload_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_kpi_app_payload_source(_outbox_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _result json;
  _org uuid;
  _ws  uuid;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT o.organization_id, o.workspace_id
    INTO _org, _ws
    FROM public.kpi_app_submission_outbox o
   WHERE o.id = _outbox_id;

  IF _org IS NULL THEN
    RAISE EXCEPTION 'Outbox row not found';
  END IF;

  IF NOT (is_org_admin(auth.uid(), _org) OR is_workspace_admin_or_higher(auth.uid(), _ws)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT json_build_object(
    'outbox', json_build_object(
      'id', o.id,
      'organization_id', o.organization_id,
      'workspace_id', o.workspace_id,
      'project_id', o.project_id,
      'mapping_id', o.mapping_id,
      'kpi_definition_id', o.kpi_definition_id,
      'source_snapshot_id', o.source_snapshot_id,
      'reporting_period_start', o.reporting_period_start,
      'reporting_period_end', o.reporting_period_end,
      'validity_date', o.validity_date,
      'source_value_type', o.source_value_type,
      'source_value_amount', o.source_value_amount,
      'source_string_value', btpm_decrypt(o.source_string_value, o.organization_id),
      'source_comment', btpm_decrypt(o.source_comment, o.organization_id),
      'source_action_plan', btpm_decrypt(o.source_action_plan, o.organization_id),
      'submission_mode', o.submission_mode,
      'status', o.status,
      'carry_forward_used', o.carry_forward_used,
      'submitted_by', o.submitted_by
    ),
    'mapping', json_build_object(
      'id', m.id,
      'is_active', m.is_active,
      'scenario_id', m.scenario_id,
      'currency_id', m.currency_id,
      'external_kpi_id', m.external_kpi_id,
      'reporting_frequency', m.reporting_frequency,
      'entered_by_email_source', m.entered_by_email_source,
      'entered_by_user_id', m.entered_by_user_id,
      'comment_source', m.comment_source,
      'action_plan_source', m.action_plan_source,
      'carry_forward_allowed', m.carry_forward_allowed
    ),
    'snapshot', json_build_object(
      'id', s.id,
      'period_start', s.period_start,
      'period_end', s.period_end,
      'value_type', s.value_type,
      'value_amount', s.value_amount,
      'string_value', btpm_decrypt(s.string_value, s.organization_id),
      'comment', btpm_decrypt(s.comment, s.organization_id),
      'action_plan', btpm_decrypt(s.action_plan, s.organization_id),
      'created_by', s.created_by,
      'calculation_status', s.calculation_status
    ),
    'snapshot_created_by_email', (
      SELECT p.email FROM public.profiles p WHERE p.id = s.created_by
    ),
    'configured_user_email', (
      SELECT p.email FROM public.profiles p WHERE p.id = m.entered_by_user_id
    ),
    'caller_email', (
      SELECT p.email FROM public.profiles p WHERE p.id = auth.uid()
    )
  ) INTO _result
  FROM public.kpi_app_submission_outbox o
  JOIN public.kpi_app_mappings m ON m.id = o.mapping_id
  JOIN public.kpi_snapshots s ON s.id = o.source_snapshot_id
  WHERE o.id = _outbox_id;

  RETURN _result;
END;
$$;


--
-- Name: get_kpi_snapshot_decrypted_for_mapping(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_kpi_snapshot_decrypted_for_mapping(_mapping_id uuid, _snapshot_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _m record;
  _s record;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT id, organization_id, workspace_id, project_id, kpi_definition_id, is_active
    INTO _m FROM public.kpi_app_mappings WHERE id = _mapping_id;
  IF _m.id IS NULL THEN
    RAISE EXCEPTION 'Mapping not found';
  END IF;

  IF NOT (is_org_admin(auth.uid(), _m.organization_id)
          OR is_workspace_admin_or_higher(auth.uid(), _m.workspace_id)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT id, organization_id, project_id, kpi_definition_id, value_type,
         value_amount, period_start, period_end, string_value, comment, action_plan
    INTO _s FROM public.kpi_snapshots WHERE id = _snapshot_id;
  IF _s.id IS NULL THEN
    RAISE EXCEPTION 'Snapshot not found';
  END IF;

  IF _s.organization_id <> _m.organization_id
     OR _s.project_id <> _m.project_id
     OR _s.kpi_definition_id <> _m.kpi_definition_id THEN
    RAISE EXCEPTION 'Snapshot scope mismatch';
  END IF;

  RETURN json_build_object(
    'id', _s.id,
    'value_type', _s.value_type,
    'value_amount', _s.value_amount,
    'period_start', _s.period_start,
    'period_end', _s.period_end,
    'string_value', btpm_decrypt(_s.string_value, _s.organization_id),
    'comment', btpm_decrypt(_s.comment, _s.organization_id),
    'action_plan', btpm_decrypt(_s.action_plan, _s.organization_id)
  );
END;
$$;


--
-- Name: get_kpi_snapshot_decrypted_for_mapping_system(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_kpi_snapshot_decrypted_for_mapping_system(_mapping_id uuid, _snapshot_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _m record;
  _kdef record;
  _ext record;
  _s record;
BEGIN
  -- Mapping
  SELECT id, organization_id, workspace_id, project_id, kpi_definition_id,
         external_kpi_id, is_active, auto_submit_enabled, reporting_frequency,
         entered_by_email_source, entered_by_user_id
    INTO _m FROM public.kpi_app_mappings WHERE id = _mapping_id;
  IF _m.id IS NULL THEN
    RAISE EXCEPTION 'Mapping not found';
  END IF;
  IF NOT _m.is_active THEN
    RAISE EXCEPTION 'Mapping inactive';
  END IF;
  IF NOT _m.auto_submit_enabled THEN
    RAISE EXCEPTION 'Mapping auto_submit_enabled=false';
  END IF;
  IF _m.reporting_frequency = 'manual_only' THEN
    RAISE EXCEPTION 'Mapping is manual_only';
  END IF;
  IF _m.entered_by_email_source = 'submitted_by_user' THEN
    RAISE EXCEPTION 'entered_by_email_source requires human user';
  END IF;
  IF _m.entered_by_email_source = 'configured_user'
     AND _m.entered_by_user_id IS NULL THEN
    RAISE EXCEPTION 'configured_user email unconfigured';
  END IF;

  -- KPI definition: scope match + non-archived + non-schedule_signal
  SELECT id, organization_id, workspace_id, target_type, target_id,
         is_archived, calculation_key, value_type
    INTO _kdef FROM public.kpi_definitions WHERE id = _m.kpi_definition_id;
  IF _kdef.id IS NULL THEN
    RAISE EXCEPTION 'KPI definition missing';
  END IF;
  IF _kdef.is_archived THEN
    RAISE EXCEPTION 'KPI definition archived';
  END IF;
  IF _kdef.calculation_key = 'schedule_signal' THEN
    RAISE EXCEPTION 'schedule_signal not submittable';
  END IF;
  IF _kdef.organization_id <> _m.organization_id
     OR _kdef.workspace_id <> _m.workspace_id
     OR _kdef.target_type <> 'project'
     OR _kdef.target_id <> _m.project_id THEN
    RAISE EXCEPTION 'Mapping/KPI scope mismatch';
  END IF;

  -- External catalog: active + value_type match
  SELECT id, is_active, value_type
    INTO _ext FROM public.kpi_app_external_kpis
   WHERE organization_id = _m.organization_id
     AND external_kpi_id = _m.external_kpi_id;
  IF _ext.id IS NULL OR NOT _ext.is_active THEN
    RAISE EXCEPTION 'External catalog inactive';
  END IF;
  IF _ext.value_type <> _kdef.value_type THEN
    RAISE EXCEPTION 'External catalog value_type mismatch';
  END IF;

  -- Snapshot: scope + value_type match against KPI + catalog
  SELECT id, organization_id, project_id, kpi_definition_id, value_type,
         value_amount, period_start, period_end, string_value, comment, action_plan
    INTO _s FROM public.kpi_snapshots WHERE id = _snapshot_id;
  IF _s.id IS NULL THEN
    RAISE EXCEPTION 'Snapshot not found';
  END IF;
  IF _s.organization_id <> _m.organization_id
     OR _s.project_id <> _m.project_id
     OR _s.kpi_definition_id <> _m.kpi_definition_id THEN
    RAISE EXCEPTION 'Snapshot scope mismatch';
  END IF;
  IF _s.value_type <> _kdef.value_type THEN
    RAISE EXCEPTION 'Snapshot/KPI value_type mismatch';
  END IF;
  IF _s.value_type <> _ext.value_type THEN
    RAISE EXCEPTION 'Snapshot/external catalog value_type mismatch';
  END IF;

  RETURN json_build_object(
    'id', _s.id,
    'value_type', _s.value_type,
    'value_amount', _s.value_amount,
    'period_start', _s.period_start,
    'period_end', _s.period_end,
    'string_value', btpm_decrypt(_s.string_value, _s.organization_id),
    'comment', btpm_decrypt(_s.comment, _s.organization_id),
    'action_plan', btpm_decrypt(_s.action_plan, _s.organization_id)
  );
END;
$$;


--
-- Name: get_latest_manual_kpi_value(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_latest_manual_kpi_value(_kpi_definition_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _ws_id uuid;
  _org_id uuid;
  _result json;
BEGIN
  SELECT workspace_id, organization_id INTO _ws_id, _org_id
    FROM kpi_definitions WHERE id = _kpi_definition_id;
  IF _ws_id IS NULL THEN RETURN NULL; END IF;

  IF NOT (is_workspace_member(auth.uid(), _ws_id) OR is_org_admin(auth.uid(), _org_id)) THEN
    RETURN NULL;
  END IF;

  SELECT row_to_json(t) INTO _result
  FROM (
    SELECT
      ku.id, ku.value, ku.update_date, ku.created_at,
      CASE WHEN ku.note IS NOT NULL
           THEN btpm_decrypt(ku.note, ku.organization_id)
           ELSE NULL END AS note
    FROM kpi_updates ku
    WHERE ku.kpi_definition_id = _kpi_definition_id
    ORDER BY ku.update_date DESC, ku.created_at DESC
    LIMIT 1
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: get_latest_roadmap_story_pack_version_content(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_latest_roadmap_story_pack_version_content(_story_pack_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _v public.roadmap_story_pack_versions;
  _result jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _v
  FROM public.roadmap_story_pack_versions
  WHERE story_pack_id = _story_pack_id
  ORDER BY version_number DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'id', _v.id,
    'version_number', _v.version_number,
    'status', _v.status,
    'created_at', _v.created_at,
    'created_by', _v.created_by,
    'source_manifest', _v.source_manifest,
    'model_metadata', _v.model_metadata,
    'story_json', CASE WHEN _v.story_json_encrypted IS NULL THEN NULL
                       ELSE public.btpm_decrypt(_v.story_json_encrypted, _pack.organization_id) END
  ) INTO _result;

  RETURN _result;
END;
$$;


--
-- Name: get_latest_roadmap_story_presentation_blueprint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_latest_roadmap_story_presentation_blueprint(_story_pack_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _run public.roadmap_story_pack_presentation_runs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run
    FROM public.roadmap_story_pack_presentation_runs
   WHERE story_pack_id = _story_pack_id
     AND status = 'succeeded'
     AND is_valid IS TRUE
   ORDER BY completed_at DESC NULLS LAST, created_at DESC
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'run_id', _run.id,
    'story_pack_version_id', _run.story_pack_version_id,
    'model', _run.model,
    'provider', _run.provider,
    'model_metadata', _run.model_metadata,
    'created_at', _run.created_at,
    'completed_at', _run.completed_at,
    'blueprint_json', CASE WHEN _run.parsed_blueprint_encrypted IS NULL THEN NULL
                           ELSE public.btpm_decrypt(_run.parsed_blueprint_encrypted, _pack.organization_id) END,
    'validation_json', CASE WHEN _run.validation_json_encrypted IS NULL THEN NULL
                            ELSE public.btpm_decrypt(_run.validation_json_encrypted, _pack.organization_id) END
  );
END;
$$;


--
-- Name: get_my_active_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_active_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pref RECORD;
  _tenant_count int := 0;
  _org_count int := 0;
  _ws_count int := 0;
  _tenant_id uuid;
  _tenant_row RECORD;
  _org_id uuid;
  _org_row RECORD;
  _ws_id uuid;
  _ws_name text;
  _requires_tenant boolean := false;
  _requires_org boolean := false;
  _is_all_ws boolean := false;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object('authenticated', false);
  END IF;

  SELECT * INTO _pref FROM public.user_active_context_preferences WHERE user_id = _uid;
  SELECT count(*) INTO _tenant_count FROM public.list_my_tenants();

  IF _tenant_count = 0 THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', false,
      'available_tenant_count', 0, 'available_organization_count', 0, 'available_workspace_count', 0);
  END IF;

  IF _pref.last_active_tenant_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.list_my_tenants() t WHERE t.tenant_id = _pref.last_active_tenant_id) THEN
    _tenant_id := _pref.last_active_tenant_id;
  ELSIF _tenant_count = 1 THEN
    SELECT t.tenant_id INTO _tenant_id FROM public.list_my_tenants() t LIMIT 1;
  ELSE
    -- Generic SaaS behavior: when a user has multiple accessible tenants
    -- and no valid preference, require explicit tenant selection.
    _requires_tenant := true;
  END IF;

  IF _requires_tenant OR _tenant_id IS NULL THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', true,
      'requires_tenant_selection', true, 'available_tenant_count', _tenant_count);
  END IF;

  SELECT id, name, slug INTO _tenant_row FROM public.tenants WHERE id = _tenant_id AND status = 'active';
  IF _tenant_row.id IS NULL THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', true,
      'requires_tenant_selection', true, 'available_tenant_count', _tenant_count);
  END IF;

  SELECT count(*) INTO _org_count FROM public.list_my_organizations_for_tenant(_tenant_id);
  IF _org_count = 0 THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', false,
      'tenant_id', _tenant_row.id, 'tenant_name', _tenant_row.name, 'tenant_slug', _tenant_row.slug,
      'available_tenant_count', _tenant_count, 'available_organization_count', 0);
  END IF;

  IF _pref.last_active_organization_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.list_my_organizations_for_tenant(_tenant_id) o
                 WHERE o.organization_id = _pref.last_active_organization_id) THEN
    _org_id := _pref.last_active_organization_id;
  ELSE
    SELECT tt.default_organization_id INTO _org_id FROM public.tenants tt WHERE tt.id = _tenant_id;
    IF _org_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.list_my_organizations_for_tenant(_tenant_id) o WHERE o.organization_id = _org_id
    ) THEN
      _org_id := NULL;
    END IF;
    IF _org_id IS NULL AND _org_count = 1 THEN
      SELECT o.organization_id INTO _org_id FROM public.list_my_organizations_for_tenant(_tenant_id) o LIMIT 1;
    END IF;
    IF _org_id IS NULL THEN _requires_org := true; END IF;
  END IF;

  IF _requires_org OR _org_id IS NULL THEN
    RETURN jsonb_build_object('authenticated', true, 'has_access', true,
      'requires_organization_selection', true,
      'tenant_id', _tenant_row.id, 'tenant_name', _tenant_row.name, 'tenant_slug', _tenant_row.slug,
      'available_tenant_count', _tenant_count, 'available_organization_count', _org_count);
  END IF;

  SELECT o.id, o.name, o.slug, o.organization_kind, o.environment_role
    INTO _org_row FROM public.organizations o WHERE o.id = _org_id;

  SELECT count(*) INTO _ws_count FROM public.list_my_workspaces_for_organization(_org_id);

  _is_all_ws := COALESCE(_pref.is_all_workspaces, false);
  IF _pref.last_active_workspace_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.list_my_workspaces_for_organization(_org_id) w
                 WHERE w.workspace_id = _pref.last_active_workspace_id) THEN
    _ws_id := _pref.last_active_workspace_id;
    _is_all_ws := false;
  ELSIF _is_all_ws THEN
    _ws_id := NULL;
  ELSIF _ws_count = 1 THEN
    SELECT w.workspace_id INTO _ws_id FROM public.list_my_workspaces_for_organization(_org_id) w LIMIT 1;
  ELSIF _ws_count > 1 THEN
    _is_all_ws := true; _ws_id := NULL;
  END IF;

  IF _ws_id IS NOT NULL THEN
    SELECT w.name INTO _ws_name FROM public.workspaces w WHERE w.id = _ws_id;
  END IF;

  -- Persist resolved active context so list_user_workspaces (and any other
  -- caller that reads user_active_context_preferences) agrees with the chip.
  INSERT INTO public.user_active_context_preferences AS p
    (user_id, last_active_tenant_id, last_active_organization_id,
     last_active_workspace_id, is_all_workspaces, updated_at)
  VALUES (_uid, _tenant_row.id, _org_row.id, _ws_id, _is_all_ws, now())
  ON CONFLICT (user_id) DO UPDATE
    SET last_active_tenant_id = EXCLUDED.last_active_tenant_id,
        last_active_organization_id = EXCLUDED.last_active_organization_id,
        last_active_workspace_id = COALESCE(EXCLUDED.last_active_workspace_id, p.last_active_workspace_id),
        is_all_workspaces = EXCLUDED.is_all_workspaces,
        updated_at = now();

  RETURN jsonb_build_object(
    'authenticated', true, 'has_access', true,
    'requires_tenant_selection', false, 'requires_organization_selection', false,
    'tenant_id', _tenant_row.id, 'tenant_name', _tenant_row.name, 'tenant_slug', _tenant_row.slug,
    'organization_id', _org_row.id, 'organization_name', _org_row.name, 'organization_slug', _org_row.slug,
    'organization_kind', _org_row.organization_kind, 'environment_role', _org_row.environment_role,
    'workspace_id', _ws_id, 'workspace_name', _ws_name, 'is_all_workspaces', _is_all_ws,
    'available_tenant_count', _tenant_count, 'available_organization_count', _org_count,
    'available_workspace_count', _ws_count);
END;
$$;


--
-- Name: get_my_admin_access_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_admin_access_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _is_super boolean := false;
  _tenants jsonb := '[]'::jsonb;
BEGIN
  IF _uid IS NULL THEN
    RETURN jsonb_build_object(
      'is_platform_super_admin', false,
      'tenant_admin_memberships', '[]'::jsonb
    );
  END IF;

  _is_super := public.is_platform_super_admin(_uid);

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'tenant_id', tm.tenant_id,
      'tenant_name', t.name,
      'tenant_slug', t.slug,
      'tenant_status', t.status,
      'role', tm.role
    ) ORDER BY t.name
  ), '[]'::jsonb) INTO _tenants
  FROM public.tenant_memberships tm
  JOIN public.tenants t ON t.id = tm.tenant_id
  WHERE tm.user_id = _uid
    AND tm.status = 'active'
    AND tm.role IN ('tenant_owner','tenant_admin');

  RETURN jsonb_build_object(
    'is_platform_super_admin', _is_super,
    'tenant_admin_memberships', _tenants
  );
END;
$$;


--
-- Name: get_org_user_display_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_user_display_name(_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_name text;
  v_email text;
  v_org uuid;
  v_caller_org uuid;
BEGIN
  IF _user_id IS NULL THEN RETURN NULL; END IF;
  IF NOT public.is_active_user(auth.uid()) THEN RETURN NULL; END IF;

  SELECT p.organization_id INTO v_caller_org FROM public.profiles p WHERE p.id = auth.uid();

  SELECT p.organization_id,
         CASE WHEN p.organization_id IS NOT NULL AND p.display_name IS NOT NULL
              THEN btpm_decrypt(p.display_name, p.organization_id) ELSE p.display_name END,
         CASE WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
              THEN btpm_decrypt(p.email, p.organization_id) ELSE p.email END
    INTO v_org, v_name, v_email
  FROM public.profiles p WHERE p.id = _user_id;

  IF v_caller_org IS NULL OR v_org IS NULL OR v_caller_org <> v_org THEN
    RETURN NULL;
  END IF;

  RETURN COALESCE(NULLIF(v_name, ''), NULLIF(v_email, ''));
END;
$$;


--
-- Name: get_org_users_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_users_list(_organization_id uuid) RETURNS TABLE(row_kind text, user_id uuid, display_name text, email text, status text, org_role text, workspace_count bigint, workspace_names text[], invitation_state text, invitation_workspace_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN RETURN; END IF;
  RETURN QUERY
  SELECT 'active_user'::text, p.id, btpm_decrypt(p.display_name, _organization_id), p.email, CASE WHEN p.is_active THEN 'active'::text ELSE 'deactivated'::text END, (SELECT ur.role::text FROM public.user_roles ur WHERE ur.user_id = p.id AND ur.organization_id = _organization_id AND ur.workspace_id IS NULL LIMIT 1), (SELECT count(*) FROM public.workspace_memberships wm JOIN public.workspaces w ON w.id = wm.workspace_id AND w.organization_id = _organization_id WHERE wm.user_id = p.id), (SELECT array_agg(w.name ORDER BY w.name) FROM public.workspace_memberships wm JOIN public.workspaces w ON w.id = wm.workspace_id AND w.organization_id = _organization_id WHERE wm.user_id = p.id), NULL::text, NULL::text
  FROM public.profiles p WHERE p.organization_id = _organization_id
  UNION ALL
  SELECT 'pending_invitation'::text, NULL::uuid, NULL::text, inv.email, 'invited'::text, inv.role::text, 0::bigint, CASE WHEN inv.workspace_id IS NOT NULL THEN ARRAY[(SELECT w.name FROM public.workspaces w WHERE w.id = inv.workspace_id)] ELSE NULL END, CASE WHEN inv.status = 'pending' AND inv.expires_at <= now() THEN 'expired' ELSE inv.status END, (SELECT w.name FROM public.workspaces w WHERE w.id = inv.workspace_id)
  FROM public.invitations inv WHERE inv.organization_id = _organization_id AND inv.status IN ('pending', 'revoked') AND NOT EXISTS (SELECT 1 FROM public.profiles p2 WHERE p2.organization_id = _organization_id AND lower(p2.email) = lower(inv.email))
  ORDER BY status, display_name NULLS LAST, email;
END;
$$;


--
-- Name: get_organization_tenant_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_organization_tenant_id(_organization_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT tenant_id FROM public.organizations WHERE id = _organization_id;
$$;


--
-- Name: get_portfolio_benefits_realization(uuid[], uuid[], uuid[], text[], uuid[], text[], text[], date, date, boolean, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portfolio_benefits_realization(_workspace_ids uuid[] DEFAULT NULL::uuid[], _program_ids uuid[] DEFAULT NULL::uuid[], _project_ids uuid[] DEFAULT NULL::uuid[], _project_statuses text[] DEFAULT NULL::text[], _project_manager_ids uuid[] DEFAULT NULL::uuid[], _benefit_types text[] DEFAULT NULL::text[], _realization_statuses text[] DEFAULT NULL::text[], _expected_from date DEFAULT NULL::date, _expected_to date DEFAULT NULL::date, _include_archived boolean DEFAULT false, _portfolio_item_ids uuid[] DEFAULT NULL::uuid[], _include_no_portfolio boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
  _has_pf_filter boolean := (_portfolio_item_ids IS NOT NULL AND array_length(_portfolio_item_ids, 1) > 0);
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  WITH accessible_projects AS (
    SELECT
      p.id           AS project_id,
      p.workspace_id,
      p.program_id,
      p.status::text AS project_status,
      p.name         AS project_name,
      p.portfolio_item_id,
      CASE WHEN pi.name IS NULL THEN NULL
           ELSE public.btpm_decrypt(pi.name, pi.organization_id) END AS portfolio_name,
      CASE WHEN pi.code IS NULL THEN NULL
           ELSE public.btpm_decrypt(pi.code, pi.organization_id) END AS portfolio_code,
      pi.lifecycle_state AS portfolio_lifecycle_state,
      pi.is_archived     AS portfolio_is_archived
    FROM public.projects p
    LEFT JOIN public.portfolio_items pi ON pi.id = p.portfolio_item_id
    WHERE public.has_project_access(_uid, p.id)
      AND (_workspace_ids     IS NULL OR p.workspace_id = ANY(_workspace_ids))
      AND (_program_ids       IS NULL OR p.program_id   = ANY(_program_ids))
      AND (_project_ids       IS NULL OR p.id           = ANY(_project_ids))
      AND (_project_statuses  IS NULL OR p.status::text = ANY(_project_statuses))
      AND (
        CASE
          WHEN _has_pf_filter AND _include_no_portfolio THEN
            (p.portfolio_item_id = ANY(_portfolio_item_ids) OR p.portfolio_item_id IS NULL)
          WHEN _has_pf_filter AND NOT _include_no_portfolio THEN
            (p.portfolio_item_id = ANY(_portfolio_item_ids))
          WHEN (NOT _has_pf_filter) AND _include_no_portfolio THEN
            (p.portfolio_item_id IS NULL)
          ELSE TRUE
        END
      )
  ),
  project_pms AS (
    SELECT
      tm.project_id,
      array_agg(DISTINCT tm.user_id)                       AS pm_user_ids,
      (array_agg(tm.user_id ORDER BY tm.created_at))[1]    AS primary_pm_id
    FROM public.project_team_members tm
    WHERE tm.canonical_role_key = 'project_manager'
    GROUP BY tm.project_id
  ),
  scoped_projects AS (
    SELECT
      ap.*,
      pp.primary_pm_id,
      pp.pm_user_ids
    FROM accessible_projects ap
    LEFT JOIN project_pms pp ON pp.project_id = ap.project_id
    WHERE _project_manager_ids IS NULL
       OR (pp.pm_user_ids IS NOT NULL AND pp.pm_user_ids && _project_manager_ids)
  ),
  base_rows AS (
    SELECT
      b.id                                    AS benefit_id,
      b.project_id,
      sp.project_name,
      b.workspace_id,
      w.name                                  AS workspace_name,
      sp.program_id,
      pr.name                                 AS program_name,
      sp.project_status,
      sp.primary_pm_id                        AS project_manager_id,
      CASE WHEN prof_pm.display_name IS NULL THEN NULL
           ELSE public.btpm_decrypt(prof_pm.display_name, b.organization_id) END AS project_manager_name,
      sp.portfolio_item_id,
      sp.portfolio_name,
      sp.portfolio_code,
      sp.portfolio_lifecycle_state,
      sp.portfolio_is_archived,
      b.organization_id,
      b.benefit_type,
      CASE WHEN b.custom_benefit_type_label IS NULL THEN NULL
           ELSE public.btpm_decrypt(b.custom_benefit_type_label, b.organization_id) END AS custom_benefit_type_label,
      CASE WHEN b.metric_name IS NULL THEN NULL
           ELSE public.btpm_decrypt(b.metric_name, b.organization_id) END AS metric_name,
      b.unit_of_measure,
      lower(trim(COALESCE(b.unit_of_measure, ''))) AS unit_raw,
      b.baseline_value,
      b.target_value,
      b.actual_value,
      b.realization_status,
      b.expected_realization_date,
      b.actual_realization_date,
      b.benefit_owner_id,
      CASE WHEN prof_ow.display_name IS NULL THEN NULL
           ELSE public.btpm_decrypt(prof_ow.display_name, b.organization_id) END AS benefit_owner_name,
      b.archived_at,
      b.created_at,
      b.updated_at
    FROM public.project_benefits b
    JOIN scoped_projects sp     ON sp.project_id = b.project_id
    LEFT JOIN public.workspaces w  ON w.id = b.workspace_id
    LEFT JOIN public.programs   pr ON pr.id = sp.program_id
    LEFT JOIN public.profiles prof_pm ON prof_pm.id = sp.primary_pm_id
    LEFT JOIN public.profiles prof_ow ON prof_ow.id = b.benefit_owner_id
    WHERE (_include_archived OR b.archived_at IS NULL)
      AND (_benefit_types        IS NULL OR b.benefit_type        = ANY(_benefit_types))
      AND (_realization_statuses IS NULL OR b.realization_status  = ANY(_realization_statuses))
      AND (
        (_expected_from IS NULL AND _expected_to IS NULL)
        OR (
          b.expected_realization_date IS NOT NULL
          AND (_expected_from IS NULL OR b.expected_realization_date >= _expected_from)
          AND (_expected_to   IS NULL OR b.expected_realization_date <= _expected_to)
        )
      )
  ),
  normalized AS (
    SELECT
      br.*,
      CASE
        WHEN br.benefit_type = 'financial_value' AND br.unit_raw IN ('eur','€') THEN 'EUR'
        WHEN br.benefit_type = 'financial_value' AND br.unit_raw IN ('usd','$') THEN 'USD'
        ELSE NULL
      END AS currency_code,
      CASE WHEN br.unit_raw IN ('fte')                        THEN 'FTE'   ELSE NULL END AS fte_flag,
      CASE WHEN br.unit_raw IN ('hours','hour','hrs','hr')    THEN 'HOURS' ELSE NULL END AS hours_flag,
      (br.actual_value IS NULL AND br.realization_status <> 'not_applicable') AS is_pending,
      (br.expected_realization_date IS NOT NULL
        AND br.expected_realization_date < current_date
        AND br.actual_value IS NULL
        AND br.realization_status NOT IN ('realized','not_applicable')) AS is_overdue
    FROM base_rows br
  ),
  financial_summary AS (
    SELECT
      currency_code                                          AS unit,
      COALESCE(SUM(target_value), 0)                         AS target,
      COALESCE(SUM(actual_value) FILTER (WHERE actual_value IS NOT NULL), 0) AS actual
    FROM normalized
    WHERE currency_code IS NOT NULL
    GROUP BY currency_code
  ),
  type_group AS (
    SELECT
      benefit_type,
      COUNT(*)                                                    AS benefit_count,
      COUNT(DISTINCT project_id)                                  AS projects_count,
      COUNT(*) FILTER (WHERE is_pending)                          AS pending_count,
      COUNT(*) FILTER (WHERE is_overdue)                          AS overdue_count,
      COALESCE(SUM(actual_value) FILTER (WHERE fte_flag   IS NOT NULL AND actual_value IS NOT NULL), 0) AS fte_actual,
      COALESCE(SUM(actual_value) FILTER (WHERE hours_flag IS NOT NULL AND actual_value IS NOT NULL), 0) AS hours_actual
    FROM normalized
    GROUP BY benefit_type
  ),
  type_financial AS (
    SELECT
      benefit_type,
      currency_code AS unit,
      COALESCE(SUM(target_value), 0)                                       AS target,
      COALESCE(SUM(actual_value) FILTER (WHERE actual_value IS NOT NULL), 0) AS actual
    FROM normalized
    WHERE currency_code IS NOT NULL
    GROUP BY benefit_type, currency_code
  ),
  project_group AS (
    SELECT
      project_id, project_name, workspace_id, workspace_name,
      program_id, program_name, project_status,
      project_manager_id, project_manager_name,
      portfolio_item_id, portfolio_name, portfolio_code,
      portfolio_lifecycle_state, portfolio_is_archived,
      COUNT(*)                            AS benefit_count,
      COUNT(*) FILTER (WHERE is_pending)  AS actuals_pending,
      COUNT(*) FILTER (WHERE is_overdue)  AS overdue_count,
      COALESCE(SUM(actual_value) FILTER (WHERE fte_flag   IS NOT NULL AND actual_value IS NOT NULL), 0) AS fte_actual,
      COALESCE(SUM(actual_value) FILTER (WHERE hours_flag IS NOT NULL AND actual_value IS NOT NULL), 0) AS hours_actual
    FROM normalized
    GROUP BY project_id, project_name, workspace_id, workspace_name,
             program_id, program_name, project_status,
             project_manager_id, project_manager_name,
             portfolio_item_id, portfolio_name, portfolio_code,
             portfolio_lifecycle_state, portfolio_is_archived
  ),
  project_financial AS (
    SELECT
      project_id,
      currency_code AS unit,
      COALESCE(SUM(target_value), 0)                                       AS target,
      COALESCE(SUM(actual_value) FILTER (WHERE actual_value IS NOT NULL), 0) AS actual
    FROM normalized
    WHERE currency_code IS NOT NULL
    GROUP BY project_id, currency_code
  )
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'projects_with_benefits',    (SELECT COUNT(DISTINCT project_id) FROM normalized),
      'benefits_tracked',          (SELECT COUNT(*) FROM normalized),
      'financial', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'unit',            unit,
            'target',          target,
            'actual',          actual,
            'achievement_pct', CASE WHEN target > 0 THEN round((actual / target) * 100, 2) ELSE NULL END
          )
          ORDER BY unit
        )
        FROM financial_summary
      ), '[]'::jsonb),
      'fte_saved',                 (SELECT COALESCE(SUM(actual_value), 0) FROM normalized WHERE fte_flag   IS NOT NULL AND actual_value IS NOT NULL),
      'hours_saved',               (SELECT COALESCE(SUM(actual_value), 0) FROM normalized WHERE hours_flag IS NOT NULL AND actual_value IS NOT NULL),
      'actuals_pending',           (SELECT COUNT(*) FROM normalized WHERE is_pending),
      'benefits_overdue_for_update', (SELECT COUNT(*) FROM normalized WHERE is_overdue)
    ),
    'benefits_by_type', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'benefit_type',       tg.benefit_type,
          'benefit_type_label', tg.benefit_type,
          'benefit_count',      tg.benefit_count,
          'projects_count',     tg.projects_count,
          'financial', COALESCE((
            SELECT jsonb_agg(
              jsonb_build_object(
                'unit',            tf.unit,
                'target',          tf.target,
                'actual',          tf.actual,
                'achievement_pct', CASE WHEN tf.target > 0 THEN round((tf.actual / tf.target) * 100, 2) ELSE NULL END
              )
              ORDER BY tf.unit
            )
            FROM type_financial tf
            WHERE tf.benefit_type = tg.benefit_type
          ), '[]'::jsonb),
          'fte_actual',    tg.fte_actual,
          'hours_actual',  tg.hours_actual,
          'pending_count', tg.pending_count,
          'overdue_count', tg.overdue_count
        )
        ORDER BY tg.benefit_type
      )
      FROM type_group tg
    ), '[]'::jsonb),
    'benefits_by_project', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'project_id',           pg.project_id,
          'project_name',         pg.project_name,
          'workspace_id',         pg.workspace_id,
          'workspace_name',       pg.workspace_name,
          'program_id',           pg.program_id,
          'program_name',         pg.program_name,
          'project_status',       pg.project_status,
          'project_manager_id',   pg.project_manager_id,
          'project_manager_name', pg.project_manager_name,
          'portfolio_item_id',        pg.portfolio_item_id,
          'portfolio_name',           pg.portfolio_name,
          'portfolio_code',           pg.portfolio_code,
          'portfolio_lifecycle_state',pg.portfolio_lifecycle_state,
          'portfolio_is_archived',    pg.portfolio_is_archived,
          'benefit_count',        pg.benefit_count,
          'financial', COALESCE((
            SELECT jsonb_agg(
              jsonb_build_object(
                'unit',            pf.unit,
                'target',          pf.target,
                'actual',          pf.actual,
                'achievement_pct', CASE WHEN pf.target > 0 THEN round((pf.actual / pf.target) * 100, 2) ELSE NULL END
              )
              ORDER BY pf.unit
            )
            FROM project_financial pf
            WHERE pf.project_id = pg.project_id
          ), '[]'::jsonb),
          'fte_actual',      pg.fte_actual,
          'hours_actual',    pg.hours_actual,
          'actuals_pending', pg.actuals_pending,
          'overdue_count',   pg.overdue_count
        )
        ORDER BY pg.project_name NULLS LAST
      )
      FROM project_group pg
    ), '[]'::jsonb),
    'benefits_requiring_update', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'benefit_id',                benefit_id,
          'project_id',                project_id,
          'project_name',              project_name,
          'workspace_name',            workspace_name,
          'portfolio_item_id',         portfolio_item_id,
          'portfolio_name',            portfolio_name,
          'portfolio_code',            portfolio_code,
          'portfolio_lifecycle_state', portfolio_lifecycle_state,
          'portfolio_is_archived',     portfolio_is_archived,
          'benefit_type',              benefit_type,
          'metric_name',               metric_name,
          'unit_of_measure',           unit_of_measure,
          'target_value',              target_value,
          'actual_value',              actual_value,
          'realization_status',        realization_status,
          'expected_realization_date', expected_realization_date,
          'benefit_owner_id',          benefit_owner_id,
          'benefit_owner_name',        benefit_owner_name
        )
        ORDER BY expected_realization_date NULLS LAST, project_name
      )
      FROM normalized
      WHERE is_overdue
    ), '[]'::jsonb),
    'rows', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'benefit_id',                benefit_id,
          'project_id',                project_id,
          'project_name',              project_name,
          'workspace_id',              workspace_id,
          'workspace_name',            workspace_name,
          'program_id',                program_id,
          'program_name',              program_name,
          'project_status',            project_status,
          'project_manager_id',        project_manager_id,
          'project_manager_name',      project_manager_name,
          'portfolio_item_id',         portfolio_item_id,
          'portfolio_name',            portfolio_name,
          'portfolio_code',            portfolio_code,
          'portfolio_lifecycle_state', portfolio_lifecycle_state,
          'portfolio_is_archived',     portfolio_is_archived,
          'benefit_type',              benefit_type,
          'custom_benefit_type_label', custom_benefit_type_label,
          'metric_name',               metric_name,
          'unit_of_measure',           unit_of_measure,
          'baseline_value',            baseline_value,
          'target_value',              target_value,
          'actual_value',              actual_value,
          'realization_status',        realization_status,
          'expected_realization_date', expected_realization_date,
          'actual_realization_date',   actual_realization_date,
          'benefit_owner_id',          benefit_owner_id,
          'benefit_owner_name',        benefit_owner_name,
          'archived_at',               archived_at,
          'created_at',                created_at,
          'updated_at',                updated_at
        )
        ORDER BY project_name NULLS LAST, expected_realization_date NULLS LAST, metric_name
      )
      FROM normalized
    ), '[]'::jsonb),
    'meta', jsonb_build_object(
      'filters_applied', jsonb_build_object(
        'workspace_ids',        to_jsonb(_workspace_ids),
        'program_ids',          to_jsonb(_program_ids),
        'project_ids',          to_jsonb(_project_ids),
        'project_statuses',     to_jsonb(_project_statuses),
        'project_manager_ids',  to_jsonb(_project_manager_ids),
        'benefit_types',        to_jsonb(_benefit_types),
        'realization_statuses', to_jsonb(_realization_statuses),
        'expected_from',        to_jsonb(_expected_from),
        'expected_to',          to_jsonb(_expected_to),
        'portfolio_item_ids',   to_jsonb(_portfolio_item_ids),
        'include_no_portfolio', to_jsonb(_include_no_portfolio)
      ),
      'generated_at',     now(),
      'include_archived', _include_archived
    )
  )
  INTO _result;

  RETURN _result;
END;
$_$;


--
-- Name: get_portfolio_item_project_membership_summary(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portfolio_item_project_membership_summary(_portfolio_item_id uuid, _include_archived_projects boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
  v_client_id text;
BEGIN
  -- Portfolio-12E.4: browser-internal only. Signed external OAuth is always denied.
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.portfolio_items WHERE id = _portfolio_item_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Portfolio item not found'; END IF;

  IF NOT public.is_org_admin(_uid, _org) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.project_name), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      p.id AS project_id,
      public.btpm_decrypt(p.name, p.organization_id) AS project_name,
      p.workspace_id,
      w.name AS workspace_name,
      p.program_id,
      (SELECT public.btpm_decrypt(pr.name, p.organization_id)
         FROM public.programs pr WHERE pr.id = p.program_id) AS program_name,
      p.status,
      p.priority,
      p.project_stage,
      p.delivery_model,
      p.start_date,
      p.target_end_date,
      p.is_archived,
      p.updated_at
    FROM public.projects p
    JOIN public.workspaces w ON w.id = p.workspace_id
    WHERE p.portfolio_item_id = _portfolio_item_id
      AND (_include_archived_projects OR p.is_archived = false)
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: get_powerbi_data_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_powerbi_data_scope(_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_eff record;
  v_workspaces jsonb;
  v_projects jsonb;
  v_summary jsonb;
  v_inc_ws_count int;
  v_exc_ws_count int;
BEGIN
  IF v_uid IS NULL OR NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Org Admin only';
  END IF;

  SELECT * INTO v_eff FROM public.get_powerbi_effective_scope(_organization_id);

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.workspace_name), '[]'::jsonb)
  INTO v_workspaces
  FROM (
    SELECT
      w.id AS workspace_id,
      w.name AS workspace_name,
      COALESCE(wr.scope_mode, 'unconfigured') AS workspace_scope_mode,
      (w.id = ANY(v_eff.included_workspace_ids)) AS effective_included,
      (SELECT count(*) FROM public.projects p2 WHERE p2.workspace_id = w.id AND p2.organization_id = _organization_id) AS project_count_total,
      (SELECT count(*) FROM public.projects p3 WHERE p3.workspace_id = w.id AND p3.organization_id = _organization_id AND p3.id = ANY(v_eff.included_project_ids)) AS project_count_effectively_included,
      COALESCE(w.is_demo, false) AS is_demo
    FROM public.workspaces w
    LEFT JOIN public.powerbi_data_scope_rules wr
      ON wr.scope_type = 'workspace'
     AND wr.organization_id = _organization_id
     AND wr.workspace_id = w.id
    WHERE w.organization_id = _organization_id
  ) t;

  -- Project rules retired: no project-level configuration collection.
  v_projects := '[]'::jsonb;

  SELECT count(*) INTO v_inc_ws_count
  FROM public.powerbi_data_scope_rules
  WHERE organization_id = _organization_id AND scope_type='workspace' AND scope_mode='included';
  SELECT count(*) INTO v_exc_ws_count
  FROM public.powerbi_data_scope_rules
  WHERE organization_id = _organization_id AND scope_type='workspace' AND scope_mode='excluded';

  v_summary := jsonb_build_object(
    'scope_configured', v_eff.scope_configured,
    'included_workspace_count', array_length(v_eff.included_workspace_ids, 1),
    'included_project_count', array_length(v_eff.included_project_ids, 1),
    'workspace_rule_included_count', v_inc_ws_count,
    'workspace_rule_excluded_count', v_exc_ws_count,
    'project_rule_included_count', 0,
    'project_rule_excluded_count', 0,
    'excluded_workspace_count', v_exc_ws_count,
    'excluded_project_count', 0,
    'warning_no_inclusion',
      v_eff.scope_configured
      AND COALESCE(array_length(v_eff.included_project_ids,1),0) = 0
  );

  RETURN jsonb_build_object(
    'organization_id', _organization_id,
    'workspaces', v_workspaces,
    'projects', v_projects,
    'summary', v_summary
  );
END;
$$;


--
-- Name: get_powerbi_effective_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_powerbi_effective_scope(_organization_id uuid) RETURNS TABLE(scope_configured boolean, included_workspace_ids uuid[], included_project_ids uuid[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_proj uuid[];
  v_ws uuid[];
  v_configured boolean;
BEGIN
  IF v_uid IS NULL OR NOT public.is_org_admin(v_uid, _organization_id) THEN
    RAISE EXCEPTION 'Org Admin only';
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.powerbi_data_scope_rules
    WHERE organization_id = _organization_id
  ) INTO v_configured;

  SELECT COALESCE(array_agg(DISTINCT w.id), ARRAY[]::uuid[]) INTO v_ws
  FROM public.workspaces w
  JOIN public.powerbi_data_scope_rules wr
    ON wr.scope_type = 'workspace'
   AND wr.organization_id = w.organization_id
   AND wr.workspace_id = w.id
   AND wr.scope_mode = 'included'
  WHERE w.organization_id = _organization_id;

  SELECT COALESCE(array_agg(p.id), ARRAY[]::uuid[]) INTO v_proj
  FROM public.projects p
  WHERE p.organization_id = _organization_id
    AND p.workspace_id = ANY(v_ws);

  RETURN QUERY SELECT v_configured, v_ws, v_proj;
END;
$$;


--
-- Name: get_project_execution_update_digest_for_snapshot_system(uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_project_execution_update_digest_for_snapshot_system(_project_id uuid, _period_start date, _period_end date, _limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _org_id uuid;
  _is_archived boolean;
  _safe_limit integer;
  _result jsonb;
BEGIN
  -- Validate project exists and capture org_id for decryption scope.
  SELECT p.organization_id, p.is_archived
    INTO _org_id, _is_archived
  FROM public.projects p
  WHERE p.id = _project_id;

  IF _org_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Period sanity (defensive)
  IF _period_start IS NULL OR _period_end IS NULL OR _period_end < _period_start THEN
    RETURN '[]'::jsonb;
  END IF;

  _safe_limit := GREATEST(1, LEAST(COALESCE(_limit, 3), 5));

  WITH project_targets AS (
    SELECT 'project'::text AS target_type, _project_id AS target_id
    UNION ALL
    SELECT 'phase'::text, ph.id FROM public.phases ph WHERE ph.project_id = _project_id
    UNION ALL
    SELECT 'task'::text, t.id FROM public.tasks t WHERE t.project_id = _project_id
  ),
  scoped AS (
    SELECT
      eu.target_type,
      eu.update_date,
      eu.created_at,
      eu.status_label,
      public.btpm_decrypt(eu.summary, eu.organization_id) AS summary_plain
    FROM public.execution_updates eu
    JOIN project_targets pt
      ON pt.target_type = eu.target_type AND pt.target_id = eu.target_id
    WHERE eu.organization_id = _org_id
      AND eu.update_date >= _period_start
      AND eu.update_date <= _period_end
    ORDER BY eu.update_date DESC, eu.created_at DESC
    LIMIT _safe_limit
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'target_type', s.target_type,
        'update_date', s.update_date,
        'status_label', s.status_label,
        'summary', LEFT(COALESCE(s.summary_plain, ''), 250)
      )
      ORDER BY s.update_date DESC, s.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO _result
  FROM scoped s;

  RETURN COALESCE(_result, '[]'::jsonb);
END;
$$;


--
-- Name: get_project_execution_update_digest_for_snapshot_system_v2(uuid, date, date, text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_project_execution_update_digest_for_snapshot_system_v2(_project_id uuid, _period_start date, _period_end date, _allowed_target_types text[] DEFAULT NULL::text[], _limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _org_id uuid;
  _safe_limit integer;
  _result jsonb;
  _filter_active boolean;
BEGIN
  SELECT p.organization_id
    INTO _org_id
  FROM public.projects p
  WHERE p.id = _project_id;

  IF _org_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  IF _period_start IS NULL OR _period_end IS NULL OR _period_end < _period_start THEN
    RETURN '[]'::jsonb;
  END IF;

  _safe_limit := GREATEST(1, LEAST(COALESCE(_limit, 3), 5));
  _filter_active := _allowed_target_types IS NOT NULL
    AND array_length(_allowed_target_types, 1) IS NOT NULL;

  WITH project_targets AS (
    SELECT 'project'::text AS target_type, _project_id AS target_id
    UNION ALL
    SELECT 'phase'::text, ph.id FROM public.phases ph WHERE ph.project_id = _project_id
    UNION ALL
    SELECT 'task'::text, t.id FROM public.tasks t WHERE t.project_id = _project_id
  ),
  scoped AS (
    SELECT
      eu.target_type,
      eu.update_date,
      eu.created_at,
      eu.status_label,
      public.btpm_decrypt(eu.summary, eu.organization_id) AS summary_plain
    FROM public.execution_updates eu
    JOIN project_targets pt
      ON pt.target_type = eu.target_type AND pt.target_id = eu.target_id
    WHERE eu.organization_id = _org_id
      AND eu.update_date >= _period_start
      AND eu.update_date <= _period_end
      AND (
        NOT _filter_active
        OR eu.target_type = ANY(_allowed_target_types)
      )
    ORDER BY eu.update_date DESC, eu.created_at DESC
    LIMIT _safe_limit
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'target_type', s.target_type,
        'update_date', s.update_date,
        'status_label', s.status_label,
        'summary', LEFT(COALESCE(s.summary_plain, ''), 250)
      )
      ORDER BY s.update_date DESC, s.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO _result
  FROM scoped s;

  RETURN COALESCE(_result, '[]'::jsonb);
END;
$$;


--
-- Name: get_project_governance_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_project_governance_summary(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _p record;
  _result jsonb;
  _active_cnt int := 0;
  _archived_cnt int := 0;
  _overdue_cnt int := 0;
  _due_soon_cnt int := 0;
  _ad_hoc_cnt int := 0;
  _last_date date;
  _last_rec uuid;
  _next_date date;
  _next_cad uuid;
  _total_rec int := 0;
  _rec_30 int := 0;
  _rec_90 int := 0;
  _missing_sp int := 0;
BEGIN
  _p := _gov_assert_project_read(_project_id);

  SELECT
    COUNT(*) FILTER (WHERE archived_at IS NULL),
    COUNT(*) FILTER (WHERE archived_at IS NOT NULL),
    COUNT(*) FILTER (WHERE archived_at IS NULL AND frequency_type <> 'ad_hoc'
                       AND next_expected_date IS NOT NULL
                       AND next_expected_date < CURRENT_DATE),
    COUNT(*) FILTER (WHERE archived_at IS NULL AND frequency_type <> 'ad_hoc'
                       AND next_expected_date IS NOT NULL
                       AND next_expected_date >= CURRENT_DATE
                       AND next_expected_date <= CURRENT_DATE + INTERVAL '7 days'),
    COUNT(*) FILTER (WHERE archived_at IS NULL AND frequency_type = 'ad_hoc')
  INTO _active_cnt, _archived_cnt, _overdue_cnt, _due_soon_cnt, _ad_hoc_cnt
  FROM governance_cadences WHERE project_id = _project_id;

  SELECT actual_date_held, id INTO _last_date, _last_rec
  FROM governance_records
  WHERE project_id = _project_id AND archived_at IS NULL
  ORDER BY actual_date_held DESC, created_at DESC
  LIMIT 1;

  SELECT next_expected_date, id INTO _next_date, _next_cad
  FROM governance_cadences
  WHERE project_id = _project_id AND archived_at IS NULL
    AND frequency_type <> 'ad_hoc'
    AND next_expected_date IS NOT NULL
  ORDER BY next_expected_date ASC
  LIMIT 1;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE actual_date_held >= CURRENT_DATE - INTERVAL '30 days'),
    COUNT(*) FILTER (WHERE actual_date_held >= CURRENT_DATE - INTERVAL '90 days'),
    COUNT(*) FILTER (WHERE sharepoint_evidence_reference IS NULL)
  INTO _total_rec, _rec_30, _rec_90, _missing_sp
  FROM governance_records
  WHERE project_id = _project_id AND archived_at IS NULL;

  _result := jsonb_build_object(
    'project_id', _project_id,
    'active_cadence_count', _active_cnt,
    'archived_cadence_count', _archived_cnt,
    'overdue_cadence_count', _overdue_cnt,
    'due_soon_cadence_count', _due_soon_cnt,
    'ad_hoc_cadence_count', _ad_hoc_cnt,
    'last_completed_governance_date', _last_date,
    'last_completed_record_id', _last_rec,
    'next_expected_governance_date', _next_date,
    'next_expected_cadence_id', _next_cad,
    'total_record_count', _total_rec,
    'records_last_30_days', _rec_30,
    'records_last_90_days', _rec_90,
    'records_missing_sharepoint_evidence_count', _missing_sp
  );
  RETURN _result;
END; $$;


--
-- Name: get_project_people_preset(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_project_people_preset(_preset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_preset record;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id;
  IF v_preset.id IS NULL THEN
    RAISE EXCEPTION 'Preset not found';
  END IF;
  IF NOT (public.is_workspace_member(v_actor, v_preset.workspace_id)
          OR public.is_org_admin(v_actor, v_preset.organization_id)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT jsonb_build_object(
    'preset', jsonb_build_object(
      'id',              v_preset.id,
      'workspace_id',    v_preset.workspace_id,
      'organization_id', v_preset.organization_id,
      'name',            public.btpm_decrypt(v_preset.name, v_preset.organization_id),
      'description',     public.btpm_decrypt(v_preset.description, v_preset.organization_id),
      'created_by',      v_preset.created_by,
      'created_at',      v_preset.created_at,
      'updated_at',      v_preset.updated_at,
      'archived_at',     v_preset.archived_at,
      'archived_by',     v_preset.archived_by
    ),
    'members', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
          'id',                 m.id,
          'member_kind',        m.member_kind,
          'stakeholder_type',   m.stakeholder_type,
          'user_id',            m.user_id,
          'display_name',       CASE
             WHEN m.user_id IS NOT NULL
               THEN (SELECT COALESCE(pr.display_name, pr.email, m.user_id::text)
                       FROM public.profiles pr WHERE pr.id = m.user_id)
             ELSE public.btpm_decrypt(m.external_name, v_preset.organization_id)
          END,
          'external_name',      public.btpm_decrypt(m.external_name, v_preset.organization_id),
          'canonical_role_key', m.canonical_role_key,
          'role_label',         public.btpm_decrypt(m.role_label, v_preset.organization_id),
          'created_at',         m.created_at,
          'updated_at',         m.updated_at
        ) ORDER BY m.member_kind, m.created_at)
        FROM public.project_people_preset_members m
       WHERE m.preset_id = v_preset.id
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END; $$;


--
-- Name: get_project_template_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_project_template_detail(_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  r RECORD;
  _bp jsonb;
  _summary jsonb;
  _proj jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT id, organization_id, workspace_id, source_project_id,
         name, description, blueprint_payload, blueprint_version,
         is_archived, created_at, updated_at, created_by, updated_by
    INTO r
    FROM public.project_templates
   WHERE id = _template_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'template not found';
  END IF;

  IF NOT (public.is_workspace_member(_caller, r.workspace_id) OR public.is_org_admin(_caller, r.organization_id)) THEN
    RAISE EXCEPTION 'access denied' USING ERRCODE = '42501';
  END IF;

  BEGIN
    _bp := public.btpm_decrypt(r.blueprint_payload, r.organization_id)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    _bp := '{}'::jsonb;
  END;

  _summary := public._template_blueprint_summary(_bp);
  _proj := COALESCE(_bp->'project', '{}'::jsonb);

  RETURN jsonb_build_object(
    'template_id', r.id,
    'organization_id', r.organization_id,
    'workspace_id', r.workspace_id,
    'source_project_id', r.source_project_id,
    'name', public.btpm_decrypt(r.name, r.organization_id),
    'description', CASE WHEN r.description IS NULL THEN NULL ELSE public.btpm_decrypt(r.description, r.organization_id) END,
    'blueprint_version', r.blueprint_version,
    'is_archived', r.is_archived,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'created_by', r.created_by,
    'updated_by', r.updated_by,
    'schedule_mode', _summary->>'schedule_mode',
    'anchor_source', _summary->>'anchor_source',
    'agile_enabled', (_summary->>'agile_enabled')::boolean,
    'summary_counts', _summary->'summary_counts',
    'project_summary', jsonb_build_object(
      'name',          _proj->>'name',
      'description',   _proj->>'description',
      'charter',       _proj->>'charter',
      'goals',         _proj->>'goals',
      'scope_in',      _proj->>'scope_in',
      'scope_out',     _proj->>'scope_out',
      'priority',      _proj->>'priority',
      'agile_enabled', COALESCE((_proj->>'agile_enabled')::boolean, false)
    )
  );
END;
$$;


--
-- Name: get_roadmap_story_pack_ai_run_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_roadmap_story_pack_ai_run_status(_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_ai_runs;
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_ai_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _run.story_pack_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'id', _run.id,
    'story_pack_id', _run.story_pack_id,
    'story_pack_version_id', _run.story_pack_version_id,
    'status', _run.status,
    'openai_response_id', _run.openai_response_id,
    'provider', _run.provider,
    'model', _run.model,
    'reasoning_effort', _run.reasoning_effort,
    'files_selected_count', _run.files_selected_count,
    'files_sent_count', _run.files_sent_count,
    'files_skipped_count', _run.files_skipped_count,
    'total_bytes_sent', _run.total_bytes_sent,
    'started_at', _run.started_at,
    'completed_at', _run.completed_at,
    'error_text', CASE WHEN _run.error_text_encrypted IS NULL THEN NULL
                       ELSE public.btpm_decrypt(_run.error_text_encrypted, _pack.organization_id) END
  );
END;
$$;


--
-- Name: get_roadmap_story_pack_config(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_roadmap_story_pack_config(_story_pack_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _result jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'pack', jsonb_build_object(
      'id', _pack.id,
      'organization_id', _pack.organization_id,
      'primary_workspace_id', _pack.primary_workspace_id,
      'program_id', _pack.program_id,
      'created_by', _pack.created_by,
      'status', _pack.status,
      'scope_config', _pack.scope_config,
      'source_config', _pack.source_config,
      'title', CASE WHEN _pack.title_encrypted IS NULL THEN NULL ELSE public.btpm_decrypt(_pack.title_encrypted, _pack.organization_id) END,
      'guidance', CASE WHEN _pack.user_guidance_encrypted IS NULL THEN NULL ELSE public.btpm_decrypt(_pack.user_guidance_encrypted, _pack.organization_id) END,
      'audience', _pack.audience,
      'focus', _pack.focus,
      'created_at', _pack.created_at,
      'updated_at', _pack.updated_at
    ),
    'sources', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'source_category', s.source_category,
        'is_enabled', s.is_enabled,
        'config', s.config,
        'sort_order', s.sort_order,
        'updated_at', s.updated_at
      ) ORDER BY s.sort_order NULLS LAST, s.source_category)
      FROM public.roadmap_story_pack_sources s WHERE s.story_pack_id = _pack.id
    ), '[]'::jsonb),
    'notes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', n.id,
        'label', CASE WHEN n.label_encrypted IS NULL THEN NULL ELSE public.btpm_decrypt(n.label_encrypted, _pack.organization_id) END,
        'body',  public.btpm_decrypt(n.body_encrypted, _pack.organization_id),
        'include_in_story', n.include_in_story,
        'sort_order', n.sort_order,
        'created_at', n.created_at,
        'updated_at', n.updated_at
      ) ORDER BY n.sort_order NULLS LAST, n.created_at)
      FROM public.roadmap_story_pack_notes n WHERE n.story_pack_id = _pack.id
    ), '[]'::jsonb),
    'external_files', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'provider', f.provider,
        'drive_id', f.drive_id,
        'item_id', f.item_id,
        'display_name', CASE WHEN f.display_name_encrypted IS NULL THEN NULL ELSE public.btpm_decrypt(f.display_name_encrypted, _pack.organization_id) END,
        'web_url',      CASE WHEN f.web_url_encrypted      IS NULL THEN NULL ELSE public.btpm_decrypt(f.web_url_encrypted,      _pack.organization_id) END,
        'user_note',    CASE WHEN f.user_note_encrypted    IS NULL THEN NULL ELSE public.btpm_decrypt(f.user_note_encrypted,    _pack.organization_id) END,
        'mime_type', f.mime_type,
        'size_bytes', f.size_bytes,
        'include_in_story', f.include_in_story,
        'created_at', f.created_at,
        'updated_at', f.updated_at
      ) ORDER BY f.created_at)
      FROM public.roadmap_story_pack_external_files f WHERE f.story_pack_id = _pack.id
    ), '[]'::jsonb),
    'versions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', v.id,
        'version_number', v.version_number,
        'status', v.status,
        'source_manifest', v.source_manifest,
        'model_metadata', v.model_metadata,
        'created_at', v.created_at
      ) ORDER BY v.version_number DESC)
      FROM public.roadmap_story_pack_versions v WHERE v.story_pack_id = _pack.id
    ), '[]'::jsonb),
    'ai_runs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id,
        'story_pack_version_id', r.story_pack_version_id,
        'status', r.status,
        'provider', r.provider,
        'model', r.model,
        'reasoning_effort', r.reasoning_effort,
        'feature_key', r.feature_key,
        'input_manifest', r.input_manifest,
        'prompt_tokens', r.prompt_tokens,
        'completion_tokens', r.completion_tokens,
        'total_tokens', r.total_tokens,
        'cost_usd', r.cost_usd,
        'started_at', r.started_at,
        'completed_at', r.completed_at,
        'created_at', r.created_at
      ) ORDER BY r.created_at DESC)
      FROM public.roadmap_story_ai_runs r WHERE r.story_pack_id = _pack.id
    ), '[]'::jsonb)
  ) INTO _result;

  RETURN _result;
END;
$$;


--
-- Name: get_roadmap_story_pack_version_debug(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_roadmap_story_pack_version_debug(_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _v public.roadmap_story_pack_versions;
  _pack public.roadmap_story_packs;
  _run public.roadmap_story_ai_runs;
  _org uuid;
  _files jsonb;
  _result jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _v FROM public.roadmap_story_pack_versions WHERE id = _version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _v.story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  _org := _pack.organization_id;

  SELECT * INTO _run
  FROM public.roadmap_story_ai_runs
  WHERE story_pack_version_id = _version_id
  ORDER BY started_at DESC
  LIMIT 1;

  IF _run.id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(rf) ORDER BY rf.created_at ASC), '[]'::jsonb)
    INTO _files
    FROM public.roadmap_story_ai_run_files rf
    WHERE rf.ai_run_id = _run.id;
  ELSE
    _files := '[]'::jsonb;
  END IF;

  _result := jsonb_build_object(
    'version', jsonb_build_object(
      'id', _v.id,
      'story_pack_id', _v.story_pack_id,
      'version_number', _v.version_number,
      'status', _v.status,
      'created_at', _v.created_at,
      'created_by', _v.created_by,
      'source_manifest', _v.source_manifest,
      'model_metadata', _v.model_metadata,
      'story_json', CASE WHEN _v.story_json_encrypted IS NULL THEN NULL
                         ELSE public.btpm_decrypt(_v.story_json_encrypted, _org) END,
      'source_snapshot', CASE WHEN _v.source_snapshot_encrypted IS NULL THEN NULL
                              ELSE public.btpm_decrypt(_v.source_snapshot_encrypted, _org) END
    ),
    'ai_run', CASE WHEN _run.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', _run.id,
      'status', _run.status,
      'provider', _run.provider,
      'model', _run.model,
      'reasoning_effort', _run.reasoning_effort,
      'feature_key', _run.feature_key,
      'input_manifest', _run.input_manifest,
      'started_at', _run.started_at,
      'completed_at', _run.completed_at,
      'prompt_tokens', _run.prompt_tokens,
      'completion_tokens', _run.completion_tokens,
      'total_tokens', _run.total_tokens,
      'openai_response_id', _run.openai_response_id,
      'files_selected_count', _run.files_selected_count,
      'files_sent_count', _run.files_sent_count,
      'files_skipped_count', _run.files_skipped_count,
      'total_bytes_sent', _run.total_bytes_sent,
      'prompt_text', CASE WHEN _run.prompt_summary_encrypted IS NULL THEN NULL
                          ELSE public.btpm_decrypt(_run.prompt_summary_encrypted, _org) END,
      'raw_response', CASE WHEN _run.output_text_encrypted IS NULL THEN NULL
                           ELSE public.btpm_decrypt(_run.output_text_encrypted, _org) END
    ) END,
    'files', _files
  );

  RETURN _result;
END;
$$;


