--
-- Name: guard_baseline_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_baseline_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE allowed text;
BEGIN
  BEGIN allowed := current_setting('btpm.baseline_write', true);
  EXCEPTION WHEN others THEN allowed := NULL; END;
  IF allowed = 'on' THEN RETURN NEW; END IF;

  IF TG_OP = 'INSERT' THEN
    IF TG_TABLE_NAME = 'projects' THEN
      IF NEW.baseline_start_date IS NOT NULL OR NEW.baseline_end_date IS NOT NULL
         OR NEW.is_baselined = true OR NEW.baseline_approved_at IS NOT NULL
         OR NEW.baseline_approved_by IS NOT NULL
      THEN
        RAISE EXCEPTION 'Baseline fields cannot be set directly. Use approve_project_baseline / rebaseline_project.';
      END IF;
    ELSIF TG_TABLE_NAME IN ('phases','tasks') THEN
      IF NEW.baseline_start_date IS NOT NULL OR NEW.baseline_end_date IS NOT NULL
         OR NEW.added_after_baseline = true
      THEN
        RAISE EXCEPTION 'Baseline fields cannot be set directly. Use approve_project_baseline / rebaseline_project.';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'projects' THEN
    IF NEW.baseline_start_date IS DISTINCT FROM OLD.baseline_start_date
       OR NEW.baseline_end_date IS DISTINCT FROM OLD.baseline_end_date
       OR NEW.is_baselined      IS DISTINCT FROM OLD.is_baselined
       OR NEW.baseline_approved_at IS DISTINCT FROM OLD.baseline_approved_at
       OR NEW.baseline_approved_by IS DISTINCT FROM OLD.baseline_approved_by
    THEN
      RAISE EXCEPTION 'Baseline fields are read-only. Use approve_project_baseline / rebaseline_project.';
    END IF;
  ELSE
    IF NEW.baseline_start_date IS DISTINCT FROM OLD.baseline_start_date
       OR NEW.baseline_end_date IS DISTINCT FROM OLD.baseline_end_date
       OR NEW.added_after_baseline IS DISTINCT FROM OLD.added_after_baseline
    THEN
      RAISE EXCEPTION 'Baseline fields are read-only. Use approve_project_baseline / rebaseline_project.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


