--
-- Name: hard_delete_governance_cadence(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_governance_cadence(_cadence_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row governance_cadences%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF _row.archived_at IS NULL THEN
    RAISE EXCEPTION 'Cadence must be archived before hard delete' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM governance_records WHERE cadence_id = _cadence_id) THEN
    RAISE EXCEPTION 'Cannot hard-delete cadence: records still reference it' USING ERRCODE='23503';
  END IF;
  DELETE FROM governance_cadences WHERE id = _cadence_id;
  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_cadence_hard_deleted', 'governance_cadence', _cadence_id,
    jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
END; $$;


--
-- Name: hard_delete_governance_record(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_governance_record(_record_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row governance_records%ROWTYPE; _dec_count int; _link_count int;
BEGIN
  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF _row.archived_at IS NULL THEN
    RAISE EXCEPTION 'Record must be archived before hard delete' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO _dec_count FROM governance_record_decisions WHERE governance_record_id = _record_id;
  SELECT count(*) INTO _link_count FROM governance_record_links WHERE governance_record_id = _record_id;
  DELETE FROM governance_records WHERE id = _record_id; -- cascades to decisions/links
  PERFORM log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_hard_deleted', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'decision_count', _dec_count,
                       'link_count', _link_count),
    _row.workspace_id);
END; $$;


