--
-- Name: hard_delete_phase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_phase(_id uuid) RETURNS TABLE(storage_path text, bucket text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row phases%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM phases WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Phase must be archived before hard delete'; END IF;
  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'phase', _id, '{}'::jsonb, _row.workspace_id);
  DELETE FROM raci_assignments WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM dependencies WHERE workspace_id = _row.workspace_id AND (
    (source_type IN ('phase','task') AND source_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id))
    OR (target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id))
  );
  DELETE FROM task_assignments WHERE task_id IN (SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM kpi_updates WHERE kpi_definition_id IN (SELECT id FROM kpi_definitions WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id));
  DELETE FROM kpi_definitions WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM blockers WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM risks WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM comments WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM execution_updates WHERE target_type IN ('phase','task') AND target_id IN (SELECT _id UNION ALL SELECT id FROM tasks WHERE phase_id=_id);
  DELETE FROM tasks WHERE phase_id=_id;
  DELETE FROM phases WHERE id=_id;
  RETURN;
END;
$$;


--
-- Name: hard_delete_program(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_program(_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row programs%ROWTYPE; _cnt int;
BEGIN
  SELECT * INTO _row FROM programs WHERE id=_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Program not found'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Program must be archived before hard delete'; END IF;
  SELECT count(*) INTO _cnt FROM projects WHERE program_id=_id;
  IF _cnt > 0 THEN RAISE EXCEPTION 'Program still has % project(s); detach or delete them first', _cnt; END IF;
  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'program', _id, '{}'::jsonb, _row.workspace_id);
  DELETE FROM programs WHERE id=_id;
END;
$$;


--
-- Name: hard_delete_project(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_project(_id uuid) RETURNS TABLE(storage_path text, bucket text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row projects%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM projects WHERE id=_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Project must be archived before hard delete'; END IF;
  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'project', _id, '{}'::jsonb, _row.workspace_id);
  UPDATE project_templates SET source_project_id = NULL WHERE source_project_id=_id;
  DELETE FROM raci_assignments WHERE workspace_id=_row.workspace_id AND target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM dependencies WHERE workspace_id=_row.workspace_id;
  DELETE FROM task_assignments WHERE task_id IN (SELECT id FROM tasks WHERE project_id=_id);
  DELETE FROM kpi_updates WHERE kpi_definition_id IN (SELECT id FROM kpi_definitions WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  ));
  DELETE FROM kpi_definitions WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM blockers WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM risks WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM comments WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM execution_updates WHERE target_type IN ('project','phase','task') AND target_id IN (
    SELECT _id UNION ALL SELECT id FROM phases WHERE project_id=_id UNION ALL SELECT id FROM tasks WHERE project_id=_id
  );
  DELETE FROM tasks WHERE project_id=_id;
  DELETE FROM backlog_items WHERE project_id=_id;
  DELETE FROM sprints WHERE project_id=_id;
  DELETE FROM board_workflow_states WHERE project_id=_id;
  DELETE FROM project_team_members WHERE project_id=_id;
  DELETE FROM phases WHERE project_id=_id;
  DELETE FROM projects WHERE id=_id;
  RETURN;
END;
$$;


