--
-- Name: hard_delete_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hard_delete_task(_id uuid) RETURNS TABLE(storage_path text, bucket text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row tasks%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM tasks WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;
  PERFORM _assert_admin(_row.workspace_id, _row.organization_id);
  IF NOT _row.is_archived THEN RAISE EXCEPTION 'Task must be archived before hard delete'; END IF;
  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  PERFORM log_activity_event(_row.organization_id, auth.uid(), 'lifecycle.hard_delete', 'task', _id, '{}'::jsonb, _row.workspace_id);
  DELETE FROM raci_assignments WHERE target_type='task' AND target_id=_id;
  DELETE FROM dependencies WHERE workspace_id=_row.workspace_id AND ((source_type='task' AND source_id=_id) OR (target_type='task' AND target_id=_id));
  DELETE FROM task_assignments WHERE task_id=_id;
  DELETE FROM kpi_updates WHERE kpi_definition_id IN (SELECT id FROM kpi_definitions WHERE target_type='task' AND target_id=_id);
  DELETE FROM kpi_definitions WHERE target_type='task' AND target_id=_id;
  DELETE FROM blockers WHERE target_type='task' AND target_id=_id;
  DELETE FROM risks WHERE target_type='task' AND target_id=_id;
  DELETE FROM comments WHERE target_type='task' AND target_id=_id;
  DELETE FROM execution_updates WHERE target_type='task' AND target_id=_id;
  DELETE FROM tasks WHERE id=_id;
  RETURN;
END;
$$;


--
-- Name: has_pm_authority(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_pm_authority(_user_id uuid, _workspace_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.is_workspace_admin_or_higher(_user_id, _workspace_id)
  OR EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND workspace_id = _workspace_id
      AND role = 'project_manager'
  )
$$;


--
-- Name: has_project_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_project_access(_user_id uuid, _project_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.projects p
    WHERE p.id = _project_id
      AND (
        public.is_org_admin(_user_id, p.organization_id)
        OR public.is_workspace_admin_or_higher(_user_id, p.workspace_id)
        OR EXISTS (
          SELECT 1 FROM public.project_memberships pm
          WHERE pm.project_id = _project_id
            AND pm.user_id = _user_id
            AND pm.removed_at IS NULL
        )
      )
  )
$$;


