$$;


--
-- Name: is_workspace_admin_or_higher(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_workspace_admin_or_higher(_user_id uuid, _workspace_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id
      AND workspace_id = _workspace_id
      AND role = 'workspace_admin'
  )
  OR EXISTS (
    SELECT 1 FROM public.user_roles ur
    JOIN public.workspaces w ON w.organization_id = ur.organization_id
    WHERE ur.user_id = _user_id
      AND w.id = _workspace_id
      AND ur.role = 'org_admin'
      AND ur.workspace_id IS NULL
  )
$$;


--
-- Name: is_workspace_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_workspace_member(_user_id uuid, _workspace_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.workspace_memberships
    WHERE user_id = _user_id
      AND workspace_id = _workspace_id
  )
$$;


--
-- Name: kc_admin_archive_article(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kc_admin_archive_article(_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.knowledge_articles WHERE id = _id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'not found'; END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.knowledge_articles
  SET status = 'archived', archived_at = now(),
      updated_by = auth.uid(), updated_at = now()
  WHERE id = _id;
END; $$;


--
-- Name: kc_admin_create_article(uuid, text, text, public.knowledge_article_type, text, text, text, public.knowledge_article_visibility, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kc_admin_create_article(_category_id uuid, _title text, _slug text, _article_type public.knowledge_article_type DEFAULT 'concept'::public.knowledge_article_type, _summary text DEFAULT NULL::text, _body text DEFAULT NULL::text, _tooltip_excerpt text DEFAULT NULL::text, _visibility public.knowledge_article_visibility DEFAULT 'all_users'::public.knowledge_article_visibility, _related_route text DEFAULT NULL::text, _related_object_type text DEFAULT NULL::text, _related_object_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _owner_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid := public.get_user_org_id(auth.uid());
  v_id  uuid;
BEGIN
  IF v_org IS NULL OR NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  -- ensure category belongs to same org
  IF NOT EXISTS (SELECT 1 FROM public.knowledge_categories WHERE id = _category_id AND organization_id = v_org) THEN
    RAISE EXCEPTION 'invalid category';
  END IF;
  INSERT INTO public.knowledge_articles (
    organization_id, category_id, title, slug, article_type,
    summary, body, tooltip_excerpt, status, visibility,
    related_route, related_object_type, related_object_id,
    workspace_id, owner_id, created_by, updated_by
  ) VALUES (
    v_org, _category_id, _title, _slug, _article_type,
    _summary, _body, _tooltip_excerpt, 'draft', _visibility,
    _related_route, _related_object_type, _related_object_id,
    _workspace_id, _owner_id, auth.uid(), auth.uid()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END; $$;


