--
-- Name: kc_admin_update_article(uuid, uuid, text, text, public.knowledge_article_type, text, text, text, public.knowledge_article_visibility, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kc_admin_update_article(_id uuid, _category_id uuid DEFAULT NULL::uuid, _title text DEFAULT NULL::text, _slug text DEFAULT NULL::text, _article_type public.knowledge_article_type DEFAULT NULL::public.knowledge_article_type, _summary text DEFAULT NULL::text, _body text DEFAULT NULL::text, _tooltip_excerpt text DEFAULT NULL::text, _visibility public.knowledge_article_visibility DEFAULT NULL::public.knowledge_article_visibility, _related_route text DEFAULT NULL::text, _related_object_type text DEFAULT NULL::text, _related_object_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _owner_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.knowledge_articles WHERE id = _id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'not found'; END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN RAISE EXCEPTION 'forbidden'; END IF;
  UPDATE public.knowledge_articles SET
    category_id         = COALESCE(_category_id, category_id),
    title               = COALESCE(_title, title),
    slug                = COALESCE(_slug, slug),
    article_type        = COALESCE(_article_type, article_type),
    summary             = COALESCE(_summary, summary),
    body                = COALESCE(_body, body),
    tooltip_excerpt     = COALESCE(_tooltip_excerpt, tooltip_excerpt),
    visibility          = COALESCE(_visibility, visibility),
    related_route       = COALESCE(_related_route, related_route),
    related_object_type = COALESCE(_related_object_type, related_object_type),
    related_object_id   = COALESCE(_related_object_id, related_object_id),
    workspace_id        = COALESCE(_workspace_id, workspace_id),
    owner_id            = COALESCE(_owner_id, owner_id),
    version             = version + 1,
    updated_by          = auth.uid(),
    updated_at          = now()
  WHERE id = _id;
END; $$;


