--
-- Name: kpi_app_mappings_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_app_mappings_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_kpi_org uuid;
  v_kpi_ws uuid;
  v_kpi_target_type text;
  v_kpi_target_id uuid;
  v_kpi_value_type text;
  v_kpi_calc_key text;
  v_kpi_archived boolean;
  v_proj_org uuid;
  v_proj_ws uuid;
  v_cat_value_type text;
  v_cat_active boolean;
BEGIN
  -- Project must exist and belong to same org+workspace
  SELECT organization_id, workspace_id
    INTO v_proj_org, v_proj_ws
    FROM public.projects
   WHERE id = NEW.project_id;

  IF v_proj_org IS NULL THEN
    RAISE EXCEPTION 'kpi_app_mappings: project_id % not found', NEW.project_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_proj_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'kpi_app_mappings: project organization mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_proj_ws <> NEW.workspace_id THEN
    RAISE EXCEPTION 'kpi_app_mappings: project workspace mismatch'
      USING ERRCODE = 'check_violation';
  END IF;

  -- KPI definition must exist, be in same org+workspace, target this project
  SELECT organization_id, workspace_id, target_type, target_id,
         value_type, calculation_key, is_archived
    INTO v_kpi_org, v_kpi_ws, v_kpi_target_type, v_kpi_target_id,
         v_kpi_value_type, v_kpi_calc_key, v_kpi_archived
    FROM public.kpi_definitions
   WHERE id = NEW.kpi_definition_id;

  IF v_kpi_org IS NULL THEN
    RAISE EXCEPTION 'kpi_app_mappings: kpi_definition_id % not found', NEW.kpi_definition_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_kpi_org <> NEW.organization_id OR v_kpi_ws <> NEW.workspace_id THEN
    RAISE EXCEPTION 'kpi_app_mappings: KPI definition org/workspace mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_kpi_target_type <> 'project' OR v_kpi_target_id <> NEW.project_id THEN
    RAISE EXCEPTION 'kpi_app_mappings: KPI definition does not target project %', NEW.project_id
      USING ERRCODE = 'check_violation';
  END IF;

  -- schedule_signal exclusion (carried from C1.6b/C1.9/C2.1)
  IF v_kpi_calc_key = 'schedule_signal' THEN
    RAISE EXCEPTION 'kpi_app_mappings: schedule_signal is non-mappable to external KPI App'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Archived KPI definition cannot be actively mapped
  IF NEW.is_active AND v_kpi_archived = true THEN
    RAISE EXCEPTION 'kpi_app_mappings: archived KPI definition cannot have active mapping'
      USING ERRCODE = 'check_violation';
  END IF;

  -- External catalog row must exist for same org (FK enforces existence;
  -- here we additionally check value_type compatibility and active state).
  SELECT value_type, is_active
    INTO v_cat_value_type, v_cat_active
    FROM public.kpi_app_external_kpis
   WHERE organization_id = NEW.organization_id
     AND external_kpi_id = NEW.external_kpi_id;

  IF v_cat_value_type IS NULL THEN
    RAISE EXCEPTION 'kpi_app_mappings: external catalog row not found for org+external_kpi_id'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF v_cat_value_type <> v_kpi_value_type THEN
    RAISE EXCEPTION 'kpi_app_mappings: value_type mismatch (BTPM=%, external=%)',
      v_kpi_value_type, v_cat_value_type
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.is_active AND v_cat_active = false THEN
    RAISE EXCEPTION 'kpi_app_mappings: external catalog row is inactive; active mapping rejected'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: kpi_app_outbox_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_app_outbox_validate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_map_org uuid;
  v_map_ws uuid;
  v_map_proj uuid;
  v_map_kpi uuid;
  v_map_active boolean;
  v_kpi_org uuid;
  v_kpi_ws uuid;
  v_kpi_target_type text;
  v_kpi_target_id uuid;
  v_kpi_value_type text;
  v_kpi_calc_key text;
  v_kpi_archived boolean;
  v_snap_org uuid;
  v_snap_kpi uuid;
  v_snap_project uuid;
  v_snap_value_type text;
BEGIN
  -- Mapping must exist + match scope + match KPI
  SELECT organization_id, workspace_id, project_id, kpi_definition_id, is_active
    INTO v_map_org, v_map_ws, v_map_proj, v_map_kpi, v_map_active
    FROM public.kpi_app_mappings
   WHERE id = NEW.mapping_id;

  IF v_map_org IS NULL THEN
    RAISE EXCEPTION 'kpi_app_outbox: mapping_id % not found', NEW.mapping_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_map_org <> NEW.organization_id
     OR v_map_ws  <> NEW.workspace_id
     OR v_map_proj <> NEW.project_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: mapping org/workspace/project mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_map_kpi <> NEW.kpi_definition_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: mapping.kpi_definition_id mismatch'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Active outbox rows must reference active mappings (cancelled rows historical)
  IF NEW.status <> 'cancelled' AND v_map_active = false THEN
    RAISE EXCEPTION 'kpi_app_outbox: active outbox rejected for inactive mapping'
      USING ERRCODE = 'check_violation';
  END IF;

  -- KPI definition: org/ws scope, schedule_signal exclusion, archive lifecycle
  SELECT organization_id, workspace_id, target_type, target_id,
         value_type, calculation_key, is_archived
    INTO v_kpi_org, v_kpi_ws, v_kpi_target_type, v_kpi_target_id,
         v_kpi_value_type, v_kpi_calc_key, v_kpi_archived
    FROM public.kpi_definitions
   WHERE id = NEW.kpi_definition_id;

  IF v_kpi_org IS NULL THEN
    RAISE EXCEPTION 'kpi_app_outbox: kpi_definition_id % not found', NEW.kpi_definition_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_kpi_org <> NEW.organization_id OR v_kpi_ws <> NEW.workspace_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: KPI definition org/workspace mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_kpi_target_type <> 'project' OR v_kpi_target_id <> NEW.project_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: KPI definition does not target project %', NEW.project_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_kpi_calc_key = 'schedule_signal' THEN
    RAISE EXCEPTION 'kpi_app_outbox: schedule_signal is non-submittable to external KPI App'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status <> 'cancelled' AND v_kpi_archived = true THEN
    RAISE EXCEPTION 'kpi_app_outbox: active outbox rejected for archived KPI definition'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_kpi_value_type <> NEW.source_value_type THEN
    RAISE EXCEPTION 'kpi_app_outbox: source_value_type mismatch (KPI=%, outbox=%)',
      v_kpi_value_type, NEW.source_value_type
      USING ERRCODE = 'check_violation';
  END IF;

  -- Snapshot must exist + match org + match KPI + match project + match value_type
  SELECT organization_id, kpi_definition_id, project_id, value_type
    INTO v_snap_org, v_snap_kpi, v_snap_project, v_snap_value_type
    FROM public.kpi_snapshots
   WHERE id = NEW.source_snapshot_id;

  IF v_snap_org IS NULL THEN
    RAISE EXCEPTION 'kpi_app_outbox: source_snapshot_id % not found', NEW.source_snapshot_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_snap_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: source_snapshot organization mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_snap_kpi <> NEW.kpi_definition_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: source_snapshot KPI mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_snap_project <> NEW.project_id THEN
    RAISE EXCEPTION 'kpi_app_outbox: source_snapshot project mismatch'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_snap_value_type <> NEW.source_value_type THEN
    RAISE EXCEPTION 'kpi_app_outbox: source_snapshot value_type mismatch (snap=%, outbox=%)',
      v_snap_value_type, NEW.source_value_type
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: kpi_scheduler_diagnostics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kpi_scheduler_diagnostics() RETURNS TABLE(expected_jobname text, job_configured boolean, jobid bigint, schedule text, active boolean, last_run_started_at timestamp with time zone, last_run_finished_at timestamp with time zone, last_run_status text, last_run_return_message text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'cron', 'extensions'
    AS $$
DECLARE
  v_is_org_admin boolean;
BEGIN
  -- Authority gate: caller must be Org Admin in at least one organization.
  -- Diagnostics expose global cron state, so workspace-admin is insufficient.
  SELECT EXISTS (
    SELECT 1
    FROM public.organizations o
    WHERE public.is_org_admin(auth.uid(), o.id)
  ) INTO v_is_org_admin;

  IF NOT v_is_org_admin THEN
    RAISE EXCEPTION 'Org-admin authority required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH expected(expected_jobname) AS (
    VALUES
      ('run-kpi-snapshot-capture-scheduler-cron'),
      ('run-kpi-app-scheduler-cron')
  ),
  jobs AS (
    SELECT j.jobid, j.jobname, j.schedule, j.active
    FROM cron.job j
    WHERE j.jobname IN (
      'run-kpi-snapshot-capture-scheduler-cron',
      'run-kpi-app-scheduler-cron'
    )
  ),
  last_runs AS (
    SELECT DISTINCT ON (d.jobid)
      d.jobid,
      d.start_time AS last_run_started_at,
      d.end_time   AS last_run_finished_at,
      d.status     AS last_run_status,
      LEFT(COALESCE(d.return_message, ''), 200) AS last_run_return_message
    FROM cron.job_run_details d
    JOIN jobs j ON j.jobid = d.jobid
    ORDER BY d.jobid, d.start_time DESC
  )
  SELECT
    e.expected_jobname,
    (j.jobid IS NOT NULL)            AS job_configured,
    j.jobid,
    j.schedule,
    j.active,
    lr.last_run_started_at,
    lr.last_run_finished_at,
    lr.last_run_status,
    NULLIF(lr.last_run_return_message, '') AS last_run_return_message
  FROM expected e
  LEFT JOIN jobs j      ON j.jobname = e.expected_jobname
  LEFT JOIN last_runs lr ON lr.jobid  = j.jobid;
END;
$$;


--
-- Name: link_adoption_object(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_adoption_object(_adoption_plan_id uuid, _object_type text, _object_id uuid, _adoption_initiative_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org uuid; _ws uuid; _proj uuid; _uid uuid := auth.uid();
        _obj_proj uuid; _init_plan uuid; _id uuid; _evt text;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF _object_type NOT IN ('risk','blocker','kpi') THEN RAISE EXCEPTION 'invalid_object_type'; END IF;
  SELECT organization_id, workspace_id, project_id INTO _org, _ws, _proj
  FROM public.adoption_plans WHERE id = _adoption_plan_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_adoption_plan'; END IF;
  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  IF _adoption_initiative_id IS NOT NULL THEN
    SELECT adoption_plan_id INTO _init_plan FROM public.adoption_initiatives WHERE id = _adoption_initiative_id;
    IF _init_plan IS DISTINCT FROM _adoption_plan_id THEN
      RAISE EXCEPTION 'initiative_plan_mismatch';
    END IF;
  END IF;

  _obj_proj := public.adoption_resolve_object_project(_object_type, _object_id);
  IF _obj_proj IS NULL THEN RAISE EXCEPTION 'invalid_object_reference'; END IF;
  IF _obj_proj <> _proj THEN RAISE EXCEPTION 'object_project_mismatch'; END IF;

  INSERT INTO public.adoption_object_links(
    organization_id, workspace_id, project_id, adoption_plan_id,
    adoption_initiative_id, object_type, object_id, created_by
  ) VALUES (
    _org, _ws, _proj, _adoption_plan_id,
    _adoption_initiative_id, _object_type, _object_id, _uid
  ) RETURNING id INTO _id;

  _evt := CASE _object_type
    WHEN 'risk' THEN 'adoption_risk_linked'
    WHEN 'blocker' THEN 'adoption_blocker_linked'
    WHEN 'kpi' THEN 'adoption_kpi_linked'
  END;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => _evt,
    _target_type => 'project', _target_id => _proj,
    _metadata => jsonb_build_object(
      'adoption_plan_id', _adoption_plan_id,
      'adoption_initiative_id', _adoption_initiative_id,
      'object_type', _object_type,
      'object_id', _object_id,
      'link_id', _id
    ),
    _workspace_id => _ws
  );
  RETURN _id;
END $$;


--
-- Name: link_task_to_adoption(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_task_to_adoption(_task_id uuid, _adoption_initiative_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid; _ws uuid; _proj uuid; _phase uuid;
  _old_init uuid; _was_related boolean;
  _plan_id uuid; _init_plan uuid; _init_archived boolean;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT t.organization_id, t.workspace_id, p.project_id, t.phase_id,
         t.adoption_initiative_id, COALESCE(t.is_adoption_related, false)
    INTO _org, _ws, _proj, _phase, _old_init, _was_related
  FROM public.tasks t
  JOIN public.phases p ON p.id = t.phase_id
  WHERE t.id = _task_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'invalid_task'; END IF;

  IF NOT public.has_pm_authority(_uid, _ws) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT id INTO _plan_id FROM public.adoption_plans
  WHERE project_id = _proj AND COALESCE(is_archived, false) = false
  LIMIT 1;
  IF _plan_id IS NULL THEN RAISE EXCEPTION 'adoption_plan_required'; END IF;

  IF _adoption_initiative_id IS NOT NULL THEN
    SELECT adoption_plan_id, COALESCE(is_archived, false)
      INTO _init_plan, _init_archived
    FROM public.adoption_initiatives WHERE id = _adoption_initiative_id;
    IF _init_plan IS NULL THEN RAISE EXCEPTION 'invalid_initiative'; END IF;
    IF _init_plan IS DISTINCT FROM _plan_id THEN RAISE EXCEPTION 'initiative_plan_mismatch'; END IF;
    IF _init_archived THEN RAISE EXCEPTION 'invalid_initiative'; END IF;
  END IF;

  UPDATE public.tasks
     SET is_adoption_related = true,
         adoption_initiative_id = _adoption_initiative_id,
         updated_at = now()
   WHERE id = _task_id;

  PERFORM public.log_activity_event(
    _organization_id => _org, _actor_id => _uid,
    _event_type => 'adoption_task_linked',
    _target_type => 'task', _target_id => _task_id,
    _metadata => jsonb_build_object(
      'project_id', _proj,
      'phase_id', _phase,
      'adoption_plan_id', _plan_id,
      'old_adoption_initiative_id', _old_init,
      'new_adoption_initiative_id', _adoption_initiative_id,
      'linked_to_general_plan', (_adoption_initiative_id IS NULL)
    ),
    _workspace_id => _ws
  );

  RETURN _task_id;
END $$;


--
-- Name: list_active_portfolio_items_for_project_picker(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_active_portfolio_items_for_project_picker(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
  v_client_id text;
BEGIN
  -- Portfolio-12E.4: browser-internal only. Signed external OAuth is always denied.
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  IF NOT public.has_project_pm_authority(_uid, _project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT organization_id INTO _org FROM public.projects WHERE id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Project not found'; END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.name_sort), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      pi.id,
      public.btpm_decrypt(pi.name, pi.organization_id) AS name,
      public.btpm_decrypt(pi.code, pi.organization_id) AS code,
      pi.lifecycle_state,
      pi.owner_id,
      public.btpm_decrypt(pi.name, pi.organization_id) AS name_sort
    FROM public.portfolio_items pi
    WHERE pi.organization_id = _org
      AND pi.is_archived = false
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: list_active_portfolio_items_for_workspace_picker(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_active_portfolio_items_for_workspace_picker(_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb;
  v_client_id text;
BEGIN
  -- Portfolio-12E.4: browser-internal only. Signed external OAuth is always denied.
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO _org FROM public.workspaces WHERE id = _workspace_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;

  IF NOT (public.has_pm_authority(_uid, _workspace_id) OR public.is_org_admin(_uid, _org)) THEN
