      public.btpm_decrypt(pi.code, pi.organization_id) AS code,
      pi.lifecycle_state,
      pi.owner_id,
      public.btpm_decrypt(pi.name, pi.organization_id) AS name_sort
    FROM public.portfolio_items pi
    WHERE pi.organization_id = _org
      AND pi.is_archived = false
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: list_adoption_templates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_adoption_templates(_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _result jsonb := '[]'::jsonb;
  _r record;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT organization_id INTO _org FROM public.workspaces WHERE id = _workspace_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'invalid_workspace';
  END IF;
  IF NOT (public.is_workspace_member(_uid, _workspace_id)
          OR public.is_org_admin(_uid, _org)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- System template entry (always available, never editable)
  _result := jsonb_build_array(
    jsonb_build_object(
      'template_id', NULL,
      'template_key', 'btpm_standard_adoption',
      'name', 'BTPM Standard Adoption Plan',
      'description', 'The built-in BTPM adoption template covering stakeholder impact, sponsor alignment, communication, training, feedback, adoption tracking, hypercare, and reinforcement.',
      'is_system', true,
      'scope', 'system',
      'source_template_key', NULL,
      'is_archived', false,
      'updated_at', NULL,
      'created_by', NULL,
      'initiative_count', jsonb_array_length(public._btpm_adoption_template_v1()),
      'task_count', (
        SELECT COALESCE(SUM(jsonb_array_length(i->'tasks')), 0)::int
        FROM jsonb_array_elements(public._btpm_adoption_template_v1()) AS i
      )
    )
  );

  FOR _r IN
    SELECT t.id, t.name, t.description, t.scope, t.source_template_key,
           t.is_system, t.is_archived, t.updated_at, t.created_by,
           t.organization_id,
           (SELECT COUNT(*) FROM public.adoption_template_initiatives i WHERE i.adoption_template_id = t.id AND i.is_archived = false) AS init_count,
           (SELECT COUNT(*) FROM public.adoption_template_tasks tk WHERE tk.adoption_template_id = t.id AND tk.is_archived = false) AS task_count
    FROM public.adoption_templates t
    WHERE t.workspace_id = _workspace_id
      AND t.is_archived = false
    ORDER BY t.updated_at DESC
  LOOP
    _result := _result || jsonb_build_array(jsonb_build_object(
      'template_id', _r.id,
      'template_key', NULL,
      'name', public.btpm_decrypt(_r.name, _r.organization_id),
      'description', public.btpm_decrypt(_r.description, _r.organization_id),
      'is_system', false,
      'scope', _r.scope,
      'source_template_key', _r.source_template_key,
      'is_archived', _r.is_archived,
      'updated_at', _r.updated_at,
      'created_by', _r.created_by,
      'initiative_count', _r.init_count,
      'task_count', _r.task_count
    ));
  END LOOP;

  RETURN _result;
END $$;


--
-- Name: list_ai_instruction_templates(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_ai_instruction_templates(_feature_key text) RETURNS SETOF public.ai_instruction_templates
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _feature_key NOT IN ('decision_case_brief') THEN
    RAISE EXCEPTION 'invalid feature_key';
  END IF;
  RETURN QUERY
    SELECT t.id,
           t.organization_id,
           t.feature_key,
           t.version,
           t.title,
           public.btpm_decrypt(t.instruction_text, t.organization_id) AS instruction_text,
           CASE WHEN t.notes IS NULL THEN NULL
                ELSE public.btpm_decrypt(t.notes, t.organization_id) END AS notes,
           t.status,
           t.created_by,
           t.activated_by,
           t.activated_at,
           t.created_at,
           t.updated_at
      FROM public.ai_instruction_templates t
     WHERE t.organization_id = _org_id
       AND t.feature_key = _feature_key
     ORDER BY t.version DESC;
END;
$$;


--
-- Name: ai_model_registry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_model_registry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    model_id text NOT NULL,
    display_name text NOT NULL,
    capability_tier text NOT NULL,
    supports_file_input boolean DEFAULT false NOT NULL,
    supports_vision boolean DEFAULT false NOT NULL,
    supports_structured_output boolean DEFAULT true NOT NULL,
    recommended_for_guide boolean DEFAULT false NOT NULL,
    recommended_for_decision_cases boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recommended_for_roadmap_story boolean DEFAULT false NOT NULL,
    CONSTRAINT ai_model_registry_provider_check CHECK ((provider = 'openai'::text)),
    CONSTRAINT ai_model_registry_tier_check CHECK ((capability_tier = ANY (ARRAY['premium_reasoning'::text, 'standard_reasoning'::text, 'low_cost'::text, 'diagnostic'::text])))
);


--
-- Name: list_ai_model_registry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_ai_model_registry() RETURNS SETOF public.ai_model_registry
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
BEGIN
  SELECT organization_id INTO _org_id FROM public.profiles WHERE id = auth.uid();
  IF _org_id IS NULL OR NOT public.is_org_admin(auth.uid(), _org_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.ai_model_registry WHERE active = true ORDER BY sort_order, display_name;
END;
$$;


--
-- Name: list_decision_case_ai_runs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decision_case_ai_runs(_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _row public.governance_records%ROWTYPE;
  _result jsonb;
  v_client_id text;
  v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM public._gov_assert_project_read(_row.project_id);
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'AI runs are only available for decision cases' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(jsonb_agg(payload ORDER BY started_at_v DESC), '[]'::jsonb)
  INTO _result
  FROM (
    SELECT
      r.started_at AS started_at_v,
      jsonb_build_object(
        'id', r.id,
        'status', r.status,
        'run_type', r.run_type,
        'model_provider', r.model_provider,
        'model_id', r.model_id,
        'model_source', r.model_source,
        'reasoning_effort', r.reasoning_effort,
        'template_id', r.template_id,
        'template_version', r.template_version,
        'files_selected_count', r.files_selected_count,
        'files_sent_count', r.files_sent_count,
        'files_skipped_count', r.files_skipped_count,
        'total_bytes_sent', r.total_bytes_sent,
        'error_code', r.error_code,
        'brief_version_id', r.brief_version_id,
        'started_by', r.started_by,
        'started_by_display', (SELECT public.btpm_decrypt(p.display_name, p.organization_id)
                               FROM public.profiles p WHERE p.id = r.started_by),
        'started_at', r.started_at,
        'completed_at', r.completed_at,
        'saved_at', r.saved_at,
        'discarded_at', r.discarded_at
      ) AS payload
    FROM public.decision_case_ai_runs r
    WHERE r.governance_record_id = _record_id
    ORDER BY r.started_at DESC
    LIMIT 50
  ) sub;

  RETURN _result;
END; $$;


--
-- Name: list_decrypted_activity_events(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_activity_events(_target_type text, _target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _result jsonb;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', ae.id, 'event_type', ae.event_type, 'target_type', ae.target_type, 'target_id', ae.target_id, 'actor_id', ae.actor_id, 'organization_id', ae.organization_id, 'workspace_id', ae.workspace_id, 'created_at', ae.created_at, 'metadata', btpm_decrypt(ae.metadata, ae.organization_id)) ORDER BY ae.created_at DESC), '[]'::jsonb) INTO _result FROM activity_events ae WHERE ae.target_type = _target_type AND ae.target_id = _target_id AND ((ae.workspace_id IS NOT NULL AND (is_workspace_member(auth.uid(), ae.workspace_id) OR is_org_admin(auth.uid(), ae.organization_id))) OR (ae.workspace_id IS NULL AND is_org_admin(auth.uid(), ae.organization_id)));
  RETURN COALESCE(_result, '[]'::jsonb);
END;
$$;


--
-- Name: list_decrypted_backlog_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_backlog_items(_project_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _result json;
  _org_id uuid;
  v_client_id text;
  v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.projects WHERE id = _project_id;
  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;

  IF public.is_user_org_member(v_caller, _org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT bi.id, bi.organization_id, bi.workspace_id, bi.project_id,
      bi.phase_id, bi.sprint_id, bi.workflow_state_id, bi.title,
      CASE WHEN bi.description IS NOT NULL AND bi.description != ''
        THEN btpm_decrypt(bi.description, bi.organization_id) ELSE bi.description END AS description,
      bi.priority, bi.sort_order, bi.is_archived, bi.created_by, bi.created_at, bi.updated_at
    FROM public.backlog_items bi WHERE bi.project_id = _project_id
    ORDER BY bi.sort_order, bi.created_at) t;
  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: list_decrypted_blockers(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_blockers(_target_type text, _target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _result jsonb;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', b.id, 'title', b.title, 'status', b.status, 'severity', b.severity, 'target_type', b.target_type, 'target_id', b.target_id, 'reported_by', b.reported_by, 'resolved_at', b.resolved_at, 'resolved_by', b.resolved_by, 'workspace_id', b.workspace_id, 'organization_id', b.organization_id, 'created_at', b.created_at, 'updated_at', b.updated_at, 'description', btpm_decrypt(b.description, b.organization_id)) ORDER BY b.created_at DESC), '[]'::jsonb) INTO _result FROM blockers b WHERE b.target_type = _target_type AND b.target_id = _target_id AND (is_workspace_member(auth.uid(), b.workspace_id) OR is_org_admin(auth.uid(), b.organization_id));
  RETURN _result;
END;
$$;


--
-- Name: list_decrypted_comments(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_comments(_target_type text, _target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT COALESCE(jsonb_agg(c_obj ORDER BY (c_obj->>'created_at') ASC), '[]'::jsonb) INTO v_result
  FROM (
    SELECT jsonb_build_object(
      'id', c.id,
      'target_type', c.target_type,
      'target_id', c.target_id,
      'author_id', c.author_id,
      'is_edited', c.is_edited,
      'organization_id', c.organization_id,
      'workspace_id', c.workspace_id,
      'created_at', c.created_at,
      'updated_at', c.updated_at,
      'body', public.btpm_decrypt(c.body, c.organization_id),
      'references', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', l.id,
          'referenced_type', l.referenced_type,
          'referenced_id', l.referenced_id,
          'workspace_id', l.workspace_id,
          'project_id', CASE l.referenced_type
            WHEN 'project' THEN l.referenced_id
            WHEN 'phase'   THEN (SELECT ph.project_id FROM public.phases ph WHERE ph.id = l.referenced_id)
            WHEN 'task'    THEN (SELECT t.project_id  FROM public.tasks  t  WHERE t.id  = l.referenced_id)
          END,
          'phase_id', CASE l.referenced_type
            WHEN 'task' THEN (SELECT t.phase_id FROM public.tasks t WHERE t.id = l.referenced_id)
            ELSE NULL
          END,
          'display_label', CASE l.referenced_type
            WHEN 'project' THEN (SELECT public.btpm_decrypt(p.name, p.organization_id) FROM public.projects p WHERE p.id = l.referenced_id)
            WHEN 'phase'   THEN (SELECT public.btpm_decrypt(ph.name, ph.organization_id) FROM public.phases ph WHERE ph.id = l.referenced_id)
            WHEN 'task'    THEN (SELECT public.btpm_decrypt(t.name, t.organization_id) FROM public.tasks t WHERE t.id = l.referenced_id)
          END,
          'context_label', CASE l.referenced_type
            WHEN 'phase' THEN (SELECT public.btpm_decrypt(p.name, p.organization_id) FROM public.projects p JOIN public.phases ph ON ph.project_id = p.id WHERE ph.id = l.referenced_id)
            WHEN 'task'  THEN (
              SELECT public.btpm_decrypt(p.name, p.organization_id) || ' › ' || public.btpm_decrypt(ph.name, ph.organization_id)
                FROM public.tasks t JOIN public.phases ph ON ph.id = t.phase_id JOIN public.projects p ON p.id = t.project_id
               WHERE t.id = l.referenced_id
            )
            ELSE NULL
          END,
          'sort_order', l.sort_order
        ) ORDER BY l.sort_order)
        FROM public.entity_object_links l
        WHERE l.owner_type = 'comment' AND l.owner_id = c.id AND l.link_role = 'reference'
      ), '[]'::jsonb)
    ) AS c_obj
    FROM public.comments c
    WHERE c.target_type = _target_type AND c.target_id = _target_id
      AND (public.is_workspace_member(v_uid, c.workspace_id) OR public.is_org_admin(v_uid, c.organization_id))
  ) sub;
  RETURN v_result;
END;
$$;


--
-- Name: list_decrypted_execution_updates(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_execution_updates(_target_type text, _target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _result jsonb;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', eu.id, 'target_type', eu.target_type, 'target_id', eu.target_id, 'author_id', eu.author_id, 'update_date', eu.update_date, 'status_label', eu.status_label, 'organization_id', eu.organization_id, 'workspace_id', eu.workspace_id, 'created_at', eu.created_at, 'summary', btpm_decrypt(eu.summary, eu.organization_id)) ORDER BY eu.update_date DESC), '[]'::jsonb) INTO _result FROM execution_updates eu WHERE eu.target_type = _target_type AND eu.target_id = _target_id AND (is_workspace_member(auth.uid(), eu.workspace_id) OR is_org_admin(auth.uid(), eu.organization_id));
  RETURN _result;
END;
$$;


--
-- Name: list_decrypted_knowledge_articles(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_knowledge_articles(_category_id uuid DEFAULT NULL::uuid, _include_unpublished boolean DEFAULT false) RETURNS TABLE(id uuid, organization_id uuid, category_id uuid, title text, slug text, article_type public.knowledge_article_type, summary text, tooltip_excerpt text, status public.knowledge_article_status, visibility public.knowledge_article_visibility, related_route text, related_object_type text, related_object_id uuid, workspace_id uuid, owner_id uuid, version integer, published_at timestamp with time zone, archived_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org      uuid := public.get_user_org_id(auth.uid());
  v_is_admin boolean;
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  v_is_admin := public.is_org_admin(auth.uid(), v_org);

  RETURN QUERY
  SELECT a.id, a.organization_id, a.category_id,
         public.btpm_decrypt(a.title, a.organization_id),
         a.slug, a.article_type,
         public.btpm_decrypt(a.summary, a.organization_id),
         public.btpm_decrypt(a.tooltip_excerpt, a.organization_id),
         a.status, a.visibility,
         a.related_route, a.related_object_type, a.related_object_id,
         a.workspace_id, a.owner_id, a.version,
         a.published_at, a.archived_at, a.created_at, a.updated_at
  FROM public.knowledge_articles a
  WHERE a.organization_id = v_org
    AND (_category_id IS NULL OR a.category_id = _category_id)
    AND (
      v_is_admin
      OR (
        (_include_unpublished IS NOT TRUE)
        AND a.status = 'published'
        AND (
          a.visibility = 'all_users'
          OR (a.visibility = 'workspace_scoped'
              AND a.workspace_id IS NOT NULL
              AND public.is_workspace_member(auth.uid(), a.workspace_id))
        )
      )
    )
  ORDER BY a.updated_at DESC;
END; $$;


--
-- Name: list_decrypted_knowledge_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_knowledge_categories() RETURNS TABLE(id uuid, organization_id uuid, name text, slug text, description text, sort_order integer, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE v_org uuid := public.get_user_org_id(auth.uid());
BEGIN
  IF v_org IS NULL OR NOT public.is_active_user(auth.uid()) THEN RETURN; END IF;
  RETURN QUERY
  SELECT c.id, c.organization_id, c.name, c.slug,
         public.btpm_decrypt(c.description, c.organization_id),
         c.sort_order, c.is_active, c.created_at, c.updated_at
  FROM public.knowledge_categories c
  WHERE c.organization_id = v_org
  ORDER BY c.sort_order, c.name;
END; $$;


--
-- Name: list_decrypted_kpi_definitions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_kpi_definitions(_project_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _ws_id uuid;
  _org_id uuid;
  _result json;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT workspace_id, organization_id INTO _ws_id, _org_id FROM public.projects WHERE id = _project_id;
  IF _ws_id IS NULL THEN RETURN '[]'::json; END IF;

  IF public.is_user_org_member(v_caller, _org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT kd.id, kd.name, kd.unit, kd.target_value, kd.current_value,
      kd.target_direction, kd.target_type, kd.target_id,
      kd.is_archived, kd.created_at, kd.updated_at, kd.created_by,
      kd.workspace_id, kd.organization_id,
      kd.source_mode, kd.value_type, kd.cadence,
      kd.calculation_key, kd.formula_version,
      kd.completion_method, kd.comment_required, kd.action_plan_required,
      kd.auto_snapshot_enabled,
      CASE WHEN kd.description IS NOT NULL
           THEN btpm_decrypt(kd.description, kd.organization_id) ELSE NULL END AS description
    FROM kpi_definitions kd
    WHERE kd.target_type='project' AND kd.target_id=_project_id
      AND kd.organization_id = _org_id
      AND kd.workspace_id = _ws_id
    ORDER BY kd.is_archived, kd.created_at) t;
  RETURN COALESCE(_result, '[]'::json);
END; $$;


--
-- Name: list_decrypted_kpi_snapshots(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_kpi_snapshots(_project_id uuid, _kpi_definition_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _ws_id uuid;
  _org_id uuid;
  _result json;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT workspace_id, organization_id INTO _ws_id, _org_id FROM public.projects WHERE id = _project_id;
  IF _ws_id IS NULL THEN RETURN '[]'::json; END IF;

  IF public.is_user_org_member(v_caller, _org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT
      ks.id, ks.kpi_definition_id, ks.project_id,
      ks.workspace_id, ks.organization_id,
      ks.snapshot_date, ks.period_start, ks.period_end,
      ks.source_mode, ks.value_type, ks.value_amount,
      ks.calculation_key, ks.formula_version,
      ks.calculation_status, ks.generated_by,
      ks.created_at, ks.created_by,
      CASE WHEN ks.string_value IS NOT NULL
           THEN public.btpm_decrypt(ks.string_value, ks.organization_id) ELSE NULL END AS string_value,
      CASE WHEN ks.comment IS NOT NULL
           THEN public.btpm_decrypt(ks.comment, ks.organization_id) ELSE NULL END AS comment,
      CASE WHEN ks.action_plan IS NOT NULL
           THEN public.btpm_decrypt(ks.action_plan, ks.organization_id) ELSE NULL END AS action_plan
    FROM public.kpi_snapshots ks
    WHERE ks.project_id = _project_id
      AND ks.organization_id = _org_id
      AND ks.workspace_id = _ws_id
      AND (_kpi_definition_id IS NULL OR ks.kpi_definition_id = _kpi_definition_id)
    ORDER BY ks.snapshot_date DESC, ks.created_at DESC
  ) t;
  RETURN COALESCE(_result, '[]'::json);
END; $$;


--
-- Name: list_decrypted_kpi_updates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_kpi_updates(_kpi_definition_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _ws_id uuid;
  _org_id uuid;
  _result json;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT workspace_id, organization_id INTO _ws_id, _org_id
    FROM public.kpi_definitions WHERE id = _kpi_definition_id;
  IF _ws_id IS NULL THEN RETURN '[]'::json; END IF;

  IF public.is_user_org_member(v_caller, _org_id) IS NOT TRUE THEN
    RETURN '[]'::json;
  END IF;

  IF NOT (is_workspace_member(v_caller, _ws_id) OR is_org_admin(v_caller, _org_id)) THEN
    RETURN '[]'::json;
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT
      ku.id, ku.kpi_definition_id, ku.value, ku.update_date,
      ku.created_at, ku.author_id,
      ku.workspace_id, ku.organization_id,
      CASE WHEN ku.note IS NOT NULL
           THEN btpm_decrypt(ku.note, ku.organization_id)
           ELSE NULL END AS note,
      CASE WHEN p.organization_id IS NOT NULL AND p.display_name IS NOT NULL
           THEN btpm_decrypt(p.display_name, p.organization_id)
           ELSE p.display_name END AS author_name,
      CASE WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
           THEN btpm_decrypt(p.email, p.organization_id)
           ELSE p.email END AS author_email
    FROM kpi_updates ku
    LEFT JOIN profiles p ON p.id = ku.author_id
    WHERE ku.kpi_definition_id = _kpi_definition_id
      AND ku.organization_id = _org_id
      AND ku.workspace_id = _ws_id
    ORDER BY ku.update_date DESC, ku.created_at DESC
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: list_decrypted_program_projects(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_program_projects(_program_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _ws_id uuid;
  _org_id uuid;
  _result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT workspace_id, organization_id INTO _ws_id, _org_id
  FROM public.programs WHERE id = _program_id;

  IF _ws_id IS NULL THEN RAISE EXCEPTION 'Program not found'; END IF;

  IF NOT public.is_user_org_member(v_caller, _org_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF NOT (
    public.is_workspace_member(v_caller, _ws_id)
    OR public.is_org_admin(v_caller, _org_id)
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', p.id,
      'name', public.btpm_decrypt(p.name, p.organization_id),
      'status', p.status,
      'priority', p.priority,
      'start_date', p.start_date,
      'target_end_date', p.target_end_date
    ) ORDER BY public.btpm_decrypt(p.name, p.organization_id)
  ), '[]'::jsonb) INTO _result
  FROM public.projects p
  WHERE p.program_id = _program_id AND p.is_archived = false;

  RETURN _result;
END;
$$;


--
-- Name: list_decrypted_project_benefits(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_project_benefits(_project_id uuid, _include_archived boolean DEFAULT false) RETURNS TABLE(id uuid, organization_id uuid, workspace_id uuid, project_id uuid, benefit_type text, custom_benefit_type_label text, metric_name text, description text, unit_of_measure text, baseline_value numeric, target_value numeric, actual_value numeric, benefit_owner_id uuid, benefit_owner_display_name text, benefit_owner_email text, realization_status text, expected_realization_date date, actual_realization_date date, evidence_note text, created_by uuid, updated_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone, archived_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_access(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Access denied to project %', _project_id USING ERRCODE='42501';
  END IF;

  RETURN QUERY
  SELECT
    b.id,
    b.organization_id,
    b.workspace_id,
    b.project_id,
    b.benefit_type,
    CASE WHEN b.custom_benefit_type_label IS NULL THEN NULL
         ELSE public.btpm_decrypt(b.custom_benefit_type_label, b.organization_id) END,
    CASE WHEN b.metric_name IS NULL THEN NULL
         ELSE public.btpm_decrypt(b.metric_name, b.organization_id) END,
    CASE WHEN b.description IS NULL THEN NULL
         ELSE public.btpm_decrypt(b.description, b.organization_id) END,
    b.unit_of_measure,
    b.baseline_value,
    b.target_value,
    b.actual_value,
    b.benefit_owner_id,
    CASE WHEN p.display_name IS NULL THEN NULL
         ELSE public.btpm_decrypt(p.display_name, b.organization_id) END,
    p.email,
    b.realization_status,
    b.expected_realization_date,
    b.actual_realization_date,
    CASE WHEN b.evidence_note IS NULL THEN NULL
         ELSE public.btpm_decrypt(b.evidence_note, b.organization_id) END,
    b.created_by,
    b.updated_by,
    b.created_at,
    b.updated_at,
    b.archived_at
  FROM public.project_benefits b
  LEFT JOIN public.profiles p ON p.id = b.benefit_owner_id
  WHERE b.project_id = _project_id
    AND (_include_archived OR b.archived_at IS NULL)
  ORDER BY b.archived_at IS NOT NULL, b.created_at DESC;
END;
$$;


--
-- Name: list_decrypted_project_phases(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_project_phases(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_proj public.projects%ROWTYPE;
  v_result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;

  IF public.is_user_org_member(v_caller, v_proj.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project_or_demo(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', ph.id, 'organization_id', ph.organization_id,
    'workspace_id', ph.workspace_id, 'project_id', ph.project_id,
    'name', ph.name,
    'description', public.btpm_decrypt(ph.description, ph.organization_id),
    'status', ph.status, 'sort_order', ph.sort_order,
    'start_date', ph.start_date, 'target_end_date', ph.target_end_date,
    'actual_start_date', ph.actual_start_date,
    'actual_end_date', ph.actual_end_date,
    'baseline_start_date', ph.baseline_start_date,
    'baseline_end_date', ph.baseline_end_date,
    'added_after_baseline', ph.added_after_baseline,
    'is_archived', ph.is_archived,
    'created_at', ph.created_at, 'updated_at', ph.updated_at,
    'created_by', ph.created_by) ORDER BY ph.sort_order), '[]'::jsonb)
  INTO v_result FROM public.phases ph WHERE ph.project_id = _project_id;
  RETURN v_result;
END; $$;


--
-- Name: list_decrypted_project_tasks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_project_tasks(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_proj public.projects%ROWTYPE;
  v_result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;

  IF public.is_user_org_member(v_caller, v_proj.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project_or_demo(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH stakeholder_rows AS (
    SELECT
      tsr.task_id,
      tsr.role_type,
      s.id AS stakeholder_id,
      s.stakeholder_type,
      s.role_label,
      (s.removed_at IS NOT NULL) AS is_removed,
      COALESCE(
        s.external_name,
        CASE
          WHEN p.organization_id IS NOT NULL
            THEN public.btpm_decrypt(p.display_name, p.organization_id)
          ELSE p.display_name
        END,
        'Member'
      )::text AS display_name
    FROM public.task_stakeholder_roles tsr
    JOIN public.tasks t ON t.id = tsr.task_id
    JOIN public.project_stakeholders s
      ON s.id = tsr.project_stakeholder_id
     AND s.project_id = t.project_id
     AND s.workspace_id = t.workspace_id
     AND s.organization_id = t.organization_id
    LEFT JOIN public.profiles p ON p.id = s.user_id
    WHERE t.project_id = _project_id
  ),
  requesters AS (
    SELECT task_id,
      jsonb_build_object(
        'id', stakeholder_id,
        'display_name', display_name,
        'stakeholder_type', stakeholder_type,
        'role_label', role_label,
        'is_removed', is_removed
      ) AS obj
    FROM stakeholder_rows
    WHERE role_type = 'requester'
  ),
  executors AS (
    SELECT task_id,
      COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', stakeholder_id,
            'display_name', display_name,
            'stakeholder_type', stakeholder_type,
            'role_label', role_label,
            'is_removed', is_removed
          )
          ORDER BY display_name ASC, stakeholder_id ASC
        ),
        '[]'::jsonb
      ) AS arr
    FROM stakeholder_rows
    WHERE role_type = 'executor'
    GROUP BY task_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', t.id, 'organization_id', t.organization_id,
    'workspace_id', t.workspace_id, 'project_id', t.project_id, 'phase_id', t.phase_id,
    'name', t.name,
    'description', public.btpm_decrypt(t.description, t.organization_id),
    'status', t.status, 'priority', t.priority, 'task_type', t.task_type,
    'sort_order', t.sort_order,
    'start_date', t.start_date, 'due_date', t.due_date,
    'actual_start_date', t.actual_start_date,
    'actual_end_date', t.actual_end_date,
    'baseline_start_date', t.baseline_start_date,
    'baseline_end_date', t.baseline_end_date,
    'added_after_baseline', t.added_after_baseline,
    'estimated_hours', t.estimated_hours, 'owner_id', t.owner_id,
    'workflow_state_id', t.workflow_state_id,
    'backlog_item_id', t.backlog_item_id,
    'is_adoption_related', COALESCE(t.is_adoption_related, false),
    'adoption_initiative_id', t.adoption_initiative_id,
    'is_archived', t.is_archived,
    'created_at', t.created_at, 'updated_at', t.updated_at,
    'created_by', t.created_by,
    'requested_by_stakeholder', r.obj,
    'executed_by_stakeholders', COALESCE(e.arr, '[]'::jsonb)
  ) ORDER BY t.sort_order), '[]'::jsonb)
  INTO v_result
  FROM public.tasks t
  LEFT JOIN requesters r ON r.task_id = t.id
  LEFT JOIN executors  e ON e.task_id = t.id
  WHERE t.project_id = _project_id;

  RETURN v_result;
END;
$$;


--
-- Name: list_decrypted_project_team(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_project_team(_project_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_proj public.projects%ROWTYPE;
  v_result json;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RETURN '[]'::json; END IF;

  IF NOT public.is_user_org_member(v_caller, v_proj.organization_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF NOT public.can_read_project_or_demo(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT COALESCE(json_agg(json_build_object(
    'id', ptm.id, 'project_id', ptm.project_id,
    'workspace_id', ptm.workspace_id, 'organization_id', ptm.organization_id,
    'user_id', ptm.user_id,
    'role_label', public.btpm_decrypt(ptm.role_label, ptm.organization_id),
    'canonical_role_key', ptm.canonical_role_key,
    'created_at', ptm.created_at, 'updated_at', ptm.updated_at,
    'display_name', public.btpm_decrypt(p.display_name, p.organization_id),
    'email', CASE
      WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
        THEN public.btpm_decrypt(p.email, p.organization_id)
      ELSE p.email
    END,
    'avatar_url', CASE
      WHEN p.organization_id IS NOT NULL AND p.avatar_url IS NOT NULL
        THEN public.btpm_decrypt(p.avatar_url, p.organization_id)
      ELSE p.avatar_url
    END)), '[]'::json)
  INTO v_result
  FROM public.project_team_members ptm
  LEFT JOIN public.profiles p ON p.id = ptm.user_id
  -- C18-C1 read-side containment: structurally in-scope rows whose user is a
  -- canonical member of the authoritative Project Organization.
  WHERE ptm.project_id = _project_id
    AND ptm.organization_id = v_proj.organization_id
    AND ptm.workspace_id = v_proj.workspace_id
    AND public.is_user_org_member(ptm.user_id, v_proj.organization_id) IS TRUE;
  RETURN v_result;
END;
$$;


--
-- Name: list_decrypted_risks(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_risks(_target_id uuid, _target_type text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_id uuid; _ws_id uuid; _result json;
BEGIN
  SELECT DISTINCT r.organization_id, r.workspace_id INTO _org_id, _ws_id
  FROM risks r WHERE r.target_id = _target_id AND r.target_type = _target_type LIMIT 1;

  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;
  IF NOT (is_workspace_member(auth.uid(), _ws_id) OR is_org_admin(auth.uid(), _org_id)) THEN
    RETURN '[]'::json;
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT r.id,
           btpm_decrypt(r.title, r.organization_id) as title,
           r.status, r.likelihood, r.impact,
           btpm_decrypt(r.description, r.organization_id) as description,
           btpm_decrypt(r.mitigation_plan, r.organization_id) as mitigation_plan,
           r.reported_by, r.target_type, r.target_id,
           r.organization_id, r.workspace_id,
           r.created_at, r.updated_at
    FROM risks r
    WHERE r.target_id = _target_id AND r.target_type = _target_type
    ORDER BY r.created_at DESC
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: list_decrypted_sprints(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_decrypted_sprints(_project_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _result json;
  _org_id uuid;
  v_client_id text;
  v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.projects WHERE id = _project_id;
  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;

  IF public.is_user_org_member(v_caller, _org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT s.id, s.organization_id, s.workspace_id, s.project_id, s.name,
      CASE WHEN s.goal IS NOT NULL AND s.goal != ''
        THEN btpm_decrypt(s.goal, s.organization_id) ELSE s.goal END AS goal,
      s.status, s.start_date, s.end_date, s.sort_order, s.is_archived, s.created_by, s.created_at, s.updated_at
    FROM public.sprints s WHERE s.project_id = _project_id
    ORDER BY s.sort_order, s.created_at) t;
  RETURN COALESCE(_result, '[]'::json);
END;
$$;


