--

CREATE FUNCTION public.list_governance_record_evidence_files(_record_id uuid, _include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _row governance_records%ROWTYPE;
  _result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_read(_row.project_id);
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Evidence files are only available for decision cases' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', f.id,
    'organization_id', f.organization_id,
    'workspace_id', f.workspace_id,
    'project_id', f.project_id,
    'governance_record_id', f.governance_record_id,
    'source_system', f.source_system,
    'site_id', btpm_decrypt(f.site_id, f.organization_id),
    'drive_id', btpm_decrypt(f.drive_id, f.organization_id),
    'item_id', btpm_decrypt(f.item_id, f.organization_id),
    'item_reference_hash', f.item_reference_hash,
    'file_name', btpm_decrypt(f.file_name, f.organization_id),
    'file_extension', CASE WHEN f.file_extension IS NULL THEN NULL ELSE btpm_decrypt(f.file_extension, f.organization_id) END,
    'mime_type', CASE WHEN f.mime_type IS NULL THEN NULL ELSE btpm_decrypt(f.mime_type, f.organization_id) END,
    'size_bytes', f.size_bytes,
    'etag', CASE WHEN f.etag IS NULL THEN NULL ELSE btpm_decrypt(f.etag, f.organization_id) END,
    'ctag', CASE WHEN f.ctag IS NULL THEN NULL ELSE btpm_decrypt(f.ctag, f.organization_id) END,
    'sharepoint_last_modified_at', f.sharepoint_last_modified_at,
    'sharepoint_created_at', f.sharepoint_created_at,
    'parent_path', CASE WHEN f.parent_path IS NULL THEN NULL ELSE btpm_decrypt(f.parent_path, f.organization_id) END,
    'sharepoint_web_url', CASE WHEN f.sharepoint_web_url IS NULL THEN NULL ELSE btpm_decrypt(f.sharepoint_web_url, f.organization_id) END,
    'evidence_title', btpm_decrypt(f.evidence_title, f.organization_id),
    'evidence_summary', CASE WHEN f.evidence_summary IS NULL THEN NULL ELSE btpm_decrypt(f.evidence_summary, f.organization_id) END,
    'evidence_date', f.evidence_date,
    'relevance_level', f.relevance_level,
    'included_in_package', f.included_in_package,
    'selected_at', f.selected_at,
    'selected_by', f.selected_by,
    'created_at', f.created_at,
    'created_by', f.created_by,
    'updated_at', f.updated_at,
    'updated_by', f.updated_by,
    'archived_at', f.archived_at,
    'archived_by', f.archived_by
  ) ORDER BY
    (f.archived_at IS NOT NULL) ASC,
    CASE f.relevance_level WHEN 'high' THEN 0 WHEN 'medium' THEN 1 WHEN 'low' THEN 2 ELSE 3 END ASC,
    f.selected_at DESC
  ), '[]'::jsonb) INTO _result
  FROM governance_record_evidence_files f
  WHERE f.governance_record_id = _record_id
    AND (_include_archived OR f.archived_at IS NULL);

  RETURN _result;
END; $$;


