--
-- Name: list_knowledge_article_ai_metadata_for_visible_articles(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_knowledge_article_ai_metadata_for_visible_articles(_article_ids uuid[]) RETURNS TABLE(article_id uuid, ai_flow text, feature_area text[], route_patterns text[], user_intents text[], audience text[], synonyms text[], freshness_label text, related_feature_flags text[], question_examples text[], answer_rules text[], forbidden_claims text[], workflow_metadata jsonb, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := public.get_user_org_id(auth.uid());
  v_is_admin boolean := FALSE;
BEGIN
  IF v_uid IS NULL OR v_org IS NULL THEN RETURN; END IF;
  v_is_admin := public.is_org_admin(v_uid, v_org);
  RETURN QUERY
  SELECT
    m.article_id, m.ai_flow, m.feature_area, m.route_patterns, m.user_intents, m.audience,
    m.synonyms, m.freshness_label, m.related_feature_flags,
    public._kc_ai_meta_decrypt_array(m.question_examples_protected, m.organization_id),
    public._kc_ai_meta_decrypt_array(m.answer_rules_protected,      m.organization_id),
    public._kc_ai_meta_decrypt_array(m.forbidden_claims_protected,  m.organization_id),
    public._kc_ai_meta_decrypt_jsonb(m.workflow_metadata_protected, m.organization_id),
    m.updated_at
  FROM public.knowledge_article_ai_metadata m
  JOIN public.knowledge_articles a ON a.id = m.article_id
  WHERE a.organization_id = v_org
    AND m.article_id = ANY(_article_ids)
    AND (
      v_is_admin
      OR (a.status = 'published' AND (
        a.visibility = 'all_users'
        OR (a.visibility = 'workspace_scoped' AND a.workspace_id IS NOT NULL
            AND public.is_workspace_member(v_uid, a.workspace_id))
      ))
    );
END;
$$;


--
-- Name: list_my_organizations_for_tenant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_organizations_for_tenant(_tenant_id uuid) RETURNS TABLE(organization_id uuid, slug text, name text, role public.organization_role, organization_kind public.organization_kind, environment_role public.environment_role)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.id, o.slug, o.name, om.role, o.organization_kind, o.environment_role
  FROM public.organization_memberships om
  JOIN public.organizations o ON o.id = om.organization_id
  JOIN public.tenant_memberships tm ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
  WHERE om.user_id = auth.uid()
    AND om.tenant_id = _tenant_id
    AND om.status = 'active'
    AND tm.status = 'active'
$$;


--
-- Name: list_my_tenants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_tenants() RETURNS TABLE(tenant_id uuid, slug text, name text, role public.tenant_role)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.id, t.slug, t.name, tm.role
  FROM public.tenant_memberships tm
  JOIN public.tenants t ON t.id = tm.tenant_id
  WHERE tm.user_id = auth.uid()
    AND tm.status = 'active'
    AND t.status = 'active'
  ORDER BY t.name;
$$;


--
-- Name: list_my_workspaces_for_organization(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_workspaces_for_organization(_organization_id uuid) RETURNS TABLE(workspace_id uuid, name text, is_active boolean, is_archived boolean, is_demo boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT w.id, w.name, w.is_active, w.is_archived, w.is_demo
  FROM public.workspaces w
  INNER JOIN public.workspace_memberships wm
    ON wm.workspace_id = w.id AND wm.user_id = auth.uid()
  WHERE w.organization_id = _organization_id
    AND COALESCE(w.is_active, true) = true
    AND COALESCE(w.is_archived, false) = false
  ORDER BY w.name;
$$;


--
-- Name: list_project_activity_events(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_activity_events(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_proj public.projects%ROWTYPE;
  v_result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;

  IF public.is_user_org_member(v_caller, v_proj.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_project_access(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH scope AS (
    SELECT 'project'::text AS t, v_proj.id AS id
    UNION ALL SELECT 'phase'::text, ph.id FROM public.phases ph WHERE ph.project_id = _project_id
    UNION ALL SELECT 'task'::text,  tk.id FROM public.tasks  tk WHERE tk.project_id = _project_id
  ),
  derived_targets AS (
    SELECT 'blocker'::text AS t, b.id FROM public.blockers b
      JOIN scope s ON s.t = b.target_type AND s.id = b.target_id
    UNION ALL SELECT 'risk'::text, r.id FROM public.risks r
      JOIN scope s ON s.t = r.target_type AND s.id = r.target_id
    UNION ALL SELECT 'kpi_definition'::text, k.id FROM public.kpi_definitions k
      JOIN scope s ON s.t = k.target_type AND s.id = k.target_id
  ),
  governance_targets AS (
    SELECT 'governance_cadence'::text AS t, gc.id
      FROM public.governance_cadences gc WHERE gc.project_id = _project_id
    UNION ALL
    SELECT 'governance_record'::text, gr.id
      FROM public.governance_records gr WHERE gr.project_id = _project_id
  ),
  all_targets AS (
    SELECT * FROM scope
    UNION ALL SELECT * FROM derived_targets
    UNION ALL SELECT * FROM governance_targets
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', ae.id,
    'event_type', ae.event_type,
    'target_type', ae.target_type,
    'target_id', ae.target_id,
    'actor_id', ae.actor_id,
    'organization_id', ae.organization_id,
    'workspace_id', ae.workspace_id,
    'created_at', ae.created_at,
    'metadata', btpm_decrypt(ae.metadata, ae.organization_id))
    ORDER BY ae.created_at DESC), '[]'::jsonb) INTO v_result
  FROM public.activity_events ae
  JOIN all_targets at ON at.t = ae.target_type AND at.id = ae.target_id
  WHERE ae.organization_id = v_proj.organization_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: list_project_adoption_reporting_summaries(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_adoption_reporting_summaries(_workspace_id uuid, _project_ids uuid[] DEFAULT NULL::uuid[]) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid    uuid := auth.uid();
  _org_id uuid;
  _today  date := (now() AT TIME ZONE 'UTC')::date;
  _result json;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Workspace not found' USING ERRCODE = '22023';
  END IF;

  IF NOT (public.is_workspace_member(_uid, _workspace_id) OR public.is_org_admin(_uid, _org_id)) THEN
    RAISE EXCEPTION 'Forbidden: not a workspace member' USING ERRCODE = '42501';
  END IF;

  WITH
  plan AS (
    SELECT
      ap.id              AS adoption_plan_id,
      ap.project_id,
      ap.workspace_id,
      ap.organization_id,
      ap.readiness_status,
      ap.enabled,
      ap.created_from_template
    FROM public.adoption_plans ap
    JOIN public.projects p
      ON p.id = ap.project_id
     AND p.is_archived = false
    WHERE ap.workspace_id = _workspace_id
      AND ap.is_archived = false
      AND (_project_ids IS NULL OR ap.project_id = ANY(_project_ids))
      AND public.has_project_access(_uid, ap.project_id)
  ),
  init_agg AS (
    SELECT
      i.adoption_plan_id,
      COUNT(*) FILTER (WHERE i.is_archived = false)                                         AS initiative_count,
      COUNT(*) FILTER (WHERE i.is_archived = false AND i.status = 'active')                 AS active_initiative_count,
      COUNT(*) FILTER (WHERE i.is_archived = false AND i.status = 'at_risk')                AS at_risk_initiative_count,
      COUNT(*) FILTER (WHERE i.is_archived = false AND i.status = 'completed')              AS completed_initiative_count
    FROM public.adoption_initiatives i
    JOIN plan ON plan.adoption_plan_id = i.adoption_plan_id
    GROUP BY i.adoption_plan_id
  ),
  task_agg AS (
    SELECT
      t.project_id,
      COUNT(*)                                                                              AS adoption_task_count,
      COUNT(*) FILTER (WHERE t.status IN ('planned','active','on_hold'))                    AS adoption_task_open_count,
      COUNT(*) FILTER (WHERE t.status = 'completed')                                        AS adoption_task_completed_count,
      COUNT(*) FILTER (
        WHERE t.status IN ('planned','active')
          AND t.due_date IS NOT NULL
          AND t.due_date < _today
      )                                                                                     AS adoption_task_overdue_count
    FROM public.tasks t
    JOIN plan ON plan.project_id = t.project_id
    WHERE t.is_archived = false
      AND (t.is_adoption_related = true OR t.adoption_initiative_id IS NOT NULL)
    GROUP BY t.project_id
  ),
  link_agg AS (
    SELECT
      l.adoption_plan_id,
      COUNT(*) FILTER (WHERE l.object_type = 'risk')    AS adoption_risk_count,
      COUNT(*) FILTER (WHERE l.object_type = 'blocker') AS adoption_blocker_count,
      COUNT(*) FILTER (WHERE l.object_type = 'kpi')     AS adoption_kpi_count
    FROM public.adoption_object_links l
    JOIN plan ON plan.adoption_plan_id = l.adoption_plan_id
    GROUP BY l.adoption_plan_id
  ),
  combined AS (
    SELECT
      plan.project_id,
      plan.workspace_id,
      plan.organization_id,
      plan.adoption_plan_id,
      plan.readiness_status,
      plan.enabled,
      plan.created_from_template,
      COALESCE(init_agg.initiative_count, 0)             AS initiative_count,
      COALESCE(init_agg.active_initiative_count, 0)      AS active_initiative_count,
      COALESCE(init_agg.at_risk_initiative_count, 0)     AS at_risk_initiative_count,
      COALESCE(init_agg.completed_initiative_count, 0)   AS completed_initiative_count,
      COALESCE(task_agg.adoption_task_count, 0)          AS adoption_task_count,
      COALESCE(task_agg.adoption_task_open_count, 0)     AS adoption_task_open_count,
      COALESCE(task_agg.adoption_task_completed_count,0) AS adoption_task_completed_count,
      COALESCE(task_agg.adoption_task_overdue_count, 0)  AS adoption_task_overdue_count,
      COALESCE(link_agg.adoption_risk_count, 0)          AS adoption_risk_count,
      COALESCE(link_agg.adoption_blocker_count, 0)       AS adoption_blocker_count,
      COALESCE(link_agg.adoption_kpi_count, 0)           AS adoption_kpi_count
    FROM plan
    LEFT JOIN init_agg ON init_agg.adoption_plan_id = plan.adoption_plan_id
    LEFT JOIN task_agg ON task_agg.project_id      = plan.project_id
    LEFT JOIN link_agg ON link_agg.adoption_plan_id = plan.adoption_plan_id
  ),
  derived AS (
    SELECT
      c.*,
      CASE
        WHEN c.readiness_status = 'at_risk' THEN 'at_risk'
        WHEN c.adoption_task_overdue_count > 0 THEN 'at_risk'
        WHEN c.at_risk_initiative_count > 0 THEN 'attention'
        WHEN c.readiness_status IN ('ready','reinforced') THEN 'ready'
        WHEN c.adoption_task_open_count > 0 OR c.active_initiative_count > 0 THEN 'on_track'
        ELSE 'preparing'
      END AS adoption_signal
    FROM combined c
  )
  SELECT COALESCE(json_agg(row_to_json(x)), '[]'::json)
  INTO _result
  FROM (
    SELECT
      d.project_id,
      d.workspace_id,
      d.organization_id,
      d.adoption_plan_id,
      true AS has_adoption_plan,
      d.readiness_status::text AS readiness_status,
      d.enabled,
      d.created_from_template,
      d.initiative_count,
      d.active_initiative_count,
      d.at_risk_initiative_count,
      d.completed_initiative_count,
      d.adoption_task_count,
      d.adoption_task_open_count,
      d.adoption_task_completed_count,
      d.adoption_task_overdue_count,
      d.adoption_risk_count,
      d.adoption_blocker_count,
      d.adoption_kpi_count,
      d.adoption_signal,
      CASE d.adoption_signal
        WHEN 'ready'     THEN 'Adoption ready'
        WHEN 'on_track'  THEN 'Adoption on track'
        WHEN 'attention' THEN 'Adoption needs attention'
        WHEN 'at_risk'   THEN 'Adoption at risk'
        WHEN 'preparing' THEN 'Adoption preparing'
        ELSE 'Adoption preparing'
      END AS adoption_label,
      (
        SELECT array_remove(ARRAY[
          CASE WHEN d.adoption_task_overdue_count > 0
            THEN d.adoption_task_overdue_count || ' adoption task' ||
                 CASE WHEN d.adoption_task_overdue_count = 1 THEN '' ELSE 's' END || ' overdue'
          END,
          CASE WHEN d.adoption_task_open_count > 0
            THEN d.adoption_task_open_count || ' adoption task' ||
                 CASE WHEN d.adoption_task_open_count = 1 THEN '' ELSE 's' END || ' open'
          END,
          CASE WHEN d.at_risk_initiative_count > 0
            THEN d.at_risk_initiative_count || ' initiative' ||
                 CASE WHEN d.at_risk_initiative_count = 1 THEN '' ELSE 's' END || ' at risk'
          END,
          CASE WHEN d.adoption_risk_count > 0
            THEN d.adoption_risk_count || ' adoption risk' ||
                 CASE WHEN d.adoption_risk_count = 1 THEN '' ELSE 's' END || ' linked'
          END,
          CASE WHEN d.adoption_blocker_count > 0
            THEN d.adoption_blocker_count || ' adoption blocker' ||
                 CASE WHEN d.adoption_blocker_count = 1 THEN '' ELSE 's' END || ' linked'
          END,
          CASE WHEN d.adoption_kpi_count > 0
            THEN d.adoption_kpi_count || ' adoption KPI' ||
                 CASE WHEN d.adoption_kpi_count = 1 THEN '' ELSE 's' END || ' linked'
          END,
          'Readiness: ' || initcap(replace(d.readiness_status::text, '_', ' '))
        ], NULL)
      ) AS reason_lines
    FROM derived d
    ORDER BY d.project_id
  ) AS x;

  RETURN COALESCE(_result, '[]'::json);
END
$$;


--
-- Name: list_project_adoption_substrate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_adoption_substrate(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _uid uuid := auth.uid(); _org uuid; _plan record; _result jsonb;
        _initiatives jsonb; _links jsonb; _task_counts jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT public.has_project_access(_uid, _project_id) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT * INTO _plan FROM public.adoption_plans
   WHERE project_id = _project_id AND is_archived = false LIMIT 1;

  IF _plan.id IS NULL THEN
    RETURN jsonb_build_object(
      'adoption_plan', NULL,
      'initiatives', '[]'::jsonb,
      'linked_task_counts', '{}'::jsonb,
      'linked_object_counts', '{}'::jsonb,
      'linked_objects', '[]'::jsonb
    );
  END IF;
  _org := _plan.organization_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', i.id,
    'adoption_plan_id', i.adoption_plan_id,
    'project_id', i.project_id,
    'name', public.btpm_decrypt(i.name, i.organization_id),
    'summary', public.btpm_decrypt(i.summary, i.organization_id),
    'readiness_area', i.readiness_area,
    'owner_id', i.owner_id,
    'status', i.status,
    'priority', i.priority,
    'target_date', i.target_date,
    'sort_order', i.sort_order,
    'is_archived', i.is_archived,
    'created_at', i.created_at,
    'updated_at', i.updated_at
  ) ORDER BY i.sort_order, i.created_at), '[]'::jsonb)
  INTO _initiatives
  FROM public.adoption_initiatives i
  WHERE i.adoption_plan_id = _plan.id AND i.is_archived = false;

  SELECT COALESCE(jsonb_object_agg(adoption_initiative_id::text, cnt), '{}'::jsonb)
  INTO _task_counts
  FROM (
    SELECT adoption_initiative_id, count(*) AS cnt
    FROM public.tasks
    WHERE project_id = _project_id AND adoption_initiative_id IS NOT NULL
    GROUP BY adoption_initiative_id
  ) t;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'adoption_initiative_id', l.adoption_initiative_id,
    'object_type', l.object_type,
    'object_id', l.object_id,
    'created_at', l.created_at
  )), '[]'::jsonb)
  INTO _links
  FROM public.adoption_object_links l
  WHERE l.adoption_plan_id = _plan.id;

  _result := jsonb_build_object(
    'adoption_plan', jsonb_build_object(
      'id', _plan.id,
      'project_id', _plan.project_id,
      'organization_id', _plan.organization_id,
      'workspace_id', _plan.workspace_id,
      'objective', public.btpm_decrypt(_plan.objective, _org),
      'impacted_audience_summary', public.btpm_decrypt(_plan.impacted_audience_summary, _org),
      'approach_summary', public.btpm_decrypt(_plan.approach_summary, _org),
      'adoption_owner_id', _plan.adoption_owner_id,
      'readiness_status', _plan.readiness_status,
      'enabled', _plan.enabled,
      'created_from_template', _plan.created_from_template,
      'is_archived', _plan.is_archived,
      'created_by', _plan.created_by,
      'created_at', _plan.created_at,
      'updated_at', _plan.updated_at
    ),
    'initiatives', _initiatives,
    'linked_task_counts', _task_counts,
    'linked_object_counts', (
      SELECT COALESCE(jsonb_object_agg(object_type, cnt), '{}'::jsonb)
      FROM (
        SELECT object_type, count(*) AS cnt FROM public.adoption_object_links
        WHERE adoption_plan_id = _plan.id GROUP BY object_type
      ) c
    ),
    'linked_objects', _links
  );
  RETURN _result;
END $$;


--
-- Name: list_project_all_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_all_blockers(_project_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_id uuid; _result json;
BEGIN
  SELECT organization_id INTO _org_id FROM projects WHERE id = _project_id;
  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;
  IF NOT public.can_read_project(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;
  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT b.id, b.title,
      CASE WHEN b.description IS NOT NULL AND b.description != ''
        THEN btpm_decrypt(b.description, b.organization_id) ELSE b.description END AS description,
      b.severity, b.status, b.target_id, b.target_type,
      b.organization_id, b.workspace_id,
      b.reported_by, b.resolved_by, b.resolved_at, b.created_at, b.updated_at
    FROM public.blockers b
    WHERE (b.target_type='project' AND b.target_id=_project_id)
      OR (b.target_type='phase' AND b.target_id IN (SELECT id FROM phases WHERE project_id=_project_id))
      OR (b.target_type='task'  AND b.target_id IN (SELECT id FROM tasks  WHERE project_id=_project_id))
    ORDER BY b.created_at DESC) t;
  RETURN COALESCE(_result, '[]'::json);
END; $$;


--
-- Name: list_project_all_risks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_all_risks(_project_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_id uuid; _result json;
BEGIN
  SELECT organization_id INTO _org_id FROM projects WHERE id = _project_id;
  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;
  IF NOT public.can_read_project(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;
  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT r.id, r.title,
      CASE WHEN r.description IS NOT NULL AND r.description != ''
        THEN btpm_decrypt(r.description, r.organization_id) ELSE r.description END AS description,
      CASE WHEN r.mitigation_plan IS NOT NULL AND r.mitigation_plan != ''
        THEN btpm_decrypt(r.mitigation_plan, r.organization_id) ELSE r.mitigation_plan END AS mitigation_plan,
      r.likelihood, r.impact, r.status, r.target_id, r.target_type,
      r.organization_id, r.workspace_id,
      r.reported_by, r.created_at, r.updated_at
    FROM public.risks r
    WHERE (r.target_type='project' AND r.target_id=_project_id)
      OR (r.target_type='phase' AND r.target_id IN (SELECT id FROM phases WHERE project_id=_project_id))
      OR (r.target_type='task'  AND r.target_id IN (SELECT id FROM tasks  WHERE project_id=_project_id))
    ORDER BY r.created_at DESC) t;
  RETURN COALESCE(_result, '[]'::json);
END; $$;


--
-- Name: list_project_governance_cadences(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_governance_cadences(_project_id uuid, _include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _p record; _result jsonb;
BEGIN
  _p := _gov_assert_project_read(_project_id);
  SELECT COALESCE(jsonb_agg(row_obj ORDER BY created_at DESC), '[]'::jsonb)
  INTO _result
  FROM (
    SELECT
      c.created_at,
      jsonb_build_object(
        'id', c.id,
        'organization_id', c.organization_id,
        'workspace_id', c.workspace_id,
        'project_id', c.project_id,
        'event_type', c.event_type,
        'event_name', btpm_decrypt(c.event_name, c.organization_id),
        'frequency_type', c.frequency_type,
        'owner_id', c.owner_id,
        'owner_stakeholder_id', c.owner_stakeholder_id,
        'owner_display_name', CASE
          WHEN c.owner_stakeholder_id IS NOT NULL THEN
            COALESCE(
              btpm_decrypt(sh.external_name, c.organization_id),
              btpm_decrypt(p.display_name, c.organization_id),
              p.email
            )
          WHEN c.owner_id IS NOT NULL THEN
            COALESCE(btpm_decrypt(p2.display_name, c.organization_id), p2.email)
          ELSE NULL
        END,
        'next_expected_date', c.next_expected_date,
        'expected_evidence_type', btpm_decrypt(c.expected_evidence_type, c.organization_id),
        'created_at', c.created_at,
        'created_by', c.created_by,
        'updated_at', c.updated_at,
        'updated_by', c.updated_by,
        'archived_at', c.archived_at,
        'archived_by', c.archived_by,
        'last_completed_date', stats.last_completed_date,
        'last_record_id', stats.last_record_id,
        'record_count', COALESCE(stats.record_count, 0),
        'decision_count', COALESCE(stats.decision_count, 0),
        'link_count', COALESCE(stats.link_count, 0),
        'derived_status', _gov_derive_cadence_status(c.frequency_type, c.next_expected_date, c.archived_at),
        'is_overdue', (c.archived_at IS NULL AND c.frequency_type <> 'ad_hoc'
                       AND c.next_expected_date IS NOT NULL
                       AND c.next_expected_date < CURRENT_DATE),
        'is_due_soon', (c.archived_at IS NULL AND c.frequency_type <> 'ad_hoc'
                        AND c.next_expected_date IS NOT NULL
                        AND c.next_expected_date >= CURRENT_DATE
                        AND c.next_expected_date <= CURRENT_DATE + INTERVAL '7 days')
      ) AS row_obj
    FROM governance_cadences c
    LEFT JOIN project_stakeholders sh ON sh.id = c.owner_stakeholder_id
    LEFT JOIN profiles p ON p.id = sh.user_id
    LEFT JOIN profiles p2 ON p2.id = c.owner_id
    LEFT JOIN LATERAL (
      SELECT
        MAX(r.actual_date_held) AS last_completed_date,
        (SELECT r2.id FROM governance_records r2
           WHERE r2.cadence_id = c.id AND r2.archived_at IS NULL
           ORDER BY r2.actual_date_held DESC, r2.created_at DESC LIMIT 1) AS last_record_id,
        COUNT(*) FILTER (WHERE r.archived_at IS NULL) AS record_count,
        (SELECT COUNT(*) FROM governance_record_decisions d
           JOIN governance_records gr ON gr.id = d.governance_record_id
          WHERE gr.cadence_id = c.id AND gr.archived_at IS NULL AND d.archived_at IS NULL) AS decision_count,
        (SELECT COUNT(*) FROM governance_record_links l
           JOIN governance_records gr ON gr.id = l.governance_record_id
          WHERE gr.cadence_id = c.id AND gr.archived_at IS NULL AND l.archived_at IS NULL) AS link_count
      FROM governance_records r
      WHERE r.cadence_id = c.id
    ) stats ON true
    WHERE c.project_id = _project_id
      AND (_include_archived OR c.archived_at IS NULL)
  ) sub;
  RETURN _result;
END; $$;


--
-- Name: list_project_governance_records(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_governance_records(_project_id uuid, _include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _p record; _result jsonb;
BEGIN
  _p := _gov_assert_project_read(_project_id);
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'organization_id', r.organization_id,
    'workspace_id', r.workspace_id,
    'project_id', r.project_id,
    'cadence_id', r.cadence_id,
    'cadence_event_type', c.event_type,
    'cadence_event_name', btpm_decrypt(c.event_name, c.organization_id),
    'cadence_frequency_type', c.frequency_type,
    'event_type', r.event_type,
    'event_name', btpm_decrypt(r.event_name, r.organization_id),
    'expected_date_snapshot', r.expected_date_snapshot,
    'actual_date_held', r.actual_date_held,
    'summary', btpm_decrypt(r.summary, r.organization_id),
    'decisions_summary', btpm_decrypt(r.decisions_summary, r.organization_id),
    'external_reference_url', btpm_decrypt(r.external_reference_url, r.organization_id),
    'sharepoint_evidence_reference', btpm_decrypt(r.sharepoint_evidence_reference, r.organization_id),
    'has_sharepoint_evidence', (r.sharepoint_evidence_reference IS NOT NULL),
    'record_kind', r.record_kind,
    'decision_stage', r.decision_stage,
    'decision_question', btpm_decrypt(r.decision_question, r.organization_id),
    'decision_owner_stakeholder_id', r.decision_owner_stakeholder_id,
    'target_decision_date', r.target_decision_date,
    'decision_count', COALESCE((
      SELECT COUNT(*)::int FROM governance_record_decisions d
      WHERE d.governance_record_id = r.id AND d.archived_at IS NULL), 0),
    'link_count', COALESCE((
      SELECT COUNT(*)::int FROM governance_record_links l
      WHERE l.governance_record_id = r.id AND l.archived_at IS NULL), 0),
    'created_at', r.created_at,
    'created_by', r.created_by,
    'updated_at', r.updated_at,
    'updated_by', r.updated_by,
    'archived_at', r.archived_at,
    'archived_by', r.archived_by
  ) ORDER BY r.actual_date_held DESC), '[]'::jsonb) INTO _result
  FROM governance_records r
  LEFT JOIN governance_cadences c ON c.id = r.cadence_id
  WHERE r.project_id = _project_id
    AND (_include_archived OR r.archived_at IS NULL);
  RETURN _result;
END; $$;


--
-- Name: list_project_people_presets(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_people_presets(_workspace_id uuid, _include_archived boolean DEFAULT false) RETURNS TABLE(id uuid, workspace_id uuid, organization_id uuid, name text, description text, created_by uuid, created_by_name text, created_at timestamp with time zone, updated_at timestamp with time zone, archived_at timestamp with time zone, archived_by uuid, member_count integer, team_count integer, stakeholder_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org   uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  SELECT w.organization_id INTO v_org FROM public.workspaces w WHERE w.id = _workspace_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Workspace not found';
  END IF;
  IF NOT (public.is_workspace_member(v_actor, _workspace_id) OR public.is_org_admin(v_actor, v_org)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.workspace_id,
    p.organization_id,
    public.btpm_decrypt(p.name,        p.organization_id)                                   AS name,
    public.btpm_decrypt(p.description, p.organization_id)                                   AS description,
    p.created_by,
    (SELECT COALESCE(pr.display_name, pr.email, p.created_by::text)
       FROM public.profiles pr WHERE pr.id = p.created_by)                                  AS created_by_name,
    p.created_at,
    p.updated_at,
    p.archived_at,
    p.archived_by,
    COALESCE(mc.total, 0)::int         AS member_count,
    COALESCE(mc.teams, 0)::int         AS team_count,
    COALESCE(mc.stakeholders, 0)::int  AS stakeholder_count
  FROM public.project_people_presets p
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::int AS total,
           COUNT(*) FILTER (WHERE m.member_kind = 'team_member')::int AS teams,
           COUNT(*) FILTER (WHERE m.member_kind = 'stakeholder')::int AS stakeholders
      FROM public.project_people_preset_members m
     WHERE m.preset_id = p.id
  ) mc ON true
  WHERE p.workspace_id = _workspace_id
    AND (_include_archived OR p.archived_at IS NULL)
  ORDER BY p.updated_at DESC;
END; $$;


--
-- Name: list_project_raci(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_raci(_project_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_org uuid;
  v_ws uuid;
  _result json;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT pr.organization_id, pr.workspace_id INTO v_org, v_ws
  FROM public.projects pr WHERE pr.id = _project_id;
  IF v_org IS NULL THEN RETURN '[]'::json; END IF;

  IF NOT public.is_user_org_member(v_caller, v_org) THEN
    RETURN '[]'::json;
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RETURN '[]'::json;
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result FROM (
    SELECT ra.id,
           ra.target_type,
           ra.target_id,
           ra.user_id,
           ra.stakeholder_id,
           ra.raci_role,
           ra.created_at,
           ra.updated_at,
           ra.workspace_id,
           ra.organization_id,
           COALESCE(
             ps.external_name,
             CASE WHEN psp.organization_id IS NOT NULL
                  THEN public.btpm_decrypt(psp.display_name, psp.organization_id)
                  ELSE psp.display_name END,
             CASE WHEN p.organization_id IS NOT NULL
                  THEN public.btpm_decrypt(p.display_name, p.organization_id)
                  ELSE p.display_name END,
             CASE WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
                  THEN public.btpm_decrypt(p.email, p.organization_id)
                  ELSE p.email END
           )::text AS display_name,
           ps.stakeholder_type AS stakeholder_type,
           ps.role_label AS stakeholder_role_label,
           CASE WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
                THEN public.btpm_decrypt(p.email, p.organization_id)
                ELSE p.email END AS email,
           CASE WHEN p.organization_id IS NOT NULL AND p.avatar_url IS NOT NULL
                THEN public.btpm_decrypt(p.avatar_url, p.organization_id)
                ELSE p.avatar_url END AS avatar_url
    FROM public.raci_assignments ra
    LEFT JOIN public.project_stakeholders ps
           ON ps.id = ra.stakeholder_id
          AND ps.project_id = _project_id
          AND ps.organization_id = v_org
          AND ps.workspace_id = v_ws
    LEFT JOIN public.profiles psp ON psp.id = ps.user_id
    LEFT JOIN public.profiles p ON p.id = ra.user_id
    -- C18-C1 read-side containment.
    WHERE ra.target_type = 'project'
      AND ra.target_id = _project_id
      AND ra.organization_id = v_org
      AND ra.workspace_id = v_ws
      AND (ra.stakeholder_id IS NULL OR ps.id IS NOT NULL)
      AND (ra.user_id IS NULL OR public.is_user_org_member(ra.user_id, v_org) IS TRUE)
      AND (ps.user_id IS NULL OR public.is_user_org_member(ps.user_id, v_org) IS TRUE)
    ORDER BY ra.created_at
  ) t;
  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: list_project_reporting_summaries(uuid, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_reporting_summaries(_workspace_id uuid, _project_ids uuid[] DEFAULT NULL::uuid[], _include_demo boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid       uuid := auth.uid();
  _org_id    uuid;
  _is_demo   boolean;
  _today     date := (now() AT TIME ZONE 'UTC')::date;
  _result    json;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id, is_demo
  INTO _org_id, _is_demo
  FROM public.workspaces
  WHERE id = _workspace_id;

  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Workspace not found' USING ERRCODE = '22023';
  END IF;

  IF NOT public.can_read_demo_or_member(_uid, _workspace_id) THEN
    RAISE EXCEPTION 'Forbidden: not a workspace member' USING ERRCODE = '42501';
  END IF;

  IF _is_demo AND NOT _include_demo AND _project_ids IS NULL THEN
    RETURN '[]'::json;
  END IF;

  WITH
  proj AS (
    SELECT
      p.id,
      p.workspace_id,
      p.organization_id,
      p.program_id,
      p.status,
      p.target_end_date,
      p.is_baselined,
      p.baseline_end_date
    FROM public.projects p
    WHERE p.workspace_id = _workspace_id
      AND p.is_archived = false
      AND (_project_ids IS NULL OR p.id = ANY(_project_ids))
  ),
  task_agg AS (
    SELECT
      t.project_id,
      COUNT(*) FILTER (WHERE t.status <> 'cancelled') AS task_actionable,
      COUNT(*) FILTER (WHERE t.status = 'completed') AS task_completed,
      COUNT(*) FILTER (WHERE t.status = 'cancelled') AS task_cancelled,
      COUNT(*) FILTER (WHERE t.status = 'planned') AS s_planned,
      COUNT(*) FILTER (WHERE t.status = 'active') AS s_active,
      COUNT(*) FILTER (WHERE t.status = 'on_hold') AS s_on_hold,
      COUNT(*) FILTER (WHERE t.status = 'completed') AS s_completed,
      COUNT(*) FILTER (WHERE t.status = 'cancelled') AS s_cancelled,
      COUNT(*) AS s_total,
      COUNT(*) FILTER (
        WHERE t.status IN ('planned','active')
          AND t.due_date IS NOT NULL
          AND t.due_date < _today
      ) AS behind_task_count,
      COUNT(*) FILTER (WHERE t.status <> 'cancelled' AND t.due_date IS NOT NULL) AS tasks_with_dates,
      -- Duration-weighted completion inputs (BTPM headline progress).
      -- Mirrors `duration_weighted_completion_percent` in the canonical
      -- KPI engine: inclusive day math, min 1 day, end basis = due_date
      -- with fallback to baseline_end_date. Cancelled/archived tasks
      -- excluded. If ANY actionable task lacks a usable start/end basis,
      -- we record tasks_missing_dates_actionable > 0 and the computed
      -- step falls back to task-count completion (transparent fallback).
      COUNT(*) FILTER (
        WHERE t.status <> 'cancelled'
          AND (
            t.start_date IS NULL
            OR COALESCE(t.due_date, t.baseline_end_date) IS NULL
            OR COALESCE(t.due_date, t.baseline_end_date) < t.start_date
          )
      ) AS tasks_missing_dates_actionable,
      COALESCE(SUM(
        CASE
          WHEN t.status <> 'cancelled'
            AND t.start_date IS NOT NULL
            AND COALESCE(t.due_date, t.baseline_end_date) IS NOT NULL
            AND COALESCE(t.due_date, t.baseline_end_date) >= t.start_date
          THEN GREATEST(1, (COALESCE(t.due_date, t.baseline_end_date) - t.start_date) + 1)
          ELSE 0
        END
      ), 0) AS duration_total_days,
      COALESCE(SUM(
        CASE
          WHEN t.status = 'completed'
            AND t.start_date IS NOT NULL
            AND COALESCE(t.due_date, t.baseline_end_date) IS NOT NULL
            AND COALESCE(t.due_date, t.baseline_end_date) >= t.start_date
          THEN GREATEST(1, (COALESCE(t.due_date, t.baseline_end_date) - t.start_date) + 1)
          ELSE 0
        END
      ), 0) AS duration_completed_days
    FROM public.tasks t
    JOIN proj ON proj.id = t.project_id
    WHERE t.is_archived = false
    GROUP BY t.project_id
  ),
  phase_agg AS (
    SELECT
      ph.project_id,
      COUNT(*) FILTER (WHERE ph.status <> 'cancelled') AS phase_actionable,
      COUNT(*) FILTER (WHERE ph.status = 'completed') AS phase_completed,
      COUNT(*) FILTER (
        WHERE ph.status IN ('planned','active')
          AND ph.target_end_date IS NOT NULL
          AND ph.target_end_date < _today
      ) AS behind_phase_count,
      COUNT(*) FILTER (WHERE ph.target_end_date IS NOT NULL) AS phases_with_dates
    FROM public.phases ph
    JOIN proj ON proj.id = ph.project_id
    WHERE ph.is_archived = false
    GROUP BY ph.project_id
  ),
  blocker_agg AS (
    SELECT
      _proj.id AS project_id,
      COUNT(DISTINCT b.id) FILTER (WHERE b.status IN ('open','in_progress')) AS open_blockers
    FROM proj _proj
    LEFT JOIN public.blockers b
      ON b.workspace_id = _proj.workspace_id
     AND (
          (b.target_type = 'project' AND b.target_id = _proj.id)
       OR (b.target_type = 'phase' AND b.target_id IN (SELECT id FROM public.phases WHERE project_id = _proj.id))
       OR (b.target_type = 'task' AND b.target_id IN (SELECT id FROM public.tasks WHERE project_id = _proj.id))
     )
    GROUP BY _proj.id
  ),
  risk_agg AS (
    SELECT
      _proj.id AS project_id,
      COUNT(DISTINCT r.id) FILTER (
        WHERE r.status IN ('open','under_mitigation','identified','mitigating')
          AND r.impact IN ('high','critical')
      ) AS active_high_risks,
      COUNT(DISTINCT r.id) FILTER (WHERE r.status = 'realized') AS realized_risks
    FROM proj _proj
    LEFT JOIN public.risks r
      ON r.workspace_id = _proj.workspace_id
     AND (
          (r.target_type = 'project' AND r.target_id = _proj.id)
       OR (r.target_type = 'phase' AND r.target_id IN (SELECT id FROM public.phases WHERE project_id = _proj.id))
       OR (r.target_type = 'task' AND r.target_id IN (SELECT id FROM public.tasks WHERE project_id = _proj.id))
     )
    GROUP BY _proj.id
  ),
  derived AS (
    SELECT
      proj.id AS project_id,
      proj.workspace_id,
      proj.program_id,
      proj.status AS project_status,
      proj.target_end_date,
      proj.is_baselined,
      proj.baseline_end_date,
      COALESCE(ta.task_actionable, 0) AS task_actionable,
      COALESCE(ta.task_completed, 0) AS task_completed,
      COALESCE(ta.task_cancelled, 0) AS task_cancelled,
      COALESCE(ta.s_planned, 0) AS s_planned,
      COALESCE(ta.s_active, 0) AS s_active,
      COALESCE(ta.s_on_hold, 0) AS s_on_hold,
      COALESCE(ta.s_completed, 0) AS s_completed,
      COALESCE(ta.s_cancelled, 0) AS s_cancelled,
      COALESCE(ta.s_total, 0) AS s_total,
      COALESCE(ta.behind_task_count, 0) AS behind_task_count,
      COALESCE(ta.tasks_with_dates, 0) AS tasks_with_dates,
      COALESCE(ta.tasks_missing_dates_actionable, 0) AS tasks_missing_dates_actionable,
      COALESCE(ta.duration_total_days, 0) AS duration_total_days,
      COALESCE(ta.duration_completed_days, 0) AS duration_completed_days,
      COALESCE(pa.phase_actionable, 0) AS phase_actionable,
      COALESCE(pa.phase_completed, 0) AS phase_completed,
      COALESCE(pa.behind_phase_count, 0) AS behind_phase_count,
      COALESCE(pa.phases_with_dates, 0) AS phases_with_dates,
      COALESCE(ba.open_blockers, 0) AS open_blockers,
      COALESCE(ra.active_high_risks, 0) AS active_high_risks,
      COALESCE(ra.realized_risks, 0) AS realized_risks
    FROM proj
    LEFT JOIN task_agg ta ON ta.project_id = proj.id
    LEFT JOIN phase_agg pa ON pa.project_id = proj.id
    LEFT JOIN blocker_agg ba ON ba.project_id = proj.id
    LEFT JOIN risk_agg ra ON ra.project_id = proj.id
  ),
  computed AS (
    SELECT
      d.*,
      -- Headline project progress (BTPM rule): duration-weighted
      -- completion when every actionable task has a usable date basis,
      -- with transparent fallback to task-count completion otherwise.
      CASE
        WHEN d.task_actionable = 0 THEN 0
        WHEN d.tasks_missing_dates_actionable = 0 AND d.duration_total_days > 0
          THEN ROUND((d.duration_completed_days::numeric / d.duration_total_days::numeric) * 100)::int
        ELSE ROUND((d.task_completed::numeric / d.task_actionable::numeric) * 100)::int
      END AS completion_percent,
      CASE
        WHEN d.task_actionable = 0 THEN 'none'
        WHEN d.tasks_missing_dates_actionable = 0 AND d.duration_total_days > 0 THEN 'duration'
        ELSE 'task_count'
      END AS completion_basis,
      (d.target_end_date IS NOT NULL OR d.phases_with_dates > 0 OR d.tasks_with_dates > 0) AS has_schedule_basis,
      (d.phase_actionable > 0 AND d.phase_actionable = d.phase_completed) AS all_phases_complete,
      (d.target_end_date IS NOT NULL AND d.target_end_date < _today) AS project_target_overdue,
      CASE
        WHEN d.is_baselined AND d.baseline_end_date IS NOT NULL AND d.target_end_date IS NOT NULL
          THEN (d.target_end_date - d.baseline_end_date)
        ELSE NULL
      END AS baseline_slip_days
    FROM derived d
  ),
  scored AS (
    SELECT
      c.*,
      CASE
        WHEN c.all_phases_complete THEN 'complete'
        WHEN NOT c.has_schedule_basis THEN 'no_schedule_basis'
        WHEN c.project_target_overdue OR c.behind_phase_count > 0 OR c.behind_task_count > 0 THEN 'behind_schedule'
        ELSE 'on_track'
      END AS schedule_signal,
      (
          (CASE WHEN c.behind_task_count >= 3 THEN 2 WHEN c.behind_task_count >= 1 THEN 1 ELSE 0 END)
        + (CASE WHEN c.behind_phase_count >= 2 THEN 2 WHEN c.behind_phase_count >= 1 THEN 1 ELSE 0 END)
        + (CASE WHEN c.project_target_overdue AND NOT c.all_phases_complete THEN 1 ELSE 0 END)
        + (CASE WHEN c.open_blockers >= 2 THEN 2 WHEN c.open_blockers >= 1 THEN 1 ELSE 0 END)
        + (CASE WHEN c.active_high_risks >= 2 THEN 2 WHEN c.active_high_risks >= 1 THEN 1 ELSE 0 END)
        + (CASE WHEN c.realized_risks > 0 THEN 2 ELSE 0 END)
      ) AS health_score
    FROM computed c
  )
  SELECT json_agg(row_to_json(out_row) ORDER BY out_row.project_id)
  INTO _result
  FROM (
    SELECT
      s.project_id,
      s.workspace_id,
      s.program_id,
      s.completion_percent,
      s.completion_basis,
      s.s_total AS task_total_count,
      s.task_completed AS task_completed_count,
      s.task_cancelled AS task_cancelled_count,
      json_build_object(
        'planned', s.s_planned,
        'active', s.s_active,
        'on_hold', s.s_on_hold,
        'completed', s.s_completed,
        'cancelled', s.s_cancelled,
        'total', s.s_total
      ) AS status_counts,
      s.schedule_signal,
      (
        SELECT COALESCE(json_agg(code), '[]'::json)
        FROM (
          SELECT 'all_phases_complete' AS code WHERE s.all_phases_complete
          UNION ALL SELECT 'no_schedule_basis' WHERE NOT s.has_schedule_basis
          UNION ALL SELECT 'project_target_overdue' WHERE s.project_target_overdue AND NOT s.all_phases_complete
          UNION ALL SELECT 'behind_phases' WHERE s.behind_phase_count > 0 AND NOT s.all_phases_complete
          UNION ALL SELECT 'behind_tasks' WHERE s.behind_task_count > 0 AND NOT s.all_phases_complete
          UNION ALL SELECT 'baseline_slip' WHERE s.baseline_slip_days IS NOT NULL AND s.baseline_slip_days > 0
        ) x
      ) AS schedule_reason_codes,
      (
        SELECT COALESCE(json_agg(line), '[]'::json)
        FROM (
          SELECT 'All phases complete' AS line WHERE s.all_phases_complete
          UNION ALL SELECT 'No schedule basis available' WHERE NOT s.has_schedule_basis
          UNION ALL SELECT 'Project target end date has passed' WHERE s.project_target_overdue AND NOT s.all_phases_complete
          UNION ALL SELECT (s.behind_phase_count || ' phase' || CASE WHEN s.behind_phase_count = 1 THEN '' ELSE 's' END || ' overdue') WHERE s.behind_phase_count > 0 AND NOT s.all_phases_complete
          UNION ALL SELECT (s.behind_task_count || ' task' || CASE WHEN s.behind_task_count = 1 THEN '' ELSE 's' END || ' overdue') WHERE s.behind_task_count > 0 AND NOT s.all_phases_complete
          UNION ALL SELECT ('Baseline slip: +' || s.baseline_slip_days || ' day' || CASE WHEN s.baseline_slip_days = 1 THEN '' ELSE 's' END) WHERE s.baseline_slip_days IS NOT NULL AND s.baseline_slip_days > 0
        ) x
      ) AS schedule_reason_lines,
      s.behind_task_count,
      s.behind_phase_count,
      s.has_schedule_basis,
      s.health_score,
      CASE
        WHEN s.health_score = 0 THEN 'green'
        WHEN s.health_score <= 2 THEN 'amber'
        ELSE 'red'
      END AS health_rag,
      CASE
        WHEN s.health_score = 0 THEN 'On Track'
        WHEN s.health_score <= 2 THEN 'Needs Attention'
        ELSE 'At Risk'
      END AS health_label,
      (
        SELECT COALESCE(json_agg(code), '[]'::json)
        FROM (
          SELECT 'overdue_tasks' AS code WHERE s.behind_task_count > 0
          UNION ALL SELECT 'overdue_phases' WHERE s.behind_phase_count > 0
          UNION ALL SELECT 'project_target_overdue' WHERE s.project_target_overdue AND NOT s.all_phases_complete
          UNION ALL SELECT 'open_blockers' WHERE s.open_blockers > 0
          UNION ALL SELECT 'active_high_risks' WHERE s.active_high_risks > 0
          UNION ALL SELECT 'realized_risks' WHERE s.realized_risks > 0
          UNION ALL SELECT 'baseline_slip' WHERE s.baseline_slip_days IS NOT NULL AND s.baseline_slip_days > 0
        ) x
      ) AS health_reason_codes,
      (
        SELECT COALESCE(json_agg(line), '[]'::json)
        FROM (
          SELECT (s.behind_task_count || ' overdue task' || CASE WHEN s.behind_task_count = 1 THEN '' ELSE 's' END) AS line WHERE s.behind_task_count > 0
          UNION ALL SELECT (s.behind_phase_count || ' overdue phase' || CASE WHEN s.behind_phase_count = 1 THEN '' ELSE 's' END) WHERE s.behind_phase_count > 0
          UNION ALL SELECT 'Project target end date has passed' WHERE s.project_target_overdue AND NOT s.all_phases_complete
          UNION ALL SELECT (s.open_blockers || ' open blocker' || CASE WHEN s.open_blockers = 1 THEN '' ELSE 's' END) WHERE s.open_blockers > 0
          UNION ALL SELECT (s.active_high_risks || ' high-impact risk' || CASE WHEN s.active_high_risks = 1 THEN '' ELSE 's' END) WHERE s.active_high_risks > 0
          UNION ALL SELECT (s.realized_risks || ' realized risk' || CASE WHEN s.realized_risks = 1 THEN '' ELSE 's' END) WHERE s.realized_risks > 0
          UNION ALL SELECT ('Baseline slip: +' || s.baseline_slip_days || ' day' || CASE WHEN s.baseline_slip_days = 1 THEN '' ELSE 's' END) WHERE s.baseline_slip_days IS NOT NULL AND s.baseline_slip_days > 0
          UNION ALL SELECT 'No issues detected' WHERE s.health_score = 0
        ) x
      ) AS health_reason_lines,
      s.is_baselined,
      s.baseline_end_date,
      s.target_end_date,
      s.baseline_slip_days,
      json_build_object(
        'has_phases', (s.phase_actionable > 0),
        'has_tasks', (s.s_total > 0),
        'has_target_end_date', (s.target_end_date IS NOT NULL),
        'has_baseline', s.is_baselined,
        'has_schedule_basis', s.has_schedule_basis
      ) AS data_sufficiency_flags,
      now() AS computed_at
    FROM scored s
  ) out_row;

  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: list_project_stakeholders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_stakeholders(_project_id uuid) RETURNS TABLE(id uuid, stakeholder_type text, user_id uuid, external_name text, display_name text, role_label text, notes text, start_date date, created_at timestamp with time zone, created_by uuid, created_by_name text, removed_at timestamp with time zone, removed_by uuid, removed_by_name text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  v_org uuid;
  v_ws uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT pr.organization_id, pr.workspace_id INTO v_org, v_ws
  FROM public.projects pr WHERE pr.id = _project_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Project not found' USING ERRCODE = 'P0002'; END IF;

  IF NOT public.is_user_org_member(v_caller, v_org) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_project(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Forbidden: not authorized to read this project' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT s.id, s.stakeholder_type, s.user_id, s.external_name,
    COALESCE(s.external_name,
      CASE WHEN p.organization_id IS NOT NULL THEN public.btpm_decrypt(p.display_name, p.organization_id)
           ELSE p.display_name END,
      CASE WHEN p.organization_id IS NOT NULL AND p.email IS NOT NULL
           THEN public.btpm_decrypt(p.email, p.organization_id)
           ELSE p.email END,
      'Member')::text AS display_name,
    s.role_label, s.notes, s.start_date, s.created_at, s.created_by,
    CASE WHEN cb.organization_id IS NOT NULL THEN public.btpm_decrypt(cb.display_name, cb.organization_id)
         ELSE cb.display_name END::text AS created_by_name,
    s.removed_at, s.removed_by,
    CASE WHEN rb.organization_id IS NOT NULL THEN public.btpm_decrypt(rb.display_name, rb.organization_id)
         ELSE rb.display_name END::text AS removed_by_name,
    s.updated_at
  FROM public.project_stakeholders s
  LEFT JOIN public.profiles p ON p.id = s.user_id
  LEFT JOIN public.profiles cb ON cb.id = s.created_by
  LEFT JOIN public.profiles rb ON rb.id = s.removed_by
  WHERE s.project_id = _project_id
  ORDER BY (s.removed_at IS NOT NULL) ASC, s.created_at DESC;
END;
$$;


--
-- Name: list_project_templates(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_project_templates(_workspace_id uuid, _include_archived boolean DEFAULT false) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _org_id uuid;
  r RECORD;
  _bp jsonb;
  _summary jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'workspace not found';
  END IF;

  IF NOT (public.is_workspace_member(_caller, _workspace_id) OR public.is_org_admin(_caller, _org_id)) THEN
    RAISE EXCEPTION 'access denied' USING ERRCODE = '42501';
  END IF;

  FOR r IN
    SELECT id, organization_id, workspace_id, source_project_id,
           name, description, blueprint_payload, blueprint_version,
           is_archived, created_at, updated_at, created_by, updated_by
      FROM public.project_templates
     WHERE workspace_id = _workspace_id
       AND (_include_archived OR is_archived = false)
     ORDER BY updated_at DESC
  LOOP
    BEGIN
      _bp := public.btpm_decrypt(r.blueprint_payload, r.organization_id)::jsonb;
    EXCEPTION WHEN OTHERS THEN
      _bp := '{}'::jsonb;
    END;

    _summary := public._template_blueprint_summary(_bp);

    RETURN NEXT jsonb_build_object(
      'template_id', r.id,
      'organization_id', r.organization_id,
      'workspace_id', r.workspace_id,
      'source_project_id', r.source_project_id,
      'name', public.btpm_decrypt(r.name, r.organization_id),
      'description', CASE WHEN r.description IS NULL THEN NULL ELSE public.btpm_decrypt(r.description, r.organization_id) END,
      'blueprint_version', r.blueprint_version,
      'is_archived', r.is_archived,
      'created_at', r.created_at,
      'updated_at', r.updated_at,
      'created_by', r.created_by,
      'updated_by', r.updated_by,
      'schedule_mode', _summary->>'schedule_mode',
      'agile_enabled', (_summary->>'agile_enabled')::boolean,
      'summary_counts', _summary->'summary_counts'
    );
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: list_roadmap_calendar_markers(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_roadmap_calendar_markers(_project_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_allowed uuid[];
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN '[]'::jsonb; END IF;
  IF _project_ids IS NULL OR array_length(_project_ids, 1) IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Filter project list down to those the caller can read (workspace member or org admin).
  SELECT COALESCE(array_agg(p.id), ARRAY[]::uuid[])
  INTO v_allowed
  FROM public.projects p
  WHERE p.id = ANY(_project_ids)
    AND (
      public.is_workspace_member(v_uid, p.workspace_id)
      OR public.is_org_admin(v_uid, p.organization_id)
    );

  IF v_allowed IS NULL OR array_length(v_allowed, 1) IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH
  phase_markers AS (
    SELECT
      'phase'::text                  AS object_kind,
      ph.id                          AS object_id,
      ph.name                        AS object_name,
      ph.phase_type::text            AS semantic_type,
      ph.target_end_date             AS event_date,
      ph.project_id                  AS project_id,
      NULL::uuid                     AS phase_id,
      NULL::text                     AS phase_name
    FROM public.phases ph
    WHERE ph.project_id = ANY(v_allowed)
      AND ph.is_archived = false
      AND ph.target_end_date IS NOT NULL
      AND ph.phase_type::text IN ('milestone','deliverable','decision','review')
  ),
  task_markers AS (
    SELECT
      'task'::text                   AS object_kind,
      t.id                           AS object_id,
      t.name                         AS object_name,
      t.task_type::text              AS semantic_type,
      t.due_date                     AS event_date,
      t.project_id                   AS project_id,
      t.phase_id                     AS phase_id,
      ph.name                        AS phase_name
    FROM public.tasks t
    LEFT JOIN public.phases ph ON ph.id = t.phase_id
    WHERE t.project_id = ANY(v_allowed)
      AND t.is_archived = false
      AND t.due_date IS NOT NULL
      AND t.task_type::text IN ('milestone','deliverable','decision','review')
  ),
  unioned AS (
    SELECT * FROM phase_markers
    UNION ALL
    SELECT * FROM task_markers
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'object_kind',   u.object_kind,
    'object_id',     u.object_id,
    'object_name',   u.object_name,
    'semantic_type', u.semantic_type,
    'event_date',    u.event_date,
    'project_id',    u.project_id,
    'phase_id',      u.phase_id,
    'phase_name',    u.phase_name,
    'workspace_id',  p.workspace_id,
    'project_name',  p.name,
    'project_status', p.status::text
  ) ORDER BY u.event_date, u.object_name), '[]'::jsonb)
  INTO v_result
  FROM unioned u
  JOIN public.projects p ON p.id = u.project_id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: list_roadmap_story_pack_included_files(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_roadmap_story_pack_included_files(_story_pack_id uuid) RETURNS TABLE(id uuid, drive_id text, item_id text, display_name text, web_url text, mime_type text, size_bytes bigint, include_in_story boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT p.* INTO _pack FROM public.roadmap_story_packs p WHERE p.id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    f.id,
    f.drive_id,
    f.item_id,
    CASE WHEN f.display_name_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(f.display_name_encrypted, _pack.organization_id) END,
    CASE WHEN f.web_url_encrypted IS NULL THEN NULL
         ELSE public.btpm_decrypt(f.web_url_encrypted, _pack.organization_id) END,
    f.mime_type,
    f.size_bytes,
    f.include_in_story
  FROM public.roadmap_story_pack_external_files f
  WHERE f.story_pack_id = _story_pack_id
  ORDER BY f.created_at ASC;
END;
$$;


--
-- Name: list_roadmap_story_packs(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_roadmap_story_packs(_include_archived boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.updated_at DESC), '[]'::jsonb)
    INTO _result
  FROM (
    SELECT
      p.id,
      p.organization_id,
      p.primary_workspace_id,
      p.program_id,
      p.status,
      p.audience,
      p.focus,
      CASE WHEN p.title_encrypted IS NULL THEN NULL
           ELSE public.btpm_decrypt(p.title_encrypted, p.organization_id) END AS title,
      p.created_at,
      p.updated_at
    FROM public.roadmap_story_packs p
    WHERE p.created_by = _uid
      AND (_include_archived OR p.status <> 'archived')
  ) t;

  RETURN _result;
END;
$$;


--
-- Name: list_sharepoint_workspace_bindings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_sharepoint_workspace_bindings(_organization_id uuid) RETURNS SETOF public.sharepoint_workspace_bindings
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  IF public.is_org_admin(auth.uid(), _organization_id) THEN
    RETURN QUERY
      SELECT * FROM public.sharepoint_workspace_bindings
      WHERE organization_id = _organization_id
      ORDER BY created_at DESC;
  ELSE
    RETURN QUERY
      SELECT b.* FROM public.sharepoint_workspace_bindings b
      WHERE b.organization_id = _organization_id
        AND public.is_workspace_admin_or_higher(auth.uid(), b.workspace_id)
      ORDER BY b.created_at DESC;
  END IF;
END;
$$;


--
-- Name: list_user_saved_views(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_user_saved_views(_surface_key text, _scope_key text DEFAULT 'global'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_org  uuid;
  v_out  jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  SELECT organization_id INTO v_org FROM public.profiles WHERE id = v_user;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization not resolved for user';
  END IF;

  SELECT COALESCE(jsonb_agg(row ORDER BY (row->>'updated_at') DESC), '[]'::jsonb)
  INTO v_out
  FROM (
    SELECT jsonb_build_object(
      'id',         v.id,
      'name',       public.btpm_decrypt(v.name, v.organization_id),
      'state',      public.btpm_decrypt(v.state_payload, v.organization_id)::jsonb,
      'created_at', v.created_at,
      'updated_at', v.updated_at
    ) AS row
    FROM public.user_saved_views v
    WHERE v.user_id = v_user
      AND v.organization_id = v_org
      AND v.surface_key = _surface_key
      AND v.scope_key   = _scope_key
  ) s;

  RETURN v_out;
END;
$$;


--
-- Name: list_user_workspaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_user_workspaces() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org_id uuid;
  _pref_org uuid;
  _active_org_count int;
  _result json;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  -- Prefer explicit preference when still valid.
  SELECT p.last_active_organization_id INTO _pref_org
    FROM public.user_active_context_preferences p
   WHERE p.user_id = _uid;

  IF _pref_org IS NOT NULL AND public.is_organization_member(_pref_org, _uid) THEN
    _org_id := _pref_org;
  ELSE
    -- Fallback: sole active organization membership. Runtime authority is
    -- organization_memberships + tenant_memberships — never profiles.organization_id.
    SELECT COUNT(*) INTO _active_org_count
      FROM public.organization_memberships om
      JOIN public.tenant_memberships tm
        ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
     WHERE om.user_id = _uid AND om.status = 'active' AND tm.status = 'active';

    IF _active_org_count = 1 THEN
      SELECT om.organization_id INTO _org_id
        FROM public.organization_memberships om
        JOIN public.tenant_memberships tm
          ON tm.tenant_id = om.tenant_id AND tm.user_id = om.user_id
       WHERE om.user_id = _uid AND om.status = 'active' AND tm.status = 'active'
       LIMIT 1;
    ELSE
      _org_id := NULL;
    END IF;
  END IF;

  IF _org_id IS NULL THEN RETURN '[]'::json; END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT * FROM (
      SELECT DISTINCT ON (w.id)
        w.id, public.btpm_decrypt(w.name, _org_id) AS name,
        w.organization_id, w.is_archived, w.is_demo
      FROM public.workspaces w
      LEFT JOIN public.workspace_memberships wm
        ON wm.workspace_id = w.id AND wm.user_id = _uid
      WHERE w.is_archived = false
        AND w.organization_id = _org_id
        AND (wm.user_id IS NOT NULL OR w.is_demo = true OR public.is_org_admin(_uid, w.organization_id))
      ORDER BY w.id
    ) inner_t
    ORDER BY name
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: list_workspace_projects(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_workspace_projects(_workspace_id uuid, _include_archived boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _org_id uuid;
  _result json;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Not a workspace member'; END IF;

  IF public.is_user_org_member(v_caller, _org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.can_read_demo_or_member(v_caller, _workspace_id) THEN
    RAISE EXCEPTION 'Not a workspace member';
  END IF;

  SELECT json_agg(row_to_json(t)) INTO _result
  FROM (
    SELECT
      p.id,
      public.btpm_decrypt(p.name, _org_id) AS name,
      p.status,
      p.priority,
      p.project_stage,
      p.delivery_model,
      p.program_id,
      p.start_date,
      p.target_end_date,
      p.agile_enabled,
      p.is_archived,
      (SELECT public.btpm_decrypt(pr.name, _org_id) FROM public.programs pr WHERE pr.id = p.program_id) AS program_name,
      p.portfolio_item_id,
      (SELECT public.btpm_decrypt(pi.name, _org_id) FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_name,
      (SELECT public.btpm_decrypt(pi.code, _org_id) FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_code,
      (SELECT pi.lifecycle_state FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_lifecycle_state,
      (SELECT pi.is_archived FROM public.portfolio_items pi WHERE pi.id = p.portfolio_item_id) AS portfolio_is_archived
    FROM public.projects p
    WHERE p.workspace_id = _workspace_id
      AND (_include_archived OR p.is_archived = false)
    ORDER BY public.btpm_decrypt(p.name, _org_id)
  ) t;

  RETURN COALESCE(_result, '[]'::json);
END;
$$;


--
-- Name: log_activity_event(uuid, uuid, text, text, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_activity_event(_organization_id uuid, _actor_id uuid, _event_type text, _target_type text, _target_id uuid, _metadata jsonb DEFAULT '{}'::jsonb, _workspace_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _event_id UUID;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;
  IF _workspace_id IS NOT NULL THEN
    IF NOT (is_workspace_member(auth.uid(), _workspace_id) OR is_org_admin(auth.uid(), _organization_id)) THEN RAISE EXCEPTION 'Access denied: not authorized for this workspace'; END IF;
  ELSE
    IF NOT is_org_admin(auth.uid(), _organization_id) THEN
      IF _actor_id != auth.uid() THEN RAISE EXCEPTION 'Access denied: org-level events require admin authority'; END IF;
    END IF;
  END IF;
  INSERT INTO public.activity_events (organization_id, actor_id, event_type, target_type, target_id, metadata, workspace_id) VALUES (_organization_id, _actor_id, _event_type, _target_type, _target_id, _metadata::text, _workspace_id) RETURNING id INTO _event_id;
  RETURN _event_id;
END;
$$;


--
-- Name: log_dependency_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_dependency_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_meta  jsonb;
  v_event text;
  v_org   uuid;
  v_ws    uuid;
BEGIN
  IF (TG_OP = 'INSERT') THEN
    v_event := 'dependency_added';
    v_org   := NEW.organization_id;
    v_ws    := NEW.workspace_id;
    v_meta := jsonb_build_object(
      'dependency_id', NEW.id,
      'predecessor_type', NEW.source_type, 'predecessor_id', NEW.source_id,
      'successor_type',   NEW.target_type, 'successor_id',   NEW.target_id,
      'dependency_type', NEW.dependency_type,
      'semantics', 'finish_to_start'
    );
    PERFORM public.log_activity_event(v_org, v_actor, v_event, NEW.target_type, NEW.target_id, v_meta, v_ws);
    PERFORM public.log_activity_event(v_org, v_actor, v_event, NEW.source_type, NEW.source_id, v_meta, v_ws);
    RETURN NEW;
  ELSIF (TG_OP = 'UPDATE') THEN
    IF NEW.dependency_type IS DISTINCT FROM OLD.dependency_type THEN
      v_event := 'dependency_type_changed';
      v_org   := NEW.organization_id;
      v_ws    := NEW.workspace_id;
      v_meta := jsonb_build_object(
        'dependency_id', NEW.id,
        'predecessor_type', NEW.source_type, 'predecessor_id', NEW.source_id,
        'successor_type',   NEW.target_type, 'successor_id',   NEW.target_id,
        'old_dependency_type', OLD.dependency_type,
        'new_dependency_type', NEW.dependency_type
      );
      PERFORM public.log_activity_event(v_org, v_actor, v_event, NEW.target_type, NEW.target_id, v_meta, v_ws);
      PERFORM public.log_activity_event(v_org, v_actor, v_event, NEW.source_type, NEW.source_id, v_meta, v_ws);
    END IF;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    v_event := 'dependency_removed';
    v_org   := OLD.organization_id;
    v_ws    := OLD.workspace_id;
    v_meta := jsonb_build_object(
      'dependency_id', OLD.id,
      'predecessor_type', OLD.source_type, 'predecessor_id', OLD.source_id,
      'successor_type',   OLD.target_type, 'successor_id',   OLD.target_id,
      'dependency_type', OLD.dependency_type,
      'semantics', 'finish_to_start'
    );
    PERFORM public.log_activity_event(v_org, v_actor, v_event, OLD.target_type, OLD.target_id, v_meta, v_ws);
    PERFORM public.log_activity_event(v_org, v_actor, v_event, OLD.source_type, OLD.source_id, v_meta, v_ws);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: log_phase_schedule_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_phase_schedule_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor uuid := auth.uid(); v_proj_baselined boolean;
BEGIN
  IF NEW.start_date IS DISTINCT FROM OLD.start_date
     OR NEW.target_end_date IS DISTINCT FROM OLD.target_end_date THEN
    SELECT is_baselined INTO v_proj_baselined FROM public.projects WHERE id = NEW.project_id;
    PERFORM public.log_activity_event(
      NEW.organization_id, v_actor, 'schedule_changed', 'phase', NEW.id,
      jsonb_build_object('old_start',OLD.start_date,'old_end',OLD.target_end_date,
                         'new_start',NEW.start_date,'new_end',NEW.target_end_date,
                         'after_baseline',COALESCE(v_proj_baselined,false)),
      NEW.workspace_id);
  END IF;
  RETURN NEW;
END; $$;


