--
-- Name: move_task_workflow_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_task_workflow_state(_task_id uuid, _workflow_state_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  _user_id uuid := auth.uid();
  _task record;
  _state record;
  _previous_workflow_state_id uuid;
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.is_active_user(_user_id) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT id, project_id, workspace_id, organization_id, workflow_state_id
  INTO _task
  FROM public.tasks
  WHERE id = _task_id;

  IF _task IS NULL THEN
    RAISE EXCEPTION 'Task not found';
  END IF;

  SELECT id, project_id, workspace_id, organization_id, is_archived
  INTO _state
  FROM public.board_workflow_states
  WHERE id = _workflow_state_id;

  IF _state IS NULL THEN
    RAISE EXCEPTION 'Workflow state not found';
  END IF;

  IF _state.is_archived THEN
    RAISE EXCEPTION 'Workflow state is archived';
  END IF;

  IF _task.project_id <> _state.project_id OR _task.workspace_id <> _state.workspace_id OR _task.organization_id <> _state.organization_id THEN
    RAISE EXCEPTION 'Task and workflow state must belong to the same project and workspace';
  END IF;

  IF NOT public.has_pm_authority(_user_id, _task.workspace_id) THEN
    RAISE EXCEPTION 'Insufficient authority';
  END IF;

  IF NOT public.can_write_demo(_user_id, _task.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized to write in this workspace (read-only/demo)';
  END IF;

  _previous_workflow_state_id := _task.workflow_state_id;

  UPDATE public.tasks
  SET workflow_state_id = _workflow_state_id
  WHERE id = _task_id;

  PERFORM public.log_activity_event(
    _organization_id => _task.organization_id,
    _workspace_id => _task.workspace_id,
    _actor_id => _user_id,
    _event_type => 'workflow_state_changed',
    _target_type => 'task',
    _target_id => _task_id,
    _metadata => jsonb_build_object(
      'source', 'agile_board',
      'from_workflow_state_id', _previous_workflow_state_id,
      'to_workflow_state_id', _workflow_state_id
    )
  );
END;
$$;


--
-- Name: notify_blocker_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_blocker_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_assignee_id uuid;
  v_task record;
  v_project_name text;
  v_payload text;
  v_idem text;
BEGIN
  IF current_setting('btpm.seed_mode', true) = 'true' THEN RETURN NEW; END IF;
  IF NEW.target_type != 'task' THEN RETURN NEW; END IF;

  SELECT ta.assignee_id INTO v_assignee_id FROM task_assignments ta WHERE ta.task_id = NEW.target_id ORDER BY ta.created_at DESC LIMIT 1;
  IF v_assignee_id IS NULL THEN RETURN NEW; END IF;
  IF v_assignee_id = NEW.reported_by THEN RETURN NEW; END IF;
  IF NOT is_workspace_member(v_assignee_id, NEW.workspace_id) THEN RETURN NEW; END IF;

  SELECT t.name, t.project_id INTO v_task FROM tasks t WHERE t.id = NEW.target_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT p.name INTO v_project_name FROM projects p WHERE p.id = v_task.project_id;

  v_idem := 'blocker_created:' || NEW.id;
  v_payload := json_build_object(
    'blocker_title', NEW.title, 'task_name', v_task.name,
    'project_name', COALESCE(v_project_name, ''),
    'task_id', NEW.target_id, 'project_id', v_task.project_id,
    'workspace_id', NEW.workspace_id
  )::text;

  INSERT INTO notification_outbox (
    event_type, recipient_id, actor_id, target_type, target_id,
    workspace_id, organization_id, payload, idempotency_key
  ) VALUES (
    'blocker_created', v_assignee_id, NEW.reported_by, 'task', NEW.target_id,
    NEW.workspace_id, NEW.organization_id, v_payload, v_idem
  ) ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: notify_blocker_resolved(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_blocker_resolved() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_task record;
  v_project_name text;
  v_payload text;
  v_idem text;
BEGIN
  IF current_setting('btpm.seed_mode', true) = 'true' THEN RETURN NEW; END IF;
  IF NEW.target_type != 'task' THEN RETURN NEW; END IF;
  IF NEW.status != 'resolved' THEN RETURN NEW; END IF;
  IF OLD.status = 'resolved' THEN RETURN NEW; END IF;
  IF NEW.reported_by IS NULL THEN RETURN NEW; END IF;
  IF NEW.resolved_by = NEW.reported_by THEN RETURN NEW; END IF;
  IF NOT is_workspace_member(NEW.reported_by, NEW.workspace_id) THEN RETURN NEW; END IF;

  SELECT t.name, t.project_id INTO v_task FROM tasks t WHERE t.id = NEW.target_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT p.name INTO v_project_name FROM projects p WHERE p.id = v_task.project_id;

  v_idem := 'blocker_resolved:' || NEW.id;
  v_payload := json_build_object(
    'blocker_title', NEW.title, 'task_name', v_task.name,
    'project_name', COALESCE(v_project_name, ''),
    'task_id', NEW.target_id, 'project_id', v_task.project_id,
    'workspace_id', NEW.workspace_id
  )::text;

  INSERT INTO notification_outbox (
    event_type, recipient_id, actor_id, target_type, target_id,
    workspace_id, organization_id, payload, idempotency_key
  ) VALUES (
    'blocker_resolved', NEW.reported_by, NEW.resolved_by, 'task', NEW.target_id,
    NEW.workspace_id, NEW.organization_id, v_payload, v_idem
  ) ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: notify_task_assigned(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_task_assigned() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_task record;
  v_project record;
  v_actor_name text;
  v_payload text;
  v_idem text;
BEGIN
  IF current_setting('btpm.seed_mode', true) = 'true' THEN RETURN NEW; END IF;
  IF NEW.assignee_id = NEW.assigned_by THEN RETURN NEW; END IF;
  IF NOT is_workspace_member(NEW.assignee_id, NEW.workspace_id) THEN RETURN NEW; END IF;

  SELECT t.name, t.project_id, t.phase_id INTO v_task FROM tasks t WHERE t.id = NEW.task_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  SELECT p.name INTO v_project FROM projects p WHERE p.id = v_task.project_id;

  v_idem := 'task_assigned:' || NEW.task_id || ':' || NEW.assignee_id || ':' || NEW.id;
  v_payload := json_build_object(
    'task_name', v_task.name,
    'project_name', COALESCE(v_project.name, ''),
    'task_id', NEW.task_id,
    'project_id', v_task.project_id,
    'workspace_id', NEW.workspace_id
  )::text;

  INSERT INTO notification_outbox (
    event_type, recipient_id, actor_id, target_type, target_id,
    workspace_id, organization_id, payload, idempotency_key
  ) VALUES (
    'task_assigned', NEW.assignee_id, NEW.assigned_by, 'task', NEW.task_id,
    NEW.workspace_id, NEW.organization_id, v_payload, v_idem
  ) ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: org_admin_assign_org_admin(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_admin_assign_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _om public.organization_memberships%ROWTYPE; _tid uuid; _prev text;
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND OR _om.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_org_member' USING ERRCODE='42501';
  END IF;
  _prev := _om.role::text;
  IF _om.role<>'org_admin' THEN
    UPDATE public.organization_memberships SET role='org_admin', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  END IF;
  PERFORM public._log_admin_authority('assign_org_admin',
    _tid, _organization_id, _target_user_id, NULL, _prev, 'org_admin', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$$;


--
-- Name: org_admin_list_org_admin_candidates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_admin_list_org_admin_candidates(_organization_id uuid, _query text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
  SELECT om.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END AS dn,
         p.email
  FROM public.organization_memberships om
  LEFT JOIN public.profiles p ON p.id=om.user_id
  WHERE om.organization_id=_organization_id AND om.status='active' AND om.role='org_member'
    AND (_query IS NULL OR _query='' OR p.email ILIKE '%'||_query||'%' OR
         (CASE WHEN p.organization_id IS NOT NULL
               THEN public.btpm_decrypt(p.display_name, p.organization_id)
               ELSE p.display_name END) ILIKE '%'||_query||'%')
  ORDER BY dn NULLS LAST, p.email NULLS LAST
  LIMIT 50;
END;$$;


--
-- Name: org_admin_list_org_admins(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_admin_list_org_admins(_organization_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, display_name text, email text, role text, status text, can_remove boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;
  RETURN QUERY
  SELECT om.id, om.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END,
         p.email, om.role::text, om.status::text,
         (om.role='org_admin' AND om.status='active' AND om.user_id<>auth.uid()),
         om.created_at
  FROM public.organization_memberships om
  LEFT JOIN public.profiles p ON p.id=om.user_id
  WHERE om.organization_id=_organization_id AND om.role='org_admin'
  ORDER BY p.email NULLS LAST;
END;$$;


--
-- Name: admin_authority_audit; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_authority_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_user_id uuid NOT NULL,
    action text NOT NULL,
    tenant_id uuid,
    organization_id uuid,
    target_user_id uuid,
    target_email text,
    previous_role text,
    new_role text,
    previous_status text,
    new_status text,
    reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL
);


--
-- Name: org_admin_list_org_authority_audit(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_admin_list_org_authority_audit(_organization_id uuid, _limit integer DEFAULT 50) RETURNS SETOF public.admin_authority_audit
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501'; END IF;
  RETURN QUERY SELECT * FROM public.admin_authority_audit
    WHERE organization_id=_organization_id ORDER BY created_at DESC LIMIT LEAST(GREATEST(_limit,1),500);
END;$$;


--
-- Name: org_admin_remove_org_admin(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_admin_remove_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _om public.organization_memberships%ROWTYPE; _tid uuid; _remaining int;
BEGIN
  IF NOT public.is_user_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
  END IF;
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND OR _om.role<>'org_admin' OR _om.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_org_admin' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO _remaining FROM public.organization_memberships
   WHERE organization_id=_organization_id AND role='org_admin' AND status='active' AND user_id<>_target_user_id;
  IF _remaining<1 THEN
    PERFORM public._log_admin_authority('blocked_last_admin_change',
      _tid, _organization_id, _target_user_id, NULL, 'org_admin', 'org_member', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'last_org_admin' USING ERRCODE='42501';
  END IF;
  UPDATE public.organization_memberships SET role='org_member', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  PERFORM public._log_admin_authority('remove_org_admin',
    _tid, _organization_id, _target_user_id, NULL, 'org_admin', 'org_member', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$$;


--
-- Name: pa_auto_grant_creator_pm(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_auto_grant_creator_pm() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.created_by IS NULL THEN
    RETURN NEW;
  END IF;

  -- Idempotent: only insert if no active row exists
  IF NOT EXISTS (
    SELECT 1 FROM public.project_memberships
    WHERE project_id = NEW.id
      AND user_id = NEW.created_by
      AND removed_at IS NULL
  ) THEN
    -- Revive a soft-removed row if present, else insert
    IF EXISTS (
      SELECT 1 FROM public.project_memberships
      WHERE project_id = NEW.id AND user_id = NEW.created_by
    ) THEN
      UPDATE public.project_memberships
      SET role = 'project_manager'::public.project_role,
          granted_by = NEW.created_by,
          removed_at = NULL,
          updated_at = now()
      WHERE project_id = NEW.id AND user_id = NEW.created_by;
    ELSE
      INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
      VALUES (NEW.id, NEW.created_by, 'project_manager'::public.project_role, NEW.created_by);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: pa_can_admin_workspace(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_can_admin_workspace(_workspace_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _org_id uuid;
BEGIN
  IF _caller IS NULL THEN RETURN false; END IF;
  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN RETURN false; END IF;
  RETURN public.is_org_admin(_caller, _org_id)
      OR public.is_workspace_admin_or_higher(_caller, _workspace_id);
END;
$$;


--
-- Name: pa_grant_all_workspace_projects(uuid, uuid, public.project_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_grant_all_workspace_projects(_target_user_id uuid, _workspace_id uuid, _override_role public.project_role DEFAULT NULL::public.project_role) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _ws_role text;
  _mapped public.project_role;
  _affected integer := 0;
BEGIN
  IF NOT public.pa_can_admin_workspace(_workspace_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  -- Resolve role
  IF _override_role IS NOT NULL THEN
    _mapped := _override_role;
  ELSE
    SELECT wm.role::text INTO _ws_role
    FROM public.workspace_memberships wm
    WHERE wm.workspace_id = _workspace_id
      AND wm.user_id = _target_user_id
    LIMIT 1;

    IF _ws_role IS NULL THEN
      RAISE EXCEPTION 'user does not have workspace membership';
    END IF;
    _mapped := public.pa_map_workspace_role_to_project_role(_ws_role);
    IF _mapped IS NULL THEN
      RAISE EXCEPTION 'workspace role % is not mappable to a project role', _ws_role;
    END IF;
  END IF;

  -- Insert/upsert for every non-archived project in workspace
  WITH target_projects AS (
    SELECT id AS project_id
    FROM public.projects
    WHERE workspace_id = _workspace_id
      AND is_archived = false
  ),
  upserted AS (
    INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
    SELECT tp.project_id, _target_user_id, _mapped, _caller
    FROM target_projects tp
    WHERE NOT EXISTS (
      SELECT 1 FROM public.project_memberships pm
      WHERE pm.project_id = tp.project_id
        AND pm.user_id = _target_user_id
        AND pm.removed_at IS NULL
    )
    RETURNING 1
  ),
  revived AS (
    UPDATE public.project_memberships pm
    SET role = _mapped, granted_by = _caller, removed_at = NULL, updated_at = now()
    FROM target_projects tp
    WHERE pm.project_id = tp.project_id
      AND pm.user_id = _target_user_id
      AND pm.removed_at IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.project_memberships pm2
        WHERE pm2.project_id = tp.project_id
          AND pm2.user_id = _target_user_id
          AND pm2.removed_at IS NULL
      )
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM upserted) + (SELECT count(*) FROM revived)
  INTO _affected;

  RETURN _affected;
END;
$$;


--
-- Name: pa_grant_project_access(uuid, uuid, public.project_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_grant_project_access(_target_user_id uuid, _project_id uuid, _role public.project_role) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _ws_id uuid;
  _existing_id uuid;
  _has_ws_membership boolean;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF _caller = _target_user_id THEN
    -- Block self-grant for non-admins; admins still go through the same path so block uniformly
    -- Allow only if caller is org_admin (rare, supportable case)
    NULL;
  END IF;

  SELECT workspace_id INTO _ws_id FROM public.projects WHERE id = _project_id;
  IF _ws_id IS NULL THEN
    RAISE EXCEPTION 'project not found';
  END IF;

  IF NOT public.pa_can_admin_workspace(_ws_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  -- Require target user to have workspace membership before granting project access
  SELECT EXISTS (
    SELECT 1 FROM public.workspace_memberships
    WHERE workspace_id = _ws_id AND user_id = _target_user_id
  ) INTO _has_ws_membership;
  IF NOT _has_ws_membership THEN
    RAISE EXCEPTION 'user does not have workspace membership';
  END IF;

  -- Upsert active membership
  SELECT id INTO _existing_id
  FROM public.project_memberships
  WHERE project_id = _project_id
    AND user_id = _target_user_id
    AND removed_at IS NULL;

  IF _existing_id IS NOT NULL THEN
    UPDATE public.project_memberships
    SET role = _role,
        granted_by = _caller,
        updated_at = now()
    WHERE id = _existing_id;
    RETURN _existing_id;
  END IF;

  -- If a soft-removed row exists, revive it
  SELECT id INTO _existing_id
  FROM public.project_memberships
  WHERE project_id = _project_id
    AND user_id = _target_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF _existing_id IS NOT NULL THEN
    UPDATE public.project_memberships
    SET role = _role,
        granted_by = _caller,
        removed_at = NULL,
        updated_at = now()
    WHERE id = _existing_id;
    RETURN _existing_id;
  END IF;

  INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
  VALUES (_project_id, _target_user_id, _role, _caller)
  RETURNING id INTO _existing_id;

  RETURN _existing_id;
END;
$$;


--
-- Name: pa_list_user_workspace_projects(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_list_user_workspace_projects(_target_user_id uuid, _workspace_id uuid) RETURNS TABLE(project_id uuid, project_name text, is_archived boolean, membership_id uuid, role public.project_role, granted_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.pa_can_admin_workspace(_workspace_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  RETURN QUERY
  SELECT p.id,
         p.name,
         p.is_archived,
         pm.id,
         pm.role,
         pm.created_at
  FROM public.projects p
  LEFT JOIN public.project_memberships pm
    ON pm.project_id = p.id
   AND pm.user_id = _target_user_id
   AND pm.removed_at IS NULL
  WHERE p.workspace_id = _workspace_id
  ORDER BY p.is_archived ASC, p.name ASC;
END;
$$;


--
-- Name: pa_map_workspace_role_to_project_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_map_workspace_role_to_project_role(_ws_role text) RETURNS public.project_role
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE _ws_role
    WHEN 'workspace_admin'   THEN 'project_manager'::public.project_role
    WHEN 'project_manager'   THEN 'project_manager'::public.project_role
    WHEN 'contributor'       THEN 'contributor'::public.project_role
    WHEN 'viewer'            THEN 'viewer'::public.project_role
    ELSE NULL
  END
$$;


--
-- Name: pa_remove_project_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_remove_project_access(_target_user_id uuid, _project_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _ws_id uuid;
BEGIN
  SELECT workspace_id INTO _ws_id FROM public.projects WHERE id = _project_id;
  IF _ws_id IS NULL THEN
    RAISE EXCEPTION 'project not found';
  END IF;
  IF NOT public.pa_can_admin_workspace(_ws_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  UPDATE public.project_memberships
  SET removed_at = now(),
      updated_at = now()
  WHERE project_id = _project_id
    AND user_id = _target_user_id
    AND removed_at IS NULL;
END;
$$;


--
-- Name: pa_reset_workspace_to_inherited(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_reset_workspace_to_inherited(_target_user_id uuid, _workspace_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _ws_role text;
  _mapped public.project_role;
  _affected integer := 0;
BEGIN
  IF NOT public.pa_can_admin_workspace(_workspace_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  SELECT wm.role::text INTO _ws_role
  FROM public.workspace_memberships wm
  WHERE wm.workspace_id = _workspace_id AND wm.user_id = _target_user_id
  LIMIT 1;
  IF _ws_role IS NULL THEN
    RAISE EXCEPTION 'user does not have workspace membership';
  END IF;
  _mapped := public.pa_map_workspace_role_to_project_role(_ws_role);
  IF _mapped IS NULL THEN
    RAISE EXCEPTION 'workspace role % is not mappable to a project role', _ws_role;
  END IF;

  -- Update active rows to mapped role
  UPDATE public.project_memberships pm
  SET role = _mapped, granted_by = _caller, updated_at = now()
  FROM public.projects p
  WHERE pm.project_id = p.id
    AND p.workspace_id = _workspace_id
    AND p.is_archived = false
    AND pm.user_id = _target_user_id
    AND pm.removed_at IS NULL
    AND pm.role <> _mapped;
  GET DIAGNOSTICS _affected = ROW_COUNT;

  -- Insert missing for non-archived projects
  WITH inserted AS (
    INSERT INTO public.project_memberships (project_id, user_id, role, granted_by)
    SELECT p.id, _target_user_id, _mapped, _caller
    FROM public.projects p
    WHERE p.workspace_id = _workspace_id
      AND p.is_archived = false
      AND NOT EXISTS (
        SELECT 1 FROM public.project_memberships pm
        WHERE pm.project_id = p.id
          AND pm.user_id = _target_user_id
          AND pm.removed_at IS NULL
      )
    RETURNING 1
  )
  SELECT _affected + count(*) FROM inserted INTO _affected;

  RETURN _affected;
END;
$$;


--
-- Name: pa_workspace_project_access_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pa_workspace_project_access_counts(_workspace_id uuid) RETURNS TABLE(user_id uuid, accessible_count integer, total_active_projects integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.pa_can_admin_workspace(_workspace_id) THEN
    RAISE EXCEPTION 'not authorized to administer this workspace';
  END IF;

  RETURN QUERY
  WITH ws_projects AS (
    SELECT id FROM public.projects WHERE workspace_id = _workspace_id AND is_archived = false
  ),
  total AS (SELECT count(*)::int AS c FROM ws_projects)
  SELECT wm.user_id,
         COALESCE((
           SELECT count(*)::int
           FROM public.project_memberships pm
           WHERE pm.user_id = wm.user_id
             AND pm.removed_at IS NULL
             AND pm.project_id IN (SELECT id FROM ws_projects)
         ), 0),
         (SELECT c FROM total)
  FROM public.workspace_memberships wm
  WHERE wm.workspace_id = _workspace_id;
END;
$$;


--
-- Name: platform_admin_assign_tenant_admin(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_assign_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_memberships%ROWTYPE;
  _prev_role text;
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND user_id = _target_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_tenant_member' USING ERRCODE = '42501';
  END IF;
  IF _row.status <> 'active' THEN
    RAISE EXCEPTION 'target_not_active_tenant_member' USING ERRCODE = '42501';
  END IF;
  IF _row.role = 'tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE = '42501';
  END IF;
  _prev_role := _row.role::text;
  IF _row.role <> 'tenant_admin' THEN
    UPDATE public.tenant_memberships
       SET role = 'tenant_admin', updated_at = now(), updated_by = auth.uid()
     WHERE id = _row.id;
  END IF;
  PERFORM public._log_admin_authority('assign_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, _prev_role, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;
$$;


--
-- Name: platform_admin_get_encryption_posture_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_get_encryption_posture_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _tenants jsonb;
  _totals  jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF NOT public.is_platform_super_admin(_caller) THEN
    RAISE EXCEPTION 'not_platform_super_admin';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(tep) ORDER BY tep.tenant_name), '[]'::jsonb)
    INTO _tenants
    FROM public.tenant_encryption_posture tep;

  SELECT jsonb_build_object(
    'tenants_total',                      (SELECT COUNT(*) FROM public.tenants),
    'tenants_with_metadata',              (SELECT COUNT(DISTINCT tenant_id) FROM public.tenant_encryption_keys),
    'organizations_total',                (SELECT COUNT(*) FROM public.organizations),
    'organizations_with_metadata',        (SELECT COUNT(*) FROM public.organization_encryption_keys),
    'organizations_missing_metadata',     (SELECT COUNT(*) FROM public.organizations o
                                              WHERE NOT EXISTS (SELECT 1 FROM public.organization_encryption_keys oek WHERE oek.organization_id = o.id)),
    'production_org_count',               (SELECT COUNT(*) FROM public.organizations WHERE environment_role = 'production'),
    'non_production_org_count',           (SELECT COUNT(*) FROM public.organizations WHERE environment_role = 'non_production')
  ) INTO _totals;

  RETURN jsonb_build_object('totals', _totals, 'tenants', _tenants);
END;
$$;


--
-- Name: platform_admin_get_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_get_overview(_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT public.is_platform_super_admin(_uid) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'tenants', jsonb_build_object(
      'total',            (SELECT COUNT(*) FROM public.tenants),
      'active',           (SELECT COUNT(*) FROM public.tenants WHERE status = 'active'),
      'provisioning',     (SELECT COUNT(*) FROM public.tenants WHERE status = 'provisioning'),
      'suspended',        (SELECT COUNT(*) FROM public.tenants WHERE status = 'suspended'),
      'archived',         (SELECT COUNT(*) FROM public.tenants WHERE status IN ('archived','deletion_requested','retained','purged'))
    ),
    'organizations', jsonb_build_object(
      'total',            (SELECT COUNT(*) FROM public.organizations),
      'production',       (SELECT COUNT(*) FROM public.organizations WHERE environment_role = 'production'),
      'non_production',   (SELECT COUNT(*) FROM public.organizations WHERE environment_role = 'non_production')
    ),
    'substrate', jsonb_build_object(
      'tenant_memberships',       (SELECT COUNT(*) FROM public.tenant_memberships),
      'organization_memberships', (SELECT COUNT(*) FROM public.organization_memberships),
      'tenant_integrations',      (SELECT COUNT(*) FROM public.tenant_integrations),
      'tenant_storage_objects',   (SELECT COUNT(*) FROM public.tenant_storage_objects),
      'tenant_export_packages',   (SELECT COUNT(*) FROM public.tenant_export_packages),
      'tenant_background_jobs',   (SELECT COUNT(*) FROM public.tenant_background_jobs),
      'tenant_scheduler_runs',    (SELECT COUNT(*) FROM public.tenant_scheduler_runs)
    ),
    'generated_at', now(),
    'reason', _reason
  );
END;
$$;


--
-- Name: platform_admin_list_tenant_admin_candidates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_list_tenant_admin_candidates(_tenant_id uuid, _query text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT tm.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END AS dn,
         p.email
  FROM public.tenant_memberships tm
  LEFT JOIN public.profiles p ON p.id = tm.user_id
  WHERE tm.tenant_id = _tenant_id AND tm.status='active' AND tm.role='tenant_member'
    AND (_query IS NULL OR _query = '' OR p.email ILIKE '%'||_query||'%' OR
         (CASE WHEN p.organization_id IS NOT NULL
               THEN public.btpm_decrypt(p.display_name, p.organization_id)
               ELSE p.display_name END) ILIKE '%'||_query||'%')
  ORDER BY dn NULLS LAST, p.email NULLS LAST
  LIMIT 50;
END;$$;


--
-- Name: platform_admin_list_tenant_admins(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_list_tenant_admins(_tenant_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, display_name text, email text, role text, status text, is_protected boolean, can_remove boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT tm.id, tm.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END,
         p.email, tm.role::text, tm.status::text,
         (tm.role = 'tenant_owner'),
         (tm.role = 'tenant_admin' AND tm.status = 'active'),
         tm.created_at
  FROM public.tenant_memberships tm
  LEFT JOIN public.profiles p ON p.id = tm.user_id
  WHERE tm.tenant_id = _tenant_id AND tm.role IN ('tenant_owner','tenant_admin')
  ORDER BY (tm.role='tenant_owner') DESC, p.email NULLS LAST;
END;$$;


--
-- Name: platform_admin_list_tenant_authority_audit(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_list_tenant_authority_audit(_tenant_id uuid, _limit integer DEFAULT 50) RETURNS SETOF public.admin_authority_audit
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501'; END IF;
  RETURN QUERY SELECT * FROM public.admin_authority_audit
    WHERE tenant_id=_tenant_id ORDER BY created_at DESC LIMIT LEAST(GREATEST(_limit,1),500);
END;$$;


--
-- Name: platform_admin_list_tenants(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_list_tenants(_reason text DEFAULT NULL::text) RETURNS TABLE(tenant_id uuid, name text, slug text, status text, created_at timestamp with time zone, default_organization_id uuid, default_organization_name text, organization_count bigint, active_member_count bigint, admin_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL OR NOT public.is_platform_super_admin(_uid) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    t.id,
    t.name,
    t.slug,
    t.status::text,
    t.created_at,
    t.default_organization_id,
    def_org.name AS default_organization_name,
    (SELECT COUNT(*) FROM public.organizations o WHERE o.tenant_id = t.id) AS organization_count,
    (SELECT COUNT(*) FROM public.tenant_memberships tm
       WHERE tm.tenant_id = t.id AND tm.status = 'active') AS active_member_count,
    (SELECT COUNT(*) FROM public.tenant_memberships tm
       WHERE tm.tenant_id = t.id AND tm.status = 'active'
         AND tm.role IN ('tenant_owner','tenant_admin')) AS admin_count
  FROM public.tenants t
  LEFT JOIN public.organizations def_org ON def_org.id = t.default_organization_id
  ORDER BY t.name;
  -- _reason accepted for future audit hook; intentionally not persisted yet.
  PERFORM 1 WHERE _reason IS NOT NULL;
END;
$$;


--
-- Name: platform_admin_remove_tenant_admin(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_remove_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_memberships%ROWTYPE;
  _remaining int;
BEGIN
  IF NOT public.is_platform_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND user_id = _target_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_tenant_member' USING ERRCODE = '42501';
  END IF;
  IF _row.role = 'tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, _row.role::text, _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE = '42501';
  END IF;
  IF _row.role <> 'tenant_admin' THEN
    RAISE EXCEPTION 'target_not_tenant_admin' USING ERRCODE = '42501';
  END IF;
  SELECT count(*) INTO _remaining
    FROM public.tenant_memberships
   WHERE tenant_id = _tenant_id AND status='active'
     AND role IN ('tenant_owner','tenant_admin')
     AND user_id <> _target_user_id;
  IF _remaining < 1 THEN
    PERFORM public._log_admin_authority('blocked_last_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_member', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'last_tenant_admin' USING ERRCODE = '42501';
  END IF;
  UPDATE public.tenant_memberships
     SET role='tenant_member', updated_at=now(), updated_by=auth.uid()
   WHERE id=_row.id;
  PERFORM public._log_admin_authority('remove_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, 'tenant_admin', 'tenant_member', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;
$$;


--
-- Name: pmg_build_result(public.pmg_command_status, text, text, uuid, uuid, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pmg_build_result(_status public.pmg_command_status, _command text, _target_type text DEFAULT NULL::text, _target_id uuid DEFAULT NULL::uuid, _project_id uuid DEFAULT NULL::uuid, _data jsonb DEFAULT '{}'::jsonb, _changes jsonb DEFAULT '[]'::jsonb, _warnings jsonb DEFAULT '[]'::jsonb, _confirmations jsonb DEFAULT '[]'::jsonb, _conflict jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_data jsonb := COALESCE(_data, '{}'::jsonb);
  v_changes jsonb := COALESCE(_changes, '[]'::jsonb);
  v_warnings jsonb := COALESCE(_warnings, '[]'::jsonb);
  v_confirmations jsonb := COALESCE(_confirmations, '[]'::jsonb);
BEGIN
  IF _command IS NULL OR btrim(_command) = '' THEN
    RAISE EXCEPTION 'pmg_build_result: command must be a non-empty string' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_data) <> 'object' THEN
    RAISE EXCEPTION 'pmg_build_result: data must be a JSON object' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_changes) <> 'array' THEN
    RAISE EXCEPTION 'pmg_build_result: changes must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_warnings) <> 'array' THEN
    RAISE EXCEPTION 'pmg_build_result: warnings must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_confirmations) <> 'array' THEN
    RAISE EXCEPTION 'pmg_build_result: confirmations must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF _conflict IS NOT NULL AND jsonb_typeof(_conflict) <> 'object' THEN
    RAISE EXCEPTION 'pmg_build_result: conflict must be null or a JSON object' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'status',        _status::text,
    'command',       _command,
    'target_type',   _target_type,
    'target_id',     _target_id,
    'project_id',    _project_id,
    'data',          v_data,
    'changes',       v_changes,
    'warnings',      v_warnings,
    'confirmations', v_confirmations,
    'conflict',      _conflict
  );
END; $$;


--
-- Name: pmg_record_command_audit(public.pmg_command_status, text, public.pmg_source_channel, uuid, text, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pmg_record_command_audit(_status public.pmg_command_status, _command text, _source_channel public.pmg_source_channel, _project_id uuid, _target_type text, _target_id uuid, _integration_id uuid, _correlation_id text, _idempotency_key text, _metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid := NULL;
  v_ws uuid := NULL;
  v_metadata jsonb := COALESCE(_metadata, '{}'::jsonb);
  v_integration_status public.tenant_integration_status;
  v_integration_enabled boolean;
  v_integration_id uuid := _integration_id;
  v_requested_user_id uuid := NULL;
  v_executing_user_id uuid := NULL;
  v_source_client_id uuid := NULL;
  v_request_id text := NULL;
  v_delegation_mode text := 'system';
  v_trusted text;
  v_trusted_channel text;
  v_auth_user text;
  v_exec_user text;
  v_client_id text;
  v_req_id text;
  v_capability_key text;
  v_client_key text;
  v_client_lifecycle text;
  v_source_system text := NULL;
  v_source_component text := NULL;
  -- API-Q.9A2: selects the API-client MCP provenance mode.
  v_apiq_mcp boolean := (_source_channel = 'mcp' AND _integration_id IS NULL);
  v_id uuid;
BEGIN
  IF _command IS NULL OR length(btrim(_command)) = 0 THEN
    RAISE EXCEPTION 'pmg_record_command_audit: _command must be non-blank';
  END IF;

  IF jsonb_typeof(v_metadata) <> 'object' THEN
    RAISE EXCEPTION 'pmg_record_command_audit: _metadata must be a JSON object';
  END IF;

  IF _source_channel IN ('btpm_ui', 'admin_import') THEN
    IF v_actor IS NULL THEN
      RAISE EXCEPTION 'pmg_record_command_audit: channel % requires an authenticated user', _source_channel;
    END IF;
  ELSIF _source_channel = 'mcp' THEN
    IF v_apiq_mcp THEN
      -- API-Q.9A2: no integration identity is only accepted with a trusted,
      -- server-established API-E MCP context. It must never fall through as
      -- anonymous/system MCP.
      IF current_setting('api_e.trusted', true) IS DISTINCT FROM 'true' THEN
        RAISE EXCEPTION 'pmg_record_command_audit: mcp requires trusted API-E context';
      END IF;
      IF current_setting('api_e.source_channel', true) IS DISTINCT FROM 'mcp' THEN
        RAISE EXCEPTION 'pmg_record_command_audit: mcp requires api_e.source_channel=mcp';
      END IF;
      v_integration_id := NULL;
    END IF;
    -- Legacy MCP integration mode (_integration_id IS NOT NULL) is unchanged.
  ELSIF _source_channel = 'external_api' THEN
    -- API-I.2: external API provenance is api_clients-based only.
    -- tenant_integrations is a separate concept and must never be mixed in.
    IF _integration_id IS NOT NULL THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api must not supply an integration identity';
    END IF;
    v_integration_id := NULL;
  END IF;

  IF v_integration_id IS NOT NULL AND _source_channel <> 'external_api' THEN
    SELECT ti.status, ti.is_enabled
      INTO v_integration_status, v_integration_enabled
      FROM public.tenant_integrations ti
      WHERE ti.id = v_integration_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'pmg_record_command_audit: integration % does not exist', v_integration_id;
    END IF;
    IF v_integration_status <> 'active' OR v_integration_enabled IS DISTINCT FROM true THEN
      IF _source_channel = 'mcp' THEN
        RAISE EXCEPTION 'pmg_record_command_audit: integration % is not active', v_integration_id;
      END IF;
    END IF;
  END IF;

  IF _project_id IS NOT NULL THEN
    SELECT p.organization_id, p.workspace_id
      INTO v_org, v_ws
      FROM public.projects p
      WHERE p.id = _project_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'pmg_record_command_audit: project % does not exist', _project_id;
    END IF;
  END IF;

  IF _source_channel IN ('btpm_ui', 'admin_import') THEN
    v_requested_user_id := v_actor;
    v_executing_user_id := v_actor;
    v_delegation_mode := 'direct_user';
  ELSIF _source_channel = 'external_api' THEN
    v_trusted := current_setting('api_e.trusted', true);
    v_trusted_channel := current_setting('api_e.source_channel', true);
    IF v_trusted IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api requires trusted API-E context';
    END IF;
    IF v_trusted_channel IS DISTINCT FROM 'external_api' THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api requires api_e.source_channel=external_api';
    END IF;

    v_auth_user := current_setting('api_e.authenticated_user_id', true);
    v_exec_user := current_setting('api_e.executing_user_id', true);
    v_client_id := current_setting('api_e.api_client_id', true);
    v_req_id := current_setting('api_e.request_id', true);

    IF v_auth_user IS NULL OR length(btrim(v_auth_user)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api missing api_e.authenticated_user_id';
    END IF;
    IF v_exec_user IS NULL OR length(btrim(v_exec_user)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api missing api_e.executing_user_id';
    END IF;
    IF v_client_id IS NULL OR length(btrim(v_client_id)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api missing api_e.api_client_id';
    END IF;
    IF v_req_id IS NULL OR length(btrim(v_req_id)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api missing api_e.request_id';
    END IF;

    BEGIN
      v_requested_user_id := v_auth_user::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.authenticated_user_id is not a valid uuid';
    END;
    BEGIN
      v_executing_user_id := v_exec_user::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.executing_user_id is not a valid uuid';
    END;
    BEGIN
      v_source_client_id := v_client_id::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.api_client_id is not a valid uuid';
    END;

    v_request_id := v_req_id;
    v_delegation_mode := 'delegated_user';

    -- API-F.1B3: source_system / source_component
    v_capability_key := current_setting('api_e.capability_key', true);
    IF v_capability_key IS NULL OR length(btrim(v_capability_key)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: external_api missing api_e.capability_key';
    END IF;
    IF length(v_capability_key) > 128 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.capability_key exceeds 128 characters';
    END IF;

    SELECT ac.client_key, ac.lifecycle_status
      INTO v_client_key, v_client_lifecycle
      FROM public.api_clients ac
      WHERE ac.id = v_source_client_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % does not exist', v_source_client_id;
    END IF;
    IF v_client_lifecycle IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % is not active', v_source_client_id;
    END IF;
    IF v_client_key IS NULL OR length(btrim(v_client_key)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % has blank client_key', v_source_client_id;
    END IF;
    IF length(v_client_key) > 128 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % client_key exceeds 128 characters', v_source_client_id;
    END IF;

    v_source_system := v_client_key;
    v_source_component := v_capability_key;
  ELSIF v_apiq_mcp THEN
    -- API-Q.9A2: API-client MCP provenance derived only from the trusted,
    -- server-established API-E MCP context. No caller metadata is consulted.
    v_auth_user := current_setting('api_e.authenticated_user_id', true);
    v_exec_user := current_setting('api_e.executing_user_id', true);
    v_client_id := current_setting('api_e.api_client_id', true);
    v_req_id := current_setting('api_e.request_id', true);
    v_capability_key := current_setting('api_e.capability_key', true);

    IF v_auth_user IS NULL OR length(btrim(v_auth_user)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: mcp missing api_e.authenticated_user_id';
    END IF;
    IF v_exec_user IS NULL OR length(btrim(v_exec_user)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: mcp missing api_e.executing_user_id';
    END IF;
    IF v_client_id IS NULL OR length(btrim(v_client_id)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: mcp missing api_e.api_client_id';
    END IF;
    IF v_req_id IS NULL OR length(btrim(v_req_id)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: mcp missing api_e.request_id';
    END IF;
    IF v_capability_key IS NULL OR length(btrim(v_capability_key)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: mcp missing api_e.capability_key';
    END IF;
    IF length(v_capability_key) > 128 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.capability_key exceeds 128 characters';
    END IF;

    BEGIN
      v_requested_user_id := v_auth_user::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.authenticated_user_id is not a valid uuid';
    END;
    BEGIN
      v_executing_user_id := v_exec_user::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.executing_user_id is not a valid uuid';
    END;
    BEGIN
      v_source_client_id := v_client_id::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_e.api_client_id is not a valid uuid';
    END;

    IF v_requested_user_id IS DISTINCT FROM v_executing_user_id THEN
      RAISE EXCEPTION 'pmg_record_command_audit: mcp requires a delegated-user identity';
    END IF;

    v_request_id := v_req_id;
    v_delegation_mode := 'delegated_user';

    SELECT ac.client_key, ac.lifecycle_status
      INTO v_client_key, v_client_lifecycle
      FROM public.api_clients ac
      WHERE ac.id = v_source_client_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % does not exist', v_source_client_id;
    END IF;
    IF v_client_lifecycle IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % is not active', v_source_client_id;
    END IF;
    IF v_client_key IS NULL OR length(btrim(v_client_key)) = 0 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % has blank client_key', v_source_client_id;
    END IF;
    IF length(v_client_key) > 128 THEN
      RAISE EXCEPTION 'pmg_record_command_audit: api_client % client_key exceeds 128 characters', v_source_client_id;
    END IF;

    v_source_system := v_client_key;
    v_source_component := v_capability_key;
  ELSE
    v_requested_user_id := NULL;
    v_executing_user_id := NULL;
    v_delegation_mode := 'system';
  END IF;

  INSERT INTO public.pmg_command_audit (
    source_channel, command, status,
    organization_id, workspace_id, project_id,
    target_type, target_id, actor_id, integration_id,
    correlation_id, idempotency_key, metadata,
    requested_user_id, executing_user_id, delegation_mode,
    source_client_id, request_id,
    source_system, source_component
  ) VALUES (
    _source_channel, _command, _status,
    v_org, v_ws, _project_id,
    _target_type, _target_id, v_actor,
    CASE WHEN _source_channel = 'external_api' OR v_apiq_mcp THEN NULL ELSE v_integration_id END,
    _correlation_id, _idempotency_key, v_metadata,
    v_requested_user_id, v_executing_user_id, v_delegation_mode,
    v_source_client_id, v_request_id,
    v_source_system, v_source_component
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: prepare_kpi_app_report_now_select(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_kpi_app_report_now_select(_mapping_id uuid, _reporting_period_start date, _reporting_period_end date) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _m record;
  _kdef record;
  _ext record;
  _snap record;
  _carry_used boolean := false;
  _reportable boolean := false;
  _reason text := NULL;
  _snapshot_creator_email text := NULL;
BEGIN
  IF NOT is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  IF _reporting_period_end < _reporting_period_start THEN
    RAISE EXCEPTION 'reporting_period_end < reporting_period_start';
  END IF;

  SELECT * INTO _m FROM public.kpi_app_mappings WHERE id = _mapping_id;
  IF _m.id IS NULL THEN
    RAISE EXCEPTION 'Mapping not found';
  END IF;

  IF NOT (is_org_admin(auth.uid(), _m.organization_id)
          OR is_workspace_admin_or_higher(auth.uid(), _m.workspace_id)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF NOT _m.is_active THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_inactive');
  END IF;

  SELECT * INTO _kdef FROM public.kpi_definitions WHERE id = _m.kpi_definition_id;
  IF _kdef.id IS NULL THEN
    RETURN json_build_object('reportable', false, 'reason', 'kpi_definition_missing');
  END IF;
  IF _kdef.is_archived THEN
    RETURN json_build_object('reportable', false, 'reason', 'kpi_definition_archived');
  END IF;
  IF _kdef.organization_id <> _m.organization_id
     OR _kdef.workspace_id <> _m.workspace_id
     OR _kdef.target_type <> 'project'
     OR _kdef.target_id <> _m.project_id THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_kpi_scope_mismatch');
  END IF;
  IF _kdef.calculation_key = 'schedule_signal' THEN
    RETURN json_build_object('reportable', false, 'reason', 'schedule_signal_not_submittable');
  END IF;

  SELECT * INTO _ext
    FROM public.kpi_app_external_kpis
   WHERE organization_id = _m.organization_id
     AND external_kpi_id = _m.external_kpi_id;
  IF _ext.id IS NULL OR NOT _ext.is_active THEN
    RETURN json_build_object('reportable', false, 'reason', 'external_catalog_inactive');
  END IF;
  IF _ext.value_type <> _kdef.value_type THEN
    RETURN json_build_object('reportable', false, 'reason', 'value_type_mismatch');
  END IF;

  SELECT * INTO _snap
    FROM public.kpi_snapshots s
   WHERE s.kpi_definition_id = _m.kpi_definition_id
     AND s.organization_id = _m.organization_id
     AND s.project_id = _m.project_id
     AND s.value_type = _kdef.value_type
     AND s.period_start = _reporting_period_start
     AND s.period_end = _reporting_period_end
   ORDER BY s.created_at DESC
   LIMIT 1;

  IF _snap.id IS NOT NULL THEN
    _reportable := true;
    _carry_used := false;
  ELSIF _m.carry_forward_allowed THEN
    SELECT * INTO _snap
      FROM public.kpi_snapshots s
     WHERE s.kpi_definition_id = _m.kpi_definition_id
       AND s.organization_id = _m.organization_id
       AND s.project_id = _m.project_id
       AND s.value_type = _kdef.value_type
       AND s.period_end IS NOT NULL
       AND s.period_end <= _reporting_period_end
     ORDER BY s.period_end DESC, s.created_at DESC
     LIMIT 1;
    IF _snap.id IS NOT NULL THEN
      _reportable := true;
      _carry_used := true;
    ELSE
      _reason := 'no_snapshot_available';
    END IF;
  ELSE
    _reason := 'no_current_period_snapshot';
  END IF;

  IF _reportable AND _m.entered_by_email_source = 'snapshot_created_by' THEN
    SELECT p.email INTO _snapshot_creator_email
      FROM public.profiles p
     WHERE p.id = _snap.created_by;
    IF _snapshot_creator_email IS NULL OR btrim(_snapshot_creator_email) = '' THEN
      _reportable := false;
      _reason := 'snapshot_created_by_email_unavailable';
    END IF;
  END IF;

  IF NOT _reportable THEN
    RETURN json_build_object(
      'reportable', false,
      'reason', _reason,
      'carry_forward_allowed', _m.carry_forward_allowed,
      'mapping', json_build_object(
        'id', _m.id,
        'organization_id', _m.organization_id,
        'workspace_id', _m.workspace_id,
        'project_id', _m.project_id,
        'kpi_definition_id', _m.kpi_definition_id,
        'external_kpi_id', _m.external_kpi_id,
        'scenario_id', _m.scenario_id,
        'currency_id', _m.currency_id,
        'reporting_frequency', _m.reporting_frequency,
        'is_active', _m.is_active,
        'carry_forward_allowed', _m.carry_forward_allowed
      ),
      'external_kpi', json_build_object(
        'external_kpi_id', _ext.external_kpi_id,
        'external_kpi_name', _ext.external_kpi_name,
        'value_type', _ext.value_type
      )
    );
  END IF;

  RETURN json_build_object(
    'reportable', true,
    'carry_forward_used', _carry_used,
    'mapping', json_build_object(
      'id', _m.id,
      'organization_id', _m.organization_id,
      'workspace_id', _m.workspace_id,
      'project_id', _m.project_id,
      'kpi_definition_id', _m.kpi_definition_id,
      'external_kpi_id', _m.external_kpi_id,
      'scenario_id', _m.scenario_id,
      'currency_id', _m.currency_id,
      'reporting_frequency', _m.reporting_frequency,
      'is_active', _m.is_active,
      'carry_forward_allowed', _m.carry_forward_allowed
    ),
    'external_kpi', json_build_object(
      'external_kpi_id', _ext.external_kpi_id,
      'external_kpi_name', _ext.external_kpi_name,
      'value_type', _ext.value_type
    ),
    'snapshot', json_build_object(
      'id', _snap.id,
      'period_start', _snap.period_start,
      'period_end', _snap.period_end,
      'value_type', _snap.value_type,
      'value_amount', _snap.value_amount,
      'text_value_present', (_snap.string_value IS NOT NULL AND length(_snap.string_value) > 0),
      'comment_present', (_snap.comment IS NOT NULL AND length(_snap.comment) > 0),
      'action_plan_present', (_snap.action_plan IS NOT NULL AND length(_snap.action_plan) > 0)
    )
  );
END;
$$;


--
-- Name: prepare_kpi_app_report_now_select_system(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_kpi_app_report_now_select_system(_mapping_id uuid, _reporting_period_start date, _reporting_period_end date) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _m record;
  _kdef record;
  _ext record;
  _snap record;
  _carry_used boolean := false;
  _reportable boolean := false;
  _reason text := NULL;
BEGIN
  IF _reporting_period_end < _reporting_period_start THEN
    RAISE EXCEPTION 'reporting_period_end < reporting_period_start';
  END IF;

  SELECT * INTO _m FROM public.kpi_app_mappings WHERE id = _mapping_id;
  IF _m.id IS NULL THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_not_found');
  END IF;

  IF NOT _m.is_active THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_inactive');
  END IF;

  IF NOT _m.auto_submit_enabled THEN
    RETURN json_build_object('reportable', false, 'reason', 'auto_submit_disabled');
  END IF;

  IF _m.reporting_frequency = 'manual_only' THEN
    RETURN json_build_object('reportable', false, 'reason', 'manual_only_not_system');
  END IF;

  -- C2.11e-correction: system mode has no human caller_email. The canonical
  -- builder rejects entered_by_email_source = submitted_by_user when
  -- caller_email is null. Reject early with a controlled reason instead of
  -- creating an outbox row that is guaranteed to fail at prepare time.
  IF _m.entered_by_email_source = 'submitted_by_user' THEN
    RETURN json_build_object(
      'reportable', false,
      'reason', 'entered_by_email_source_requires_human_user'
    );
  END IF;

  IF _m.entered_by_email_source = 'configured_user'
     AND _m.entered_by_user_id IS NULL THEN
    RETURN json_build_object(
      'reportable', false,
      'reason', 'configured_user_email_unconfigured'
    );
  END IF;

  -- KPI definition validation
  SELECT * INTO _kdef FROM public.kpi_definitions WHERE id = _m.kpi_definition_id;
  IF _kdef.id IS NULL THEN
    RETURN json_build_object('reportable', false, 'reason', 'kpi_definition_missing');
  END IF;
  IF _kdef.is_archived THEN
    RETURN json_build_object('reportable', false, 'reason', 'kpi_definition_archived');
  END IF;
  IF _kdef.organization_id <> _m.organization_id
     OR _kdef.workspace_id <> _m.workspace_id
     OR _kdef.target_type <> 'project'
     OR _kdef.target_id <> _m.project_id THEN
    RETURN json_build_object('reportable', false, 'reason', 'mapping_kpi_scope_mismatch');
  END IF;
  IF _kdef.calculation_key = 'schedule_signal' THEN
    RETURN json_build_object('reportable', false, 'reason', 'schedule_signal_not_submittable');
  END IF;

  -- External catalog validation
  SELECT * INTO _ext
    FROM public.kpi_app_external_kpis
   WHERE organization_id = _m.organization_id
     AND external_kpi_id = _m.external_kpi_id;
  IF _ext.id IS NULL OR NOT _ext.is_active THEN
    RETURN json_build_object('reportable', false, 'reason', 'external_catalog_inactive');
  END IF;
  IF _ext.value_type <> _kdef.value_type THEN
    RETURN json_build_object('reportable', false, 'reason', 'value_type_mismatch');
  END IF;

  -- A) Current-period snapshot (exact match)
  SELECT * INTO _snap
    FROM public.kpi_snapshots s
   WHERE s.kpi_definition_id = _m.kpi_definition_id
     AND s.organization_id = _m.organization_id
     AND s.project_id = _m.project_id
     AND s.value_type = _kdef.value_type
     AND s.period_start = _reporting_period_start
     AND s.period_end = _reporting_period_end
   ORDER BY s.created_at DESC
   LIMIT 1;

  IF _snap.id IS NOT NULL THEN
    _reportable := true;
    _carry_used := false;
  ELSIF _m.carry_forward_allowed THEN
    SELECT * INTO _snap
      FROM public.kpi_snapshots s
     WHERE s.kpi_definition_id = _m.kpi_definition_id
       AND s.organization_id = _m.organization_id
       AND s.project_id = _m.project_id
       AND s.value_type = _kdef.value_type
       AND s.period_end IS NOT NULL
       AND s.period_end <= _reporting_period_end
     ORDER BY s.period_end DESC, s.created_at DESC
     LIMIT 1;
    IF _snap.id IS NOT NULL THEN
      _reportable := true;
      _carry_used := true;
    ELSE
      _reason := 'no_snapshot_available';
    END IF;
  ELSE
    _reason := 'no_current_period_snapshot';
  END IF;

  IF NOT _reportable THEN
    RETURN json_build_object(
      'reportable', false,
      'reason', _reason,
      'carry_forward_allowed', _m.carry_forward_allowed,
      'mapping', json_build_object(
        'id', _m.id,
        'organization_id', _m.organization_id,
        'workspace_id', _m.workspace_id,
        'project_id', _m.project_id,
        'kpi_definition_id', _m.kpi_definition_id,
        'external_kpi_id', _m.external_kpi_id,
        'scenario_id', _m.scenario_id,
        'currency_id', _m.currency_id,
        'reporting_frequency', _m.reporting_frequency,
        'is_active', _m.is_active,
        'carry_forward_allowed', _m.carry_forward_allowed
      ),
      'external_kpi', json_build_object(
        'external_kpi_id', _ext.external_kpi_id,
        'external_kpi_name', _ext.external_kpi_name,
        'value_type', _ext.value_type
      )
    );
  END IF;

  RETURN json_build_object(
    'reportable', true,
    'carry_forward_used', _carry_used,
    'mapping', json_build_object(
      'id', _m.id,
      'organization_id', _m.organization_id,
      'workspace_id', _m.workspace_id,
      'project_id', _m.project_id,
      'kpi_definition_id', _m.kpi_definition_id,
      'external_kpi_id', _m.external_kpi_id,
      'scenario_id', _m.scenario_id,
      'currency_id', _m.currency_id,
      'reporting_frequency', _m.reporting_frequency,
      'is_active', _m.is_active,
      'carry_forward_allowed', _m.carry_forward_allowed
    ),
    'external_kpi', json_build_object(
      'external_kpi_id', _ext.external_kpi_id,
      'external_kpi_name', _ext.external_kpi_name,
      'value_type', _ext.value_type
    ),
    'snapshot', json_build_object(
      'id', _snap.id,
      'period_start', _snap.period_start,
      'period_end', _snap.period_end,
      'value_type', _snap.value_type,
      'value_amount', _snap.value_amount,
      'text_value_present', (_snap.string_value IS NOT NULL AND length(_snap.string_value) > 0),
      'comment_present', (_snap.comment IS NOT NULL AND length(_snap.comment) > 0),
      'action_plan_present', (_snap.action_plan IS NOT NULL AND length(_snap.action_plan) > 0)
    )
  );
END;
$$;


--
-- Name: prevent_last_org_admin_removal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_last_org_admin_removal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _remaining INT;
BEGIN
  -- Only guard org_admin role deletions
  IF OLD.role != 'org_admin' OR OLD.workspace_id IS NOT NULL THEN
    RETURN OLD;
  END IF;

  SELECT count(*) INTO _remaining
  FROM public.user_roles
  WHERE organization_id = OLD.organization_id
    AND role = 'org_admin'
    AND workspace_id IS NULL
    AND id != OLD.id;

  IF _remaining < 1 THEN
    RAISE EXCEPTION 'Cannot remove the last organization admin';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: prevent_last_workspace_admin_removal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_last_workspace_admin_removal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE _remaining INT;
BEGIN
  IF OLD.role != 'workspace_admin' OR OLD.workspace_id IS NULL THEN RETURN OLD; END IF;
  SELECT count(*) INTO _remaining FROM public.user_roles
    WHERE workspace_id = OLD.workspace_id AND role = 'workspace_admin' AND id != OLD.id;
  IF _remaining < 1 THEN RAISE EXCEPTION 'Cannot remove the last workspace admin'; END IF;
  RETURN OLD;
END; $$;


--
-- Name: prevent_self_org_admin_removal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_self_org_admin_removal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.role = 'org_admin' AND OLD.workspace_id IS NULL AND OLD.user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot remove your own organization admin role';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: preview_adoption_template(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_adoption_template(_workspace_id uuid, _template_id uuid DEFAULT NULL::uuid, _template_key text DEFAULT 'btpm_standard_adoption'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _org uuid;
  _t record;
  _initiatives jsonb := '[]'::jsonb;
  _i record;
  _tasks jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT organization_id INTO _org FROM public.workspaces WHERE id = _workspace_id;
  IF _org IS NULL THEN
    RAISE EXCEPTION 'invalid_workspace';
  END IF;
  IF NOT (public.is_workspace_member(_uid, _workspace_id)
          OR public.is_org_admin(_uid, _org)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Standard template
  IF _template_id IS NULL THEN
    IF COALESCE(_template_key, '') <> 'btpm_standard_adoption' THEN
      RAISE EXCEPTION 'invalid_template_key';
    END IF;
    SELECT jsonb_agg(
      jsonb_build_object(
        'key', i->>'key',
        'name', i->>'name',
        'readiness_area', i->>'readiness_area',
        'sort_order', (i->>'sort_order')::int,
        'summary', i->>'summary',
        'default_selected', true,
        'tasks', (
          SELECT jsonb_agg(jsonb_build_object(
            'key', t->>'key',
            'title', t->>'title',
            'description', NULL,
            'default_selected', true,
            'is_custom', false
          ))
          FROM jsonb_array_elements(i->'tasks') AS t
        )
      )
    ) INTO _initiatives FROM jsonb_array_elements(public._btpm_adoption_template_v1()) AS i;

    RETURN jsonb_build_object(
      'template_id', NULL,
      'template_key', 'btpm_standard_adoption',
      'name', 'BTPM Standard Adoption Plan',
      'description', 'The built-in BTPM adoption template.',
      'is_system', true,
      'editable', false,
      'scope', 'system',
      'source_template_key', NULL,
      'initiatives', COALESCE(_initiatives, '[]'::jsonb)
    );
  END IF;

  -- Saved custom template
  SELECT * INTO _t FROM public.adoption_templates WHERE id = _template_id;
  IF _t.id IS NULL THEN
    RAISE EXCEPTION 'invalid_template';
  END IF;
  IF _t.workspace_id <> _workspace_id THEN
    RAISE EXCEPTION 'template_workspace_mismatch';
  END IF;
  IF NOT (public.is_workspace_member(_uid, _t.workspace_id)
          OR public.is_org_admin(_uid, _t.organization_id)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'key', i.template_key,
      'name', public.btpm_decrypt(i.name, i.organization_id),
      'readiness_area', i.readiness_area,
      'sort_order', i.sort_order,
      'summary', public.btpm_decrypt(i.summary, i.organization_id),
      'default_selected', i.default_selected,
      'tasks', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'key', tk.template_key,
          'title', public.btpm_decrypt(tk.title, tk.organization_id),
          'description', public.btpm_decrypt(tk.description, tk.organization_id),
          'default_selected', tk.default_selected,
          'is_custom', tk.is_custom
        ) ORDER BY tk.sort_order, tk.template_key)
        FROM public.adoption_template_tasks tk
        WHERE tk.adoption_template_initiative_id = i.id
          AND tk.is_archived = false
      ), '[]'::jsonb)
    ) ORDER BY i.sort_order, i.template_key
  ) INTO _initiatives
  FROM public.adoption_template_initiatives i
  WHERE i.adoption_template_id = _t.id AND i.is_archived = false;

  RETURN jsonb_build_object(
    'template_id', _t.id,
    'template_key', NULL,
    'name', public.btpm_decrypt(_t.name, _t.organization_id),
    'description', public.btpm_decrypt(_t.description, _t.organization_id),
    'is_system', false,
    'editable', true,
    'scope', _t.scope,
    'source_template_key', _t.source_template_key,
    'initiatives', COALESCE(_initiatives, '[]'::jsonb)
  );
END $$;


--
-- Name: preview_phase_clone_blueprint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_phase_clone_blueprint(_phase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  _caller uuid;
  _phase public.phases%ROWTYPE;
  _org uuid;
  _ws  uuid;
  _proj uuid;
  _anchor date;
  _schedule_mode text;
  _anchor_source text;

  _phase_obj jsonb;
  _tasks jsonb;
  _deps jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  _caller := auth.uid();

  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  IF NOT public.is_active_user(_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _phase FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'phase not found';
  END IF;

  _org  := _phase.organization_id;
  _ws   := _phase.workspace_id;
  _proj := _phase.project_id;

  IF public.is_user_org_member(_caller, _org) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_pm_authority(_caller, _ws) THEN
    RAISE EXCEPTION 'PM authority required for phase clone blueprint';
  END IF;

  _anchor := public._clone_anchor_for_phase(_phase_id);
  IF _anchor IS NULL THEN
    _schedule_mode := 'unscheduled';
    _anchor_source := NULL;
  ELSIF _phase.start_date IS NOT NULL THEN
    _schedule_mode := 'relative';
    _anchor_source := 'phase_start_date';
  ELSE
    _schedule_mode := 'relative';
    _anchor_source := 'earliest_planning_date';
  END IF;

  _phase_obj := jsonb_build_object(
    'name', public.btpm_decrypt(_phase.name, _org),
    'description', public.btpm_decrypt(_phase.description, _org),
    'phase_type', _phase.phase_type,
    'sort_order_provenance', _phase.sort_order,
    'schedule', jsonb_build_object(
      'start_offset_days',      public._clone_offset_days(_anchor, _phase.start_date),
      'target_end_offset_days', public._clone_offset_days(_anchor, _phase.target_end_date)
    )
  );

  -- Tasks within this phase
  WITH tk AS (
    SELECT 'task_' || ROW_NUMBER() OVER (ORDER BY t.sort_order, t.created_at) AS ref, t.*
    FROM public.tasks t
    WHERE t.phase_id = _phase_id AND t.is_archived = false
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'ref', ref,
    'source_id', id,
    'phase_ref', 'phase_1',
    'name', public.btpm_decrypt(name, _org),
    'description', public.btpm_decrypt(description, _org),
    'task_type', task_type,
    'priority', priority,
    'estimated_hours', estimated_hours,
    'sort_order', sort_order,
    'backlog_item_provenance_id', backlog_item_id,
    'schedule', jsonb_build_object(
      'start_offset_days', public._clone_offset_days(_anchor, start_date),
      'due_offset_days',   public._clone_offset_days(_anchor, due_date)
    )
  ) ORDER BY sort_order), '[]'::jsonb) INTO _tasks FROM tk;

  -- Internal task-to-task dependencies only — both ends inside this phase
  WITH tk AS (
    SELECT 'task_' || ROW_NUMBER() OVER (ORDER BY t.sort_order, t.created_at) AS ref, t.id
    FROM public.tasks t
    WHERE t.phase_id = _phase_id AND t.is_archived = false
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'entity_type', 'task',
    'source_ref', src.ref,
    'target_ref', tgt.ref,
    'dependency_type', d.dependency_type,
    'description', public.btpm_decrypt(d.description, _org)
  )), '[]'::jsonb) INTO _deps
  FROM public.dependencies d
  JOIN tk src ON d.source_type = 'task' AND d.source_id = src.id
  JOIN tk tgt ON d.target_type = 'task' AND d.target_id = tgt.id;

  RETURN jsonb_build_object(
    'version', 'clone_blueprint_v1',
    'blueprint_kind', 'phase',
    'saved_at', to_jsonb(now()),
    'schedule_mode', _schedule_mode,
    'anchor_source', _anchor_source,
    'anchor_date', _anchor,
    'source', jsonb_build_object(
      'organization_id', _org,
      'workspace_id', _ws,
      'project_id', _proj,
      'phase_id', _phase_id
    ),
    'project', NULL,
    'phase', _phase_obj,
    'phases', jsonb_build_array(jsonb_build_object('ref','phase_1') || _phase_obj),
    'tasks',  _tasks,
    'dependencies', _deps,
    'kpi_definitions', '[]'::jsonb,
    'agile', jsonb_build_object(
      'enabled', false,
      'workflow_states', '[]'::jsonb,
      'sprints', '[]'::jsonb,
      'backlog_items', '[]'::jsonb
    )
  );
END;
$$;


--
-- Name: preview_phase_clone_in_project(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_phase_clone_in_project(_phase_id uuid, _phase_start_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _bp jsonb;
  _src_phase RECORD;
  _proj RECORD;
  _tk jsonb;
  _start_off int; _due_off int; _end_off int;
  _new_phase_start date; _new_phase_end date;
  _eff_start date; _eff_end date;
  _reasons jsonb := '[]'::jsonb;
  _requires boolean := false;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT id, project_id, workspace_id, organization_id, name
    INTO _src_phase
  FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;

  IF NOT public.has_pm_authority(_caller, _src_phase.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  SELECT id, name, start_date, target_end_date
    INTO _proj
  FROM public.projects WHERE id = _src_phase.project_id;

  _bp := public.preview_phase_clone_blueprint(_phase_id);

  IF _phase_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
    RETURN jsonb_build_object(
      'requires_widening', false,
      'schedule_mode_applied',
        CASE WHEN _phase_start_date IS NULL THEN 'unscheduled_seeded_start_only'
             ELSE 'unscheduled_seeded_start_only' END,
      'parent_project_id', _proj.id,
      'parent_project_name', _proj.name,
      'parent_current_start', _proj.start_date,
      'parent_current_end', _proj.target_end_date,
      'parent_proposed_start', _proj.start_date,
      'parent_proposed_end', _proj.target_end_date
    );
  END IF;

  -- Compute new phase + task window from blueprint offsets and _phase_start_date
  _start_off := NULLIF(_bp->'phase'->'schedule'->>'start_offset_days','')::int;
  _end_off   := NULLIF(_bp->'phase'->'schedule'->>'target_end_offset_days','')::int;
  _new_phase_start := CASE WHEN _start_off IS NOT NULL THEN _phase_start_date + _start_off ELSE _phase_start_date END;
  _new_phase_end   := CASE WHEN _end_off   IS NOT NULL THEN _phase_start_date + _end_off   ELSE NULL END;

  _eff_start := _new_phase_start;
  _eff_end := _new_phase_end;

  FOR _tk IN SELECT * FROM jsonb_array_elements(COALESCE(_bp->'tasks','[]'::jsonb)) LOOP
    _start_off := NULLIF(_tk->'schedule'->>'start_offset_days','')::int;
    _due_off   := NULLIF(_tk->'schedule'->>'due_offset_days','')::int;
    IF _start_off IS NOT NULL THEN
      IF _eff_start IS NULL OR (_phase_start_date + _start_off) < _eff_start THEN
        _eff_start := _phase_start_date + _start_off;
      END IF;
    END IF;
    IF _due_off IS NOT NULL THEN
      IF _eff_end IS NULL OR (_phase_start_date + _due_off) > _eff_end THEN
        _eff_end := _phase_start_date + _due_off;
      END IF;
    END IF;
  END LOOP;

  -- Compare against parent project window
  IF _proj.start_date IS NOT NULL AND _eff_start IS NOT NULL AND _eff_start < _proj.start_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','phase_before_project','date', _eff_start);
  END IF;
  IF _proj.target_end_date IS NOT NULL AND _eff_end IS NOT NULL AND _eff_end > _proj.target_end_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','phase_after_project','date', _eff_end);
  END IF;

  RETURN jsonb_build_object(
    'requires_widening', _requires,
    'schedule_mode_applied','relative_reanchored',
    'parent_project_id', _proj.id,
    'parent_project_name', _proj.name,
    'parent_current_start', _proj.start_date,
    'parent_current_end', _proj.target_end_date,
    'parent_proposed_start',
        CASE WHEN _eff_start IS NOT NULL AND (_proj.start_date IS NULL OR _eff_start < _proj.start_date)
             THEN _eff_start ELSE _proj.start_date END,
    'parent_proposed_end',
        CASE WHEN _eff_end IS NOT NULL AND (_proj.target_end_date IS NULL OR _eff_end > _proj.target_end_date)
             THEN _eff_end ELSE _proj.target_end_date END,
    'phase_proposed_start', _new_phase_start,
    'phase_proposed_end', _new_phase_end,
    'reasons', _reasons
  );
END;
$$;


--
-- Name: preview_phase_planning_change(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_phase_planning_change(_phase_id uuid, _new_start date, _new_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  ph record;
  pr record;
  bad_child record;
  needs_ext boolean := false;
  proposed_start date;
  proposed_end   date;
BEGIN
  SELECT id, project_id, workspace_id, status, is_archived, start_date, target_end_date, name
    INTO ph
    FROM public.phases
   WHERE id = _phase_id;

  IF ph.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_not_found');
  END IF;

  IF NOT public.is_workspace_admin_or_higher(auth.uid(), ph.workspace_id) THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'not_authorized');
  END IF;

  IF ph.status = 'completed' THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_completed_locked');
  END IF;
  IF ph.status = 'cancelled' OR ph.is_archived THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_cancelled_or_archived');
  END IF;

  IF _new_start IS NOT NULL AND _new_end IS NOT NULL AND _new_end < _new_start THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'invalid_range');
  END IF;

  -- Cannot shrink under existing children
  SELECT name, start_date AS d INTO bad_child
    FROM public.tasks
   WHERE phase_id = ph.id
     AND status <> 'cancelled' AND NOT is_archived
     AND start_date IS NOT NULL
     AND _new_start IS NOT NULL
     AND start_date < _new_start
   ORDER BY start_date ASC LIMIT 1;
  IF bad_child.name IS NOT NULL THEN
    RETURN jsonb_build_object('blocked', true,
      'blocked_reason', format('phase_shrinks_under_child_start:%s:%s', bad_child.name, bad_child.d));
  END IF;

  SELECT name, due_date AS d INTO bad_child
    FROM public.tasks
   WHERE phase_id = ph.id
     AND status <> 'cancelled' AND NOT is_archived
     AND due_date IS NOT NULL
     AND _new_end IS NOT NULL
     AND due_date > _new_end
   ORDER BY due_date DESC LIMIT 1;
  IF bad_child.name IS NOT NULL THEN
    RETURN jsonb_build_object('blocked', true,
      'blocked_reason', format('phase_shrinks_under_child_end:%s:%s', bad_child.name, bad_child.d));
  END IF;

  -- Project containment
  SELECT id, name, start_date, target_end_date
    INTO pr
    FROM public.projects
   WHERE id = ph.project_id;

  IF pr.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'project_not_found');
  END IF;

  proposed_start := pr.start_date;
  proposed_end   := pr.target_end_date;

  IF _new_start IS NOT NULL AND pr.start_date IS NOT NULL AND _new_start < pr.start_date THEN
    needs_ext := true; proposed_start := _new_start;
  END IF;
  IF _new_end IS NOT NULL AND pr.target_end_date IS NOT NULL AND _new_end > pr.target_end_date THEN
    needs_ext := true; proposed_end := _new_end;
  END IF;

  RETURN jsonb_build_object(
    'valid', NOT needs_ext,
    'requires_extension', needs_ext,
    'blocked', false,
    'blocked_reason', NULL,
    'parent_project_id', pr.id,
    'parent_project_name', pr.name,
    'parent_current_start', pr.start_date,
    'parent_current_end',   pr.target_end_date,
    'parent_proposed_start', proposed_start,
    'parent_proposed_end',   proposed_end
  );
END;
$$;


--
-- Name: preview_phase_timeline_action(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_phase_timeline_action(_phase_id uuid, _action text, _new_start date, _new_end date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_phase   public.phases%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_uid     uuid := auth.uid();

  v_delta_days   int;
  v_executed_cnt int := 0;
  v_active_cnt   int := 0;
  v_movable_cnt  int := 0;

  v_resolved_action text;
  v_proposed_start  date := _new_start;
  v_proposed_end    date := _new_end;

  v_proj_proposed_start date;
  v_proj_proposed_end   date;
  v_requires_proj_ext   boolean := false;

  v_anchor_min_start date;
  v_anchor_max_end   date;

  v_blocking_child_name text;
  v_blocking_child_date date;
BEGIN
  SELECT * INTO v_phase FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'phase_not_found');
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = v_phase.project_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'project_not_found');
  END IF;

  -- Authorization: PM/workspace-admin or higher.
  IF NOT public.is_workspace_admin_or_higher(v_uid, v_phase.workspace_id)
     AND NOT public.has_pm_authority(v_uid, v_phase.workspace_id) THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'not_authorized');
  END IF;

  -- Lifecycle guards (mirror 4F.2).
  IF v_phase.is_archived OR v_phase.status = 'cancelled' THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'phase_cancelled_or_archived');
  END IF;
  IF v_phase.status = 'completed' THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'phase_completed_locked');
  END IF;

  IF _new_start IS NULL OR _new_end IS NULL OR _new_end < _new_start THEN
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'invalid_range');
  END IF;

  -- Count executed/active/movable children (eligible = not archived, not cancelled).
  SELECT
    COUNT(*) FILTER (WHERE actual_start_date IS NOT NULL),
    COUNT(*) FILTER (WHERE status = 'completed' OR actual_end_date IS NOT NULL),
    COUNT(*) FILTER (WHERE actual_start_date IS NULL AND actual_end_date IS NULL
                       AND status <> 'completed')
  INTO v_executed_cnt, v_active_cnt, v_movable_cnt
  FROM public.tasks
  WHERE phase_id = _phase_id
    AND is_archived = false
    AND status <> 'cancelled';

  -- Anchored window across executed/completed children (used for resize floor).
  SELECT
    MIN(COALESCE(actual_start_date, start_date)),
    MAX(COALESCE(actual_end_date, due_date))
  INTO v_anchor_min_start, v_anchor_max_end
  FROM public.tasks
  WHERE phase_id = _phase_id
    AND is_archived = false
    AND status <> 'cancelled'
    AND (actual_start_date IS NOT NULL OR status = 'completed');

  IF _action = 'drag' THEN
    v_delta_days := (_new_start - v_phase.start_date);

    IF v_executed_cnt > 0 THEN
      -- Shift remaining work: only not-started movable children shift.
      v_resolved_action := 'shift_remaining_work';

      -- Recompute phase window so it contains BOTH anchored work and shifted
      -- not-started work. We use the proposed delta on the not-started children.
      SELECT
        LEAST(
          COALESCE(MIN(start_date) + v_delta_days, _new_start),
          COALESCE(v_anchor_min_start, _new_start)
        ),
        GREATEST(
          COALESCE(MAX(due_date)   + v_delta_days, _new_end),
          COALESCE(v_anchor_max_end, _new_end)
        )
      INTO v_proposed_start, v_proposed_end
      FROM public.tasks
      WHERE phase_id = _phase_id
        AND is_archived = false
        AND status <> 'cancelled'
        AND actual_start_date IS NULL
        AND actual_end_date IS NULL
        AND status <> 'completed'
        AND start_date IS NOT NULL
        AND due_date   IS NOT NULL;

      IF v_proposed_start IS NULL THEN v_proposed_start := _new_start; END IF;
      IF v_proposed_end   IS NULL THEN v_proposed_end   := _new_end;   END IF;

    ELSE
      v_resolved_action := 'move_phase_plan';
      v_proposed_start := _new_start;
      v_proposed_end   := _new_end;
    END IF;

  ELSIF _action = 'resize' THEN
    v_resolved_action := 'resize_phase';
    v_proposed_start := _new_start;
    v_proposed_end   := _new_end;

    -- Shrinking under anchored or active planned child work is blocked.
    -- Check anchored floor.
    IF v_anchor_min_start IS NOT NULL AND _new_start > v_anchor_min_start THEN
      v_blocking_child_name := 'anchored work';
      v_blocking_child_date := v_anchor_min_start;
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_start:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;
    IF v_anchor_max_end IS NOT NULL AND _new_end < v_anchor_max_end THEN
      v_blocking_child_name := 'anchored work';
      v_blocking_child_date := v_anchor_max_end;
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_end:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;

    -- Check planned floor (any not-cancelled child).
    SELECT name, start_date INTO v_blocking_child_name, v_blocking_child_date
    FROM public.tasks
    WHERE phase_id = _phase_id
      AND is_archived = false
      AND status <> 'cancelled'
      AND start_date IS NOT NULL
      AND start_date < _new_start
    ORDER BY start_date ASC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_start:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;
    SELECT name, due_date INTO v_blocking_child_name, v_blocking_child_date
    FROM public.tasks
    WHERE phase_id = _phase_id
      AND is_archived = false
      AND status <> 'cancelled'
      AND due_date IS NOT NULL
      AND due_date > _new_end
    ORDER BY due_date DESC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'valid', false, 'blocked', true,
        'blocked_reason', 'phase_shrinks_under_child_end:' || v_blocking_child_name || ':' || v_blocking_child_date::text,
        'has_executed_children', v_executed_cnt > 0
      );
    END IF;
  ELSE
    RETURN jsonb_build_object('valid', false, 'blocked', true, 'blocked_reason', 'invalid_action');
  END IF;

  -- Project extension check.
  IF v_project.start_date IS NOT NULL AND v_proposed_start < v_project.start_date THEN
    v_requires_proj_ext := true;
    v_proj_proposed_start := v_proposed_start;
  ELSE
    v_proj_proposed_start := v_project.start_date;
  END IF;

  IF v_project.target_end_date IS NOT NULL AND v_proposed_end > v_project.target_end_date THEN
    v_requires_proj_ext := true;
    v_proj_proposed_end := v_proposed_end;
  ELSE
    v_proj_proposed_end := v_project.target_end_date;
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'blocked', false,
    'blocked_reason', NULL,
    'resolved_action', v_resolved_action,
    'has_executed_children', v_executed_cnt > 0,
    'requires_project_extension', v_requires_proj_ext,
    'requires_extension', v_requires_proj_ext,
    'phase_id', v_phase.id,
    'phase_name', v_phase.name,
    'phase_current_start', v_phase.start_date,
    'phase_current_end',   v_phase.target_end_date,
    'phase_proposed_start', v_proposed_start,
    'phase_proposed_end',   v_proposed_end,
    'parent_project_id', v_project.id,
    'parent_project_name', v_project.name,
    'parent_current_start', v_project.start_date,
    'parent_current_end',   v_project.target_end_date,
    'parent_proposed_start', v_proj_proposed_start,
    'parent_proposed_end',   v_proj_proposed_end,
    'moved_children_count', CASE WHEN v_resolved_action = 'shift_remaining_work' THEN v_movable_cnt
                                 WHEN v_resolved_action = 'move_phase_plan' THEN v_movable_cnt + v_active_cnt
                                 ELSE 0 END,
    'anchored_children_count', v_executed_cnt,
    'delta_days', v_delta_days
  );
END;
$$;


--
-- Name: preview_project_adoption_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_project_adoption_template(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _proj_start date;
  _proj_end date;
  _sug_start date;
  _sug_end date;
  _date_source text := 'none';
  _initiatives jsonb;
  _enriched jsonb := '[]'::jsonb;
  _i jsonb;
  _task_count int := 0;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  SELECT start_date, target_end_date INTO _proj_start, _proj_end
  FROM public.projects WHERE id = _project_id;
  IF _proj_start IS NULL AND _proj_end IS NULL AND NOT EXISTS (
    SELECT 1 FROM public.projects WHERE id = _project_id
  ) THEN
    RAISE EXCEPTION 'invalid_project';
  END IF;
  IF NOT public.has_project_access(_uid, _project_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Date suggestion: project > phases > tasks > none
  IF _proj_start IS NOT NULL OR _proj_end IS NOT NULL THEN
    _sug_start := _proj_start;
    _sug_end   := _proj_end;
    _date_source := 'project_dates';
  ELSE
    SELECT MIN(start_date), MAX(target_end_date)
      INTO _sug_start, _sug_end
    FROM public.phases
    WHERE project_id = _project_id AND is_archived = false;
    IF _sug_start IS NOT NULL OR _sug_end IS NOT NULL THEN
      _date_source := 'phase_dates';
    ELSE
      SELECT MIN(start_date), MAX(due_date)
        INTO _sug_start, _sug_end
      FROM public.tasks
      WHERE project_id = _project_id AND is_archived = false;
      IF _sug_start IS NOT NULL OR _sug_end IS NOT NULL THEN
        _date_source := 'task_dates';
      END IF;
    END IF;
  END IF;

  _initiatives := public._btpm_adoption_template_v1();

  FOR _i IN SELECT * FROM jsonb_array_elements(_initiatives)
  LOOP
    _enriched := _enriched || jsonb_build_array(
      jsonb_build_object(
        'key', _i->>'key',
        'name', _i->>'name',
        'readiness_area', _i->>'readiness_area',
        'sort_order', (_i->>'sort_order')::int,
        'summary', _i->>'summary',
        'default_selected', true,
        'tasks', (
          SELECT jsonb_agg(jsonb_build_object(
            'key', t->>'key',
            'title', t->>'title',
            'description', NULL,
            'default_selected', true
          ))
          FROM jsonb_array_elements(_i->'tasks') AS t
        )
      )
    );
    _task_count := _task_count + jsonb_array_length(_i->'tasks');
  END LOOP;

  RETURN jsonb_build_object(
    'project_id', _project_id,
    'template_key', 'btpm_standard_adoption',
    'template_name', 'BTPM Standard Adoption Plan',
    'recommended_phase_name', 'Adoption & Readiness',
    'creates_normal_phase', true,
    'creates_normal_tasks', true,
    'dates_auto_populated', _date_source <> 'none',
    'suggested_phase_start_date', _sug_start,
    'suggested_phase_end_date',   _sug_end,
    'date_source', _date_source,
    'initiative_count', jsonb_array_length(_enriched),
    'task_count', _task_count,
    'initiatives', _enriched
  );
END $$;


--
-- Name: preview_project_clone_blueprint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_project_clone_blueprint(_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _project public.projects%ROWTYPE; _org uuid; _ws uuid; _anchor date;
  _schedule_mode text; _anchor_source text;
  _project_obj jsonb; _phases jsonb; _tasks jsonb; _deps jsonb; _kpis jsonb;
  _agile jsonb; _states jsonb; _sprints jsonb; _backlog jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT * INTO _project FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'project not found'; END IF;
  _org := _project.organization_id; _ws := _project.workspace_id;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'PM authority required for project clone blueprint'; END IF;
  _anchor := public._clone_anchor_for_project(_project_id);
  IF _anchor IS NULL THEN _schedule_mode := 'unscheduled'; _anchor_source := NULL;
  ELSIF _project.start_date IS NOT NULL THEN _schedule_mode := 'relative'; _anchor_source := 'project_start_date';
  ELSE _schedule_mode := 'relative'; _anchor_source := 'earliest_planning_date'; END IF;
  _project_obj := jsonb_build_object('name', _project.name,
    'description', public.btpm_decrypt(_project.description, _org),
    'charter', public.btpm_decrypt(_project.charter, _org),
    'goals', public.btpm_decrypt(_project.goals, _org),
    'scope_in', public.btpm_decrypt(_project.scope_in, _org),
    'scope_out', public.btpm_decrypt(_project.scope_out, _org),
    'priority', _project.priority, 'agile_enabled', _project.agile_enabled,
    'schedule', jsonb_build_object(
      'start_offset_days', public._clone_offset_days(_anchor, _project.start_date),
      'target_end_offset_days', public._clone_offset_days(_anchor, _project.target_end_date)));
  WITH ph AS (SELECT 'phase_' || ROW_NUMBER() OVER (ORDER BY p.sort_order, p.created_at) AS ref, p.*
    FROM public.phases p WHERE p.project_id = _project_id AND p.is_archived = false)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('ref', ref, 'source_id', id,
    'name', public.btpm_decrypt(name, _org),
    'description', public.btpm_decrypt(description, _org),
    'phase_type', phase_type, 'sort_order', sort_order,
    'schedule', jsonb_build_object(
      'start_offset_days', public._clone_offset_days(_anchor, start_date),
      'target_end_offset_days', public._clone_offset_days(_anchor, target_end_date))
  ) ORDER BY sort_order), '[]'::jsonb) INTO _phases FROM ph;
  WITH ph AS (SELECT 'phase_' || ROW_NUMBER() OVER (ORDER BY p.sort_order, p.created_at) AS ref, p.id
    FROM public.phases p WHERE p.project_id = _project_id AND p.is_archived = false),
  bi AS (SELECT 'backlog_' || ROW_NUMBER() OVER (ORDER BY b.sort_order, b.created_at) AS ref, b.id
    FROM public.backlog_items b WHERE b.project_id = _project_id AND b.is_archived = false),
  ws AS (SELECT 'state_' || ROW_NUMBER() OVER (ORDER BY w.sort_order, w.created_at) AS ref, w.id
    FROM public.board_workflow_states w WHERE w.project_id = _project_id AND w.is_archived = false),
  tk AS (SELECT 'task_' || ROW_NUMBER() OVER (ORDER BY t.phase_id, t.sort_order, t.created_at) AS ref,
    t.*, ph.ref AS phase_ref, bi.ref AS backlog_ref, ws.ref AS state_ref
    FROM public.tasks t JOIN ph ON ph.id = t.phase_id
    LEFT JOIN bi ON bi.id = t.backlog_item_id
    LEFT JOIN ws ON ws.id = t.workflow_state_id
    WHERE t.project_id = _project_id AND t.is_archived = false)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('ref', ref, 'source_id', id, 'phase_ref', phase_ref,
    'name', public.btpm_decrypt(name, _org),
    'description', public.btpm_decrypt(description, _org),
    'task_type', task_type, 'priority', priority, 'estimated_hours', estimated_hours,
    'sort_order', sort_order, 'backlog_item_ref', backlog_ref, 'workflow_state_ref', state_ref,
    'schedule', jsonb_build_object(
      'start_offset_days', public._clone_offset_days(_anchor, start_date),
      'due_offset_days', public._clone_offset_days(_anchor, due_date))
  ) ORDER BY phase_ref, sort_order), '[]'::jsonb) INTO _tasks FROM tk;
  WITH ph AS (SELECT 'phase_' || ROW_NUMBER() OVER (ORDER BY p.sort_order, p.created_at) AS ref, p.id
    FROM public.phases p WHERE p.project_id = _project_id AND p.is_archived = false),
  tk AS (SELECT 'task_' || ROW_NUMBER() OVER (ORDER BY t.phase_id, t.sort_order, t.created_at) AS ref, t.id
    FROM public.tasks t WHERE t.project_id = _project_id AND t.is_archived = false),
  ph_deps AS (SELECT 'phase' AS entity_type, src.ref AS source_ref, tgt.ref AS target_ref,
    d.dependency_type, public.btpm_decrypt(d.description, _org) AS description
    FROM public.dependencies d JOIN ph src ON d.source_type = 'phase' AND d.source_id = src.id
    JOIN ph tgt ON d.target_type = 'phase' AND d.target_id = tgt.id),
  tk_deps AS (SELECT 'task' AS entity_type, src.ref AS source_ref, tgt.ref AS target_ref,
    d.dependency_type, public.btpm_decrypt(d.description, _org) AS description
    FROM public.dependencies d JOIN tk src ON d.source_type = 'task' AND d.source_id = src.id
    JOIN tk tgt ON d.target_type = 'task' AND d.target_id = tgt.id),
  all_deps AS (SELECT * FROM ph_deps UNION ALL SELECT * FROM tk_deps)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('entity_type', entity_type, 'source_ref', source_ref,
    'target_ref', target_ref, 'dependency_type', dependency_type, 'description', description)),
    '[]'::jsonb) INTO _deps FROM all_deps;
  WITH k AS (SELECT 'kpi_' || ROW_NUMBER() OVER (ORDER BY kd.created_at) AS ref, kd.*
    FROM public.kpi_definitions kd WHERE kd.target_type='project' AND kd.target_id=_project_id AND kd.is_archived=false)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('ref', ref, 'source_id', id,
    'name', public.btpm_decrypt(name, _org),
    'description', public.btpm_decrypt(description, _org),
    'unit', unit, 'target_value', target_value, 'target_direction', target_direction)),
    '[]'::jsonb) INTO _kpis FROM k;
  IF _project.agile_enabled THEN
    WITH ws AS (SELECT 'state_' || ROW_NUMBER() OVER (ORDER BY w.sort_order, w.created_at) AS ref, w.*
      FROM public.board_workflow_states w WHERE w.project_id=_project_id AND w.is_archived=false)
    SELECT COALESCE(jsonb_agg(jsonb_build_object('ref', ref, 'source_id', id,
      'name', public.btpm_decrypt(name, _org), 'category', category, 'sort_order', sort_order)
      ORDER BY sort_order), '[]'::jsonb) INTO _states FROM ws;
    WITH sp AS (SELECT 'sprint_' || ROW_NUMBER() OVER (ORDER BY s.sort_order, s.created_at) AS ref, s.*
      FROM public.sprints s WHERE s.project_id=_project_id AND s.is_archived=false)
    SELECT COALESCE(jsonb_agg(jsonb_build_object('ref', ref, 'source_id', id, 'name', name,
      'goal', public.btpm_decrypt(goal, _org), 'sort_order', sort_order,
      'schedule', jsonb_build_object(
        'start_offset_days', public._clone_offset_days(_anchor, start_date),
        'end_offset_days', public._clone_offset_days(_anchor, end_date)))
      ORDER BY sort_order), '[]'::jsonb) INTO _sprints FROM sp;
    WITH ph AS (SELECT 'phase_' || ROW_NUMBER() OVER (ORDER BY p.sort_order, p.created_at) AS ref, p.id
      FROM public.phases p WHERE p.project_id=_project_id AND p.is_archived=false),
    sp AS (SELECT 'sprint_' || ROW_NUMBER() OVER (ORDER BY s.sort_order, s.created_at) AS ref, s.id
      FROM public.sprints s WHERE s.project_id=_project_id AND s.is_archived=false),
    ws AS (SELECT 'state_' || ROW_NUMBER() OVER (ORDER BY w.sort_order, w.created_at) AS ref, w.id
      FROM public.board_workflow_states w WHERE w.project_id=_project_id AND w.is_archived=false),
    bi AS (SELECT 'backlog_' || ROW_NUMBER() OVER (ORDER BY b.sort_order, b.created_at) AS ref, b.*,
      ph.ref AS phase_ref, sp.ref AS sprint_ref, ws.ref AS state_ref
      FROM public.backlog_items b LEFT JOIN ph ON ph.id = b.phase_id
      LEFT JOIN sp ON sp.id = b.sprint_id
      LEFT JOIN ws ON ws.id = b.workflow_state_id
      WHERE b.project_id = _project_id AND b.is_archived = false)
    SELECT COALESCE(jsonb_agg(jsonb_build_object('ref', ref, 'source_id', id, 'title', title,
      'description', public.btpm_decrypt(description, _org), 'priority', priority,
      'sort_order', sort_order, 'phase_ref', phase_ref, 'sprint_ref', sprint_ref,
      'workflow_state_ref', state_ref) ORDER BY sort_order), '[]'::jsonb) INTO _backlog FROM bi;
    _agile := jsonb_build_object('enabled', true,
      'workflow_states', COALESCE(_states, '[]'::jsonb),
      'sprints', COALESCE(_sprints, '[]'::jsonb),
      'backlog_items', COALESCE(_backlog, '[]'::jsonb));
  ELSE
    _agile := jsonb_build_object('enabled', false,
      'workflow_states', '[]'::jsonb, 'sprints', '[]'::jsonb, 'backlog_items', '[]'::jsonb);
  END IF;
  RETURN jsonb_build_object('version', 'clone_blueprint_v1', 'blueprint_kind', 'project',
    'saved_at', to_jsonb(now()), 'schedule_mode', _schedule_mode, 'anchor_source', _anchor_source,
    'anchor_date', _anchor,
    'source', jsonb_build_object('organization_id', _org, 'workspace_id', _ws,
      'project_id', _project_id, 'phase_id', NULL),
    'project', _project_obj, 'phase', NULL, 'phases', _phases, 'tasks', _tasks,
    'dependencies', _deps, 'kpi_definitions', _kpis, 'agile', _agile);
END; $$;


--
-- Name: preview_project_people_preset_application(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_project_people_preset_application(_preset_id uuid, _project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor           uuid := auth.uid();
  v_preset          public.project_people_presets;
  v_project         record;
  v_items           jsonb := '[]'::jsonb;
  v_errors          jsonb := '[]'::jsonb;
  v_will_team       int := 0;
  v_will_stake      int := 0;
  v_already         int := 0;
  v_skipped         int := 0;
  v_total           int := 0;
  v_has_blocking    boolean := false;
  v_preset_name     text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id;
  IF v_preset.id IS NULL THEN
    -- Uniform not-authorized envelope (do not leak existence)
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT id, workspace_id, organization_id
    INTO v_project
    FROM public.projects
   WHERE id = _project_id;
  IF v_project.id IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  -- Read authority: preset workspace access + project read access
  IF NOT (public.is_workspace_member(v_actor, v_preset.workspace_id)
          OR public.is_org_admin(v_actor, v_preset.organization_id)) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT public.can_read_project(v_actor, _project_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_preset_name := public.btpm_decrypt(v_preset.name, v_preset.organization_id);

  -- Preset/project scope errors are fatal (has_blocking_errors=true)
  IF v_preset.workspace_id IS DISTINCT FROM v_project.workspace_id
     OR v_preset.organization_id IS DISTINCT FROM v_project.organization_id THEN
    v_has_blocking := true;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code','workspace_mismatch',
      'message','Preset and project belong to different workspaces or organizations.'));
  END IF;
  IF v_preset.scope_type <> 'workspace' THEN
    v_has_blocking := true;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code','invalid_scope','message','Preset scope must be workspace.'));
  END IF;
  IF v_preset.archived_at IS NOT NULL THEN
    v_has_blocking := true;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code','preset_archived','message','Preset is archived.'));
  END IF;

  IF v_has_blocking THEN
    RETURN jsonb_build_object(
      'summary', jsonb_build_object(
        'preset_id',              _preset_id,
        'preset_name',            v_preset_name,
        'project_id',             _project_id,
        'total_members',          0,
        'will_add_team_members',  0,
        'will_add_stakeholders',  0,
        'already_exists',         0,
        'skipped_ineligible',     0,
        'has_blocking_errors',    true
      ),
      'items',  '[]'::jsonb,
      'errors', v_errors
    );
  END IF;

  -- Per-member classification (materialized in one CTE for consistency)
  WITH src AS (
    SELECT
      m.id                                                             AS member_id,
      m.member_kind,
      m.stakeholder_type,
      m.user_id,
      m.canonical_role_key,
      NULLIF(btrim(public.btpm_decrypt(m.role_label,    v_preset.organization_id)), '') AS role_label,
      NULLIF(btrim(public.btpm_decrypt(m.external_name, v_preset.organization_id)), '') AS external_name_plain
    FROM public.project_people_preset_members m
    WHERE m.preset_id = _preset_id
  ),
  classified AS (
    SELECT
      s.*,
      CASE
        -- ============ Team member (internal) ============
        WHEN s.member_kind = 'team_member' THEN
          CASE
            WHEN EXISTS (SELECT 1 FROM public.project_team_members ptm
                          WHERE ptm.project_id = _project_id AND ptm.user_id = s.user_id)
              THEN 'already_exists'
            WHEN NOT public.is_active_user(s.user_id)
              THEN 'inactive_user'
            WHEN NOT public.is_workspace_member(s.user_id, v_project.workspace_id)
              THEN 'no_longer_workspace_member'
            ELSE 'will_add'
          END
        -- ============ Internal stakeholder ============
        WHEN s.member_kind = 'stakeholder' AND s.stakeholder_type = 'workspace_member' THEN
          CASE
            WHEN EXISTS (SELECT 1 FROM public.project_stakeholders sk
                          WHERE sk.project_id = _project_id
                            AND sk.stakeholder_type = 'workspace_member'
                            AND sk.user_id = s.user_id
                            AND sk.removed_at IS NULL)
              THEN 'already_exists'
            WHEN NOT public.is_active_user(s.user_id)
              THEN 'inactive_user'
            WHEN NOT public.is_workspace_member(s.user_id, v_project.workspace_id)
              THEN 'no_longer_workspace_member'
            WHEN EXISTS (SELECT 1 FROM public.project_stakeholders sk
                          WHERE sk.project_id = _project_id
                            AND sk.stakeholder_type = 'workspace_member'
                            AND sk.user_id = s.user_id
                            AND sk.removed_at IS NOT NULL)
              THEN 'otherwise_ineligible'
            ELSE 'will_add'
          END
        -- ============ External stakeholder ============
        WHEN s.member_kind = 'stakeholder' AND s.stakeholder_type = 'external' THEN
          CASE
            WHEN s.external_name_plain IS NULL THEN 'invalid_external'
            WHEN EXISTS (
              SELECT 1 FROM public.project_stakeholders sk
              WHERE sk.project_id = _project_id
                AND sk.stakeholder_type = 'external'
                AND sk.removed_at IS NULL
                AND lower(btrim(sk.external_name)) = lower(s.external_name_plain)
            ) THEN 'already_exists'
            ELSE 'will_add'
          END
        ELSE 'otherwise_ineligible'
      END AS classification
    FROM src s
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'member_id',          c.member_id,
      'member_kind',        c.member_kind,
      'stakeholder_type',   c.stakeholder_type,
      'user_id',            c.user_id,
      'display_name',       CASE
        WHEN c.user_id IS NOT NULL
          THEN (SELECT COALESCE(
                          CASE WHEN pr.organization_id IS NOT NULL
                               THEN public.btpm_decrypt(pr.display_name, pr.organization_id)
                               ELSE pr.display_name END,
                          pr.email, c.user_id::text)
                  FROM public.profiles pr WHERE pr.id = c.user_id)
        ELSE c.external_name_plain
      END,
      'canonical_role_key', c.canonical_role_key,
      'role_label',         c.role_label,
      'classification',     c.classification,
      'reason', CASE
        WHEN c.classification = 'otherwise_ineligible'
             AND c.member_kind = 'stakeholder'
             AND c.stakeholder_type = 'workspace_member'
          THEN 'previously_removed'
        ELSE NULL
      END
    ) ORDER BY c.member_kind, c.member_id), '[]'::jsonb),
    COUNT(*)::int,
    COUNT(*) FILTER (WHERE c.classification = 'will_add' AND c.member_kind = 'team_member')::int,
    COUNT(*) FILTER (WHERE c.classification = 'will_add' AND c.member_kind = 'stakeholder')::int,
    COUNT(*) FILTER (WHERE c.classification = 'already_exists')::int,
    COUNT(*) FILTER (WHERE c.classification NOT IN ('will_add','already_exists'))::int
    INTO v_items, v_total, v_will_team, v_will_stake, v_already, v_skipped
    FROM classified c;

  IF v_total = 0 THEN
    v_has_blocking := true;
    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
      'code','empty_preset','message','Preset has no members to apply.'));
  END IF;

  RETURN jsonb_build_object(
    'summary', jsonb_build_object(
      'preset_id',              _preset_id,
      'preset_name',            v_preset_name,
      'project_id',             _project_id,
      'total_members',          v_total,
      'will_add_team_members',  v_will_team,
      'will_add_stakeholders',  v_will_stake,
      'already_exists',         v_already,
      'skipped_ineligible',     v_skipped,
      'has_blocking_errors',    v_has_blocking
    ),
    'items',  v_items,
    'errors', v_errors
  );
END; $$;


--
-- Name: preview_project_planning_change(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_project_planning_change(_project_id uuid, _new_start date, _new_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE pr record; bad record;
BEGIN
  SELECT id, organization_id, workspace_id, name, start_date, target_end_date
    INTO pr FROM public.projects WHERE id = _project_id;
  IF pr.id IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'requires_extension', false, 'blocked', true,
      'blocked_reason', 'project_not_found',
      'parent_current_start', NULL, 'parent_current_end', NULL,
      'parent_proposed_start', NULL, 'parent_proposed_end', NULL); END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RETURN jsonb_build_object('valid', false, 'requires_extension', false, 'blocked', true,
      'blocked_reason', 'not_authorized',
      'parent_current_start', pr.start_date, 'parent_current_end', pr.target_end_date,
      'parent_proposed_start', _new_start, 'parent_proposed_end', _new_end); END IF;
  IF _new_start IS NOT NULL AND _new_end IS NOT NULL AND _new_end < _new_start THEN
    RETURN jsonb_build_object('valid', false, 'requires_extension', false, 'blocked', true,
      'blocked_reason', 'invalid_range',
      'parent_current_start', pr.start_date, 'parent_current_end', pr.target_end_date,
      'parent_proposed_start', _new_start, 'parent_proposed_end', _new_end); END IF;
  IF _new_start IS NOT NULL THEN
    SELECT id, name, start_date AS d INTO bad FROM public.phases
     WHERE project_id = pr.id AND status <> 'cancelled' AND NOT is_archived
       AND start_date IS NOT NULL AND start_date < _new_start
     ORDER BY start_date ASC LIMIT 1;
    IF bad.id IS NOT NULL THEN
      RETURN jsonb_build_object('valid', false, 'requires_extension', false, 'blocked', true,
        'blocked_reason', 'project_shrinks_under_child_start:' || bad.name || ':' || bad.d::text,
        'parent_current_start', pr.start_date, 'parent_current_end', pr.target_end_date,
        'parent_proposed_start', _new_start, 'parent_proposed_end', _new_end); END IF;
  END IF;
  IF _new_end IS NOT NULL THEN
    SELECT id, name, target_end_date AS d INTO bad FROM public.phases
     WHERE project_id = pr.id AND status <> 'cancelled' AND NOT is_archived
       AND target_end_date IS NOT NULL AND target_end_date > _new_end
     ORDER BY target_end_date DESC LIMIT 1;
    IF bad.id IS NOT NULL THEN
      RETURN jsonb_build_object('valid', false, 'requires_extension', false, 'blocked', true,
        'blocked_reason', 'project_shrinks_under_child_end:' || bad.name || ':' || bad.d::text,
        'parent_current_start', pr.start_date, 'parent_current_end', pr.target_end_date,
        'parent_proposed_start', _new_start, 'parent_proposed_end', _new_end); END IF;
  END IF;
  RETURN jsonb_build_object('valid', true, 'requires_extension', false, 'blocked', false,
    'blocked_reason', NULL,
    'parent_project_id', pr.id, 'parent_project_name', pr.name,
    'parent_current_start', pr.start_date, 'parent_current_end', pr.target_end_date,
    'parent_proposed_start', _new_start, 'parent_proposed_end', _new_end);
END; $$;


--
-- Name: preview_project_template_instantiation(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_project_template_instantiation(_template_id uuid, _project_start_date date DEFAULT NULL::date, _program_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _tpl RECORD;
  _payload_text text;
  _bp jsonb;
  _bp_kind text;
  _schedule_mode text;
  _eff jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT id, organization_id, workspace_id, source_project_id,
         blueprint_payload, blueprint_version, is_archived
    INTO _tpl
  FROM public.project_templates
  WHERE id = _template_id;

  IF NOT FOUND THEN RAISE EXCEPTION 'Template not found'; END IF;
  IF _tpl.is_archived THEN RAISE EXCEPTION 'Template is archived'; END IF;

  IF NOT public.has_pm_authority(_caller, _tpl.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required in template workspace';
  END IF;

  IF _program_id IS NOT NULL THEN
    PERFORM 1 FROM public.programs
      WHERE id = _program_id
        AND organization_id = _tpl.organization_id
        AND workspace_id = _tpl.workspace_id
        AND is_archived = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Program not found in template workspace/organization';
    END IF;
  END IF;

  IF _tpl.blueprint_version <> 'clone_blueprint_v1' THEN
    RAISE EXCEPTION 'Unsupported blueprint version: %', _tpl.blueprint_version;
  END IF;

  _payload_text := public.btpm_decrypt(_tpl.blueprint_payload, _tpl.organization_id);
  _bp := _payload_text::jsonb;
  _bp_kind := _bp->>'blueprint_kind';
  _schedule_mode := COALESCE(_bp->>'schedule_mode', 'unscheduled');

  IF _bp_kind <> 'project' THEN
    RAISE EXCEPTION 'Stored blueprint is not a project blueprint (kind=%)', _bp_kind;
  END IF;

  IF _project_start_date IS NULL OR _schedule_mode <> 'relative' THEN
    -- Unscheduled apply path: nothing to widen
    RETURN jsonb_build_object(
      'requires_widening', false,
      'schedule_mode_applied',
        CASE WHEN _project_start_date IS NULL THEN 'unscheduled'
             ELSE 'unscheduled' END,
      'nominal_start', NULL, 'nominal_end', NULL,
      'effective_start', NULL, 'effective_end', NULL,
      'reasons', '[]'::jsonb
    );
  END IF;

  _eff := public._compute_project_effective_window(_bp, _project_start_date);

  RETURN _eff || jsonb_build_object(
    'schedule_mode_applied','relative_reanchored',
    'template_id', _template_id,
    'project_start_date_applied', _project_start_date
  );
END;
$$;


--
-- Name: preview_task_clone_blueprint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_task_clone_blueprint(_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client_id text;
  _caller uuid;
  _task_row public.tasks%ROWTYPE;
  _phase_row public.phases%ROWTYPE;
  _phase_name text;
  _phase_desc text;
  _anchor date;
  _schedule_mode text;
  _anchor_source text;
  _result jsonb;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  _caller := auth.uid();
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _task_row FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task % not found', _task_id USING ERRCODE = 'P0002';
  END IF;

  IF public.is_user_org_member(_caller, _task_row.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_pm_authority(_caller, _task_row.workspace_id) THEN
    RAISE EXCEPTION 'Access denied: PM authority required in workspace %', _task_row.workspace_id
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _phase_row FROM public.phases WHERE id = _task_row.phase_id;

  -- Decrypt phase narrative for provenance
  BEGIN
    _phase_name := public.btpm_decrypt(_phase_row.name, _phase_row.organization_id);
  EXCEPTION WHEN OTHERS THEN
    _phase_name := _phase_row.name;
  END;
  BEGIN
    _phase_desc := public.btpm_decrypt(_phase_row.description, _phase_row.organization_id);
  EXCEPTION WHEN OTHERS THEN
    _phase_desc := _phase_row.description;
  END;

  -- Anchor resolution
  _anchor := public._clone_anchor_for_task(_task_id);
  IF _anchor IS NULL THEN
    _schedule_mode := 'unscheduled';
    _anchor_source := NULL;
  ELSE
    _schedule_mode := 'relative';
    IF _task_row.start_date IS NOT NULL THEN
      _anchor_source := 'task_start_date';
    ELSE
      _anchor_source := 'task_earliest_date';
    END IF;
  END IF;

  -- Decrypt task narrative
  DECLARE
    _task_name text;
    _task_desc text;
  BEGIN
    BEGIN
      _task_name := public.btpm_decrypt(_task_row.name, _task_row.organization_id);
    EXCEPTION WHEN OTHERS THEN
      _task_name := _task_row.name;
    END;
    BEGIN
      _task_desc := public.btpm_decrypt(_task_row.description, _task_row.organization_id);
    EXCEPTION WHEN OTHERS THEN
      _task_desc := _task_row.description;
    END;

    _result := jsonb_build_object(
      'version', 'clone_blueprint_v1',
      'blueprint_kind', 'task',
      'saved_at', to_jsonb(now()),
      'schedule_mode', _schedule_mode,
      'anchor_source', _anchor_source,
      'anchor_date', to_jsonb(_anchor),
      'source', jsonb_build_object(
        'organization_id', _task_row.organization_id,
        'workspace_id', _task_row.workspace_id,
        'project_id', _task_row.project_id,
        'phase_id', _task_row.phase_id,
        'task_id', _task_row.id
      ),
      'project', NULL,
      'phase', jsonb_build_object(
        'ref', 'phase_1',
        'source_id', _phase_row.id,
        'name', _phase_name,
        'description', _phase_desc
      ),
      'phases', '[]'::jsonb,
      'tasks', jsonb_build_array(
        jsonb_build_object(
          'ref', 'task_1',
          'source_id', _task_row.id,
          'phase_ref', 'phase_1',
          'name', _task_name,
          'description', _task_desc,
          'task_type', _task_row.task_type,
          'priority', _task_row.priority,
          'estimated_hours', _task_row.estimated_hours,
          'sort_order', _task_row.sort_order,
          'backlog_item_ref', NULL,
          'workflow_state_ref', NULL,
          'provenance', jsonb_build_object(
            'backlog_item_id', _task_row.backlog_item_id,
            'workflow_state_id', _task_row.workflow_state_id
          ),
          'schedule', CASE
            WHEN _schedule_mode = 'unscheduled' THEN jsonb_build_object(
              'start_offset_days', NULL,
              'due_offset_days', NULL
            )
            ELSE jsonb_build_object(
              'start_offset_days', public._clone_offset_days(_anchor, _task_row.start_date),
              'due_offset_days',   public._clone_offset_days(_anchor, _task_row.due_date)
            )
          END
        )
      ),
      'dependencies', '[]'::jsonb,
      'kpi_definitions', '[]'::jsonb,
      'agile', jsonb_build_object(
        'enabled', false,
        'workflow_states', '[]'::jsonb,
        'sprints', '[]'::jsonb,
        'backlog_items', '[]'::jsonb
      )
    );
  END;

  RETURN _result;
END;
$$;


--
-- Name: preview_task_clone_in_phase(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_task_clone_in_phase(_task_id uuid, _task_start_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _src_task RECORD;
  _phase RECORD;
  _bp jsonb;
  _start_off int; _due_off int;
  _t_start date; _t_due date;
  _requires boolean := false;
  _reasons jsonb := '[]'::jsonb;
BEGIN
  IF _caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT * INTO _src_task FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;

  IF NOT public.has_pm_authority(_caller, _src_task.workspace_id) THEN
    RAISE EXCEPTION 'PM authority required';
  END IF;

  SELECT id, name, start_date, target_end_date INTO _phase
    FROM public.phases WHERE id = _src_task.phase_id;

  _bp := public.preview_task_clone_blueprint(_task_id);

  IF _task_start_date IS NULL OR (_bp->>'schedule_mode') <> 'relative' THEN
    RETURN jsonb_build_object(
      'requires_widening', false,
      'schedule_mode_applied','unscheduled_preserved',
      'parent_phase_id', _phase.id,
      'parent_phase_name', _phase.name,
      'parent_current_start', _phase.start_date,
      'parent_current_end', _phase.target_end_date,
      'parent_proposed_start', _phase.start_date,
      'parent_proposed_end', _phase.target_end_date
    );
  END IF;

  _start_off := NULLIF(_bp->'task'->'schedule'->>'start_offset_days','')::int;
  _due_off   := NULLIF(_bp->'task'->'schedule'->>'due_offset_days','')::int;
  _t_start := CASE WHEN _start_off IS NOT NULL THEN _task_start_date + _start_off ELSE _task_start_date END;
  _t_due   := CASE WHEN _due_off   IS NOT NULL THEN _task_start_date + _due_off   ELSE NULL END;

  IF _phase.start_date IS NOT NULL AND _t_start IS NOT NULL AND _t_start < _phase.start_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','task_before_phase','date', _t_start);
  END IF;
  IF _phase.target_end_date IS NOT NULL AND _t_due IS NOT NULL AND _t_due > _phase.target_end_date THEN
    _requires := true;
    _reasons := _reasons || jsonb_build_object('kind','task_after_phase','date', _t_due);
  END IF;

  RETURN jsonb_build_object(
    'requires_widening', _requires,
    'schedule_mode_applied','relative_reanchored',
    'parent_phase_id', _phase.id,
    'parent_phase_name', _phase.name,
    'parent_current_start', _phase.start_date,
    'parent_current_end', _phase.target_end_date,
    'parent_proposed_start',
        CASE WHEN _t_start IS NOT NULL AND (_phase.start_date IS NULL OR _t_start < _phase.start_date)
             THEN _t_start ELSE _phase.start_date END,
    'parent_proposed_end',
        CASE WHEN _t_due IS NOT NULL AND (_phase.target_end_date IS NULL OR _t_due > _phase.target_end_date)
             THEN _t_due ELSE _phase.target_end_date END,
    'task_proposed_start', _t_start,
    'task_proposed_end', _t_due,
    'reasons', _reasons
  );
END;
$$;


--
-- Name: preview_task_planning_change(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_task_planning_change(_task_id uuid, _new_phase_id uuid, _new_start date, _new_due date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  t  record;
  ph record;
  ws_id uuid;
  needs_ext boolean := false;
  proposed_start date;
  proposed_end   date;
  blocked boolean := false;
  reason  text := NULL;
BEGIN
  SELECT id, phase_id, workspace_id, status, is_archived, start_date, due_date, name
    INTO t
    FROM public.tasks
   WHERE id = _task_id;

  IF t.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'task_not_found');
  END IF;

  ws_id := t.workspace_id;
  IF NOT public.is_workspace_admin_or_higher(auth.uid(), ws_id) THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'not_authorized');
  END IF;

  -- Completed-item lock (4F.2)
  IF t.status = 'completed' THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'task_completed_locked');
  END IF;
  IF t.status = 'cancelled' OR t.is_archived THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'task_cancelled_or_archived');
  END IF;

  IF _new_start IS NOT NULL AND _new_due IS NOT NULL AND _new_due < _new_start THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'invalid_range');
  END IF;

  SELECT id, name, start_date, target_end_date, status, is_archived
    INTO ph
    FROM public.phases
   WHERE id = COALESCE(_new_phase_id, t.phase_id);

  IF ph.id IS NULL THEN
    RETURN jsonb_build_object('blocked', true, 'blocked_reason', 'phase_not_found');
  END IF;

  proposed_start := ph.start_date;
  proposed_end   := ph.target_end_date;

  IF _new_start IS NOT NULL AND ph.start_date IS NOT NULL AND _new_start < ph.start_date THEN
    needs_ext := true;
    proposed_start := _new_start;
  END IF;
  IF _new_due IS NOT NULL AND ph.target_end_date IS NOT NULL AND _new_due > ph.target_end_date THEN
    needs_ext := true;
    proposed_end := _new_due;
  END IF;

  RETURN jsonb_build_object(
    'valid', NOT needs_ext AND NOT blocked,
    'requires_extension', needs_ext,
    'blocked', blocked,
    'blocked_reason', reason,
    'parent_phase_id', ph.id,
    'parent_phase_name', ph.name,
    'parent_current_start', ph.start_date,
    'parent_current_end',   ph.target_end_date,
    'parent_proposed_start', proposed_start,
    'parent_proposed_end',   proposed_end
  );
END;
$$;


--
-- Name: publish_roadmap_story_presentation_version(uuid, uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_roadmap_story_presentation_version(_story_pack_id uuid, _story_pack_version_id uuid, _presentation_blueprint_run_id uuid, _title text, _snapshot_json text, _source_limitations_json text, _source_mode text, _publish_warnings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _pack_version public.roadmap_story_pack_versions;
  _run public.roadmap_story_pack_presentation_runs;
  _presentation public.roadmap_story_presentations;
  _presentation_id uuid;
  _next_version integer;
  _new_version_id uuid;
  _title_final text;
  _pack_title_plain text;
  _title_enc text;
  _snapshot_enc text;
  _limitations_enc text;
  _effective_pack_version_id uuid;
  _snapshot_scope_used boolean := false;
  _scope_config_fallback_used boolean := false;
  _source_snap_json text;
  _source_snap jsonb;
  _sources jsonb;
  _cat_key text;
  _cat_val jsonb;
  _cat_items jsonb;
  _row jsonb;
  _pid uuid;
  _wid uuid;
  _pid_text text;
  _wid_text text;
  _candidates jsonb := '[]'::jsonb;
  _captured jsonb;
  _captured_project_ids uuid[];
  _captured_workspace_ids uuid[];
  _candidate_ids uuid[];
  _proj record;
  _accepted_count integer := 0;
  _skipped_no_access integer := 0;
  _skipped_org_mismatch integer := 0;
  _skipped_invalid integer := 0;
  _warnings jsonb := COALESCE(_publish_warnings, '[]'::jsonb);
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF _source_mode IS NULL OR _source_mode NOT IN ('ai_blueprint','deterministic') THEN
    RAISE EXCEPTION 'invalid_source_mode' USING ERRCODE = '22023';
  END IF;

  IF _snapshot_json IS NULL OR length(_snapshot_json) = 0 THEN
    RAISE EXCEPTION 'invalid_snapshot' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'story_pack_archived' USING ERRCODE = '22023';
  END IF;

  IF _presentation_blueprint_run_id IS NOT NULL THEN
    SELECT * INTO _run FROM public.roadmap_story_pack_presentation_runs
     WHERE id = _presentation_blueprint_run_id;
    IF NOT FOUND
       OR _run.story_pack_id <> _story_pack_id
       OR _run.status <> 'succeeded'
       OR COALESCE(_run.is_valid, false) = false THEN
      RAISE EXCEPTION 'invalid_presentation_blueprint_run' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF _story_pack_version_id IS NOT NULL THEN
    _effective_pack_version_id := _story_pack_version_id;
    IF _run.id IS NOT NULL
       AND _run.story_pack_version_id IS NOT NULL
       AND _run.story_pack_version_id <> _story_pack_version_id THEN
      RAISE EXCEPTION 'inconsistent_story_pack_version_run' USING ERRCODE = '22023';
    END IF;
  ELSIF _run.id IS NOT NULL THEN
    _effective_pack_version_id := _run.story_pack_version_id;
  END IF;

  IF _effective_pack_version_id IS NOT NULL THEN
    SELECT * INTO _pack_version FROM public.roadmap_story_pack_versions
     WHERE id = _effective_pack_version_id;
    IF NOT FOUND OR _pack_version.story_pack_id <> _story_pack_id THEN
      RAISE EXCEPTION 'invalid_story_pack_version' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- Title: prefer explicit request, then decrypted pack title, then default.
  BEGIN
    _pack_title_plain := CASE
      WHEN _pack.title_encrypted IS NULL THEN NULL
      ELSE public.btpm_decrypt(_pack.title_encrypted, _pack.organization_id)
    END;
  EXCEPTION WHEN others THEN
    _pack_title_plain := NULL;
  END;
  _title_final := COALESCE(
    NULLIF(btrim(_title), ''),
    NULLIF(btrim(_pack_title_plain), ''),
    'Roadmap Story'
  );
  IF length(_title_final) > 300 THEN
    _title_final := left(_title_final, 300);
  END IF;

  IF _pack_version.id IS NOT NULL
     AND _pack_version.source_snapshot_encrypted IS NOT NULL THEN
    BEGIN
      _source_snap_json := public.btpm_decrypt(
        _pack_version.source_snapshot_encrypted, _pack.organization_id
      );
      IF _source_snap_json IS NOT NULL AND length(_source_snap_json) > 0 THEN
        BEGIN
          _source_snap := _source_snap_json::jsonb;
        EXCEPTION WHEN others THEN
          _source_snap := NULL;
        END;
      END IF;
    EXCEPTION WHEN others THEN
      _source_snap := NULL;
    END;

    IF _source_snap IS NOT NULL THEN
      _sources := _source_snap -> 'sources';
      IF _sources IS NOT NULL AND jsonb_typeof(_sources) = 'object' THEN
        FOR _cat_key, _cat_val IN SELECT * FROM jsonb_each(_sources) LOOP
          _cat_items := _cat_val -> 'items';
          IF _cat_items IS NULL OR jsonb_typeof(_cat_items) <> 'array' THEN
            CONTINUE;
          END IF;
          FOR _row IN SELECT * FROM jsonb_array_elements(_cat_items) LOOP
            _pid_text := COALESCE(
              _row ->> 'project_id',
              _row ->> 'projectId',
              (_row -> 'project') ->> 'id'
            );
            _wid_text := COALESCE(
              _row ->> 'workspace_id',
              _row ->> 'workspaceId',
              (_row -> 'workspace') ->> 'id'
            );
            BEGIN
              _pid := _pid_text::uuid;
            EXCEPTION WHEN others THEN
              _pid := NULL;
            END;
            BEGIN
              _wid := _wid_text::uuid;
            EXCEPTION WHEN others THEN
              _wid := NULL;
            END;
            IF _pid IS NOT NULL THEN
              _candidates := _candidates || jsonb_build_object(
                'project_id', _pid,
                'workspace_id', _wid
              );
            END IF;
          END LOOP;
        END LOOP;
      END IF;

      IF jsonb_array_length(_candidates) > 0 THEN
        SELECT COALESCE(array_agg(DISTINCT (v ->> 'project_id')::uuid), ARRAY[]::uuid[])
          INTO _candidate_ids
          FROM jsonb_array_elements(_candidates) v;
        _snapshot_scope_used := true;
      END IF;
    END IF;
  END IF;

  IF _candidate_ids IS NULL OR array_length(_candidate_ids, 1) IS NULL THEN
    _captured := COALESCE(_pack.scope_config, '{}'::jsonb) -> 'roadmap_filters';
    IF _captured IS NOT NULL THEN
      SELECT COALESCE(array_agg((v)::uuid), ARRAY[]::uuid[])
        INTO _captured_project_ids
        FROM jsonb_array_elements_text(COALESCE(_captured -> 'project_ids', '[]'::jsonb)) v;
      SELECT COALESCE(array_agg((v)::uuid), ARRAY[]::uuid[])
        INTO _captured_workspace_ids
        FROM jsonb_array_elements_text(COALESCE(_captured -> 'workspace_ids', '[]'::jsonb)) v;

      IF array_length(_captured_project_ids, 1) IS NOT NULL THEN
        _candidate_ids := _captured_project_ids;
        _scope_config_fallback_used := true;
      ELSIF array_length(_captured_workspace_ids, 1) IS NOT NULL THEN
        SELECT COALESCE(array_agg(p.id), ARRAY[]::uuid[])
          INTO _candidate_ids
          FROM public.projects p
         WHERE p.workspace_id = ANY(_captured_workspace_ids);
        _scope_config_fallback_used := true;
      END IF;
    END IF;
    IF _candidate_ids IS NULL THEN
      _candidate_ids := ARRAY[]::uuid[];
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('roadmap_story_pack:' || _story_pack_id::text)::bigint
  );

  SELECT * INTO _presentation FROM public.roadmap_story_presentations
   WHERE story_pack_id = _story_pack_id;

  IF NOT FOUND THEN
    INSERT INTO public.roadmap_story_presentations
      (organization_id, story_pack_id, title_encrypted, status, created_by)
    VALUES (
      _pack.organization_id,
      _story_pack_id,
      public.btpm_encrypt(_title_final, _pack.organization_id),
      'active',
      _uid
    )
    RETURNING * INTO _presentation;
  ELSE
    IF _presentation.status = 'archived' THEN
      UPDATE public.roadmap_story_presentations
         SET status = 'active',
             title_encrypted = public.btpm_encrypt(_title_final, _pack.organization_id),
             updated_at = now()
       WHERE id = _presentation.id
       RETURNING * INTO _presentation;
    ELSE
      UPDATE public.roadmap_story_presentations
         SET title_encrypted = public.btpm_encrypt(_title_final, _pack.organization_id),
             updated_at = now()
       WHERE id = _presentation.id
       RETURNING * INTO _presentation;
    END IF;
  END IF;
  _presentation_id := _presentation.id;

  SELECT COALESCE(MAX(version_number), 0) + 1
    INTO _next_version
    FROM public.roadmap_story_presentation_versions
   WHERE presentation_id = _presentation_id;

  _title_enc := public.btpm_encrypt(_title_final, _pack.organization_id);
  _snapshot_enc := public.btpm_encrypt(_snapshot_json, _pack.organization_id);
  _limitations_enc := CASE
    WHEN _source_limitations_json IS NULL OR length(_source_limitations_json) = 0 THEN NULL
    ELSE public.btpm_encrypt(_source_limitations_json, _pack.organization_id)
  END;

  INSERT INTO public.roadmap_story_presentation_versions (
    organization_id,
    presentation_id,
    story_pack_id,
    story_pack_version_id,
    presentation_blueprint_run_id,
    version_number,
    title_encrypted,
    snapshot_encrypted,
    source_limitations_encrypted,
    status,
    published_by
  ) VALUES (
    _pack.organization_id,
    _presentation_id,
    _story_pack_id,
    _effective_pack_version_id,
    _presentation_blueprint_run_id,
    _next_version,
    _title_enc,
    _snapshot_enc,
    _limitations_enc,
    'active',
    _uid
  )
  RETURNING id INTO _new_version_id;

  IF array_length(_candidate_ids, 1) IS NOT NULL THEN
    FOR _proj IN
      SELECT DISTINCT p.id AS project_id, p.workspace_id AS workspace_id,
             w.organization_id AS workspace_org
        FROM public.projects p
        JOIN public.workspaces w ON w.id = p.workspace_id
       WHERE p.id = ANY(_candidate_ids)
    LOOP
      IF _proj.workspace_org IS DISTINCT FROM _pack.organization_id THEN
        _skipped_org_mismatch := _skipped_org_mismatch + 1;
        CONTINUE;
      END IF;
      IF NOT public.has_project_access(_uid, _proj.project_id) THEN
        _skipped_no_access := _skipped_no_access + 1;
        CONTINUE;
      END IF;
      INSERT INTO public.roadmap_story_presentation_version_projects
        (presentation_version_id, organization_id, workspace_id, project_id)
      VALUES (_new_version_id, _pack.organization_id, _proj.workspace_id, _proj.project_id)
      ON CONFLICT DO NOTHING;
      _accepted_count := _accepted_count + 1;
    END LOOP;
    _skipped_invalid := array_length(_candidate_ids, 1)
      - (_accepted_count + _skipped_no_access + _skipped_org_mismatch);
    IF _skipped_invalid < 0 THEN _skipped_invalid := 0; END IF;
  END IF;

  IF _snapshot_scope_used THEN
    _warnings := _warnings || to_jsonb(
      'Source-project scope derived from captured Story Pack source snapshot.'::text
    );
  ELSIF _scope_config_fallback_used THEN
    _warnings := _warnings || to_jsonb(
      'Source-project scope derived from Story Pack filter configuration (fallback).'::text
    );
  END IF;
  IF _skipped_no_access > 0 THEN
    _warnings := _warnings || to_jsonb(
      format('%s source project(s) skipped because the publisher lacks access.',
             _skipped_no_access)
    );
  END IF;
  IF _skipped_org_mismatch > 0 THEN
    _warnings := _warnings || to_jsonb(
      format('%s source project(s) skipped because they belong to another organization.',
             _skipped_org_mismatch)
    );
  END IF;
  IF _skipped_invalid > 0 THEN
    _warnings := _warnings || to_jsonb(
      format('%s candidate project id(s) skipped because no matching project row was found.',
             _skipped_invalid)
    );
  END IF;
  IF _accepted_count = 0 THEN
    _warnings := _warnings || to_jsonb(
      'No source projects could be derived. This published version will be openable only by the publisher or Story Pack owner.'::text
    );
  END IF;

  RETURN jsonb_build_object(
    'presentation_id', _presentation_id,
    'version_id', _new_version_id,
    'story_pack_id', _story_pack_id,
    'story_pack_version_id', _effective_pack_version_id,
    'version_number', _next_version,
    'title', _title_final,
    'status', 'active',
    'published_at', now(),
    'source_project_count', _accepted_count,
    'source_mode', _source_mode,
    'scope_source', CASE
      WHEN _snapshot_scope_used THEN 'source_snapshot'
      WHEN _scope_config_fallback_used THEN 'scope_config_fallback'
      ELSE 'none'
    END,
    'warnings', _warnings
  );
END;
$$;


--
-- Name: reactivate_workspace(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_workspace(_workspace_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED' USING ERRCODE = '42501';
  END IF;

  SELECT organization_id INTO v_org
    FROM public.workspaces
   WHERE id = _workspace_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'WORKSPACE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_org_admin(v_actor, v_org) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED_ORG_ADMIN_REQUIRED' USING ERRCODE = '42501';
  END IF;

  UPDATE public.workspaces
     SET is_active  = true,
         updated_at = now()
   WHERE id = _workspace_id
     AND is_active = false;

  INSERT INTO public.activity_events
    (organization_id, workspace_id, actor_id, target_type, target_id, event_type, metadata)
  VALUES
    (v_org, _workspace_id, v_actor, 'workspace', _workspace_id,
     'workspace.reactivated',
     jsonb_build_object('lifecycle', 'reactivate', 'step', '5.4')::text);
END;
$$;


--
-- Name: rebaseline_project(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebaseline_project(_project_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_proj public.projects%ROWTYPE;
BEGIN
  SELECT * INTO v_proj FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT v_proj.is_baselined THEN
    RAISE EXCEPTION 'Project is not baselined. Use approve_project_baseline first.';
  END IF;
  PERFORM public._snapshot_baseline(_project_id);
  PERFORM public.log_activity_event(
    _organization_id => v_proj.organization_id,
    _actor_id        => auth.uid(),
    _event_type      => 'baseline_rebaselined',
    _target_type     => 'project',
    _target_id       => _project_id,
    _metadata        => jsonb_build_object('rebaselined_at', now()),
    _workspace_id    => v_proj.workspace_id
  );
END; $$;


--
-- Name: record_generated_decision_case_document(uuid, public.generated_doc_type, public.generated_doc_status, text, timestamp with time zone, public.generated_doc_publish_status, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_generated_decision_case_document(_record_id uuid, _document_type public.generated_doc_type, _generation_status public.generated_doc_status, _output_filename text, _source_snapshot_at timestamp with time zone, _publish_status public.generated_doc_publish_status DEFAULT 'not_published'::public.generated_doc_publish_status, _sharepoint_item_id text DEFAULT NULL::text, _sharepoint_web_url text DEFAULT NULL::text, _error_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.governance_records%ROWTYPE;
  _uid uuid := auth.uid();
  _new_id uuid;
  _note text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501'; END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Generated documents are only available for decision cases' USING ERRCODE='22023';
  END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _document_type NOT IN (
    'decision_case_word_brief'::public.generated_doc_type,
    'decision_case_ppt_onepager'::public.generated_doc_type
  ) THEN
    RAISE EXCEPTION 'Unsupported document_type for decision case' USING ERRCODE='22023';
  END IF;

  _note := CASE WHEN _error_note IS NULL THEN NULL ELSE left(_error_note, 500) END;

  INSERT INTO public.generated_operational_documents (
    organization_id, workspace_id, project_id, governance_record_id,
    document_type, generation_status, output_filename, generated_by,
    source_snapshot_at, sharepoint_publish_status, sharepoint_item_id,
    sharepoint_web_url, error_note
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _row.id,
    _document_type, _generation_status, _output_filename, _uid,
    _source_snapshot_at,
    COALESCE(_publish_status, 'not_published'::public.generated_doc_publish_status),
    _sharepoint_item_id, _sharepoint_web_url, _note
  )
  RETURNING id INTO _new_id;

  RETURN _new_id;
END; $$;


--
-- Name: record_generated_operational_document(uuid, public.generated_doc_type, public.generated_doc_status, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_generated_operational_document(_project_id uuid, _document_type public.generated_doc_type, _generation_status public.generated_doc_status, _output_filename text, _source_snapshot_at timestamp with time zone, _error_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _uid uuid := auth.uid(); _org_id uuid; _ws_id uuid; _new_id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT organization_id, workspace_id INTO _org_id, _ws_id FROM public.projects WHERE id = _project_id;
  IF _org_id IS NULL THEN RAISE EXCEPTION 'Project not found'; END IF;
  IF NOT public.has_project_pm_authority(_uid, _project_id) THEN
    RAISE EXCEPTION 'Not authorized to generate documents for this project'; END IF;
  INSERT INTO public.generated_operational_documents (organization_id, workspace_id, project_id,
    document_type, generation_status, output_filename, generated_by, source_snapshot_at,
    sharepoint_publish_status, error_note)
  VALUES (_org_id, _ws_id, _project_id, _document_type, _generation_status, _output_filename,
    _uid, _source_snapshot_at, 'not_published'::public.generated_doc_publish_status, _error_note)
  RETURNING id INTO _new_id;
  RETURN _new_id;
END; $$;


--
-- Name: record_generated_operational_document(uuid, public.generated_doc_type, public.generated_doc_status, text, timestamp with time zone, public.generated_doc_publish_status, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_generated_operational_document(_project_id uuid, _document_type public.generated_doc_type, _generation_status public.generated_doc_status, _output_filename text, _source_snapshot_at timestamp with time zone, _publish_status public.generated_doc_publish_status, _sharepoint_item_id text, _sharepoint_web_url text, _error_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _uid uuid := auth.uid(); _org_id uuid; _ws_id uuid; _new_id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
