  INSERT INTO public.generated_operational_documents (organization_id, workspace_id, project_id,
    document_type, generation_status, output_filename, generated_by, source_snapshot_at,
    sharepoint_publish_status, sharepoint_item_id, sharepoint_web_url, error_note)
  VALUES (_org_id, _ws_id, _project_id, _document_type, _generation_status, _output_filename,
    _uid, _source_snapshot_at,
    COALESCE(_publish_status, 'not_published'::public.generated_doc_publish_status),
    _sharepoint_item_id, _sharepoint_web_url, _error_note)
  RETURNING id INTO _new_id;
  RETURN _new_id;
