--
-- Name: record_generated_roadmap_document(uuid, uuid[], uuid, public.generated_doc_type, public.generated_doc_status, text, timestamp with time zone, public.generated_doc_publish_status, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_generated_roadmap_document(_uid uuid, _project_ids uuid[], _workspace_id uuid, _document_type public.generated_doc_type, _generation_status public.generated_doc_status, _output_filename text, _source_snapshot_at timestamp with time zone, _publish_status public.generated_doc_publish_status, _sharepoint_item_id text, _sharepoint_web_url text, _error_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
  _new_id uuid;
  _pid uuid;
  _proj_org uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Missing user id';
  END IF;
  IF NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'Not an active user';
  END IF;
  IF _project_ids IS NULL OR array_length(_project_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Empty project scope';
  END IF;

  -- Anchor/publishing workspace defines the organization boundary for
  -- the document history row. Roadmap PPT decks may legitimately include
  -- projects from multiple workspaces within the same organization, so
  -- we validate same-organization, NOT same-workspace.
  SELECT organization_id INTO _org_id FROM public.workspaces WHERE id = _workspace_id;
  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Workspace not found';
  END IF;

  -- Re-validate every project in scope:
  --   1) project exists,
  --   2) project belongs to the same organization as the anchor workspace
  --      (no cross-organization leakage),
  --   3) caller passes has_project_access (org admin, workspace admin, or
  --      explicit project membership — NOT generic workspace membership).
  FOREACH _pid IN ARRAY _project_ids LOOP
    SELECT p.organization_id INTO _proj_org
      FROM public.projects p
      WHERE p.id = _pid;
    IF _proj_org IS NULL THEN
      RAISE EXCEPTION 'Project % not found', _pid;
    END IF;
    IF _proj_org <> _org_id THEN
      RAISE EXCEPTION 'Project % is outside organization %', _pid, _org_id;
    END IF;
    IF NOT public.has_project_access(_uid, _pid) THEN
      RAISE EXCEPTION 'Not authorized for project % in roadmap scope', _pid;
    END IF;
  END LOOP;

  INSERT INTO public.generated_operational_documents (
    organization_id, workspace_id, project_id, document_type, generation_status,
    output_filename, generated_by, source_snapshot_at,
    sharepoint_publish_status, sharepoint_item_id, sharepoint_web_url, error_note
  ) VALUES (
    _org_id, _workspace_id, NULL, _document_type, _generation_status,
    _output_filename, _uid, _source_snapshot_at,
    _publish_status, _sharepoint_item_id, _sharepoint_web_url, _error_note
  ) RETURNING id INTO _new_id;
  RETURN _new_id;
END;
$$;


