    organization_id, workspace_id, target_type, target_id, payload
  ) VALUES (
    _organization_id, _workspace_id, _target_type, _target_id, _payload
  )
  RETURNING id INTO _id;

  RETURN _id;
END;
$$;


--
-- Name: record_outbound_email_event(uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_outbound_email_event(_tenant_id uuid, _organization_id uuid, _workspace_id uuid, _project_id uuid, _task_id uuid, _recipient_user_id uuid, _recipient_email text, _email_type text, _event_key text, _status text, _provider_message_id text DEFAULT NULL::text, _error_code text DEFAULT NULL::text, _safe_error_message text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF _tenant_id IS NULL OR _organization_id IS NULL
     OR _recipient_email IS NULL OR _email_type IS NULL
     OR _event_key IS NULL OR _status IS NULL THEN
    RAISE EXCEPTION 'record_outbound_email_event: missing required argument'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.outbound_email_events (
    tenant_id, organization_id, workspace_id, project_id, task_id,
    recipient_user_id, recipient_email, email_type, event_key, status,
    provider_message_id, error_code, safe_error_message, metadata
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _project_id, _task_id,
    _recipient_user_id, lower(trim(_recipient_email)), _email_type, _event_key, _status,
    _provider_message_id, _error_code, _safe_error_message, COALESCE(_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: record_roadmap_story_run_files(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_roadmap_story_run_files(_run_id uuid, _files jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _run public.roadmap_story_ai_runs;
  _inserted integer := 0;
  _item jsonb;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _run FROM public.roadmap_story_ai_runs WHERE id = _run_id;
  IF NOT FOUND OR _run.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _files IS NULL OR jsonb_typeof(_files) <> 'array' THEN
    RETURN 0;
  END IF;

  FOR _item IN SELECT * FROM jsonb_array_elements(_files) LOOP
    INSERT INTO public.roadmap_story_ai_run_files (
      ai_run_id, story_pack_id, external_file_id, attachment_alias,
      status, input_kind, file_extension, mime_type, size_bytes, sha256, skip_reason
    ) VALUES (
      _run_id,
      _run.story_pack_id,
      NULLIF(_item->>'external_file_id','')::uuid,
      COALESCE(_item->>'attachment_alias','file'),
      COALESCE(_item->>'status','skipped'),
      COALESCE(_item->>'input_kind','none'),
      _item->>'file_extension',
      _item->>'mime_type',
      NULLIF(_item->>'size_bytes','')::bigint,
      _item->>'sha256',
      _item->>'skip_reason'
    );
    _inserted := _inserted + 1;
  END LOOP;
  RETURN _inserted;
END;
$$;


--
-- Name: record_tenant_integration_test_result(uuid, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_tenant_integration_test_result(_integration_id uuid, _organization_id uuid, _actor_user_id uuid, _result text, _safe_error_code text, _function_name text, _request_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  _integ   public.tenant_integrations%ROWTYPE;
  _org_ok  boolean := false;
  _org_tenant uuid;
  _safe_code text;
BEGIN
  -- 1. Validate result vocabulary.
  IF _result IS NULL OR _result NOT IN ('success','failure','blocked') THEN
    RAISE EXCEPTION 'invalid_test_result'
      USING ERRCODE = '22023';
  END IF;

  -- 2. Load the integration row. Missing integration is fatal but is not
  --    disclosed with identifiers in the error message.
  SELECT * INTO _integ FROM public.tenant_integrations
   WHERE id = _integration_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'integration_not_found'
      USING ERRCODE = 'P0002';
  END IF;

  -- 3. If an Organization is supplied it MUST belong to the same Tenant.
  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations
     WHERE id = _organization_id;
    IF NOT FOUND OR _org_tenant IS DISTINCT FROM _integ.tenant_id THEN
      RAISE EXCEPTION 'organization_tenant_mismatch'
        USING ERRCODE = '22023';
    END IF;
    _org_ok := true;
  END IF;

  -- 4. Normalize the safe error code. Only stored for failure/blocked.
  IF _result = 'success' THEN
    _safe_code := NULL;
  ELSE
    -- Constrain to a bounded identifier shape; never accept free-form text.
    IF _safe_error_code IS NULL
       OR length(_safe_error_code) = 0
       OR length(_safe_error_code) > 80
       OR _safe_error_code !~ '^[a-z0-9_]+$'
    THEN
      _safe_code := 'test_result_unclassified';
    ELSE
      _safe_code := _safe_error_code;
    END IF;
  END IF;

  -- 5. Update ONLY the canonical test-status fields. Never touch status,
  --    is_enabled, configuration, or secret readiness.
  IF _result = 'success' THEN
    UPDATE public.tenant_integrations
       SET last_tested_at     = now(),
           last_success_at    = now(),
           last_error_message = NULL
     WHERE id = _integration_id;
  ELSE
    UPDATE public.tenant_integrations
       SET last_tested_at     = now(),
           last_error_at      = now(),
           last_error_message = _safe_code
     WHERE id = _integration_id;
  END IF;

  -- 6. Audit trail. Never stores raw provider messages, secret values,
  --    tokens, Vault IDs, or fingerprints — only the safe classification.
  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, organization_id, integration_id,
    actor_user_id, actor_type, action, reason,
    function_name, request_id, result, error_message
  ) VALUES (
    _integ.tenant_id,
    CASE WHEN _org_ok THEN _organization_id ELSE NULL END,
    _integration_id,
    _actor_user_id,
    'user',
    'tested'::public.tenant_secret_audit_action,
    NULL,
    _function_name,
    _request_id,
    _result,
    _safe_code
  );
END;
$_$;


--
-- Name: tenant_storage_objects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_storage_objects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    workspace_id uuid,
    bucket text NOT NULL,
    object_path text NOT NULL,
    legacy_object_path text,
    surface text NOT NULL,
    object_type text NOT NULL,
    object_id uuid,
    file_name text NOT NULL,
    content_type text,
    size_bytes bigint,
    checksum text,
    storage_status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tso_metadata_is_object CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT tso_path_prefixed_by_tenant CHECK ((object_path ~~ ((tenant_id)::text || '/%'::text))),
    CONSTRAINT tso_status_allowed CHECK ((storage_status = ANY (ARRAY['active'::text, 'deleted'::text, 'archived'::text, 'pending'::text, 'failed'::text])))
);


--
-- Name: register_tenant_storage_object(uuid, uuid, uuid, text, text, text, uuid, text, text, bigint, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_tenant_storage_object(_tenant_id uuid, _organization_id uuid, _workspace_id uuid, _bucket text, _surface text, _object_type text, _object_id uuid, _file_name text, _content_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _checksum text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb, _legacy_object_path text DEFAULT NULL::text) RETURNS public.tenant_storage_objects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_storage_objects;
  _path text;
  _bucket_seg text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT (
    public.is_platform_super_admin(auth.uid())
    OR public.is_tenant_admin(_tenant_id, auth.uid())
    OR public.is_organization_admin(_organization_id, auth.uid())
    OR (_workspace_id IS NOT NULL AND public.is_workspace_member(auth.uid(), _workspace_id))
  ) THEN
    RAISE EXCEPTION 'Not authorized to register storage object in this scope' USING ERRCODE = '42501';
  END IF;

  _bucket_seg := public._sanitize_storage_segment(_bucket);
  IF _bucket_seg IS NULL THEN RAISE EXCEPTION 'bucket is required'; END IF;

  _path := public.build_tenant_storage_path(
    _tenant_id, _organization_id, _workspace_id, _surface, _object_type, _object_id, _file_name
  );

  INSERT INTO public.tenant_storage_objects (
    tenant_id, organization_id, workspace_id, bucket, object_path, legacy_object_path,
    surface, object_type, object_id, file_name, content_type, size_bytes, checksum,
    storage_status, created_by, updated_by, metadata
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _bucket_seg, _path, _legacy_object_path,
    _surface, _object_type, _object_id, _file_name, _content_type, _size_bytes, _checksum,
    'pending', auth.uid(), auth.uid(), COALESCE(_metadata, '{}'::jsonb)
  )
  ON CONFLICT (bucket, object_path) DO UPDATE
     SET updated_by = auth.uid(),
         updated_at = now(),
         metadata = COALESCE(EXCLUDED.metadata, public.tenant_storage_objects.metadata)
  RETURNING * INTO _row;
  RETURN _row;
END $$;


--
-- Name: remove_dependency(uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_dependency(_dependency_id uuid, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_ws uuid; v_org uuid;
  v_src_type text; v_src_id uuid; v_tgt_type text; v_tgt_id uuid;
  v_updated_at timestamptz;
  v_project uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'remove_dependency',
      'dependency', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _dependency_id IS NULL OR _expected_updated_at IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'remove_dependency',
      'dependency', NULL, NULL,
      jsonb_build_object('reason','invalid_input'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT workspace_id, organization_id, source_type, source_id, target_type, target_id, updated_at
    INTO v_ws, v_org, v_src_type, v_src_id, v_tgt_type, v_tgt_id, v_updated_at
    FROM public.dependencies
    WHERE id = _dependency_id
    FOR UPDATE;

  IF v_ws IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'remove_dependency',
      'dependency', NULL, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_pm_authority(v_actor, v_ws)
     OR NOT public.can_write_demo(v_actor, v_ws) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'remove_dependency',
      'dependency', _dependency_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Derive parent project (needed for both conflict audit and applied audit).
  IF v_src_type = 'phase' THEN
    SELECT project_id INTO v_project FROM public.phases WHERE id = v_src_id;
  ELSIF v_src_type = 'task' THEN
    SELECT project_id INTO v_project FROM public.tasks WHERE id = v_src_id;
  ELSE
    v_project := v_src_id;
  END IF;

  IF v_updated_at IS DISTINCT FROM _expected_updated_at THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'remove_dependency',
      'btpm_ui'::public.pmg_source_channel,
      v_project, 'dependency', _dependency_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'stale', true,
        'source_type', v_src_type,
        'target_type', v_tgt_type,
        'workspace_id', v_ws
      )
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'remove_dependency',
      'dependency', _dependency_id, v_project,
      jsonb_build_object('reason','stale_write','current_updated_at', v_updated_at),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DELETE FROM public.dependencies WHERE id = _dependency_id;

  PERFORM public.pmg_record_command_audit(
    'applied'::public.pmg_command_status, 'remove_dependency',
    'btpm_ui'::public.pmg_source_channel,
    v_project, 'dependency', _dependency_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'source_type', v_src_type, 'target_type', v_tgt_type,
      'workspace_id', v_ws
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status, 'remove_dependency',
    'dependency', _dependency_id, v_project,
    jsonb_build_object('id', _dependency_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$$;


--
-- Name: remove_project_people_preset_member(uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_project_people_preset_member(_member_id uuid, _expected_preset_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor  uuid := auth.uid();
  v_preset public.project_people_presets;
  v_member public.project_people_preset_members;
  v_count  int;
BEGIN
  SELECT * INTO v_member FROM public.project_people_preset_members WHERE id = _member_id FOR UPDATE;
  IF v_member.id IS NULL THEN
    RETURN public.pmg_build_result('no_change', 'remove_project_people_preset_member',
      'project_people_preset_member', NULL, NULL,
      jsonb_build_object('reason','not_found'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = v_member.preset_id FOR UPDATE;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  IF v_preset.updated_at IS DISTINCT FROM _expected_preset_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'remove_project_people_preset_member',
      'project_people_preset_member', _member_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  SELECT COUNT(*)::int INTO v_count FROM public.project_people_preset_members WHERE preset_id = v_member.preset_id;
  IF v_count <= 1 THEN
    RETURN public.pmg_build_result('invalid', 'remove_project_people_preset_member',
      'project_people_preset_member', _member_id, NULL,
      jsonb_build_object('reason','cannot_remove_final_member'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  DELETE FROM public.project_people_preset_members WHERE id = _member_id;
  UPDATE public.project_people_presets SET updated_at = now() WHERE id = v_member.preset_id;

  PERFORM public._ppp_record_audit('applied', 'remove_project_people_preset_member',
    v_preset, 'project_people_preset_member', _member_id, _correlation_id, _idempotency_key,
    jsonb_build_object('member_kind', v_member.member_kind, 'stakeholder_type', v_member.stakeholder_type));

  RETURN public.pmg_build_result('applied', 'remove_project_people_preset_member',
    'project_people_preset_member', _member_id, NULL,
    jsonb_build_object('id', _member_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $$;


--
-- Name: remove_project_stakeholder(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_project_stakeholder(_stakeholder_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_row public.project_stakeholders;
  v_display text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
  INTO v_row
  FROM public.project_stakeholders
  WHERE id = _stakeholder_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Stakeholder not found';
  END IF;

  IF NOT (public.is_org_admin(v_actor, v_row.organization_id) OR public.has_pm_authority(v_actor, v_row.workspace_id)) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_row.removed_at IS NOT NULL THEN
    RETURN;
  END IF;

  UPDATE public.project_stakeholders
  SET removed_at = now(), removed_by = v_actor
  WHERE id = _stakeholder_id;

  IF v_row.stakeholder_type = 'workspace_member' THEN
    SELECT COALESCE(display_name, email, v_row.user_id::text)
    INTO v_display
    FROM public.profiles
    WHERE id = v_row.user_id;
  ELSE
    v_display := v_row.external_name;
  END IF;

  PERFORM public.log_activity_event(
    v_row.organization_id,
    v_actor,
    'stakeholder_removed',
    'project',
    v_row.project_id,
    jsonb_build_object(
      'stakeholder_id', _stakeholder_id,
      'stakeholder_type', v_row.stakeholder_type,
      'display_name', v_display,
      'role_label', v_row.role_label,
      'start_date', v_row.start_date
    ),
    v_row.workspace_id
  );
END;
$$;


--
-- Name: remove_roadmap_story_pack_external_file(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_roadmap_story_pack_external_file(_file_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _story_pack_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT story_pack_id INTO _story_pack_id FROM public.roadmap_story_pack_external_files WHERE id = _file_id;
  IF _story_pack_id IS NULL OR NOT public.is_story_pack_owner(_uid, _story_pack_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.assert_roadmap_story_pack_editable(_story_pack_id);
  DELETE FROM public.roadmap_story_pack_external_files WHERE id = _file_id;
END;
$$;


--
-- Name: rename_project_people_preset(uuid, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_project_people_preset(_preset_id uuid, _name text, _description text, _expected_updated_at timestamp with time zone, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_preset      public.project_people_presets;
  v_name_norm   text;
  v_desc_norm   text;
  v_dupe        uuid;
  r             record;
BEGIN
  SELECT * INTO v_preset FROM public.project_people_presets WHERE id = _preset_id FOR UPDATE;
  IF v_preset.id IS NULL THEN
    RETURN public.pmg_build_result('not_authorized', 'rename_project_people_preset',
      'project_people_preset', NULL, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;
  PERFORM public._ppp_authorize_write(v_actor, v_preset, true);

  v_name_norm := NULLIF(btrim(COALESCE(_name, '')), '');
  v_desc_norm := NULLIF(btrim(COALESCE(_description, '')), '');
  IF v_name_norm IS NULL THEN
    RETURN public.pmg_build_result('invalid', 'rename_project_people_preset',
      'project_people_preset', _preset_id, NULL,
      jsonb_build_object('reason','name_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  IF v_preset.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RETURN public.pmg_build_result('conflict', 'rename_project_people_preset',
      'project_people_preset', _preset_id, NULL, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('server_updated_at', v_preset.updated_at));
  END IF;

  -- Duplicate name within same workspace amongst active presets (decrypt + compare, locked scope)
  FOR r IN
    SELECT id, name FROM public.project_people_presets
     WHERE workspace_id = v_preset.workspace_id
       AND archived_at IS NULL
       AND id <> _preset_id
     FOR UPDATE
  LOOP
    IF lower(btrim(public.btpm_decrypt(r.name, v_preset.organization_id))) = lower(v_name_norm) THEN
      v_dupe := r.id;
      EXIT;
    END IF;
  END LOOP;

  IF v_dupe IS NOT NULL THEN
    RETURN public.pmg_build_result('invalid', 'rename_project_people_preset',
      'project_people_preset', _preset_id, NULL,
      jsonb_build_object('reason','duplicate_name'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  UPDATE public.project_people_presets
     SET name = v_name_norm, description = v_desc_norm
   WHERE id = _preset_id;

  PERFORM public._ppp_record_audit('applied', 'rename_project_people_preset',
    v_preset, 'project_people_preset', _preset_id, _correlation_id, _idempotency_key,
    jsonb_build_object('description_present', v_desc_norm IS NOT NULL));

  RETURN public.pmg_build_result('applied', 'rename_project_people_preset',
    'project_people_preset', _preset_id, NULL,
    jsonb_build_object('id', _preset_id),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $$;


--
-- Name: reopen_phase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_phase(_phase_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row public.phases%ROWTYPE;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT * INTO v_row FROM public.phases WHERE id = _phase_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Phase not found'; END IF;

  IF NOT public.has_pm_authority(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: PM authority required to reopen a phase';
  END IF;

  IF NOT public.can_write_demo(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  IF v_row.status <> 'completed' THEN
    RAISE EXCEPTION 'Only completed phases can be reopened (current status: %)', v_row.status;
  END IF;

  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  UPDATE public.phases
  SET status     = 'active',
      updated_at = now()
  WHERE id = _phase_id;
  PERFORM set_config('app.allow_lifecycle_bypass', '', true);

  PERFORM public.log_activity_event(
    v_row.organization_id,
    auth.uid(),
    'phase_reopened',
    'phase',
    _phase_id,
    jsonb_build_object(
      'prior_status', 'completed',
      'new_status',   'active',
      'project_id',   v_row.project_id
    ),
    v_row.workspace_id
  );
END;
$$;


--
-- Name: reopen_task(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_task(_task_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row public.tasks%ROWTYPE;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'Account is deactivated';
  END IF;

  SELECT * INTO v_row FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;

  IF NOT public.has_pm_authority(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: PM authority required to reopen a task';
  END IF;

  IF NOT public.can_write_demo(auth.uid(), v_row.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized: this workspace is read-only';
  END IF;

  IF v_row.status <> 'completed' THEN
    RAISE EXCEPTION 'Only completed tasks can be reopened (current status: %)', v_row.status;
  END IF;

  PERFORM set_config('app.allow_lifecycle_bypass', 'on', true);
  UPDATE public.tasks
  SET status     = 'active',
      updated_at = now()
  WHERE id = _task_id;
  PERFORM set_config('app.allow_lifecycle_bypass', '', true);

  PERFORM public.log_activity_event(
    v_row.organization_id,
    auth.uid(),
    'task_reopened',
    'task',
    _task_id,
    jsonb_build_object(
      'prior_status', 'completed',
      'new_status',   'active',
      'project_id',   v_row.project_id,
      'phase_id',     v_row.phase_id
    ),
    v_row.workspace_id
  );
END;
$$;


--
-- Name: reorder_backlog_items(uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_backlog_items(_project_id uuid, _rows jsonb, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_project record;
  v_input_count int;
  v_stale_ids uuid[];
  v_changed_count int := 0;
  v_audit_status public.pmg_command_status;
  v_data jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, workspace_id INTO v_project FROM public.projects WHERE id = _project_id;
  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _rows IS NULL OR jsonb_typeof(_rows) <> 'array' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','rows_not_array'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._pmg_backlog_reorder_input;
  CREATE TEMP TABLE _pmg_backlog_reorder_input (
    id uuid,
    expected_updated_at timestamptz,
    new_sort_order integer
  ) ON COMMIT DROP;

  BEGIN
    INSERT INTO pg_temp._pmg_backlog_reorder_input (id, expected_updated_at, new_sort_order)
    SELECT (elem->>'id')::uuid,
           (elem->>'expected_updated_at')::timestamptz,
           (elem->>'new_sort_order')::int
      FROM jsonb_array_elements(_rows) AS elem;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','malformed_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT count(*) INTO v_input_count FROM pg_temp._pmg_backlog_reorder_input;

  IF v_input_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','no_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_backlog_reorder_input
     WHERE id IS NULL OR expected_updated_at IS NULL OR new_sort_order IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','row_field_missing'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT id) FROM pg_temp._pmg_backlog_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','duplicate_row_ids'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT new_sort_order) FROM pg_temp._pmg_backlog_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','duplicate_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  -- Lock the parent scope: all backlog rows for this project.
  PERFORM 1 FROM public.backlog_items WHERE project_id = _project_id FOR UPDATE;

  -- Every submitted id must exist in this project.
  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_backlog_reorder_input i
      LEFT JOIN public.backlog_items b
        ON b.id = i.id AND b.project_id = _project_id
     WHERE b.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      jsonb_build_object('reason','unknown_or_cross_project_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT COALESCE(array_agg(b.id), ARRAY[]::uuid[])
    INTO v_stale_ids
    FROM public.backlog_items b
    JOIN pg_temp._pmg_backlog_reorder_input i ON i.id = b.id
   WHERE b.project_id = _project_id
     AND b.updated_at IS DISTINCT FROM i.expected_updated_at;

  IF array_length(v_stale_ids, 1) IS NOT NULL THEN
    PERFORM public.pmg_record_command_audit(
      'conflict'::public.pmg_command_status, 'reorder_backlog_items',
      'btpm_ui'::public.pmg_source_channel,
      _project_id, 'backlog_item_collection', _project_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'submitted_count', v_input_count,
        'changed_count', 0,
        'stale_count', array_length(v_stale_ids, 1)
      )
    );
    RETURN public.pmg_build_result(
      'conflict'::public.pmg_command_status, 'reorder_backlog_items',
      'backlog_item_collection', _project_id, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object('code','stale_backlog_order','stale_ids', to_jsonb(v_stale_ids))
    );
  END IF;

  WITH upd AS (
    UPDATE public.backlog_items b
       SET sort_order = i.new_sort_order
      FROM pg_temp._pmg_backlog_reorder_input i
     WHERE b.id = i.id
       AND b.project_id = _project_id
       AND b.sort_order IS DISTINCT FROM i.new_sort_order
    RETURNING b.id
  )
  SELECT count(*) INTO v_changed_count FROM upd;

  v_audit_status := CASE WHEN v_changed_count = 0
    THEN 'no_change'::public.pmg_command_status
    ELSE 'applied'::public.pmg_command_status END;

  SELECT jsonb_build_object(
    'submitted_count', v_input_count,
    'changed_count', v_changed_count,
    'ordered_items', COALESCE(jsonb_agg(
      jsonb_build_object('id', b.id, 'sort_order', b.sort_order, 'updated_at', b.updated_at)
      ORDER BY b.sort_order
    ), '[]'::jsonb)
  ) INTO v_data
  FROM public.backlog_items b
  WHERE b.id IN (SELECT id FROM pg_temp._pmg_backlog_reorder_input);

  PERFORM public.pmg_record_command_audit(
    v_audit_status, 'reorder_backlog_items',
    'btpm_ui'::public.pmg_source_channel,
    _project_id, 'backlog_item_collection', _project_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'submitted_count', v_input_count,
      'changed_count', v_changed_count,
      'stale_count', 0
    )
  );

  RETURN public.pmg_build_result(
    v_audit_status, 'reorder_backlog_items',
    'backlog_item_collection', _project_id, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$$;


--
-- Name: reorder_phases(uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_phases(_project_id uuid, _rows jsonb, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  -- API-M.6A: server-derived source channel. Never caller-provided.
  v_client_id text;
  v_trusted boolean := false;
  v_source_channel public.pmg_source_channel := 'btpm_ui'::public.pmg_source_channel;
  -- API-Q Phase Reorder Step 1: trusted channel is server-derived only.
  v_trusted_channel text;
  v_actor uuid := auth.uid();
  v_project record;
  v_input_count int;
  v_existing_count int;
  v_stale_ids uuid[];
  v_changed_count int := 0;
  v_audit_status public.pmg_command_status;
  v_data jsonb;
BEGIN
  -- 0. API-M.6A source-awareness + exact-capability containment.
  --    Exception-safe client identity (API-K.2 precedent).
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    BEGIN
      v_trusted := api_e_private.assert_trusted_context();
    EXCEPTION WHEN OTHERS THEN
      v_trusted := false;
    END;

    v_trusted_channel := nullif(btrim(coalesce(current_setting('api_e.source_channel', true),'')),'');

    IF v_trusted IS NOT TRUE
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.api_version', true),'')),''), '') <> 'v1'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_kind', true),'')),''), '') <> 'command'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_key', true),'')),''), '') <> 'phases:reorder'
       OR v_trusted_channel IS NULL
       OR v_trusted_channel NOT IN ('external_api','mcp')
    THEN
      -- Fail closed BEFORE any target lookup, row lock, write or audit.
      RETURN public.pmg_build_result(
        _status => 'not_authorized'::public.pmg_command_status,
        _command => 'reorder_phases',
        _target_type => 'phase_collection',
        _target_id => NULL,
        _project_id => _project_id,
        _data => '{}'::jsonb,
        _changes => '[]'::jsonb,
        _warnings => '[]'::jsonb,
        _confirmations => '[]'::jsonb,
        _conflict => NULL
      );
    END IF;

    IF v_trusted_channel = 'external_api' THEN
      v_source_channel := 'external_api'::public.pmg_source_channel;
    ELSE
      v_source_channel := 'mcp'::public.pmg_source_channel;
    END IF;
  END IF;

  -- Authentication
  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  -- Project existence
  SELECT id, organization_id, workspace_id
    INTO v_project
    FROM public.projects
   WHERE id = _project_id;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  -- Authority (project-level PM + demo write gate on resolved workspace)
  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      _status => 'not_authorized'::public.pmg_command_status,
      _command => 'reorder_phases',
      _target_type => 'phase_collection',
      _target_id => NULL,
      _project_id => _project_id,
      _data => '{}'::jsonb,
      _changes => '[]'::jsonb,
      _warnings => '[]'::jsonb,
      _confirmations => '[]'::jsonb,
      _conflict => NULL
    );
  END IF;

  -- Structural validation of _rows
  IF _rows IS NULL OR jsonb_typeof(_rows) <> 'array' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','rows_not_array'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._pmg_reorder_input;
  CREATE TEMP TABLE _pmg_reorder_input (
    id uuid,
    expected_updated_at timestamptz,
    new_sort_order integer
  ) ON COMMIT DROP;

  BEGIN
    INSERT INTO pg_temp._pmg_reorder_input (id, expected_updated_at, new_sort_order)
    SELECT
      (elem->>'id')::uuid,
      (elem->>'expected_updated_at')::timestamptz,
      (elem->>'new_sort_order')::int
    FROM jsonb_array_elements(_rows) AS elem;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','malformed_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT count(*) INTO v_input_count FROM pg_temp._pmg_reorder_input;

  IF v_input_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','no_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_reorder_input
     WHERE id IS NULL OR expected_updated_at IS NULL OR new_sort_order IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','row_field_missing'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT id) FROM pg_temp._pmg_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','duplicate_row_ids'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT new_sort_order) FROM pg_temp._pmg_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','duplicate_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT (
    SELECT bool_and(new_sort_order = expected_pos)
      FROM (
        SELECT new_sort_order,
               row_number() OVER (ORDER BY new_sort_order) - 1 AS expected_pos
          FROM pg_temp._pmg_reorder_input
      ) x
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','non_contiguous_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  PERFORM 1 FROM public.phases WHERE project_id = _project_id FOR UPDATE;

  SELECT count(*) INTO v_existing_count
    FROM public.phases WHERE project_id = _project_id;

  IF v_input_count <> v_existing_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object(
        'reason','row_count_mismatch',
        'submitted_count', v_input_count,
        'expected_count', v_existing_count
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_reorder_input i
      LEFT JOIN public.phases ph
        ON ph.id = i.id AND ph.project_id = _project_id
     WHERE ph.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','unknown_or_cross_project_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.phases ph
      LEFT JOIN pg_temp._pmg_reorder_input i ON i.id = ph.id
     WHERE ph.project_id = _project_id AND i.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      jsonb_build_object('reason','missing_phase_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT COALESCE(array_agg(ph.id), ARRAY[]::uuid[])
    INTO v_stale_ids
    FROM public.phases ph
    JOIN pg_temp._pmg_reorder_input i ON i.id = ph.id
   WHERE ph.project_id = _project_id
     AND ph.updated_at IS DISTINCT FROM i.expected_updated_at;

  IF array_length(v_stale_ids, 1) IS NOT NULL THEN
    v_audit_status := 'conflict'::public.pmg_command_status;
    PERFORM public.pmg_record_command_audit(
      v_audit_status, 'reorder_phases',
      v_source_channel,
      _project_id, 'phase_collection', NULL, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'submitted_count', v_input_count,
        'changed_count', 0,
        'stale_count', array_length(v_stale_ids, 1)
      )
    );
    RETURN public.pmg_build_result(
      v_audit_status, 'reorder_phases',
      'phase_collection', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object(
        'code', 'stale_phase_order',
        'stale_ids', to_jsonb(v_stale_ids)
      )
    );
  END IF;

  WITH upd AS (
    UPDATE public.phases ph
       SET sort_order = i.new_sort_order
      FROM pg_temp._pmg_reorder_input i
     WHERE ph.id = i.id
       AND ph.project_id = _project_id
       AND ph.sort_order IS DISTINCT FROM i.new_sort_order
    RETURNING ph.id
  )
  SELECT count(*) INTO v_changed_count FROM upd;

  IF v_changed_count = 0 THEN
    v_audit_status := 'no_change'::public.pmg_command_status;
  ELSE
    v_audit_status := 'applied'::public.pmg_command_status;
  END IF;

  SELECT jsonb_build_object(
    'submitted_count', v_input_count,
    'changed_count', v_changed_count,
    'ordered_phases', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', ph.id,
        'sort_order', ph.sort_order,
        'updated_at', ph.updated_at
      ) ORDER BY ph.sort_order
    ), '[]'::jsonb)
  )
  INTO v_data
  FROM public.phases ph
  WHERE ph.project_id = _project_id;

  PERFORM public.pmg_record_command_audit(
    v_audit_status, 'reorder_phases',
    v_source_channel,
    _project_id, 'phase_collection', NULL, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'submitted_count', v_input_count,
      'changed_count', v_changed_count,
      'stale_count', 0
    )
  );

  RETURN public.pmg_build_result(
    v_audit_status, 'reorder_phases',
    'phase_collection', NULL, _project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$$;


--
-- Name: reorder_tasks(uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_tasks(_phase_id uuid, _rows jsonb, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  -- API-M.9A: server-derived source channel. Never caller-provided.
  v_client_id text;
  v_trusted boolean := false;
  v_source_channel public.pmg_source_channel := 'btpm_ui'::public.pmg_source_channel;
  -- API-Q Task Reorder Step 1: trusted channel is server-derived only.
  v_trusted_channel text;
  v_actor uuid := auth.uid();
  v_phase record;
  v_project_id uuid;
  v_input_count int;
  v_existing_count int;
  v_stale_ids uuid[];
  v_changed_count int := 0;
  v_audit_status public.pmg_command_status;
  v_data jsonb;
BEGIN
  -- 0. API-M.9A source-awareness + exact-capability containment.
  --    Exception-safe client identity (API-K.2 / API-M.6A precedent).
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    BEGIN
      v_trusted := api_e_private.assert_trusted_context();
    EXCEPTION WHEN OTHERS THEN
      v_trusted := false;
    END;

    v_trusted_channel := nullif(btrim(coalesce(current_setting('api_e.source_channel', true),'')),'');

    IF v_trusted IS NOT TRUE
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.api_version', true),'')),''), '') <> 'v1'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_kind', true),'')),''), '') <> 'command'
       OR COALESCE(NULLIF(btrim(COALESCE(current_setting('api_e.capability_key', true),'')),''), '') <> 'tasks:reorder'
       OR v_trusted_channel IS NULL
       OR v_trusted_channel NOT IN ('external_api','mcp')
    THEN
      -- Fail closed BEFORE is_active_user, Phase lookup, temp table, FOR UPDATE,
      -- write or audit.
      RETURN public.pmg_build_result(
        'not_authorized'::public.pmg_command_status, 'reorder_tasks',
        'task_collection', _phase_id, NULL,
        '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
      );
    END IF;

    IF v_trusted_channel = 'external_api' THEN
      v_source_channel := 'external_api'::public.pmg_source_channel;
    ELSE
      v_source_channel := 'mcp'::public.pmg_source_channel;
    END IF;
  END IF;

  IF v_actor IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT id, project_id, workspace_id
    INTO v_phase
    FROM public.phases
   WHERE id = _phase_id;

  IF v_phase.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, NULL,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  v_project_id := v_phase.project_id;

  IF NOT public.has_project_pm_authority(v_actor, v_project_id)
     OR NOT public.can_write_demo(v_actor, v_phase.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF _rows IS NULL OR jsonb_typeof(_rows) <> 'array' THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','rows_not_array'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._pmg_task_reorder_input;
  CREATE TEMP TABLE _pmg_task_reorder_input (
    id uuid,
    expected_updated_at timestamptz,
    new_sort_order integer
  ) ON COMMIT DROP;

  BEGIN
    INSERT INTO pg_temp._pmg_task_reorder_input (id, expected_updated_at, new_sort_order)
    SELECT
      (elem->>'id')::uuid,
      (elem->>'expected_updated_at')::timestamptz,
      (elem->>'new_sort_order')::int
    FROM jsonb_array_elements(_rows) AS elem;
  EXCEPTION WHEN others THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','malformed_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END;

  SELECT count(*) INTO v_input_count FROM pg_temp._pmg_task_reorder_input;

  IF v_input_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','no_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_task_reorder_input
     WHERE id IS NULL OR expected_updated_at IS NULL OR new_sort_order IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','row_field_missing'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT id) FROM pg_temp._pmg_task_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','duplicate_row_ids'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF (SELECT count(DISTINCT new_sort_order) FROM pg_temp._pmg_task_reorder_input) <> v_input_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','duplicate_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF NOT (
    SELECT bool_and(new_sort_order = expected_pos)
      FROM (
        SELECT new_sort_order,
               row_number() OVER (ORDER BY new_sort_order) - 1 AS expected_pos
          FROM pg_temp._pmg_task_reorder_input
      ) x
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','non_contiguous_sort_positions'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  PERFORM 1 FROM public.tasks WHERE phase_id = _phase_id FOR UPDATE;

  SELECT count(*) INTO v_existing_count
    FROM public.tasks WHERE phase_id = _phase_id;

  IF v_input_count <> v_existing_count THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object(
        'reason','row_count_mismatch',
        'submitted_count', v_input_count,
        'expected_count', v_existing_count
      ),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_temp._pmg_task_reorder_input i
      LEFT JOIN public.tasks t
        ON t.id = i.id AND t.phase_id = _phase_id
     WHERE t.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','unknown_or_cross_phase_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tasks t
      LEFT JOIN pg_temp._pmg_task_reorder_input i ON i.id = t.id
     WHERE t.phase_id = _phase_id AND i.id IS NULL
  ) THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      jsonb_build_object('reason','missing_task_rows'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
    );
  END IF;

  SELECT COALESCE(array_agg(t.id), ARRAY[]::uuid[])
    INTO v_stale_ids
    FROM public.tasks t
    JOIN pg_temp._pmg_task_reorder_input i ON i.id = t.id
   WHERE t.phase_id = _phase_id
     AND t.updated_at IS DISTINCT FROM i.expected_updated_at;

  IF array_length(v_stale_ids, 1) IS NOT NULL THEN
    v_audit_status := 'conflict'::public.pmg_command_status;
    PERFORM public.pmg_record_command_audit(
      v_audit_status, 'reorder_tasks',
      v_source_channel,
      v_project_id, 'task_collection', _phase_id, NULL,
      _correlation_id, _idempotency_key,
      jsonb_build_object(
        'submitted_count', v_input_count,
        'changed_count', 0,
        'stale_count', array_length(v_stale_ids, 1)
      )
    );
    RETURN public.pmg_build_result(
      v_audit_status, 'reorder_tasks',
      'task_collection', _phase_id, v_project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
      jsonb_build_object(
        'code', 'stale_task_order',
        'stale_ids', to_jsonb(v_stale_ids)
      )
    );
  END IF;

  WITH upd AS (
    UPDATE public.tasks t
       SET sort_order = i.new_sort_order
      FROM pg_temp._pmg_task_reorder_input i
     WHERE t.id = i.id
       AND t.phase_id = _phase_id
       AND t.sort_order IS DISTINCT FROM i.new_sort_order
    RETURNING t.id
  )
  SELECT count(*) INTO v_changed_count FROM upd;

  IF v_changed_count = 0 THEN
    v_audit_status := 'no_change'::public.pmg_command_status;
  ELSE
    v_audit_status := 'applied'::public.pmg_command_status;
  END IF;

  SELECT jsonb_build_object(
    'submitted_count', v_input_count,
    'changed_count', v_changed_count,
    'ordered_tasks', COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', t.id,
        'sort_order', t.sort_order,
        'updated_at', t.updated_at
      ) ORDER BY t.sort_order
    ), '[]'::jsonb)
  )
  INTO v_data
  FROM public.tasks t
  WHERE t.phase_id = _phase_id;

  PERFORM public.pmg_record_command_audit(
    v_audit_status, 'reorder_tasks',
    v_source_channel,
    v_project_id, 'task_collection', _phase_id, NULL,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'submitted_count', v_input_count,
      'changed_count', v_changed_count,
      'stale_count', 0
    )
  );

  RETURN public.pmg_build_result(
    v_audit_status, 'reorder_tasks',
    'task_collection', _phase_id, v_project_id,
    v_data, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL
  );
END;
$$;


--
-- Name: report_governance_cadences(uuid, uuid, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_governance_cadences(_organization_id uuid, _workspace_id uuid DEFAULT NULL::uuid, _project_ids uuid[] DEFAULT NULL::uuid[], _include_archived boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
BEGIN
  PERFORM _gov_report_assert_scope(_organization_id, _workspace_id);

  WITH eligible_projects AS (
    SELECT p.id, p.organization_id, p.workspace_id
    FROM projects p
    WHERE p.organization_id = _organization_id
      AND (_workspace_id IS NULL OR p.workspace_id = _workspace_id)
      AND (_project_ids IS NULL OR p.id = ANY(_project_ids))
      AND (
        is_org_admin(_uid, p.organization_id)
        OR is_workspace_member(_uid, p.workspace_id)
      )
  ),
  cadence_record_agg AS (
    SELECT
      r.cadence_id,
      COUNT(*) FILTER (WHERE r.archived_at IS NULL) AS record_count,
      MAX(CASE WHEN r.archived_at IS NULL THEN r.actual_date_held END) AS last_completed_date
    FROM governance_records r
    WHERE r.cadence_id IS NOT NULL
      AND r.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY r.cadence_id
  ),
  decision_per_cadence AS (
    SELECT r.cadence_id, COUNT(d.*) AS decision_count
    FROM governance_records r
    LEFT JOIN governance_record_decisions d
           ON d.governance_record_id = r.id AND d.archived_at IS NULL
    WHERE r.cadence_id IS NOT NULL
      AND r.archived_at IS NULL
      AND r.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY r.cadence_id
  ),
  link_per_cadence AS (
    SELECT r.cadence_id, COUNT(l.*) AS link_count
    FROM governance_records r
    LEFT JOIN governance_record_links l
           ON l.governance_record_id = r.id AND l.archived_at IS NULL
    WHERE r.cadence_id IS NOT NULL
      AND r.archived_at IS NULL
      AND r.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY r.cadence_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'organization_id',     c.organization_id,
    'workspace_id',        c.workspace_id,
    'project_id',          c.project_id,
    'cadence_id',          c.id,
    'event_type',          c.event_type,
    'event_name',          public.btpm_decrypt(c.event_name, c.organization_id),
    'frequency_type',      c.frequency_type,
    'owner_id',            c.owner_id,
    'owner_display_name',  CASE WHEN c.owner_id IS NULL THEN NULL
                                ELSE public.btpm_decrypt(pr.display_name, c.organization_id) END,
    'owner_email',         CASE WHEN c.owner_id IS NULL THEN NULL ELSE pr.email END,
    'next_expected_date',  c.next_expected_date,
    'last_completed_date', cra.last_completed_date,
    'record_count',        COALESCE(cra.record_count, 0),
    'decision_count',      COALESCE(dpc.decision_count, 0),
    'link_count',          COALESCE(lpc.link_count, 0),
    'derived_status',      _gov_derive_cadence_status(c.frequency_type, c.next_expected_date, c.archived_at),
    'is_archived',         (c.archived_at IS NOT NULL),
    'archived_at',         c.archived_at,
    'created_at',          c.created_at,
    'updated_at',          c.updated_at
  )), '[]'::jsonb)
  INTO _result
  FROM governance_cadences c
  JOIN eligible_projects ep ON ep.id = c.project_id
  LEFT JOIN profiles pr ON pr.id = c.owner_id
  LEFT JOIN cadence_record_agg cra ON cra.cadence_id = c.id
  LEFT JOIN decision_per_cadence dpc ON dpc.cadence_id = c.id
  LEFT JOIN link_per_cadence lpc ON lpc.cadence_id = c.id
  WHERE _include_archived OR c.archived_at IS NULL;

  RETURN _result;
END;
$$;


--
-- Name: report_governance_event_types(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_governance_event_types(_organization_id uuid, _workspace_id uuid DEFAULT NULL::uuid, _project_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
BEGIN
  PERFORM _gov_report_assert_scope(_organization_id, _workspace_id);

  WITH eligible_projects AS (
    SELECT p.id, p.organization_id, p.workspace_id
    FROM projects p
    WHERE p.organization_id = _organization_id
      AND (_workspace_id IS NULL OR p.workspace_id = _workspace_id)
      AND (_project_ids IS NULL OR p.id = ANY(_project_ids))
      AND (
        is_org_admin(_uid, p.organization_id)
        OR is_workspace_member(_uid, p.workspace_id)
      )
  ),
  cadence_buckets AS (
    SELECT
      c.organization_id, c.workspace_id, c.project_id, c.event_type,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL) AS active_cadence_count,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL
                          AND c.frequency_type <> 'ad_hoc'
                          AND c.next_expected_date IS NOT NULL
                          AND c.next_expected_date < CURRENT_DATE) AS overdue_count,
      MIN(CASE WHEN c.archived_at IS NULL
                AND c.frequency_type <> 'ad_hoc'
                AND c.next_expected_date IS NOT NULL
              THEN c.next_expected_date END) AS next_expected_date
    FROM governance_cadences c
    WHERE c.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY c.organization_id, c.workspace_id, c.project_id, c.event_type
  ),
  record_buckets AS (
    SELECT
      r.project_id, r.event_type,
      COUNT(*) FILTER (WHERE r.archived_at IS NULL) AS record_count,
      MAX(CASE WHEN r.archived_at IS NULL THEN r.actual_date_held END) AS latest_record_date
    FROM governance_records r
    WHERE r.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY r.project_id, r.event_type
  ),
  decision_buckets AS (
    SELECT r.project_id, r.event_type, COUNT(d.*) AS decision_count
    FROM governance_records r
    LEFT JOIN governance_record_decisions d
           ON d.governance_record_id = r.id AND d.archived_at IS NULL
    WHERE r.archived_at IS NULL
      AND r.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY r.project_id, r.event_type
  ),
  unioned AS (
    SELECT cb.project_id, cb.event_type FROM cadence_buckets cb
    UNION
    SELECT rb.project_id, rb.event_type FROM record_buckets rb
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'organization_id',      ep.organization_id,
    'workspace_id',         ep.workspace_id,
    'project_id',           u.project_id,
    'event_type',           u.event_type,
    'active_cadence_count', COALESCE(cb.active_cadence_count, 0),
    'record_count',         COALESCE(rb.record_count, 0),
    'decision_count',       COALESCE(db.decision_count, 0),
    'latest_record_date',   rb.latest_record_date,
    'next_expected_date',   cb.next_expected_date,
    'overdue_count',        COALESCE(cb.overdue_count, 0)
  )), '[]'::jsonb)
  INTO _result
  FROM unioned u
  JOIN eligible_projects ep ON ep.id = u.project_id
  LEFT JOIN cadence_buckets  cb ON cb.project_id = u.project_id AND cb.event_type = u.event_type
  LEFT JOIN record_buckets   rb ON rb.project_id = u.project_id AND rb.event_type = u.event_type
  LEFT JOIN decision_buckets db ON db.project_id = u.project_id AND db.event_type = u.event_type;

  RETURN _result;
END;
$$;


--
-- Name: report_governance_records(uuid, uuid, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_governance_records(_organization_id uuid, _workspace_id uuid DEFAULT NULL::uuid, _project_ids uuid[] DEFAULT NULL::uuid[], _include_archived boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
BEGIN
  PERFORM _gov_report_assert_scope(_organization_id, _workspace_id);

  WITH eligible_projects AS (
    SELECT p.id, p.organization_id, p.workspace_id
    FROM projects p
    WHERE p.organization_id = _organization_id
      AND (_workspace_id IS NULL OR p.workspace_id = _workspace_id)
      AND (_project_ids IS NULL OR p.id = ANY(_project_ids))
      AND (
        is_org_admin(_uid, p.organization_id)
        OR is_workspace_member(_uid, p.workspace_id)
      )
  ),
  decisions_per_record AS (
    SELECT d.governance_record_id, COUNT(*) AS decision_count
    FROM governance_record_decisions d
    WHERE d.archived_at IS NULL
      AND d.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY d.governance_record_id
  ),
  links_per_record AS (
    SELECT
      l.governance_record_id,
      COUNT(*)                                                          AS link_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'task')             AS linked_task_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'phase')            AS linked_phase_reference_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'risk')             AS linked_risk_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'blocker')          AS linked_blocker_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'kpi_definition')   AS linked_kpi_definition_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'kpi_update')       AS linked_kpi_update_count
    FROM governance_record_links l
    WHERE l.archived_at IS NULL
      AND l.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY l.governance_record_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'organization_id',              r.organization_id,
    'workspace_id',                 r.workspace_id,
    'project_id',                   r.project_id,
    'record_id',                    r.id,
    'cadence_id',                   r.cadence_id,
    'event_type',                   r.event_type,
    'event_name',                   public.btpm_decrypt(r.event_name, r.organization_id),
    'expected_date_snapshot',       r.expected_date_snapshot,
    'actual_date_held',             r.actual_date_held,
    'was_late',                     CASE
      WHEN r.expected_date_snapshot IS NULL THEN NULL
      ELSE r.actual_date_held > r.expected_date_snapshot
    END,
    'days_late',                    CASE
      WHEN r.expected_date_snapshot IS NULL THEN NULL
      ELSE GREATEST(0, (r.actual_date_held - r.expected_date_snapshot))
    END,
    'has_sharepoint_evidence',      (r.sharepoint_evidence_reference IS NOT NULL),
    'has_external_reference_url',   (r.external_reference_url IS NOT NULL),
    'decision_count',               COALESCE(dpr.decision_count, 0),
    'link_count',                   COALESCE(lpr.link_count, 0),
    'linked_task_count',            COALESCE(lpr.linked_task_count, 0),
    'linked_phase_reference_count', COALESCE(lpr.linked_phase_reference_count, 0),
    'linked_risk_count',            COALESCE(lpr.linked_risk_count, 0),
    'linked_blocker_count',         COALESCE(lpr.linked_blocker_count, 0),
    'linked_kpi_definition_count',  COALESCE(lpr.linked_kpi_definition_count, 0),
    'linked_kpi_update_count',      COALESCE(lpr.linked_kpi_update_count, 0),
    'is_archived',                  (r.archived_at IS NOT NULL),
    'archived_at',                  r.archived_at,
    'created_at',                   r.created_at,
    'created_by',                   r.created_by
  )), '[]'::jsonb)
  INTO _result
  FROM governance_records r
  JOIN eligible_projects ep ON ep.id = r.project_id
  LEFT JOIN decisions_per_record dpr ON dpr.governance_record_id = r.id
  LEFT JOIN links_per_record lpr ON lpr.governance_record_id = r.id
  WHERE _include_archived OR r.archived_at IS NULL;

  RETURN _result;
END;
$$;


--
-- Name: report_project_governance_summary(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_project_governance_summary(_organization_id uuid, _workspace_id uuid DEFAULT NULL::uuid, _project_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _result jsonb;
BEGIN
  PERFORM _gov_report_assert_scope(_organization_id, _workspace_id);

  WITH eligible_projects AS (
    SELECT p.id, p.organization_id, p.workspace_id,
           public.btpm_decrypt(p.name, p.organization_id) AS project_name
    FROM projects p
    WHERE p.organization_id = _organization_id
      AND (_workspace_id IS NULL OR p.workspace_id = _workspace_id)
      AND (_project_ids IS NULL OR p.id = ANY(_project_ids))
      AND (
        is_org_admin(_uid, p.organization_id)
        OR is_workspace_member(_uid, p.workspace_id)
      )
  ),
  ws AS (
    SELECT w.id, public.btpm_decrypt(w.name, w.organization_id) AS workspace_name
    FROM workspaces w
    WHERE w.organization_id = _organization_id
  ),
  cadence_agg AS (
    SELECT
      c.project_id,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL)                          AS active_cadence_count,
      COUNT(*) FILTER (WHERE c.archived_at IS NOT NULL)                      AS archived_cadence_count,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL
                          AND c.frequency_type <> 'ad_hoc'
                          AND c.next_expected_date IS NOT NULL
                          AND c.next_expected_date < CURRENT_DATE)           AS overdue_cadence_count,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL
                          AND c.frequency_type <> 'ad_hoc'
                          AND c.next_expected_date IS NOT NULL
                          AND c.next_expected_date >= CURRENT_DATE
                          AND c.next_expected_date <= CURRENT_DATE + INTERVAL '7 days')
                                                                              AS due_soon_cadence_count,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL AND c.frequency_type = 'ad_hoc')
                                                                              AS ad_hoc_cadence_count,
      COUNT(*) FILTER (WHERE c.archived_at IS NULL AND c.frequency_type <> 'ad_hoc')
                                                                              AS recurring_cadence_count
    FROM governance_cadences c
    WHERE c.project_id IN (SELECT id FROM eligible_projects)
    GROUP BY c.project_id
  ),
  next_expected AS (
    SELECT DISTINCT ON (c.project_id)
      c.project_id, c.next_expected_date, c.id AS cadence_id
    FROM governance_cadences c
    WHERE c.project_id IN (SELECT id FROM eligible_projects)
      AND c.archived_at IS NULL
      AND c.frequency_type <> 'ad_hoc'
      AND c.next_expected_date IS NOT NULL
    ORDER BY c.project_id, c.next_expected_date ASC
  ),
  last_completed AS (
    SELECT DISTINCT ON (r.project_id)
      r.project_id, r.actual_date_held, r.id AS record_id
    FROM governance_records r
    WHERE r.project_id IN (SELECT id FROM eligible_projects)
      AND r.archived_at IS NULL
    ORDER BY r.project_id, r.actual_date_held DESC, r.created_at DESC
  ),
  record_agg AS (
    SELECT
      r.project_id,
      COUNT(*)                                                                         AS total_record_count,
      COUNT(*) FILTER (WHERE r.actual_date_held >= CURRENT_DATE - INTERVAL '30 days')  AS records_last_30_days,
      COUNT(*) FILTER (WHERE r.actual_date_held >= CURRENT_DATE - INTERVAL '90 days')  AS records_last_90_days,
      COUNT(*) FILTER (WHERE r.sharepoint_evidence_reference IS NULL)                  AS records_missing_sharepoint_evidence_count
    FROM governance_records r
    WHERE r.project_id IN (SELECT id FROM eligible_projects)
      AND r.archived_at IS NULL
    GROUP BY r.project_id
  ),
  decision_agg AS (
    SELECT d.project_id, COUNT(*) AS decision_count
    FROM governance_record_decisions d
    WHERE d.project_id IN (SELECT id FROM eligible_projects)
      AND d.archived_at IS NULL
    GROUP BY d.project_id
  ),
  link_agg AS (
    SELECT
      l.project_id,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'task')           AS linked_task_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'phase')          AS linked_phase_reference_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'risk')           AS linked_risk_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'blocker')        AS linked_blocker_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'kpi_definition') AS linked_kpi_definition_count,
      COUNT(*) FILTER (WHERE l.linked_object_type = 'kpi_update')     AS linked_kpi_update_count
    FROM governance_record_links l
    WHERE l.project_id IN (SELECT id FROM eligible_projects)
      AND l.archived_at IS NULL
    GROUP BY l.project_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'organization_id',                          ep.organization_id,
    'workspace_id',                             ep.workspace_id,
    'workspace_name',                           ws.workspace_name,
    'project_id',                               ep.id,
    'project_name',                             ep.project_name,
    'active_cadence_count',                     COALESCE(ca.active_cadence_count, 0),
    'archived_cadence_count',                   COALESCE(ca.archived_cadence_count, 0),
    'overdue_cadence_count',                    COALESCE(ca.overdue_cadence_count, 0),
    'due_soon_cadence_count',                   COALESCE(ca.due_soon_cadence_count, 0),
    'ad_hoc_cadence_count',                     COALESCE(ca.ad_hoc_cadence_count, 0),
    'recurring_cadence_count',                  COALESCE(ca.recurring_cadence_count, 0),
    'next_expected_governance_date',            ne.next_expected_date,
    'next_expected_cadence_id',                 ne.cadence_id,
    'last_completed_governance_date',           lc.actual_date_held,
    'last_completed_record_id',                 lc.record_id,
    'total_governance_record_count',            COALESCE(ra.total_record_count, 0),
    'records_last_30_days',                     COALESCE(ra.records_last_30_days, 0),
    'records_last_90_days',                     COALESCE(ra.records_last_90_days, 0),
    'records_missing_sharepoint_evidence_count',COALESCE(ra.records_missing_sharepoint_evidence_count, 0),
    'decision_count',                           COALESCE(da.decision_count, 0),
    'linked_task_count',                        COALESCE(la.linked_task_count, 0),
    'linked_phase_reference_count',             COALESCE(la.linked_phase_reference_count, 0),
    'linked_risk_count',                        COALESCE(la.linked_risk_count, 0),
    'linked_blocker_count',                     COALESCE(la.linked_blocker_count, 0),
    'linked_kpi_definition_count',              COALESCE(la.linked_kpi_definition_count, 0),
    'linked_kpi_update_count',                  COALESCE(la.linked_kpi_update_count, 0),
    'governance_health_status',                 CASE
      WHEN COALESCE(ca.active_cadence_count, 0) = 0
           AND COALESCE(ca.archived_cadence_count, 0) = 0       THEN 'no_cadence'
      WHEN COALESCE(ca.active_cadence_count, 0) = 0
           AND COALESCE(ca.archived_cadence_count, 0) > 0       THEN 'inactive_only'
      WHEN COALESCE(ca.overdue_cadence_count, 0) > 0            THEN 'overdue'
      WHEN COALESCE(ca.due_soon_cadence_count, 0) > 0           THEN 'due_soon'
      WHEN COALESCE(ca.recurring_cadence_count, 0) = 0
           AND COALESCE(ca.ad_hoc_cadence_count, 0) > 0         THEN 'ad_hoc_only'
      ELSE                                                            'on_track'
    END
  )), '[]'::jsonb)
  INTO _result
  FROM eligible_projects ep
  LEFT JOIN ws            ON ws.id = ep.workspace_id
  LEFT JOIN cadence_agg   ca ON ca.project_id = ep.id
  LEFT JOIN next_expected ne ON ne.project_id = ep.id
  LEFT JOIN last_completed lc ON lc.project_id = ep.id
  LEFT JOIN record_agg    ra ON ra.project_id = ep.id
  LEFT JOIN decision_agg  da ON da.project_id = ep.id
  LEFT JOIN link_agg      la ON la.project_id = ep.id;

  RETURN _result;
END;
$$;


--
-- Name: reset_kpi_app_outbox(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_kpi_app_outbox(_outbox_id uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.kpi_app_submission_outbox%ROWTYPE;
  _stale_after_minutes constant integer := 15;
  _now timestamptz := now();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row
  FROM public.kpi_app_submission_outbox
  WHERE id = _outbox_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Outbox not found' USING ERRCODE = 'P0002';
  END IF;

  -- Authority gate: org admin OR workspace admin/higher for this row.
  IF NOT (
    public.is_org_admin(auth.uid(), _row.organization_id)
    OR public.is_workspace_admin_or_higher(auth.uid(), _row.workspace_id)
  ) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  -- Already superseded: idempotent success.
  IF _row.superseded_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'outbox_id', _row.id,
      'already_superseded', true,
      'superseded_at', _row.superseded_at
    );
  END IF;

  -- Never reset a successful submission.
  IF _row.status = 'submitted' OR _row.submitted_at IS NOT NULL AND _row.status = 'submitted' THEN
    RAISE EXCEPTION 'Submitted outbox cannot be reset' USING ERRCODE = '22023';
  END IF;

  -- Never reset an in-progress row unless it is stale.
  IF _row.status = 'submitting'
     AND (_row.last_attempt_at IS NULL
          OR _row.last_attempt_at > _now - make_interval(mins => _stale_after_minutes)) THEN
    RAISE EXCEPTION 'In-progress outbox is not stale; cannot reset' USING ERRCODE = '22023';
  END IF;

  -- Allow reset for failed / queued / payload_ready / retry_pending / stale submitting.
  IF _row.status NOT IN ('failed', 'queued', 'payload_ready', 'retry_pending', 'submitting') THEN
    RAISE EXCEPTION 'Outbox status % is not resettable', _row.status USING ERRCODE = '22023';
  END IF;

  UPDATE public.kpi_app_submission_outbox
     SET superseded_at = _now,
         superseded_by = auth.uid(),
         superseded_reason = NULLIF(btrim(_reason), '')
   WHERE id = _outbox_id
     AND superseded_at IS NULL;

  RETURN jsonb_build_object(
    'ok', true,
    'outbox_id', _outbox_id,
    'superseded_at', _now,
    'previous_status', _row.status
  );
END;
$$;


--
-- Name: resolve_child_project_scope(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_child_project_scope(_table text, _target_type text, _target_id uuid, _project_id_direct uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pid uuid;
BEGIN
  IF _table IN ('phases','tasks') THEN
    RETURN _project_id_direct;
  END IF;
  IF _target_type = 'project' THEN
    RETURN _target_id;
  ELSIF _target_type = 'phase' THEN
    SELECT project_id INTO v_pid FROM public.phases WHERE id = _target_id;
    RETURN v_pid;
  ELSIF _target_type = 'task' THEN
    SELECT project_id INTO v_pid FROM public.tasks WHERE id = _target_id;
    RETURN v_pid;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: resolve_effective_integration_secret_ref(uuid, uuid, public.tenant_integration_kind, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_effective_integration_secret_ref(_tenant_id uuid, _organization_id uuid, _integration_kind public.tenant_integration_kind, _secret_name text, _integration_name text DEFAULT 'default'::text, _reason text DEFAULT NULL::text, _function_name text DEFAULT NULL::text, _request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _integration public.tenant_integrations;
  _org_tenant uuid;
  _integration_disabled_override_id uuid;
  _secret_override public.organization_secret_overrides;
  _selected_ref_id uuid;
  _ref public.tenant_secret_refs;
BEGIN
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id is required';
  END IF;

  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant
      FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      INSERT INTO public.tenant_secret_access_audit(
        tenant_id, organization_id, actor_user_id, actor_type,
        action, reason, function_name, request_id, result, error_message
      ) VALUES (_tenant_id, _organization_id, auth.uid(), 'service',
                'failed', _reason, _function_name, _request_id, 'blocked',
                'organization_not_in_tenant');
      RETURN jsonb_build_object('status','blocked','reason','organization_not_in_tenant');
    END IF;
  END IF;

  SELECT * INTO _integration FROM public.tenant_integrations
   WHERE tenant_id = _tenant_id
     AND kind = _integration_kind
     AND name = _integration_name;

  IF _integration.id IS NULL OR NOT _integration.is_enabled OR _integration.status <> 'active' THEN
    INSERT INTO public.tenant_secret_access_audit(
      tenant_id, organization_id, integration_id, actor_user_id, actor_type,
      action, reason, function_name, request_id, result, error_message
    ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
              'failed', _reason, _function_name, _request_id, 'blocked',
              'integration_not_active');
    RETURN jsonb_build_object('status','blocked','reason','integration_not_active');
  END IF;

  IF _organization_id IS NOT NULL THEN
    SELECT id INTO _integration_disabled_override_id
      FROM public.organization_secret_overrides
     WHERE organization_id = _organization_id
       AND integration_id = _integration.id
       AND secret_name IS NULL
       AND is_disabled = true
     LIMIT 1;
    IF _integration_disabled_override_id IS NOT NULL THEN
      INSERT INTO public.tenant_secret_access_audit(
        tenant_id, organization_id, integration_id, actor_user_id, actor_type,
        action, reason, function_name, request_id, result, error_message
      ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
                'failed', _reason, _function_name, _request_id, 'blocked',
                'organization_integration_disabled');
      RETURN jsonb_build_object('status','blocked','reason','organization_integration_disabled');
    END IF;

    SELECT * INTO _secret_override
      FROM public.organization_secret_overrides
     WHERE organization_id = _organization_id
       AND integration_id = _integration.id
       AND secret_name = _secret_name
     LIMIT 1;
    IF _secret_override.id IS NOT NULL THEN
      IF _secret_override.is_disabled THEN
        INSERT INTO public.tenant_secret_access_audit(
          tenant_id, organization_id, integration_id, actor_user_id, actor_type,
          action, reason, function_name, request_id, result, error_message
        ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
                  'failed', _reason, _function_name, _request_id, 'blocked',
                  'organization_secret_disabled');
        RETURN jsonb_build_object('status','blocked','reason','organization_secret_disabled');
      END IF;
      IF _secret_override.secret_ref_id IS NOT NULL THEN
        SELECT * INTO _ref FROM public.tenant_secret_refs
         WHERE id = _secret_override.secret_ref_id
           AND tenant_id = _tenant_id
           AND integration_id = _integration.id
           AND organization_id = _organization_id
           AND secret_name = _secret_name
           AND secret_scope = 'organization_override'
           AND status = 'active';
        IF _ref.id IS NOT NULL THEN
          _selected_ref_id := _ref.id;
        END IF;
      END IF;
    END IF;
  END IF;

  IF _selected_ref_id IS NULL THEN
    SELECT * INTO _ref FROM public.tenant_secret_refs
     WHERE tenant_id = _tenant_id
       AND integration_id = _integration.id
       AND secret_name = _secret_name
       AND secret_scope = 'tenant'
       AND organization_id IS NULL
       AND status = 'active'
     LIMIT 1;
    IF _ref.id IS NOT NULL THEN
      _selected_ref_id := _ref.id;
    END IF;
  END IF;

  IF _selected_ref_id IS NULL THEN
    INSERT INTO public.tenant_secret_access_audit(
      tenant_id, organization_id, integration_id, actor_user_id, actor_type,
      action, reason, function_name, request_id, result, error_message
    ) VALUES (_tenant_id, _organization_id, _integration.id, auth.uid(), 'service',
              'failed', _reason, _function_name, _request_id, 'failure',
              'no_active_secret_ref');
    RETURN jsonb_build_object('status','not_found','reason','no_active_secret_ref');
  END IF;

  INSERT INTO public.tenant_secret_access_audit(
    tenant_id, organization_id, integration_id, secret_ref_id, actor_user_id, actor_type,
    action, reason, function_name, request_id, result
  ) VALUES (_tenant_id, _organization_id, _integration.id, _ref.id, auth.uid(), 'service',
            'resolved', _reason, _function_name, _request_id, 'success');

  RETURN jsonb_build_object(
    'status','ok',
    'integration_id', _integration.id,
    'integration_kind', _integration.kind,
    'integration_name', _integration.name,
    'secret_ref_id', _ref.id,
    'secret_name', _ref.secret_name,
    'secret_kind', _ref.secret_kind,
    'secret_scope', _ref.secret_scope,
    'organization_id', _ref.organization_id,
    'vault_secret_id', _ref.vault_secret_id,
    'fingerprint', _ref.secret_fingerprint,
    'config_metadata', _integration.config_metadata
  );
END $$;


--
-- Name: resolve_effective_integration_secret_value(uuid, uuid, public.tenant_integration_kind, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_effective_integration_secret_value(_tenant_id uuid, _organization_id uuid, _integration_kind public.tenant_integration_kind, _secret_name text, _integration_name text DEFAULT 'default'::text, _reason text DEFAULT NULL::text, _function_name text DEFAULT NULL::text, _request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
DECLARE
  v_meta jsonb;
  v_status text;
  v_vault_id uuid;
  v_value text;
BEGIN
  v_meta := public.resolve_effective_integration_secret_ref(
    _tenant_id, _organization_id, _integration_kind, _secret_name,
    _integration_name, _reason, _function_name, _request_id
  );

  v_status := v_meta->>'status';
  IF v_status <> 'ok' THEN
    RETURN v_meta;
  END IF;

  v_vault_id := NULLIF(v_meta->>'vault_secret_id','')::uuid;
  IF v_vault_id IS NULL THEN
    RETURN jsonb_set(v_meta, '{status}', to_jsonb('not_found'::text));
  END IF;

  SELECT ds.decrypted_secret INTO v_value
  FROM vault.decrypted_secrets ds
  WHERE ds.id = v_vault_id;

  IF v_value IS NULL THEN
    RETURN jsonb_set(v_meta, '{status}', to_jsonb('not_found'::text));
  END IF;

  RETURN jsonb_build_object(
    'status', 'ok',
    'integration_id', v_meta->'integration_id',
    'integration_kind', v_meta->'integration_kind',
    'integration_name', v_meta->'integration_name',
    'secret_name', v_meta->'secret_name',
    'secret_kind', v_meta->'secret_kind',
    'secret_scope', v_meta->'secret_scope',
    'organization_id', v_meta->'organization_id',
    'config_metadata', COALESCE(v_meta->'config_metadata', '{}'::jsonb),
    'value', v_value
  );
END;
$$;


--
-- Name: resolve_organization_encryption_key_metadata(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_organization_encryption_key_metadata(_tenant_id uuid, _organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_tenant uuid; _row public.organization_encryption_keys%ROWTYPE; _tek public.tenant_encryption_keys%ROWTYPE;
BEGIN
  IF _tenant_id IS NULL OR _organization_id IS NULL THEN
    RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: tenant_id and organization_id required';
  END IF;
  SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _organization_id;
  IF _org_tenant IS NULL THEN
    RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: organization not found';
  END IF;
  IF _org_tenant <> _tenant_id THEN
    RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: organization does not belong to tenant';
  END IF;
  SELECT * INTO _row FROM public.organization_encryption_keys WHERE organization_id = _organization_id;
  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: organization encryption metadata missing';
  END IF;
  IF _row.key_scope <> 'organization_data_key' THEN
    RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: unexpected key_scope %', _row.key_scope;
  END IF;
  IF _row.key_status NOT IN ('active_legacy_org_key') THEN
    RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: key_status % not usable', _row.key_status;
  END IF;
  IF _row.tenant_encryption_key_id IS NOT NULL THEN
    SELECT * INTO _tek FROM public.tenant_encryption_keys WHERE id = _row.tenant_encryption_key_id;
    IF _tek.id IS NULL OR _tek.tenant_id <> _tenant_id THEN
      RAISE EXCEPTION 'resolve_organization_encryption_key_metadata: tenant metadata inconsistent';
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'tenant_id', _row.tenant_id,
    'organization_id', _row.organization_id,
    'encryption_model', 'legacy_org_key',
    'key_scope', _row.key_scope,
    'legacy_key_name', _row.legacy_key_name,
    'key_status', _row.key_status,
    'key_version', _row.key_version
  );
END;
$$;


--
-- Name: resolve_project_id(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_project_id(_target_type text, _target_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE _target_type
    WHEN 'project' THEN _target_id
    WHEN 'phase'   THEN (SELECT project_id FROM public.phases WHERE id = _target_id)
    WHEN 'task'    THEN (SELECT project_id FROM public.tasks  WHERE id = _target_id)
    WHEN 'risk' THEN (
      SELECT CASE r.target_type
        WHEN 'project' THEN r.target_id
        WHEN 'phase'   THEN (SELECT project_id FROM public.phases WHERE id = r.target_id)
        WHEN 'task'    THEN (SELECT project_id FROM public.tasks  WHERE id = r.target_id)
      END FROM public.risks r WHERE r.id = _target_id
    )
    WHEN 'blocker' THEN (
      SELECT CASE b.target_type
        WHEN 'project' THEN b.target_id
        WHEN 'phase'   THEN (SELECT project_id FROM public.phases WHERE id = b.target_id)
        WHEN 'task'    THEN (SELECT project_id FROM public.tasks  WHERE id = b.target_id)
      END FROM public.blockers b WHERE b.id = _target_id
    )
    WHEN 'kpi_definition' THEN (
      SELECT CASE k.target_type
        WHEN 'project' THEN k.target_id
        WHEN 'phase'   THEN (SELECT project_id FROM public.phases WHERE id = k.target_id)
        WHEN 'task'    THEN (SELECT project_id FROM public.tasks  WHERE id = k.target_id)
      END FROM public.kpi_definitions k WHERE k.id = _target_id
    )
    WHEN 'governance_cadence' THEN (SELECT project_id FROM public.governance_cadences WHERE id = _target_id)
    WHEN 'governance_record'  THEN (SELECT project_id FROM public.governance_records  WHERE id = _target_id)
    ELSE NULL
  END
$$;


