--
-- Name: resolve_route_context_boundary(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_route_context_boundary(_workspace_id uuid DEFAULT NULL::uuid, _project_id uuid DEFAULT NULL::uuid, _program_id uuid DEFAULT NULL::uuid, _phase_id uuid DEFAULT NULL::uuid, _task_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _resolved_ws uuid;
  _resolved_org uuid;
  _object_type text := 'workspace';
  _object_id uuid;
  _org RECORD;
  _tenant RECORD;
  _ws RECORD;
  _task RECORD;
  _phase RECORD;
  _project RECORD;
  _program RECORD;
  _has_access boolean := false;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF _task_id IS NOT NULL THEN
    _object_type := 'task'; _object_id := _task_id;
    SELECT id, workspace_id, project_id, phase_id INTO _task FROM public.tasks WHERE id = _task_id;
    IF _task.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','task','object_id',_task_id,'not_found', true);
    END IF;
    _resolved_ws := _task.workspace_id;
    IF _project_id IS NOT NULL AND _task.project_id IS DISTINCT FROM _project_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','task','object_id',_task_id,'inconsistent', true, 'reason','Task does not belong to the provided project');
    END IF;
    IF _phase_id IS NOT NULL AND _task.phase_id IS DISTINCT FROM _phase_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','task','object_id',_task_id,'inconsistent', true, 'reason','Task does not belong to the provided phase');
    END IF;
  ELSIF _phase_id IS NOT NULL THEN
    _object_type := 'phase'; _object_id := _phase_id;
    SELECT id, workspace_id, project_id INTO _phase FROM public.phases WHERE id = _phase_id;
    IF _phase.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','phase','object_id',_phase_id,'not_found', true);
    END IF;
    _resolved_ws := _phase.workspace_id;
    IF _project_id IS NOT NULL AND _phase.project_id IS DISTINCT FROM _project_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','phase','object_id',_phase_id,'inconsistent', true, 'reason','Phase does not belong to the provided project');
    END IF;
  ELSIF _project_id IS NOT NULL THEN
    _object_type := 'project'; _object_id := _project_id;
    SELECT id, workspace_id, program_id INTO _project FROM public.projects WHERE id = _project_id;
    IF _project.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','project','object_id',_project_id,'not_found', true);
    END IF;
    _resolved_ws := _project.workspace_id;
    IF _program_id IS NOT NULL AND _project.program_id IS DISTINCT FROM _program_id THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','project','object_id',_project_id,'inconsistent', true, 'reason','Project does not belong to the provided program');
    END IF;
  ELSIF _program_id IS NOT NULL THEN
    _object_type := 'program'; _object_id := _program_id;
    SELECT id, workspace_id INTO _program FROM public.programs WHERE id = _program_id;
    IF _program.id IS NULL THEN
      RETURN jsonb_build_object('has_access', false, 'object_type','program','object_id',_program_id,'not_found', true);
    END IF;
    _resolved_ws := _program.workspace_id;
  ELSIF _workspace_id IS NOT NULL THEN
    _object_type := 'workspace'; _object_id := _workspace_id;
    _resolved_ws := _workspace_id;
  ELSE
    RAISE EXCEPTION 'At least one id must be provided';
  END IF;

  -- Workspace consistency: any explicit _workspace_id must match resolution
  IF _workspace_id IS NOT NULL AND _resolved_ws IS DISTINCT FROM _workspace_id THEN
    RETURN jsonb_build_object('has_access', false, 'object_type', _object_type, 'object_id', _object_id, 'inconsistent', true, 'reason','Object does not belong to the provided workspace');
  END IF;

  SELECT id, name, organization_id INTO _ws FROM public.workspaces WHERE id = _resolved_ws;
  IF _ws.id IS NULL THEN
    RETURN jsonb_build_object('has_access', false, 'object_type', _object_type, 'object_id', _object_id, 'not_found', true);
  END IF;
  _resolved_org := _ws.organization_id;

  SELECT id, name, tenant_id, environment_role, organization_kind, slug INTO _org FROM public.organizations WHERE id = _resolved_org;
  SELECT id, name, slug INTO _tenant FROM public.tenants WHERE id = _org.tenant_id;

  -- Operational route access: workspace member OR organization admin.
  -- Tenant-admin / platform-super-admin alone do NOT pass here.
  _has_access :=
       public.is_workspace_member(_uid, _resolved_ws)
    OR public.is_organization_admin(_resolved_org, _uid);

  IF NOT _has_access THEN
    RETURN jsonb_build_object(
      'has_access', false,
      'access_denied', true,
      'object_type', _object_type,
      'object_id', _object_id
    );
  END IF;

  RETURN jsonb_build_object(
    'has_access', true,
    'object_type', _object_type,
    'object_id', _object_id,
    'tenant_id', _tenant.id,
    'tenant_name', _tenant.name,
    'tenant_slug', _tenant.slug,
    'organization_id', _org.id,
    'organization_name', _org.name,
    'organization_slug', _org.slug,
    'environment_role', _org.environment_role,
    'organization_kind', _org.organization_kind,
    'workspace_id', _ws.id,
    'workspace_name', _ws.name
  );
END $$;


--
-- Name: resolve_sharepoint_project_binding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_sharepoint_project_binding(_project_id uuid) RETURNS TABLE(project_binding_id uuid, project_id uuid, workspace_id uuid, organization_id uuid, binding_mode public.sharepoint_project_binding_mode, binding_status public.sharepoint_project_binding_status, is_restricted boolean, folder_web_url text, folder_relative_path text, folder_item_id text, effective_site_web_url text, effective_site_id text, effective_library_web_url text, effective_library_id_or_drive_id text, workspace_binding_id uuid, workspace_binding_status public.sharepoint_workspace_binding_status, last_validated_at timestamp with time zone, last_validation_code text, last_validation_note text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ws uuid; v_org uuid;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'unauthorized'; END IF;
  SELECT p.workspace_id, p.organization_id INTO v_ws, v_org
  FROM public.projects p WHERE p.id = _project_id;
  IF v_ws IS NULL THEN RAISE EXCEPTION 'project_not_found'; END IF;
  IF NOT public.has_project_access(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'unauthorized'; END IF;
  RETURN QUERY
  SELECT pb.id, pb.project_id, pb.workspace_id, pb.organization_id,
    pb.binding_mode, pb.binding_status, pb.is_restricted,
    pb.folder_web_url, pb.folder_relative_path, pb.folder_item_id,
    COALESCE(pb.resolved_site_web_url, wb.site_web_url),
    COALESCE(pb.resolved_site_id, wb.site_id),
    COALESCE(pb.resolved_library_web_url, wb.library_web_url),
    COALESCE(pb.resolved_library_id_or_drive_id, wb.library_id_or_drive_id),
    wb.id, wb.binding_status,
    pb.last_validated_at, pb.last_validation_code, pb.last_validation_note
  FROM public.sharepoint_project_bindings pb
  LEFT JOIN public.sharepoint_workspace_bindings wb
    ON wb.id = pb.workspace_sharepoint_binding_id
  WHERE pb.project_id = _project_id AND pb.binding_status <> 'disabled' LIMIT 1;
END; $$;


--
-- Name: resolve_tenant_encryption_key_version_metadata(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_tenant_encryption_key_version_metadata(_tenant_id uuid, _key_version integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _r public.tenant_encryption_keys%ROWTYPE;
BEGIN
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id_required'; END IF;
  IF _key_version IS NULL OR _key_version <= 0 THEN RAISE EXCEPTION 'invalid_key_version'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.tenants WHERE id = _tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_found';
  END IF;

  SELECT * INTO _r
    FROM public.tenant_encryption_keys
    WHERE tenant_id = _tenant_id
      AND key_scope = 'tenant_encryption_key'
      AND key_version = _key_version
    LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'tenant_id', _tenant_id,
      'key_scope', 'tenant_encryption_key',
      'key_version', _key_version,
      'key_status', NULL,
      'key_provider', NULL,
      'payload_format_ready', false,
      'fresh_tenant_key_created', false,
      'legacy_material_imported', false,
      'updated_at', NULL,
      'last_rotated_at', NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'tenant_id', _r.tenant_id,
    'key_scope', _r.key_scope,
    'key_version', _r.key_version,
    'key_status', _r.key_status,
    'key_provider', _r.key_provider,
    'payload_format_ready', COALESCE((_r.metadata->>'payload_format_ready')::boolean, false),
    'fresh_tenant_key_created', COALESCE((_r.metadata->>'fresh_tenant_key_created')::boolean, false),
    'legacy_material_imported', COALESCE((_r.metadata->>'legacy_material_imported')::boolean, false),
    'updated_at', _r.updated_at,
    'last_rotated_at', _r.last_rotated_at
  );
END;
$$;


--
-- Name: resolve_tenant_encryption_v1_metadata(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_tenant_encryption_v1_metadata(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_encryption_keys%ROWTYPE;
BEGIN
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id_required';
  END IF;

  SELECT * INTO _row
    FROM public.tenant_encryption_keys
    WHERE tenant_id = _tenant_id
      AND key_scope = 'tenant_encryption_key'
      AND key_version = 1
    LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'tenant_id', _tenant_id,
      'key_scope', 'tenant_encryption_key',
      'key_version', 1,
      'key_status', NULL,
      'key_provider', NULL,
      'legacy_material_imported', false,
      'legacy_material_equivalence_verified', false,
      'runtime_caller_migration_active', false,
      'business_record_reencryption_performed', false,
      'payload_format_ready', false,
      'legacy_org_keys_retained', true,
      'updated_at', NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'tenant_id', _row.tenant_id,
    'key_scope', _row.key_scope,
    'key_version', _row.key_version,
    'key_status', _row.key_status,
    'key_provider', _row.key_provider,
    'legacy_material_imported', COALESCE((_row.metadata ->> 'legacy_material_imported')::boolean, false),
    'legacy_material_equivalence_verified', COALESCE((_row.metadata ->> 'legacy_material_equivalence_verified')::boolean, false),
    'runtime_caller_migration_active', COALESCE((_row.metadata ->> 'runtime_caller_migration_active')::boolean, false),
    'business_record_reencryption_performed', COALESCE((_row.metadata ->> 'business_record_reencryption_performed')::boolean, false),
    'payload_format_ready', COALESCE((_row.metadata ->> 'payload_format_ready')::boolean, false),
    'legacy_org_keys_retained', COALESCE((_row.metadata ->> 'legacy_org_keys_retained')::boolean, true),
    'updated_at', _row.updated_at
  );
END;
$$;


--
-- Name: restore_governance_cadence(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_governance_cadence(_cadence_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row governance_cadences%ROWTYPE; v_client_id text; v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM governance_cadences WHERE id = _cadence_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cadence not found' USING ERRCODE='P0002'; END IF;
  PERFORM _gov_assert_project_write(_row.project_id);
  IF _row.archived_at IS NOT NULL THEN
    UPDATE governance_cadences SET archived_at = NULL, archived_by = NULL, updated_at = now()
    WHERE id = _cadence_id;
    PERFORM log_activity_event(_row.organization_id, v_caller,
      'governance_cadence_restored', 'governance_cadence', _cadence_id,
      jsonb_build_object('project_id', _row.project_id), _row.workspace_id);
  END IF;
END; $$;


