--
-- Name: save_ai_decision_brief_version(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_ai_decision_brief_version(_record_id uuid, _ai_run_id uuid, _edited_brief_text text, _make_current boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _row public.governance_records%ROWTYPE;
  _run public.decision_case_ai_runs%ROWTYPE;
  _next int;
  _id uuid;
  _edited text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
  IF _run.governance_record_id <> _record_id THEN
    RAISE EXCEPTION 'AI run does not belong to this record' USING ERRCODE='22023';
  END IF;
  IF _run.status NOT IN ('completed') THEN
    RAISE EXCEPTION 'AI run is not in a saveable state (status=%)', _run.status USING ERRCODE='22023';
  END IF;
  IF _run.brief_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'AI run is already linked to a brief version' USING ERRCODE='22023';
  END IF;

  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  IF _edited IS NULL THEN
    RAISE EXCEPTION 'edited_brief_text is required' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, false) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    edited_brief_text,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, 'btpm_generated', COALESCE(_make_current, false),
    _edited,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  UPDATE public.decision_case_ai_runs
    SET status = 'saved',
        saved_at = now(),
        brief_version_id = _id,
        updated_at = now()
    WHERE id = _ai_run_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', 'btpm_generated',
                       'is_current', COALESCE(_make_current, false),
                       'ai_run_id', _ai_run_id),
    _row.workspace_id);

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'decision_case_ai_run_saved', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'ai_run_id', _ai_run_id,
                       'brief_version_id', _id),
    _row.workspace_id);

  RETURN jsonb_build_object('brief_version_id', _id, 'version_number', _next, 'ai_run_id', _ai_run_id);
END; $$;


--
-- Name: save_ai_decision_brief_version_v2(uuid, uuid, text, boolean, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_ai_decision_brief_version_v2(_record_id uuid, _ai_run_id uuid, _edited_brief_text text, _make_current boolean DEFAULT false, _recommendation_text text DEFAULT NULL::text, _requested_decision_text text DEFAULT NULL::text, _guardrails_text text DEFAULT NULL::text, _residual_risks_text text DEFAULT NULL::text, _open_questions_text text DEFAULT NULL::text, _confidence_level text DEFAULT NULL::text, _decision_readiness text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _row public.governance_records%ROWTYPE;
  _run public.decision_case_ai_runs%ROWTYPE;
  _next int;
  _id uuid;
  _edited text;
  _conf text;
  _ready text;
BEGIN
  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;
  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  PERFORM public._gov_assert_project_write(_row.project_id);

  SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
  IF _run.governance_record_id <> _record_id THEN
    RAISE EXCEPTION 'AI run does not belong to this record' USING ERRCODE='22023';
  END IF;
  IF _run.status NOT IN ('completed') THEN
    RAISE EXCEPTION 'AI run is not in a saveable state (status=%)', _run.status USING ERRCODE='22023';
  END IF;
  IF _run.brief_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'AI run is already linked to a brief version' USING ERRCODE='22023';
  END IF;

  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  IF _edited IS NULL THEN
    RAISE EXCEPTION 'edited_brief_text is required' USING ERRCODE='22023';
  END IF;

  _conf := NULLIF(trim(COALESCE(_confidence_level, '')), '');
  IF _conf IS NOT NULL AND _conf NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid confidence_level: %', _conf USING ERRCODE='22023';
  END IF;
  _ready := NULLIF(trim(COALESCE(_decision_readiness, '')), '');
  IF _ready IS NOT NULL AND _ready NOT IN ('ready_for_decision','needs_clarification','not_ready') THEN
    RAISE EXCEPTION 'Invalid decision_readiness: %', _ready USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, false) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = auth.uid(), updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    edited_brief_text,
    recommendation_text, requested_decision_text,
    guardrails_text, residual_risks_text,
    open_questions_text, confidence_level, decision_readiness,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, 'btpm_generated', COALESCE(_make_current, false),
    _edited,
    NULLIF(trim(COALESCE(_recommendation_text,'')),''),
    NULLIF(trim(COALESCE(_requested_decision_text,'')),''),
    NULLIF(trim(COALESCE(_guardrails_text,'')),''),
    NULLIF(trim(COALESCE(_residual_risks_text,'')),''),
    NULLIF(trim(COALESCE(_open_questions_text,'')),''),
    _conf,
    _ready,
    auth.uid(), auth.uid()
  ) RETURNING id INTO _id;

  UPDATE public.decision_case_ai_runs
    SET status = 'saved',
        saved_at = now(),
        brief_version_id = _id,
        updated_at = now()
    WHERE id = _ai_run_id;

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', 'btpm_generated',
                       'is_current', COALESCE(_make_current, false),
                       'ai_run_id', _ai_run_id,
                       'has_structured_fields', true),
    _row.workspace_id);

  PERFORM public.log_activity_event(_row.organization_id, auth.uid(),
    'decision_case_ai_run_saved', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'ai_run_id', _ai_run_id,
                       'brief_version_id', _id),
    _row.workspace_id);

  RETURN jsonb_build_object('brief_version_id', _id, 'version_number', _next, 'ai_run_id', _ai_run_id);
END; $$;


--
-- Name: save_decision_brief_version_v3(uuid, text, text, boolean, uuid, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_decision_brief_version_v3(_record_id uuid, _source_type text, _edited_brief_text text DEFAULT NULL::text, _make_current boolean DEFAULT true, _ai_run_id uuid DEFAULT NULL::uuid, _executive_intro_text text DEFAULT NULL::text, _options_summary text DEFAULT NULL::text, _requested_decision_text text DEFAULT NULL::text, _recommendation_text text DEFAULT NULL::text, _guardrails_text text DEFAULT NULL::text, _residual_risks_text text DEFAULT NULL::text, _open_questions_text text DEFAULT NULL::text, _confidence_level text DEFAULT NULL::text, _decision_readiness text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _row public.governance_records%ROWTYPE;
  _run public.decision_case_ai_runs%ROWTYPE;
  _next int;
  _id uuid;
  _edited text;
  _intro text; _opts text; _req text; _rec text; _grd text; _rsk text; _oq text;
  _conf text; _ready text;
  _src text;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;

  _src := NULLIF(trim(COALESCE(_source_type, '')), '');
  IF _src IS NULL OR _src NOT IN ('btpm_generated','manual_edit','copilot_paste') THEN
    RAISE EXCEPTION 'Invalid source_type %', _source_type USING ERRCODE='22023';
  END IF;

  IF _ai_run_id IS NOT NULL THEN
    SELECT * INTO _run FROM public.decision_case_ai_runs WHERE id = _ai_run_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'AI run not found' USING ERRCODE='P0002'; END IF;
    IF _run.governance_record_id <> _record_id THEN
      RAISE EXCEPTION 'AI run does not belong to this record' USING ERRCODE='22023';
    END IF;
    IF _run.status NOT IN ('completed','saved') THEN
      RAISE EXCEPTION 'AI run is not in a saveable state (status=%)', _run.status USING ERRCODE='22023';
    END IF;
  END IF;

  _edited := NULLIF(trim(COALESCE(_edited_brief_text, '')), '');
  _intro  := NULLIF(trim(COALESCE(_executive_intro_text, '')), '');
  _opts   := NULLIF(trim(COALESCE(_options_summary, '')), '');
  _req    := NULLIF(trim(COALESCE(_requested_decision_text, '')), '');
  _rec    := NULLIF(trim(COALESCE(_recommendation_text, '')), '');
  _grd    := NULLIF(trim(COALESCE(_guardrails_text, '')), '');
  _rsk    := NULLIF(trim(COALESCE(_residual_risks_text, '')), '');
  _oq     := NULLIF(trim(COALESCE(_open_questions_text, '')), '');

  IF _edited IS NULL AND _intro IS NULL AND _opts IS NULL AND _req IS NULL
     AND _rec IS NULL AND _grd IS NULL AND _rsk IS NULL AND _oq IS NULL THEN
    RAISE EXCEPTION 'At least one brief field is required' USING ERRCODE='22023';
  END IF;

  _conf := NULLIF(trim(COALESCE(_confidence_level, '')), '');
  IF _conf IS NOT NULL AND _conf NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid confidence_level: %', _conf USING ERRCODE='22023';
  END IF;
  _ready := NULLIF(trim(COALESCE(_decision_readiness, '')), '');
  IF _ready IS NOT NULL AND _ready NOT IN ('ready_for_decision','needs_clarification','not_ready') THEN
    RAISE EXCEPTION 'Invalid decision_readiness: %', _ready USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1 INTO _next
    FROM public.governance_record_brief_versions
    WHERE governance_record_id = _record_id;

  IF COALESCE(_make_current, true) THEN
    UPDATE public.governance_record_brief_versions
      SET is_current = false, updated_by = v_caller, updated_at = now()
      WHERE governance_record_id = _record_id AND is_current = true;
  END IF;

  INSERT INTO public.governance_record_brief_versions (
    organization_id, workspace_id, project_id, governance_record_id,
    version_number, source_type, is_current,
    edited_brief_text,
    executive_intro_text, options_summary,
    requested_decision_text, recommendation_text,
    guardrails_text, residual_risks_text,
    open_questions_text, confidence_level, decision_readiness,
    created_by, updated_by
  ) VALUES (
    _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
    _next, _src, COALESCE(_make_current, true),
    _edited,
    _intro, _opts,
    _req, _rec,
    _grd, _rsk,
    _oq, _conf, _ready,
    v_caller, v_caller
  ) RETURNING id INTO _id;

  IF _ai_run_id IS NOT NULL AND _run.status = 'completed' THEN
    UPDATE public.decision_case_ai_runs
      SET status = 'saved',
          saved_at = now(),
          brief_version_id = _id,
          updated_at = now()
      WHERE id = _ai_run_id AND brief_version_id IS NULL;
  END IF;

  PERFORM public.log_activity_event(_row.organization_id, v_caller,
    'governance_record_brief_version_created', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _id,
                       'version_number', _next,
                       'source_type', _src,
                       'is_current', COALESCE(_make_current, true),
                       'ai_run_id', _ai_run_id,
                       'has_structured_fields', true,
                       'rpc', 'save_decision_brief_version_v3'),
    _row.workspace_id);

  RETURN jsonb_build_object(
    'brief_version_id', _id,
    'version_number', _next,
    'ai_run_id', _ai_run_id
  );
END; $$;


--
-- Name: save_project_people_preset_from_project(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_project_people_preset_from_project(_project_id uuid, _name text, _description text DEFAULT NULL::text, _correlation_id text DEFAULT NULL::text, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor          uuid := auth.uid();
  v_project        record;
  v_name_norm      text;
  v_desc_norm      text;
  v_dupe_id        uuid;
  v_prior_preset   uuid;
  v_prior_meta     jsonb;
  v_preset_row     public.project_people_presets;
  v_new_preset_id  uuid;
  v_team_count     integer := 0;
  v_int_count      integer := 0;
  v_ext_count      integer := 0;
  v_member_count   integer := 0;
  r                record;
BEGIN
  ----------------------------------------------------------------------------
  -- 1. Authentication
  ----------------------------------------------------------------------------
  IF v_actor IS NULL OR NOT public.is_active_user(v_actor) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status,
      'save_project_people_preset_from_project',
      'project_people_preset', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  ----------------------------------------------------------------------------
  -- 2. Resolve Project scope server-side (never trust caller)
  ----------------------------------------------------------------------------
  SELECT id, workspace_id, organization_id
    INTO v_project
    FROM public.projects
   WHERE id = _project_id
   FOR SHARE;

  IF v_project.id IS NULL THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status,
      'save_project_people_preset_from_project',
      'project_people_preset', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  ----------------------------------------------------------------------------
  -- 3. Authority
  ----------------------------------------------------------------------------
  IF NOT public.has_project_pm_authority(v_actor, _project_id)
     OR NOT public.can_write_demo(v_actor, v_project.workspace_id) THEN
    RETURN public.pmg_build_result(
      'not_authorized'::public.pmg_command_status,
      'save_project_people_preset_from_project',
      'project_people_preset', NULL, _project_id,
      '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  ----------------------------------------------------------------------------
  -- 4. WPP.7 HARDENING: transaction-scoped advisory lock BEFORE replay lookup
  --    Keyed on (command, actor, idempotency_key). Guarantees at most one
  --    concurrent execution per (actor,key) tuple across all sessions, so
  --    the pmg_command_audit replay probe below cannot race a sibling call
  --    that has not yet committed its audit row.
  ----------------------------------------------------------------------------
  IF _idempotency_key IS NOT NULL AND length(btrim(_idempotency_key)) > 0 THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'save_project_people_preset_from_project|' || v_actor::text || '|' || _idempotency_key,
        0
      )
    );

    -- 4b. Idempotency replay (safe under the advisory lock).
    SELECT (metadata->>'preset_id')::uuid, metadata
      INTO v_prior_preset, v_prior_meta
      FROM public.pmg_command_audit
     WHERE command = 'save_project_people_preset_from_project'
       AND actor_id = v_actor
       AND idempotency_key = _idempotency_key
       AND status = 'applied'::public.pmg_command_status
     ORDER BY created_at DESC
     LIMIT 1;

    IF v_prior_preset IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.project_people_presets WHERE id = v_prior_preset) THEN
      RETURN public.pmg_build_result(
        'no_change'::public.pmg_command_status,
        'save_project_people_preset_from_project',
        'project_people_preset', v_prior_preset, _project_id,
        jsonb_build_object(
          'id', v_prior_preset,
          'workspace_id', v_project.workspace_id,
          'reason', 'idempotent_replay',
          'team_count',        COALESCE((v_prior_meta->>'team_count')::int, 0),
          'stakeholder_count', COALESCE((v_prior_meta->>'stakeholder_count')::int, 0)
        ),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
    END IF;
  END IF;

  ----------------------------------------------------------------------------
  -- 5. Validate name
  ----------------------------------------------------------------------------
  v_name_norm := NULLIF(btrim(COALESCE(_name, '')), '');
  v_desc_norm := NULLIF(btrim(COALESCE(_description, '')), '');
  IF v_name_norm IS NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status,
      'save_project_people_preset_from_project',
      'project_people_preset', NULL, _project_id,
      jsonb_build_object('reason','name_required'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  ----------------------------------------------------------------------------
  -- 6. Duplicate active preset name (decrypt+compare)
  ----------------------------------------------------------------------------
  FOR r IN
    SELECT id, name
      FROM public.project_people_presets
     WHERE workspace_id = v_project.workspace_id
       AND archived_at IS NULL
     FOR UPDATE
  LOOP
    IF lower(btrim(public.btpm_decrypt(r.name, v_project.organization_id))) = lower(v_name_norm) THEN
      v_dupe_id := r.id;
      EXIT;
    END IF;
  END LOOP;

  IF v_dupe_id IS NOT NULL THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status,
      'save_project_people_preset_from_project',
      'project_people_preset', NULL, _project_id,
      jsonb_build_object('reason','duplicate_name'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  ----------------------------------------------------------------------------
  -- 7. Count active source rows
  ----------------------------------------------------------------------------
  SELECT COUNT(*)::int INTO v_team_count
    FROM public.project_team_members WHERE project_id = _project_id;

  SELECT
    COUNT(*) FILTER (WHERE stakeholder_type = 'workspace_member')::int,
    COUNT(*) FILTER (WHERE stakeholder_type = 'external')::int
    INTO v_int_count, v_ext_count
    FROM public.project_stakeholders
   WHERE project_id = _project_id AND removed_at IS NULL;

  IF v_team_count = 0 AND v_int_count = 0 AND v_ext_count = 0 THEN
    RETURN public.pmg_build_result(
      'invalid'::public.pmg_command_status,
      'save_project_people_preset_from_project',
      'project_people_preset', NULL, _project_id,
      jsonb_build_object('reason','empty_source'),
      '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END IF;

  ----------------------------------------------------------------------------
  -- 8. Transactional creation.
  --    Note: project_stakeholders.external_name and role_label are plaintext
  --    columns (verified in production: no encryption trigger on
  --    project_stakeholders and rows contain human-readable values). Only
  --    project_team_members.role_label is protected under organization_id
  --    and is decrypted below.
  ----------------------------------------------------------------------------
  BEGIN
    INSERT INTO public.project_people_presets (
      organization_id, workspace_id, scope_type, name, description, created_by
    ) VALUES (
      v_project.organization_id, v_project.workspace_id, 'workspace',
      v_name_norm, v_desc_norm, v_actor
    )
    RETURNING id INTO v_new_preset_id;

    INSERT INTO public.project_people_preset_members (
      preset_id, member_kind, stakeholder_type,
      user_id, external_name, canonical_role_key, role_label
    )
    SELECT
      v_new_preset_id, 'team_member', NULL,
      ptm.user_id, NULL,
      NULLIF(btrim(COALESCE(ptm.canonical_role_key, '')), ''),
      NULLIF(btrim(COALESCE(public.btpm_decrypt(ptm.role_label, ptm.organization_id), '')), '')
      FROM public.project_team_members ptm
     WHERE ptm.project_id = _project_id;

    INSERT INTO public.project_people_preset_members (
      preset_id, member_kind, stakeholder_type,
      user_id, external_name, canonical_role_key, role_label
    )
    SELECT
      v_new_preset_id, 'stakeholder', 'workspace_member',
      s.user_id, NULL, NULL,
      NULLIF(btrim(COALESCE(s.role_label, '')), '')
      FROM public.project_stakeholders s
     WHERE s.project_id = _project_id
       AND s.removed_at IS NULL
       AND s.stakeholder_type = 'workspace_member'
       AND s.user_id IS NOT NULL;

    INSERT INTO public.project_people_preset_members (
      preset_id, member_kind, stakeholder_type,
      user_id, external_name, canonical_role_key, role_label
    )
    SELECT
      v_new_preset_id, 'stakeholder', 'external',
      NULL,
      btrim(s.external_name),
      NULL,
      NULLIF(btrim(COALESCE(s.role_label, '')), '')
      FROM public.project_stakeholders s
     WHERE s.project_id = _project_id
       AND s.removed_at IS NULL
       AND s.stakeholder_type = 'external'
       AND s.external_name IS NOT NULL
       AND length(btrim(s.external_name)) > 0;

    SELECT COUNT(*)::int INTO v_member_count
      FROM public.project_people_preset_members
     WHERE preset_id = v_new_preset_id;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN public.pmg_build_result(
        'invalid'::public.pmg_command_status,
        'save_project_people_preset_from_project',
        'project_people_preset', NULL, _project_id,
        jsonb_build_object('reason','source_invalid','detail', SQLERRM),
        '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
  END;

  ----------------------------------------------------------------------------
  -- 9. Audit
  ----------------------------------------------------------------------------
  SELECT * INTO v_preset_row FROM public.project_people_presets WHERE id = v_new_preset_id;

  PERFORM public._ppp_record_audit(
    'applied'::public.pmg_command_status,
    'save_project_people_preset_from_project',
    v_preset_row,
    'project_people_preset', v_new_preset_id,
    _correlation_id, _idempotency_key,
    jsonb_build_object(
      'source_project_id',           _project_id,
      'source_workspace_id',         v_project.workspace_id,
      'team_count',                  v_team_count,
      'stakeholder_internal_count',  v_int_count,
      'stakeholder_external_count',  v_ext_count,
      'stakeholder_count',           v_int_count + v_ext_count,
      'member_count',                v_member_count
    )
  );

  RETURN public.pmg_build_result(
    'applied'::public.pmg_command_status,
    'save_project_people_preset_from_project',
    'project_people_preset', v_new_preset_id, _project_id,
    jsonb_build_object(
      'id',                 v_new_preset_id,
      'workspace_id',       v_project.workspace_id,
      'team_count',         v_team_count,
      'stakeholder_count',  v_int_count + v_ext_count,
      'member_count',       v_member_count
    ),
    '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL);
END; $$;


--
-- Name: save_project_template_from_project(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_project_template_from_project(_project_id uuid, _template_name text, _template_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE _caller uuid := auth.uid(); _org uuid; _ws uuid; _blueprint jsonb; _new_id uuid; _agile jsonb; _counts jsonb; v_client_id text;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF _caller IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF NOT public.is_active_user(_caller) THEN
    RAISE EXCEPTION 'Account is deactivated' USING ERRCODE='42501'; END IF;
  IF _template_name IS NULL OR length(trim(_template_name)) = 0 THEN
    RAISE EXCEPTION 'template_name required' USING ERRCODE='22023'; END IF;
  SELECT p.organization_id, p.workspace_id INTO _org, _ws FROM public.projects p WHERE p.id = _project_id;
  IF _org IS NULL THEN RAISE EXCEPTION 'project not found' USING ERRCODE='P0002'; END IF;
  IF public.is_user_org_member(_caller, _org) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  IF NOT public.has_project_pm_authority(_caller, _project_id) THEN
    RAISE EXCEPTION 'access denied: PM authority required' USING ERRCODE='42501'; END IF;
  IF NOT public.can_write_demo(_caller, _ws) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  _blueprint := public.preview_project_clone_blueprint(_project_id);
  IF _blueprint IS NULL OR _blueprint->>'version' <> 'clone_blueprint_v1'
     OR _blueprint->>'blueprint_kind' <> 'project' THEN
    RAISE EXCEPTION 'invalid blueprint payload returned by preview_project_clone_blueprint' USING ERRCODE='22023'; END IF;
  INSERT INTO public.project_templates (organization_id, workspace_id, source_project_id,
    name, description, blueprint_payload, blueprint_version, created_by, updated_by)
  VALUES (_org, _ws, _project_id, _template_name, _template_description, _blueprint::text,
    'clone_blueprint_v1', _caller, _caller) RETURNING id INTO _new_id;
  BEGIN
    PERFORM public.log_activity_event(_caller, 'project_template_created',
      jsonb_build_object('source_project_id', _project_id, 'workspace_id', _ws,
        'blueprint_version', 'clone_blueprint_v1'),
      _org, _new_id, 'project_template', _ws);
  EXCEPTION WHEN OTHERS THEN NULL; END;
  _agile := COALESCE(_blueprint->'agile', '{}'::jsonb);
  _counts := jsonb_build_object(
    'phases', jsonb_array_length(COALESCE(_blueprint->'phases', '[]'::jsonb)),
    'tasks', jsonb_array_length(COALESCE(_blueprint->'tasks', '[]'::jsonb)),
    'dependencies', jsonb_array_length(COALESCE(_blueprint->'dependencies', '[]'::jsonb)),
    'kpi_definitions', jsonb_array_length(COALESCE(_blueprint->'kpi_definitions', '[]'::jsonb)),
    'workflow_states', jsonb_array_length(COALESCE(_agile->'workflow_states', '[]'::jsonb)),
    'sprints', jsonb_array_length(COALESCE(_agile->'sprints', '[]'::jsonb)),
    'backlog_items', jsonb_array_length(COALESCE(_agile->'backlog_items', '[]'::jsonb)));
  RETURN jsonb_build_object('template_id', _new_id, 'organization_id', _org,
    'workspace_id', _ws, 'source_project_id', _project_id,
    'blueprint_version', 'clone_blueprint_v1', 'template_name', _template_name,
    'schedule_mode', _blueprint->>'schedule_mode', 'copied_counts', _counts);
END; $$;


--
-- Name: search_workspace_project_deep_matches(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_workspace_project_deep_matches(_workspace_id uuid, _query text, _include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_q text;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO v_org FROM public.workspaces WHERE id = _workspace_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;

  IF NOT (public.is_workspace_member(v_uid, _workspace_id)
          OR public.is_org_admin(v_uid, v_org)) THEN
    RAISE EXCEPTION 'Not authorized for this workspace';
  END IF;

  v_q := lower(COALESCE(NULLIF(trim(_query), ''), ''));
  IF length(v_q) < 2 THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH accessible AS (
    SELECT p.id AS project_id,
           p.organization_id,
           public.btpm_decrypt(p.name, p.organization_id) AS project_name,
           CASE WHEN p.program_id IS NOT NULL
                THEN public.btpm_decrypt(pr.name, pr.organization_id)
                ELSE NULL END AS program_name
      FROM public.projects p
      LEFT JOIN public.programs pr ON pr.id = p.program_id
     WHERE p.workspace_id = _workspace_id
       AND (_include_archived OR p.is_archived = false)
       AND public.has_project_access(v_uid, p.id)
  ),
  proj_match AS (
    SELECT project_id,
           'project'::text AS type,
           project_name AS label,
           NULL::text AS context_label,
           NULL::uuid AS phase_id,
           NULL::uuid AS task_id
      FROM accessible
     WHERE lower(COALESCE(project_name,'')) LIKE '%' || v_q || '%'
  ),
  prog_match AS (
    SELECT project_id,
           'program'::text AS type,
           program_name AS label,
           NULL::text AS context_label,
           NULL::uuid AS phase_id,
           NULL::uuid AS task_id
      FROM accessible
     WHERE program_name IS NOT NULL
       AND lower(program_name) LIKE '%' || v_q || '%'
  ),
  phase_match AS (
    SELECT a.project_id,
           'phase'::text AS type,
           public.btpm_decrypt(ph.name, ph.organization_id) AS label,
           a.project_name AS context_label,
           ph.id AS phase_id,
           NULL::uuid AS task_id
      FROM public.phases ph
      JOIN accessible a ON a.project_id = ph.project_id
     WHERE lower(COALESCE(public.btpm_decrypt(ph.name, ph.organization_id),''))
           LIKE '%' || v_q || '%'
  ),
  task_match AS (
    SELECT a.project_id,
           'task'::text AS type,
           public.btpm_decrypt(t.name, t.organization_id) AS label,
           public.btpm_decrypt(ph.name, ph.organization_id) AS context_label,
           t.phase_id,
           t.id AS task_id
      FROM public.tasks t
      JOIN public.phases ph ON ph.id = t.phase_id
      JOIN accessible a ON a.project_id = t.project_id
     WHERE lower(COALESCE(public.btpm_decrypt(t.name, t.organization_id),''))
           LIKE '%' || v_q || '%'
  ),
  all_matches AS (
    SELECT * FROM proj_match
    UNION ALL SELECT * FROM prog_match
    UNION ALL SELECT * FROM phase_match
    UNION ALL SELECT * FROM task_match
  ),
  grouped AS (
    SELECT project_id,
           COUNT(*) AS match_count,
           jsonb_agg(
             jsonb_build_object(
               'type', type,
               'label', label,
               'context_label', context_label,
               'phase_id', phase_id,
               'task_id', task_id
             )
             ORDER BY CASE type WHEN 'project' THEN 0 WHEN 'program' THEN 1 WHEN 'phase' THEN 2 ELSE 3 END
           ) AS matches
      FROM all_matches
     GROUP BY project_id
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'project_id', project_id,
           'match_count', match_count,
           'matches', matches
         )), '[]'::jsonb)
    INTO v_result
    FROM grouped;

  RETURN v_result;
END;
$$;


--
-- Name: search_workspace_reference_targets(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_workspace_reference_targets(_workspace_id uuid, _query text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_q text;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(v_uid) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT organization_id INTO v_org FROM public.workspaces WHERE id = _workspace_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Workspace not found'; END IF;

  IF NOT (public.is_workspace_member(v_uid, _workspace_id)
          OR public.is_org_admin(v_uid, v_org)) THEN
    RAISE EXCEPTION 'Not authorized for this workspace';
  END IF;

  v_q := lower(COALESCE(NULLIF(trim(_query), ''), ''));

  WITH proj AS (
    SELECT 'project'::text AS target_type,
           p.id AS target_id,
           p.workspace_id,
           p.id AS project_id,
           NULL::uuid AS phase_id,
           public.btpm_decrypt(p.name, p.organization_id) AS display_label,
           NULL::text AS context_label,
           p.updated_at
      FROM public.projects p
     WHERE p.workspace_id = _workspace_id
       AND p.is_archived = false
  ),
  ph AS (
    SELECT 'phase'::text AS target_type,
           x.id AS target_id,
           x.workspace_id,
           x.project_id,
           NULL::uuid AS phase_id,
           public.btpm_decrypt(x.name, x.organization_id) AS display_label,
           public.btpm_decrypt(p2.name, p2.organization_id) AS context_label,
           x.updated_at
      FROM public.phases x
      JOIN public.projects p2 ON p2.id = x.project_id
     WHERE x.workspace_id = _workspace_id
       AND x.is_archived = false
  ),
  tk AS (
    SELECT 'task'::text AS target_type,
           t.id AS target_id,
           t.workspace_id,
           t.project_id,
           t.phase_id,
           public.btpm_decrypt(t.name, t.organization_id) AS display_label,
           public.btpm_decrypt(p3.name, p3.organization_id)
             || ' › ' ||
             public.btpm_decrypt(ph2.name, ph2.organization_id) AS context_label,
           t.updated_at
      FROM public.tasks t
      JOIN public.projects p3 ON p3.id = t.project_id
      JOIN public.phases   ph2 ON ph2.id = t.phase_id
     WHERE t.workspace_id = _workspace_id
  ),
  combined AS (
    SELECT * FROM proj
    UNION ALL SELECT * FROM ph
    UNION ALL SELECT * FROM tk
  ),
  filtered AS (
    SELECT *
      FROM combined
     WHERE v_q = '' OR lower(COALESCE(display_label,'')) LIKE '%' || v_q || '%'
                    OR lower(COALESCE(context_label,'')) LIKE '%' || v_q || '%'
     ORDER BY
       CASE target_type WHEN 'project' THEN 0 WHEN 'phase' THEN 1 ELSE 2 END,
       updated_at DESC
     LIMIT 25
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'target_type', target_type,
           'target_id', target_id,
           'workspace_id', workspace_id,
           'project_id', project_id,
           'phase_id', phase_id,
           'display_label', display_label,
           'context_label', context_label
         )), '[]'::jsonb)
    INTO v_result
    FROM filtered;

  RETURN v_result;
END;
$$;


--
-- Name: seed_post_baseline_phase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_post_baseline_phase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_baselined boolean;
BEGIN
  SELECT is_baselined INTO v_baselined FROM public.projects WHERE id = NEW.project_id;
  IF COALESCE(v_baselined,false) THEN
    IF NEW.start_date IS NULL OR NEW.target_end_date IS NULL THEN
      RAISE EXCEPTION 'Phases added to a baselined project must have planned start and target end dates.';
    END IF;
    PERFORM set_config('btpm.baseline_write','on',true);
    UPDATE public.phases SET baseline_start_date=NEW.start_date,
      baseline_end_date=NEW.target_end_date, added_after_baseline=true WHERE id = NEW.id;
    PERFORM set_config('btpm.baseline_write','off',true);
    PERFORM public.log_activity_event(
      NEW.organization_id,
      auth.uid(),
      'baseline_post_add',
      'phase',
      NEW.id,
      jsonb_build_object('baseline_start',NEW.start_date,'baseline_end',NEW.target_end_date),
      NEW.workspace_id
    );
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: seed_post_baseline_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_post_baseline_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_baselined boolean;
BEGIN
  SELECT is_baselined INTO v_baselined FROM public.projects WHERE id = NEW.project_id;
  IF COALESCE(v_baselined,false) THEN
    IF NEW.start_date IS NULL OR NEW.due_date IS NULL THEN
      RAISE EXCEPTION 'Tasks added to a baselined project must have planned start and due dates.';
    END IF;
    PERFORM set_config('btpm.baseline_write','on',true);
    UPDATE public.tasks SET baseline_start_date=NEW.start_date,
      baseline_end_date=NEW.due_date, added_after_baseline=true WHERE id = NEW.id;
    PERFORM set_config('btpm.baseline_write','off',true);
    PERFORM public.log_activity_event(
      NEW.organization_id,
      auth.uid(),
      'baseline_post_add',
      'task',
      NEW.id,
      jsonb_build_object('baseline_start',NEW.start_date,'baseline_end',NEW.due_date),
      NEW.workspace_id
    );
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: service_enqueue_tenant_background_job(uuid, text, jsonb, uuid, uuid, integer, text, integer, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_enqueue_tenant_background_job(_tenant_id uuid, _job_type text, _payload jsonb DEFAULT '{}'::jsonb, _organization_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _priority integer DEFAULT 100, _idempotency_key text DEFAULT NULL::text, _max_attempts integer DEFAULT 3, _not_before timestamp with time zone DEFAULT NULL::timestamp with time zone, _requested_by uuid DEFAULT NULL::uuid, _run_as_user_id uuid DEFAULT NULL::uuid) RETURNS public.tenant_background_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_background_jobs;
  _org_tenant uuid;
BEGIN
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id is required'; END IF;
  IF _job_type IS NULL OR length(btrim(_job_type)) = 0 THEN RAISE EXCEPTION 'job_type is required'; END IF;
  IF jsonb_typeof(COALESCE(_payload, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'payload must be a JSON object';
  END IF;
  PERFORM public._assert_job_payload_no_secret_keys(COALESCE(_payload, '{}'::jsonb));

  IF _organization_id IS NOT NULL THEN
    SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = _organization_id;
    IF _org_tenant IS NULL OR _org_tenant <> _tenant_id THEN
      RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _tenant_id;
    END IF;
  END IF;

  IF _requested_by IS NOT NULL THEN
    IF NOT public.is_tenant_member(_tenant_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active tenant member';
    END IF;
    IF _organization_id IS NOT NULL
       AND NOT public.is_organization_member(_organization_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_requested_by, _workspace_id) THEN
      RAISE EXCEPTION 'requested_by is not an active workspace member';
    END IF;
  END IF;

  IF _run_as_user_id IS NOT NULL THEN
    IF NOT public.is_tenant_member(_tenant_id, _run_as_user_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active tenant member';
    END IF;
    IF _organization_id IS NOT NULL
       AND NOT public.is_organization_member(_organization_id, _run_as_user_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_run_as_user_id, _workspace_id) THEN
      RAISE EXCEPTION 'run_as_user_id is not an active workspace member';
    END IF;
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT * INTO _row FROM public.tenant_background_jobs
      WHERE tenant_id = _tenant_id AND job_type = _job_type AND idempotency_key = _idempotency_key;
    IF _row.id IS NOT NULL THEN RETURN _row; END IF;
  END IF;

  INSERT INTO public.tenant_background_jobs (
    tenant_id, organization_id, workspace_id, job_type, priority,
    requested_by, run_as_user_id, idempotency_key, payload, max_attempts, not_before
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _job_type, COALESCE(_priority, 100),
    _requested_by, _run_as_user_id, _idempotency_key, COALESCE(_payload, '{}'::jsonb),
    COALESCE(_max_attempts, 3), _not_before
  ) RETURNING * INTO _row;
  RETURN _row;
END $$;


--
-- Name: service_get_tenant_protected_download_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_get_tenant_protected_download_context(_storage_object_id uuid, _requested_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _o public.tenant_storage_objects;
BEGIN
  SELECT * INTO _o FROM public.tenant_storage_objects WHERE id = _storage_object_id;
  IF _o.id IS NULL THEN RAISE EXCEPTION 'Storage object % not found', _storage_object_id; END IF;

  IF _requested_by IS NOT NULL THEN
    IF NOT public.is_tenant_member(_o.tenant_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active tenant member';
    END IF;
    IF NOT public.is_organization_member(_o.organization_id, _requested_by) THEN
      RAISE EXCEPTION 'requested_by is not an active organization member';
    END IF;
    IF _o.workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_requested_by, _o.workspace_id) THEN
      RAISE EXCEPTION 'requested_by is not an active workspace member';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'storage_object_id', _o.id,
    'tenant_id', _o.tenant_id,
    'organization_id', _o.organization_id,
    'workspace_id', _o.workspace_id,
    'bucket', _o.bucket,
    'object_path', _o.object_path,
    'file_name', _o.file_name,
    'content_type', _o.content_type,
    'size_bytes', _o.size_bytes,
    'storage_status', _o.storage_status
  );
END $$;


--
-- Name: service_manage_powerbi_reporting_identity(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_manage_powerbi_reporting_identity(_tenant_id uuid, _action text, _actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  _act text;
  _tenant record;
  _map record;
  _role text;
  _role_oid oid;
  _role_exists boolean := false;
  _reader_exists boolean := false;
  _login boolean := false;
  _conn_limit int;
  _rolsuper boolean; _rolcreatedb boolean; _rolcreaterole boolean;
  _rolreplication boolean; _rolbypassrls boolean; _rolinherit boolean;
  _memberships text[] := ARRAY[]::text[];
  _owned_schemas int := 0;
  _owned_relations int := 0;
  _settings text[];
  _has_search_path boolean := false;
  _has_readonly boolean := false;
  _has_stmt_timeout boolean := false;
  _has_idle_timeout boolean := false;
  _session_defaults_ok boolean := false;
  _attrs_ok boolean := false;
  _membership_ok boolean := false;
  _ownership_ok boolean := false;
  _security_drift boolean := false;
  _terminated int := 0;
  _grantor text;
  _pw text;
  _new_meta jsonb;
  _old_meta jsonb;
  _s text;

  -- Postflight snapshot vars
  _pf_login boolean;
  _pf_state text;
  _pf_credstate text;
  _pf_tenant_active boolean;
  _pf_last_verified timestamptz;
  _pf_memberships text[];
BEGIN
  -- 1. Input validation
  IF _tenant_id IS NULL OR _actor_user_id IS NULL OR _action IS NULL THEN
    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = '22023';
  END IF;
  _act := lower(btrim(_action));
  IF _act NOT IN ('provision','rotate','disable','enable','activate','revoke') THEN
    RAISE EXCEPTION 'invalid_action' USING ERRCODE = '22023';
  END IF;

  -- 2. Tenant load (status not enforced here — see per-action gate below)
  SELECT id, name, status::text AS status INTO _tenant
    FROM public.tenants WHERE id = _tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002'; END IF;

  -- 3. Authorization
  IF NOT (public.is_platform_super_admin(_actor_user_id)
          OR public.is_tenant_admin(_tenant_id, _actor_user_id)) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- 4. Derive role name (never client-supplied)
  _role := 'btpm_pbi_t_' || replace(_tenant_id::text, '-', '');
  IF _role !~ '^btpm_pbi_t_[a-f0-9]{32}$' THEN
    RAISE EXCEPTION 'invalid_derived_role' USING ERRCODE = '42501';
  END IF;

  -- 5. Load mapping (if any)
  SELECT login_role_name, tenant_id, state::text AS state,
         provisioned_at, last_rotated_at, last_verified_at,
         disabled_at, revoked_at, operational_metadata
    INTO _map
    FROM pbi_reporting_security.tenant_login_map
   WHERE tenant_id = _tenant_id
   ORDER BY provisioned_at DESC LIMIT 1;
  _old_meta := COALESCE(_map.operational_metadata, '{}'::jsonb);

  -- 6. Shared reader base role inspection (existence-only; per-action gate below)
  _reader_exists := EXISTS (
    SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'btpm_pbi_reader'
  );

  -- 6b. Per-action gates for normal (non-emergency) actions.
  --     Tenant-active + reader-role existence are required only for actions
  --     that provision or restore data-access capability. Disable/revoke are
  --     emergency shutdowns and must remain executable in either state.
  IF _act IN ('provision','rotate','enable','activate') THEN
    IF _tenant.status <> 'active' THEN
      RAISE EXCEPTION 'tenant_not_active' USING ERRCODE = '42501';
    END IF;
    IF NOT _reader_exists THEN
      RAISE EXCEPTION 'reader_role_missing' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 7. Inspect role (may or may not exist)
  SELECT r.oid, r.rolcanlogin, r.rolconnlimit,
         r.rolsuper, r.rolcreatedb, r.rolcreaterole,
         r.rolreplication, r.rolbypassrls, r.rolinherit
    INTO _role_oid, _login, _conn_limit,
         _rolsuper, _rolcreatedb, _rolcreaterole,
         _rolreplication, _rolbypassrls, _rolinherit
    FROM pg_catalog.pg_roles r WHERE r.rolname = _role;
  _role_exists := FOUND;

  IF _role_exists THEN
    SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[])
      INTO _memberships
      FROM pg_catalog.pg_auth_members m
      JOIN pg_catalog.pg_roles pr ON pr.oid = m.roleid
     WHERE m.member = _role_oid;

    SELECT COUNT(*) INTO _owned_schemas
      FROM pg_catalog.pg_namespace WHERE nspowner = _role_oid;
    SELECT COUNT(*) INTO _owned_relations
      FROM pg_catalog.pg_class WHERE relowner = _role_oid;

    _has_search_path := false; _has_readonly := false;
    _has_stmt_timeout := false; _has_idle_timeout := false;
    SELECT s.setconfig INTO _settings
      FROM pg_catalog.pg_db_role_setting s
     WHERE s.setrole = _role_oid AND s.setdatabase = 0;
    IF _settings IS NOT NULL THEN
      FOREACH _s IN ARRAY _settings LOOP
        IF _s = 'search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN _has_search_path := true;
        ELSIF _s = 'default_transaction_read_only=on' THEN _has_readonly := true;
        ELSIF _s = 'statement_timeout=5min' THEN _has_stmt_timeout := true;
        ELSIF _s = 'idle_in_transaction_session_timeout=1min' THEN _has_idle_timeout := true;
        END IF;
      END LOOP;
    END IF;
    _session_defaults_ok := _has_search_path AND _has_readonly AND _has_stmt_timeout AND _has_idle_timeout;
    _attrs_ok := (_rolsuper = false) AND (_rolcreatedb = false)
             AND (_rolcreaterole = false) AND (_rolreplication = false)
             AND (_rolbypassrls = false) AND (_rolinherit = true)
             AND (_conn_limit = 8);
    _membership_ok := (_memberships = ARRAY['btpm_pbi_reader']::text[]);
    _ownership_ok := (_owned_schemas = 0 AND _owned_relations = 0);
  END IF;

  -- 8. Security drift (safe boolean; details never returned/logged).
  --    Includes: mapped-role missing, shared reader missing, or any
  --    invariant deviation on the Tenant role.
  _security_drift := (_map.login_role_name IS NOT NULL AND NOT _role_exists)
    OR (NOT _reader_exists)
    OR (_role_exists AND NOT (_attrs_ok AND _membership_ok AND _ownership_ok AND _session_defaults_ok));

  -- =========================================================================
  -- PROVISION
  -- =========================================================================
  IF _act = 'provision' THEN
    IF _map.login_role_name IS NOT NULL THEN
      RAISE EXCEPTION 'mapping_already_exists' USING ERRCODE = '42501';
    END IF;
    IF _role_exists THEN
      RAISE EXCEPTION 'role_already_exists' USING ERRCODE = '42501';
    END IF;

    _pw := encode(extensions.gen_random_bytes(32), 'hex');
    EXECUTE format(
      'CREATE ROLE %I LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE '
      'NOREPLICATION NOBYPASSRLS INHERIT CONNECTION LIMIT 8 PASSWORD %L',
      _role, _pw
    );
    EXECUTE format('GRANT btpm_pbi_reader TO %I', _role);
    EXECUTE format('ALTER ROLE %I SET search_path = %s',
      _role, 'pbi_reporting, pbi_reporting_security, pg_catalog');
    EXECUTE format('ALTER ROLE %I SET default_transaction_read_only = on', _role);
    EXECUTE format('ALTER ROLE %I SET statement_timeout = ''5min''', _role);
    EXECUTE format('ALTER ROLE %I SET idle_in_transaction_session_timeout = ''1min''', _role);

    _new_meta := jsonb_build_object(
      'provisioning_stage', 'credential_issued_pending_activation',
      'credential_state',   'pending_activation',
      'login_enabled',      true,
      'tenant_access_active', false,
      'session_pooler_verified', false,
      'session_user_verified',   false,
      'fail_closed_pre_activation_verified', false
    );

    INSERT INTO pbi_reporting_security.tenant_login_map (
      login_role_name, tenant_id, state,
      provisioned_at, last_rotated_at, last_verified_at,
      disabled_at, revoked_at,
      actor_identity, actor_type, operational_metadata,
      created_at, updated_at
    ) VALUES (
      _role, _tenant_id, 'disabled',
      now(), now(), NULL,
      now(), NULL,
      _actor_user_id::text, 'tenant_admin_action', _new_meta,
      now(), now()
    );

    INSERT INTO pbi_reporting_security.tenant_login_audit (
      event_type, login_role_name, tenant_id,
      actor_identity, actor_type, context, event_at
    ) VALUES (
      'provisioned', _role, _tenant_id,
      _actor_user_id::text, 'tenant_admin_action',
      jsonb_build_object(
        'action','provision','login_enabled',true,
        'mapping_state','disabled','credential_state','pending_activation',
        'credential_returned_once',true,'verification_required',true,
        'next_action','activate'
      ),
      now()
    );

    -- Postflight — full: attributes, membership, ownership, session defaults, mapping
    SELECT r.oid, r.rolcanlogin, r.rolconnlimit,
           r.rolsuper, r.rolcreatedb, r.rolcreaterole,
           r.rolreplication, r.rolbypassrls, r.rolinherit
      INTO _role_oid, _pf_login, _conn_limit,
           _rolsuper, _rolcreatedb, _rolcreaterole,
           _rolreplication, _rolbypassrls, _rolinherit
      FROM pg_catalog.pg_roles r WHERE r.rolname = _role;
    IF NOT FOUND THEN RAISE EXCEPTION 'postflight_provision_failed' USING ERRCODE = '42501'; END IF;
    IF NOT (COALESCE(_pf_login,false)
            AND _rolsuper = false AND _rolcreatedb = false AND _rolcreaterole = false
            AND _rolreplication = false AND _rolbypassrls = false
            AND _rolinherit = true AND _conn_limit = 8) THEN
      RAISE EXCEPTION 'postflight_provision_failed' USING ERRCODE = '42501';
    END IF;
    SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[])
      INTO _pf_memberships
      FROM pg_catalog.pg_auth_members m
      JOIN pg_catalog.pg_roles pr ON pr.oid = m.roleid
     WHERE m.member = _role_oid;
    IF _pf_memberships <> ARRAY['btpm_pbi_reader']::text[] THEN
      RAISE EXCEPTION 'postflight_provision_failed' USING ERRCODE = '42501';
    END IF;
    IF (SELECT COUNT(*) FROM pg_catalog.pg_namespace WHERE nspowner = _role_oid) > 0
       OR (SELECT COUNT(*) FROM pg_catalog.pg_class WHERE relowner = _role_oid) > 0 THEN
      RAISE EXCEPTION 'postflight_provision_failed' USING ERRCODE = '42501';
    END IF;
    _has_search_path := false; _has_readonly := false;
    _has_stmt_timeout := false; _has_idle_timeout := false;
    SELECT s.setconfig INTO _settings
      FROM pg_catalog.pg_db_role_setting s WHERE s.setrole = _role_oid AND s.setdatabase = 0;
    IF _settings IS NOT NULL THEN
      FOREACH _s IN ARRAY _settings LOOP
        IF _s = 'search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN _has_search_path := true;
        ELSIF _s = 'default_transaction_read_only=on' THEN _has_readonly := true;
        ELSIF _s = 'statement_timeout=5min' THEN _has_stmt_timeout := true;
        ELSIF _s = 'idle_in_transaction_session_timeout=1min' THEN _has_idle_timeout := true;
        END IF;
      END LOOP;
    END IF;
    IF NOT (_has_search_path AND _has_readonly AND _has_stmt_timeout AND _has_idle_timeout) THEN
      RAISE EXCEPTION 'postflight_provision_failed' USING ERRCODE = '42501';
    END IF;
    SELECT m.state::text, m.operational_metadata->>'credential_state',
           (m.operational_metadata->>'tenant_access_active')::boolean, m.last_verified_at
      INTO _pf_state, _pf_credstate, _pf_tenant_active, _pf_last_verified
      FROM pbi_reporting_security.tenant_login_map m WHERE m.login_role_name = _role;
    IF NOT (_pf_state = 'disabled' AND _pf_credstate = 'pending_activation'
            AND _pf_tenant_active = false AND _pf_last_verified IS NULL) THEN
      RAISE EXCEPTION 'postflight_provision_failed' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
      'action','provision','tenant_id',_tenant_id,'login_role_name',_role,
      'mapping_state','disabled','credential_state','pending_activation',
      'one_time_password',_pw,'password_display_once',true,
      'verification_required',true,'next_action','activate'
    );
  END IF;

  -- For every non-provision action the mapping must already exist and match.
  IF _map.login_role_name IS NULL THEN
    RAISE EXCEPTION 'mapping_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF _map.login_role_name <> _role THEN
    RAISE EXCEPTION 'mapping_role_mismatch' USING ERRCODE = '42501';
  END IF;

  -- =========================================================================
  -- Full-invariant gate for rotate / enable / activate (strict).
  -- Disable/revoke deliberately skip this gate — they are emergency controls.
  -- =========================================================================
  IF _act IN ('rotate','enable','activate') THEN
    IF NOT _role_exists THEN
      RAISE EXCEPTION 'role_missing' USING ERRCODE = 'P0002';
    END IF;
    IF NOT _attrs_ok THEN
      RAISE EXCEPTION 'role_attributes_invalid' USING ERRCODE = '42501';
    END IF;
    IF NOT _membership_ok THEN
      RAISE EXCEPTION 'membership_invalid' USING ERRCODE = '42501';
    END IF;
    IF _owned_schemas > 0 THEN
      RAISE EXCEPTION 'role_owns_schemas' USING ERRCODE = '42501';
    END IF;
    IF _owned_relations > 0 THEN
      RAISE EXCEPTION 'role_owns_relations' USING ERRCODE = '42501';
    END IF;
    IF NOT _session_defaults_ok THEN
      RAISE EXCEPTION 'session_defaults_invalid' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- =========================================================================
  -- ROTATE — only from active; result = disabled pending activation
  -- =========================================================================
  IF _act = 'rotate' THEN
    IF _map.state <> 'active' THEN
      RAISE EXCEPTION 'mapping_not_active' USING ERRCODE = '42501';
    END IF;
    IF _login = false THEN
      RAISE EXCEPTION 'role_nologin_unexpected' USING ERRCODE = '42501';
    END IF;
    _pw := encode(extensions.gen_random_bytes(32), 'hex');
    EXECUTE format('ALTER ROLE %I LOGIN PASSWORD %L', _role, _pw);

    _new_meta := _old_meta || jsonb_build_object(
      'provisioning_stage', 'credential_issued_pending_activation',
      'credential_state','pending_activation','login_enabled',true,
      'tenant_access_active',false,'session_pooler_verified',false,
      'session_user_verified',false,'fail_closed_pre_activation_verified',false
    );

    UPDATE pbi_reporting_security.tenant_login_map
       SET state='disabled', disabled_at=now(), last_rotated_at=now(),
           last_verified_at=NULL, operational_metadata=_new_meta,
           actor_identity=_actor_user_id::text, actor_type='tenant_admin_action',
           updated_at=now()
     WHERE login_role_name=_role;

    INSERT INTO pbi_reporting_security.tenant_login_audit(
      event_type, login_role_name, tenant_id, actor_identity, actor_type, context, event_at
    ) VALUES (
      'rotated', _role, _tenant_id, _actor_user_id::text, 'tenant_admin_action',
      jsonb_build_object('action','rotate','mapping_state','disabled',
        'credential_state','pending_activation','credential_returned_once',true,
        'verification_required',true,'next_action','activate'), now()
    );

    -- Postflight — full invariants must still hold
    SELECT r.oid, r.rolcanlogin, r.rolconnlimit, r.rolsuper, r.rolcreatedb, r.rolcreaterole,
           r.rolreplication, r.rolbypassrls, r.rolinherit
      INTO _role_oid, _pf_login, _conn_limit, _rolsuper, _rolcreatedb, _rolcreaterole,
           _rolreplication, _rolbypassrls, _rolinherit
      FROM pg_catalog.pg_roles r WHERE r.rolname = _role;
    IF NOT FOUND OR NOT (COALESCE(_pf_login,false)
        AND _rolsuper=false AND _rolcreatedb=false AND _rolcreaterole=false
        AND _rolreplication=false AND _rolbypassrls=false AND _rolinherit=true AND _conn_limit=8) THEN
      RAISE EXCEPTION 'postflight_rotate_failed' USING ERRCODE = '42501';
    END IF;
    SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[]) INTO _pf_memberships
      FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles pr ON pr.oid=m.roleid
     WHERE m.member=_role_oid;
    IF _pf_memberships <> ARRAY['btpm_pbi_reader']::text[]
       OR (SELECT COUNT(*) FROM pg_catalog.pg_namespace WHERE nspowner=_role_oid) > 0
       OR (SELECT COUNT(*) FROM pg_catalog.pg_class WHERE relowner=_role_oid) > 0 THEN
      RAISE EXCEPTION 'postflight_rotate_failed' USING ERRCODE = '42501';
    END IF;
    _has_search_path:=false;_has_readonly:=false;_has_stmt_timeout:=false;_has_idle_timeout:=false;
    SELECT s.setconfig INTO _settings FROM pg_catalog.pg_db_role_setting s
      WHERE s.setrole=_role_oid AND s.setdatabase=0;
    IF _settings IS NOT NULL THEN
      FOREACH _s IN ARRAY _settings LOOP
        IF _s='search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN _has_search_path:=true;
        ELSIF _s='default_transaction_read_only=on' THEN _has_readonly:=true;
        ELSIF _s='statement_timeout=5min' THEN _has_stmt_timeout:=true;
        ELSIF _s='idle_in_transaction_session_timeout=1min' THEN _has_idle_timeout:=true;
        END IF;
      END LOOP;
    END IF;
    IF NOT (_has_search_path AND _has_readonly AND _has_stmt_timeout AND _has_idle_timeout) THEN
      RAISE EXCEPTION 'postflight_rotate_failed' USING ERRCODE = '42501';
    END IF;
    SELECT m.state::text, m.operational_metadata->>'credential_state',
           (m.operational_metadata->>'tenant_access_active')::boolean, m.last_verified_at
      INTO _pf_state, _pf_credstate, _pf_tenant_active, _pf_last_verified
      FROM pbi_reporting_security.tenant_login_map m WHERE m.login_role_name=_role;
    IF NOT (_pf_state='disabled' AND _pf_credstate='pending_activation'
            AND _pf_tenant_active=false AND _pf_last_verified IS NULL) THEN
      RAISE EXCEPTION 'postflight_rotate_failed' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
      'action','rotate','tenant_id',_tenant_id,'login_role_name',_role,
      'mapping_state','disabled','credential_state','pending_activation',
      'one_time_password',_pw,'password_display_once',true,
      'verification_required',true,'next_action','activate'
    );
  END IF;

  -- =========================================================================
  -- ENABLE — only from administratively disabled + NOLOGIN
  -- =========================================================================
  IF _act = 'enable' THEN
    IF _map.state <> 'disabled' THEN
      RAISE EXCEPTION 'mapping_not_disabled' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(_old_meta->>'credential_state','') <> 'disabled' THEN
      RAISE EXCEPTION 'credential_not_disabled' USING ERRCODE = '42501';
    END IF;
    IF _login = true THEN
      RAISE EXCEPTION 'role_not_nologin' USING ERRCODE = '42501';
    END IF;

    _pw := encode(extensions.gen_random_bytes(32), 'hex');
    EXECUTE format('ALTER ROLE %I LOGIN PASSWORD %L', _role, _pw);

    _new_meta := _old_meta || jsonb_build_object(
      'provisioning_stage','credential_issued_pending_activation',
      'credential_state','pending_activation','login_enabled',true,
      'tenant_access_active',false,'session_pooler_verified',false,
      'session_user_verified',false,'fail_closed_pre_activation_verified',false
    );

    UPDATE pbi_reporting_security.tenant_login_map
       SET state='disabled', disabled_at=COALESCE(disabled_at, now()),
           last_rotated_at=now(), last_verified_at=NULL,
           operational_metadata=_new_meta, actor_identity=_actor_user_id::text,
           actor_type='tenant_admin_action', updated_at=now()
     WHERE login_role_name=_role;

    INSERT INTO pbi_reporting_security.tenant_login_audit(
      event_type, login_role_name, tenant_id, actor_identity, actor_type, context, event_at
    ) VALUES (
      'other', _role, _tenant_id, _actor_user_id::text, 'tenant_admin_action',
      jsonb_build_object('action','reenabled_pending_activation',
        'mapping_state','disabled','credential_state','pending_activation',
        'credential_returned_once',true,'verification_required',true,'next_action','activate'),
      now()
    );

    -- Postflight — full invariants
    SELECT r.oid, r.rolcanlogin, r.rolconnlimit, r.rolsuper, r.rolcreatedb, r.rolcreaterole,
           r.rolreplication, r.rolbypassrls, r.rolinherit
      INTO _role_oid, _pf_login, _conn_limit, _rolsuper, _rolcreatedb, _rolcreaterole,
           _rolreplication, _rolbypassrls, _rolinherit
      FROM pg_catalog.pg_roles r WHERE r.rolname = _role;
    IF NOT FOUND OR NOT (COALESCE(_pf_login,false)
        AND _rolsuper=false AND _rolcreatedb=false AND _rolcreaterole=false
        AND _rolreplication=false AND _rolbypassrls=false AND _rolinherit=true AND _conn_limit=8) THEN
      RAISE EXCEPTION 'postflight_enable_failed' USING ERRCODE = '42501';
    END IF;
    SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[]) INTO _pf_memberships
      FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles pr ON pr.oid=m.roleid
     WHERE m.member=_role_oid;
    IF _pf_memberships <> ARRAY['btpm_pbi_reader']::text[]
       OR (SELECT COUNT(*) FROM pg_catalog.pg_namespace WHERE nspowner=_role_oid) > 0
       OR (SELECT COUNT(*) FROM pg_catalog.pg_class WHERE relowner=_role_oid) > 0 THEN
      RAISE EXCEPTION 'postflight_enable_failed' USING ERRCODE = '42501';
    END IF;
    _has_search_path:=false;_has_readonly:=false;_has_stmt_timeout:=false;_has_idle_timeout:=false;
    SELECT s.setconfig INTO _settings FROM pg_catalog.pg_db_role_setting s
      WHERE s.setrole=_role_oid AND s.setdatabase=0;
    IF _settings IS NOT NULL THEN
      FOREACH _s IN ARRAY _settings LOOP
        IF _s='search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN _has_search_path:=true;
        ELSIF _s='default_transaction_read_only=on' THEN _has_readonly:=true;
        ELSIF _s='statement_timeout=5min' THEN _has_stmt_timeout:=true;
        ELSIF _s='idle_in_transaction_session_timeout=1min' THEN _has_idle_timeout:=true;
        END IF;
      END LOOP;
    END IF;
    IF NOT (_has_search_path AND _has_readonly AND _has_stmt_timeout AND _has_idle_timeout) THEN
      RAISE EXCEPTION 'postflight_enable_failed' USING ERRCODE = '42501';
    END IF;
    SELECT m.state::text, m.operational_metadata->>'credential_state',
           (m.operational_metadata->>'tenant_access_active')::boolean, m.last_verified_at
      INTO _pf_state, _pf_credstate, _pf_tenant_active, _pf_last_verified
      FROM pbi_reporting_security.tenant_login_map m WHERE m.login_role_name=_role;
    IF NOT (_pf_state='disabled' AND _pf_credstate='pending_activation'
            AND _pf_tenant_active=false AND _pf_last_verified IS NULL) THEN
      RAISE EXCEPTION 'postflight_enable_failed' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
      'action','enable','tenant_id',_tenant_id,'login_role_name',_role,
      'mapping_state','disabled','credential_state','pending_activation',
      'one_time_password',_pw,'password_display_once',true,
      'verification_required',true,'next_action','activate'
    );
  END IF;

  -- =========================================================================
  -- ACTIVATE — pending_activation → active. No password.
  -- =========================================================================
  IF _act = 'activate' THEN
    IF _map.state <> 'disabled' THEN
      RAISE EXCEPTION 'mapping_not_disabled' USING ERRCODE = '42501';
    END IF;
    IF COALESCE(_old_meta->>'credential_state','') <> 'pending_activation' THEN
      RAISE EXCEPTION 'credential_not_pending_activation' USING ERRCODE = '42501';
    END IF;
    IF _login = false THEN
      RAISE EXCEPTION 'role_nologin_unexpected' USING ERRCODE = '42501';
    END IF;

    _new_meta := _old_meta || jsonb_build_object(
      'provisioning_stage','tenant_mapping_active','credential_state','active',
      'login_enabled',true,'tenant_access_active',true,
      'session_pooler_verified',true,'session_user_verified',true,
      'fail_closed_pre_activation_verified',true,
      'verification_channel','tenant_admin_confirmed_power_bi_test'
    );

    UPDATE pbi_reporting_security.tenant_login_map
       SET state='active', disabled_at=NULL, revoked_at=NULL,
           last_verified_at=now(), operational_metadata=_new_meta,
           actor_identity=_actor_user_id::text, actor_type='tenant_admin_action',
           updated_at=now()
     WHERE login_role_name=_role;

    INSERT INTO pbi_reporting_security.tenant_login_audit(
      event_type, login_role_name, tenant_id, actor_identity, actor_type, context, event_at
    ) VALUES (
      'verified', _role, _tenant_id, _actor_user_id::text, 'tenant_admin_action',
      jsonb_build_object('action','activate_after_external_verification',
        'evidence_source','tenant_admin_confirmed_power_bi_test',
        'session_user_match',true,'disabled_fail_closed_verified',true,
        'previous_mapping_state','disabled','new_mapping_state','active'),
      now()
    );

    -- Postflight — full invariants + active mapping + verification flags
    SELECT r.oid, r.rolcanlogin, r.rolconnlimit, r.rolsuper, r.rolcreatedb, r.rolcreaterole,
           r.rolreplication, r.rolbypassrls, r.rolinherit
      INTO _role_oid, _pf_login, _conn_limit, _rolsuper, _rolcreatedb, _rolcreaterole,
           _rolreplication, _rolbypassrls, _rolinherit
      FROM pg_catalog.pg_roles r WHERE r.rolname = _role;
    IF NOT FOUND OR NOT (COALESCE(_pf_login,false)
        AND _rolsuper=false AND _rolcreatedb=false AND _rolcreaterole=false
        AND _rolreplication=false AND _rolbypassrls=false AND _rolinherit=true AND _conn_limit=8) THEN
      RAISE EXCEPTION 'postflight_activate_failed' USING ERRCODE = '42501';
    END IF;
    SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[]) INTO _pf_memberships
      FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles pr ON pr.oid=m.roleid
     WHERE m.member=_role_oid;
    IF _pf_memberships <> ARRAY['btpm_pbi_reader']::text[]
       OR (SELECT COUNT(*) FROM pg_catalog.pg_namespace WHERE nspowner=_role_oid) > 0
       OR (SELECT COUNT(*) FROM pg_catalog.pg_class WHERE relowner=_role_oid) > 0 THEN
      RAISE EXCEPTION 'postflight_activate_failed' USING ERRCODE = '42501';
    END IF;
    _has_search_path:=false;_has_readonly:=false;_has_stmt_timeout:=false;_has_idle_timeout:=false;
    SELECT s.setconfig INTO _settings FROM pg_catalog.pg_db_role_setting s
      WHERE s.setrole=_role_oid AND s.setdatabase=0;
    IF _settings IS NOT NULL THEN
      FOREACH _s IN ARRAY _settings LOOP
        IF _s='search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN _has_search_path:=true;
        ELSIF _s='default_transaction_read_only=on' THEN _has_readonly:=true;
        ELSIF _s='statement_timeout=5min' THEN _has_stmt_timeout:=true;
        ELSIF _s='idle_in_transaction_session_timeout=1min' THEN _has_idle_timeout:=true;
        END IF;
      END LOOP;
    END IF;
    IF NOT (_has_search_path AND _has_readonly AND _has_stmt_timeout AND _has_idle_timeout) THEN
      RAISE EXCEPTION 'postflight_activate_failed' USING ERRCODE = '42501';
    END IF;
    SELECT m.state::text, m.operational_metadata->>'credential_state',
           (m.operational_metadata->>'tenant_access_active')::boolean, m.last_verified_at
      INTO _pf_state, _pf_credstate, _pf_tenant_active, _pf_last_verified
      FROM pbi_reporting_security.tenant_login_map m WHERE m.login_role_name=_role;
    IF NOT (_pf_state='active' AND _pf_credstate='active'
            AND _pf_tenant_active=true AND _pf_last_verified IS NOT NULL
            AND COALESCE((_new_meta->>'session_pooler_verified')::boolean,false)
            AND COALESCE((_new_meta->>'session_user_verified')::boolean,false)
            AND COALESCE((_new_meta->>'fail_closed_pre_activation_verified')::boolean,false)) THEN
      RAISE EXCEPTION 'postflight_activate_failed' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
      'action','activate','tenant_id',_tenant_id,'login_role_name',_role,
      'mapping_state','active','credential_state','active',
      'password_display_once',false,'verification_required',false
    );
  END IF;

  -- =========================================================================
  -- DISABLE — fail-safe. Only from active. Runs even when drift is present
  --           or the Tenant is not active or the shared reader is absent.
  -- =========================================================================
  IF _act = 'disable' THEN
    IF _map.state <> 'active' THEN
      RAISE EXCEPTION 'mapping_not_active' USING ERRCODE = '42501';
    END IF;

    _terminated := 0;
    IF _role_exists THEN
      EXECUTE format('ALTER ROLE %I NOLOGIN', _role);
      -- Terminate only sessions owned by the derived Tenant role, never our own.
      SELECT COALESCE(SUM(CASE WHEN pg_catalog.pg_terminate_backend(s.pid) THEN 1 ELSE 0 END), 0)::int
        INTO _terminated
        FROM pg_catalog.pg_stat_activity s
       WHERE s.usename = _role
         AND s.pid <> pg_backend_pid();
    END IF;

    _new_meta := _old_meta || jsonb_build_object(
      'provisioning_stage','administratively_disabled','credential_state','disabled',
      'login_enabled',false,'tenant_access_active',false,
      'session_pooler_verified',false,'session_user_verified',false,
      'fail_closed_pre_activation_verified',false
    );

    UPDATE pbi_reporting_security.tenant_login_map
       SET state='disabled', disabled_at=now(), last_verified_at=NULL,
           operational_metadata=_new_meta,
           actor_identity=_actor_user_id::text, actor_type='tenant_admin_action',
           updated_at=now()
     WHERE login_role_name=_role;

    INSERT INTO pbi_reporting_security.tenant_login_audit(
      event_type, login_role_name, tenant_id, actor_identity, actor_type, context, event_at
    ) VALUES (
      'disabled', _role, _tenant_id, _actor_user_id::text, 'tenant_admin_action',
      jsonb_build_object(
        'action','disable','mapping_state','disabled','credential_state','disabled',
        'login_enabled',false,
        'security_drift_detected', _security_drift,
        'terminated_session_count', _terminated
      ),
      now()
    );

    -- Postflight — do NOT re-require role invariants
    SELECT r.rolcanlogin INTO _pf_login FROM pg_catalog.pg_roles r WHERE r.rolname=_role;
    SELECT m.state::text, m.operational_metadata->>'credential_state',
           (m.operational_metadata->>'tenant_access_active')::boolean, m.last_verified_at
      INTO _pf_state, _pf_credstate, _pf_tenant_active, _pf_last_verified
      FROM pbi_reporting_security.tenant_login_map m WHERE m.login_role_name=_role;
    IF NOT (_pf_state='disabled' AND _pf_credstate='disabled'
            AND _pf_tenant_active=false AND _pf_last_verified IS NULL
            AND (NOT _role_exists OR COALESCE(_pf_login,true)=false)) THEN
      RAISE EXCEPTION 'postflight_disable_failed' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
      'action','disable','tenant_id',_tenant_id,'login_role_name',_role,
      'mapping_state','disabled','credential_state','disabled',
      'password_display_once',false,
      'security_drift_detected', _security_drift,
      'terminated_session_count', _terminated
    );
  END IF;

  -- =========================================================================
  -- REVOKE — fail-safe and final. From active or disabled. Runs even when
  --          drift is present or the Tenant is not active or the shared
  --          reader is absent.
  -- =========================================================================
  IF _act = 'revoke' THEN
    IF _map.state NOT IN ('active','disabled') THEN
      RAISE EXCEPTION 'mapping_not_revokable' USING ERRCODE = '42501';
    END IF;

    _terminated := 0;
    IF _role_exists THEN
      EXECUTE format('ALTER ROLE %I NOLOGIN PASSWORD NULL', _role);
      SELECT COALESCE(SUM(CASE WHEN pg_catalog.pg_terminate_backend(s.pid) THEN 1 ELSE 0 END), 0)::int
        INTO _terminated
        FROM pg_catalog.pg_stat_activity s
       WHERE s.usename = _role
         AND s.pid <> pg_backend_pid();

      -- Revoke every direct membership currently granted to the Tenant role.
      FOR _grantor IN
        SELECT pr.rolname
          FROM pg_catalog.pg_auth_members m
          JOIN pg_catalog.pg_roles pr ON pr.oid = m.roleid
         WHERE m.member = _role_oid
      LOOP
        EXECUTE format('REVOKE %I FROM %I', _grantor, _role);
      END LOOP;
    END IF;

    _new_meta := _old_meta || jsonb_build_object(
      'provisioning_stage','revoked','credential_state','revoked',
      'login_enabled',false,'tenant_access_active',false,
      'session_pooler_verified',false,'session_user_verified',false,
      'fail_closed_pre_activation_verified',false
    );

    UPDATE pbi_reporting_security.tenant_login_map
       SET state='revoked', revoked_at=now(), disabled_at=NULL,
           last_verified_at=NULL, operational_metadata=_new_meta,
           actor_identity=_actor_user_id::text, actor_type='tenant_admin_action',
           updated_at=now()
     WHERE login_role_name=_role;

    INSERT INTO pbi_reporting_security.tenant_login_audit(
      event_type, login_role_name, tenant_id, actor_identity, actor_type, context, event_at
    ) VALUES (
      'revoked', _role, _tenant_id, _actor_user_id::text, 'tenant_admin_action',
      jsonb_build_object(
        'action','revoke','mapping_state','revoked','credential_state','revoked',
        'login_enabled',false,
        'security_drift_detected', _security_drift,
        'terminated_session_count', _terminated
      ),
      now()
    );

    -- Postflight — mapping revoked + role (if exists) NOLOGIN + zero direct memberships.
    SELECT r.oid, r.rolcanlogin INTO _role_oid, _pf_login
      FROM pg_catalog.pg_roles r WHERE r.rolname=_role;
    IF FOUND THEN
      SELECT COALESCE(array_agg(pr.rolname), ARRAY[]::text[]) INTO _pf_memberships
        FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles pr ON pr.oid=m.roleid
       WHERE m.member=_role_oid;
      IF _pf_login = true OR array_length(_pf_memberships,1) IS NOT NULL THEN
        RAISE EXCEPTION 'postflight_revoke_failed' USING ERRCODE = '42501';
      END IF;
    END IF;
    SELECT m.state::text, m.operational_metadata->>'credential_state',
           (m.operational_metadata->>'tenant_access_active')::boolean, m.last_verified_at
      INTO _pf_state, _pf_credstate, _pf_tenant_active, _pf_last_verified
      FROM pbi_reporting_security.tenant_login_map m WHERE m.login_role_name=_role;
    IF NOT (_pf_state='revoked' AND _pf_credstate='revoked'
            AND _pf_tenant_active=false AND _pf_last_verified IS NULL) THEN
      RAISE EXCEPTION 'postflight_revoke_failed' USING ERRCODE = '42501';
    END IF;

    RETURN jsonb_build_object(
      'action','revoke','tenant_id',_tenant_id,'login_role_name',_role,
      'mapping_state','revoked','credential_state','revoked',
      'password_display_once',false,
      'security_drift_detected', _security_drift,
      'terminated_session_count', _terminated
    );
  END IF;

  RAISE EXCEPTION 'unhandled_action' USING ERRCODE = '42501';
END $_$;


--
-- Name: service_register_tenant_storage_object(uuid, uuid, text, text, text, text, uuid, uuid, text, bigint, text, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_register_tenant_storage_object(_tenant_id uuid, _organization_id uuid, _bucket text, _surface text, _object_type text, _file_name text, _workspace_id uuid DEFAULT NULL::uuid, _object_id uuid DEFAULT NULL::uuid, _content_type text DEFAULT NULL::text, _size_bytes bigint DEFAULT NULL::bigint, _checksum text DEFAULT NULL::text, _metadata jsonb DEFAULT '{}'::jsonb, _legacy_object_path text DEFAULT NULL::text, _created_by uuid DEFAULT NULL::uuid) RETURNS public.tenant_storage_objects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.tenant_storage_objects;
  _path text;
  _bucket_seg text;
BEGIN
  IF _tenant_id IS NULL OR _organization_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id and organization_id are required';
  END IF;

  _bucket_seg := public._sanitize_storage_segment(_bucket);
  IF _bucket_seg IS NULL THEN RAISE EXCEPTION 'bucket is required'; END IF;

  IF _created_by IS NOT NULL THEN
    IF NOT public.is_tenant_member(_tenant_id, _created_by) THEN
      RAISE EXCEPTION 'created_by user is not an active tenant member';
    END IF;
    IF NOT public.is_organization_member(_organization_id, _created_by) THEN
      RAISE EXCEPTION 'created_by user is not an active organization member';
    END IF;
    IF _workspace_id IS NOT NULL
       AND NOT public.is_workspace_member(_created_by, _workspace_id) THEN
      RAISE EXCEPTION 'created_by user is not an active workspace member';
    END IF;
  END IF;

  _path := public.build_tenant_storage_path(
    _tenant_id, _organization_id, _workspace_id, _surface, _object_type, _object_id, _file_name
  );

  INSERT INTO public.tenant_storage_objects (
    tenant_id, organization_id, workspace_id, bucket, object_path, legacy_object_path,
    surface, object_type, object_id, file_name, content_type, size_bytes, checksum,
    storage_status, created_by, updated_by, metadata
  ) VALUES (
    _tenant_id, _organization_id, _workspace_id, _bucket_seg, _path, _legacy_object_path,
    _surface, _object_type, _object_id, _file_name, _content_type, _size_bytes, _checksum,
    'pending', _created_by, _created_by, COALESCE(_metadata, '{}'::jsonb)
  )
  ON CONFLICT (bucket, object_path) DO UPDATE
     SET updated_by = COALESCE(_created_by, public.tenant_storage_objects.updated_by),
         updated_at = now(),
         metadata = COALESCE(EXCLUDED.metadata, public.tenant_storage_objects.metadata)
  RETURNING * INTO _row;
  RETURN _row;
END $$;


--
-- Name: set_comment_edited(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_comment_edited() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.body IS DISTINCT FROM NEW.body THEN
    NEW.is_edited := true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_current_governance_record_brief_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_governance_record_brief_version(_brief_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _v public.governance_record_brief_versions%ROWTYPE;
  _row public.governance_records%ROWTYPE;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _v FROM public.governance_record_brief_versions WHERE id = _brief_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Brief version not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _v.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Brief versions are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;

  UPDATE public.governance_record_brief_versions
    SET is_current = false, updated_by = v_caller, updated_at = now()
    WHERE governance_record_id = _v.governance_record_id AND is_current = true AND id <> _brief_version_id;

  UPDATE public.governance_record_brief_versions
    SET is_current = true, updated_by = v_caller, updated_at = now()
    WHERE id = _brief_version_id;

  PERFORM public.log_activity_event(_row.organization_id, v_caller,
    'governance_record_brief_version_set_current', 'governance_record', _v.governance_record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'brief_version_id', _brief_version_id,
                       'version_number', _v.version_number),
    _row.workspace_id);
END; $$;


--
-- Name: set_current_governance_record_copilot_data_package(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_governance_record_copilot_data_package(_package_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
  v_caller uuid;
  _p public.governance_record_copilot_data_packages%ROWTYPE;
  _row public.governance_records%ROWTYPE;
  _sp_id uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _p FROM public.governance_record_copilot_data_packages WHERE id = _package_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data package not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO _row FROM public.governance_records WHERE id = _p.governance_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent record not found' USING ERRCODE='P0002'; END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Data packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;

  FOREACH _sp_id IN ARRAY _p.source_project_ids LOOP
    IF NOT public.has_project_access(v_caller, _sp_id) THEN
      RAISE EXCEPTION 'You do not have access to source project %', _sp_id USING ERRCODE='42501';
    END IF;
  END LOOP;

  UPDATE public.governance_record_copilot_data_packages
    SET is_current = false, package_status = CASE WHEN package_status = 'prepared' THEN 'superseded' ELSE package_status END
    WHERE governance_record_id = _p.governance_record_id AND is_current = true AND id <> _package_id;

  UPDATE public.governance_record_copilot_data_packages
    SET is_current = true
    WHERE id = _package_id;

  PERFORM public.log_activity_event(_row.organization_id, v_caller,
    'governance_record_copilot_data_package_set_current', 'governance_record', _p.governance_record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'data_package_id', _package_id,
                       'version_number', _p.version_number),
    _row.workspace_id);
END; $$;


--
-- Name: set_current_governance_record_stakeholder_package(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_governance_record_stakeholder_package(_package_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_client_id text;
