--
-- Name: set_roadmap_story_run_response_id(uuid, text, integer, integer, integer, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_roadmap_story_run_response_id(_run_id uuid, _openai_response_id text, _files_selected_count integer DEFAULT 0, _files_sent_count integer DEFAULT 0, _files_skipped_count integer DEFAULT 0, _total_bytes_sent bigint DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
