$$;


--
-- Name: set_task_assignee(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_task_assignee(_task_id uuid, _assignee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  _task public.tasks%ROWTYPE;
  _old_assignee uuid;
  _actor uuid := auth.uid();
BEGIN
  IF _actor IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_active_user(_actor) THEN RAISE EXCEPTION 'Account is deactivated'; END IF;

  SELECT * INTO _task FROM public.tasks WHERE id = _task_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;
  IF NOT public.has_project_access(_actor, _task.project_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT assignee_id INTO _old_assignee
  FROM public.task_assignments
  WHERE task_id = _task_id
  ORDER BY created_at DESC
  LIMIT 1;

  DELETE FROM public.task_assignments WHERE task_id = _task_id;

  IF _assignee_id IS NOT NULL THEN
    INSERT INTO public.task_assignments (task_id, assignee_id, assigned_by, workspace_id, organization_id)
    VALUES (_task_id, _assignee_id, _actor, _task.workspace_id, _task.organization_id);
  END IF;

  IF _old_assignee IS DISTINCT FROM _assignee_id THEN
    BEGIN
      PERFORM public.log_activity_event(
        _organization_id => _task.organization_id,
        _actor_id        => _actor,
        _event_type      => 'task_assignee_changed',
        _target_type     => 'task',
        _target_id       => _task_id,
        _metadata        => jsonb_build_object(
          'task_name', _task.name,
          'project_id', _task.project_id,
          'phase_id', _task.phase_id,
          'old_assignee_id', _old_assignee,
          'new_assignee_id', _assignee_id
        ),
        _workspace_id    => _task.workspace_id
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'task_id', _task_id,
    'old_assignee_id', _old_assignee,
    'new_assignee_id', _assignee_id
  );
END; $$;


--
-- Name: start_roadmap_story_generation_run(uuid, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_roadmap_story_generation_run(_story_pack_id uuid, _provider text, _model text, _reasoning_effort text, _input_manifest jsonb, _prompt_summary text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _run_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'This Story Pack is archived. Unarchive it before generating.' USING ERRCODE = '42501';
  END IF;

  IF _reasoning_effort IS NOT NULL AND _reasoning_effort NOT IN ('low','medium','high') THEN
    RAISE EXCEPTION 'invalid reasoning_effort';
  END IF;

  INSERT INTO public.roadmap_story_ai_runs (
    story_pack_id, created_by, status, provider, model, reasoning_effort,
    feature_key, input_manifest, prompt_summary_encrypted, started_at
  )
  VALUES (
    _story_pack_id, _uid, 'pending', _provider, _model, _reasoning_effort,
    'roadmap_story',
    COALESCE(_input_manifest, '{}'::jsonb),
    CASE WHEN _prompt_summary IS NULL OR _prompt_summary = '' THEN NULL
         ELSE public.btpm_encrypt(_prompt_summary, _pack.organization_id) END,
    now()
  )
  RETURNING id INTO _run_id;

  RETURN _run_id;
END;
$$;


--
-- Name: start_roadmap_story_presentation_run(uuid, uuid, text, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_roadmap_story_presentation_run(_story_pack_id uuid, _story_pack_version_id uuid, _provider text, _model text, _reasoning_effort text, _input_manifest jsonb, _prompt text, _input_package_json text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _pack public.roadmap_story_packs;
  _version_pack_id uuid;
  _run_id uuid;
BEGIN
  IF _uid IS NULL OR NOT public.is_active_user(_uid) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _pack FROM public.roadmap_story_packs WHERE id = _story_pack_id;
  IF NOT FOUND OR _pack.created_by <> _uid THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _pack.status = 'archived' THEN
    RAISE EXCEPTION 'This Story Pack is archived.' USING ERRCODE = '42501';
  END IF;
  IF _reasoning_effort IS NOT NULL AND _reasoning_effort NOT IN ('low','medium','high') THEN
    RAISE EXCEPTION 'invalid reasoning_effort';
  END IF;

  -- Phase 6B.7b.1 — Version integrity guard: when a version id is provided,
  -- it must exist and belong to the same Story Pack.
  IF _story_pack_version_id IS NOT NULL THEN
    SELECT story_pack_id INTO _version_pack_id
      FROM public.roadmap_story_pack_versions
     WHERE id = _story_pack_version_id;
    IF NOT FOUND OR _version_pack_id <> _story_pack_id THEN
      RAISE EXCEPTION 'invalid_story_pack_version' USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.roadmap_story_pack_presentation_runs (
    story_pack_id, story_pack_version_id, created_by, status,
    provider, model, reasoning_effort, feature_key, input_manifest,
    prompt_encrypted, input_package_encrypted, started_at
  ) VALUES (
    _story_pack_id, _story_pack_version_id, _uid, 'pending',
    _provider, _model, _reasoning_effort, 'roadmap_story_presentation',
    COALESCE(_input_manifest, '{}'::jsonb),
    CASE WHEN _prompt IS NULL OR _prompt = '' THEN NULL
         ELSE public.btpm_encrypt(_prompt, _pack.organization_id) END,
    CASE WHEN _input_package_json IS NULL OR _input_package_json = '' THEN NULL
         ELSE public.btpm_encrypt(_input_package_json, _pack.organization_id) END,
    now()
  )
  RETURNING id INTO _run_id;
  RETURN _run_id;
END;
$$;


--
-- Name: start_tenant_scheduler_run(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_tenant_scheduler_run(_tenant_id uuid, _scheduler_name text, _metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.tenant_scheduler_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row public.tenant_scheduler_runs;
BEGIN
  IF _tenant_id IS NULL THEN RAISE EXCEPTION 'tenant_id is required'; END IF;
  INSERT INTO public.tenant_scheduler_runs (tenant_id, scheduler_name, status, metadata)
  VALUES (_tenant_id, _scheduler_name, 'running', COALESCE(_metadata, '{}'::jsonb))
  RETURNING * INTO _row;
  RETURN _row;
END $$;


--
-- Name: sync_kpi_current_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_kpi_current_value() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _latest_date DATE;
BEGIN
  -- Find the latest update_date for this definition
  SELECT MAX(update_date) INTO _latest_date
  FROM public.kpi_updates
  WHERE kpi_definition_id = NEW.kpi_definition_id;

  -- Only sync if this insert is the latest (or tied for latest)
  IF NEW.update_date >= _latest_date THEN
    UPDATE public.kpi_definitions
    SET current_value = NEW.value
    WHERE id = NEW.kpi_definition_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_sharepoint_org_site_projection(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_sharepoint_org_site_projection(_organization_id uuid, _site_web_url text, _site_id text, _site_label_or_name text, _validation_status text, _validation_code text, _validation_note text) RETURNS public.sharepoint_org_site_connections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.sharepoint_org_site_connections;
  v_row      public.sharepoint_org_site_connections;
  v_status   text;
BEGIN
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = _organization_id) THEN
    RAISE EXCEPTION 'organization_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF _site_web_url IS NULL OR length(btrim(_site_web_url)) = 0 THEN
    RAISE EXCEPTION 'site_web_url_required' USING ERRCODE = '22023';
  END IF;

  v_status := COALESCE(_validation_status, 'configured_unvalidated');
  IF v_status NOT IN ('configured_unvalidated','validated','invalid') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
  FROM public.sharepoint_org_site_connections
  WHERE organization_id = _organization_id
    AND connection_status <> 'disabled'
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    UPDATE public.sharepoint_org_site_connections
    SET site_web_url         = _site_web_url,
        site_id              = _site_id,
        site_label_or_name   = COALESCE(_site_label_or_name, site_label_or_name),
        managed_outside_btpm = true,
        connection_status    = v_status,
        last_validated_at    = CASE WHEN v_status IN ('validated','invalid') THEN now() ELSE last_validated_at END,
        last_validation_code = COALESCE(_validation_code, last_validation_code),
        last_validation_note = COALESCE(_validation_note, last_validation_note)
    WHERE id = v_existing.id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.sharepoint_org_site_connections (
      organization_id, site_web_url, site_id, site_label_or_name,
      managed_outside_btpm, connection_status,
      last_validated_at, last_validation_code, last_validation_note
    ) VALUES (
      _organization_id, _site_web_url, _site_id, _site_label_or_name,
      true, v_status,
      CASE WHEN v_status IN ('validated','invalid') THEN now() ELSE NULL END,
      _validation_code, _validation_note
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END
$$;


--
-- Name: sync_workflow_pm_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_workflow_pm_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _category workflow_state_category;
  _new_status pm_status;
BEGIN
  IF NEW.workflow_state_id IS NULL THEN RETURN NEW; END IF;

  SELECT category INTO _category FROM public.board_workflow_states WHERE id = NEW.workflow_state_id;
  IF _category IS NULL THEN RETURN NEW; END IF;

  CASE _category
    WHEN 'todo' THEN _new_status := 'planned';
    WHEN 'in_progress' THEN _new_status := 'active';
    WHEN 'in_review' THEN _new_status := 'active';
    WHEN 'done' THEN _new_status := 'completed';
  END CASE;

  IF NEW.status NOT IN ('on_hold', 'cancelled') THEN
    NEW.status := _new_status;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tenant_admin_assign_org_admin(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_assign_org_admin(_organization_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _tid uuid; _om public.organization_memberships%ROWTYPE; _tm_ok boolean; _prev text;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  SELECT EXISTS(SELECT 1 FROM public.tenant_memberships
    WHERE tenant_id=_tid AND user_id=_target_user_id AND status='active') INTO _tm_ok;
  IF NOT _tm_ok THEN RAISE EXCEPTION 'target_not_active_tenant_member' USING ERRCODE='42501'; END IF;
  SELECT * INTO _om FROM public.organization_memberships
   WHERE organization_id=_organization_id AND user_id=_target_user_id;
  IF NOT FOUND THEN
    INSERT INTO public.organization_memberships(tenant_id, organization_id, user_id, role, status, created_by, updated_by)
    VALUES (_tid, _organization_id, _target_user_id, 'org_admin', 'active', auth.uid(), auth.uid())
    RETURNING * INTO _om;
    PERFORM public._log_admin_authority('assign_org_admin',
      _tid, _organization_id, _target_user_id, NULL, NULL, 'org_admin', NULL, 'active', _reason, '{"created_membership":true}'::jsonb);
    RETURN _om.id;
  END IF;
  IF _om.status<>'active' THEN RAISE EXCEPTION 'target_membership_inactive' USING ERRCODE='42501'; END IF;
  _prev := _om.role::text;
  IF _om.role<>'org_admin' THEN
    UPDATE public.organization_memberships SET role='org_admin', updated_at=now(), updated_by=auth.uid() WHERE id=_om.id;
  END IF;
  PERFORM public._log_admin_authority('assign_org_admin',
    _tid, _organization_id, _target_user_id, NULL, _prev, 'org_admin', _om.status::text, _om.status::text, _reason, '{}'::jsonb);
  RETURN _om.id;
END;$$;


--
-- Name: tenant_admin_assign_tenant_admin(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_assign_tenant_admin(_tenant_id uuid, _target_user_id uuid, _reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row public.tenant_memberships%ROWTYPE; _prev text;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  SELECT * INTO _row FROM public.tenant_memberships
   WHERE tenant_id=_tenant_id AND user_id=_target_user_id;
  IF NOT FOUND OR _row.status<>'active' THEN
    RAISE EXCEPTION 'target_not_active_tenant_member' USING ERRCODE='42501';
  END IF;
  IF _row.role='tenant_owner' THEN
    PERFORM public._log_admin_authority('blocked_protected_tenant_admin_change',
      _tenant_id, NULL, _target_user_id, NULL, _row.role::text, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
    RAISE EXCEPTION 'protected_tenant_admin' USING ERRCODE='42501';
  END IF;
  _prev := _row.role::text;
  IF _row.role<>'tenant_admin' THEN
    UPDATE public.tenant_memberships SET role='tenant_admin', updated_at=now(), updated_by=auth.uid() WHERE id=_row.id;
  END IF;
  PERFORM public._log_admin_authority('assign_tenant_admin',
    _tenant_id, NULL, _target_user_id, NULL, _prev, 'tenant_admin', _row.status::text, _row.status::text, _reason, '{}'::jsonb);
  RETURN _row.id;
END;$$;


--
-- Name: tenant_admin_disable_integration_secret(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_disable_integration_secret(_integration_id uuid, _secret_name text, _organization_id uuid DEFAULT NULL::uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _integ public.tenant_integrations;
  _ref_id uuid;
  _row public.tenant_secret_refs;
BEGIN
  IF _integration_id IS NULL OR _secret_name IS NULL THEN
    RAISE EXCEPTION 'integration_id and secret_name are required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN
    RAISE EXCEPTION 'Integration % not found', _integration_id USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_tenant_admin(_integ.tenant_id, auth.uid()) THEN
    RAISE EXCEPTION 'Only Tenant Admin may disable integration secrets for tenant %', _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  IF NOT public._is_allowed_tenant_integration_secret_name(_integ.kind, _secret_name) THEN
    RAISE EXCEPTION 'Secret name % is not allowed for integration kind %', _secret_name, _integ.kind::text
      USING ERRCODE = '22023';
  END IF;

  IF _organization_id IS NULL THEN
    SELECT id INTO _ref_id
      FROM public.tenant_secret_refs
     WHERE integration_id = _integ.id
       AND secret_name = _secret_name
       AND secret_scope = 'tenant'
     LIMIT 1;

    IF _ref_id IS NULL THEN
      RAISE EXCEPTION 'Secret % not configured for this scope', _secret_name USING ERRCODE = '42704';
    END IF;

    _row := public.admin_disable_tenant_secret(_ref_id, false, _reason);

    RETURN jsonb_build_object(
      'integration_id',  _row.integration_id,
      'organization_id', _row.organization_id,
      'secret_name',     _row.secret_name,
      'secret_scope',    _row.secret_scope,
      'status',          _row.status,
      'disabled_at',     _row.disabled_at
    );
  END IF;

  -- Organization override path.
  IF NOT EXISTS (
    SELECT 1 FROM public.organizations
     WHERE id = _organization_id AND tenant_id = _integ.tenant_id
  ) THEN
    RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  SELECT id INTO _ref_id
    FROM public.tenant_secret_refs
   WHERE integration_id = _integ.id
     AND secret_name = _secret_name
     AND secret_scope = 'organization_override'
     AND organization_id = _organization_id
   LIMIT 1;

  IF _ref_id IS NOT NULL THEN
    _row := public.admin_disable_tenant_secret(_ref_id, false, _reason);
  END IF;

  -- Upsert override row as disabled so the resolver blocks fallback.
  INSERT INTO public.organization_secret_overrides (
    tenant_id, organization_id, integration_id, secret_name,
    secret_ref_id, is_disabled, override_reason, created_by, updated_by
  ) VALUES (
    _integ.tenant_id, _organization_id, _integ.id, _secret_name,
    _ref_id, true, _reason, auth.uid(), auth.uid()
  )
  ON CONFLICT (organization_id, integration_id, secret_name)
  WHERE secret_name IS NOT NULL
  DO UPDATE SET
    secret_ref_id   = COALESCE(EXCLUDED.secret_ref_id, public.organization_secret_overrides.secret_ref_id),
    is_disabled     = true,
    override_reason = EXCLUDED.override_reason,
    updated_by      = auth.uid(),
    updated_at      = now();

  IF _ref_id IS NULL THEN
    -- No existing secret ref, but override is marked disabled -> resolver blocks.
    RETURN jsonb_build_object(
      'integration_id',  _integ.id,
      'organization_id', _organization_id,
      'secret_name',     _secret_name,
      'secret_scope',    'organization_override',
      'status',          'disabled',
      'disabled_at',     now()
    );
  END IF;

  RETURN jsonb_build_object(
    'integration_id',  _row.integration_id,
    'organization_id', _row.organization_id,
    'secret_name',     _row.secret_name,
    'secret_scope',    _row.secret_scope,
    'status',          _row.status,
    'disabled_at',     _row.disabled_at
  );
END $$;


--
-- Name: tenant_admin_get_ai_provider_setting(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_ai_provider_setting(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active text;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);

  SELECT s.active_provider INTO v_active
    FROM public.tenant_ai_provider_settings s
   WHERE s.tenant_id = _tenant_id;

  RETURN jsonb_build_object(
    'tenant_id', _tenant_id,
    'active_provider', v_active,
    'providers', jsonb_build_array(
      public._tenant_ai_provider_readiness(_tenant_id, 'openai'),
      public._tenant_ai_provider_readiness(_tenant_id, 'azure_openai')
    )
  );
END $$;


--
-- Name: tenant_admin_get_azure_openai_deployments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_azure_openai_deployments(_integration_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ti public.tenant_integrations;
  v_meta jsonb;
  v_deps jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_configured int := 0;
  v_required int := 0;
  v_key text;
  v_label text;
  v_usage text;
  v_dep text;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF v_ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;
  IF v_ti.kind::text <> 'azure_openai' OR v_ti.name <> 'default' THEN
    RAISE EXCEPTION 'integration is not azure_openai default' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(v_ti.tenant_id);

  v_meta := COALESCE(v_ti.config_metadata, '{}'::jsonb);
  IF jsonb_typeof(v_meta) = 'object'
     AND (v_meta ? 'azure_deployments')
     AND jsonb_typeof(v_meta -> 'azure_deployments') = 'object' THEN
    v_deps := v_meta -> 'azure_deployments';
  ELSE
    v_deps := '{}'::jsonb;
  END IF;

  -- Text models from active registry.
  FOR v_key, v_label IN
    SELECT model_id, display_name
    FROM public.ai_model_registry
    WHERE provider = 'openai' AND active = true
    ORDER BY sort_order, model_id
  LOOP
    v_required := v_required + 1;
    v_dep := NULL;
    IF (v_deps ? v_key)
       AND jsonb_typeof(v_deps -> v_key) = 'string'
       AND btrim(v_deps ->> v_key) <> '' THEN
      v_dep := v_deps ->> v_key;
      v_configured := v_configured + 1;
    END IF;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'model_key', v_key,
      'display_label', v_label,
      'usage', 'text',
      'deployment_name', v_dep
    ));
  END LOOP;

  -- Fixed embedding entry.
  v_key := 'text-embedding-3-small';
  v_required := v_required + 1;
  v_dep := NULL;
  IF (v_deps ? v_key)
     AND jsonb_typeof(v_deps -> v_key) = 'string'
     AND btrim(v_deps ->> v_key) <> '' THEN
    v_dep := v_deps ->> v_key;
    v_configured := v_configured + 1;
  END IF;
  v_rows := v_rows || jsonb_build_array(jsonb_build_object(
    'model_key', v_key,
    'display_label', 'Text embedding 3 small',
    'usage', 'embedding',
    'deployment_name', v_dep
  ));

  RETURN jsonb_build_object(
    'integration_id', v_ti.id,
    'mappings', v_rows,
    'required_count', v_required,
    'configured_count', v_configured,
    'complete', (v_configured = v_required)
  );
END $$;


--
-- Name: tenant_admin_get_azure_openai_endpoint(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_azure_openai_endpoint(_integration_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _ti public.tenant_integrations;
  _endpoint text;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF _ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;
  IF _ti.kind::text <> 'azure_openai' THEN
    RAISE EXCEPTION 'integration is not azure_openai' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(_ti.tenant_id);

  IF jsonb_typeof(COALESCE(_ti.config_metadata, '{}'::jsonb)) = 'object'
     AND (_ti.config_metadata ? 'endpoint')
     AND jsonb_typeof(_ti.config_metadata -> 'endpoint') = 'string' THEN
    _endpoint := _ti.config_metadata ->> 'endpoint';
    IF btrim(_endpoint) = '' THEN _endpoint := NULL; END IF;
  ELSE
    _endpoint := NULL;
  END IF;

  RETURN jsonb_build_object(
    'integration_id', _ti.id,
    'endpoint', _endpoint,
    'endpoint_configured', (_endpoint IS NOT NULL)
  );
END $$;


--
-- Name: tenant_admin_get_encryption_posture(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_encryption_posture(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _tenant jsonb;
  _orgs   jsonb;
  _v1     jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_id_required';
  END IF;
  IF NOT public.is_tenant_admin(_tenant_id, _caller) THEN
    RAISE EXCEPTION 'not_tenant_admin_for_tenant';
  END IF;

  SELECT to_jsonb(tep) INTO _tenant
    FROM public.tenant_encryption_posture tep
   WHERE tep.tenant_id = _tenant_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(oep) ORDER BY oep.environment_role, oep.organization_name), '[]'::jsonb)
    INTO _orgs
    FROM public.organization_encryption_posture oep
   WHERE oep.tenant_id = _tenant_id;

  _v1 := public.resolve_tenant_encryption_v1_metadata(_tenant_id);

  RETURN jsonb_build_object(
    'tenant', COALESCE(_tenant, jsonb_build_object('tenant_id', _tenant_id, 'tenant_key_status', 'missing_metadata')),
    'organizations', _orgs,
    'tenant_key_v1', _v1
  );
END;
$$;


--
-- Name: tenant_admin_get_integration_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_integration_detail(_integration_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _ti public.tenant_integrations;
  _secrets jsonb;
  _matrix jsonb;
  _key_count int;
BEGIN
  IF _integration_id IS NULL THEN
    RAISE EXCEPTION 'integration_id is required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _ti FROM public.tenant_integrations WHERE id = _integration_id;
  IF _ti.id IS NULL THEN
    RAISE EXCEPTION 'integration not found' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(_ti.tenant_id);

  SELECT COALESCE(jsonb_agg(row_to_json(s) ORDER BY s.secret_scope, s.secret_name), '[]'::jsonb) INTO _secrets
  FROM (
    SELECT
      r.id AS secret_ref_id,
      r.secret_name,
      r.secret_kind,
      r.secret_scope::text AS secret_scope,
      r.status::text AS status,
      r.organization_id,
      o.name AS organization_name,
      r.updated_at,
      r.rotated_at,
      r.disabled_at,
      r.revoked_at
    FROM public.tenant_secret_refs r
    LEFT JOIN public.organizations o ON o.id = r.organization_id
    WHERE r.integration_id = _ti.id
  ) s;

  SELECT COALESCE(jsonb_agg(row_to_json(m) ORDER BY m.organization_name), '[]'::jsonb) INTO _matrix
  FROM (
    SELECT
      o.id AS organization_id,
      o.name AS organization_name,
      o.slug AS organization_slug,
      o.organization_kind::text AS organization_kind,
      o.environment_role::text AS environment_role,
      (o.environment_role = 'production') AS is_production,
      (SELECT COUNT(*)::int FROM public.organization_secret_overrides oso
         WHERE oso.integration_id = _ti.id AND oso.organization_id = o.id) AS override_count,
      (SELECT COUNT(*)::int FROM public.organization_secret_overrides oso
         WHERE oso.integration_id = _ti.id AND oso.organization_id = o.id AND oso.is_disabled = true) AS disabled_override_count,
      CASE
        WHEN EXISTS (SELECT 1 FROM public.organization_secret_overrides oso
                     WHERE oso.integration_id = _ti.id AND oso.organization_id = o.id AND oso.is_disabled = true)
          THEN 'disabled'
        WHEN EXISTS (SELECT 1 FROM public.organization_secret_overrides oso
                     WHERE oso.integration_id = _ti.id AND oso.organization_id = o.id AND oso.is_disabled = false)
          THEN 'organization_override'
        WHEN EXISTS (SELECT 1 FROM public.tenant_secret_refs r
                     WHERE r.integration_id = _ti.id AND r.secret_scope = 'tenant' AND r.status = 'active')
          THEN 'tenant_default'
        ELSE 'missing'
      END AS effective_source
    FROM public.organizations o
    WHERE o.tenant_id = _ti.tenant_id
  ) m;

  _key_count := CASE
    WHEN jsonb_typeof(COALESCE(_ti.config_metadata, '{}'::jsonb)) = 'object'
      THEN (SELECT COUNT(*)::int FROM jsonb_object_keys(COALESCE(_ti.config_metadata, '{}'::jsonb)))
    ELSE 0
  END;

  RETURN jsonb_build_object(
    'integration', jsonb_build_object(
      'id', _ti.id,
      'tenant_id', _ti.tenant_id,
      'kind', _ti.kind::text,
      'name', _ti.name,
      'status', _ti.status::text,
      'is_enabled', _ti.is_enabled,
      'has_config_metadata', (_key_count > 0),
      'config_metadata_key_count', _key_count,
      'last_tested_at', _ti.last_tested_at,
      'last_success_at', _ti.last_success_at,
      'last_error_at', _ti.last_error_at,
      'last_error_message', _ti.last_error_message,
      'created_at', _ti.created_at,
      'updated_at', _ti.updated_at,
      'tenant_active_secret_count',
        (SELECT COUNT(*)::int FROM public.tenant_secret_refs r
          WHERE r.integration_id = _ti.id AND r.secret_scope = 'tenant' AND r.status = 'active')
    ),
    'secrets', _secrets,
    'organization_matrix', _matrix
  );
END $$;


--
-- Name: tenant_admin_get_operations_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_operations_summary(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _exports jsonb;
  _imports jsonb;
  _jobs jsonb;
  _scheduler jsonb;
  _storage_total bigint;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _exports
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_export_packages
        WHERE tenant_id = _tenant_id GROUP BY status) e;

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _imports
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_import_temp_objects
        WHERE tenant_id = _tenant_id GROUP BY status) i;

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _jobs
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_background_jobs
        WHERE tenant_id = _tenant_id GROUP BY status) j;

  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO _scheduler
  FROM (SELECT status, COUNT(*) AS cnt FROM public.tenant_scheduler_runs
        WHERE tenant_id = _tenant_id GROUP BY status) s;

  SELECT COUNT(*) INTO _storage_total FROM public.tenant_storage_objects
   WHERE tenant_id = _tenant_id AND deleted_at IS NULL;

  RETURN jsonb_build_object(
    'storage_object_count', _storage_total,
    'export_packages_by_status', _exports,
    'import_temp_by_status', _imports,
    'background_jobs_by_status', _jobs,
    'scheduler_runs_by_status', _scheduler,
    'generated_at', now()
  );
END;
$$;


--
-- Name: tenant_admin_get_organization_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_organization_detail(_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _o public.organizations;
  _tenant_name text;
  _default_org_id uuid;
  _is_prod boolean;
  _workspace_count int;
  _org_admin_count int;
  _integrations jsonb;
BEGIN
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO _o FROM public.organizations WHERE id = _organization_id;
  IF _o.id IS NULL THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_tenant_admin_caller(_o.tenant_id);

  SELECT name, default_organization_id INTO _tenant_name, _default_org_id
    FROM public.tenants WHERE id = _o.tenant_id;

  _is_prod := (_o.environment_role = 'production');

  SELECT COUNT(*)::int INTO _workspace_count
    FROM public.workspaces w
   WHERE w.organization_id = _o.id AND w.is_archived = false;

  -- 4D.10A.1 fix: correct enum value is `org_admin`, not `organization_admin`.
  SELECT COUNT(*)::int INTO _org_admin_count
    FROM public.organization_memberships om
   WHERE om.organization_id = _o.id
     AND om.status = 'active'
     AND om.role = 'org_admin'::public.organization_role;

  SELECT COALESCE(jsonb_agg(row_to_json(x)), '[]'::jsonb) INTO _integrations
  FROM (
    SELECT
      ti.id AS integration_id,
      ti.kind::text AS kind,
      ti.name,
      ti.status::text AS status,
      ti.is_enabled,
      (SELECT COUNT(*)::int FROM public.tenant_secret_refs r
        WHERE r.integration_id = ti.id AND r.secret_scope = 'tenant' AND r.status = 'active') AS tenant_active_secret_count,
      (SELECT COUNT(*)::int FROM public.organization_secret_overrides oso
        WHERE oso.integration_id = ti.id AND oso.organization_id = _o.id) AS override_count,
      (SELECT COUNT(*)::int FROM public.organization_secret_overrides oso
        WHERE oso.integration_id = ti.id AND oso.organization_id = _o.id AND oso.is_disabled = true) AS disabled_override_count,
      (SELECT COUNT(*)::int FROM public.organization_secret_overrides oso
        WHERE oso.integration_id = ti.id AND oso.organization_id = _o.id AND oso.is_disabled = false) AS active_override_count
    FROM public.tenant_integrations ti
    WHERE ti.tenant_id = _o.tenant_id
    ORDER BY ti.kind::text, ti.name
  ) x;

  RETURN jsonb_build_object(
    'organization', jsonb_build_object(
      'id', _o.id,
      'tenant_id', _o.tenant_id,
      'tenant_name', _tenant_name,
      'name', _o.name,
      'slug', _o.slug,
      'organization_kind', _o.organization_kind::text,
      'environment_role', _o.environment_role::text,
      'is_default', (_o.id = _default_org_id),
      'created_at', _o.created_at,
      'updated_at', _o.updated_at
    ),
    'environment_safety', jsonb_build_object(
      'is_production', _is_prod,
      'outbound_email', _is_prod,
      'external_api_write', _is_prod,
      'real_integration', _is_prod,
      'export', true,
      'export_without_watermark', _is_prod,
      'storage_write', true,
      'background_job_enqueue', true
    ),
    'workspace_count', _workspace_count,
    'org_admin_count', _org_admin_count,
    'integrations', _integrations
  );
END $$;


--
-- Name: tenant_admin_get_organization_encryption_posture(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_organization_encryption_posture(_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _caller uuid := auth.uid();
  _tenant_id uuid;
  _row jsonb;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'authentication_required';
  END IF;
  IF _organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  SELECT o.tenant_id INTO _tenant_id
    FROM public.organizations o
   WHERE o.id = _organization_id;

  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'organization_not_found';
  END IF;

  IF NOT public.is_tenant_admin(_tenant_id, _caller) THEN
    RAISE EXCEPTION 'not_tenant_admin_for_tenant';
  END IF;

  SELECT to_jsonb(oep) INTO _row
    FROM public.organization_encryption_posture oep
   WHERE oep.organization_id = _organization_id;

  RETURN COALESCE(_row, jsonb_build_object(
    'organization_id', _organization_id,
    'tenant_id', _tenant_id,
    'key_status', 'missing_metadata'
  ));
END;
$$;


--
-- Name: tenant_admin_get_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_overview(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _t record;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);

  SELECT t.id, t.name, t.slug, t.status::text AS status, t.default_organization_id,
         def.name AS default_organization_name
    INTO _t
  FROM public.tenants t
  LEFT JOIN public.organizations def ON def.id = t.default_organization_id
  WHERE t.id = _tenant_id;

  RETURN jsonb_build_object(
    'tenant', jsonb_build_object(
      'id', _t.id,
      'name', _t.name,
      'slug', _t.slug,
      'status', _t.status,
      'default_organization_id', _t.default_organization_id,
      'default_organization_name', _t.default_organization_name
    ),
    'counts', jsonb_build_object(
      'organizations',        (SELECT COUNT(*) FROM public.organizations o WHERE o.tenant_id = _tenant_id),
      'active_members',       (SELECT COUNT(*) FROM public.tenant_memberships tm WHERE tm.tenant_id = _tenant_id AND tm.status = 'active'),
      'admins',               (SELECT COUNT(*) FROM public.tenant_memberships tm WHERE tm.tenant_id = _tenant_id AND tm.status = 'active' AND tm.role IN ('tenant_owner','tenant_admin')),
      'integrations',         (SELECT COUNT(*) FROM public.tenant_integrations ti WHERE ti.tenant_id = _tenant_id),
      'integrations_enabled', (SELECT COUNT(*) FROM public.tenant_integrations ti WHERE ti.tenant_id = _tenant_id AND ti.is_enabled = true),
      'storage_objects',      (SELECT COUNT(*) FROM public.tenant_storage_objects s WHERE s.tenant_id = _tenant_id AND s.deleted_at IS NULL),
      'export_packages',      (SELECT COUNT(*) FROM public.tenant_export_packages e WHERE e.tenant_id = _tenant_id),
      'jobs_queued',          (SELECT COUNT(*) FROM public.tenant_background_jobs j WHERE j.tenant_id = _tenant_id AND j.status = 'queued'),
      'jobs_running',         (SELECT COUNT(*) FROM public.tenant_background_jobs j WHERE j.tenant_id = _tenant_id AND j.status = 'running'),
      'jobs_failed',          (SELECT COUNT(*) FROM public.tenant_background_jobs j WHERE j.tenant_id = _tenant_id AND j.status = 'failed')
    ),
    'generated_at', now()
  );
END;
$$;


--
-- Name: tenant_admin_get_powerbi_reporting_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_get_powerbi_reporting_readiness(_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pbi_reporting_security', 'pbi_reporting'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _tenant record;
  _map record;
  _role text;
  _role_oid oid;
  _role_exists boolean := false;
  _login boolean := false;
  _conn_limit int := NULL;
  _rolsuper boolean;
  _rolcreatedb boolean;
  _rolcreaterole boolean;
  _rolreplication boolean;
  _rolbypassrls boolean;
  _rolinherit boolean;
  _memberships text[] := ARRAY[]::text[];
  _settings text[];
  _role_security_ok boolean := false;
  _membership_ok boolean := false;
  _session_defaults_ok boolean := false;
  _op jsonb := '{}'::jsonb;
  _last_verified_evt timestamptz;
  _session_pooler_verified boolean := false;
  _session_user_verified boolean := false;
  _fail_closed_verified boolean := false;
  _mapping_state text := NULL;
  _credential_state text := NULL;
  _orgs jsonb;
  _coverage jsonb;
  _readiness text;
  _latest_evt record;
  _has_search_path boolean := false;
  _has_readonly boolean := false;
  _has_stmt_timeout boolean := false;
  _has_idle_timeout boolean := false;
  _s text;
BEGIN
  IF _uid IS NULL OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.is_platform_super_admin(_uid) OR public.is_tenant_admin(_tenant_id, _uid)) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT id, name, slug, status::text AS status
    INTO _tenant
    FROM public.tenants
   WHERE id = _tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT login_role_name, state::text AS state,
         provisioned_at, last_rotated_at, last_verified_at,
         disabled_at, operational_metadata
    INTO _map
    FROM pbi_reporting_security.tenant_login_map
   WHERE tenant_id = _tenant_id
   ORDER BY provisioned_at DESC
   LIMIT 1;

  IF _map.login_role_name IS NOT NULL THEN
    _role := _map.login_role_name;
    _op := COALESCE(_map.operational_metadata, '{}'::jsonb);
    _mapping_state := _map.state;
    _credential_state := _op->>'credential_state';

    SELECT r.oid, true, r.rolcanlogin, r.rolconnlimit,
           r.rolsuper, r.rolcreatedb, r.rolcreaterole,
           r.rolreplication, r.rolbypassrls, r.rolinherit
      INTO _role_oid, _role_exists, _login, _conn_limit,
           _rolsuper, _rolcreatedb, _rolcreaterole,
           _rolreplication, _rolbypassrls, _rolinherit
      FROM pg_catalog.pg_roles r
     WHERE r.rolname = _role;

    IF _role_exists THEN
      _role_security_ok := COALESCE(_login,false)
                       AND _rolsuper = false
                       AND _rolcreatedb = false
                       AND _rolcreaterole = false
                       AND _rolreplication = false
                       AND _rolbypassrls = false
                       AND _rolinherit = true
                       AND _conn_limit = 8;

      SELECT COALESCE(array_agg(pr.rolname ORDER BY pr.rolname), ARRAY[]::text[])
        INTO _memberships
        FROM pg_catalog.pg_auth_members m
        JOIN pg_catalog.pg_roles pr ON pr.oid = m.roleid
       WHERE m.member = _role_oid;

      _membership_ok := (_memberships = ARRAY['btpm_pbi_reader']::text[]);

      SELECT s.setconfig INTO _settings
        FROM pg_catalog.pg_db_role_setting s
       WHERE s.setrole = _role_oid AND s.setdatabase = 0;

      IF _settings IS NOT NULL THEN
        FOREACH _s IN ARRAY _settings LOOP
          IF _s = 'search_path=pbi_reporting, pbi_reporting_security, pg_catalog' THEN
            _has_search_path := true;
          ELSIF _s = 'default_transaction_read_only=on' THEN
            _has_readonly := true;
          ELSIF _s = 'statement_timeout=5min' THEN
            _has_stmt_timeout := true;
          ELSIF _s = 'idle_in_transaction_session_timeout=1min' THEN
            _has_idle_timeout := true;
          END IF;
        END LOOP;
      END IF;
      _session_defaults_ok := _has_search_path AND _has_readonly
                          AND _has_stmt_timeout AND _has_idle_timeout;
    END IF;

    _session_pooler_verified := COALESCE((_op->>'session_pooler_verified')::boolean, false);
    _session_user_verified   := COALESCE((_op->>'session_user_verified')::boolean, false);
    _fail_closed_verified    := COALESCE((_op->>'fail_closed_pre_activation_verified')::boolean, false);

    SELECT event_type::text AS event_type, event_at
      INTO _latest_evt
      FROM pbi_reporting_security.tenant_login_audit
     WHERE tenant_id = _tenant_id
       AND login_role_name = _role
     ORDER BY event_at DESC
     LIMIT 1;

    IF _map.last_verified_at IS NULL THEN
      SELECT MAX(event_at) INTO _last_verified_evt
        FROM pbi_reporting_security.tenant_login_audit
       WHERE tenant_id = _tenant_id
         AND login_role_name = _role
         AND event_type = 'verified';
    END IF;
  END IF;

  WITH tenant_orgs AS (
    SELECT o.id, o.name, o.environment_role::text AS environment_role
      FROM public.organizations o
     WHERE o.tenant_id = _tenant_id
  ),
  ws_counts AS (
    SELECT w.organization_id, COUNT(*) AS total_ws
      FROM public.workspaces w
      JOIN tenant_orgs o ON o.id = w.organization_id
     WHERE NOT w.is_archived
     GROUP BY w.organization_id
  ),
  rules AS (
    SELECT r.organization_id, r.scope_mode
      FROM public.powerbi_data_scope_rules r
      JOIN tenant_orgs o ON o.id = r.organization_id
     WHERE r.scope_type = 'workspace'
  ),
  rule_counts AS (
    SELECT organization_id,
           COUNT(*) FILTER (WHERE scope_mode = 'included') AS included_ws,
           COUNT(*) FILTER (WHERE scope_mode = 'excluded') AS excluded_ws
      FROM rules
     GROUP BY organization_id
  ),
  projects_in_scope AS (
    SELECT sp.organization_id, COUNT(*)::int AS scoped_project_count
      FROM pbi_reporting._scope_projects sp
      JOIN tenant_orgs o ON o.id = sp.organization_id
     GROUP BY sp.organization_id
  )
  SELECT COALESCE(jsonb_agg(row_json ORDER BY (row_json->>'organization_name')), '[]'::jsonb)
    INTO _orgs
    FROM (
      SELECT jsonb_build_object(
               'organization_id', o.id,
               'organization_name', o.name,
               'environment_role', o.environment_role,
               'total_workspace_count', COALESCE(wc.total_ws, 0),
               'included_workspace_count', COALESCE(rc.included_ws, 0),
               'excluded_workspace_count', COALESCE(rc.excluded_ws, 0),
               'unconfigured_workspace_count',
                 GREATEST(COALESCE(wc.total_ws,0) - COALESCE(rc.included_ws,0) - COALESCE(rc.excluded_ws,0), 0),
               'scoped_project_count', COALESCE(ps.scoped_project_count, 0),
               'scope_configured', (COALESCE(rc.included_ws,0) + COALESCE(rc.excluded_ws,0)) > 0
             ) AS row_json
        FROM tenant_orgs o
        LEFT JOIN ws_counts wc ON wc.organization_id = o.id
        LEFT JOIN rule_counts rc ON rc.organization_id = o.id
        LEFT JOIN projects_in_scope ps ON ps.organization_id = o.id
    ) s;

  _coverage := jsonb_build_object(
    'organization_count', jsonb_array_length(_orgs),
    'organizations_with_reporting_scope',
      (SELECT COUNT(*) FROM jsonb_array_elements(_orgs) x WHERE (x->>'scope_configured')::boolean),
    'included_workspace_count',
      COALESCE((SELECT SUM((x->>'included_workspace_count')::int) FROM jsonb_array_elements(_orgs) x), 0),
    'excluded_workspace_count',
      COALESCE((SELECT SUM((x->>'excluded_workspace_count')::int) FROM jsonb_array_elements(_orgs) x), 0),
    'scoped_project_count',
      COALESCE((SELECT SUM((x->>'scoped_project_count')::int) FROM jsonb_array_elements(_orgs) x), 0)
  );

  -- Adjusted status ordering
  IF _map.login_role_name IS NULL THEN
    _readiness := 'not_provisioned';
  ELSIF _mapping_state = 'revoked' THEN
    _readiness := 'revoked';
  ELSIF _mapping_state = 'disabled' AND _credential_state = 'pending_activation' THEN
    _readiness := 'attention_required';
  ELSIF _mapping_state = 'disabled' AND _credential_state = 'disabled' THEN
    _readiness := 'disabled';
  ELSIF _mapping_state = 'disabled' THEN
    _readiness := 'disabled';
  ELSIF _mapping_state = 'active'
        AND _role_exists
        AND COALESCE(_login,false)
        AND _role_security_ok
        AND _membership_ok
        AND _session_defaults_ok
        AND _session_pooler_verified
        AND _session_user_verified
        AND _fail_closed_verified
        AND COALESCE(_map.last_verified_at, _last_verified_evt) IS NOT NULL
        AND (_coverage->>'included_workspace_count')::int > 0 THEN
    _readiness := 'ready';
  ELSE
    _readiness := 'attention_required';
  END IF;

  RETURN jsonb_build_object(
    'tenant', jsonb_build_object(
      'id', _tenant.id,
      'name', _tenant.name,
      'slug', _tenant.slug,
      'status', _tenant.status
    ),
    'readiness_status', _readiness,
    'identity', jsonb_build_object(
      'login_role_name', _map.login_role_name,
      'mapping_state', _mapping_state,
      'role_exists', _role_exists,
      'login_enabled', COALESCE(_login, false),
      'connection_limit', _conn_limit,
      'role_security_attributes_valid', _role_security_ok,
      'membership_valid', _membership_ok,
      'session_defaults_valid', _session_defaults_ok,
      'session_pooler_verified', _session_pooler_verified,
      'session_user_verified', _session_user_verified,
      'fail_closed_verified', _fail_closed_verified,
      'provisioned_at', _map.provisioned_at,
      'last_rotated_at', _map.last_rotated_at,
      'last_verified_at', COALESCE(_map.last_verified_at, _last_verified_evt),
      'credential_state', _credential_state
    ),
    'connection_guidance', jsonb_build_object(
      'host_hint', 'Obtain from Supabase → Connect (Session Pooler)',
      'connection_method', 'Supabase Session Pooler',
      'port', 5432,
      'database', 'postgres',
      'connectivity_mode', 'Import',
      'notes', 'Use the Tenant-specific reporting login shown above with the Supabase Session Pooler. The password is provisioned outside BTPM and is never displayed here.'
    ),
    'latest_safe_event', jsonb_build_object(
      'event_type', _latest_evt.event_type,
      'event_at',   _latest_evt.event_at
    ),
    'coverage_summary', _coverage,
    'organizations', _orgs
  );
END $$;


--
-- Name: tenant_admin_list_integration_secret_metadata(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_integration_secret_metadata(_integration_id uuid, _organization_id uuid DEFAULT NULL::uuid) RETURNS TABLE(integration_id uuid, organization_id uuid, organization_name text, secret_name text, secret_kind text, secret_scope text, status text, rotated_at timestamp with time zone, disabled_at timestamp with time zone, revoked_at timestamp with time zone, updated_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _integ public.tenant_integrations;
BEGIN
  SELECT * INTO _integ FROM public.tenant_integrations WHERE id = _integration_id;
  IF _integ.id IS NULL THEN
    RAISE EXCEPTION 'Integration % not found', _integration_id USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_tenant_admin(_integ.tenant_id, auth.uid()) THEN
    RAISE EXCEPTION 'Only Tenant Admin may read integration secret metadata for tenant %', _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  IF _organization_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.organizations
     WHERE id = _organization_id AND tenant_id = _integ.tenant_id
  ) THEN
    RAISE EXCEPTION 'Organization % does not belong to tenant %', _organization_id, _integ.tenant_id
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT r.integration_id, r.organization_id, o.name AS organization_name,
           r.secret_name, r.secret_kind,
           r.secret_scope::text, r.status::text,
           r.rotated_at, r.disabled_at, r.revoked_at, r.updated_at, r.created_at
      FROM public.tenant_secret_refs r
      LEFT JOIN public.organizations o ON o.id = r.organization_id
     WHERE r.integration_id = _integ.id
       AND (
         _organization_id IS NULL
         OR (r.secret_scope = 'organization_override' AND r.organization_id = _organization_id)
         OR (r.secret_scope = 'tenant')
       )
     ORDER BY r.secret_scope::text, r.secret_name, o.name NULLS FIRST;
END $$;


--
-- Name: tenant_admin_list_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_members(_tenant_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, display_name text, email text, role text, status text, created_at timestamp with time zone, deactivated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  RETURN QUERY
  -- Actual tenant memberships
  SELECT
    tm.id                                                   AS membership_id,
    tm.user_id                                              AS user_id,
    CASE WHEN p.organization_id IS NOT NULL
         THEN public.btpm_decrypt(p.display_name, p.organization_id)
         ELSE p.display_name END                            AS display_name,
    p.email                                                 AS email,
    tm.role::text                                           AS role,
    tm.status::text                                         AS status,
    tm.created_at                                           AS created_at,
    tm.deactivated_at                                       AS deactivated_at
  FROM public.tenant_memberships tm
  LEFT JOIN public.profiles p ON p.id = tm.user_id
  WHERE tm.tenant_id = _tenant_id

  UNION ALL

  -- Pending invitations that target this tenant (not yet accepted / not expired /
  -- not revoked) and whose email is not already an active tenant member.
  SELECT
    i.id                                                    AS membership_id,
    NULL::uuid                                              AS user_id,
    NULL::text                                              AS display_name,
    i.email                                                 AS email,
    COALESCE(i.tenant_role::text, 'tenant_member')          AS role,
    'pending'::text                                         AS status,
    i.created_at                                            AS created_at,
    NULL::timestamptz                                       AS deactivated_at
  FROM public.invitations i
  WHERE i.tenant_id = _tenant_id
    AND i.status = 'pending'
    AND i.expires_at > now()
    AND NOT EXISTS (
      SELECT 1
      FROM public.tenant_memberships tm2
      JOIN public.profiles p2 ON p2.id = tm2.user_id
      WHERE tm2.tenant_id = _tenant_id
        AND tm2.status = 'active'
        AND lower(p2.email) = lower(i.email)
    )
  ORDER BY 6 DESC, 5, 4 NULLS LAST;  -- status desc (active/pending), role, email
END;
$$;


--
-- Name: tenant_admin_list_org_admin_candidates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_org_admin_candidates(_organization_id uuid, _query text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, email text, is_org_member boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _tid uuid;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  RETURN QUERY
  SELECT tm.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END AS dn,
         p.email,
         EXISTS (
           SELECT 1 FROM public.organization_memberships om
           WHERE om.organization_id=_organization_id AND om.user_id=tm.user_id AND om.status='active'
         )
  FROM public.tenant_memberships tm
  LEFT JOIN public.profiles p ON p.id=tm.user_id
  WHERE tm.tenant_id=_tid AND tm.status='active'
    AND NOT EXISTS (
      SELECT 1 FROM public.organization_memberships om
      WHERE om.organization_id=_organization_id AND om.user_id=tm.user_id
        AND om.role='org_admin' AND om.status='active'
    )
    AND (_query IS NULL OR _query='' OR p.email ILIKE '%'||_query||'%' OR
         (CASE WHEN p.organization_id IS NOT NULL
               THEN public.btpm_decrypt(p.display_name, p.organization_id)
               ELSE p.display_name END) ILIKE '%'||_query||'%')
  ORDER BY dn NULLS LAST, p.email NULLS LAST
  LIMIT 50;
END;$$;


--
-- Name: tenant_admin_list_org_admins(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_org_admins(_organization_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, display_name text, email text, role text, status text, can_remove boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _tid uuid;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  RETURN QUERY
  SELECT om.id, om.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END,
         p.email, om.role::text, om.status::text,
         (om.role='org_admin' AND om.status='active'),
         om.created_at
  FROM public.organization_memberships om
  LEFT JOIN public.profiles p ON p.id=om.user_id
  WHERE om.organization_id=_organization_id AND om.role='org_admin'
  ORDER BY p.email NULLS LAST;
END;$$;


