-- Name: tenant_admin_list_org_authority_audit(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_org_authority_audit(_organization_id uuid, _limit integer DEFAULT 50) RETURNS SETOF public.admin_authority_audit
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _tid uuid;
BEGIN
  SELECT tenant_id INTO _tid FROM public.organizations WHERE id=_organization_id;
  IF _tid IS NULL THEN RAISE EXCEPTION 'organization_not_found' USING ERRCODE='42501'; END IF;
  PERFORM public._assert_tenant_admin_caller(_tid);
  RETURN QUERY SELECT * FROM public.admin_authority_audit
    WHERE organization_id=_organization_id ORDER BY created_at DESC LIMIT LEAST(GREATEST(_limit,1),500);
END;$$;


--
-- Name: tenant_admin_list_organizations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_organizations(_tenant_id uuid) RETURNS TABLE(organization_id uuid, name text, slug text, organization_kind text, environment_role text, is_default boolean, active_member_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _default uuid;
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  SELECT default_organization_id INTO _default FROM public.tenants WHERE id = _tenant_id;

  RETURN QUERY
  SELECT
    o.id,
    o.name,
    o.slug,
    o.organization_kind::text,
    o.environment_role::text,
    (o.id = _default) AS is_default,
    (SELECT COUNT(*) FROM public.organization_memberships om
       WHERE om.organization_id = o.id AND om.status = 'active') AS active_member_count,
    o.created_at
  FROM public.organizations o
  WHERE o.tenant_id = _tenant_id
  ORDER BY o.name;
END;
$$;


