-- Name: tenant_admin_list_tenant_admin_candidates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_tenant_admin_candidates(_tenant_id uuid, _query text DEFAULT NULL::text) RETURNS TABLE(user_id uuid, display_name text, email text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  RETURN QUERY
  SELECT tm.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END AS dn,
         p.email
  FROM public.tenant_memberships tm
  LEFT JOIN public.profiles p ON p.id=tm.user_id
  WHERE tm.tenant_id=_tenant_id AND tm.status='active' AND tm.role='tenant_member'
    AND (_query IS NULL OR _query='' OR p.email ILIKE '%'||_query||'%' OR
         (CASE WHEN p.organization_id IS NOT NULL
               THEN public.btpm_decrypt(p.display_name, p.organization_id)
               ELSE p.display_name END) ILIKE '%'||_query||'%')
  ORDER BY dn NULLS LAST, p.email NULLS LAST
  LIMIT 50;
END;$$;


--
-- Name: tenant_admin_list_tenant_admins(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_admin_list_tenant_admins(_tenant_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, display_name text, email text, role text, status text, is_protected boolean, can_remove boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public._assert_tenant_admin_caller(_tenant_id);
  RETURN QUERY
  SELECT tm.id, tm.user_id,
         CASE WHEN p.organization_id IS NOT NULL
              THEN public.btpm_decrypt(p.display_name, p.organization_id)
              ELSE p.display_name END,
         p.email, tm.role::text, tm.status::text,
         (tm.role='tenant_owner'),
         (tm.role='tenant_admin' AND tm.status='active'),
         tm.created_at
  FROM public.tenant_memberships tm
  LEFT JOIN public.profiles p ON p.id=tm.user_id
  WHERE tm.tenant_id=_tenant_id AND tm.role IN ('tenant_owner','tenant_admin')
