  IF NEW.organization_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.name := public.btpm_encrypt_if_legacy(NEW.name, NEW.organization_id);
    NEW.summary := public.btpm_encrypt_if_legacy(NEW.summary, NEW.organization_id);
  ELSE
    IF NEW.name IS DISTINCT FROM OLD.name THEN
      NEW.name := public.btpm_encrypt_if_legacy(NEW.name, NEW.organization_id);
    END IF;
    IF NEW.summary IS DISTINCT FROM OLD.summary THEN
      NEW.summary := public.btpm_encrypt_if_legacy(NEW.summary, NEW.organization_id);
    END IF;
  END IF;
  RETURN NEW;
END $$;


