--
-- Name: tg_phase_metadata_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_phase_metadata_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _changed jsonb := '{}'::jsonb; _org uuid := NEW.organization_id;
DECLARE _old_desc text; _new_desc text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;

  IF NEW.name IS DISTINCT FROM OLD.name THEN
    _changed := _changed || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
  END IF;

  IF NEW.description IS DISTINCT FROM OLD.description THEN
    BEGIN
      _old_desc := CASE WHEN OLD.description IS NULL OR OLD.description = '' THEN OLD.description
                        ELSE public.btpm_decrypt(OLD.description, _org) END;
    EXCEPTION WHEN OTHERS THEN _old_desc := NULL; END;
    BEGIN
      _new_desc := CASE WHEN NEW.description IS NULL OR NEW.description = '' THEN NEW.description
                        ELSE public.btpm_decrypt(NEW.description, _org) END;
    EXCEPTION WHEN OTHERS THEN _new_desc := NULL; END;
    _changed := _changed || jsonb_build_object('description', jsonb_build_object('old', _old_desc, 'new', _new_desc));
  END IF;

  IF _changed = '{}'::jsonb THEN RETURN NEW; END IF;

  BEGIN
    PERFORM public.log_activity_event(
      _organization_id => NEW.organization_id,
      _actor_id        => auth.uid(),
      _event_type      => 'phase_metadata_updated',
      _target_type     => 'phase',
      _target_id       => NEW.id,
      _metadata        => jsonb_build_object(
        'phase_name', NEW.name,
        'project_id', NEW.project_id,
        'changed_fields', _changed
      ),
      _workspace_id    => NEW.workspace_id
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END; $$;


