--
-- Name: tg_phases_actual_and_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_phases_actual_and_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_was_completed boolean := (TG_OP = 'UPDATE' AND OLD.status = 'completed');
BEGIN
  -- Range validation
  IF NEW.actual_start_date IS NOT NULL
     AND NEW.actual_end_date IS NOT NULL
     AND NEW.actual_end_date < NEW.actual_start_date THEN
    RAISE EXCEPTION 'phase actual_end_date (%) cannot be before actual_start_date (%)',
      NEW.actual_end_date, NEW.actual_start_date;
  END IF;

  -- Block direct manual writes to phase actuals; only internal rollup may set them
  IF TG_OP = 'INSERT' THEN
    IF (NEW.actual_start_date IS NOT NULL OR NEW.actual_end_date IS NOT NULL)
       AND NOT public._actual_rollup_allowed() THEN
      RAISE EXCEPTION 'phase.actual_start_date / actual_end_date are derived; manual writes are not allowed';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.actual_start_date IS DISTINCT FROM OLD.actual_start_date
        OR NEW.actual_end_date IS DISTINCT FROM OLD.actual_end_date)
       AND NOT public._actual_rollup_allowed() THEN
      RAISE EXCEPTION 'phase.actual_start_date / actual_end_date are derived; manual writes are not allowed';
    END IF;
  END IF;

  -- Completed-phase lock (per 4F.1):
  -- Lock start_date, target_end_date, status, project_id
  IF v_was_completed AND NOT public._lifecycle_bypass_allowed() THEN
    IF NEW.start_date      IS DISTINCT FROM OLD.start_date      THEN
      RAISE EXCEPTION 'Phase is completed; reopen required to change start_date';
    END IF;
    IF NEW.target_end_date IS DISTINCT FROM OLD.target_end_date THEN
      RAISE EXCEPTION 'Phase is completed; reopen required to change target_end_date';
    END IF;
    IF NEW.project_id      IS DISTINCT FROM OLD.project_id      THEN
      RAISE EXCEPTION 'Phase is completed; reopen required to change project_id';
    END IF;
    IF NEW.status          IS DISTINCT FROM OLD.status          THEN
      RAISE EXCEPTION 'Phase is completed; reopen required to change status';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tg_phases_after_rollup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_phases_after_rollup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status      IS DISTINCT FROM OLD.status
       OR NEW.is_archived IS DISTINCT FROM OLD.is_archived
       OR NEW.actual_start_date IS DISTINCT FROM OLD.actual_start_date
       OR NEW.actual_end_date   IS DISTINCT FROM OLD.actual_end_date
       OR NEW.project_id IS DISTINCT FROM OLD.project_id THEN
      PERFORM public._recompute_project_actuals(NEW.project_id);
      IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN
        PERFORM public._recompute_project_actuals(OLD.project_id);
      END IF;
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


