--
-- Name: tg_project_templates_encrypt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_project_templates_encrypt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.ensure_org_encryption_key(NEW.organization_id);

  -- name: encrypt on INSERT, and on UPDATE whenever it changed.
  -- No heuristic detection — single, deterministic rule.
  IF NEW.name IS NOT NULL AND NEW.name <> '' THEN
    IF TG_OP = 'INSERT' OR NEW.name IS DISTINCT FROM OLD.name THEN
      NEW.name := public.btpm_encrypt_if_legacy(NEW.name, NEW.organization_id);
    END IF;
  END IF;

  IF NEW.description IS NOT NULL AND NEW.description <> '' THEN
    IF TG_OP = 'INSERT' OR NEW.description IS DISTINCT FROM OLD.description THEN
      NEW.description := public.btpm_encrypt_if_legacy(NEW.description, NEW.organization_id);
    END IF;
  END IF;

  IF NEW.blueprint_payload IS NOT NULL AND NEW.blueprint_payload <> '' THEN
    IF TG_OP = 'INSERT' OR NEW.blueprint_payload IS DISTINCT FROM OLD.blueprint_payload THEN
      NEW.blueprint_payload := public.btpm_encrypt_if_legacy(NEW.blueprint_payload, NEW.organization_id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


