--
-- Name: tg_projects_actual_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_projects_actual_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.actual_start_date IS NOT NULL
     AND NEW.actual_end_date IS NOT NULL
     AND NEW.actual_end_date < NEW.actual_start_date THEN
    RAISE EXCEPTION 'project actual_end_date (%) cannot be before actual_start_date (%)',
      NEW.actual_end_date, NEW.actual_start_date;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF (NEW.actual_start_date IS NOT NULL OR NEW.actual_end_date IS NOT NULL)
       AND NOT public._actual_rollup_allowed() THEN
      RAISE EXCEPTION 'project.actual_start_date / actual_end_date are derived; manual writes are not allowed';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF (NEW.actual_start_date IS DISTINCT FROM OLD.actual_start_date
        OR NEW.actual_end_date IS DISTINCT FROM OLD.actual_end_date)
       AND NOT public._actual_rollup_allowed() THEN
      RAISE EXCEPTION 'project.actual_start_date / actual_end_date are derived; manual writes are not allowed';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


