--
-- Name: tg_risk_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_risk_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event text;
  v_meta  jsonb;
BEGIN
  IF (TG_OP = 'INSERT') THEN
    v_event := 'risk_opened';
    v_meta := jsonb_build_object(
      'risk_id', NEW.id,
      'title', NEW.title,
      'likelihood', NEW.likelihood::text,
      'impact', NEW.impact::text,
      'status', NEW.status::text,
      'anchor_type', NEW.target_type,
      'anchor_id',   NEW.target_id
    );
    PERFORM public.log_activity_event(
      NEW.organization_id, auth.uid(), v_event, 'risk', NEW.id, v_meta, NEW.workspace_id
    );
    PERFORM public.log_activity_event(
      NEW.organization_id, auth.uid(), v_event, NEW.target_type, NEW.target_id, v_meta, NEW.workspace_id
    );
    RETURN NEW;
  END IF;

  IF (TG_OP = 'UPDATE') THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      v_event := 'risk_state_changed';
      v_meta := jsonb_build_object(
        'risk_id', NEW.id,
        'title', NEW.title,
        'old_status', OLD.status::text,
        'new_status', NEW.status::text,
        'anchor_type', NEW.target_type,
        'anchor_id',   NEW.target_id
      );
      PERFORM public.log_activity_event(
        NEW.organization_id, auth.uid(), v_event, 'risk', NEW.id, v_meta, NEW.workspace_id
      );
      PERFORM public.log_activity_event(
        NEW.organization_id, auth.uid(), v_event, NEW.target_type, NEW.target_id, v_meta, NEW.workspace_id
      );
    END IF;
    RETURN NEW;
  END IF;

  RETURN NULL;
END; $$;


