--
-- Name: tg_task_metadata_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_task_metadata_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _changed jsonb := '{}'::jsonb; _org uuid := NEW.organization_id;
DECLARE _old_desc text; _new_desc text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;

  -- Phase move → its own event, not folded into metadata diff.
  IF NEW.phase_id IS DISTINCT FROM OLD.phase_id THEN
    BEGIN
      PERFORM public.log_activity_event(
        _organization_id => NEW.organization_id,
        _actor_id        => auth.uid(),
        _event_type      => 'task_moved',
        _target_type     => 'task',
        _target_id       => NEW.id,
        _metadata        => jsonb_build_object(
          'task_name', NEW.name,
          'project_id', NEW.project_id,
          'old_phase_id', OLD.phase_id,
          'new_phase_id', NEW.phase_id
        ),
        _workspace_id    => NEW.workspace_id
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  IF NEW.name IS DISTINCT FROM OLD.name THEN
    _changed := _changed || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
  END IF;
  IF NEW.priority IS DISTINCT FROM OLD.priority THEN
    _changed := _changed || jsonb_build_object('priority', jsonb_build_object('old', OLD.priority::text, 'new', NEW.priority::text));
  END IF;
  IF NEW.task_type IS DISTINCT FROM OLD.task_type THEN
    _changed := _changed || jsonb_build_object('task_type', jsonb_build_object('old', OLD.task_type::text, 'new', NEW.task_type::text));
  END IF;
  IF NEW.estimated_hours IS DISTINCT FROM OLD.estimated_hours THEN
    _changed := _changed || jsonb_build_object('estimated_hours', jsonb_build_object('old', OLD.estimated_hours, 'new', NEW.estimated_hours));
  END IF;
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    _changed := _changed || jsonb_build_object('owner_id', jsonb_build_object('old', OLD.owner_id, 'new', NEW.owner_id));
  END IF;
  IF NEW.description IS DISTINCT FROM OLD.description THEN
    BEGIN
      _old_desc := CASE WHEN OLD.description IS NULL OR OLD.description = '' THEN OLD.description
                        ELSE public.btpm_decrypt(OLD.description, _org) END;
    EXCEPTION WHEN OTHERS THEN _old_desc := NULL; END;
    BEGIN
      _new_desc := CASE WHEN NEW.description IS NULL OR NEW.description = '' THEN NEW.description
                        ELSE public.btpm_decrypt(NEW.description, _org) END;
    EXCEPTION WHEN OTHERS THEN _new_desc := NULL; END;
    _changed := _changed || jsonb_build_object('description', jsonb_build_object('old', _old_desc, 'new', _new_desc));
  END IF;

  IF _changed = '{}'::jsonb THEN RETURN NEW; END IF;

  BEGIN
    PERFORM public.log_activity_event(
      _organization_id => NEW.organization_id,
      _actor_id        => auth.uid(),
      _event_type      => 'task_metadata_updated',
      _target_type     => 'task',
      _target_id       => NEW.id,
      _metadata        => jsonb_build_object(
        'task_name', NEW.name,
        'project_id', NEW.project_id,
        'phase_id', NEW.phase_id,
        'changed_fields', _changed
      ),
      _workspace_id    => NEW.workspace_id
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END; $$;


--
-- Name: tg_task_validate_adoption_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_task_validate_adoption_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE i_org uuid; i_ws uuid; i_proj uuid;
BEGIN
  IF NEW.adoption_initiative_id IS NULL THEN
    -- ensure flag and id are consistent
    IF NEW.is_adoption_related IS DISTINCT FROM true THEN
      -- allow user to mark task adoption-related without an initiative
      NULL;
    END IF;
    RETURN NEW;
  END IF;

  SELECT organization_id, workspace_id, project_id INTO i_org, i_ws, i_proj
  FROM public.adoption_initiatives WHERE id = NEW.adoption_initiative_id;
  IF i_org IS NULL THEN
    RAISE EXCEPTION 'task: invalid adoption_initiative_id';
  END IF;
  IF NEW.organization_id <> i_org OR NEW.workspace_id <> i_ws OR NEW.project_id <> i_proj THEN
    RAISE EXCEPTION 'task: adoption_initiative must belong to same project/workspace/organization';
  END IF;
  -- force flag true when an initiative is linked
  NEW.is_adoption_related := true;
  RETURN NEW;
END $$;


--
-- Name: tg_tasks_actual_and_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_tasks_actual_and_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_was_completed boolean := (TG_OP = 'UPDATE' AND OLD.status = 'completed');
BEGIN
  -- Range validation (always)
  IF NEW.actual_start_date IS NOT NULL
     AND NEW.actual_end_date IS NOT NULL
     AND NEW.actual_end_date < NEW.actual_start_date THEN
    RAISE EXCEPTION 'actual_end_date (%) cannot be before actual_start_date (%)',
      NEW.actual_end_date, NEW.actual_start_date;
  END IF;

  -- actual_end_date requires actual_start_date
  IF NEW.actual_end_date IS NOT NULL AND NEW.actual_start_date IS NULL THEN
    RAISE EXCEPTION 'actual_end_date cannot be set without actual_start_date';
  END IF;

  -- Completed-task lock (per 4F.1):
  -- Lock start_date, due_date, phase_id, actual_start_date, actual_end_date, status
  -- Allow status change from completed -> X ONLY via reopen RPC
  IF v_was_completed AND NOT public._lifecycle_bypass_allowed() THEN
    IF NEW.start_date         IS DISTINCT FROM OLD.start_date         THEN
      RAISE EXCEPTION 'Task is completed; reopen required to change start_date';
    END IF;
    IF NEW.due_date           IS DISTINCT FROM OLD.due_date           THEN
      RAISE EXCEPTION 'Task is completed; reopen required to change due_date';
    END IF;
    IF NEW.phase_id           IS DISTINCT FROM OLD.phase_id           THEN
      RAISE EXCEPTION 'Task is completed; reopen required to change phase_id';
    END IF;
    IF NEW.actual_start_date  IS DISTINCT FROM OLD.actual_start_date  THEN
      RAISE EXCEPTION 'Task is completed; reopen required to change actual_start_date';
    END IF;
    IF NEW.actual_end_date    IS DISTINCT FROM OLD.actual_end_date    THEN
      RAISE EXCEPTION 'Task is completed; reopen required to change actual_end_date';
    END IF;
    IF NEW.status             IS DISTINCT FROM OLD.status             THEN
      RAISE EXCEPTION 'Task is completed; reopen required to change status';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tg_tasks_after_actual_rollup_and_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_tasks_after_actual_rollup_and_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_phase_changed boolean := false;
  v_actual_changed boolean := false;
  v_old_phase uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_actual_changed := (NEW.actual_start_date IS NOT NULL OR NEW.actual_end_date IS NOT NULL);
    PERFORM public._recompute_phase_actuals(NEW.phase_id);
    PERFORM public._recompute_project_actuals(NEW.project_id);
  ELSIF TG_OP = 'UPDATE' THEN
    v_phase_changed := (NEW.phase_id IS DISTINCT FROM OLD.phase_id);
    v_actual_changed := (NEW.actual_start_date IS DISTINCT FROM OLD.actual_start_date
                      OR NEW.actual_end_date   IS DISTINCT FROM OLD.actual_end_date);

    IF v_actual_changed OR v_phase_changed
       OR NEW.status      IS DISTINCT FROM OLD.status
       OR NEW.is_archived IS DISTINCT FROM OLD.is_archived THEN
      PERFORM public._recompute_phase_actuals(NEW.phase_id);
      IF v_phase_changed THEN
        PERFORM public._recompute_phase_actuals(OLD.phase_id);
      END IF;
      PERFORM public._recompute_project_actuals(NEW.project_id);
    END IF;

    -- Log material actual-date changes on the task itself only
    IF v_actual_changed THEN
      PERFORM public.log_activity_event(
        NEW.organization_id,
        auth.uid(),
        'task_actual_dates_updated',
        'task',
        NEW.id,
        jsonb_build_object(
          'old_actual_start_date', OLD.actual_start_date,
          'new_actual_start_date', NEW.actual_start_date,
          'old_actual_end_date',   OLD.actual_end_date,
          'new_actual_end_date',   NEW.actual_end_date,
          'project_id', NEW.project_id,
          'phase_id',   NEW.phase_id
        ),
        NEW.workspace_id
      );
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: tg_tasks_after_phase_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_tasks_after_phase_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public._recompute_phase_completion(NEW.phase_id);

  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status      IS DISTINCT FROM OLD.status
       OR NEW.is_archived IS DISTINCT FROM OLD.is_archived
       OR NEW.phase_id    IS DISTINCT FROM OLD.phase_id THEN
      PERFORM public._recompute_phase_completion(NEW.phase_id);
      IF NEW.phase_id IS DISTINCT FROM OLD.phase_id THEN
        PERFORM public._recompute_phase_completion(OLD.phase_id);
      END IF;
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


