--
-- Name: transition_governance_decision_case_stage(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_governance_decision_case_stage(_record_id uuid, _target_stage text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _row public.governance_records%ROWTYPE;
  _current text;
  _order int;
  _target_order int;
  _has_brief boolean;
  _has_provided_pkg boolean;
  v_client_id text;
  v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized'
      USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Governance record not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Stage transitions are only allowed on decision_case records'
      USING ERRCODE = '22023';
  END IF;

  _current := COALESCE(_row.decision_stage, 'initiated');

  IF _current = 'closed' THEN
    RAISE EXCEPTION 'This decision case is closed and cannot be transitioned.'
      USING ERRCODE = '22023';
  END IF;
  IF _current = 'decision_taken' THEN
    RAISE EXCEPTION 'A decision has been taken; further progression is handled by the closure flow.'
      USING ERRCODE = '22023';
  END IF;

  IF _target_stage NOT IN ('evidence_collection','brief_prepared','pending_decision') THEN
    RAISE EXCEPTION 'Target stage % is not allowed via lifecycle transition.', _target_stage
      USING ERRCODE = '22023';
  END IF;

  _order := CASE _current
    WHEN 'initiated' THEN 1
    WHEN 'evidence_collection' THEN 2
    WHEN 'brief_prepared' THEN 3
    WHEN 'provided_to_stakeholders' THEN 4
    WHEN 'pending_decision' THEN 5
    WHEN 'decision_taken' THEN 6
    WHEN 'closed' THEN 7
  END;
  _target_order := CASE _target_stage
    WHEN 'evidence_collection' THEN 2
    WHEN 'brief_prepared' THEN 3
    WHEN 'pending_decision' THEN 5
  END;

  IF _target_order <= _order THEN
    RAISE EXCEPTION 'Stage transitions are forward-only.'
      USING ERRCODE = '22023';
  END IF;

  IF _target_stage = 'brief_prepared' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.governance_record_brief_versions
       WHERE governance_record_id = _record_id AND is_current = true
    ) INTO _has_brief;
    IF NOT _has_brief THEN
      RAISE EXCEPTION 'Create a Copilot Brief version before marking the brief as prepared.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF _target_stage = 'pending_decision' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.governance_record_stakeholder_packages
       WHERE governance_record_id = _record_id
         AND is_current = true
         AND package_status = 'provided'
    ) INTO _has_provided_pkg;
    IF NOT _has_provided_pkg THEN
      RAISE EXCEPTION 'Mark a stakeholder package as provided before moving to pending decision.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.governance_records
     SET decision_stage = _target_stage,
         updated_at = now()
   WHERE id = _record_id;

  PERFORM public.log_activity_event(
    _row.organization_id,
    v_caller,
    'governance_decision_case_stage_transitioned',
    'governance_record',
    _record_id,
    jsonb_build_object(
      'project_id', _row.project_id,
      'record_id', _record_id,
      'from_stage', _current,
      'to_stage', _target_stage
    ),
    _row.workspace_id
  );
END; $$;


--
-- Name: projects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.projects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    program_id uuid,
    name text NOT NULL,
    description text,
    status public.pm_status DEFAULT 'planned'::public.pm_status NOT NULL,
    priority public.pm_priority DEFAULT 'medium'::public.pm_priority NOT NULL,
    start_date date,
    target_end_date date,
    is_archived boolean DEFAULT false NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    charter text,
    goals text,
    scope_in text,
    scope_out text,
    agile_enabled boolean DEFAULT false NOT NULL,
    baseline_start_date date,
    baseline_end_date date,
    is_baselined boolean DEFAULT false NOT NULL,
    baseline_approved_at timestamp with time zone,
    baseline_approved_by uuid,
    actual_start_date date,
    actual_end_date date,
    project_stage public.project_stage DEFAULT 'planning'::public.project_stage NOT NULL,
    business_case text,
    success_criteria text,
    completion_criteria text,
    budget_narrative text,
    assumptions text,
    constraints text,
    delivery_model public.project_delivery_model,
    portfolio_item_id uuid,
    CONSTRAINT btpm_projects_date_range_valid CHECK (((start_date IS NULL) OR (target_end_date IS NULL) OR (target_end_date >= start_date)))
);


--
-- Name: transition_project_stage(uuid, public.project_stage); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_project_stage(_project_id uuid, _project_stage public.project_stage) RETURNS public.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_project public.projects;
  v_old_stage public.project_stage;
  v_client_id text;
  v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;

  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();

  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Not authorized: inactive user';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = _project_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Project not found';
  END IF;

  IF public.is_user_org_member(v_caller, v_project.organization_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.has_project_pm_authority(v_caller, _project_id) THEN
    RAISE EXCEPTION 'Not authorized: PM+ authority required to transition project stage';
  END IF;

  IF NOT public.can_write_demo(v_caller, v_project.workspace_id) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  v_old_stage := v_project.project_stage;
  IF v_old_stage = _project_stage THEN
    RETURN v_project;
  END IF;

  UPDATE public.projects
  SET project_stage = _project_stage,
      updated_at = now()
  WHERE id = _project_id
  RETURNING * INTO v_project;

  INSERT INTO public.activity_events (organization_id, workspace_id, actor_id,
    target_id, target_type, event_type, metadata)
  VALUES (v_project.organization_id, v_project.workspace_id, v_caller,
    v_project.id, 'project', 'project_stage_transitioned',
    json_build_object('from_stage', v_old_stage::text, 'to_stage', _project_stage::text)::text);

  RETURN v_project;
END;
$$;


--
-- Name: trg_capture_comment_mentions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_capture_comment_mentions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_member record;
  v_body_lower text;
  v_matched_ids uuid[] := '{}';
BEGIN
  IF current_setting('btpm.seed_mode', true) = 'true' THEN RETURN NEW; END IF;

  IF NEW.target_type NOT IN ('task', 'phase') THEN RETURN NEW; END IF;
  v_body_lower := lower(NEW.body);
  IF position('@' in v_body_lower) = 0 THEN RETURN NEW; END IF;

  BEGIN
    CREATE TEMP TABLE IF NOT EXISTS _mention_capture (
      comment_id uuid,
      mentioned_user_id uuid
    ) ON COMMIT DELETE ROWS;
  EXCEPTION WHEN duplicate_table THEN
    NULL;
  END;

  -- Guarded DELETE to satisfy sql_safe_updates (PostgREST sets this on)
  DELETE FROM _mention_capture WHERE comment_id IS NOT NULL OR comment_id IS NULL;

  FOR v_member IN
    SELECT wm.user_id,
           lower(btpm_decrypt(p.display_name, p.organization_id)) AS decrypted_name
      FROM workspace_memberships wm
      JOIN profiles p ON p.id = wm.user_id
     WHERE wm.workspace_id = NEW.workspace_id
       AND p.display_name IS NOT NULL
       AND p.display_name != ''
       AND p.is_active = true
  LOOP
    IF v_member.user_id = NEW.author_id THEN CONTINUE; END IF;
    IF v_member.decrypted_name IS NOT NULL
       AND v_member.decrypted_name != ''
       AND position('@' || v_member.decrypted_name in v_body_lower) > 0
    THEN
      v_matched_ids := v_matched_ids || v_member.user_id;
      INSERT INTO _mention_capture (comment_id, mentioned_user_id)
        VALUES (NEW.id, v_member.user_id);
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


