    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.metadata IS NULL
     OR btrim(NEW.metadata) IN ('', '{}', '[]', 'null', '"null"', '""') THEN
    NEW.metadata := NULL;
  ELSE
    NEW.metadata := btpm_encrypt_if_legacy(NEW.metadata, NEW.organization_id);
  END IF;
  RETURN NEW;
END;
$$;


