    IF NEW.options_summary IS DISTINCT FROM OLD.options_summary AND NEW.options_summary IS NOT NULL THEN NEW.options_summary := public.btpm_encrypt_if_legacy(NEW.options_summary, NEW.organization_id); END IF;
    IF NEW.recommendation_text IS DISTINCT FROM OLD.recommendation_text AND NEW.recommendation_text IS NOT NULL THEN NEW.recommendation_text := public.btpm_encrypt_if_legacy(NEW.recommendation_text, NEW.organization_id); END IF;
    IF NEW.guardrails_text IS DISTINCT FROM OLD.guardrails_text AND NEW.guardrails_text IS NOT NULL THEN NEW.guardrails_text := public.btpm_encrypt_if_legacy(NEW.guardrails_text, NEW.organization_id); END IF;
    IF NEW.residual_risks_text IS DISTINCT FROM OLD.residual_risks_text AND NEW.residual_risks_text IS NOT NULL THEN NEW.residual_risks_text := public.btpm_encrypt_if_legacy(NEW.residual_risks_text, NEW.organization_id); END IF;
    IF NEW.requested_decision_text IS DISTINCT FROM OLD.requested_decision_text AND NEW.requested_decision_text IS NOT NULL THEN NEW.requested_decision_text := public.btpm_encrypt_if_legacy(NEW.requested_decision_text, NEW.organization_id); END IF;
    IF NEW.open_questions_text IS DISTINCT FROM OLD.open_questions_text AND NEW.open_questions_text IS NOT NULL THEN NEW.open_questions_text := public.btpm_encrypt_if_legacy(NEW.open_questions_text, NEW.organization_id); END IF;
  END IF;
  RETURN NEW;
END; $$;


