    IF NEW.context_reason IS NOT NULL THEN
      NEW.context_reason := public.btpm_encrypt_if_legacy(NEW.context_reason, NEW.organization_id);
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.context_reason IS DISTINCT FROM OLD.context_reason
       AND NEW.context_reason IS NOT NULL THEN
      NEW.context_reason := public.btpm_encrypt_if_legacy(NEW.context_reason, NEW.organization_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


