--

CREATE FUNCTION public.trg_encrypt_governance_record_decision_outcome() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.ensure_org_encryption_key(NEW.organization_id);
  IF TG_OP = 'INSERT' THEN
    NEW.final_decision_text := public.btpm_encrypt_if_legacy(NEW.final_decision_text, NEW.organization_id);
    IF NEW.decided_by_text IS NOT NULL THEN NEW.decided_by_text := public.btpm_encrypt_if_legacy(NEW.decided_by_text, NEW.organization_id); END IF;
    IF NEW.approval_forum IS NOT NULL THEN NEW.approval_forum := public.btpm_encrypt_if_legacy(NEW.approval_forum, NEW.organization_id); END IF;
    IF NEW.decision_rationale IS NOT NULL THEN NEW.decision_rationale := public.btpm_encrypt_if_legacy(NEW.decision_rationale, NEW.organization_id); END IF;
    IF NEW.conditions_guardrails IS NOT NULL THEN NEW.conditions_guardrails := public.btpm_encrypt_if_legacy(NEW.conditions_guardrails, NEW.organization_id); END IF;
    IF NEW.residual_risks IS NOT NULL THEN NEW.residual_risks := public.btpm_encrypt_if_legacy(NEW.residual_risks, NEW.organization_id); END IF;
    IF NEW.follow_up_actions IS NOT NULL THEN NEW.follow_up_actions := public.btpm_encrypt_if_legacy(NEW.follow_up_actions, NEW.organization_id); END IF;
    IF NEW.signoff_evidence_url IS NOT NULL THEN NEW.signoff_evidence_url := public.btpm_encrypt_if_legacy(NEW.signoff_evidence_url, NEW.organization_id); END IF;
    IF NEW.closure_note IS NOT NULL THEN NEW.closure_note := public.btpm_encrypt_if_legacy(NEW.closure_note, NEW.organization_id); END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.final_decision_text IS DISTINCT FROM OLD.final_decision_text THEN NEW.final_decision_text := public.btpm_encrypt_if_legacy(NEW.final_decision_text, NEW.organization_id); END IF;
    IF NEW.decided_by_text IS DISTINCT FROM OLD.decided_by_text AND NEW.decided_by_text IS NOT NULL THEN NEW.decided_by_text := public.btpm_encrypt_if_legacy(NEW.decided_by_text, NEW.organization_id); END IF;
    IF NEW.approval_forum IS DISTINCT FROM OLD.approval_forum AND NEW.approval_forum IS NOT NULL THEN NEW.approval_forum := public.btpm_encrypt_if_legacy(NEW.approval_forum, NEW.organization_id); END IF;
    IF NEW.decision_rationale IS DISTINCT FROM OLD.decision_rationale AND NEW.decision_rationale IS NOT NULL THEN NEW.decision_rationale := public.btpm_encrypt_if_legacy(NEW.decision_rationale, NEW.organization_id); END IF;
    IF NEW.conditions_guardrails IS DISTINCT FROM OLD.conditions_guardrails AND NEW.conditions_guardrails IS NOT NULL THEN NEW.conditions_guardrails := public.btpm_encrypt_if_legacy(NEW.conditions_guardrails, NEW.organization_id); END IF;
    IF NEW.residual_risks IS DISTINCT FROM OLD.residual_risks AND NEW.residual_risks IS NOT NULL THEN NEW.residual_risks := public.btpm_encrypt_if_legacy(NEW.residual_risks, NEW.organization_id); END IF;
    IF NEW.follow_up_actions IS DISTINCT FROM OLD.follow_up_actions AND NEW.follow_up_actions IS NOT NULL THEN NEW.follow_up_actions := public.btpm_encrypt_if_legacy(NEW.follow_up_actions, NEW.organization_id); END IF;
    IF NEW.signoff_evidence_url IS DISTINCT FROM OLD.signoff_evidence_url AND NEW.signoff_evidence_url IS NOT NULL THEN NEW.signoff_evidence_url := public.btpm_encrypt_if_legacy(NEW.signoff_evidence_url, NEW.organization_id); END IF;
    IF NEW.closure_note IS DISTINCT FROM OLD.closure_note AND NEW.closure_note IS NOT NULL THEN NEW.closure_note := public.btpm_encrypt_if_legacy(NEW.closure_note, NEW.organization_id); END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_encrypt_governance_record_evidence_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_encrypt_governance_record_evidence_file() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM ensure_org_encryption_key(NEW.organization_id);
  IF TG_OP = 'INSERT' THEN
    NEW.site_id := btpm_encrypt_if_legacy(NEW.site_id, NEW.organization_id);
    NEW.drive_id := btpm_encrypt_if_legacy(NEW.drive_id, NEW.organization_id);
    NEW.item_id := btpm_encrypt_if_legacy(NEW.item_id, NEW.organization_id);
    NEW.file_name := btpm_encrypt_if_legacy(NEW.file_name, NEW.organization_id);
    NEW.evidence_title := btpm_encrypt_if_legacy(NEW.evidence_title, NEW.organization_id);
    IF NEW.file_extension IS NOT NULL THEN NEW.file_extension := btpm_encrypt_if_legacy(NEW.file_extension, NEW.organization_id); END IF;
    IF NEW.mime_type IS NOT NULL THEN NEW.mime_type := btpm_encrypt_if_legacy(NEW.mime_type, NEW.organization_id); END IF;
    IF NEW.etag IS NOT NULL THEN NEW.etag := btpm_encrypt_if_legacy(NEW.etag, NEW.organization_id); END IF;
    IF NEW.ctag IS NOT NULL THEN NEW.ctag := btpm_encrypt_if_legacy(NEW.ctag, NEW.organization_id); END IF;
    IF NEW.parent_path IS NOT NULL THEN NEW.parent_path := btpm_encrypt_if_legacy(NEW.parent_path, NEW.organization_id); END IF;
    IF NEW.sharepoint_web_url IS NOT NULL THEN NEW.sharepoint_web_url := btpm_encrypt_if_legacy(NEW.sharepoint_web_url, NEW.organization_id); END IF;
    IF NEW.evidence_summary IS NOT NULL THEN NEW.evidence_summary := btpm_encrypt_if_legacy(NEW.evidence_summary, NEW.organization_id); END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.evidence_title IS DISTINCT FROM OLD.evidence_title THEN
      NEW.evidence_title := btpm_encrypt_if_legacy(NEW.evidence_title, NEW.organization_id); END IF;
    IF NEW.evidence_summary IS DISTINCT FROM OLD.evidence_summary AND NEW.evidence_summary IS NOT NULL THEN
      NEW.evidence_summary := btpm_encrypt_if_legacy(NEW.evidence_summary, NEW.organization_id); END IF;
    -- The other encrypted fields are immutable through the update RPC, so we
    -- intentionally do NOT re-encrypt them on UPDATE.
  END IF;
  RETURN NEW;
END; $$;


