--
-- Name: trg_encrypt_kpi_app_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_encrypt_kpi_app_attempt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org
    FROM public.kpi_app_submission_outbox
   WHERE id = NEW.outbox_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'kpi_app_submission_attempts: outbox_id % not found', NEW.outbox_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.upstream_body_summary := btpm_encrypt_if_legacy(NEW.upstream_body_summary, v_org);
    NEW.error_message         := btpm_encrypt_if_legacy(NEW.error_message,         v_org);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_encrypt_kpi_app_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_encrypt_kpi_app_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.source_string_value         := btpm_encrypt_if_legacy(NEW.source_string_value,         NEW.organization_id);
    NEW.source_comment              := btpm_encrypt_if_legacy(NEW.source_comment,              NEW.organization_id);
    NEW.source_action_plan          := btpm_encrypt_if_legacy(NEW.source_action_plan,          NEW.organization_id);
    NEW.last_upstream_body_summary  := btpm_encrypt_if_legacy(NEW.last_upstream_body_summary,  NEW.organization_id);
    NEW.last_error_message          := btpm_encrypt_if_legacy(NEW.last_error_message,          NEW.organization_id);
  ELSIF TG_OP = 'UPDATE' THEN
    -- Only encrypt fields that changed in this UPDATE (avoid re-encrypt loops).
    IF NEW.source_string_value IS DISTINCT FROM OLD.source_string_value THEN
      NEW.source_string_value := btpm_encrypt_if_legacy(NEW.source_string_value, NEW.organization_id);
    END IF;
    IF NEW.source_comment IS DISTINCT FROM OLD.source_comment THEN
      NEW.source_comment := btpm_encrypt_if_legacy(NEW.source_comment, NEW.organization_id);
    END IF;
    IF NEW.source_action_plan IS DISTINCT FROM OLD.source_action_plan THEN
      NEW.source_action_plan := btpm_encrypt_if_legacy(NEW.source_action_plan, NEW.organization_id);
    END IF;
    IF NEW.last_upstream_body_summary IS DISTINCT FROM OLD.last_upstream_body_summary THEN
      NEW.last_upstream_body_summary := btpm_encrypt_if_legacy(NEW.last_upstream_body_summary, NEW.organization_id);
    END IF;
    IF NEW.last_error_message IS DISTINCT FROM OLD.last_error_message THEN
      NEW.last_error_message := btpm_encrypt_if_legacy(NEW.last_error_message, NEW.organization_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


