  IF TG_OP = 'INSERT' THEN
    NEW.name        := public.btpm_encrypt_if_legacy(NEW.name,        NEW.organization_id);
    NEW.code        := public.btpm_encrypt_if_legacy(NEW.code,        NEW.organization_id);
    NEW.description := public.btpm_encrypt_if_legacy(NEW.description, NEW.organization_id);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.name        IS DISTINCT FROM OLD.name        THEN NEW.name        := public.btpm_encrypt_if_legacy(NEW.name,        NEW.organization_id); END IF;
    IF NEW.code        IS DISTINCT FROM OLD.code        THEN NEW.code        := public.btpm_encrypt_if_legacy(NEW.code,        NEW.organization_id); END IF;
    IF NEW.description IS DISTINCT FROM OLD.description THEN NEW.description := public.btpm_encrypt_if_legacy(NEW.description, NEW.organization_id); END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_encrypt_profile_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_encrypt_profile_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_email text;
BEGIN
  IF NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Default display_name from email local-part when null/empty.
  IF NEW.display_name IS NULL OR btrim(NEW.display_name) = '' THEN
    v_email := NEW.email;
    IF v_email IS NULL OR position('@' in v_email) = 0 THEN
      SELECT email INTO v_email FROM auth.users WHERE id = NEW.id;
    END IF;
    IF v_email IS NOT NULL AND position('@' in v_email) > 0 THEN
      NEW.display_name := split_part(lower(v_email), '@', 1);
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.display_name := btpm_encrypt_if_legacy(NEW.display_name, NEW.organization_id);
    NEW.avatar_url := btpm_encrypt_if_legacy(NEW.avatar_url, NEW.organization_id);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.display_name IS DISTINCT FROM OLD.display_name THEN
      NEW.display_name := btpm_encrypt_if_legacy(NEW.display_name, NEW.organization_id);
    END IF;
    IF NEW.avatar_url IS DISTINCT FROM OLD.avatar_url THEN
      NEW.avatar_url := btpm_encrypt_if_legacy(NEW.avatar_url, NEW.organization_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


