--
-- Name: trg_encrypt_project_benefits_fn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_encrypt_project_benefits_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.ensure_org_encryption_key(NEW.organization_id);

  IF TG_OP = 'INSERT' THEN
    IF NEW.metric_name IS NOT NULL THEN
      NEW.metric_name := public.btpm_encrypt_if_legacy(NEW.metric_name, NEW.organization_id);
    END IF;
    IF NEW.description IS NOT NULL THEN
      NEW.description := public.btpm_encrypt_if_legacy(NEW.description, NEW.organization_id);
    END IF;
    IF NEW.custom_benefit_type_label IS NOT NULL THEN
      NEW.custom_benefit_type_label := public.btpm_encrypt_if_legacy(NEW.custom_benefit_type_label, NEW.organization_id);
    END IF;
    IF NEW.evidence_note IS NOT NULL THEN
      NEW.evidence_note := public.btpm_encrypt_if_legacy(NEW.evidence_note, NEW.organization_id);
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.metric_name IS DISTINCT FROM OLD.metric_name AND NEW.metric_name IS NOT NULL THEN
      NEW.metric_name := public.btpm_encrypt_if_legacy(NEW.metric_name, NEW.organization_id);
    END IF;
    IF NEW.description IS DISTINCT FROM OLD.description AND NEW.description IS NOT NULL THEN
      NEW.description := public.btpm_encrypt_if_legacy(NEW.description, NEW.organization_id);
    END IF;
    IF NEW.custom_benefit_type_label IS DISTINCT FROM OLD.custom_benefit_type_label
       AND NEW.custom_benefit_type_label IS NOT NULL THEN
      NEW.custom_benefit_type_label := public.btpm_encrypt_if_legacy(NEW.custom_benefit_type_label, NEW.organization_id);
    END IF;
    IF NEW.evidence_note IS DISTINCT FROM OLD.evidence_note AND NEW.evidence_note IS NOT NULL THEN
      NEW.evidence_note := public.btpm_encrypt_if_legacy(NEW.evidence_note, NEW.organization_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


