--

CREATE FUNCTION public.trg_encrypt_project_narratives() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.description         := btpm_encrypt_if_legacy(NEW.description,         NEW.organization_id);
    NEW.charter             := btpm_encrypt_if_legacy(NEW.charter,             NEW.organization_id);
    NEW.goals               := btpm_encrypt_if_legacy(NEW.goals,               NEW.organization_id);
    NEW.scope_in            := btpm_encrypt_if_legacy(NEW.scope_in,            NEW.organization_id);
    NEW.scope_out           := btpm_encrypt_if_legacy(NEW.scope_out,           NEW.organization_id);
    NEW.business_case       := btpm_encrypt_if_legacy(NEW.business_case,       NEW.organization_id);
    NEW.success_criteria    := btpm_encrypt_if_legacy(NEW.success_criteria,    NEW.organization_id);
    NEW.completion_criteria := btpm_encrypt_if_legacy(NEW.completion_criteria, NEW.organization_id);
    NEW.budget_narrative    := btpm_encrypt_if_legacy(NEW.budget_narrative,    NEW.organization_id);
    NEW.assumptions         := btpm_encrypt_if_legacy(NEW.assumptions,         NEW.organization_id);
    NEW.constraints         := btpm_encrypt_if_legacy(NEW.constraints,         NEW.organization_id);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.description         IS DISTINCT FROM OLD.description         THEN NEW.description         := btpm_encrypt_if_legacy(NEW.description,         NEW.organization_id); END IF;
    IF NEW.charter             IS DISTINCT FROM OLD.charter             THEN NEW.charter             := btpm_encrypt_if_legacy(NEW.charter,             NEW.organization_id); END IF;
    IF NEW.goals               IS DISTINCT FROM OLD.goals               THEN NEW.goals               := btpm_encrypt_if_legacy(NEW.goals,               NEW.organization_id); END IF;
    IF NEW.scope_in            IS DISTINCT FROM OLD.scope_in            THEN NEW.scope_in            := btpm_encrypt_if_legacy(NEW.scope_in,            NEW.organization_id); END IF;
    IF NEW.scope_out           IS DISTINCT FROM OLD.scope_out           THEN NEW.scope_out           := btpm_encrypt_if_legacy(NEW.scope_out,           NEW.organization_id); END IF;
    IF NEW.business_case       IS DISTINCT FROM OLD.business_case       THEN NEW.business_case       := btpm_encrypt_if_legacy(NEW.business_case,       NEW.organization_id); END IF;
    IF NEW.success_criteria    IS DISTINCT FROM OLD.success_criteria    THEN NEW.success_criteria    := btpm_encrypt_if_legacy(NEW.success_criteria,    NEW.organization_id); END IF;
    IF NEW.completion_criteria IS DISTINCT FROM OLD.completion_criteria THEN NEW.completion_criteria := btpm_encrypt_if_legacy(NEW.completion_criteria, NEW.organization_id); END IF;
    IF NEW.budget_narrative    IS DISTINCT FROM OLD.budget_narrative    THEN NEW.budget_narrative    := btpm_encrypt_if_legacy(NEW.budget_narrative,    NEW.organization_id); END IF;
    IF NEW.assumptions         IS DISTINCT FROM OLD.assumptions         THEN NEW.assumptions         := btpm_encrypt_if_legacy(NEW.assumptions,         NEW.organization_id); END IF;
    IF NEW.constraints         IS DISTINCT FROM OLD.constraints         THEN NEW.constraints         := btpm_encrypt_if_legacy(NEW.constraints,         NEW.organization_id); END IF;
  END IF;
  RETURN NEW;
END;
$$;


