--
-- Name: trg_gbcl_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_gbcl_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _r record;
  _sp record;
  _belongs boolean;
  _kpi_target_type text;
  _kpi_target_id uuid;
BEGIN
  -- Parent governance record
  SELECT organization_id, workspace_id, project_id, record_kind INTO _r
    FROM public.governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF _r.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'BTPM context links are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: BTPM context link must inherit parent record scope' USING ERRCODE='22023';
  END IF;

  -- Source project
  SELECT id, organization_id, workspace_id INTO _sp
    FROM public.projects WHERE id = NEW.source_project_id;
  IF _sp IS NULL THEN
    RAISE EXCEPTION 'Source project % not found', NEW.source_project_id USING ERRCODE='P0002';
  END IF;
  IF _sp.organization_id <> _r.organization_id THEN
    RAISE EXCEPTION 'Source project must be in the same organization as the parent project' USING ERRCODE='22023';
  END IF;
  IF NEW.source_workspace_id <> _sp.workspace_id THEN
    RAISE EXCEPTION 'source_workspace_id must match the source project workspace' USING ERRCODE='22023';
  END IF;

  -- Allowed enumerations
  IF NEW.object_type NOT IN
     ('project','phase','task','risk','blocker','kpi_definition','kpi_update') THEN
    RAISE EXCEPTION 'Invalid object_type %', NEW.object_type USING ERRCODE='22023';
  END IF;
  IF NEW.relationship_type NOT IN
     ('directly_relevant','dependency','shared_risk','shared_blocker',
      'shared_milestone','implementation_source','other') THEN
    RAISE EXCEPTION 'Invalid relationship_type %', NEW.relationship_type USING ERRCODE='22023';
  END IF;
  IF NEW.relevance_level NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid relevance_level %', NEW.relevance_level USING ERRCODE='22023';
  END IF;

  -- Object ownership validation
  _belongs := false;

  IF NEW.object_type = 'project' THEN
    IF NEW.object_id <> NEW.source_project_id THEN
      RAISE EXCEPTION 'For object_type=project, object_id must equal source_project_id' USING ERRCODE='22023';
    END IF;
    _belongs := true;

  ELSIF NEW.object_type = 'phase' THEN
    SELECT EXISTS(SELECT 1 FROM public.phases WHERE id = NEW.object_id AND project_id = NEW.source_project_id)
      INTO _belongs;

  ELSIF NEW.object_type = 'task' THEN
    SELECT EXISTS(SELECT 1 FROM public.tasks WHERE id = NEW.object_id AND project_id = NEW.source_project_id)
      INTO _belongs;

  ELSIF NEW.object_type = 'risk' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.risks r
      WHERE r.id = NEW.object_id AND (
        (r.target_type='project' AND r.target_id = NEW.source_project_id)
        OR (r.target_type='phase'
            AND r.target_id IN (SELECT id FROM public.phases WHERE project_id = NEW.source_project_id))
        OR (r.target_type='task'
            AND r.target_id IN (SELECT id FROM public.tasks  WHERE project_id = NEW.source_project_id))
      )
    ) INTO _belongs;

  ELSIF NEW.object_type = 'blocker' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.blockers b
      WHERE b.id = NEW.object_id AND (
        (b.target_type='project' AND b.target_id = NEW.source_project_id)
        OR (b.target_type='phase'
            AND b.target_id IN (SELECT id FROM public.phases WHERE project_id = NEW.source_project_id))
        OR (b.target_type='task'
            AND b.target_id IN (SELECT id FROM public.tasks  WHERE project_id = NEW.source_project_id))
      )
    ) INTO _belongs;

  ELSIF NEW.object_type = 'kpi_definition' THEN
    SELECT EXISTS(
      SELECT 1 FROM public.kpi_definitions k
      WHERE k.id = NEW.object_id AND (
        (k.target_type='project' AND k.target_id = NEW.source_project_id)
        OR (k.target_type='phase'
            AND k.target_id IN (SELECT id FROM public.phases WHERE project_id = NEW.source_project_id))
        OR (k.target_type='task'
            AND k.target_id IN (SELECT id FROM public.tasks  WHERE project_id = NEW.source_project_id))
      )
    ) INTO _belongs;

  ELSIF NEW.object_type = 'kpi_update' THEN
    SELECT k.target_type, k.target_id
      INTO _kpi_target_type, _kpi_target_id
      FROM public.kpi_updates u
      JOIN public.kpi_definitions k ON k.id = u.kpi_definition_id
      WHERE u.id = NEW.object_id;
    IF _kpi_target_type IS NULL THEN
      _belongs := false;
    ELSIF _kpi_target_type = 'project' THEN
      _belongs := (_kpi_target_id = NEW.source_project_id);
    ELSIF _kpi_target_type = 'phase' THEN
      SELECT EXISTS(SELECT 1 FROM public.phases WHERE id = _kpi_target_id AND project_id = NEW.source_project_id)
        INTO _belongs;
    ELSIF _kpi_target_type = 'task' THEN
      SELECT EXISTS(SELECT 1 FROM public.tasks WHERE id = _kpi_target_id AND project_id = NEW.source_project_id)
        INTO _belongs;
    ELSE
      _belongs := false;
    END IF;
  END IF;

  IF NOT _belongs THEN
    RAISE EXCEPTION 'Linked % % does not belong to source project %',
      NEW.object_type, NEW.object_id, NEW.source_project_id USING ERRCODE='22023';
  END IF;

  RETURN NEW;
END;
$$;


