--
-- Name: trg_gcdp_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_gcdp_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _r record;
  _sp_id uuid;
  _other_org boolean;
  _has_parent boolean;
BEGIN
  SELECT organization_id, workspace_id, project_id, record_kind INTO _r
    FROM public.governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF _r.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Data packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: data package must inherit parent record scope' USING ERRCODE='22023';
  END IF;
  IF NEW.version_number IS NULL OR NEW.version_number <= 0 THEN
    RAISE EXCEPTION 'version_number must be positive' USING ERRCODE='22023';
  END IF;
  IF NEW.package_status NOT IN ('prepared','shared_externally','superseded') THEN
    RAISE EXCEPTION 'Invalid package_status %', NEW.package_status USING ERRCODE='22023';
  END IF;
  IF NEW.package_filename IS NULL OR length(trim(NEW.package_filename)) = 0 THEN
    RAISE EXCEPTION 'package_filename is required' USING ERRCODE='22023';
  END IF;
  IF NEW.package_json IS NULL OR length(trim(NEW.package_json)) = 0 THEN
    RAISE EXCEPTION 'package_json is required' USING ERRCODE='22023';
  END IF;
  IF NEW.source_project_ids IS NULL OR array_length(NEW.source_project_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'source_project_ids must be non-empty' USING ERRCODE='22023';
  END IF;

  _has_parent := false;
  FOREACH _sp_id IN ARRAY NEW.source_project_ids LOOP
    IF _sp_id = NEW.project_id THEN _has_parent := true; END IF;
    SELECT (organization_id <> _r.organization_id) INTO _other_org
      FROM public.projects WHERE id = _sp_id;
    IF _other_org IS NULL THEN
      RAISE EXCEPTION 'Source project % not found', _sp_id USING ERRCODE='P0002';
    END IF;
    IF _other_org THEN
      RAISE EXCEPTION 'Source project % must be in the same organization as the parent project', _sp_id USING ERRCODE='22023';
    END IF;
  END LOOP;
  IF NOT _has_parent THEN
    RAISE EXCEPTION 'source_project_ids must include the parent project id' USING ERRCODE='22023';
  END IF;

  -- DC.16: bundle fields
  IF NEW.package_format NOT IN ('json_only','zip_bundle') THEN
    RAISE EXCEPTION 'Invalid package_format %', NEW.package_format USING ERRCODE='22023';
  END IF;
  IF NEW.bundle_status NOT IN ('not_generated','generated','partial','failed') THEN
    RAISE EXCEPTION 'Invalid bundle_status %', NEW.bundle_status USING ERRCODE='22023';
  END IF;
  IF NEW.bundle_size_bytes IS NOT NULL AND NEW.bundle_size_bytes < 0 THEN
    RAISE EXCEPTION 'bundle_size_bytes must be >= 0' USING ERRCODE='22023';
  END IF;
  IF NEW.bundle_file_count IS NOT NULL AND NEW.bundle_file_count < 0 THEN
    RAISE EXCEPTION 'bundle_file_count must be >= 0' USING ERRCODE='22023';
  END IF;
  IF NEW.bundle_packaged_file_count IS NOT NULL AND NEW.bundle_packaged_file_count < 0 THEN
    RAISE EXCEPTION 'bundle_packaged_file_count must be >= 0' USING ERRCODE='22023';
  END IF;
  IF NEW.bundle_failed_file_count IS NOT NULL AND NEW.bundle_failed_file_count < 0 THEN
    RAISE EXCEPTION 'bundle_failed_file_count must be >= 0' USING ERRCODE='22023';
  END IF;
  IF NEW.bundle_metadata_only_count IS NOT NULL AND NEW.bundle_metadata_only_count < 0 THEN
    RAISE EXCEPTION 'bundle_metadata_only_count must be >= 0' USING ERRCODE='22023';
  END IF;
  IF NEW.package_format = 'zip_bundle' AND NEW.bundle_status IN ('generated','partial') THEN
    IF NEW.bundle_storage_bucket IS NULL OR length(trim(NEW.bundle_storage_bucket)) = 0 THEN
      RAISE EXCEPTION 'bundle_storage_bucket required when bundle is generated' USING ERRCODE='22023';
    END IF;
    IF NEW.bundle_storage_path IS NULL OR length(trim(NEW.bundle_storage_path)) = 0 THEN
      RAISE EXCEPTION 'bundle_storage_path required when bundle is generated' USING ERRCODE='22023';
    END IF;
    IF NEW.bundle_filename IS NULL OR length(trim(NEW.bundle_filename)) = 0 THEN
      RAISE EXCEPTION 'bundle_filename required when bundle is generated' USING ERRCODE='22023';
    END IF;
    IF NEW.bundle_hash IS NULL OR length(trim(NEW.bundle_hash)) = 0 THEN
      RAISE EXCEPTION 'bundle_hash required when bundle is generated' USING ERRCODE='22023';
    END IF;
    IF NEW.bundle_size_bytes IS NULL THEN
      RAISE EXCEPTION 'bundle_size_bytes required when bundle is generated' USING ERRCODE='22023';
    END IF;
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: trg_gcpl_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_gcpl_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _r record;
  _lp record;
  _dep record;
BEGIN
  SELECT organization_id, workspace_id, project_id, record_kind INTO _r
    FROM public.governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF _r.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Cross-project links are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: cross-project link must inherit parent record scope' USING ERRCODE='22023';
  END IF;

  SELECT id, organization_id, workspace_id INTO _lp
    FROM public.projects WHERE id = NEW.linked_project_id;
  IF _lp IS NULL THEN
    RAISE EXCEPTION 'Linked project % not found', NEW.linked_project_id USING ERRCODE='P0002';
  END IF;
  IF NEW.linked_project_id = _r.project_id THEN
    RAISE EXCEPTION 'Cross-project link cannot reference the parent project itself' USING ERRCODE='22023';
  END IF;
  IF _lp.organization_id <> _r.organization_id THEN
    RAISE EXCEPTION 'Linked project must be in the same organization as the parent project' USING ERRCODE='22023';
  END IF;
  IF NEW.linked_project_workspace_id <> _lp.workspace_id THEN
    RAISE EXCEPTION 'linked_project_workspace_id must match the linked project workspace' USING ERRCODE='22023';
  END IF;

  IF NEW.relationship_type NOT IN
     ('formal_dependency','shared_risk','shared_blocker','shared_milestone','manual_related','other') THEN
    RAISE EXCEPTION 'Invalid relationship_type %', NEW.relationship_type USING ERRCODE='22023';
  END IF;

  IF NEW.source_dependency_id IS NOT NULL THEN
    SELECT source_type, source_id, target_type, target_id INTO _dep
      FROM public.dependencies WHERE id = NEW.source_dependency_id;
    IF _dep IS NULL THEN
      RAISE EXCEPTION 'Source dependency % not found', NEW.source_dependency_id USING ERRCODE='P0002';
    END IF;
    IF _dep.source_type <> 'project' OR _dep.target_type <> 'project' THEN
      RAISE EXCEPTION 'Source dependency must be a project-to-project dependency' USING ERRCODE='22023';
    END IF;
    IF NOT (
      (_dep.source_id = _r.project_id AND _dep.target_id = NEW.linked_project_id) OR
      (_dep.source_id = NEW.linked_project_id AND _dep.target_id = _r.project_id)
    ) THEN
      RAISE EXCEPTION 'Source dependency does not connect parent project and linked project' USING ERRCODE='22023';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


