--
-- Name: trg_gdo_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_gdo_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _r record;
BEGIN
  SELECT organization_id, workspace_id, project_id, record_kind INTO _r
    FROM public.governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF _r.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Decision outcomes are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: decision outcome must inherit parent record scope' USING ERRCODE='22023';
  END IF;
  IF NEW.decision_result NOT IN ('approved','approved_with_conditions','rejected','deferred') THEN
    RAISE EXCEPTION 'Invalid decision_result %', NEW.decision_result USING ERRCODE='22023';
  END IF;
  IF NEW.signoff_status NOT IN ('draft','ready_for_signoff','signed_off') THEN
    RAISE EXCEPTION 'Invalid signoff_status %', NEW.signoff_status USING ERRCODE='22023';
  END IF;
  IF NEW.final_decision_text IS NULL OR length(trim(NEW.final_decision_text)) = 0 THEN
    RAISE EXCEPTION 'final_decision_text is required' USING ERRCODE='22023';
  END IF;
  IF NEW.decision_date IS NULL THEN
    RAISE EXCEPTION 'decision_date is required' USING ERRCODE='22023';
  END IF;
  -- 4D.12L.7b: format-aware. Encrypted values (btpmenc:...) bypass the
  -- plaintext prefix check. Plaintext validation is preserved as-is.
  IF NEW.signoff_evidence_url IS NOT NULL
     AND (
       TG_OP = 'INSERT'
       OR NEW.signoff_evidence_url IS DISTINCT FROM OLD.signoff_evidence_url
     )
     AND left(NEW.signoff_evidence_url, 8) <> 'btpmenc:'
     AND NEW.signoff_evidence_url NOT LIKE 'http://%'
     AND NEW.signoff_evidence_url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'signoff_evidence_url must start with http:// or https://' USING ERRCODE='22023';
  END IF;
  IF NEW.implementation_owner_stakeholder_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.project_stakeholders s
      WHERE s.id = NEW.implementation_owner_stakeholder_id AND s.project_id = NEW.project_id
    ) THEN
      RAISE EXCEPTION 'Implementation owner stakeholder does not belong to this project' USING ERRCODE='22023';
    END IF;
  END IF;
  RETURN NEW;
END; $$;


