--
-- Name: trg_gref_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_gref_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _r record;
BEGIN
  SELECT organization_id, workspace_id, project_id, record_kind INTO _r
  FROM governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF _r.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Evidence files are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: evidence file must match parent record scope' USING ERRCODE='22023';
  END IF;
  IF NEW.source_system IS DISTINCT FROM 'sharepoint' THEN
    RAISE EXCEPTION 'Unsupported source_system' USING ERRCODE='22023';
  END IF;
  IF NEW.relevance_level NOT IN ('high','medium','low') THEN
    RAISE EXCEPTION 'Invalid relevance_level' USING ERRCODE='22023';
  END IF;
  IF coalesce(trim(NEW.site_id),'') = ''
     OR coalesce(trim(NEW.drive_id),'') = ''
     OR coalesce(trim(NEW.item_id),'') = ''
     OR coalesce(trim(NEW.item_reference_hash),'') = ''
     OR coalesce(trim(NEW.file_name),'') = ''
     OR coalesce(trim(NEW.evidence_title),'') = '' THEN
    RAISE EXCEPTION 'Required SharePoint reference fields missing' USING ERRCODE='22023';
  END IF;
  IF NEW.size_bytes IS NOT NULL AND NEW.size_bytes < 0 THEN
    RAISE EXCEPTION 'size_bytes must be >= 0' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END; $$;


