--
-- Name: trg_grl_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_grl_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _r record; _ok boolean;
BEGIN
  SELECT organization_id, workspace_id, project_id INTO _r
  FROM governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: link must match parent record scope' USING ERRCODE='22023';
  END IF;
  -- Validate the linked object belongs to the same project. Fail closed.
  _ok := false;
  IF NEW.linked_object_type = 'phase' THEN
    SELECT EXISTS(SELECT 1 FROM phases WHERE id = NEW.linked_object_id AND project_id = NEW.project_id) INTO _ok;
  ELSIF NEW.linked_object_type = 'task' THEN
    SELECT EXISTS(
      SELECT 1 FROM tasks t JOIN phases ph ON ph.id = t.phase_id
      WHERE t.id = NEW.linked_object_id AND ph.project_id = NEW.project_id) INTO _ok;
  ELSIF NEW.linked_object_type = 'risk' THEN
    SELECT EXISTS(SELECT 1 FROM risks WHERE id = NEW.linked_object_id
      AND target_type = 'project' AND target_id = NEW.project_id) INTO _ok;
    IF NOT _ok THEN
      -- also accept risks linked to a phase/task in this project
      SELECT EXISTS(
        SELECT 1 FROM risks r WHERE r.id = NEW.linked_object_id AND (
          (r.target_type = 'phase' AND EXISTS(SELECT 1 FROM phases p WHERE p.id = r.target_id AND p.project_id = NEW.project_id))
          OR
          (r.target_type = 'task' AND EXISTS(
             SELECT 1 FROM tasks t JOIN phases p ON p.id = t.phase_id
             WHERE t.id = r.target_id AND p.project_id = NEW.project_id))
        )
      ) INTO _ok;
    END IF;
  ELSIF NEW.linked_object_type = 'blocker' THEN
    SELECT EXISTS(SELECT 1 FROM blockers WHERE id = NEW.linked_object_id
      AND target_type = 'project' AND target_id = NEW.project_id) INTO _ok;
    IF NOT _ok THEN
      SELECT EXISTS(
        SELECT 1 FROM blockers b WHERE b.id = NEW.linked_object_id AND (
          (b.target_type = 'phase' AND EXISTS(SELECT 1 FROM phases p WHERE p.id = b.target_id AND p.project_id = NEW.project_id))
          OR
          (b.target_type = 'task' AND EXISTS(
             SELECT 1 FROM tasks t JOIN phases p ON p.id = t.phase_id
             WHERE t.id = b.target_id AND p.project_id = NEW.project_id))
        )
      ) INTO _ok;
    END IF;
  ELSIF NEW.linked_object_type = 'kpi_definition' THEN
    SELECT EXISTS(SELECT 1 FROM kpi_definitions WHERE id = NEW.linked_object_id AND project_id = NEW.project_id) INTO _ok;
  ELSIF NEW.linked_object_type = 'kpi_update' THEN
    SELECT EXISTS(
      SELECT 1 FROM kpi_updates ku JOIN kpi_definitions kd ON kd.id = ku.kpi_definition_id
      WHERE ku.id = NEW.linked_object_id AND kd.project_id = NEW.project_id) INTO _ok;
  END IF;
  IF NOT _ok THEN
    RAISE EXCEPTION 'Linked object %/% not found within project %',
      NEW.linked_object_type, NEW.linked_object_id, NEW.project_id USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: trg_gsp_scope_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_gsp_scope_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _r record;
BEGIN
  SELECT organization_id, workspace_id, project_id, record_kind INTO _r
    FROM public.governance_records WHERE id = NEW.governance_record_id;
  IF _r IS NULL THEN
    RAISE EXCEPTION 'Governance record % not found', NEW.governance_record_id USING ERRCODE='P0002';
  END IF;
  IF _r.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Stakeholder packages are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;
  IF NEW.organization_id <> _r.organization_id
     OR NEW.workspace_id <> _r.workspace_id
     OR NEW.project_id <> _r.project_id THEN
    RAISE EXCEPTION 'Scope mismatch: stakeholder package must inherit parent record scope' USING ERRCODE='22023';
  END IF;
  IF NEW.package_status NOT IN ('draft','ready','provided') THEN
    RAISE EXCEPTION 'Invalid package_status %', NEW.package_status USING ERRCODE='22023';
  END IF;
  IF NEW.version_number IS NULL OR NEW.version_number <= 0 THEN
    RAISE EXCEPTION 'version_number must be positive' USING ERRCODE='22023';
  END IF;
  IF NEW.package_title IS NULL OR length(trim(NEW.package_title)) = 0 THEN
    RAISE EXCEPTION 'package_title is required' USING ERRCODE='22023';
  END IF;
  -- 4D.12L.7b: format-aware. Encrypted values (btpmenc:...) bypass the
  -- plaintext prefix check. Plaintext validation is preserved as-is.
  IF NEW.distribution_evidence_url IS NOT NULL
     AND (
       TG_OP = 'INSERT'
       OR NEW.distribution_evidence_url IS DISTINCT FROM OLD.distribution_evidence_url
     )
     AND left(NEW.distribution_evidence_url, 8) <> 'btpmenc:'
     AND NEW.distribution_evidence_url NOT LIKE 'http://%'
     AND NEW.distribution_evidence_url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'distribution_evidence_url must start with http:// or https://' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END; $$;


