--
-- Name: trg_portfolio_item_team_members_assert_row_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_portfolio_item_team_members_assert_row_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  _parent_org uuid;
  _parent_found boolean := false;
  _profile_active boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- A. Parent Portfolio containment (organization derived server-side)
    SELECT p.organization_id, true INTO _parent_org, _parent_found
    FROM public.portfolio_items p
    WHERE p.id = NEW.portfolio_item_id;

    IF NOT COALESCE(_parent_found, false) THEN
      RAISE EXCEPTION 'portfolio_team_parent_portfolio_not_found' USING ERRCODE = '23503';
    END IF;

    IF NEW.organization_id IS DISTINCT FROM _parent_org THEN
      RAISE EXCEPTION 'portfolio_team_organization_mismatch' USING ERRCODE = '23514';
    END IF;

    -- C. Active-member eligibility on INSERT
    IF COALESCE(NEW.is_active, false) THEN
      IF public.is_user_org_member(NEW.user_id, _parent_org) IS NOT TRUE THEN
        RAISE EXCEPTION 'portfolio_team_member_not_organization_member' USING ERRCODE = '42501';
      END IF;

      SELECT pr.is_active INTO _profile_active
      FROM public.profiles pr
      WHERE pr.id = NEW.user_id;

      IF _profile_active IS NULL THEN
        RAISE EXCEPTION 'portfolio_team_member_profile_not_found' USING ERRCODE = '23503';
      END IF;

      IF _profile_active IS NOT TRUE THEN
        RAISE EXCEPTION 'portfolio_team_member_profile_inactive' USING ERRCODE = '42501';
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  -- B. Immutable Team-row identity
  IF NEW.portfolio_item_id IS DISTINCT FROM OLD.portfolio_item_id THEN
    RAISE EXCEPTION 'portfolio_team_portfolio_item_immutable' USING ERRCODE = '42501';
  END IF;

  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'portfolio_team_organization_immutable' USING ERRCODE = '42501';
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'portfolio_team_user_immutable' USING ERRCODE = '42501';
  END IF;

  -- D. Reactivation eligibility (false -> true only). E. everything else unchanged.
  IF COALESCE(OLD.is_active, false) = false AND COALESCE(NEW.is_active, false) = true THEN
    SELECT p.organization_id INTO _parent_org
    FROM public.portfolio_items p
    WHERE p.id = NEW.portfolio_item_id;

    IF _parent_org IS NULL THEN
      RAISE EXCEPTION 'portfolio_team_parent_portfolio_not_found' USING ERRCODE = '23503';
    END IF;

    IF public.is_user_org_member(NEW.user_id, _parent_org) IS NOT TRUE THEN
      RAISE EXCEPTION 'portfolio_team_member_not_organization_member' USING ERRCODE = '42501';
    END IF;

    SELECT pr.is_active INTO _profile_active
    FROM public.profiles pr
    WHERE pr.id = NEW.user_id;

    IF _profile_active IS NULL THEN
      RAISE EXCEPTION 'portfolio_team_member_profile_not_found' USING ERRCODE = '23503';
    END IF;

    IF _profile_active IS NOT TRUE THEN
      RAISE EXCEPTION 'portfolio_team_member_profile_inactive' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END
$$;


