--
-- Name: trg_produce_mention_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_produce_mention_notifications() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_mention record;
  v_target_name text;
  v_project_id uuid;
  v_project_name text;
  v_idem text;
  v_payload text;
  v_has_captures boolean;
BEGIN
  IF NEW.target_type NOT IN ('task', 'phase') THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT EXISTS (SELECT 1 FROM _mention_capture WHERE comment_id = NEW.id)
      INTO v_has_captures;
  EXCEPTION WHEN undefined_table THEN
    RETURN NEW;
  END;

  IF NOT v_has_captures THEN
    RETURN NEW;
  END IF;

  IF NEW.target_type = 'task' THEN
    SELECT t.name, t.project_id INTO v_target_name, v_project_id
      FROM tasks t WHERE t.id = NEW.target_id;
  ELSIF NEW.target_type = 'phase' THEN
    SELECT ph.name, ph.project_id INTO v_target_name, v_project_id
      FROM phases ph WHERE ph.id = NEW.target_id;
  END IF;

  IF v_project_id IS NOT NULL THEN
    SELECT p.name INTO v_project_name FROM projects p WHERE p.id = v_project_id;
  END IF;

  FOR v_mention IN
    SELECT mentioned_user_id FROM _mention_capture WHERE comment_id = NEW.id
  LOOP
    v_idem := 'mention:' || NEW.id || ':' || v_mention.mentioned_user_id;

    v_payload := json_build_object(
      'target_name', COALESCE(v_target_name, ''),
      'project_name', COALESCE(v_project_name, ''),
      'target_type', NEW.target_type,
      'target_id', NEW.target_id,
      'project_id', v_project_id,
      'workspace_id', NEW.workspace_id
    )::text;

    INSERT INTO notification_outbox (
      event_type, recipient_id, actor_id, target_type, target_id,
      workspace_id, organization_id, payload, idempotency_key, source_comment_id
    ) VALUES (
      'mention', v_mention.mentioned_user_id, NEW.author_id,
      NEW.target_type, NEW.target_id,
      NEW.workspace_id, NEW.organization_id, v_payload, v_idem, NEW.id
    ) ON CONFLICT (idempotency_key) DO NOTHING;
  END LOOP;

  DELETE FROM _mention_capture WHERE comment_id = NEW.id;

  RETURN NEW;
END;
$$;


