--
-- Name: unarchive_backlog_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unarchive_backlog_item(_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _row backlog_items%ROWTYPE;
BEGIN
  SELECT * INTO _row FROM backlog_items WHERE id = _id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Backlog item not found' USING ERRCODE='P0002'; END IF;
  PERFORM _assert_pm_or_admin(_row.workspace_id, _row.organization_id);
  IF _row.is_archived THEN
    UPDATE backlog_items SET is_archived=false, updated_at=now() WHERE id=_id;
    PERFORM log_activity_event(_row.organization_id, auth.uid(), 'backlog_item_unarchived', 'backlog_item', _id, '{}'::jsonb, _row.workspace_id);
  END IF;
END; $$;


