END;
$$;


--
-- Name: upsert_governance_record_decision_outcome(uuid, text, text, date, text, text, text, text, text, text, uuid, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_governance_record_decision_outcome(_record_id uuid, _decision_result text, _final_decision_text text, _decision_date date, _decided_by_text text DEFAULT NULL::text, _approval_forum text DEFAULT NULL::text, _decision_rationale text DEFAULT NULL::text, _conditions_guardrails text DEFAULT NULL::text, _residual_risks text DEFAULT NULL::text, _follow_up_actions text DEFAULT NULL::text, _implementation_owner_stakeholder_id uuid DEFAULT NULL::uuid, _implementation_target_date date DEFAULT NULL::date, _signoff_status text DEFAULT 'draft'::text, _signoff_evidence_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _row public.governance_records%ROWTYPE;
  _existing_id uuid;
  _existing_closed_at timestamptz;
  _id uuid;
  _final text; _decided text; _forum text; _rat text; _cond text; _risks text; _follow text; _url text;
  _stk_project_id uuid;
  _stk_org_id uuid;
  _stk_workspace_id uuid;
  _stk_type text;
  _stk_user_id uuid;
  _stk_removed_at timestamptz;
  v_client_id text;
  v_caller uuid;
BEGIN
  BEGIN
    v_client_id := api_e_private.jwt_client_id();
  EXCEPTION WHEN OTHERS THEN
    v_client_id := 'unresolved_client';
  END;
  IF v_client_id IS NOT NULL THEN
    RAISE EXCEPTION 'Not authorized'
      USING ERRCODE = '42501';
  END IF;

  v_caller := auth.uid();
  IF v_caller IS NULL OR NOT public.is_active_user(v_caller) THEN
    RAISE EXCEPTION 'Unauthorized'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO _row FROM public.governance_records WHERE id = _record_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Record not found' USING ERRCODE='P0002'; END IF;

  PERFORM public._gov_assert_project_write(_row.project_id);

  IF _row.record_kind IS DISTINCT FROM 'decision_case' THEN
    RAISE EXCEPTION 'Decision outcomes are only allowed on decision_case records' USING ERRCODE='22023';
  END IF;

  IF _row.decision_stage = 'closed' THEN
    RAISE EXCEPTION 'Closed decision cases cannot be edited' USING ERRCODE='22023';
  END IF;

  IF _decision_result NOT IN ('approved','approved_with_conditions','rejected','deferred') THEN
    RAISE EXCEPTION 'Invalid decision_result %', _decision_result USING ERRCODE='22023';
  END IF;
  IF _signoff_status NOT IN ('draft','ready_for_signoff','signed_off') THEN
    RAISE EXCEPTION 'Invalid signoff_status %', _signoff_status USING ERRCODE='22023';
  END IF;

  _final := NULLIF(trim(COALESCE(_final_decision_text, '')), '');
  IF _final IS NULL THEN
    RAISE EXCEPTION 'final_decision_text is required' USING ERRCODE='22023';
  END IF;
  IF _decision_date IS NULL THEN
    RAISE EXCEPTION 'decision_date is required' USING ERRCODE='22023';
  END IF;

  _decided := NULLIF(trim(COALESCE(_decided_by_text, '')), '');
  _forum   := NULLIF(trim(COALESCE(_approval_forum, '')), '');
  _rat     := NULLIF(trim(COALESCE(_decision_rationale, '')), '');
  _cond    := NULLIF(trim(COALESCE(_conditions_guardrails, '')), '');
  _risks   := NULLIF(trim(COALESCE(_residual_risks, '')), '');
  _follow  := NULLIF(trim(COALESCE(_follow_up_actions, '')), '');
  _url     := NULLIF(trim(COALESCE(_signoff_evidence_url, '')), '');

  IF _url IS NOT NULL AND _url NOT LIKE 'http://%' AND _url NOT LIKE 'https://%' THEN
    RAISE EXCEPTION 'signoff_evidence_url must start with http:// or https://' USING ERRCODE='22023';
  END IF;

  IF _implementation_owner_stakeholder_id IS NOT NULL THEN
    SELECT s.project_id, s.organization_id, s.workspace_id, s.stakeholder_type, s.user_id, s.removed_at
      INTO _stk_project_id, _stk_org_id, _stk_workspace_id, _stk_type, _stk_user_id, _stk_removed_at
      FROM public.project_stakeholders s
     WHERE s.id = _implementation_owner_stakeholder_id;

    IF _stk_project_id IS NULL
       OR _stk_project_id IS DISTINCT FROM _row.project_id
       OR _stk_org_id IS DISTINCT FROM _row.organization_id
       OR _stk_workspace_id IS DISTINCT FROM _row.workspace_id
       OR _stk_removed_at IS NOT NULL THEN
      RAISE EXCEPTION 'Implementation owner stakeholder does not belong to this project' USING ERRCODE='22023';
    END IF;

    IF _stk_type = 'workspace_member' THEN
      IF _stk_user_id IS NULL
         OR NOT public.is_active_user(_stk_user_id)
         OR public.is_user_org_member(_stk_user_id, _row.organization_id) IS NOT TRUE
         OR public.is_user_workspace_member(_stk_user_id, _row.workspace_id) IS NOT TRUE THEN
        RAISE EXCEPTION 'Implementation owner stakeholder does not belong to this project' USING ERRCODE='22023';
      END IF;
    END IF;
  END IF;

  SELECT id, closed_at INTO _existing_id, _existing_closed_at
    FROM public.governance_record_decision_outcomes
   WHERE governance_record_id = _record_id;

  IF _existing_id IS NOT NULL AND _existing_closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Closed decision cases cannot be edited' USING ERRCODE='22023';
  END IF;

  IF _existing_id IS NULL THEN
    INSERT INTO public.governance_record_decision_outcomes (
      organization_id, workspace_id, project_id, governance_record_id,
      decision_result, final_decision_text, decision_date,
      decided_by_text, approval_forum, decision_rationale,
      conditions_guardrails, residual_risks, follow_up_actions,
      implementation_owner_stakeholder_id, implementation_target_date,
      signoff_status, signoff_evidence_url,
      created_by, updated_by
    ) VALUES (
      _row.organization_id, _row.workspace_id, _row.project_id, _record_id,
      _decision_result, _final, _decision_date,
      _decided, _forum, _rat,
      _cond, _risks, _follow,
      _implementation_owner_stakeholder_id, _implementation_target_date,
      _signoff_status, _url,
      v_caller, v_caller
    )
    RETURNING id INTO _id;
  ELSE
    UPDATE public.governance_record_decision_outcomes SET
      decision_result = _decision_result,
      final_decision_text = _final,
      decision_date = _decision_date,
      decided_by_text = _decided,
      approval_forum = _forum,
      decision_rationale = _rat,
      conditions_guardrails = _cond,
      residual_risks = _risks,
      follow_up_actions = _follow,
      implementation_owner_stakeholder_id = _implementation_owner_stakeholder_id,
      implementation_target_date = _implementation_target_date,
      signoff_status = _signoff_status,
      signoff_evidence_url = _url,
      updated_by = v_caller,
      updated_at = now()
    WHERE id = _existing_id
    RETURNING id INTO _id;
  END IF;

  IF _row.decision_stage IS DISTINCT FROM 'closed' THEN
    UPDATE public.governance_records
       SET decision_stage = 'decision_taken', updated_at = now()
     WHERE id = _record_id AND decision_stage IS DISTINCT FROM 'closed';
  END IF;

  PERFORM public.log_activity_event(_row.organization_id, v_caller,
    'governance_record_decision_outcome_saved', 'governance_record', _record_id,
    jsonb_build_object('project_id', _row.project_id,
                       'decision_outcome_id', _id,
                       'decision_result', _decision_result,
                       'signoff_status', _signoff_status,
                       'decision_date', _decision_date),
    _row.workspace_id);

  RETURN _id;
END; $$;


--
-- Name: upsert_project_closure_summary(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_project_closure_summary(_project_id uuid, _outcome_summary text DEFAULT NULL::text, _benefits_summary text DEFAULT NULL::text, _achievements_summary text DEFAULT NULL::text, _open_items_summary text DEFAULT NULL::text, _transition_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _p record;
  _existing_id uuid;
  _id uuid;
  _proj_status text;
  _o text; _b text; _a text; _oi text; _tn text;
  _is_create boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Project-edit authority required' USING ERRCODE='42501';
  END IF;

  SELECT organization_id, workspace_id, status::text
    INTO _p FROM public.projects WHERE id = _project_id;
  IF _p IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;
  _proj_status := _p.status;

  -- Normalize: trim & convert empty strings to NULL
  _o  := NULLIF(btrim(COALESCE(_outcome_summary, '')), '');
  _b  := NULLIF(btrim(COALESCE(_benefits_summary, '')), '');
  _a  := NULLIF(btrim(COALESCE(_achievements_summary, '')), '');
  _oi := NULLIF(btrim(COALESCE(_open_items_summary, '')), '');
  _tn := NULLIF(btrim(COALESCE(_transition_notes, '')), '');

  IF _o IS NULL AND _b IS NULL AND _a IS NULL AND _oi IS NULL AND _tn IS NULL THEN
    RAISE EXCEPTION 'Enter at least one closure summary field before saving.'
      USING ERRCODE='22023';
  END IF;

  -- Optional length guardrails (per-field 4000 chars)
  IF length(COALESCE(_o,''))  > 4000
     OR length(COALESCE(_b,''))  > 4000
     OR length(COALESCE(_a,''))  > 4000
     OR length(COALESCE(_oi,'')) > 4000
     OR length(COALESCE(_tn,'')) > 4000 THEN
    RAISE EXCEPTION 'Each closure summary field must be 4000 characters or fewer.'
      USING ERRCODE='22023';
  END IF;

  SELECT id INTO _existing_id
    FROM public.project_closure_summaries WHERE project_id = _project_id;

  IF _existing_id IS NULL THEN
    _is_create := true;
    INSERT INTO public.project_closure_summaries (
      organization_id, workspace_id, project_id,
      outcome_summary_encrypted, benefits_summary_encrypted,
      achievements_summary_encrypted, open_items_summary_encrypted,
      transition_notes_encrypted, created_by, updated_by
    ) VALUES (
      _p.organization_id, _p.workspace_id, _project_id,
      _o, _b, _a, _oi, _tn, auth.uid(), auth.uid()
    ) RETURNING id INTO _id;
  ELSE
    _is_create := false;
    UPDATE public.project_closure_summaries SET
      outcome_summary_encrypted      = _o,
      benefits_summary_encrypted     = _b,
      achievements_summary_encrypted = _a,
      open_items_summary_encrypted   = _oi,
      transition_notes_encrypted     = _tn,
      updated_by                     = auth.uid(),
      updated_at                     = now()
    WHERE id = _existing_id;
    _id := _existing_id;
  END IF;

  PERFORM public.log_activity_event(
    _p.organization_id, auth.uid(),
    CASE WHEN _is_create
         THEN 'project_closure_summary_created'
         ELSE 'project_closure_summary_updated' END,
    'project_closure_summary', _id,
    jsonb_build_object(
      'project_id', _project_id,
      'project_status_at_event', _proj_status,
      'post_closure', (_proj_status IN ('completed','cancelled'))
    ),
    _p.workspace_id);

  RETURN _id;
END;
$$;


--
-- Name: upsert_project_lessons_learned_document_metadata(uuid, text, text, text, text, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_project_lessons_learned_document_metadata(_project_id uuid, _status text, _document_name text DEFAULT NULL::text, _sharepoint_web_url text DEFAULT NULL::text, _sharepoint_drive_id text DEFAULT NULL::text, _sharepoint_item_id text DEFAULT NULL::text, _created_in_sharepoint_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _last_modified_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _event_type text DEFAULT 'project_lessons_learned_document_status_changed'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  _p record;
  _existing record;
  _id uuid;
  _prev_status text;
  _is_create boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';
  END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'Project-edit authority required' USING ERRCODE='42501';
  END IF;

  IF _status NOT IN ('not_created','available','missing_folder','creation_failed','link_broken') THEN
    RAISE EXCEPTION 'Invalid status: %', _status USING ERRCODE='22023';
  END IF;

  SELECT organization_id, workspace_id INTO _p
    FROM public.projects WHERE id = _project_id;
  IF _p IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE='P0002';
  END IF;

  SELECT id, status INTO _existing
    FROM public.project_lessons_learned_documents WHERE project_id = _project_id;

  IF _existing.id IS NULL THEN
    _is_create := true;
    INSERT INTO public.project_lessons_learned_documents (
      organization_id, workspace_id, project_id,
      document_name_encrypted, sharepoint_web_url_encrypted,
      sharepoint_drive_id_encrypted, sharepoint_item_id_encrypted,
      created_in_sharepoint_at, last_modified_at,
      status, created_by, metadata_refreshed_at
    ) VALUES (
      _p.organization_id, _p.workspace_id, _project_id,
      _document_name, _sharepoint_web_url, _sharepoint_drive_id, _sharepoint_item_id,
      _created_in_sharepoint_at, _last_modified_at,
      _status, auth.uid(), now()
    ) RETURNING id INTO _id;
    _prev_status := NULL;
  ELSE
    _id := _existing.id;
    _prev_status := _existing.status;
    -- For non-available statuses, preserve prior encrypted fields when caller passes NULL
    UPDATE public.project_lessons_learned_documents SET
      document_name_encrypted       = COALESCE(_document_name, document_name_encrypted),
      sharepoint_web_url_encrypted  = COALESCE(_sharepoint_web_url, sharepoint_web_url_encrypted),
      sharepoint_drive_id_encrypted = COALESCE(_sharepoint_drive_id, sharepoint_drive_id_encrypted),
      sharepoint_item_id_encrypted  = COALESCE(_sharepoint_item_id, sharepoint_item_id_encrypted),
      created_in_sharepoint_at      = COALESCE(_created_in_sharepoint_at, created_in_sharepoint_at),
      last_modified_at              = COALESCE(_last_modified_at, last_modified_at),
      status                        = _status,
      metadata_refreshed_at         = now()
    WHERE id = _id;
  END IF;

  PERFORM public.log_activity_event(
    _p.organization_id, auth.uid(),
    _event_type, 'project_lessons_learned_document', _id,
    jsonb_build_object(
      'project_id', _project_id,
      'status', _status,
      'previous_status', _prev_status,
      'created', _is_create
    ),
    _p.workspace_id);

  RETURN _id;
END;
$$;


--
-- Name: upsert_sharepoint_org_site(uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_sharepoint_org_site(_organization_id uuid, _site_web_url text, _site_label_or_name text DEFAULT NULL::text, _site_id text DEFAULT NULL::text, _managed_outside_btpm boolean DEFAULT true) RETURNS public.sharepoint_org_site_connections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.sharepoint_org_site_connections;
  v_row public.sharepoint_org_site_connections;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;
  IF NOT public.is_org_admin(auth.uid(), _organization_id) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF _site_web_url IS NULL OR length(btrim(_site_web_url)) = 0 THEN
    RAISE EXCEPTION 'site_web_url_required';
  END IF;

  SELECT * INTO v_existing
  FROM public.sharepoint_org_site_connections
  WHERE organization_id = _organization_id
    AND connection_status <> 'disabled'
  LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    UPDATE public.sharepoint_org_site_connections
    SET site_web_url           = _site_web_url,
        site_label_or_name     = _site_label_or_name,
        site_id                = _site_id,
        managed_outside_btpm   = COALESCE(_managed_outside_btpm, true),
        connection_status      = 'configured_unvalidated',
        last_validated_at      = NULL,
        last_validation_code   = NULL,
        last_validation_note   = NULL
    WHERE id = v_existing.id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.sharepoint_org_site_connections (
      organization_id, site_web_url, site_label_or_name, site_id,
      managed_outside_btpm, connection_status, created_by
    ) VALUES (
      _organization_id, _site_web_url, _site_label_or_name, _site_id,
      COALESCE(_managed_outside_btpm, true), 'configured_unvalidated', auth.uid()
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END
$$;


--
-- Name: upsert_sharepoint_project_binding(uuid, public.sharepoint_project_binding_mode, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_sharepoint_project_binding(_project_id uuid, _binding_mode public.sharepoint_project_binding_mode, _folder_web_url text, _folder_relative_path text DEFAULT NULL::text, _folder_item_id text DEFAULT NULL::text, _resolved_site_web_url text DEFAULT NULL::text, _resolved_site_id text DEFAULT NULL::text, _resolved_library_web_url text DEFAULT NULL::text, _resolved_library_id_or_drive_id text DEFAULT NULL::text) RETURNS public.sharepoint_project_bindings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ws uuid; v_org uuid; v_existing public.sharepoint_project_bindings;
  v_row public.sharepoint_project_bindings; v_ws_binding_id uuid; v_is_restricted boolean;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'unauthorized'; END IF;
  SELECT workspace_id, organization_id INTO v_ws, v_org FROM public.projects WHERE id = _project_id;
  IF v_ws IS NULL THEN RAISE EXCEPTION 'project_not_found'; END IF;
  IF NOT public.has_project_pm_authority(auth.uid(), _project_id) THEN
    RAISE EXCEPTION 'unauthorized'; END IF;
  IF _folder_web_url IS NULL OR length(btrim(_folder_web_url)) = 0 THEN
    RAISE EXCEPTION 'folder_web_url_required'; END IF;
  IF _binding_mode = 'workspace_library_default' THEN
    SELECT id INTO v_ws_binding_id FROM public.sharepoint_workspace_bindings
    WHERE workspace_id = v_ws AND binding_status <> 'disabled' LIMIT 1;
    IF v_ws_binding_id IS NULL THEN RAISE EXCEPTION 'workspace_binding_required_for_default_mode'; END IF;
    v_is_restricted := false;
  ELSE
    IF _resolved_site_web_url IS NULL OR _resolved_library_web_url IS NULL THEN
      RAISE EXCEPTION 'resolved_site_and_library_required_for_restricted_mode'; END IF;
    v_ws_binding_id := NULL; v_is_restricted := true;
  END IF;
  SELECT * INTO v_existing FROM public.sharepoint_project_bindings
  WHERE project_id = _project_id AND binding_status <> 'disabled' LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
    UPDATE public.sharepoint_project_bindings
    SET binding_mode = _binding_mode, binding_status = 'linked_unvalidated',
        workspace_sharepoint_binding_id = v_ws_binding_id,
        folder_web_url = _folder_web_url, folder_relative_path = _folder_relative_path,
        folder_item_id = _folder_item_id,
        resolved_site_web_url = _resolved_site_web_url, resolved_site_id = _resolved_site_id,
        resolved_library_web_url = _resolved_library_web_url,
        resolved_library_id_or_drive_id = _resolved_library_id_or_drive_id,
        is_restricted = v_is_restricted, last_validated_at = NULL,
        last_validation_code = NULL, last_validation_note = NULL, updated_by = auth.uid()
    WHERE id = v_existing.id RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.sharepoint_project_bindings (organization_id, workspace_id, project_id,
      workspace_sharepoint_binding_id, binding_mode, binding_status,
      folder_web_url, folder_relative_path, folder_item_id,
      resolved_site_web_url, resolved_site_id,
      resolved_library_web_url, resolved_library_id_or_drive_id,
      is_restricted, created_by, updated_by)
    VALUES (v_org, v_ws, _project_id, v_ws_binding_id, _binding_mode, 'linked_unvalidated',
      _folder_web_url, _folder_relative_path, _folder_item_id,
      _resolved_site_web_url, _resolved_site_id,
      _resolved_library_web_url, _resolved_library_id_or_drive_id,
      v_is_restricted, auth.uid(), auth.uid()) RETURNING * INTO v_row;
  END IF;
  RETURN v_row;
END; $$;


--
-- Name: upsert_sharepoint_workspace_binding(uuid, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_sharepoint_workspace_binding(_workspace_id uuid, _site_web_url text DEFAULT NULL::text, _library_web_url text DEFAULT NULL::text, _site_label_or_name text DEFAULT NULL::text, _library_label_or_name text DEFAULT NULL::text, _site_id text DEFAULT NULL::text, _library_id_or_drive_id text DEFAULT NULL::text, _managed_outside_btpm boolean DEFAULT true) RETURNS public.sharepoint_workspace_bindings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_site public.sharepoint_org_site_connections;
  v_existing public.sharepoint_workspace_bindings;
  v_row public.sharepoint_workspace_bindings;
BEGIN
  IF NOT public.is_active_user(auth.uid()) THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  SELECT organization_id INTO v_org FROM public.workspaces WHERE id = _workspace_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'workspace_not_found';
  END IF;
  IF NOT public.is_org_admin(auth.uid(), v_org) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  -- The org-level SharePoint site MUST be configured first.
  SELECT * INTO v_site
  FROM public.sharepoint_org_site_connections
  WHERE organization_id = v_org
    AND connection_status <> 'disabled'
  LIMIT 1;
  IF v_site.id IS NULL THEN
    RAISE EXCEPTION 'org_site_not_configured';
  END IF;

  IF _library_web_url IS NULL OR length(btrim(_library_web_url)) = 0 THEN
    RAISE EXCEPTION 'library_web_url_required';
  END IF;

  -- Validate library belongs to the configured org site (prefix match,
  -- case-insensitive, tolerant of trailing slash).
  IF lower(btrim(_library_web_url)) NOT LIKE lower(rtrim(v_site.site_web_url, '/')) || '%' THEN
    RAISE EXCEPTION 'library_outside_org_site';
  END IF;

  SELECT * INTO v_existing
  FROM public.sharepoint_workspace_bindings
  WHERE workspace_id = _workspace_id
    AND binding_status <> 'disabled'
  LIMIT 1;

  IF v_existing.id IS NOT NULL THEN
    UPDATE public.sharepoint_workspace_bindings
    SET site_web_url           = v_site.site_web_url,
        site_id                = v_site.site_id,
        site_label_or_name     = COALESCE(v_site.site_label_or_name, _site_label_or_name),
        library_web_url        = _library_web_url,
        library_label_or_name  = _library_label_or_name,
        library_id_or_drive_id = _library_id_or_drive_id,
        managed_outside_btpm   = COALESCE(_managed_outside_btpm, true),
        binding_status         = 'configured_unvalidated',
        last_validated_at      = NULL,
        last_validation_code   = NULL,
        last_validation_note   = NULL,
        updated_by             = auth.uid()
    WHERE id = v_existing.id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.sharepoint_workspace_bindings (
      organization_id, workspace_id,
      site_web_url, library_web_url, site_label_or_name, library_label_or_name,
      site_id, library_id_or_drive_id, managed_outside_btpm,
      binding_status, created_by
    ) VALUES (
      v_org, _workspace_id,
      v_site.site_web_url, _library_web_url,
      COALESCE(v_site.site_label_or_name, _site_label_or_name),
      _library_label_or_name,
      v_site.site_id, _library_id_or_drive_id, COALESCE(_managed_outside_btpm, true),
      'configured_unvalidated', auth.uid()
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN v_row;
END
$$;


--
-- Name: upsert_user_saved_view(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_user_saved_view(_id uuid, _surface_key text, _scope_key text, _name text, _state jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_org  uuid;
  v_id   uuid;
  v_row  jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF _name IS NULL OR length(btrim(_name)) = 0 THEN
    RAISE EXCEPTION 'name required';
  END IF;
  IF _state IS NULL THEN
    RAISE EXCEPTION 'state required';
  END IF;
  SELECT organization_id INTO v_org FROM public.profiles WHERE id = v_user;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization not resolved for user';
  END IF;

  IF _id IS NULL THEN
    INSERT INTO public.user_saved_views (
      organization_id, user_id, surface_key, scope_key, name, state_payload
    ) VALUES (
      v_org, v_user, _surface_key, COALESCE(_scope_key, 'global'),
      public.btpm_encrypt(btrim(_name), v_org),
      public.btpm_encrypt(_state::text, v_org)
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.user_saved_views
       SET name          = public.btpm_encrypt(btrim(_name), v_org),
           state_payload = public.btpm_encrypt(_state::text, v_org)
     WHERE id = _id
       AND user_id = v_user
       AND organization_id = v_org
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'saved view not found';
    END IF;
  END IF;

  SELECT jsonb_build_object(
    'id',         v.id,
    'name',       public.btpm_decrypt(v.name, v.organization_id),
    'state',      public.btpm_decrypt(v.state_payload, v.organization_id)::jsonb,
    'created_at', v.created_at,
    'updated_at', v.updated_at
  ) INTO v_row
  FROM public.user_saved_views v
  WHERE v.id = v_id;

  RETURN v_row;
END;
$$;


--
-- Name: validate_dependency_no_cycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_dependency_no_cycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_found boolean;
BEGIN
  -- A new edge source -> target creates a cycle iff target can already reach source
  -- via the existing graph (restricted to same source_type to match same-level rule).
  WITH RECURSIVE reach(node) AS (
    SELECT NEW.target_id
    UNION
    SELECT d.target_id
    FROM public.dependencies d
    JOIN reach r ON d.source_id = r.node
    WHERE d.source_type = NEW.source_type
  )
  SELECT EXISTS (SELECT 1 FROM reach WHERE node = NEW.source_id) INTO v_found;

  IF v_found THEN
    RAISE EXCEPTION 'Dependency would create a cycle (% -> %)', NEW.source_id, NEW.target_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: validate_dependency_same_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_dependency_same_level() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Must be same entity type
  IF NEW.source_type != NEW.target_type THEN
    RAISE EXCEPTION 'Dependencies must be same-level: source_type (%) must equal target_type (%)',
      NEW.source_type, NEW.target_type;
  END IF;

  -- Only allowed entity types
  IF NEW.source_type NOT IN ('project', 'phase', 'task') THEN
    RAISE EXCEPTION 'Dependencies only allowed on project, phase, or task (got: %)', NEW.source_type;
  END IF;

  -- No self-reference
  IF NEW.source_id = NEW.target_id THEN
    RAISE EXCEPTION 'A dependency cannot reference itself';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_invitation_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_invitation_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status NOT IN ('pending', 'accepted', 'declined', 'expired', 'revoked') THEN
    RAISE EXCEPTION 'Invalid invitation status: %', NEW.status;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_kpi_auto_snapshot_eligibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_kpi_auto_snapshot_eligibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If KPI is being archived, force auto_snapshot_enabled to false (UX-friendly path)
  IF NEW.is_archived = true AND NEW.auto_snapshot_enabled = true THEN
    NEW.auto_snapshot_enabled := false;
  END IF;

  -- If auto_snapshot_enabled is true, enforce eligibility
  IF NEW.auto_snapshot_enabled = true THEN
    IF NEW.source_mode <> 'automatic' THEN
      RAISE EXCEPTION 'auto_snapshot_enabled requires source_mode = automatic (got %)', NEW.source_mode
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.is_archived = true THEN
      RAISE EXCEPTION 'auto_snapshot_enabled cannot be true on an archived KPI'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.cadence IS NULL OR NEW.cadence NOT IN ('weekly','monthly','quarterly','yearly') THEN
      RAISE EXCEPTION 'auto_snapshot_enabled requires cadence in (weekly, monthly, quarterly, yearly); got %', NEW.cadence
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.calculation_key IS NULL THEN
      RAISE EXCEPTION 'auto_snapshot_enabled requires a calculation_key'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.calculation_key = 'schedule_signal' THEN
      RAISE EXCEPTION 'auto_snapshot_enabled is not allowed for calculation_key = schedule_signal'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_kpi_definition_target_level(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_kpi_definition_target_level() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.target_type NOT IN ('project', 'program') THEN
    RAISE EXCEPTION 'KPI definitions are only allowed at project or program level (got: %)', NEW.target_type;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_kpi_schedule_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_kpi_schedule_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ws_org uuid;
  v_paired RECORD;
  v_this_offset_min bigint;
  v_paired_offset_min bigint;
BEGIN
  -- (a) workspace belongs to organization_id
  SELECT organization_id INTO v_ws_org
  FROM public.workspaces
  WHERE id = NEW.workspace_id;

  IF v_ws_org IS NULL THEN
    RAISE EXCEPTION 'kpi_schedule_policies: workspace % not found', NEW.workspace_id;
  END IF;

  IF v_ws_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'kpi_schedule_policies: organization_id % does not match workspace organization %',
      NEW.organization_id, v_ws_org;
  END IF;

  -- (b) Cross-process ordering rule (C3.9g §6.7):
  -- For the same (workspace, cadence), kpi_app_auto_submit scheduled offset
  -- must NOT be earlier than automatic_snapshot_capture scheduled offset.
  -- Compared as (delay_days * 1440) + minutes-of-day.
  -- Only enforced when BOTH rows are active. If paired row is inactive or
  -- missing, save is allowed (Admin UX warning is C3.9j responsibility).
  IF NEW.is_active = true THEN
    IF NEW.process_type = 'kpi_app_auto_submit' THEN
      SELECT * INTO v_paired
      FROM public.kpi_schedule_policies
      WHERE workspace_id = NEW.workspace_id
        AND process_type = 'automatic_snapshot_capture'
        AND cadence = NEW.cadence
        AND is_active = true
        AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);

      IF v_paired IS NOT NULL AND v_paired.workspace_id IS NOT NULL THEN
        v_this_offset_min := (NEW.delay_days_after_period_close::bigint * 1440)
          + (EXTRACT(HOUR FROM NEW.run_time_utc)::bigint * 60)
          + EXTRACT(MINUTE FROM NEW.run_time_utc)::bigint;
        v_paired_offset_min := (v_paired.delay_days_after_period_close::bigint * 1440)
          + (EXTRACT(HOUR FROM v_paired.run_time_utc)::bigint * 60)
          + EXTRACT(MINUTE FROM v_paired.run_time_utc)::bigint;

        IF v_this_offset_min < v_paired_offset_min THEN
          RAISE EXCEPTION 'kpi_schedule_policies: kpi_app_auto_submit (%, +% day(s) %) must not run before automatic_snapshot_capture (+% day(s) %) for same workspace/cadence',
            NEW.cadence, NEW.delay_days_after_period_close, NEW.run_time_utc,
            v_paired.delay_days_after_period_close, v_paired.run_time_utc;
        END IF;
      END IF;
    ELSIF NEW.process_type = 'automatic_snapshot_capture' THEN
      SELECT * INTO v_paired
      FROM public.kpi_schedule_policies
      WHERE workspace_id = NEW.workspace_id
        AND process_type = 'kpi_app_auto_submit'
        AND cadence = NEW.cadence
        AND is_active = true
        AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);

      IF v_paired IS NOT NULL AND v_paired.workspace_id IS NOT NULL THEN
        v_this_offset_min := (NEW.delay_days_after_period_close::bigint * 1440)
          + (EXTRACT(HOUR FROM NEW.run_time_utc)::bigint * 60)
          + EXTRACT(MINUTE FROM NEW.run_time_utc)::bigint;
        v_paired_offset_min := (v_paired.delay_days_after_period_close::bigint * 1440)
          + (EXTRACT(HOUR FROM v_paired.run_time_utc)::bigint * 60)
          + EXTRACT(MINUTE FROM v_paired.run_time_utc)::bigint;

        IF v_paired_offset_min < v_this_offset_min THEN
          RAISE EXCEPTION 'kpi_schedule_policies: automatic_snapshot_capture (%, +% day(s) %) must not run after kpi_app_auto_submit (+% day(s) %) for same workspace/cadence',
            NEW.cadence, NEW.delay_days_after_period_close, NEW.run_time_utc,
            v_paired.delay_days_after_period_close, v_paired.run_time_utc;
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_kpi_update_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_kpi_update_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.kpi_definitions
    WHERE id = NEW.kpi_definition_id
      AND workspace_id = NEW.workspace_id
      AND organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'KPI update must match the KPI definition workspace and organization';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_organization_encryption_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_organization_encryption_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _org_tenant uuid; _tek_tenant uuid;
BEGIN
  SELECT tenant_id INTO _org_tenant FROM public.organizations WHERE id = NEW.organization_id;
  IF _org_tenant IS NULL THEN
    RAISE EXCEPTION 'organization_encryption_keys: organization % not found', NEW.organization_id;
  END IF;
  IF NEW.tenant_id <> _org_tenant THEN
    RAISE EXCEPTION 'organization_encryption_keys: tenant_id % does not match organization tenant %', NEW.tenant_id, _org_tenant;
  END IF;
  IF NEW.tenant_encryption_key_id IS NOT NULL THEN
    SELECT tenant_id INTO _tek_tenant FROM public.tenant_encryption_keys WHERE id = NEW.tenant_encryption_key_id;
    IF _tek_tenant IS NULL THEN
      RAISE EXCEPTION 'organization_encryption_keys: tenant_encryption_key_id % not found', NEW.tenant_encryption_key_id;
    END IF;
    IF _tek_tenant <> NEW.tenant_id THEN
      RAISE EXCEPTION 'organization_encryption_keys: tenant_encryption_key % belongs to different tenant', NEW.tenant_encryption_key_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_phase_project_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_phase_project_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.projects
    WHERE id = NEW.project_id
      AND workspace_id = NEW.workspace_id
      AND organization_id = NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'Phase must belong to the same workspace and organization as its project';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_project_benefit_fn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_project_benefit_fn() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE _p record;
BEGIN
  SELECT organization_id, workspace_id INTO _p
    FROM public.projects WHERE id = NEW.project_id;
  IF _p IS NULL THEN
    RAISE EXCEPTION 'Project % not found', NEW.project_id USING ERRCODE='P0002';
  END IF;
  IF NEW.organization_id <> _p.organization_id
     OR NEW.workspace_id <> _p.workspace_id THEN
    RAISE EXCEPTION 'Scope mismatch: benefit must inherit project organization and workspace'
      USING ERRCODE='22023';
  END IF;

  -- custom label rule
  IF NEW.benefit_type = 'other' THEN
    IF NEW.custom_benefit_type_label IS NULL
       OR length(btrim(NEW.custom_benefit_type_label)) = 0 THEN
      RAISE EXCEPTION 'custom_benefit_type_label is required when benefit_type = other'
        USING ERRCODE='22023';
    END IF;
  ELSE
    IF NEW.custom_benefit_type_label IS NOT NULL
       AND length(btrim(NEW.custom_benefit_type_label)) > 0 THEN
      RAISE EXCEPTION 'custom_benefit_type_label must be null unless benefit_type = other'
        USING ERRCODE='22023';
    END IF;
  END IF;

  -- non-negative numerics
  IF NEW.baseline_value IS NOT NULL AND NEW.baseline_value < 0 THEN
    RAISE EXCEPTION 'baseline_value must be non-negative' USING ERRCODE='22023';
  END IF;
  IF NEW.target_value IS NULL OR NEW.target_value < 0 THEN
    RAISE EXCEPTION 'target_value is required and must be non-negative' USING ERRCODE='22023';
  END IF;
  IF NEW.actual_value IS NOT NULL AND NEW.actual_value < 0 THEN
    RAISE EXCEPTION 'actual_value must be non-negative' USING ERRCODE='22023';
  END IF;

  -- realized / partially_realized require actual_value
  IF NEW.realization_status IN ('realized','partially_realized')
     AND NEW.actual_value IS NULL THEN
    RAISE EXCEPTION 'actual_value is required when realization_status is realized or partially_realized'
      USING ERRCODE='22023';
  END IF;

  RETURN NEW;
END;
$$;


