--
-- Name: validate_project_portfolio_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_project_portfolio_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_p_org uuid;
  v_p_archived boolean;
  v_check_needed boolean := false;
BEGIN
  IF NEW.portfolio_item_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_check_needed := true;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.portfolio_item_id IS DISTINCT FROM OLD.portfolio_item_id THEN
      v_check_needed := true;
    END IF;
  END IF;

  IF NOT v_check_needed THEN
    -- portfolio_item_id unchanged; do not block on stale archived state.
    RETURN NEW;
  END IF;

  SELECT organization_id, is_archived
    INTO v_p_org, v_p_archived
    FROM public.portfolio_items
   WHERE id = NEW.portfolio_item_id;

  IF v_p_org IS NULL THEN
    RAISE EXCEPTION 'Portfolio item % does not exist', NEW.portfolio_item_id;
  END IF;

  IF v_p_org <> NEW.organization_id THEN
    RAISE EXCEPTION 'Portfolio item % belongs to a different organization', NEW.portfolio_item_id;
  END IF;

  IF v_p_archived THEN
    RAISE EXCEPTION 'Portfolio item % is archived and cannot be newly assigned', NEW.portfolio_item_id;
  END IF;

  RETURN NEW;
END;
$$;


