    CONSTRAINT api_capability_catalogue_http_method_chk CHECK ((http_method = ANY (ARRAY['GET'::text, 'POST'::text, 'PATCH'::text, 'PUT'::text, 'DELETE'::text]))),
    CONSTRAINT api_capability_catalogue_key_format_chk CHECK (((capability_key = lower(capability_key)) AND (capability_key ~ '^[a-z][a-z0-9._:-]*$'::text) AND (length(capability_key) <= 100))),
    CONSTRAINT api_capability_catalogue_key_not_generic_chk CHECK ((capability_key <> ALL (ARRAY['crud'::text, 'generic_crud'::text, 'rpc'::text, 'generic_rpc'::text, 'table_access'::text, 'postgrest'::text, 'service_role'::text, '*'::text]))),
    CONSTRAINT api_capability_catalogue_kind_chk CHECK ((capability_kind = ANY (ARRAY['read'::text, 'command'::text]))),
    CONSTRAINT api_capability_catalogue_lifecycle_chk CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'retired'::text]))),
    CONSTRAINT api_capability_catalogue_route_id_chk CHECK (((route_id = lower(route_id)) AND (route_id ~ '^[a-z][a-z0-9._-]*$'::text) AND (length(route_id) <= 100))),
    CONSTRAINT api_capability_catalogue_route_path_chk CHECK (((route_path = (('/'::text || api_version) || SUBSTRING(route_path FROM (length(api_version) + 2)))) AND (route_path ~ '^/v[1-9][0-9]*/[a-z0-9/_:.-]*$'::text) AND (length(route_path) <= 200))),
    CONSTRAINT api_capability_catalogue_route_version_boundary_chk CHECK ((route_path ~~ (('/'::text || api_version) || '/%'::text))),
    CONSTRAINT api_capability_catalogue_scope_level_chk CHECK ((scope_level = ANY (ARRAY['organization'::text, 'workspace'::text, 'project'::text])))
);


