    CONSTRAINT organization_encryption_keys_status_check CHECK ((key_status = ANY (ARRAY['active_legacy_org_key'::text, 'wrapped_by_tenant_master_key'::text, 'rotating'::text, 'retired'::text])))
);


--
-- Name: organization_encryption_posture; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.organization_encryption_posture AS
 SELECT o.id AS organization_id,
    o.tenant_id,
    o.name AS organization_name,
    o.environment_role,
    (o.environment_role = 'production'::public.environment_role) AS is_production,
    (oek.legacy_key_name IS NOT NULL) AS legacy_org_key_name_present,
    COALESCE(oek.key_status, 'missing_metadata'::text) AS key_status,
    oek.key_scope,
        CASE
            WHEN (oek.key_status = 'wrapped_by_tenant_master_key'::text) THEN 'tenant_envelope'::text
            WHEN (oek.key_status = 'active_legacy_org_key'::text) THEN 'legacy_org_key'::text
            WHEN (oek.key_status IS NULL) THEN 'missing_metadata'::text
            ELSE oek.key_status
        END AS encryption_model,
    oek.last_rotated_at,
        CASE
            WHEN (oek.id IS NULL) THEN ARRAY['missing_encryption_metadata'::text]
            ELSE ARRAY[]::text[]
        END AS warnings
   FROM (public.organizations o
     LEFT JOIN public.organization_encryption_keys oek ON ((oek.organization_id = o.id)));


