    row_locator jsonb NOT NULL,
    status text DEFAULT 'planned'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_attempt_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    safe_error_code text,
    safe_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tenant_enc_mig_rows_attempt_chk CHECK ((attempt_count >= 0)),
    CONSTRAINT tenant_enc_mig_rows_locator_obj_chk CHECK ((jsonb_typeof(row_locator) = 'object'::text)),
    CONSTRAINT tenant_enc_mig_rows_metadata_obj_chk CHECK ((jsonb_typeof(safe_metadata) = 'object'::text)),
    CONSTRAINT tenant_enc_mig_rows_names_non_empty_chk CHECK (((length(btrim(table_name)) > 0) AND (length(btrim(column_name)) > 0))),
    CONSTRAINT tenant_enc_mig_rows_status_chk CHECK ((status = ANY (ARRAY['planned'::text, 'running'::text, 'completed'::text, 'failed'::text, 'skipped'::text, 'verification_failed'::text])))
);


--
-- Name: tenant_encryption_migration_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_encryption_migration_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    source_model text NOT NULL,
    target_model text NOT NULL,
    target_key_version integer,
    status text DEFAULT 'planned'::text NOT NULL,
    dry_run_only boolean DEFAULT false NOT NULL,
    initiated_by uuid,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    paused_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    total_fields_planned integer DEFAULT 0 NOT NULL,
    total_rows_planned bigint DEFAULT 0 NOT NULL,
    total_rows_scanned bigint DEFAULT 0 NOT NULL,
    total_rows_migrated bigint DEFAULT 0 NOT NULL,
    total_rows_skipped_null bigint DEFAULT 0 NOT NULL,
    total_rows_skipped_tenant_versioned bigint DEFAULT 0 NOT NULL,
    total_rows_failed bigint DEFAULT 0 NOT NULL,
    blocker_count integer DEFAULT 0 NOT NULL,
    safe_error_code text,
    safe_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT tenant_enc_mig_runs_completed_requires_started_chk CHECK (((completed_at IS NULL) OR (started_at IS NOT NULL))),
    CONSTRAINT tenant_enc_mig_runs_counts_chk CHECK (((total_fields_planned >= 0) AND (total_rows_planned >= 0) AND (total_rows_scanned >= 0) AND (total_rows_migrated >= 0) AND (total_rows_skipped_null >= 0) AND (total_rows_skipped_tenant_versioned >= 0) AND (total_rows_failed >= 0) AND (blocker_count >= 0))),
    CONSTRAINT tenant_enc_mig_runs_metadata_obj_chk CHECK ((jsonb_typeof(safe_metadata) = 'object'::text)),
    CONSTRAINT tenant_enc_mig_runs_paused_requires_status_chk CHECK (((paused_at IS NULL) OR (status = 'paused'::text))),
    CONSTRAINT tenant_enc_mig_runs_source_model_chk CHECK ((source_model = 'legacy_org_key_model'::text)),
    CONSTRAINT tenant_enc_mig_runs_status_chk CHECK ((status = ANY (ARRAY['planned'::text, 'running'::text, 'paused'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'verification_failed'::text]))),
    CONSTRAINT tenant_enc_mig_runs_target_kv_chk CHECK (((target_key_version IS NULL) OR (target_key_version > 0))),
    CONSTRAINT tenant_enc_mig_runs_target_model_chk CHECK ((target_model = 'tenant_versioned_key_model'::text))
);


--
-- Name: tenant_encryption_posture; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_encryption_posture AS
 WITH tmk AS (
         SELECT tek.tenant_id,
            tek.key_status,
            tek.key_scope,
            tek.key_provider,
            tek.key_version,
            tek.last_rotated_at,
            tek.updated_at
           FROM public.tenant_encryption_keys tek
          WHERE (tek.key_scope = 'tenant_master_key'::text)
        ), tek_v1 AS (
         SELECT DISTINCT ON (tek.tenant_id) tek.tenant_id,
            tek.key_status,
            tek.key_provider,
            tek.key_version,
            tek.metadata,
            tek.updated_at
           FROM public.tenant_encryption_keys tek
          WHERE ((tek.key_scope = 'tenant_encryption_key'::text) AND (tek.key_version = 1))
          ORDER BY tek.tenant_id, tek.key_version DESC
        ), tek_active AS (
         SELECT DISTINCT ON (tek.tenant_id) tek.tenant_id,
            tek.key_version,
            tek.key_status,
            tek.key_provider,
            tek.metadata,
            tek.updated_at
           FROM public.tenant_encryption_keys tek
          WHERE ((tek.key_scope = 'tenant_encryption_key'::text) AND (tek.key_status = 'active_for_encrypt'::text))
          ORDER BY tek.tenant_id, tek.key_version DESC
        ), org_agg AS (
         SELECT o.tenant_id,
            count(*) AS organization_count,
            count(*) FILTER (WHERE (o.environment_role = 'production'::public.environment_role)) AS production_org_count,
            count(*) FILTER (WHERE (o.environment_role = 'non_production'::public.environment_role)) AS non_production_org_count,
            count(oek.id) AS organizations_with_metadata,
            (count(*) - count(oek.id)) AS organizations_missing_metadata
           FROM (public.organizations o
             LEFT JOIN public.organization_encryption_keys oek ON ((oek.organization_id = o.id)))
          GROUP BY o.tenant_id
        ), legacy_key_agg AS (
         SELECT o.tenant_id,
            count(oek.id) AS retained_legacy_org_keys
           FROM (public.organizations o
             LEFT JOIN public.organization_encryption_keys oek ON ((oek.organization_id = o.id)))
          GROUP BY o.tenant_id
        ), runtime_cutover AS (
         SELECT r.tenant_id,
            bool_or((r.status = 'completed'::text)) AS complete
           FROM public.tenant_encryption_migration_runs r
          WHERE ((r.safe_metadata ->> 'phase'::text) = '4D.12M'::text)
          GROUP BY r.tenant_id
        ), final_verify AS (
         SELECT DISTINCT ON (r.tenant_id) r.tenant_id,
            r.status,
            COALESCE(((r.safe_metadata ->> 'legacy_bare_candidate'::text))::bigint, (0)::bigint) AS legacy_bare_candidate,
            COALESCE(((r.safe_metadata ->> 'malformed_or_unsupported_btpmenc'::text))::bigint, (0)::bigint) AS malformed_count,
            COALESCE(((r.safe_metadata ->> 'tenant_versioned_unreadable'::text))::bigint, (0)::bigint) AS tv_unreadable,
            COALESCE(((r.safe_metadata ->> 'fields_scanned'::text))::integer, 0) AS fields_scanned,
            COALESCE(((r.safe_metadata ->> 'tenant_versioned_decryptable'::text))::bigint, (0)::bigint) AS tv_decryptable,
            r.completed_at
           FROM public.tenant_encryption_migration_runs r
          WHERE ((r.safe_metadata ->> 'phase'::text) = '4D.12N.1'::text)
          ORDER BY r.tenant_id, r.completed_at DESC NULLS LAST
        )
 SELECT t.id AS tenant_id,
    t.name AS tenant_name,
    COALESCE(tmk.key_status, 'missing_metadata'::text) AS tenant_key_status,
    tmk.key_scope AS tenant_key_scope,
    tmk.key_provider AS tenant_key_provider,
    tmk.key_version AS tenant_key_version,
    tmk.last_rotated_at AS tenant_last_rotated_at,
    COALESCE(oa.organization_count, (0)::bigint) AS organization_count,
    COALESCE(oa.organizations_with_metadata, (0)::bigint) AS organizations_with_metadata,
    COALESCE(oa.organizations_missing_metadata, (0)::bigint) AS organizations_missing_metadata,
    COALESCE(oa.production_org_count, (0)::bigint) AS production_org_count,
    COALESCE(oa.non_production_org_count, (0)::bigint) AS non_production_org_count,
        CASE
            WHEN ((COALESCE(fv.status, ''::text) = 'completed'::text) AND (fv.legacy_bare_candidate = 0) AND (fv.malformed_count = 0) AND (fv.tv_unreadable = 0)) THEN 'tenant_versioned_migration_complete'::text
            WHEN COALESCE(rc.complete, false) THEN 'tenant_versioned_runtime'::text
            ELSE 'legacy_org_key_model'::text
        END AS model_status,
        CASE
            WHEN (COALESCE(rc.complete, false) OR (COALESCE(fv.status, ''::text) = 'completed'::text)) THEN 'tenant_versioned_runtime'::text
            ELSE 'legacy_org_key_model'::text
        END AS runtime_model,
    tek_v1.key_status AS tenant_key_v1_status,
    COALESCE(((tek_v1.metadata ->> 'legacy_material_imported'::text))::boolean, false) AS tenant_key_v1_imported,
    (tek_v1.key_status = 'import_blocked'::text) AS tenant_key_v1_import_blocked,
    (tek_v1.metadata ->> 'block_reason_code'::text) AS tenant_key_v1_block_reason_code,
    tek_active.key_version AS active_tenant_key_version,
    tek_active.key_status AS active_tenant_key_status,
    COALESCE(((tek_active.metadata ->> 'payload_format_ready'::text))::boolean, true) AS tenant_key_payload_format_ready,
    COALESCE(rc.complete, false) AS runtime_caller_migration_active,
    ((COALESCE(fv.status, ''::text) = 'completed'::text) AND (fv.legacy_bare_candidate = 0)) AS business_record_reencryption_performed,
    COALESCE(oa.organizations_missing_metadata, (0)::bigint) AS warning_count,
        CASE
            WHEN (tmk.tenant_id IS NULL) THEN 1
            ELSE 0
        END AS high_gap_count,
    GREATEST(COALESCE(tmk.updated_at, t.created_at), COALESCE(tek_v1.updated_at, t.created_at), COALESCE(tek_active.updated_at, t.created_at), COALESCE(t.updated_at, t.created_at)) AS updated_at,
    ((COALESCE(fv.status, ''::text) = 'completed'::text) AND (fv.legacy_bare_candidate = 0) AND (fv.malformed_count = 0) AND (fv.tv_unreadable = 0)) AS final_verification_passed,
    COALESCE(fv.legacy_bare_candidate, (0)::bigint) AS final_legacy_remaining,
    COALESCE(fv.malformed_count, (0)::bigint) AS final_malformed_remaining,
    COALESCE(fv.tv_unreadable, (0)::bigint) AS final_tenant_versioned_unreadable,
    COALESCE(fv.fields_scanned, 0) AS final_fields_scanned,
    COALESCE(fv.tv_decryptable, (0)::bigint) AS final_tenant_versioned_populated,
    true AS legacy_org_keys_retained,
    COALESCE(lka.retained_legacy_org_keys, (0)::bigint) AS retained_legacy_org_key_count,
        CASE
            WHEN ((COALESCE(fv.status, ''::text) = 'completed'::text) AND (fv.legacy_bare_candidate = 0) AND (fv.malformed_count = 0) AND (fv.tv_unreadable = 0) AND COALESCE(rc.complete, false)) THEN 'ready_for_review'::text
            ELSE 'pending_migration'::text
        END AS legacy_key_retirement_readiness,
    'not_approved'::text AS legacy_key_retirement_action_status
   FROM (((((((public.tenants t
     LEFT JOIN tmk ON ((tmk.tenant_id = t.id)))
     LEFT JOIN tek_v1 ON ((tek_v1.tenant_id = t.id)))
     LEFT JOIN tek_active ON ((tek_active.tenant_id = t.id)))
     LEFT JOIN org_agg oa ON ((oa.tenant_id = t.id)))
     LEFT JOIN legacy_key_agg lka ON ((lka.tenant_id = t.id)))
     LEFT JOIN runtime_cutover rc ON ((rc.tenant_id = t.id)))
     LEFT JOIN final_verify fv ON ((fv.tenant_id = t.id)));


